class group
{
public:
    typedef std::vector<std::string>::const_iterator const_iterator;
    typedef std::vector<std::string>::size_type size_type;
    // Define the key-value store using an unordered map
    std::unordered_map<std::string, std::string> data;
    // Template function to retrieve the value associated with a given key
    template<typename T>
    T get(const std::string& key) const {
        auto it = data.find(key);
        if (it != data.end()) {
            try {
                return convert<T>(it->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Value cannot be converted to the requested type");
            }
        } else {
            throw std::out_of_range("Key does not exist");
        }
    }
    // Template function to retrieve the value associated with a given key, with a default value provided
    template<typename T>
    T get(const std::string& key, const T& def) const {
        auto it = data.find(key);
        if (it != data.end()) {
            try {
                return convert<T>(it->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Value cannot be converted to the requested type");
            }
        } else {
            return def;
        }
    }
private:
    // Helper function to convert the stored string value to the requested type
    template<typename T>
    T convert(const std::string& value) const {
        if (std::is_same<T, int>::value) {
            return std::stoi(value);
        } else if (std::is_same<T, double>::value) {
            return std::stod(value);
        } else if (std::is_same<T, std::string>::value) {
            return value;
        } else {
            throw std::invalid_argument("Unsupported type conversion");
        }
    }
};

#include <vector>
using namespace std;
void dfs(vector<vector<char>>& grid, int i, int j) {
    if (i < 0 || i >= grid.size() || j < 0 || j >= grid[0].size() || grid[i][j] != 'L') {
        return;
    }
    grid[i][j] = 'W';  // Mark the cell as visited
    dfs(grid, i + 1, j);  // Check cell below
    dfs(grid, i - 1, j);  // Check cell above
    dfs(grid, i, j + 1);  // Check cell to the right
    dfs(grid, i, j - 1);  // Check cell to the left
    dfs(grid, i + 1, j + 1);  // Check cell diagonally below-right
    dfs(grid, i - 1, j - 1);  // Check cell diagonally above-left
    dfs(grid, i + 1, j - 1);  // Check cell diagonally below-left
    dfs(grid, i - 1, j + 1);  // Check cell diagonally above-right
}
int countConnectedLand(vector<vector<char>>& grid) {
    int count = 0;
    for (int i = 0; i < grid.size(); i++) {
        for (int j = 0; j < grid[0].size(); j++) {
            if (grid[i][j] == 'L') {
                count++;
                dfs(grid, i, j);
            }
        }
    }
    return count;
}

