    for (const auto& element : dataStructure) {
        if (std::find(elementsToSkip.begin(), elementsToSkip.end(), element) != elementsToSkip.end()) {
            continue; // Skipping the element
        }
        std::cout << element << " "; // Process the element
    }
    std::cout << std::endl;
    return 0;
}

