class StockSpanner {
    stack<pair<int, int>> st; // pair of price and span
public:
    StockSpanner() {

    }

    int next(int price) {
        int res = 1;
        while (!st.empty() && st.top().first <= price) {
            res += st.top().second;
            st.pop();
        }
        st.push(make_pair(price, res));
        return res;        
    }
