struct ScalaFpgaRawHeader {
    uint16_t m_minApdOffset;
    uint16_t m_maxApdOffset;
    uint16_t m_frequencyInteger;
    uint16_t m_frequencyFractional;
    uint16_t m_deviceId;
    uint16_t m_reservedHeader7;
};
bool parseHeader(const uint8_t* rawData, size_t dataSize, ScalaFpgaRawHeader& header) {
    if (dataSize < sizeof(ScalaFpgaRawHeader)) {
        return false;  // Insufficient data for header
    }
    // Extract and populate the header fields
    header.m_minApdOffset = (rawData[1] << 8) | rawData[0];
    header.m_maxApdOffset = (rawData[3] << 8) | rawData[2];
    header.m_frequencyInteger = (rawData[5] << 8) | rawData[4];
    header.m_frequencyFractional = (rawData[7] << 8) | rawData[6];
    header.m_deviceId = (rawData[9] << 8) | rawData[8];
    header.m_reservedHeader7 = (rawData[11] << 8) | rawData[10];
    return true;  // Header parsing successful
}

