class ThrowingUniquePtrException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Assignment from throwing::unique_ptr to another is not allowed";
    }
};
template <typename T>
class throwing::unique_ptr {
private:
    T* ptr;
public:
    unique_ptr(T* p) : ptr(p) {}
    ~unique_ptr() {
        delete[] ptr;
    }
    unique_ptr& operator=(const unique_ptr& other) {
        throw ThrowingUniquePtrException();
    }
};
