#include <cstring>
class SimpleString {
  private:
    const char* p_;
  public:
    // Constructor
    SimpleString(const char* str) : p_(str) {}
    // Method to return the length of the string
    size_t length() const {
        return strlen(p_);
    }
    // Method to return the character at a specified index in the string
    char charAt(size_t index) const {
        if (index < length()) {
            return p_[index];
        } else {
            // Handle out-of-bounds index
            return '\0';
        }
    }
    // Method to concatenate another string to the current string and return a new string object
    SimpleString concatenate(const char* str) const {
        size_t totalLength = length() + strlen(str);
        char* newString = new char[totalLength + 1];
        strcpy(newString, p_);
        strcat(newString, str);
        SimpleString result(newString);
        delete[] newString;
        return result;
    }
};

#include <iostream>
#include <cmath>
namespace rw {
    namespace math {
        template <typename T>
        class Quaternion {
        public:
            T w, x, y, z;
            Quaternion(T w, T x, T y, T z) : w(w), x(x), y(y), z(z) {}
            Quaternion<T> conjugate() const {
                return Quaternion<T>(w, -x, -y, -z);
            }
            Quaternion<T> multiply(const Quaternion<T>& other) const {
                T newW = w * other.w - x * other.x - y * other.y - z * other.z;
                T newX = w * other.x + x * other.w + y * other.z - z * other.y;
                T newY = w * other.y - x * other.z + y * other.w + z * other.x;
                T newZ = w * other.z + x * other.y - y * other.x + z * other.w;
                return Quaternion<T>(newW, newX, newY, newZ);
            }
            void normalize() {
                T magnitude = std::sqrt(w * w + x * x + y * y + z * z);
                if (magnitude != 0) {
                    w /= magnitude;
                    x /= magnitude;
                    y /= magnitude;
                    z /= magnitude;
                }
            }
        };
    } // namespace math
} // namespace rw

