using namespace std;
class GridPaths {
private:
    vector<string> grid;
    int ans;
    void f(int x, int y, int right, int down) {
        if (x == grid.size() - 1 && y == grid[0].size() - 1) {
            ans++;
            return;
        }
        if (right < grid.size() - 1) {
            f(x, y + 1, right + 1, down);
        }
        if (down < grid[0].size() - 1) {
            f(x + 1, y, right, down + 1);
        }
    }
public:
    int countPaths(int n) {
        grid.clear();
        string dots;
        dots.push_back('.');
        for (int i = 0; i < n; i++)
            grid.push_back(dots);
        ans = 0;
        f(0, 0, 0, 0);
        return ans;
    }
};

