void compare_normal_derivative(double delta, BicubicPatch* patch, Vector3 base_normal, int resolution, Vector3 analytic_full_deriv) {
    // Backup original values for restoration after comparison
    double backup_f = patch->n01->f;
    Vector3 backup_dx = patch->n01->dx;
    // Calculate the normal derivative with a small change in parameter value
    patch->n01->f += delta;
    Vector3 perturbed_normal = patch->calculateNormal();
    Vector3 numerical_deriv = (perturbed_normal - base_normal) / delta;
    // Restore original parameter value
    patch->n01->f = backup_f;
    // Compare the numerical derivative with the analytically calculated full derivative
    double error = (numerical_deriv - analytic_full_deriv).length();
    // Output the comparison result
    if (error < resolution) {
        std::cout << "Normal derivative comparison passed with error: " << error << std::endl;
    } else {
        std::cout << "Normal derivative comparison failed with error: " << error << std::endl;
    }
    // Restore original dx value
    patch->n01->dx = backup_dx;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;
const int MAXN = 1005; // Maximum number of vertices
int graph[MAXN][MAXN]; // Adjacency matrix representing the graph
int indegrees[MAXN];    // Array to store the indegree of each vertex
int n;                  // Number of vertices in the graph
int tlsort() {
    vector<int> order; // Stores the topological order of vertices
    queue<int> q;      // Queue to perform BFS for topological sorting
    for (int i = 0; i < n; i++) {
        if (indegrees[i] == 0) {
            q.push(i); // Add vertices with indegree 0 to the queue
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u); // Add the vertex to the topological order
        for (int v = 0; v < n; v++) {
            if (graph[u][v] > 0) {
                indegrees[v]--; // Decrement the indegree of adjacent vertices
                if (indegrees[v] == 0) {
                    q.push(v); // Add vertices with updated indegree 0 to the queue
                }
            }
        }
    }
    if (order.size() != n) {
        return -1; // Graph contains a cycle, return -1
    } else {
        return order.size(); // Return the number of vertices in the topological order
    }
}
int main() {
    // Input graph and indegrees
    // ...
    int result = tlsort();
    if (result == -1) {
        cout << "Impossible\n";
    } else {
        cout << result << '\n';
    }
    return 0;
}

