// Function to find the nearest power of 2 to n
int pow2_near(int n) {
    int power = 1;
    while (power * 2 <= n) {
        power *= 2;
    }
    return power;
}
int main() {
    std::cout << pow2_near(47) << std::endl;  // Output: 32
    std::cout << pow2_near(64) << std::endl;  // Output: 64
    std::cout << pow2_near(65) << std::endl;  // Output: 64
    return 0;
}

void Server::incomingMessage()
{
    // Read the incoming message from the socket
    QByteArray message = socket->readAll();
    // Iterate through all connected clients and relay the message
    for (QTcpSocket *client : clients) {
        if (client != socket) {  // Exclude the sender
            qint64 bytesWritten = client->write(message);
            if (bytesWritten == -1) {
                // Handle error writing to client
                qDebug() << "Error writing to client";
            }
        }
    }
    // Check for any errors or disconnections
    if (socket->state() == QAbstractSocket::UnconnectedState) {
        // Handle client disconnection
        clients.removeOne(socket);
        socket->deleteLater();
    }
}

#include <iostream>
#include <stack>
using namespace std;
class Stack {
private:
    stack<int> mainStack;
    stack<int> minStack;
public:
    void push(int x) {
        // Add element to main stack
        mainStack.push(x);

        // Update minStack if the added element is smaller or equal to the current minimum
        if (minStack.empty() || x <= minStack.top()) {
            minStack.push(x);
        }
    }
    void pop() {
        // Remove element from main stack
        if (mainStack.top() == minStack.top()) {
            minStack.pop();
        }
        mainStack.pop();
    }
    int top() {
        return mainStack.top();
    }
    bool isEmpty() {
        return mainStack.empty();
    }
    int getMin() {
        return minStack.top();
    }
};

#include <type_traits>
enum class ExternalFunctorObjectToBeCached { yes, no };
template <typename ReturnType, bool IsConst, ExternalFunctorObjectToBeCached CachePolicy, class Func>
class TaskType {
public:
    ReturnType execute() {
        return func_();
    }
private:
    Func func_;
};
template <class Func>
constexpr auto make_TaskType() {
    return TaskType<std::invoke_result_t<Func>, true, ExternalFunctorObjectToBeCached::no, Func>();
}
template <typename T, std::conditional_t<std::is_class<T>::value, T&, T> val, class Func>
constexpr auto make_TaskType(Func&& func) {
    return TaskType<T, std::is_const<T>::value, ExternalFunctorObjectToBeCached::no, Func>(std::forward<Func>(func));
}

