    set_default_option("TRACE_EXCEPTIONS", true);
    ConfigurationManager::set("TRACE_EXCEPTIONS", false);
    std::cout << "TRACE_EXCEPTIONS: " << ConfigurationManager::get<bool>("TRACE_EXCEPTIONS", true) << std::endl;
    return 0;
}

