template<typename SrcPort, typename DstPort>
class Path {
    std::vector<std::pair<SrcPort, DstPort>> _path;
public:
    // Function to check for cycles in the path
    bool hasCycle() const {
        std::set<std::pair<SrcPort, DstPort>> seen;
        for (const auto& pp : _path) {
            if (seen.count(pp) != 0) {
                return true;  // Cycle found
            }
            seen.insert(pp);
        }
        return false;  // No cycle found
    }
};

