#include <vector>
#include <algorithm>
class AddressSpaceManager {
private:
    int size;
    std::vector<bool> memoryMap;  // Represents the availability of each address in the address space
public:
    AddressSpaceManager(int size) : size(size), memoryMap(size, false) {}
    int allocate(int blockSize) {
        for (int i = 0; i <= size - blockSize; ++i) {
            if (std::all_of(memoryMap.begin() + i, memoryMap.begin() + i + blockSize, [](bool val) { return !val; })) {
                for (int j = i; j < i + blockSize; ++j) {
                    memoryMap[j] = true;  // Mark the memory block as allocated
                }
                return i;  // Return the starting address of the allocated block
            }
        }
        return -1;  // No suitable block available
    }
    void deallocate(int address) {
        if (address >= 0 && address < size) {
            memoryMap[address] = false;  // Mark the memory block as deallocated
        }
    }
};

