namespace mozjs
{
	GlobalHeapManager::GlobalHeapManager(JSContext* ctx) : m_ctx(ctx) {}
	std::unique_ptr<GlobalHeapManager> GlobalHeapManager::Create(JSContext* ctx)
	{
		return std::unique_ptr<GlobalHeapManager>(new GlobalHeapManager(ctx));
	}
	void GlobalHeapManager::RegisterUser(IHeapUser* heapUser)
	{
		std::scoped_lock sl(m_users_lock);
		m_users.emplace(heapUser, heapUser);
	}
	void GlobalHeapManager::UnregisterUser(IHeapUser* heapUser)
	{
		std::scoped_lock sl(m_users_lock);
		m_users.erase(heapUser);
	}
	uint32_t GlobalHeapManager::Store(JS::HandleValue valueToStore)
	{
		std::scoped_lock sl(m_elements_lock);
		if (!m_unused_elements.empty())
		{
			m_unused_elements.clear();
		}
		while (m_elements.contains(m_current_id))
		{
			++m_current_id;
		}
		m_elements.emplace(m_current_id, std::make_unique<HeapElement>(valueToStore));
		return m_current_id++;
	}
	uint32_t GlobalHeapManager::Store(JS::HandleObject valueToStore)
	{
		JS::RootedValue jsValue(m_ctx, JS::ObjectValue(*valueToStore));
		return Store(jsValue);
	}
	uint32_t GlobalHeapManager::Store(JS::HandleFunction valueToStore)
	{
		JS::RootedObject jsObject(m_ctx, JS_GetFunctionObject(valueToStore));
		return Store(jsObject);
	}
	JS::Heap<JS::Value>& GlobalHeapManager::Get(uint32_t id)
	{
		std::scoped_lock sl(m_elements_lock);
		if (!m_unused_elements.empty())
		{
			m_unused_elements.clear();
		}
		return *m_elements[id];
	}
	void GlobalHeapManager::Remove(uint32_t id)
	{
		std::scoped_lock sl(m_elements_lock);
		m_unused_elements.emplace_back(std::move(m_elements[id]));
		m_elements.erase(id);
	}
	void GlobalHeapManager::Trace(JSTracer* trc)
	{
		std::scoped_lock sl(m_elements_lock);
		for (auto& [id, heapElement] : m_elements)
		{
			JS::TraceEdge(trc, heapElement.get(), "CustomHeap_Global");
		}
		for (auto& heapElement : m_unused_elements)
		{
			JS::TraceEdge(trc, heapElement.get(), "CustomHeap_Global");
		}
	}
	void GlobalHeapManager::PrepareForGc()
	{
		std::scoped_lock sl(m_users_lock);
		for (auto& [id, heapUser] : m_users)
		{
			heapUser->PrepareForGlobalGc();
		}
		m_unused_elements.clear();
		m_elements.clear();
	}
}

#include "comms/torchcomms/nccl/TorchWorkNCCL.hpp"
namespace torch::comms {
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::garbageCollectLocked() {
  TorchWorkNCCL::WorkStatus last_status = TorchWorkNCCL::WorkStatus::COMPLETED;
  // Keep popping completed elements until we hit an in-progress element
  // or the queue is empty
  // Use an iterator to safely remove empty queues while iterating
  auto it = stream_work_queues_.begin();
  while (it != stream_work_queues_.end()) {
    auto& work_queue = it->second;
    while (!work_queue.empty()) {
      // Get the first work object in the queue
      auto work = work_queue.front();
      // Use the checkStatus function to determine the work status
      TorchWorkNCCL::WorkStatus status = work->checkStatus();
      last_status = status;
      if (status == TorchWorkNCCL::WorkStatus::COMPLETED) {
        // Work is completed, remove it from the work queue
        work_queue.pop();
        // Continue to the next element in the queue
      } else if (
          status == TorchWorkNCCL::WorkStatus::TIMEDOUT ||
          status == TorchWorkNCCL::WorkStatus::ERROR) {
        // Return the error status immediately
        return status;
      } else {
        // NOT_STARTED or INPROGRESS - stop processing this queue
        break;
      }
    }
    // If the queue is now empty, remove it from the map
    if (work_queue.empty()) {
      it = stream_work_queues_.erase(it);
    } else {
      ++it;
    }
  }
  return last_status;
}
// Thread-safety: This method is called from the timeout watchdog thread while
// the main thread may be enqueuing work via enqueueWork(). The
// work_queues_mutex_ ensures proper synchronization - both garbageCollect() and
// enqueueWork() acquire the mutex before accessing stream_work_queues_.
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::garbageCollect() {
  std::lock_guard<std::mutex> lock(work_queues_mutex_);
  return garbageCollectLocked();
}
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::finalize() {
  // Because this function is typically called after the timeout thread has
  // already joined, we might not need to lock here.  But doing the lock anyway,
  // as defensive programming, just in case someone moves the thread join order
  // later.  The cost of the lock itself should be small on modern linux systems
  // (uncontended locks are typically just an atomic operation).
  std::lock_guard<std::mutex> lock(work_queues_mutex_);
  // Initialize the status to COMPLETED to cover the case where the queue is
  // empty
  TorchWorkNCCL::WorkStatus status = TorchWorkNCCL::WorkStatus::COMPLETED;
  while (!stream_work_queues_.empty()) {
    status = garbageCollectLocked();
    if (status == TorchWorkNCCL::WorkStatus::ERROR ||
        status == TorchWorkNCCL::WorkStatus::TIMEDOUT ||
        status == TorchWorkNCCL::WorkStatus::COMPLETED) {
      break;
    }
  }
  // Clear all work queues & completed work queue.
  //
  // NOTE: finalize MUST return without holding references to any work object,
  // otherwise it may leak object and cause side effects.
  stream_work_queues_.clear();
  return status;
}
void TorchWorkNCCLQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCL> work,
    cudaStream_t stream) {
  // Add work to stream's queue after events have been recorded
  std::lock_guard<std::mutex> lock(work_queues_mutex_);
  stream_work_queues_[stream].push(std::move(work));
}
} // namespace torch::comms

#include <gtest/gtest.h>
#include <perforator/lib/python/python.h>
#include <contrib/libs/re2/re2/re2.h>
#include <contrib/libs/re2/re2/stringpiece.h>
using namespace NPerforator::NLinguist::NPython;
// Declare the TryScanVersion function from python.cpp
namespace NPerforator::NLinguist::NPython {
    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}
TEST(PythonVersionParsing, TryScanVersion) {
    struct TTestCase {
        TString VersionString;
        bool ShouldParse;
        TPythonVersion ExpectedVersion;
    };
    TVector<TTestCase> testCases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},  // Major not 2 or 3
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };
    for (const auto& testCase : testCases) {
        TMaybe<TPythonVersion> result = TryScanVersion(TConstArrayRef<char>{testCase.VersionString.data(), testCase.VersionString.size()});
        if (testCase.ShouldParse) {
            ASSERT_TRUE(result.Defined()) << "Failed to parse version from string: '" << testCase.VersionString << "'";
            TString expectedVersionStr =
                std::to_string(testCase.ExpectedVersion.MajorVersion) + "." +
                std::to_string(testCase.ExpectedVersion.MinorVersion) + "." +
                std::to_string(testCase.ExpectedVersion.MicroVersion);
            TString actualVersionStr =
                std::to_string(result->MajorVersion) + "." +
                std::to_string(result->MinorVersion) + "." +
                std::to_string(result->MicroVersion);
            EXPECT_EQ(result->MajorVersion, testCase.ExpectedVersion.MajorVersion)
                << "Major version mismatch for input: '" << testCase.VersionString
                << "', expected: " << expectedVersionStr
                << ", got: " << actualVersionStr;
            EXPECT_EQ(result->MinorVersion, testCase.ExpectedVersion.MinorVersion)
                << "Minor version mismatch for input: '" << testCase.VersionString
                << "', expected: " << expectedVersionStr
                << ", got: " << actualVersionStr;
            EXPECT_EQ(result->MicroVersion, testCase.ExpectedVersion.MicroVersion)
                << "Micro version mismatch for input: '" << testCase.VersionString
                << "', expected: " << expectedVersionStr
                << ", got: " << actualVersionStr;
        } else {
            EXPECT_FALSE(result.Defined()) << "Should not parse version from string: '" << testCase.VersionString << "'";
        }
