    const ContextOptions& opt;
    const TestCaseData*   tc;
    std::mutex            mutex;
    // constructor has to accept the ContextOptions by ref as a single argument
    MyXmlReporter(const ContextOptions& in)
            : stdout_stream(*in.cout)
            , opt(in)
            , tc(nullptr) {}
