#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
#include <iomanip>
// Use a fixed seed for deterministic behavior of the randomized algorithm
std::mt19937 rng(42);
void solve() {
    int n;
    int m;
    std::cin >> n >> m;
    // Weights for the multiplicative weights update algorithm
    std::vector<long double> weights(n, 1.0L);
    // Keep track of mistakes for each participant to handle the b=0 case
    std::vector<int> mistakes(n, 0);
    for (int k = 0; k < m; ++k) {
        std::string s;
        std::cin >> s;
        int my_guess;
        // Find the minimum number of mistakes any participant has made so far.
        int min_mistakes = *std::min_element(mistakes.begin(), mistakes.end());
        // Hybrid Strategy:
        // If there is at least one "perfect" expert (0 mistakes so far), follow them.
        // This guarantees we make 0 mistakes if the best participant makes 0 mistakes (b=0).
        if (min_mistakes == 0) {
            int first_perfect_idx = -1;
            for (int i = 0; i < n; ++i) {
                if (mistakes[i] == 0) {
                    first_perfect_idx = i;
                    break;
                }
            }
            my_guess = s[first_perfect_idx] - '0';
        } else {
            // Otherwise, use Randomized Weighted Majority.
            long double weight_for_0 = 0.0L;
            long double weight_for_1 = 0.0L;
            for (int i = 0; i < n; ++i) {
                if (s[i] == '0') {
                    weight_for_0 += weights[i];
                } else {
                    weight_for_1 += weights[i];
                }
            }
            long double total_weight = weight_for_0 + weight_for_1;

            // Handle the unlikely case where all weights decay to zero.
            if (total_weight == 0.0L) {
                my_guess = 0; // Default guess
            } else {
                long double prob_1 = weight_for_1 / total_weight;
                std::uniform_real_distribution<long double> dist(0.0L, 1.0L);
                if (dist(rng) < prob_1) {
                    my_guess = 1;
                } else {
                    my_guess = 0;
                }
            }
        }
        std::cout << my_guess << std::endl;
        int outcome;
        std::cin >> outcome;
        // Update mistakes and weights based on the actual outcome
        for (int i = 0; i < n; ++i) {
            if ((s[i] - '0') != outcome) {
                mistakes[i]++;
                // Penalize wrong experts by halving their weight.
                weights[i] *= 0.5L;
            }
        }
    }
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    solve();
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// Structure to store swap operations
struct SwapOp {
    int x1, y1, x2, y2;
};
int main() {
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    const int N = 30;
    // Using a vector of vectors to represent the pyramid
    // A[x][y] stores the value at coordinates (x, y)
    vector<vector<int>> A(N);

    // Reading input
    for (int i = 0; i < N; ++i) {
        A[i].reserve(i + 1);
        for (int j = 0; j <= i; ++j) {
            int val;
            cin >> val;
            A[i].push_back(val);
        }
    }
    vector<SwapOp> ans;
    // Reserve memory to avoid reallocations. 
    // Theoretical max swaps is 4495 for N=30, so 10000 is safe.
    ans.reserve(10000);
    // Bottom-up heap construction strategy.
    // We iterate from the second to last row (N-2) up to the top (0).
    // The last row (N-1) does not need processing as they are leaves.
    // This order ensures that when we process a node, its children's sub-pyramids 
    // already satisfy the condition (are valid heaps).
    for (int i = N - 2; i >= 0; --i) {
        for (int j = 0; j <= i; ++j) {
            // Perform sift-down for the ball currently at (i, j)
            int curr_x = i;
            int curr_y = j;

            // Continue sifting down until we reach the bottom or the condition is satisfied
            while (curr_x < N - 1) {
                // Indices of the two children directly below
                int left_x = curr_x + 1;
                int left_y = curr_y;
                int right_x = curr_x + 1;
                int right_y = curr_y + 1;

                int val_curr = A[curr_x][curr_y];
                int val_left = A[left_x][left_y];
                int val_right = A[right_x][right_y];

                // Check if the heap property is satisfied: Parent < both Children
                if (val_curr < val_left && val_curr < val_right) {
                    break;
                }

                // If not, swap with the smaller child.
                // This is the standard greedy choice for min-heaps to float the smallest value up.
                if (val_left < val_right) {
                    // Left child is smaller, swap with left
                    ans.push_back({curr_x, curr_y, left_x, left_y});
                    swap(A[curr_x][curr_y], A[left_x][left_y]);
                    // Update current position to follow the large value down
                    curr_x = left_x;
                    curr_y = left_y;
                } else {
                    // Right child is smaller, swap with right
                    ans.push_back({curr_x, curr_y, right_x, right_y});
                    swap(A[curr_x][curr_y], A[right_x][right_y]);
                    // Update current position
                    curr_x = right_x;
                    curr_y = right_y;
                }
            }
        }
    }
    // Output result
    cout << ans.size() << "\n";
    for (const auto& op : ans) {
        cout << op.x1 << " " << op.y1 << " " << op.x2 << " " << op.y2 << "\n";
    }
    return 0;
}

#include "FiberPool.hpp"
#include "ScriptMgr.hpp"
namespace YimMenu
{
	void FiberPool::InitImpl(int num_fibers)
	{
		for (std::size_t i = 0; i < num_fibers; ++i)
		{
			ScriptMgr::AddScript(std::make_unique<Script>(&ScriptEntry));
		}
	}
	void FiberPool::DestroyImpl()
	{
		std::lock_guard lock(m_Mutex);
		while (!m_Jobs.empty())
			m_Jobs.pop();
	}
	void FiberPool::PushImpl(std::function<void()> callback)
	{
		std::lock_guard lock(m_Mutex);
		m_Jobs.push(std::move(callback));
	}
	void FiberPool::Tick()
	{
		std::unique_lock lock(m_Mutex);
		if (!m_Jobs.empty())
		{
			auto job = std::move(m_Jobs.top());
			m_Jobs.pop();
			lock.unlock();
			std::invoke(std::move(job));
		}
	}
	void FiberPool::ScriptEntry()
	{
		while (g_Running)
		{
			FiberPool::GetInstance().Tick();
			ScriptMgr::Yield();
		}
	}
}

#include <asio/dispatch.hpp>
#include <asio/execution_context.hpp>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <queue>
using asio::dispatch;
using asio::execution_context;
class priority_scheduler : public execution_context
{
public:
  // A class that satisfies the Executor requirements.
  class executor_type
  {
  public:
    executor_type(priority_scheduler& ctx, int pri) noexcept
      : context_(ctx), priority_(pri)
    {
    }
    priority_scheduler& context() const noexcept
    {
      return context_;
    }
    void on_work_started() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }
    void on_work_finished() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }
    template <class Func, class Alloc>
    void dispatch(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }
    template <class Func, class Alloc>
    void post(Func f, const Alloc& a) const
    {
      auto p(std::allocate_shared<item<Func>>(
            typename std::allocator_traits<
              Alloc>::template rebind_alloc<char>(a),
            priority_, std::move(f)));
      std::lock_guard<std::mutex> lock(context_.mutex_);
      context_.queue_.push(p);
      context_.condition_.notify_one();
    }
    template <class Func, class Alloc>
    void defer(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }
    friend bool operator==(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ == &b.context_;
    }
    friend bool operator!=(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ != &b.context_;
    }
  private:
    priority_scheduler& context_;
    int priority_;
  };
  executor_type get_executor(int pri = 0) noexcept
  {
    return executor_type(*const_cast<priority_scheduler*>(this), pri);
  }
  void run()
  {
    std::unique_lock<std::mutex> lock(mutex_);
    for (;;)
    {
      condition_.wait(lock, [&]{ return stopped_ || !queue_.empty(); });
      if (stopped_)
        return;
      auto p(queue_.top());
      queue_.pop();
      lock.unlock();
      p->execute_(p);
      lock.lock();
    }
  }
  void stop()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    stopped_ = true;
    condition_.notify_all();
  }
private:
  struct item_base
  {
    int priority_;
    void (*execute_)(std::shared_ptr<item_base>&);
  };
  template <class Func>
  struct item : item_base
  {
    item(int pri, Func f) : function_(std::move(f))
    {
      priority_ = pri;
      execute_ = [](std::shared_ptr<item_base>& p)
      {
        Func tmp(std::move(static_cast<item*>(p.get())->function_));
        p.reset();
        tmp();
      };
    }
    Func function_;
  };
  struct item_comp
  {
    bool operator()(
        const std::shared_ptr<item_base>& a,
        const std::shared_ptr<item_base>& b)
    {
      return a->priority_ < b->priority_;
    }
  };
  std::mutex mutex_;
  std::condition_variable condition_;
  std::priority_queue<
    std::shared_ptr<item_base>,
    std::vector<std::shared_ptr<item_base>>,
    item_comp> queue_;
  bool stopped_ = false;
};
int main()
{
  priority_scheduler sched;
  auto low = sched.get_executor(0);
  auto med = sched.get_executor(1);
  auto high = sched.get_executor(2);
  dispatch(low, []{ std::cout << "1\n"; });
  dispatch(low, []{ std::cout << "11\n"; });
  dispatch(med, []{ std::cout << "2\n"; });
