#include <vector>
#include <mpi.h>
#include <algorithm>
#include <tuple> // for std::tie
#include <madvoro/Voronoi3D.hpp>
#include "mpi_utils.hpp"
#include "read_points.hpp"
using namespace MadVoro;
int main(int argc, char *argv[])
{
    MPI_Init(&argc, &argv);
    int rank, size;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);
    // some of the points are inside the fox, and some of them are outside. This is crucial, of course, to create the fox's faces.
    // we should remember what points are inside.
    std::vector<Vector3D> allPoints;
    std::vector<double> isInside;

    if(rank == 0)
    {
        // read points
        std::vector<Vector3D> insidePoints = readPoints("input/points_inside_fox");
        std::vector<Vector3D> outsidePoints = readPoints("input/points_outside_fox");
        allPoints.insert(allPoints.end(), insidePoints.cbegin(), insidePoints.cend());
        for(size_t i = 0; i < insidePoints.size(); i++) isInside.push_back(1);
        allPoints.insert(allPoints.end(), outsidePoints.cbegin(), outsidePoints.cend());
        for(size_t i = 0; i < outsidePoints.size(); i++) isInside.push_back(0);
    }
    // not really necessary, but it is more efficient to distribute the points between the different ranks
    auto [myPoints, myIsInside] = SpreadPointsToProcessors(allPoints, isInside);
    Vector3D ll(-13, -1, -90), ur(15, 80, 70);
    Voronoi3D diag(ll, ur);

    if(rank == 0)
    {
        std::cout << "Constructing the Voronoi diagram" << std::endl;
    }
    diag.SetVerbosity(true); // print build iterations
    diag.BuildParallel(myPoints);
    // after the build, the list of points changes. The `myIsInside` list is not longer accurate, and should be updated.
    // we use a special function of Voronoi3D to help us recognize which points have moved, and where to.
    std::tie(myPoints, myIsInside) = GetPointsAfterBuildExchange(diag, myPoints, myIsInside);
#ifdef MADVORO_WITH_VTK
    std::string vtkFilename = "fox.vtu";
    if(rank == 0)
    {
        std::cout << "Starting VTK Print to file called " << vtkFilename << std::endl;
    }
    // print to VTK, with a field of "isInside" to each point. When you want to see the VTK result, make sure you filter by 'isInside == 1'
    diag.ToVTK(vtkFilename, {"isInside"}, {myIsInside});
#else
    if(rank == 0)
    {
        std::cout << "VTK support not enabled. Skipping VTK output." << std::endl;
    }
#endif
    MPI_Finalize();
}

#include <__config>
#include <__verbose_abort>
#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#ifdef __BIONIC__
#  include <syslog.h>
extern "C" void android_set_abort_message(const char* msg);
#endif   // __BIONIC__
#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
#  include <CrashReporterClient.h>
#endif
_LIBCPP_BEGIN_NAMESPACE_STD
_LIBCPP_WEAK void __libcpp_verbose_abort(char const* format, ...) noexcept {
  // Write message to stderr. We do this before formatting into a
  // buffer so that we still get some information out if that fails.
  {
    va_list list;
    va_start(list, format);
    std::vfprintf(stderr, format, list);
    va_end(list);
  }
  // Format the arguments into an allocated buffer for CrashReport & friends.
  // We leak the buffer on purpose, since we're about to abort() anyway.
  char* buffer;
  (void)buffer;
  va_list list;
  va_start(list, format);
#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
  // Note that we should technically synchronize accesses here (by e.g. taking a lock),
  // however concretely we're only setting a pointer, so the likelihood of a race here
  // is low.
  vasprintf(&buffer, format, list);
  CRSetCrashLogMessage(buffer);
#elif defined(__BIONIC__)
  vasprintf(&buffer, format, list);
  // Show error in tombstone.
  android_set_abort_message(buffer);
  // Show error in logcat.
  openlog("libc++", 0, 0);
  syslog(LOG_CRIT, "%s", buffer);
  closelog();
#endif
  va_end(list);
  std::abort();
}
_LIBCPP_END_NAMESPACE_STD

#include <cstdlib>
#include <iostream>
#include <memory>
#include <utility>
#include "asio.hpp"
using asio::ip::tcp;
class session
  : public std::enable_shared_from_this<session>
{
public:
  session(tcp::socket socket)
    : socket_(std::move(socket))
  {
  }
  void start()
  {
    do_read();
  }
private:
  void do_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(data_, max_length),
        [this, self](std::error_code ec, std::size_t length)
        {
          if (!ec)
          {
            do_write(length);
          }
        });
  }
  void do_write(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(data_, length),
        [this, self](std::error_code ec, std::size_t /*length*/)
        {
          if (!ec)
          {
            do_read();
          }
        });
  }
  tcp::socket socket_;
  enum { max_length = 1024 };
  char data_[max_length];
};
class server
{
public:
  server(asio::io_context& io_context, short port)
    : acceptor_(io_context, tcp::endpoint(tcp::v4(), port))
  {
    do_accept();
  }
private:
  void do_accept()
  {
    acceptor_.async_accept(
        [this](std::error_code ec, tcp::socket socket)
        {
          if (!ec)
          {
            std::make_shared<session>(std::move(socket))->start();
          }
          do_accept();
        });
  }
  tcp::acceptor acceptor_;
};
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_tcp_echo_server <port>\n";
      return 1;
    }
    asio::io_context io_context;
    server s(io_context, std::atoi(argv[1]));
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

#include "asio/buffer.hpp"
#include "asio/connect.hpp"
#include "asio/io_context.hpp"
#include "asio/ip/tcp.hpp"
#include "asio/read_until.hpp"
#include "asio/system_error.hpp"
#include "asio/write.hpp"
#include <cstdlib>
#include <iostream>
#include <string>
using asio::ip::tcp;
//----------------------------------------------------------------------
//
// This class manages socket timeouts by running the io_context using the timed
// io_context::run_for() member function. Each asynchronous operation is given
// a timeout within which it must complete. The socket operations themselves
// use lambdas as completion handlers. For a given socket operation, the client
// object runs the io_context to block thread execution until the operation
// completes or the timeout is reached. If the io_context::run_for() function
// times out, the socket is closed and the outstanding asynchronous operation
// is cancelled.
//
class client
{
public:
  void connect(const std::string& host, const std::string& service,
      std::chrono::steady_clock::duration timeout)
  {
    // Resolve the host name and service to a list of endpoints.
    auto endpoints = tcp::resolver(io_context_).resolve(host, service);
    // Start the asynchronous operation itself. The lambda that is used as a
    // callback will update the error variable when the operation completes.
    // The blocking_udp_client.cpp example shows how you can use std::bind
    // rather than a lambda.
    std::error_code error;
    asio::async_connect(socket_, endpoints,
        [&](const std::error_code& result_error,
            const tcp::endpoint& /*result_endpoint*/)
        {
          error = result_error;
        });
    // Run the operation until it completes, or until the timeout.
    run(timeout);
    // Determine whether a connection was successfully established.
    if (error)
      throw std::system_error(error);
  }
  std::string read_line(std::chrono::steady_clock::duration timeout)
  {
    // Start the asynchronous operation. The lambda that is used as a callback
    // will update the error and n variables when the operation completes. The
    // blocking_udp_client.cpp example shows how you can use std::bind rather
    // than a lambda.
    std::error_code error;
    std::size_t n = 0;
    asio::async_read_until(socket_,
        asio::dynamic_buffer(input_buffer_), '\n',
        [&](const std::error_code& result_error,
            std::size_t result_n)
        {
          error = result_error;
          n = result_n;
        });
    // Run the operation until it completes, or until the timeout.
    run(timeout);
    // Determine whether the read completed successfully.
    if (error)
      throw std::system_error(error);
    std::string line(input_buffer_.substr(0, n - 1));
    input_buffer_.erase(0, n);
    return line;
  }
  void write_line(const std::string& line,
      std::chrono::steady_clock::duration timeout)
  {
    std::string data = line + "\n";
    // Start the asynchronous operation itself. The lambda that is used as a
    // callback will update the error variable when the operation completes.
    // The blocking_udp_client.cpp example shows how you can use std::bind
    // rather than a lambda.
    std::error_code error;
    asio::async_write(socket_, asio::buffer(data),
        [&](const std::error_code& result_error,
            std::size_t /*result_n*/)
        {
          error = result_error;
        });
    // Run the operation until it completes, or until the timeout.
    run(timeout);
    // Determine whether the read completed successfully.
    if (error)
      throw std::system_error(error);
  }
private:
  void run(std::chrono::steady_clock::duration timeout)
  {
    // Restart the io_context, as it may have been left in the "stopped" state
    // by a previous operation.
    io_context_.restart();
    // Block until the asynchronous operation has completed, or timed out. If
    // the pending asynchronous operation is a composed operation, the deadline
    // applies to the entire operation, rather than individual operations on
    // the socket.
    io_context_.run_for(timeout);
    // If the asynchronous operation completed successfully then the io_context
    // would have been stopped due to running out of work. If it was not
    // stopped, then the io_context::run_for call must have timed out.
    if (!io_context_.stopped())
    {
      // Close the socket to cancel the outstanding asynchronous operation.
      socket_.close();
      // Run the io_context again until the operation completes.
      io_context_.run();
    }
  }
  asio::io_context io_context_;
  tcp::socket socket_{io_context_};
  std::string input_buffer_;
};
//----------------------------------------------------------------------
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 4)
    {
      std::cerr << "Usage: blocking_tcp_client <host> <port> <message>\n";
      return 1;
    }
    client c;
    c.connect(argv[1], argv[2], std::chrono::seconds(10));
    auto time_sent = std::chrono::steady_clock::now();
    c.write_line(argv[3], std::chrono::seconds(10));
    for (;;)
    {
      std::string line = c.read_line(std::chrono::seconds(10));
      // Keep going until we get back the line that was sent.
      if (line == argv[3])
        break;
    }
    auto time_received = std::chrono::steady_clock::now();
    std::cout << "Round trip time: ";
    std::cout << std::chrono::duration_cast<
      std::chrono::microseconds>(
        time_received - time_sent).count();
    std::cout << " microseconds\n";
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

