#ifndef LLMAPPING
#define LLMAPPING std::map<std::string, Value *>
#endif
namespace SLOT {
LLVMFunction::LLVMFunction(bool t_shiftToMultiply, context &t_scx,
                           Function *t_contents)
    : shiftToMultiply(t_shiftToMultiply), scx(t_scx), contents(t_contents),
      varCounter(0), extraVariables(t_scx) {
  // Mirror the LLVM function signature in the SMT world. Each LLVM
  // argument becomes a Z3 constant with a matching sort; we keep the
  // names identical so later lookups stay straightforward.
  scx.set_rounding_mode(RNE);
  for (Argument *arg = contents->arg_begin(); arg < contents->arg_end();
       arg++) {
    if (arg->getType()->isIntegerTy()) {
      // 1-wide integer --> boolean
      if (arg->getType()->getIntegerBitWidth() == 1) {
        variables.insert(
            make_pair(arg->getName().str(),
                      scx.bool_const(arg->getName().str().c_str())));
      } else {
        // Regular bitvector case
        variables.insert(
            make_pair(arg->getName().str(),
                      scx.bv_const(arg->getName().str().c_str(),
                                   arg->getType()->getIntegerBitWidth())));
      }
    } else if (arg->getType()->isHalfTy()) {
      variables.insert(
          make_pair(arg->getName().str(),
                    scx.fpa_const(arg->getName().str().c_str(), 5, 11)));
    } else if (arg->getType()->isFloatTy()) {
      variables.insert(
          make_pair(arg->getName().str(),
                    scx.fpa_const(arg->getName().str().c_str(), 8, 24)));
    } else if (arg->getType()->isDoubleTy()) {
      variables.insert(
          make_pair(arg->getName().str(),
                    scx.fpa_const(arg->getName().str().c_str(), 11, 53)));
    } else if (arg->getType()->isFP128Ty()) {
      variables.insert(
          make_pair(arg->getName().str(),
                    scx.fpa_const(arg->getName().str().c_str(), 15, 113)));
    } else {
      std::string type_str;
      llvm::raw_string_ostream rso(type_str);
      arg->print(rso);
      throw UnsupportedTypeException("unsupported LLVM variable type",
                                     rso.str());
    }
  }
}
// For fp to bv bitcast, create a new variable and constraint it equal at the
// top level
expr LLVMFunction::AddBCVariable(std::unique_ptr<LLVMNode> contents) {
  std::string name = "_slot_smtbc_" + std::to_string(varCounter) + "_";
  expr var = scx.bv_const(name.c_str(), contents->Width());
  variables.insert(make_pair(name, var));
  expr added = (var.mk_from_ieee_bv(contents->SMTSort()) == contents->ToSMT());
  extraVariables = (varCounter == 0) ? added : (extraVariables && added);
  varCounter++;
  return var;
}
expr LLVMFunction::ToSMT() {
  // Recurse from the return value down the CFG, combining any additional
  // constraints introduced for helper variables (e.g., bitcasts) so the
  // solver sees the full set of equations.
  expr fromChildren =
      LLVMNode::MakeLLVMNode(
          shiftToMultiply, scx, *this,
          ((ReturnInst *)contents->getEntryBlock().getTerminator())
              ->getOperand(0))
          ->ToSMT();
  return (varCounter == 0) ? fromChildren : (extraVariables && fromChildren);
}
} // namespace SLOT

#include <iostream>
#include <nlohmann/json.hpp>
using json = nlohmann::json;
using namespace nlohmann::literals;
int main()
{
    // create a JSON value
    const json j =
    {
        {"number", 1}, {"string", "foo"}, {"array", {1, 2}}
    };
    // read-only access
    // output element with JSON pointer "/number"
    std::cout << j.at("/number"_json_pointer) << '\n';
    // output element with JSON pointer "/string"
    std::cout << j.at("/string"_json_pointer) << '\n';
    // output element with JSON pointer "/array"
    std::cout << j.at("/array"_json_pointer) << '\n';
    // output element with JSON pointer "/array/1"
    std::cout << j.at("/array/1"_json_pointer) << '\n';
    // out_of_range.109
    try
    {
        // try to use an array index that is not a number
        json::const_reference ref = j.at("/array/one"_json_pointer);
    }
    catch (const json::parse_error& e)
    {
        std::cout << e.what() << '\n';
    }
    // out_of_range.401
    try
    {
        // try to use an invalid array index
        json::const_reference ref = j.at("/array/4"_json_pointer);
    }
    catch (const json::out_of_range& e)
    {
        std::cout << e.what() << '\n';
    }
    // out_of_range.402
    try
    {
        // try to use the array index '-'
        json::const_reference ref = j.at("/array/-"_json_pointer);
    }
    catch (const json::out_of_range& e)
    {
        std::cout << e.what() << '\n';
    }
    // out_of_range.403
    try
    {
        // try to use a JSON pointer to a nonexistent object key
        json::const_reference ref = j.at("/foo"_json_pointer);
    }
    catch (const json::out_of_range& e)
    {
        std::cout << e.what() << '\n';
    }
    // out_of_range.404
    try
    {
        // try to use a JSON pointer that cannot be resolved
        json::const_reference ref = j.at("/number/foo"_json_pointer);
    }
    catch (const json::out_of_range& e)
    {
        std::cout << e.what() << '\n';
    }
}

