namespace fuzzer {
//
// The __start___libfuzzer_extra_counters variable is align 16, size 16 to
// ensure the padding between it and the next variable in this section (either
// __libfuzzer_extra_counters or __stop___libfuzzer_extra_counters) will be
// located at (__start___libfuzzer_extra_counters +
// sizeof(__start___libfuzzer_extra_counters)). Otherwise, the calculation of
// (stop - (start + sizeof(start))) might be skewed.
//
// The section name, __libfuzzer_extra_countaaa ends with "aaa", so it sorts
// before __libfuzzer_extra_counters alphabetically. We want the start symbol to
// be placed in the section just before the user supplied counters (if present).
//
#pragma section(".data$__libfuzzer_extra_countaaa")
ATTRIBUTE_ALIGNED(16)
__declspec(allocate(".data$__libfuzzer_extra_countaaa")) uint8_t
    __start___libfuzzer_extra_counters[16] = {0};
//
// Example of what the user-supplied counters should look like. First, the
// pragma to create the section name. It will fall alphabetically between
// ".data$__libfuzzer_extra_countaaa" and ".data$__libfuzzer_extra_countzzz".
// Next, the declspec to allocate the variable inside the specified section.
// Finally, some array, struct, whatever that is used to track the counter data.
// The size of this variable is computed at runtime by finding the difference of
// __stop___libfuzzer_extra_counters and __start___libfuzzer_extra_counters +
// sizeof(__start___libfuzzer_extra_counters).
//
//
//     #pragma section(".data$__libfuzzer_extra_counters")
//     __declspec(allocate(".data$__libfuzzer_extra_counters"))
//         uint8_t any_name_variable[64 * 1024];
//
//
// Here, the section name, __libfuzzer_extra_countzzz ends with "zzz", so it
// sorts after __libfuzzer_extra_counters alphabetically. We want the stop
// symbol to be placed in the section just after the user supplied counters (if
// present). Align to 1 so there isn't any padding placed between this and the
// previous variable.
//
#pragma section(".data$__libfuzzer_extra_countzzz")
ATTRIBUTE_ALIGNED(1)
__declspec(allocate(".data$__libfuzzer_extra_countzzz")) uint8_t
    __stop___libfuzzer_extra_counters = 0;
uint8_t *ExtraCountersBegin() {
  return __start___libfuzzer_extra_counters +
         sizeof(__start___libfuzzer_extra_counters);
}
uint8_t *ExtraCountersEnd() { return &__stop___libfuzzer_extra_counters; }
ATTRIBUTE_NO_SANITIZE_ALL
void ClearExtraCounters() {
  uint8_t *Beg = ExtraCountersBegin();
  SecureZeroMemory(Beg, ExtraCountersEnd() - Beg);
}
} // namespace fuzzer
#endif

#include <format>
#include <sm/vec>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
int main()
{
    // Set up a mplot::Visual 'scene environment'.
    mplot::Visual v(1280, 575, "Made with mplot::GraphVisual");
    // Create a GraphVisual object (obtaining a unique_ptr to the object) with a spatial offset within the scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double>> (sm::vec<float>{ 0.0f, 0.0f, 0.0f });
    // This mandatory line of boilerplate code sets the parent pointer in GraphVisual and binds some functions
    v.bindmodel (gv);
    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;
    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    x.linspace (0, 10, 11);
    // Hand chosen numbers
    sm::vvec<double> y = { 5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1 };
    // Choose a line graph by creating a lines stylepolicy datasetstyle.
    mplot::DatasetStyle ds (mplot::stylepolicy::lines);
    ds.linecolour = mplot::colour::crimson;
    // For this graph, set manual y axis limits
    gv->setlimits_y (0, 10);
    // Now set the data
    gv->setdata (x, y, ds);
    // A second DatasetStyle is used to specify a colour and linewidth for a horizontal line at y=7.
    mplot::DatasetStyle ds_horz (mplot::stylepolicy::lines);
    ds_horz.linecolour = mplot::colour::grey68;
    ds_horz.linewidth = ds.linewidth * 0.6f;
#ifdef GRAPH_LINES_SIMPLE
    gv->add_y_crossing_lines (x, y, 7, ds);
#else
    // Find, and annotate with vertical lines, the locations where the graph crosses
    // y=7. The x values of the crossing points are returned.
    sm::vvec<double> xcross = gv->add_y_crossing_lines (x, y, 7, ds, ds_horz);
    // Use results in xcross to annotate the graph
    size_t n = xcross.size();
    std::stringstream ss;
    if (n > 0) {
        // Loop through the elements of xcross, formatting a string
        for (size_t i = 0; i < n; ++i) {
            ss << std::format ("{}{}{:.2f}", ((i == 0 || i == n - 1) ? "" : ", "), (i == (n - 1) ? " and " : ""), xcross[i]);
        }
    } else {
        ss << "[no values]";
    }
    // Add a label at location {.05, .05, 0} with fontsize 0.03
    gv->addLabel (std::format("y=7 at x = {:s}", ss.str()), { 0.05f, 0.05f, 0.0f }, mplot::TextFeatures(0.03f));
#endif
    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();
    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    v.addVisualModel (gv);
    // Render the scene on the screen until user quits with 'Ctrl-q'
    v.keepOpen();
    // Because v owns the unique_ptr to the GraphVisual, its memory will be deallocated when v goes out of scope.
    return 0;
}

#include <catch2/catch_test_macros.hpp>
#include <Gorgon/Encoding/LZMA.h>
#include <fstream>
#include <string>
using namespace Gorgon;
using namespace Gorgon::Encoding;
TEST_CASE("LZMA compress and decompress vector round-trip", "[LZMA]") {
    // Read README.md from project root
    std::ifstream file(TESTDIR "/../../README.md", std::ios::binary);
    REQUIRE(file.is_open());
    std::string original((std::istreambuf_iterator<char>(file)),
                          std::istreambuf_iterator<char>());
    file.close();
    REQUIRE(!original.empty());
    // Convert to byte vector
    std::vector<Byte> input(original.begin(), original.end());
    SECTION("With uncompressed size (default)") {
        LZMA lzma(true);
        // Compress
        std::vector<Byte> compressed;
        lzma.Encode(input, compressed);
        REQUIRE(!compressed.empty());
        // Compressed output should differ from input
        REQUIRE(compressed.size() != input.size());
        // Decompress
        std::vector<Byte> decompressed;
        lzma.Decode(compressed, decompressed);
        // Verify round-trip
        REQUIRE(decompressed.size() == input.size());
        std::string result(decompressed.begin(), decompressed.end());
        REQUIRE(result == original);
    }
    SECTION("Without uncompressed size") {
        LZMA lzma(false);
        // Compress
        std::vector<Byte> compressed;
        lzma.Encode(input, compressed);
        REQUIRE(!compressed.empty());
        // Decompress (fsize unknown, rely on end marker)
        std::vector<Byte> decompressed;
        lzma.Decode(compressed, decompressed);
        // Verify round-trip
        REQUIRE(decompressed.size() == input.size());
        std::string result(decompressed.begin(), decompressed.end());
        REQUIRE(result == original);
    }
    SECTION("PropertySize returns correct values") {
        LZMA lzmaWithSize(true);
        REQUIRE(lzmaWithSize.PropertySize() == 13); // 5 props + 8 size
        LZMA lzmaNoSize(false);
        REQUIRE(lzmaNoSize.PropertySize() == 5); // 5 props only
    }
}
TEST_CASE("LZMA compress and decompress string round-trip", "[LZMA]") {
    std::string original = "Hello, this is a test string for LZMA compression! "
                           "It needs to be long enough to actually compress. "
                           "LZMA compression works best with repeated patterns. "
                           "Repeated patterns. Repeated patterns. Repeated patterns. "
                           "The quick brown fox jumps over the lazy dog. "
                           "The quick brown fox jumps over the lazy dog. "
                           "The quick brown fox jumps over the lazy dog.";
    LZMA lzma;
    // Compress string to vector
    std::vector<Byte> compressed;
    lzma.Encode(original, compressed);
    REQUIRE(!compressed.empty());
    // Decompress vector to string
    std::string decompressed;
    lzma.Decode(compressed, decompressed);
    REQUIRE(decompressed == original);
}

