#include "server.hpp"
#include <signal.h>
#include <utility>
namespace http {
namespace server {
server::server(const std::string& address, const std::string& port,
    const std::string& doc_root)
  : io_context_(1),
    signals_(io_context_),
    acceptor_(io_context_),
    connection_manager_(),
    request_handler_(doc_root)
{
  // Register to handle the signals that indicate when the server should exit.
  // It is safe to register for the same signal multiple times in a program,
  // provided all registration for the specified signal is made through Asio.
  signals_.add(SIGINT);
  signals_.add(SIGTERM);
#if defined(SIGQUIT)
  signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)
  do_await_stop();
  // Open the acceptor with the option to reuse the address (i.e. SO_REUSEADDR).
  asio::ip::tcp::resolver resolver(io_context_);
  asio::ip::tcp::endpoint endpoint =
    *resolver.resolve(address, port).begin();
  acceptor_.open(endpoint.protocol());
  acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  acceptor_.bind(endpoint);
  acceptor_.listen();
  do_accept();
}
void server::run()
{
  // The io_context::run() call will block until all asynchronous operations
  // have finished. While the server is running, there is always at least one
  // asynchronous operation outstanding: the asynchronous accept call waiting
  // for new incoming connections.
  io_context_.run();
}
void server::do_accept()
{
  acceptor_.async_accept(
      [this](std::error_code ec, asio::ip::tcp::socket socket)
      {
        // Check whether the server was stopped by a signal before this
        // completion handler had a chance to run.
        if (!acceptor_.is_open())
        {
          return;
        }
        if (!ec)
        {
          connection_manager_.start(std::make_shared<connection>(
              std::move(socket), connection_manager_, request_handler_));
        }
        do_accept();
      });
}
void server::do_await_stop()
{
  signals_.async_wait(
      [this](std::error_code /*ec*/, int /*signo*/)
      {
        // The server is stopped by cancelling all outstanding asynchronous
        // operations. Once all operations have finished the io_context::run()
        // call will exit.
        acceptor_.close();
        connection_manager_.stop_all();
      });
}
} // namespace server
} // namespace http

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// Maximum number of elements as per problem statement
const int MAXN = 200005;
int a[MAXN];
int n;
// Function to perform a query
void query(int l, int r, int &x, int &f) {
    if (l > r) {
        x = -1; f = -1;
        return;
    }
    cout << "? " << l << " " << r << endl;
    cin >> x >> f;
    // If we receive -1, it means invalid query or error, terminate to avoid TLE on closed stream
    if (x == -1) exit(0); 
}
// Recursive solver
// l, r: current range
// known_x, known_f: mode and frequency of the range if already known, else -1
void solve(int l, int r, int known_x, int known_f) {
    if (l > r) return;
    int x, f;
    if (known_x != -1) {
        x = known_x;
        f = known_f;
    } else {
        query(l, r, x, f);
    }
    // Base case: if frequency equals the length of the subarray, 
    // the whole subarray consists of x.
    if (f == r - l + 1) {
        for (int i = l; i <= r; ++i) {
            a[i] = x;
        }
        return;
    }
    // We split the problem based on the frequency f.
    // The range [l, r] has length L.
    // We query a prefix of length L - f: [l, r - f]
    // And a suffix of length L - f: [l + f, r]
    // Note: The length of the query ranges is (r - f) - l + 1 = (r - l + 1) - f = L - f.
    // These queries help us determine where x is located.
    int x1, f1;
    query(l, r - f, x1, f1);

    if (x1 == x) {
        // If the mode of the prefix is still x, then x is "dominant" in the left part.
        // We recurse on the left part with known info.
        // For the right part (the remaining suffix of size f), we treat it as a new problem.
        // The remaining part is [r - f + 1, r].
        solve(l, r - f, x1, f1);
        solve(r - f + 1, r, -1, -1);
        return;
    }

    int x2, f2;
    query(l + f, r, x2, f2);

    if (x2 == x) {
        // If the mode of the suffix is still x, then x is "dominant" in the right part.
        // Recurse on the right part with known info.
        // The remaining prefix is [l, l + f - 1].
        solve(l, l + f - 1, -1, -1);
        solve(l + f, r, x2, f2);
        return;
    }

    // If x is not the mode of the prefix nor the suffix, it means x is concentrated in the middle
    // or distributed such that it doesn't dominate the ends.
    // However, specifically, if the two query ranges [l, r-f] and [l+f, r] leave a gap in the middle,
    // that gap MUST be filled with x.
    // A gap exists if (r - f) < (l + f) - 1. 
    // The gap is [r - f + 1, l + f - 1].
    // This happens if 2*f > r - l + 1.
    if (2 * f > r - l + 1) {
        for (int i = r - f + 1; i <= l + f - 1; ++i) {
            a[i] = x;
        }
    }

    // Recurse on both sub-intervals using the information we gathered.
    // Even if ranges overlap, this is safe because the array is sorted and values are consistent.
    solve(l, r - f, x1, f1);
    solve(l + f, r, x2, f2);
}
int main() {
    // Optimization for faster I/O (though interaction requires flush)
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    if (!(cin >> n)) return 0;
    solve(1, n, -1, -1);
    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << a[i];
    }
    cout << endl;
    return 0;
}

#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/use_future.hpp>
#include <asio/write.hpp>
#include <cstring>
#include <iostream>
#include <string>
#include <type_traits>
#include <utility>
using asio::ip::tcp;
//------------------------------------------------------------------------------
// This is the simplest example of a composed asynchronous operation, where we
// simply repackage an existing operation. The asynchronous operation
// requirements are met by delegating responsibility to the underlying
// operation.
template <typename CompletionToken>
auto async_write_message(tcp::socket& socket,
    const char* message, CompletionToken&& token)
  // The return type of the initiating function is deduced from the combination
  // of CompletionToken type and the completion handler's signature. When the
  // completion token is a simple callback, the return type is void. However,
  // when the completion token is asio::yield_context (used for stackful
  // coroutines) the return type would be std::size_t, and when the completion
  // token is asio::use_future it would be std::future<std::size_t>.
  -> typename asio::async_result<
    typename std::decay<CompletionToken>::type,
    void(std::error_code, std::size_t)>::return_type
{
  // When delegating to the underlying operation we must take care to perfectly
  // forward the completion token. This ensures that our operation works
  // correctly with move-only function objects as callbacks, as well as other
  // completion token types.
  return asio::async_write(socket,
      asio::buffer(message, std::strlen(message)),
      std::forward<CompletionToken>(token));
}
//------------------------------------------------------------------------------
void test_callback()
{
  asio::io_context io_context;
  tcp::acceptor acceptor(io_context, {tcp::v4(), 55555});
  tcp::socket socket = acceptor.accept();
  // Test our asynchronous operation using a lambda as a callback.
  async_write_message(socket, "Testing callback\r\n",
      [](const std::error_code& error, std::size_t n)
      {
        if (!error)
        {
          std::cout << n << " bytes transferred\n";
        }
        else
        {
          std::cout << "Error: " << error.message() << "\n";
        }
      });
  io_context.run();
}
//------------------------------------------------------------------------------
void test_future()
{
  asio::io_context io_context;
  tcp::acceptor acceptor(io_context, {tcp::v4(), 55555});
  tcp::socket socket = acceptor.accept();
  // Test our asynchronous operation using the use_future completion token.
  // This token causes the operation's initiating function to return a future,
  // which may be used to synchronously wait for the result of the operation.
  std::future<std::size_t> f = async_write_message(
      socket, "Testing future\r\n", asio::use_future);
  io_context.run();
  try
  {
    // Get the result of the operation.
    std::size_t n = f.get();
    std::cout << n << " bytes transferred\n";
  }
  catch (const std::exception& e)
  {
    std::cout << "Error: " << e.what() << "\n";
  }
}
//------------------------------------------------------------------------------
int main()
{
  test_callback();
  test_future();
}

