#include <Alembic/AbcMaterial/MaterialFlatten.h>
#include "PrintMaterial.h"
namespace Abc =  Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;
void write()
{
    Abc::OArchive archive(
            Alembic::AbcCoreOgawa::WriteArchive(), "FlattenMaterial.abc" );
    Abc::OObject root(archive, Abc::kTop);
    //make a dummy enclosing object
    Abc::OObject materials(root, "materials");
    Mat::OMaterial parentMaterial(materials, "parentMaterial");
    parentMaterial.getSchema().setShader("prman", "surface", "paintedplastic");
    parentMaterial.getSchema().setShader("prman", "displacement", "knobby");
    {
        Abc::OFloatProperty prop(
                parentMaterial.getSchema().getShaderParameters(
                        "prman", "surface"),
                        "Kd");
        prop.set(0.5);
    }
    {
        Abc::OStringProperty prop(
                parentMaterial.getSchema().getShaderParameters(
                        "prman", "surface"), "texname");
        prop.set("taco");
    }
    {
        Abc::OFloatProperty prop(
                parentMaterial.getSchema().getShaderParameters(
                        "prman", "displacement"),
                        "height");
        prop.set(0.75);
    }
    Mat::OMaterial childMaterial(parentMaterial, "childMaterial");
    childMaterial.getSchema().setShader("prman", "surface",
            "betterpaintedplastic");
    {
        Abc::OStringProperty prop(
                childMaterial.getSchema().getShaderParameters(
                        "prman", "surface"), "texname");
        prop.set("cheese");
    }
}
void read()
{
    Abc::IArchive archive(Alembic::AbcCoreOgawa::ReadArchive(),
            "FlattenMaterial.abc");
    Abc::IObject materialsObject(archive.getTop(), "materials");
    Mat::IMaterial parentMaterial(materialsObject, "parentMaterial");
    Mat::IMaterial childMaterial(parentMaterial, "childMaterial");
    std::cout << "----------------------------------------\n";
    std::cout << "LOCAL\n";
    std::cout << "---------------------------\n";
    std::cout << "Local parent material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(parentMaterial.getSchema());
    std::cout << "---------------------------\n";
    std::cout << "Local child material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(childMaterial.getSchema());
    std::cout << "----------------------------------------\n";
    std::cout << "FLATTENED\n";
    printFlattenedMaterial(parentMaterial);
    printFlattenedMaterial(childMaterial);
}
int main( int argc, char *argv[] )
{
    write();
    read();
    return 0;
}

#include "test_ffb_common.h"
namespace FFBEngineTests {
TEST_CASE(test_issue_42_ffb_inversion_persistence, "Config") {
    std::cout << "\nTest: Issue #42 - FFB Inversion Persistence Across Presets" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    Config::LoadPresets();
    // Case 1: Start with Invert = True
    FFBEngineTestAccess::SetInvertForce(engine, true);
    ASSERT_TRUE(engine.m_invert_force);
    // Apply "Default" preset
    Config::ApplyPreset(0, engine);
    ASSERT_TRUE(engine.m_invert_force); // Should remain true
    // Apply "T300" preset (which used to set it to true explicitly)
    int t300_idx = -1;
    for(int i=0; i<(int)Config::presets.size(); i++) {
        if(Config::presets[i].name == "T300") {
            t300_idx = i;
            break;
        }
    }
    if(t300_idx != -1) {
        Config::ApplyPreset(t300_idx, engine);
        ASSERT_TRUE(engine.m_invert_force);
    }
    // Case 2: Start with Invert = False
    FFBEngineTestAccess::SetInvertForce(engine, false);
    ASSERT_FALSE(engine.m_invert_force);
    // Apply "Default" preset
    Config::ApplyPreset(0, engine);
    ASSERT_FALSE(engine.m_invert_force); // Should remain false!
    if(t300_idx != -1) {
        Config::ApplyPreset(t300_idx, engine);
        ASSERT_FALSE(engine.m_invert_force); // Should remain false!
    }
    // Case 3: Verify Preset::UpdateFromEngine doesn't capture it (indirectly verified by lack of member)
    // But we can check that if we change engine inversion, and update a preset, then change engine inversion back,
    // applying the preset doesn't revert it.
    Preset user_preset("UserTest", false);
    FFBEngineTestAccess::SetInvertForce(engine, true);
    user_preset.UpdateFromEngine(engine);
    FFBEngineTestAccess::SetInvertForce(engine, false);
    user_preset.Apply(engine);
    ASSERT_FALSE(engine.m_invert_force); // Apply should NOT have changed it to true
}
TEST_CASE(test_issue_42_ffb_inversion_global_persistence, "Config") {
    std::cout << "\nTest: Issue #42 - FFB Inversion Global Persistence (Save/Load)" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    std::string test_ini = "test_issue_42_persistence.ini";
    // Case 1: Save as True, Load
    FFBEngineTestAccess::SetInvertForce(engine, true);
    Config::Save(engine, test_ini);
    FFBEngine engine_load;
    FFBEngineTestAccess::SetInvertForce(engine_load, false); // Distort
    Config::Load(engine_load, test_ini);
    ASSERT_TRUE(engine_load.m_invert_force);
    // Case 2: Save as False, Load
    FFBEngineTestAccess::SetInvertForce(engine, false);
    Config::Save(engine, test_ini);
    FFBEngine engine_load2;
    FFBEngineTestAccess::SetInvertForce(engine_load2, true); // Distort
    Config::Load(engine_load2, test_ini);
    ASSERT_FALSE(engine_load2.m_invert_force);
    std::remove(test_ini.c_str());
}
} // namespace FFBEngineTests

