  os.flush();
  EXPECT_EQ(left, "hi....");
  std::string right;
  llvm::raw_string_ostream os2(right);
  output_right_aligned_text(os2, "hi", 6, '.', false);
  os2.flush();
  EXPECT_EQ(right, "....hi");
}
