               str = QString::asprintf("%.3f,  %.3f", pBtPolar->sailAngleMin(is), pBtPolar->sailAngleMax(is));
               writeTextElement(strange, str);
           }
       }
       writeEndElement();
   }
   writeEndElement();
}
