// Calculates the product based on set sizes
int calculateProduct(int n, int b, set<int> v, set<int> u)
{
    u.insert(b);  // Insert the value b into set u
    // Calculate the product of the differences between n and the sizes of sets v and u
    int result = (n - v.size()) * (n - u.size());
    return result;  // Return the calculated product
}

