// Generates OpenGL texture setup code
std::string generateOpenGLTextureSetup(int wrap, int minFilter, int magFilter, int internalFormat, int size)
{
    std::stringstream openglCode;
    // Set texture wrapping parameters
    openglCode << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_WRAP_R, " << wrap << ");\n";
    openglCode << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_MIN_FILTER, " << minFilter << ");\n";
    openglCode << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_MAG_FILTER, " << magFilter << ");\n";
    // Allocate 3D texture storage
    openglCode << "glTexStorage3D(GL_TEXTURE_3D, 7, " << internalFormat << ", " << size << ", " << size << ", " << size << ");\n";
    return openglCode.str();
}

#include "log.h"
#include <chrono>

// Logger class to measure elapsed time
class Logger
{
private:
    std::chrono::time_point<std::chrono::steady_clock> start_tp;

public:
    // Constructor initializes the start time point
    Logger() : start_tp(std::chrono::steady_clock::now()) {}

    // Logs the elapsed time since construction
    void logElapsedTime()
    {
        auto current_tp = std::chrono::steady_clock::now();
        auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(current_tp - start_tp).count();
