std::string getRegistryValue(const std::string& keyName, const std::string& valueName)
{
    HKEY hKey;
    std::string retrievedValue;

    // Open the registry key
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, keyName.c_str(), 0, KEY_READ, &hKey) == ERROR_SUCCESS)
    {
        DWORD type;
        DWORD dataSize;

        // Query the value type and size
        if (RegQueryValueEx(hKey, valueName.c_str(), NULL, &type, NULL, &dataSize) == ERROR_SUCCESS)
        {
            if (type == REG_SZ)
            {
                // Allocate memory for the string value
                char* buffer = new char[dataSize];

                // Retrieve the string value
                if (RegQueryValueEx(hKey, valueName.c_str(), NULL, &type, reinterpret_cast<LPBYTE>(buffer), &dataSize) == ERROR_SUCCESS)
                {
                    retrievedValue = std::string(buffer);
                }

                delete[] buffer;
            }
            // Add handling for other value types if needed (e.g., REG_DWORD, REG_BINARY, etc.)
        }

        RegCloseKey(hKey);
    }

    return retrievedValue;
