// NamespaceManager class to manage identifiers in different namespaces
class NamespaceManager {
private:
    // Nested unordered_map: outer for namespace names, inner for identifiers within each namespace
    std::unordered_map<std::string, std::unordered_map<std::string, bool>> namespaces;

public:
    // Adds an identifier to a specified namespace
    void addIdentifier(const std::string& namespaceName, const std::string& identifier) {
        namespaces[namespaceName][identifier] = true;
    }

    // Checks if an identifier exists in a given namespace and returns a message
    std::string getIdentifier(const std::string& namespaceName, const std::string& identifier) {
        if (namespaces.find(namespaceName) != namespaces.end()) {
            if (namespaces[namespaceName].find(identifier) != namespaces[namespaceName].end()) {
                return "Identifier '" + identifier + "' found in namespace '" + namespaceName + "'.";
            }
        }
        return "Identifier '" + identifier + "' not found in namespace '" + namespaceName + "'.";
    }
};

