// Caesar cipher function for a single character
char caesarCipher(char c, int key)
{
    char A = (islower(c)) ? 'a' : 'A';
    c = (isalpha(c)) ? (c - A + (26 - key)) % 26 + A : c;
    return c;
}

int main()
{
    std::string input;
    int key;

    // Prompt for input text
    std::cout << "Enter a line of text:\n";
    std::getline(std::cin, input);

    // Prompt for shift key
    std::cout << "Enter an integer to shift the text (1-25):\n";
    std::cin >> key;

    // Validate key range
    while (key < 1 || key > 25)
    {
        std::cout << "Invalid shift value. Please enter an integer between 1 and 25:\n";
        std::cin >> key;
    }

    // Encrypt the text
    std::string encryptedText;
    for (char c : input)
    {
        encryptedText += caesarCipher(c, key);
    }

    // Output result
    std::cout << "Encrypted text: " << encryptedText << std::endl;
    return 0;
}

