// Class to ensure printing in order using synchronization
class PrintInOrder {
public:
    PrintInOrder() : count(1) {}

    void first() {
        printNumber(1);
    }

    void second() {
        printNumber(2);
    }

    void third() {
        printNumber(3);
    }

private:
    int count;
    std::mutex mtx;
    std::condition_variable cv;

    // Helper function to print number with synchronization
    void printNumber(int num) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, num] { return count == num; });
        std::cout << num << std::endl;
        count++;
        cv.notify_all();
    }
};

// Test case for PrintInOrder functionality
TEST(PrintInOrderTest, Foo) {
    PrintInOrder printInOrder;
    std::thread t1(&PrintInOrder::first, &printInOrder);
    std::thread t2(&PrintInOrder::second, &printInOrder);
    std::thread t3(&PrintInOrder::third, &printInOrder);

    t1.join();
    t2.join();
    t3.join();

    std::string output = testing::internal::GetCapturedStdout();
    ASSERT_EQ(output, "123\n");
}

