// Function to check if two trees can form a pair with distance k
bool canFormTreePair(std::vector<int> tree, int k)
{
    // Sort the tree positions in ascending order
    std::sort(tree.begin(), tree.end());

    int i = 0;
    int j = tree.size() - 1;

    while (i < j)
    {
        if (tree[i] + k < tree[j])
        {
            // Move to the next tree position from the left
            i++;
        }
        else if (tree[i] + k > tree[j])
        {
            // Move to the next tree position from the right
            j--;
        }
        else
        {
            // Found two trees with distance k
            return true;
        }
    }

    // No such pair of trees found
    return false;
}

