// Class representing a list of items
class ItemList {
private:
    Item* mHead;
    Item* mCurrent;

public:
    // Constructor initializes the list
    ItemList() : mHead(nullptr), mCurrent(nullptr) {
        // Initialize the list
        // For example, add items to the list
    }

    // Adds an item with the given id to the front of the list
    void AddItem(int id) {
        // Add an item with the given id to the list
        Item* newItem = new Item();
        newItem->mnId = id;
        newItem->Next = mHead;
        mHead = newItem;
    }

    // Returns the next item in the list and advances the current pointer
    Item* Next() {
        if (mCurrent == nullptr) {
            mCurrent = mHead;
        } else {
            mCurrent = mCurrent->Next;
        }
        return mCurrent;
    }
};

