// Loads a PNG image from a stream
Bitmap LoadPNG(std::istream& stream)
{
    // Read entire stream into buffer
    std::string in_buffer((std::istreambuf_iterator<char>(stream)), std::istreambuf_iterator<char>());

    std::vector<unsigned char> out_buffer;
    unsigned long width, height;

    // Decode PNG data
    int error = decodePNG(out_buffer, width, height, reinterpret_cast<const unsigned char*>(in_buffer.c_str()), in_buffer.size());

    if(error != 0)
    {
        // Handle decoding error
        Log::Error("PNG decoding error: " + std::to_string(error));
        return Bitmap(); // Return empty bitmap on error
    }

    // Create bitmap with decoded dimensions
    Bitmap bitmap(width, height);

    // Copy pixel data from decoded buffer to bitmap
    for(unsigned long y = 0; y < height; ++y)
    {
        for(unsigned long x = 0; x < width; ++x)
        {
            unsigned long pos = (y * width + x) * 4;

            // Set pixel color using RGBA values
            bitmap.SetPixel(x, y, Color(out_buffer[pos], out_buffer[pos + 1], out_buffer[pos + 2], out_buffer[pos + 3]));
        }
    }

    return bitmap;
}

