using namespace std;

// Stock spanner class implementation
class StockSpanner {
    // Stack to store pairs of price and span
    stack<pair<int, int>> st;

public:
    // Constructor
    StockSpanner() {

    }

    // Calculate the span for the given price
    int next(int price) {
        int res = 1;

        // Pop elements while the top price is <= current price
        while (!st.empty() && st.top().first <= price) {
            res += st.top().second;
            st.pop();
        }

        // Push current price and its span
        st.push(make_pair(price, res));

        return res;
    }
};

