// Base class for IO objects
class io_base_t {
public:
  virtual bool read() = 0;
  virtual bool write() = 0;
  virtual ~io_base_t() {}

  void setFilename(const std::string& filename) {
    filename_ = filename;
  }

protected:
  std::string filename_;
};

// Factory for creating IO objects
class io_factory_t {
public:
  static io_factory_t& instance() {
    static io_factory_t factory;
    return factory;
  }

  using create_func_t = io_base_t* (*)();

  bool registerType(const std::string& type, create_func_t createFunc) {
    return creators_.emplace(type, createFunc).second;
  }

  io_base_t* create(const std::string& type, const std::string& filename) {
    auto it = creators_.find(type);
    if (it != creators_.end()) {
      io_base_t* io = it->second();
      io->setFilename(filename);
      return io;
    }
    return nullptr;
  }

private:
  io_factory_t() {}
  std::unordered_map<std::string, create_func_t> creators_;
};

