        size_t nb_recv = rte_eth_rx_burst(0, 0, mbufs, BURSTSZ);
        // Process the received packets in parallel
        #pragma omp parallel for
        for (size_t i = 0; i < nb_recv; ++i)
        {
            // Process the mbufs[i] packet here
