private:
    mt19937 rng;  // Mersenne Twister pseudo-random generator
    uniform_int_distribution<int> distribution;

public:
    // Constructor initializes RNG with current time and sets distribution range
    RandomNumberGenerator(int min, int max) 
        : rng(system_clock::now().time_since_epoch().count()), 
          distribution(min, max) {}

    // Generate a random number within the current distribution range
    int generate() {
        return distribution(rng);
    }

    // Update the distribution range
    void setRange(int newMin, int newMax) {
        distribution = uniform_int_distribution<int>(newMin, newMax);
    }
};

int main() {
    // Create a random number generator with range [1, 100]
    RandomNumberGenerator rng(1, 100);

    // Generate and print 10 random numbers
    for (int i = 0; i < 10; ++i) {
        cout << rng.generate() << " ";
    }
    cout << endl;

    // Change the range to [50, 150]
    rng.setRange(50, 150);

    // Generate and print 10 random numbers in the new range
    for (int i = 0; i < 10; ++i) {
        cout << rng.generate() << " ";
    }
    cout << endl;

    return 0;
}

