#include <iostream>

// State machine implementation
class StateMachine {
public:
    enum State {
        STATE_A,
        STATE_B,
        STATE_C
    };

    // Constructor initializes state machine to STATE_A
    StateMachine() : currentState(STATE_A) {}

    // Method to transition to a new state
    void transitionTo(State newState) {
        currentState = newState;
    }

    // Method to retrieve the current state
    State getCurrentState() {
        return currentState;
    }

private:
    State currentState;
};

int main() {
    StateMachine sm;

    // Print initial state
    std::cout << "Current state: " << sm.getCurrentState() << std::endl;

    // Transition to STATE_B
    sm.transitionTo(StateMachine::STATE_B);
    std::cout << "Current state: " << sm.getCurrentState() << std::endl;

    // Transition to STATE_C
    sm.transitionTo(StateMachine::STATE_C);
    std::cout << "Current state: " << sm.getCurrentState() << std::endl;

    return 0;
}

