// Forward declarations
class CExpr;
class CApply;

// Visitor interface
class IVisitor {
public:
    virtual void visit(CExpr* e) = 0;
    virtual void visit(CApply* e) = 0;
};

// Expression base class
class CExpr {
public:
    virtual void accept(IVisitor* visitor) = 0;
};

// Apply expression class
class CApply : public CExpr {
public:
    void accept(IVisitor* visitor) override {
        visitor->visit(this);
    }
};

// Pretty printer class
class CPrettyPrinter : public IVisitor {
public:
    void visit(CExpr* e) override {
        std::cout << "Default expression visit" << std::endl;
    }

    void visit(CApply* e) override {
        std::cout << "(";
        // Additional pretty printing logic for CApply
        std::cout << ")";
    }
};

int main() {
    std::unique_ptr<CExpr> expr = std::make_unique<CApply>();
    CPrettyPrinter printer;
    expr->accept(&printer);
    return 0;
}

