// Tic Tac Toe game class
class TicTacToe {
private:
    std::vector<std::vector<char>> board;
    char current_player;

public:
    // Constructor initializes the board and current player
    TicTacToe() : board(3, std::vector<char>(3, ' ')), current_player('X') {}

    // Marks a position on the board
    void mark_board(int position) {
        int row = (position - 1) / 3;
        int col = (position - 1) % 3;
        if (board[row][col] == ' ') {
            board[row][col] = current_player;
            current_player = (current_player == 'X') ? 'O' : 'X';
        }
    }

    // Checks if the given player has won
    bool check_winner(char player) {
        // Check rows
        for (int i = 0; i < 3; ++i) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < 3; ++i) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check diagonals
        if ((board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
            (board[0][2] == player && board[1][1] == player && board[2][0] == player)) {
            return true;
        }
        return false;
    }

    // Determines if the game is over
    bool game_over() {
        if (check_winner('X') || check_winner('O')) {
            return true;
        }
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (board[i][j] == ' ') {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
    TicTacToe* game = new TicTacToe();

    // Player X moves
    game->mark_board(1);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    // Player O moves
    game->mark_board(2);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    // Player X moves
    game->mark_board(3);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    // Player O moves
    game->mark_board(4);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    // Player X moves
    game->mark_board(5);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    // Player O moves
    game->mark_board(7);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    delete game;
    return 0;
}

