// Class definition for OverloadedFunctions
class OverloadedFunctions {
private:
    int data;
public:
    // Constructor initializes data to 0
    OverloadedFunctions() : data(0) {}

    // Lvalue reference overload: adds value to data
    void process(int& value) & {
        data += value;
    }

    // Rvalue reference overload: subtracts value from data
    void process(int&& value) && {
        data -= value;
    }

    // Getter method for data
    int getData() const {
        return data;
    }
};

// Main function demonstrating overloading
int main()
{
    // Create first object and process lvalue
    OverloadedFunctions obj1;
    int val1 = 5;
    obj1.process(val1);  // Calls process(int& value) & and increments data by 5

    // Print result for first object
    std::cout << "Data after lvalue process: " << obj1.getData() << std::endl;

    // Create second object and process rvalue
    OverloadedFunctions obj2;
    obj2.process(3);  // Calls process(int&& value) && and decrements data by 3

    // Print result for second object
    std::cout << "Data after rvalue process: " << obj2.getData() << std::endl;

    return 0;
}

