// Checks if a binary tree is symmetric
bool isSymmetric(TreeNode* root)
{
    if(root == NULL)
    {
        return true; // An empty tree is symmetric
    }
    return isMirror(root->left, root->right);
}

// Helper function to check if two subtrees are mirrors of each other
bool isMirror(TreeNode* leftSub, TreeNode* rightSub)
{
    if(leftSub == NULL && rightSub == NULL)
    {
        return true; // Both subtrees are empty, so they are symmetric
    }
    if(leftSub == NULL || rightSub == NULL)
    {
        return false; // One subtree is empty while the other is not, so they are not symmetric
    }
    if(leftSub->val != rightSub->val)
    {
        return false; // Values at the current nodes are different, so they are not symmetric
    }
    return isMirror(leftSub->left, rightSub->right) && isMirror(leftSub->right, rightSub->left);
}

