SIZE_T CalculateProcessMemoryUsage(DWORD processId)
{
    HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, processId);
    if(hProcess == NULL)
    {
        // Handle error in opening the process
