// Calculates the rotation matrix from roll, pitch, yaw angles
Eigen::Matrix3d calculateRotationMatrix(double roll, double pitch, double yaw)
{
    Eigen::Matrix3d R_x, R_y, R_z, R;

    // Rotation around x-axis (roll)
    R_x << 1, 0, 0,
           0, cos(roll), -sin(roll),
           0, sin(roll), cos(roll);

    // Rotation around y-axis (pitch)
    R_y << cos(pitch), 0, sin(pitch),
           0, 1, 0,
           -sin(pitch), 0, cos(pitch);

    // Rotation around z-axis (yaw)
    R_z << cos(yaw), -sin(yaw), 0,
           sin(yaw), cos(yaw), 0,
           0, 0, 1;

    // Combined rotation: R = R_z * R_y * R_x
    R = R_z * R_y * R_x;

    return R;
}

int main()
{
    // Example Euler angles in radians
    double roll = 0.1;   // Roll angle
    double pitch = 0.2;  // Pitch angle
    double yaw = 0.3;    // Yaw angle

    // Compute rotation matrix
    Eigen::Matrix3d rotationMatrix = calculateRotationMatrix(roll, pitch, yaw);

    // Output the result
    std::cout << "Rotation Matrix:" << std::endl << rotationMatrix << std::endl;

    return 0;

}

