// Macro for logging errors
#define LOG_ERROR(log, message, query_id, error_code) do { \
    std::ostringstream error_message_stream; \
    error_message_stream << message; \
    std::string formatted_message = error_message_stream.str(); \
    size_t query_id_pos = formatted_message.find("query_id={}"); \
    if (query_id_pos != std::string::npos) { \
        formatted_message.replace(query_id_pos, 11, "query_id=" + std::to_string(query_id)); \
    } \
    size_t error_code_pos = formatted_message.find("error={}"); \
    if (error_code_pos != std::string::npos) { \
        formatted_message.replace(error_code_pos, 9, "error=" + std::to_string(error_code)); \
    } \
    log.logError(formatted_message); \
} while(0)

// Exception class
class Exception {
public:
    Exception(const std::string& message, int error_code) {
        std::ostringstream error_message_stream;
        error_message_stream << message;
        std::string formatted_message = error_message_stream.str();
        size_t error_code_pos = formatted_message.find("error={}");
        if (error_code_pos != std::string::npos) {
            formatted_message.replace(error_code_pos, 8, "error=" + std::to_string(error_code));
        }
        throw std::runtime_error(formatted_message);
    }
};

