// Define the orcamap function to map 2D coordinates to 3D indices
std::vector<int> orcamap(int eta, int phi)
{
    std::vector<int> indices(3);
    // Calculate the first index
    indices[0] = phi / 8;
    // Calculate the second index
    indices[1] = eta / 8;
    // Calculate the third index
    indices[2] = phi % 8 * 8 + eta % 8;
    return indices;
}

