// Class to manage a secret number guessing game
class SecretNumber {
private:
    int secret;
    std::pair<int, int> range;
    int guessCount;

public:
    // Constructor initializes the secret number and range
    SecretNumber(int min, int max)
        : range(std::make_pair(min, max)), guessCount(0)
    {
        srand(static_cast<unsigned int>(time(nullptr)));
        secret = rand() % (max - min + 1) + min;
    }

    // Process a guess and return whether it's correct
    bool makeGuess(int guess)
    {
        guessCount++;
        return guess == secret;
    }

    // Get the range of possible values
    std::pair<int, int> getRange()
    {
        return range;
    }

    // Get the number of guesses made so far
    int getGuessCount()
    {
        return guessCount;
    }
};

