// Class for modifying HTTP request headers
class HeaderModifier {
public:
    // Modifies the request header if it matches predefined rules
    bool ModifyRequestHeader(const std::string& header) {
        // Check if the header contains "User-Agent"
        if (header.find("User-Agent") != std::string::npos) {
            // Replace with custom User-Agent
            modifiedHeaders += "User-Agent: Custom-Agent\r\n";
            return true;  // Modification was successful
        }
        // Additional rules can be added here
        return false;  // No modification applied
    }

    // Returns all modified headers
    std::string GetModifiedHeaders() const {
        return modifiedHeaders;
    }

private:
    std::string modifiedHeaders;  // Stores modified header data
};

// Main function to demonstrate header modification
int main() {
    // Sample HTTP request data
    std::string data = "GET /index.html HTTP/1.1\r\nHost: www.example.com\r\nUser-Agent: Mozilla/5.0\r\n\r\n";

    // Initialize modifier and parsing variables
    HeaderModifier test;
    const char* current_data = data.c_str();
    unsigned long current_data_len = data.length();
    bool is_modified = false;
    std::string headers;

    // Parse each line of the HTTP headers
    while (current_data_len) {
        std::string line;

        // Extract a single line
        while (*current_data != '\r' && *current_data != '\n' && current_data_len) {
            line += *current_data;
            ++current_data;
            --current_data_len;
        }

        // Handle line endings
        if (*current_data == '\r' || *current_data == '\n') {
            if (!line.empty()) {
                // Attempt to modify the header line
                if (test.ModifyRequestHeader(line))
                    is_modified = true;

                // Add original or modified line to headers
                if (!line.empty()) {
                    headers += line;
                    headers += "\r\n";
                }
            }

            // Skip the line ending characters
            ++current_data;
            --current_data_len;
        }
    }

    // Apply modifications if any were made
    if (is_modified) {
        headers = test.GetModifiedHeaders();
    }

    // Output the final headers
    std::cout << "Modified Headers:\n" << headers << std::endl;
    return 0;
}

