// Log level enumeration
enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

class Logger {
public:
    // Set the minimum log level to display
    void setLogLevel(LogLevel level) {
        logLevel = level;
    }

    // Add an output stream destination for logs
    void addOutputDestination(std::ostream& output) {
        outputDestinations.push_back(&output);
    }

    // Core logging function
    void log(LogLevel level, const std::string& message) {
        if (level >= logLevel) {
            for (auto dest : outputDestinations) {
                (*dest) << "[" << logLevelToString(level) << "] " << message << std::endl;
            }
        }
    }

    // Convenience methods for specific log levels
    void logDebug(const std::string& message) {
        log(LogLevel::DEBUG, message);
    }

    void logInfo(const std::string& message) {
        log(LogLevel::INFO, message);
    }

    void logWarning(const std::string& message) {
        log(LogLevel::WARNING, message);
    }

    void logError(const std::string& message) {
        log(LogLevel::ERROR, message);
    }

private:
    LogLevel logLevel = LogLevel::DEBUG;
    std::vector<std::ostream*> outputDestinations;

    // Convert log level enum to string
    std::string logLevelToString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO: return "INFO";
            case LogLevel::WARNING: return "WARNING";
            case LogLevel::ERROR: return "ERROR";
        }
        return "";
    }
};

int main() {
    Logger logger;

    // Add console as output destination
    logger.addOutputDestination(std::cout);

    // Add file as output destination
    std::ofstream file("log.txt");
    logger.addOutputDestination(file);

    // Set minimum log level to INFO
    logger.setLogLevel(LogLevel::INFO);

    // Log messages at various levels
    logger.logDebug("This is a debug message");
    logger.logInfo("This is an info message");
    logger.logWarning("This is a warning message");
    logger.logError("This is an error message");

    file.close();  // Close the file stream

    return 0;
}

