// Log levels enumeration
enum class LogLevel { INFO, WARNING, ERROR, DEBUG };

class Logger {
public:
    // Log an info message
    void info(const std::string& message) {
        log(LogLevel::INFO, message);
    }

    // Log a warning message
    void warning(const std::string& message) {
        log(LogLevel::WARNING, message);
    }

    // Log an error message
    void error(const std::string& message) {
        log(LogLevel::ERROR, message);
    }

    // Log a debug message
    void debug(const std::string& message) {
        log(LogLevel::DEBUG, message);
    }

    // Assert condition and log if failed
    void assertCondition(bool condition, const std::string& message) {
        if (!condition) {
            error("Assertion failed: " + message);
            terminateProgram();
        }
    }

    // Set output destination for logs
    void setOutputDestination(std::ostream& output) {
        output_ = &output;
    }

private:
    std::ostream* output_ = &std::cout;

    // Core logging function
    void log(LogLevel level, const std::string& message) {
        std::string levelStr;
        switch (level) {
            case LogLevel::INFO:
                levelStr = "INFO";
                break;
            case LogLevel::WARNING:
                levelStr = "WARNING";
                break;
            case LogLevel::ERROR:
                levelStr = "ERROR";
                break;
            case LogLevel::DEBUG:
                levelStr = "DEBUG";
                break;
        }
        (*output_) << "[" << levelStr << "] " << message << std::endl;
    }

    // Terminate program on assertion failure
    void terminateProgram() {
        throw std::runtime_error("Program terminated due to assertion failure");
    }
};

int main() {
    Logger logger;
    logger.error("An error occurred");
    logger.debug("Debugging information");
    logger.setOutputDestination(std::cerr);
    logger.warning("This is a warning");
    logger.assertCondition(2 + 2 == 5, "Math is broken");
    logger.info("This message should not be logged");
    return 0;
}

