using namespace std;

// Stack class implementation with min functionality
class Stack {
private:
    stack<int> mainStack;
    stack<int> minStack;

public:
    // Push element onto stack
    void push(int x) {
        // Add element to main stack
        mainStack.push(x);

        // Update minStack if the added element is smaller or equal to the current minimum
        if (minStack.empty() || x <= minStack.top()) {
            minStack.push(x);
        }
    }

    // Pop element from stack
    void pop() {
        // Remove element from main stack
        if (mainStack.top() == minStack.top()) {
            minStack.pop();
        }
        mainStack.pop();
    }

    // Get top element
    int top() {
        return mainStack.top();
    }

    // Check if stack is empty
    bool isEmpty() {
        return mainStack.empty();
    }

    // Get minimum element
    int getMin() {
        return minStack.top();
    }
};

#include <type_traits>

// Enum to control caching policy
enum class ExternalFunctorObjectToBeCached { yes, no };

// TaskType class template
template <typename ReturnType, bool IsConst, ExternalFunctorObjectToBeCached CachePolicy, class Func>
class TaskType {
public:
    // Execute the stored function
    ReturnType execute() {
        return func_;
    }

private:
    Func func_;
};

// First overload: deduces return type and assumes constness, no caching
template <class Func>
constexpr auto make_TaskType() {
    return TaskType<std::invoke_result_t<Func>, true, ExternalFunctorObjectToBeCached::no, Func>();
}

// Second overload: takes a value and forwards the functor
template <typename T, std::conditional_t<std::is_class<T>::value, T&, T> val, class Func>
constexpr auto make_TaskType(Func&& func) {
    return TaskType<T, std::is_const<T>::value, ExternalFunctorObjectToBeCached::no, Func>(std::forward<Func>(func));
}

