// Function to calculate the MZs of y ion fragments
void calculateYIonMZs(std::string peptideSequence, std::vector<double>& vvdYionMass)
{
    // Define the mass values of amino acids
    std::unordered_map<char, double> aminoAcidMass = {
        {'A', 71.03711},
        {'R', 156.10111},
        {'N', 114.04293},
        {'D', 115.02694},
        {'C', 103.00919},
        {'E', 129.04259},
        {'Q', 128.05858},
        {'G', 57.02146},
        {'H', 137.05891},
        {'I', 113.08406},
        {'L', 113.08406},
        {'K', 128.09496},
        {'M', 131.04049},
        {'F', 147.06841},
        {'P', 97.05276},
        {'S', 87.03203},
        {'T', 101.04768},
        {'W', 186.07931},
        {'Y', 163.06333},
        {'V', 99.06841}
    };

    // Calculate the MZs of y ion fragments
    double yIonMass = 0;
    for(int i=1; i<peptideSequence.length(); ++i)
    {
        yIonMass += aminoAcidMass[peptideSequence[i-1]];
        vvdYionMass[i-1] = (yIonMass + 1) / 1; // Assuming charge = 1
    }
}

int main()
{
    std::string peptideSeq = "PEPTIDE";
    std::vector<double> yIonMasses(peptideSeq.length() - 1, 0);
    calculateYIonMZs(peptideSeq, yIonMasses);

    // Output the calculated MZs of y ion fragments
    for(double mz : yIonMasses)
    {
        std::cout << mz << " ";
    }

    return 0;
}

#include <mutex>
#include <condition_variable>
#include <iostream>
#include <thread>
#include <vector>

// FenceManager class for synchronization
class FenceManager {
public:
    // Create a new fence with given value
    void CreateFence(int fenceValue)
    {
        std::unique_lock<std::mutex> lock(_mutex);
        _fenceValues.push_back(fenceValue);
        _fences.push_back(false);
    }

    // Signal the fence with specified value
    void SignalFence(int fenceValue)
    {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = std::find(_fenceValues.begin(), _fenceValues.end(), fenceValue);
        if (it != _fenceValues.end())
        {
            size_t index = std::distance(_fenceValues.begin(), it);
            _fences[index] = true;
            _cv.notify_all();
        }
    }

    // Wait until the fence with specified value is signaled
    void WaitForFence(int fenceValue)
    {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = std::find(_fenceValues.begin(), _fenceValues.end(), fenceValue);
        if (it != _fenceValues.end())
        {
            size_t index = std::distance(_fenceValues.begin(), it);
            _cv.wait(lock, [this, index] { return _fences[index]; });
        }
    }

private:
    std::vector<int> _fenceValues;
    std::vector<bool> _fences;
    std::mutex _mutex;
    std::condition_variable _cv;
};

// Main function demonstrating fence usage
int main()
{
    FenceManager fenceManager;

    // Create fences
    fenceManager.CreateFence(1);
    fenceManager.CreateFence(2);
    fenceManager.CreateFence(3);

    // Signal fences from different threads
    std::thread t1([&fenceManager] { fenceManager.SignalFence(1); });
    std::thread t2([&fenceManager] { fenceManager.SignalFence(2); });
    std::thread t3([&fenceManager] { fenceManager.SignalFence(3); });

    t1.join();
    t2.join();
    t3.join();

    // Wait for fences to be signaled
    fenceManager.WaitForFence(1);
    fenceManager.WaitForFence(2);
    fenceManager.WaitForFence(3);

    std::cout << "All fences signaled." << std::endl;
    return 0;
}

