void RemoveExtraArguments(QueryArgumentMap& queryArgs, const std::set<std::string>& setName)
{
    // Create a copy of the queryArgs map to iterate over and remove entries
    QueryArgumentMap queryArgsCopy = queryArgs;

    // Iterate over the queryArgsCopy and remove entries with keys not present in setName
    for(auto it = queryArgsCopy.begin(); it != queryArgsCopy.end(); )
    {
        if(setName.find(it->first) == setName.end())
        {
            queryArgs.erase(it++);
        }
        else
        {
            ++it;
        }
    }
}

