#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

// Scheduler class for managing tasks in a separate thread
class Scheduler {
public:
    // Constructor initializes the running flag
    Scheduler() : running(true) {}

    // Starts the worker thread
    void startAsync()
    {
        worker = std::thread([this] { this->run(); });
    }

    // Adds a task to the queue
    void addTask(void (*task)())
    {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push(task);
        condition.notify_one();
    }

    // Main worker loop
    void run()
    {
        while (running)
        {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !tasks.empty() || !running; });
            if (!tasks.empty())
            {
                auto task = tasks.front();
                tasks.pop();
                lock.unlock();  // Release the lock before executing the task
                task();         // Execute the task
            }
        }
    }

    // Destructor ensures clean shutdown
    ~Scheduler()
    {
        running = false;
        condition.notify_one();  // Notify the running thread to exit
        if (worker.joinable())
        {
            worker.join();
        }
    }

private:
    std::queue<void (*)()> tasks;
    std::mutex mutex;
    std::condition_variable condition;
    std::thread worker;
    bool running;
};

