// Observer interface for notification pattern
class AIObserver
{
public:
    virtual ~AIObserver() {};
    virtual void OnNotify(/*add parameters*/) = 0;
};

// Subject class that maintains observers and notifies them
class Subject
{
public:
    // Add an observer to the list
    void Subscribe(AIObserver* observer)
    {
        observers.push_back(observer);
    }

    // Remove an observer from the list
    void Unsubscribe(AIObserver* observer)
    {
        auto it = std::find(observers.begin(), observers.end(), observer);
        if (it != observers.end())
        {
            observers.erase(it);
        }
    }

    // Notify all registered observers
    void Notify(/*add parameters*/)
    {
        for (auto observer : observers)
        {
            observer->OnNotify(/*pass parameters*/);
        }
    }

private:
    std::vector<AIObserver*> observers;
};

