#include <vector>
#include <stack>

// Solution class for minimum operations
class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        std::stack<int> st;
        int ans = 0;
        // Iterate through each number in the input vector
        for (int num : nums) {
            // Remove elements from stack that are greater than current number
            while (!st.empty() && num < st.top()) {
                st.pop();  // Invalidate larger numbers for current context
            }
            // Push new element if stack is empty or current number is greater than top
            if (st.empty() || num > st.top()) {
                if (num > 0) ans++;
                st.push(num);
            }
        }
        return ans;
    }
};

