#include <vector>
#include <algorithm>

class Solution {
public:
    // Replace non-coprime adjacent elements with their LCM
    vector<int> replaceNonCoprimes(vector<int>& nums) {
        vector<int> result;

        for(int &i:nums) {
            result.push_back(i);        // Push the new element in stack

            // While we have two elements and they are not co-prime
            while(result.size()>1 && __gcd(result.back(), result[result.size()-2]) > 1) {
                long long a = result.back();
                long long b = result[result.size()-2];
                long long g = __gcd(a, b);  // Get the last two numbers and their GCD

                // Remove the two elements
                result.pop_back();
                result.pop_back();

                // Push the LCM of the two numbers, replacing them
                result.push_back(a * b / g);
            }
        }

        return result;
    }
};

