#include "ARM.h"
#include "ARMInstrInfo.h"
#include "ARMMachineFunctionInfo.h"
#include "llvm/ADT/Statistic.h"
#include "llvm/CodeGen/MachineFunctionPass.h"

using namespace llvm;

#define DEBUG_TYPE "double barriers"

STATISTIC(NumDMBsRemoved, "Number of DMBs removed");

namespace {

class ARMOptimizeBarriersPass : public MachineFunctionPass {
public:
  static char ID;

  ARMOptimizeBarriersPass() : MachineFunctionPass(ID) {}

  bool runOnMachineFunction(MachineFunction &Fn) override;

  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }

  StringRef getPassName() const override { 
    return "optimise barriers pass"; 
  }
};

char ARMOptimizeBarriersPass::ID = 0;

}

// Returns whether the instruction can safely move past a DMB instruction
// The current implementation allows this iif MI does not have any possible
// memory access
static bool CanMovePastDMB(const MachineInstr *MI) {
  return !(MI->mayLoad() ||
           MI->mayStore() ||
           MI->hasUnmodeledSideEffects() ||
           MI->isCall() ||
           MI->isReturn());
}

bool ARMOptimizeBarriersPass::runOnMachineFunction(MachineFunction &MF) {
  if (skipFunction(MF.getFunction()))
    return false;

  // Vector to store the DMBs we will remove after the first iteration
  std::vector<MachineInstr *> ToRemove;

  // DMBType is the Imm value of the first operand. It determines whether it's a
  // DMB ish, dmb sy, dmb osh, etc
  int64_t DMBType = -1;

  // Find a dmb. If we can move it until the next dmb, tag the second one for
  // removal
  for (auto &MBB : MF) {
    // Will be true when we have seen a DMB, and not seen any instruction since
    // that cannot move past a DMB
    bool IsRemovableNextDMB = false;

    for (auto &MI : MBB) {
      if (MI.getOpcode() == ARM::DMB) {
        if (IsRemovableNextDMB) {
          // If the Imm of this DMB is the same as that of the last DMB, we can
          // tag this second DMB for removal
          if (MI.getOperand(0).getImm() == DMBType) {
            ToRemove.push_back(&MI);
          } else {
            // If it has a different DMBType, we cannot remove it, but will scan
            // for the next DMB, recording this DMB's type as last seen DMB type
            DMBType = MI.getOperand(0).getImm();
          }
        } else {
          // After we see a DMB, a next one is removable
          IsRemovableNextDMB = true;
          DMBType = MI.getOperand(0).getImm();
        }
      } else if (!CanMovePastDMB(&MI)) {
        // If we find an instruction unable to pass past a DMB, a next DMB is
        // not removable
        IsRemovableNextDMB = false;
      }
    }
  }

  bool Changed = false;

  // Remove the tagged DMB
  for (auto *MI : ToRemove) {
    MI->eraseFromParent();
    ++NumDMBsRemoved;
    Changed = true;
  }

  return Changed;
}

/// createARMOptimizeBarriersPass - Returns an instance of the remove double
/// barriers
/// pass.
FunctionPass *llvm::createARMOptimizeBarriersPass() {
  return new ARMOptimizeBarriersPass();
}

#include "ReduceInstructions.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include <set>

using namespace llvm;

/// Filter out cases where deleting the instruction will likely cause the
/// user/def of the instruction to fail the verifier.
//
// TODO: Technically the verifier only enforces preallocated token usage and
// there is a none token.
static bool shouldAlwaysKeep(const Instruction &I)
{
    return I.isEHPad() || I.getType()->isTokenTy() || I.isSwiftError();
}

/// Removes out-of-chunk arguments from functions, and modifies their calls
/// accordingly. It also removes allocations of out-of-chunk arguments.
static void extractInstrFromModule(Oracle &O, ReducerWorkItem &WorkItem)
{
    Module &Program = WorkItem.getModule();

    std::vector<Instruction *> InitInstToKeep;

    for (auto &F : Program)
        for (auto &BB : F)
        {
            // Removing the terminator would make the block invalid. Only iterate over
            // instructions before the terminator.
            InitInstToKeep.push_back(BB.getTerminator());

            for (auto &Inst : make_range(BB.begin(), std::prev(BB.end())))
            {
                if (shouldAlwaysKeep(Inst) || O.shouldKeep())
                    InitInstToKeep.push_back(&Inst);
            }
        }

    // We create a vector first, then convert it to a set, so that we don't have
    // to pay the cost of rebalancing the set frequently if the order we insert
    // the elements doesn't match the order they should appear inside the set.
    std::set<Instruction *> InstToKeep(InitInstToKeep.begin(),
                                       InitInstToKeep.end());

    std::vector<Instruction *> InstToDelete;

    for (auto &F : Program)
        for (auto &BB : F)
            for (auto &Inst : BB)
                if (!InstToKeep.count(&Inst))
                {
                    Inst.replaceAllUsesWith(getDefaultValue(Inst.getType()));
                    InstToDelete.push_back(&Inst);
                }

    for (auto &I : InstToDelete)
        I->eraseFromParent();
}

void llvm::reduceInstructionsDeltaPass(TestRunner &Test)
{
    runDeltaPass(Test, extractInstrFromModule, "Reducing Instructions");
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>

using namespace std;

// Wrapper for query to handle interaction and termination checks
int ask(int i, int j)
{
    cout << "? " << i << " " << j << endl;
    int res;
    cin >> res;
    if (res == -1) {
        exit(0);
    }
    return res;
}

void solve()
{
    int n;
    if (!(cin >> n)) return;

    // Use a vector of player indices to allow random shuffling
    vector<int> p(n);
    iota(p.begin(), p.end(), 1);

    // Random shuffle helps in finding the Impostor earlier on average,
    // reducing the total cost (Q).
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    shuffle(p.begin(), p.end(), rng);

    int impostor = -1;

    // We process players in pairs (p[k], p[k+1]).
    // Since there is exactly one Impostor, any pair not containing the Impostor
    // will yield symmetric responses (both 0 or both 1).
    // The pair containing the Impostor will yield asymmetric responses (0 and 1).

    int limit = n - (n % 2);

    for (int k = 0; k < limit; k += 2)
    {
        int u = p[k];
        int v = p[k+1];

        int r1 = ask(u, v); // u's opinion of v
        int r2 = ask(v, u); // v's opinion of u

        if (r1 != r2)
        {
            // Found the pair containing the Impostor: {u, v}
            // One is the Impostor, the other is a Knight or Knave.
            // Since we found the Impostor pair, any other player w is NOT the Impostor.
            // We use w as a witness to distinguish between u and v.

            int w;
            // Pick a valid witness w != u and w != v
            if (k == 0)
            {
                // If we are at the first pair, picking from p[2] is safe because n >= 3
                // If n=3, p[2] is the leftover, which is safe since Impostor is in {u, v}
                w = p[2];
            }
            else
            {
                // If we are past the first pair, p[0] is safe
                w = p[0];
            }

            int q1 = ask(u, w); // u's opinion of w
            int q2 = ask(v, w); // v's opinion of w

            if (q1 != q2)
            {
                // Case 1: The pair consists of a Knight and an Impostor.
                // A Knight tells the truth about w.
                // An Impostor lies about w (behaves like a Knave).
                // Since w is not an Impostor, Truth(w) != Lie(w).
                // In the initial pair check {K, I}:
                // K -> I is 1 (Knight sees Impostor as Knight)
                // I -> K is 0 (Impostor sees Knight as Knight, lies -> 0)
                // So the one who said 0 is the Impostor.
                if (r1 == 0) impostor = u;
                else impostor = v;
            }
            else
            {
                // Case 2: The pair consists of a Knave and an Impostor.
                // A Knave lies about w.
                // An Impostor lies about w.
                // Lie(w) == Lie(w), so q1 == q2.
                // In the initial pair check {L, I}:
                // L -> I is 0 (Knave sees Impostor as Knight, lies -> 0)
                // I -> L is 1 (Impostor sees Knave as Knave, lies -> 1)
                // So the one who said 1 is the Impostor.
                if (r1 == 1) impostor = u;
                else impostor = v;
            }

            cout << "! " << impostor << endl;
            return;
        }
    }

    // If we checked all pairs and found no asymmetry, the Impostor must be the leftover player.
    // This is only possible if n is odd.
    if (n % 2 == 1)
    {
        cout << "! " << p[n-1] << endl;
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t)
    {
        while(t--)
        {
            solve();
        }
    }
    return 0;
}

