            nowbar::ControlPanelCore::shutdown();
            nowbar::PlaybackStateManager::shutdown();

            if (g_gdiplusToken) {
                Gdiplus::GdiplusShutdown(g_gdiplusToken);
                g_gdiplusToken = 0;
            }
        }
    };

    static initquit_factory_t<GdiplusInitializer> g_gdiplus_init;
