// Branch function for left path
unsigned int BoolNatTernaryPrecedenceSafe::branch_left(const bool b)
{
    if(b)
    {
        return (0 + 1);
    }
    else
    {
        return 0;
    }
}

// Branch function for right path
unsigned int BoolNatTernaryPrecedenceSafe::branch_right(const bool b)
{
    if(b)
    {
        return ((0 + 1) + 1);
    }
    else
    {
        return (((0 + 1) + 1) + 1);
    }
}

