#include <iostream>
#include <cmath>

// This function implements the recursive solution to move n balls
// from the 'from' basket to the 'to' basket, using 'other' as auxiliary.
void solve(int n, int from, int to, int other)
{
    if (n == 0)
    {
        return;
    }
    // Step 1: Move n-1 balls from 'from' to 'other'
    solve(n - 1, from, other, to);

    // Step 2: Move the nth ball from 'from' to 'to'
    std::cout << from << " " << to << "\n";

    // Step 3: Move n-1 balls from 'other' to 'to'
    solve(n - 1, other, to, from);
}

int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    std::cin >> n;

    // The total number of moves for N balls is 2^N - 1.
    // We use long long to avoid overflow for larger N, though for N > 20
    // the number of moves becomes very large to print within time limits.
    // This suggests test cases will have N small enough.
    long long moves = (1LL << n) - 1;
    std::cout << moves << "\n";

    // Start the process to move N balls from basket 1 to 3, using 2 as auxiliary.
    solve(n, 1, 3, 2);

    return 0;
}

#include <format>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

// Main function demonstrating mplot usage with GraphVisual
int main()
{
    // Set up a mplot::Visual 'scene environment'.
    mplot::Visual v(1024, 768, "Made with mplot::GraphVisual");

    // Create a GraphVisual object (obtaining a unique_ptr to the object) with a spatial offset within the scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // This mandatory line of boilerplate code sets the parent pointer in GraphVisual and binds some functions
    v.bindmodel(gv);

    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> y;

    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    y.linspace(0, 10, 11);

    // Hand chosen numbers
    sm::vvec<double> x = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Choose a line graph by creating a lines stylepolicy datasetstyle.
    mplot::DatasetStyle ds(mplot::stylepolicy::lines);
    ds.linecolour = mplot::colour::crimson;

    // For this graph, set manual y axis limits
    gv->setlimits_y(0, 10);

    // Now set the data
    gv->setdata(x, y, ds);

    // A second DatasetStyle is used to specify a colour and linewidth for a vertical line at x=3.3
    mplot::DatasetStyle ds_vert(mplot::stylepolicy::lines);
    ds_vert.linecolour = mplot::colour::grey68;
    ds_vert.linewidth = ds.linewidth * 0.6f;

    // Find, and annotate with vertical lines, the locations where the graph crosses
    // x=3.3. The y values of the crossing points are returned.
    sm::vvec<double> ycross = gv->add_x_crossing_lines(x, y, 3.3, ds, ds_vert);

    size_t n = ycross.size();

    std::stringstream ss;

    if (n > 0)
    {
        // Loop through the elements of ycross, formatting a string
        for (size_t i = 0; i < n; ++i)
        {
            ss << std::format("{}{}{:.2f}", ((i == 0 || i == n - 1) ? "" : ", "), (i == (n - 1) ? " and " : ""), ycross[i]);
        }
    }
    else
    {
        ss << "[no values]";
    }

    // Add a label at location {.05, .05, 0} with fontsize 0.03
    gv->addLabel(std::format("At x=3.3, y = {:s}", ss.str()), {0.05f, 0.05f, 0.0f}, mplot::TextFeatures(0.03f));

    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();

    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    v.addVisualModel(gv);

    // Render the scene on the screen until user quits with 'Ctrl-q'
    v.keepOpen();

    // Because v owns the unique_ptr to the GraphVisual, its memory will be deallocated when v goes out of scope.
    return 0;
}

