using namespace ocs2;
using namespace mobile_manipulator;

// Pinocchio interface for robot kinematics/dynamics
std::unique_ptr<PinocchioInterface> pInterface;
// Geometry interface for self-collision checking
std::shared_ptr<PinocchioGeometryInterface> gInterface;
// Visualization interface for geometry data
std::unique_ptr<GeometryInterfaceVisualization> vInterface;
// Stores the last received joint state message
sensor_msgs::JointState lastMsg;
// Publisher for visualization messages
std::unique_ptr<ros::Publisher> pub;

// Callback function for joint state updates
void jointStateCallback(sensor_msgs::JointStateConstPtr msg) 
{
    // Skip if position hasn't changed
    if (lastMsg.position == msg->position) 
    {
        return;
    }

    // Update stored position
    lastMsg.position = msg->position;

    // Construct full configuration vector (9 DOF: 3 base + 6 arm)
    Eigen::VectorXd q(9);
    q(0) = q(1) = q(2) = 0.0;
    for(size_t i = 3; i < 9; ++i)
    {
        q(i) = lastMsg.position[i - 3];
    }

    // Publish distance information
    vInterface->publishDistances(q);
}

int main(int argc, char** argv) 
{
    // Initialize ROS node
    ros::init(argc, argv, "distance_visualization");
    ros::NodeHandle nodeHandle;

    // Get ROS parameters
    std::string urdfPath, taskFile;
    nodeHandle.getParam("/taskFile", taskFile);
    nodeHandle.getParam("/urdfFile", urdfPath);

    // Read the task file using property tree
    boost::property_tree::ptree pt;
    boost::property_tree::read_info(taskFile, pt);

    // Load manipulator type from task file
    ManipulatorModelType modelType = mobile_manipulator::loadManipulatorType(
        taskFile, "model_information.manipulatorModelType"
    );

    // Load list of joints to remove (make fixed)
    std::vector<std::string> removeJointNames;
    loadData::loadStdVector<std::string>(
        taskFile, "model_information.removeJoints", removeJointNames, true
    );

    // Load base frame name
    std::string baseFrame;
    loadData::loadPtreeValue<std::string>(
        pt, baseFrame, "model_information.baseFrame", false
    );

    // Create Pinocchio interface
    pInterface.reset(new PinocchioInterface(
        ::ocs2::mobile_manipulator::createPinocchioInterface(urdfPath, modelType)
    ));

    // Print model information to stderr
    std::cerr << "\n #### Model Information:";
    std::cerr << "\n #### =============================================================================\n";
    std::cerr << "\n #### model_information.manipulatorModelType: " << static_cast<int>(modelType);
    std::cerr << "\n #### model_information.removeJoints: ";
    for(const auto& name : removeJointNames) 
    {
        std::cerr << "\"" << name << "\" ";
    }
    std::cerr << "\n #### model_information.baseFrame: \"" << baseFrame << "\"";

    // Load collision object pairs
    std::vector<std::pair<size_t, size_t>> selfCollisionObjectPairs;
    std::vector<std::pair<std::string, std::string>> selfCollisionLinkPairs;
    loadData::loadStdVectorOfPair(
        taskFile, "selfCollision.collisionObjectPairs", selfCollisionObjectPairs
    );
    loadData::loadStdVectorOfPair(
        taskFile, "selfCollision.collisionLinkPairs", selfCollisionLinkPairs
    );

    // Print loaded collision object pairs
    for(const auto& element : selfCollisionObjectPairs) 
    {
        std::cerr << "[" << element.first << ", " << element.second << "]; ";
    }
    std::cerr << std::endl;

