    // Test lock functionality for any lock type
    template <typename TLock>
    void TestLock()
    {
        TLock lock;
        UNIT_ASSERT(!lock.IsLocked());
        lock.Acquire();
        UNIT_ASSERT(lock.IsLocked());
        lock.Release();
        UNIT_ASSERT(!lock.IsLocked());
        UNIT_ASSERT(lock.TryAcquire());
        UNIT_ASSERT(lock.IsLocked());
        UNIT_ASSERT(!lock.TryAcquire());
        UNIT_ASSERT(lock.IsLocked());
        lock.Release();
        UNIT_ASSERT(!lock.IsLocked());
        // Lockable requirements
        lock.lock();
        UNIT_ASSERT(lock.IsLocked());
        UNIT_ASSERT(!lock.try_lock());
        lock.unlock();
        UNIT_ASSERT(!lock.IsLocked());
    }

