    // Save animation to writer based on type
    void SaveAnimation(Writer &writer, const Graphics::RectangularAnimationProvider &object)
    {
        auto obj = &object;
        if(dynamic_cast<const Graphics::Bitmap*>(obj))
        {
            Image::SaveThis(writer, dynamic_cast<const Graphics::Bitmap&>(object));
        }
        else if(dynamic_cast<const Graphics::BitmapAnimationProvider*>(obj))
        {
            Animation::SaveThis(writer, dynamic_cast<const Graphics::BitmapAnimationProvider&>(object));
        }
        else if(dynamic_cast<const Graphics::ILineProvider*>(obj))
        {
            Line::SaveThis(writer, dynamic_cast<const Graphics::ILineProvider&>(object));
        }
        else if(dynamic_cast<const Graphics::IRectangleProvider*>(obj))
        {
            Rectangle::SaveThis(writer, dynamic_cast<const Graphics::IRectangleProvider&>(object));
        }
        else if(dynamic_cast<const Graphics::IMaskedObjectProvider*>(obj))
        {
            MaskedObject::SaveThis(writer, dynamic_cast<const Graphics::IMaskedObjectProvider&>(object));
        }
        else if(dynamic_cast<const Graphics::ITintedObjectProvider*>(obj))
        {
            TintedObject::SaveThis(writer, dynamic_cast<const Graphics::ITintedObjectProvider&>(object));
        }
        else if(dynamic_cast<const Graphics::IScalableObjectProvider*>(obj))
        {
            ScalableObject::SaveThis(writer, dynamic_cast<const Graphics::IScalableObjectProvider&>(object));
        }
        else if(dynamic_cast<const Graphics::IStackedObjectProvider*>(obj))
        {
            StackedObject::SaveThis(writer, dynamic_cast<const Graphics::IStackedObjectProvider&>(object));
        }
        else
        {
            throw std::runtime_error("Cannot save animation: Unsupported animation type.");
        }
    }

    // Save animation for pointer (handles null case)
    void SaveAnimation(Writer &writer, const Graphics::RectangularAnimationProvider *object)
    {
        if(!object)
        {
            Null::SaveThis(writer);
        }
        else
        {
            SaveAnimation(writer, *object);
        }
    }

}

#include "llvm/Support/circular_raw_ostream.h"
#include <algorithm>

using namespace llvm;

// Implements the write operation for circular buffer
void circular_raw_ostream::write_impl(const char *Ptr, size_t Size) 
{
  // If no buffer is configured, delegate to underlying stream
  if (BufferSize == 0) 
  {
    TheStream->write(Ptr, Size);
    return;
  }

  // Write into the buffer, wrapping if necessary.
  while (Size != 0) 
  {
    unsigned Bytes = 
      std::min(unsigned(Size), unsigned(BufferSize - (Cur - BufferArray)));

    memcpy(Cur, Ptr, Bytes);
    Size -= Bytes;
    Cur += Bytes;

    // Check if we've reached the end of the buffer
    if (Cur == BufferArray + BufferSize) 
    {
      // Reset the output pointer to the start of the buffer.
      Cur = BufferArray;
      Filled = true;
    }
  }
}

// Flushes the buffer with a banner prefix
void circular_raw_ostream::flushBufferWithBanner() 
{
  if (BufferSize != 0) 
  {
    // Write out the banner first
    TheStream->write(Banner, std::strlen(Banner));
    flushBuffer();
  }
}

#include "hook_wrapper.h"
#include <format>
#include <string>
#include "instruction_length.h"
#include "memory.h"

#pragma comment(lib, "Ws2_32.lib")
#pragma comment(lib, "psapi.lib")

// Writes a relative jump instruction at the given address
static void write_relative_jump(int jump_instr_addr, int relative_jump_size)
{
    *reinterpret_cast<uint8_t*>(jump_instr_addr) = 0xE9;
    *reinterpret_cast<int*>(jump_instr_addr + 1) = relative_jump_size;

    DWORD old_protect;
    VirtualProtect((LPVOID)jump_instr_addr, 5, PAGE_EXECUTE_READWRITE, &old_protect);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<PVOID>(jump_instr_addr), 5);
}

// Fixes relative addresses in call/jump opcodes after moving them into the trampoline buffer
void hook::patch_trampoline_relative_jumps()
{
    int i = 0;
    unsigned char* opcodes = reinterpret_cast<unsigned char*>(trampoline);

    while (i < orig_byte_count)
    {
        if (opcodes[i] == 0xe8 || opcodes[i] == 0xe9)
        {
            if (i + 5 > orig_byte_count)
                fatal_error();  // Misaligned instruction detected

            int32_t* relative_address = reinterpret_cast<int32_t*>(&opcodes[i + 1]);
            *relative_address += patch_address - trampoline;  // Adjust by delta
        }

        i += Zeal::InstructionLength(&opcodes[i]);  // Advance by full instruction length
    }
}

// Reports a fatal error during hook patching and terminates execution
void hook::fatal_error()
{
    std::string message = "Fatal Zeal hook wrapper patching: " + std::format("0x{:x}", patch_address);
    int result_id = MessageBoxA(NULL, message.c_str(), "Internal Zeal error", MB_OK | MB_TOPMOST);
    throw std::bad_alloc();  // Triggers program termination
}

void hook::detour()
{
    // Determine required byte count for original instructions (minimum 5 for jump)
    orig_byte_count = Zeal::InstructionLength((unsigned char*)patch_address);
    while (orig_byte_count < 5)  // Need at least 5 bytes for a JMP instruction
        orig_byte_count += Zeal::InstructionLength((unsigned char*)(patch_address + orig_byte_count));

    // Save original bytes for later restoration
    if (orig_byte_count > sizeof(original_bytes))
    {
        fatal_error();  // Buffer overflow — crash the program
        return;
    }

    memcpy(original_bytes, (void*)patch_address, orig_byte_count);

    // Allocate executable memory for trampoline
    DWORD dummy_protect;
    int trampoline_size = orig_byte_count + 5;
    VirtualProtect(trampoline_bytes, trampoline_size, PAGE_EXECUTE_READWRITE, &dummy_protect);

    // Copy original bytes to trampoline and fix relative addresses
    memcpy(trampoline_bytes, original_bytes, orig_byte_count);
    patch_trampoline_relative_jumps();

    // Append jump back to original function after moved instructions
    int jump_instr_addr = trampoline + orig_byte_count;
    int relative_jump_size = (patch_address + orig_byte_count) - (jump_instr_addr + 5);
    *reinterpret_cast<uint8_t*>(jump_instr_addr) = 0xE9;
    *reinterpret_cast<int*>(jump_instr_addr + 1) = relative_jump_size;

    FlushInstructionCache(GetCurrentProcess(), trampoline_bytes, trampoline_size);

    // Patch original location with jump to detour
    DWORD old_protect;
    VirtualProtect((LPVOID)patch_address, orig_byte_count, PAGE_EXECUTE_READWRITE, &old_protect);

    int relative_jump_to_callee = replacement_callee_addr - (patch_address + 5);
    *reinterpret_cast<uint8_t*>(patch_address) = 0xE9;
    *reinterpret_cast<int*>(patch_address + 1) = relative_jump_to_callee;

    // Fill remaining space with NOPs if more than 5 bytes were overwritten
    if (orig_byte_count > 5)
        mem::set(patch_address + 5, 0x90, orig_byte_count - 5);

    VirtualProtect((LPVOID)patch_address, orig_byte_count, old_protect, &old_protect);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<PVOID>(patch_address), orig_byte_count);
}

void hook::replace_call()
{
    DWORD old;
    VirtualProtect((LPVOID)patch_address, 0x5, PAGE_EXECUTE_READWRITE, &old);

    if (*(BYTE*)patch_address != 0xE9 && *(BYTE*)patch_address != 0xE8)
        fatal_error();  // Unexpected opcode — crash the program

    // Create trampoline to preserve original target
    int orig_jmp_dest_addr = mem::instruction_to_absolute_address(patch_address);
    int trampoline_to_orig_jmp_dest = orig_jmp_dest_addr - (trampoline + 5);
    write_relative_jump(trampoline, trampoline_to_orig_jmp_dest);

    // Save original bytes and update jump target
    orig_byte_count = 5;
    memcpy(original_bytes, (LPVOID)patch_address, orig_byte_count);

    int relative_jump_size = replacement_callee_addr - (patch_address + 5);
    *(int*)(patch_address + 1) = relative_jump_size;

    VirtualProtect((LPVOID)patch_address, 0x5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), (LPVOID)patch_address, 0x5);
}

void hook::replace_vtable()
{
    // Create trampoline to preserve original vtable entry target
    int orig_jmp_addr = *reinterpret_cast<int*>(patch_address);
    int relative_jump_size = orig_jmp_addr - (trampoline + 5);
    write_relative_jump(trampoline, relative_jump_size);

    // Save original bytes (4 bytes for pointer on 32-bit, but assumed here as 4)
    orig_byte_count = 4;
    memcpy(original_bytes, &patch_address, orig_byte_count);

    // Replace vtable entry with new function address
    mem::write<int>(patch_address, replacement_callee_addr);
}

// Destructor: restores original bytes at patched location
hook::~hook()
{
    mem::copy(patch_address, original_bytes, orig_byte_count);
}

