namespace {

/// NVPTXAssignValidGlobalNames
class NVPTXAssignValidGlobalNames : public ModulePass {
public:
  static char ID;

  NVPTXAssignValidGlobalNames() : ModulePass(ID) {}

  bool runOnModule(Module &M) override;

  /// Clean up the name to remove symbols invalid in PTX.
  std::string cleanUpName(StringRef Name);
};

}

char NVPTXAssignValidGlobalNames::ID = 0;

namespace llvm {
void initializeNVPTXAssignValidGlobalNamesPass(PassRegistry &);
}

INITIALIZE_PASS(NVPTXAssignValidGlobalNames, "nvptx-assign-valid-global-names",
                "Assign valid PTX names to globals", false, false)

bool NVPTXAssignValidGlobalNames::runOnModule(Module &M) {
  for (GlobalVariable &GV : M.globals()) {
    // We are only allowed to rename local symbols.
    if (GV.hasLocalLinkage()) {
      // setName doesn't do extra work if the name does not change.
      // Note: this does not create collisions - if setName is asked to set the
      // name to something that already exists, it adds a proper postfix to
      // avoid collisions.
      GV.setName(cleanUpName(GV.getName()));
    }
  }

  // Do the same for local functions.
  for (Function &F : M.functions())
    if (F.hasLocalLinkage())
      F.setName(cleanUpName(F.getName()));

  return true;
}

std::string NVPTXAssignValidGlobalNames::cleanUpName(StringRef Name) {
  std::string ValidName;
  raw_string_ostream ValidNameStream(ValidName);

  for (char C : Name) {
    if (C == '.' || C == '@' || C == '<' || C == '>') {
      ValidNameStream << "_$_";
    } else {
      ValidNameStream << C;
    }
  }

  return ValidNameStream.str();
}

ModulePass *llvm::createNVPTXAssignValidGlobalNamesPass() {
  return new NVPTXAssignValidGlobalNames();
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Maps a character from the set {'A'-'Z', '0'-'9'} to an integer index [0, 35].
inline int char_to_int(char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    }
    return c - '0' + 26;
}

// Finds a common subsequence by greedily matching characters from string 'a' in string 'b'.
// This function has a time complexity of O(|a| + |b|).
std::string solve_greedy(const std::string& a, const std::string& b) {
    // Precompute positions of each character in string 'b' for fast lookups.
    // pos[i] stores a sorted list of indices where the i-th character of the alphabet appears in 'b'.
    std::vector<std::vector<int>> pos(36);
    for (int i = 0; i < b.length(); ++i) {
        pos[char_to_int(b[i])].push_back(i);
    }

    std::string res;
    // Reserve memory to avoid reallocations. A safe upper bound for LCS length is min(|a|, |b|).
    res.reserve(std::min(a.length(), b.length()));

    int last_pos_b = -1;
    // 'p' stores pointers for each character's position vector to avoid re-scanning from the beginning.
    std::vector<int> p(36, 0);

    for (char c : a) {
        int char_idx = char_to_int(c);

        // Find the next occurrence of 'c' in 'b' after 'last_pos_b' by advancing the pointer p[char_idx].
        while (p[char_idx] < pos[char_idx].size() && pos[char_idx][p[char_idx]] <= last_pos_b) {
            p[char_idx]++;
        }

        // If a valid position is found, append the character to the result and update the last position.
        if (p[char_idx] < pos[char_idx].size()) {
            res.push_back(c);
            last_pos_b = pos[char_idx][p[char_idx]];
            p[char_idx]++; // Move pointer for the next search of this character.
        }
    }

    return res;
}

int main() {
    // Fast I/O for large inputs.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::string s1, s2;
    std::cin >> s1 >> s2;

    // Run the greedy algorithm in both directions to get two candidate subsequences.
    std::string res1 = solve_greedy(s1, s2);
    std::string res2 = solve_greedy(s2, s1);

    // Output the longer of the two results.
    if (res1.length() >= res2.length()) {
        std::cout << res1 << std::endl;
    } else {
        std::cout << res2 << std::endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

class Solution {
public:
    // brute force solution using linear search
    bool searchBrute(vector<int>& nums, int target) {
        // brute force solution: binary search
        // edge cases
        if(nums[0] == target || nums[nums.size()-1] == target) {
            return true;
        }
        for(int i = 1; i < nums.size()-1; i++) {
            if(nums[i] == target) {
                return true;
            }
        }
        return false;
        // TC: O(n) : linear search checks every element => O(n) for array containing n elements
        // SC: O(1) : No extra space used
    }

    // optimal solution using binary search
    bool searchOpt(vector<int>& nums, int target) {
        // optimal solution: binary search because at either side of pivot element, the search space is sorted
        // if first or the last element is the target
        if(nums[0] == target || nums[nums.size()-1] == target) {
            return true;
        }

        int low = 0;
        int high = nums.size()-1;

        while(low <= high) {
            int mid = low + (high - low)/2;

            // checking the conditions
            // case 1: nums[mid] is the target
            if(nums[mid] == target) {
                return true;
            }

            // due to rotation and repetition, there is a 
            // chance that elements at both ends are equal to mid
            if((nums[mid] == nums[low]) && (nums[high] == nums[mid])) {
                low++;
                high--;
            }
            else if(nums[low] <= nums[mid]) {
                // first half is sorted => implement binary search
                if((nums[low] <= target) && (target < nums[mid])) {
                    // target is present in first half
                    high = mid - 1;
                }
                else {
                    // target is not present in first half
                    low = mid + 1;
                }
            }
            else {
                // second half is sorted => apply binary search
                if((nums[mid] < target) && (target <= nums[high])) {
                    // target is in 2nd half
                    low = mid + 1;
                }
                else {
                    // target is not in 2nd half
                    high = mid - 1;
                }
            }
        } 

        return false;
        /*
            TC: O(log n): binary search halves the search space at each iteration hence log2(n) number of operations
            SC: O(1): no extra space has been used
        */
    }
};

int main() {
    vector<int> nums = {2,5,6,0,0,1,2};
    int target1 = 3;
    int target2 = 0;

    Solution s;

    bool ans = s.searchOpt(nums, target1);
    cout << ans << endl; // expected 0 => false

    bool ans2 = s.searchOpt(nums, target2);
    cout << ans2 << endl; // expected 1 => True

    return 0;
}

#include "server.hpp"
#include <boost/bind.hpp>
#include <signal.h>

namespace http {
namespace server {

// Server constructor
server::server(const std::string& address, const std::string& port,
    const std::string& doc_root)
  : io_context_(),
    signals_(io_context_),
    acceptor_(io_context_),
    connection_manager_(),
    new_connection_(),
    request_handler_(doc_root)
{
  // Register to handle the signals that indicate when the server should exit.
  // It is safe to register for the same signal multiple times in a program,
  // provided all registration for the specified signal is made through Asio.
  signals_.add(SIGINT);
  signals_.add(SIGTERM);
#if defined(SIGQUIT)
  signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  signals_.async_wait(boost::bind(&server::handle_stop, this));

  // Open the acceptor with the option to reuse the address (i.e. SO_REUSEADDR).
  asio::ip::tcp::resolver resolver(io_context_);
  asio::ip::tcp::endpoint endpoint =
    *resolver.resolve(address, port).begin();

  acceptor_.open(endpoint.protocol());
  acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  acceptor_.bind(endpoint);
  acceptor_.listen();

  start_accept();
}

// Run the server's main event loop
void server::run()
{
  // The io_context::run() call will block until all asynchronous operations
  // have finished. While the server is running, there is always at least one
  // asynchronous operation outstanding: the asynchronous accept call waiting
  // for new incoming connections.
  io_context_.run();
}

// Start accepting new connections
void server::start_accept()
{
  new_connection_.reset(new connection(io_context_,
        connection_manager_, request_handler_));
  acceptor_.async_accept(new_connection_->socket(),
      boost::bind(&server::handle_accept, this,
        asio::placeholders::error));
}

// Handle completion of an accept operation
void server::handle_accept(const asio::error_code& e)
{
  // Check whether the server was stopped by a signal before this completion
  // handler had a chance to run.
  if (!acceptor_.is_open())
  {
    return;
  }

  if (!e)
  {
    connection_manager_.start(new_connection_);
  }

  start_accept();
}

// Handle server stop signals
void server::handle_stop()
{
  // The server is stopped by cancelling all outstanding asynchronous
  // operations. Once all operations have finished the io_context::run() call
  // will exit.
  acceptor_.close();
  connection_manager_.stop_all();
}

} // namespace server
} // namespace http

