class Solution {
public:
    // Finds the first bad version
    int firstBadVersion(int n)
    {
        int kk;
        for(int i=n;i>0;i--)
        {
            if(isBadVersion(i))
            {
                kk=i;
            }
            else break;
        }
        // Return the first bad version found
        return kk;

    }
};

