namespace Karm::Scene {

// Represents an opacity modifier node
export struct Opacity : Proxy {
    f64 _opacity;

    // Constructor initializes the opacity and base node
    Opacity(Rc<Node> node, f64 opacity)
        : Proxy(node), _opacity(opacity) {}

    // Paints the node with applied opacity
    void paint(Gfx::Canvas& g, Math::Rectf r, PaintOptions o) override {
        g.push();
        g.opacity(_opacity);
        _node->paint(g, r, o);
        g.pop();
    }

    // Outputs a representation of this opacity node
    void repr(Io::Emit& e) const override {
        e("(opacity opacity:{} content:{})", _opacity, _node);
    }
};

