    A obj; // Calls A()

    // Array of objects - calls constructor 3 times
    A arr[3]; // Calls A() three times

    // Dynamic array allocation - calls constructor 3 times
    A* dynamicArr = new A[3]; // Calls A() three times

    // Deallocate dynamic array - calls destructor 3 times
    delete[] dynamicArr; // Calls ~A() three times

    // Note: delete and delete[] properly call destructors for dynamically allocated objects

