class Solution {
public:
    // Moves all zeroes to the end of the array
    void moveZeroes(vector<int>& nums)
    {
        int n = nums.size();
        for(int i = 0; i < n - 1; ++i)
        {
            for(int j = 0; j < n - 1; ++j)
            {
                if(nums[j] == 0)
                {
                    swap(nums[j], nums[j + 1]);
                }
            }
        }
    }
};

#include <iostream>
#include <climits>
using namespace std;

/**
 * Definition for a binary tree node.
*/
struct TreeNode {
     int val;
     TreeNode *left;
     TreeNode *right;
     TreeNode() : val(0), left(nullptr), right(nullptr) {}
     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    // Helper function to validate BST with given min and max bounds
    bool isValidBSTHelper(TreeNode* root, long minVal, long maxVal) {
        if (!root) return true; // An empty tree is a valid BST

        // Check if the current node's value violates the min/max constraints
        if (root->val <= minVal || root->val >= maxVal) {
            return false;
        }

        // Recursively check the left and right subtrees with updated constraints
        return isValidBSTHelper(root->left, minVal, root->val) &&
               isValidBSTHelper(root->right, root->val, maxVal);
    }

    // Main function to check if a binary tree is a valid BST
    bool isValidBST(TreeNode* root) {
        return isValidBSTHelper(root, LONG_MIN, LONG_MAX);
    }
};

