#include <vector>
#include <string>

// Class to generate valid parenthesis combinations
class Solution {
public:
    // Recursive helper function
    void recursiveF(int op, int cl, std::string s, std::vector<std::string> &ans)
    {
        // Base case: when no closing brackets remain
        if (cl == 0) {
            ans.push_back(s);
        }
        // Add closing bracket if available
        if (cl > op) {
            recursiveF(op, cl - 1, s + ')', ans);
        }
        // Add opening bracket if available
        if (op > 0) {
            recursiveF(op - 1, cl, s + '(', ans);
        }
    }

    // Main function to generate all valid parenthesis combinations
    std::vector<std::string> generateParenthesis(int n)
    {
        int op = n, cl = n;
        std::string s = "";
        std::vector<std::string> ans;
        recursiveF(op, cl, s, ans);
        return ans;
    }
};

