#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

// Class definition for printer
class printer
{
public:
  // Constructor initializes timer and count
  printer(asio::io_context& io)
    : timer_(io, asio::chrono::seconds(1)),
      count_(0)
  {
    // Start the first async wait
    timer_.async_wait(boost::bind(&printer::print, this));
  }

  // Destructor prints final count
  ~printer()
  {
    std::cout << "Final count is " << count_ << std::endl;
  }

  // Print method with recursive async calls
  void print()
  {
    if (count_ < 5)
    {
      std::cout << count_ << std::endl;
      ++count_;
      timer_.expires_at(timer_.expiry() + asio::chrono::seconds(1));
      timer_.async_wait(boost::bind(&printer::print, this));
    }
  }

private:
  asio::steady_timer timer_;
  int count_;
};

// Main function
int main()
{
  asio::io_context io;
  printer p(io);
  io.run();
  return 0;
}

