#include <vector>
#include <algorithm>

class Solution {
public:
    // Calculates the maximum profit from stock transactions
    int maxProfit(std::vector<int>& prices) 
    {
        int n = prices.size();
        int maxProfit = 0;
        int lowestTillday = prices[0];

        for(int i = 0; i < n; ++i)
        {
            // Update the minimum price seen so far
            lowestTillday = std::min(prices[i], lowestTillday);

            // Calculate profit if sold today
            int ProfitSellToday = (prices[i] - lowestTillday);

            // Update maximum profit
            maxProfit = std::max(maxProfit, ProfitSellToday);
        }

        return maxProfit;
    }
};

