#include <vector>
#include <unordered_set>
#include <climits>
#include <string>

class Solution {
public:
    // Function to count palindromic subsequences
    int countPalindromicSubsequence(std::string inputString)
    {
        // Arrays to store the minimum and maximum occurrences of each character
        std::vector<int> minExist(26, INT_MAX);
        std::vector<int> maxExist(26, INT_MIN);

        // Populate minExist and maxExist arrays
        for(int i = 0; i < inputString.size(); i++)
        {
            int charIndex = inputString[i] - 'a';
            minExist[charIndex] = std::min(minExist[charIndex], i);
            maxExist[charIndex] = std::max(maxExist[charIndex], i);
        }

        // Variable to store the final count
        int uniqueCount = 0;

        // Iterate over each character in the alphabet
        for (int charIndex = 0; charIndex < 26; charIndex++)
        {
            // Skip characters that didn't appear
            if (minExist[charIndex] == INT_MAX || maxExist[charIndex] == INT_MIN)
            {
                continue;
            }

            // Set to store unique characters between min and max positions
            std::unordered_set<char> uniqueCharsBetween;

            // Collect unique middle characters
            for (int j = minExist[charIndex] + 1; j < maxExist[charIndex]; j++)
            {
                uniqueCharsBetween.insert(inputString[j]);
            }

            // Add count of distinct middle characters
            uniqueCount += uniqueCharsBetween.size();
        }

        // Return total count
        return uniqueCount;
    }
};

