namespace examples {

// Parses a TXT record key=value pair from string
static bool parse_txt_record(rav::dnssd::TxtRecord& txt_record, const std::string& string_value) {
    if (string_value.empty())
        return false;

    const size_t pos = string_value.find('=');
    if (pos != std::string::npos)
        txt_record[string_value.substr(0, pos)] = string_value.substr(pos + 1);
    else
        txt_record[string_value.substr(0, pos)] = "";

    return true;
}

}  // namespace examples

int main(int const argc, char* argv[]) {
    rav::set_log_level_from_env();
    rav::do_system_checks();

    std::vector<std::string> args;
    for (int i = 1; i < argc; i++) {
        args.emplace_back(argv[i]);
    }

    // Check minimum required arguments
    if (args.size() < 2) {
        std::cout << "Error: expected at least an argument which specifies the service type and an argument which "
                     "specifies the port number (example: _test._tcp 1234 key1=value1 key2=value2)"
                  << std::endl;
        return -1;
    }

    // Parse port number
    int port_number = 0;
    try {
        port_number = std::stoi(args[1]);
    } catch (const std::exception& e) {
        std::cout << "Invalid port number: " << e.what() << std::endl;
        return -1;
    }

    // Parse remaining arguments as TXT record entries
    rav::dnssd::TxtRecord txt_record;
    for (auto it = args.begin() + 2; it != args.end(); ++it) {
        examples::parse_txt_record(txt_record, *it);
    }

    boost::asio::io_context io_context;
    const auto advertiser = rav::dnssd::Advertiser::create(io_context);

    if (advertiser == nullptr) {
        RAV_LOG_ERROR("Error: no dnssd advertiser implementation available for this platform");
        return -1;
    }

    advertiser->on_error = [](const auto& error_message) {
        RAV_LOG_ERROR("Advertiser error: {}", error_message);
    };

    advertiser->on_name_conflict = [](const auto* reg_type, const auto* name) {
        RAV_LOG_CRITICAL("Name conflict: {} {}", reg_type, name);
    };

    const auto service_id =
        advertiser->register_service(args[0], "Test service", nullptr, static_cast<uint16_t>(port_number), txt_record, true, true);

    std::thread io_context_thread([&io_context] {
        io_context.run();
    });

    RAV_LOG_INFO("Enter key=value to update the TXT record, or q to exit...");

    std::string cmd;
    while (true) {
        std::getline(std::cin, cmd);

        if (cmd == "q" || cmd == "Q") {
            break;
        }

        if (cmd == "r" || cmd == "R") {
            advertiser->unregister_service(service_id);
            continue;
        }

        try {
            if (examples::parse_txt_record(txt_record, cmd)) {
                // Schedule updates on the io_context thread since advertiser is not thread-safe
                boost::asio::post(io_context, [=, &advertiser] {
                    advertiser->update_txt_record(service_id, txt_record);
                    RAV_LOG_INFO("Updated txt record");
                });
            }
        } catch (const std::exception& e) {
            RAV_LOG_ERROR("Failed to update txt record: {}", e.what());
        }
    }

    io_context.stop();
    io_context_thread.join();

    std::cout << "Exit" << std::endl;
    return 0;
}

