// Main function demonstrating multimap usage
int main()
{
    // Multimap of strings to integers (stores multiple values for same key)
    multimap<string, int> m;

    // Insert key-value pairs using insert
    m.insert(make_pair("headphones", 100));
    m.insert(make_pair("mouse", 200));
    m.insert(make_pair("keyboard", 300));
    m.insert(make_pair("monitor", 400));
    m.insert(make_pair("monitor", 500));
    m.insert(make_pair("monitor", 600));
    m.insert(make_pair("monitor", 700));

    // Insert key-value pairs using emplace
    m.emplace("tablet", 400);
    m.emplace("tablet", 500);
    m.emplace("tablet", 600);

    // Iterate and print all elements
    for(auto p: m)
    {
        cout<<p.first<<" "<<p.second<<endl;
    }

    cout<<endl;

    // Print size, max_size, and emptiness
    cout<<m.size()<<endl;
    cout<<m.max_size()<<endl;
