// Include custom headers for Bezier curve processing and plotting
#include <sm/bezcoord>
#include <sm/bezcurvepath>
#include <mplot/ReadCurves.h>

int main()
{
    int rtn = -1;

    try 
    {
        // Read curves from SVG file
        mplot::ReadCurves r("../../tests/trial.svg");

        // Get cortical path as Bezier curve
        sm::bezcurvepath<float> bcp = r.getCorticalPath();

        // Compute points along the curve with step size 0.01
        bcp.computePoints (0.01f);

        // Retrieve computed points
        std::vector<sm::bezcoord<float>> pts = bcp.getPoints();

        // Output number of points retrieved
        std::cout << "Got " << pts.size() << " points with getPoints()" << std::endl;

        // Iterate through points and print each one
        auto i = pts.begin();
        while (i != pts.end()) 
        {
            std::cout << *i << std::endl;
            ++i;
        }

        // Set precision for detailed output
        std::cout.precision(12);

        // Print specific point at index 23
        std::cout << "pts[23] =  " << pts[23].t()
                  << " " << pts[23].x()
                  << " " << pts[23].y()
                  << std::endl;

        // Check if point values match expected values within tolerance
        if ((std::abs(pts[23].t() - 0.329311) < 0.00001f)
            && (std::abs(pts[23].x() - 0.849296) < 0.00001f)
            && (std::abs(pts[23].y()- 1.00673) < 0.00001f)) 
        {
            std::cout << "Matches expectation; rtn IS 0" << std::endl;
            rtn = 0;
        } 
        else 
        {
            std::cout << "rtn not 0" << std::endl;
        }
    } 
    catch (const std::exception& e) 
    {
        std::cerr << "Caught exception reading trial.svg: " << e.what() << std::endl;
        rtn = -1;
    }

    return rtn;
}

