    magic_enum::containers::set color_set {Color::RED, Color::GREEN, Color::BLUE};

    // Check initial state
    std::cout << color_set.empty() << std::endl; // false
    std::cout << color_set.size() << std::endl; // 3

    // Clear the set
    color_set.clear();
    std::cout << color_set.empty() << std::endl; // true
