class Solution {
public:
    // Finds the duplicate number in the array
    int findDuplicate(vector<int>& nums)
    {
        int dup = 0;
        int n = nums.size();

        // Sort the array to bring duplicates together
        sort(nums.begin(), nums.end());

        // Linear scan to find adjacent duplicates
        for(int i = 0; i < n - 1; i++)
        {
            if(nums[i] == nums[i + 1])
            {
                dup = nums[i];
            }
        }

        // Return the duplicate value found
        return dup;
    }
};

