            SNew(SButton)
            .IsEnabled(this, &FDMXLibraryRecorderAddAllPatchesButtonCustomization::GetAddAllEnabled)
            .OnClicked(this, &FDMXLibraryRecorderAddAllPatchesButtonCustomization::HandleOnClicked)
