#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>

using namespace std;

// Grid dimensions
const int N = 20;
const int M = 20;

// Logical dimensions for maze generation (since we use 2x2 blocks implicitly with walls)
const int H = 10;
const int W = 10;

// Global map and visited array
vector<string> grid_map(N, string(M, '0'));
vector<vector<bool>> visited(H, vector<bool>(W, false));

// Random number generator with fixed seed for reproducibility
mt19937 rng(1337);

// Depth-First Search to generate a maze (Spanning Tree)
void dfs(int r, int c)
{
    visited[r][c] = true;

    // Mark the logical cell position in the actual grid
    // Logical cell (r, c) corresponds to grid cell (2*r, 2*c)
    grid_map[2 * r][2 * c] = '1';

    // Possible directions: Up, Down, Left, Right
    vector<pair<int, int>> dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Shuffle directions to create a random maze
    shuffle(dirs.begin(), dirs.end(), rng);

    for (auto d : dirs)
    {
        int nr = r + d.first;
        int nc = c + d.second;

        // Check bounds and if visited
        if (nr >= 0 && nr < H && nc >= 0 && nc < W && !visited[nr][nc])
        {
            // Remove the wall between the current cell and the neighbor
            // The wall is located at the intermediate coordinate
            grid_map[2 * r + d.first][2 * c + d.second] = '1';

            // Recurse
            dfs(nr, nc);
        }
    }
}

int main()
{
    // Start DFS from the top-left corner (0, 0) of the logical grid
    dfs(0, 0);

    // Print the dimensions
    cout << N << " " << M << endl;

    // Print the grid
    for (int i = 0; i < N; i++)
    {
        cout << grid_map[i] << endl;
    }

    return 0;
}

#include <TranslatorRoster.h>
#include <TranslatorFormats.h>
#include <DataIO.h>
#include <File.h>
#include <Entry.h>
#include <Message.h>
#include <iostream>

// Main function to translate Markdown to plain text
int main()
{
    // Open the Markdown file for reading
    BFile markdownFile("./sample.md", B_READ_ONLY);
    if (markdownFile.InitCheck() != B_OK)
    {
        std::cerr << "Failed to open sample.md\n";
        return 1;
    }

    // Create the text file for writing (overwrite if exists)
    BFile txtFile("./sample.txt", B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
    if (txtFile.InitCheck() != B_OK)
    {
        std::cerr << "Failed to create sample.txt\n";
        return 1;
    }

    // Get the default translator roster
    BTranslatorRoster* roster = BTranslatorRoster::Default();
    if (!roster)
    {
        std::cerr << "Failed to get translator roster\n";
        return 1;
    }

    // Prepare identification info
    BMessage ext;
    ext.AddString("name", "./sample.md");
    ext.AddString("BEOS:TYPE", "text/markdown");
    translator_info tinfo;
    status_t result = roster->Identify(&markdownFile, &ext, &tinfo);
    if (result == B_OK)
    {
        const char* name = nullptr;
        const char* info = nullptr;
        int32 version = 0;

        // Get translator details
        if (roster->GetTranslatorInfo(tinfo.translator, &name, &info, &version) == B_OK)
        {
            std::cout << "Translator selected: " << name << " (version " << version << ")\n";
            std::cout << "Info: " << info << "\n";
        }
        else
        {
            std::cerr << "Error: GetTranslatorInfo() failed\n";
        }
    }
    else
    {
        std::cerr << "Identify failed: " << result << "\n";
        return 1;
    }

    // Reset file pointer to the beginning before translation
    markdownFile.Seek(0, SEEK_SET);

    // Translate the Markdown file to plain text
    status_t status = roster->Translate(&markdownFile, nullptr, &ext, &txtFile, B_TRANSLATOR_TEXT);
    if (status != B_OK)
    {
        std::cerr << "Translation failed: " << status << "\n";
        return 1;
    }
    else
    {
        std::cout << "Saved txt file: sample.txt\n";
    }

    return 0;
}

