#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <string>
#include <iostream>

// Main function entry point
int main()
{
    std::cout << "=== coroutine ===" << std::endl;

    // Create Lua state and task list
    sol::state lua;
    std::vector<sol::coroutine> tasks;

    // Open required Lua libraries
    lua.open_libraries(sol::lib::base, sol::lib::coroutine);

    // Create a dedicated thread for running tasks
    sol::thread runner_thread = sol::thread::create(lua);

    // Register the start_task function
    lua.set_function("start_task",
        [&runner_thread, &tasks](
            sol::function f, sol::variadic_args va)
        {
            // Always get the current state from the runner thread
            sol::state_view runner_thread_state = runner_thread.state();

            // Add new coroutine to our task list to keep it alive
            std::size_t task_index = tasks.size();
            tasks.emplace_back(runner_thread_state, f);

            // Get reference to the newly created coroutine
            sol::coroutine& f_on_runner_thread = tasks[task_index];

            // Call coroutine with arguments transferred from calling thread
            int wait = f_on_runner_thread(va);
            std::cout << "First return: " << wait << std::endl;

            // Resume coroutine without new arguments
            f_on_runner_thread();
            std::cout << "Second run complete: " << wait << std::endl;
        });

    // Execute Lua script with task definitions
    lua.script(
        R"(
function main(x, y, z)
	-- do something
	coroutine.yield(20)
	-- do something else
	-- do ...
	print(x, y, z)
end

function main2(x, y)
	coroutine.yield(10)
	print(x, y)
end

-- Start both tasks
start_task(main, 10, 12, 8)
start_task(main2, 1, 2)
)");

    std::cout << std::endl;
    return 0;
}

