#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <memory>
#include <iostream>

struct holy {
private:
    holy() : data() {
    }
    holy(int value) : data(value) {
    }
    ~holy() {
    }

public:
    struct deleter {
        void operator()(holy* p) const {
            destroy(*p);
        }
    };

    const int data;

    static std::unique_ptr<holy, deleter> create() {
        std::cout << "creating 'holy' unique_ptr directly and "
                     "letting sol/Lua handle it"
                  << std::endl;
        return std::unique_ptr<holy, deleter>(new holy(50));
    }

    static void initialize(holy& uninitialized_memory) {
        std::cout << "initializing 'holy' userdata at "
                  << static_cast<void*>(&uninitialized_memory)
                  << std::endl;
        // receive uninitialized memory from Lua:
        // properly set it by calling a constructor
        // on it
        // "placement new"
        new (&uninitialized_memory) holy();
    }

    static void destroy(holy& memory_from_lua) {
        std::cout << "destroying 'holy' userdata at "
                  << static_cast<void*>(&memory_from_lua)
                  << std::endl;
        memory_from_lua.~holy();
    }
};

int main() {
    std::cout << "=== usertype_initializers ===" << std::endl;

    { // additional scope to make usertype destroy earlier
        sol::state lua;
        lua.open_libraries();

        lua.new_usertype<holy>("holy",
             "new",
             sol::initializers(&holy::initialize),
             "create",
             sol::factories(&holy::create),
             sol::meta_function::garbage_collect,
             sol::destructor(&holy::destroy),
             "data",
             &holy::data);

        lua.script(R"(
h1 = holy.create()
h2 = holy.new()
print('h1.data is ' .. h1.data)
print('h2.data is ' .. h2.data)
)");

        holy& h1 = lua["h1"];
        holy& h2 = lua["h2"];

        SOL_ASSERT(h1.data == 50);
        SOL_ASSERT(h2.data == 0);
    }

    std::cout << std::endl;
}

#include <algorithm>
#include "IRsend.h"

// Constants
const uint16_t kGlobalCacheMaxRepeat = 50;
const uint32_t kGlobalCacheMinUsec = 80;
const uint8_t kGlobalCacheFreqIndex = 0;
const uint8_t kGlobalCacheRptIndex = kGlobalCacheFreqIndex + 1;
const uint8_t kGlobalCacheRptStartIndex = kGlobalCacheRptIndex + 1;
const uint8_t kGlobalCacheStartIndex = kGlobalCacheRptStartIndex + 1;

#if SEND_GLOBALCACHE

/// Send a shortened GlobalCache (GC) IRdb/control tower formatted message.
/// Status: STABLE / Known working.
/// @param[in] buf Array of uint16_t containing the shortened GlobalCache data.
/// @param[in] len Nr. of entries in the buf[] array.
/// @note Global Cache format without the emitter ID or request ID.
///  Starts at the frequency (Hertz), followed by nr. of times to emit (count),
///  then the offset for repeats (where a repeat will start from),
///  then the rest of entries are the actual IR message as units of periodic
///  time.
///  e.g. sendir,1:1,1,38000,1,1,9,70,9,30,9,... -> 38000,1,1,9,70,9,30,9,...
/// @see https://irdb.globalcache.com/Home/Database
void IRsend::sendGC(uint16_t buf[], uint16_t len)
{
    uint16_t hz = buf[kGlobalCacheFreqIndex];  // GC frequency is in Hz.
    enableIROut(hz);
    uint32_t periodic_time = calcUSecPeriod(hz, false);
    uint8_t emits =
        std::min(buf[kGlobalCacheRptIndex],
                 static_cast<uint16_t>(kGlobalCacheMaxRepeat));

    // Repeat
    for (uint8_t repeat = 0; repeat < emits; repeat++)
    {
        // First time through, start at the beginning (kGlobalCacheStartIndex),
        // otherwise for repeats, we start a specified offset from that.
        uint16_t offset = kGlobalCacheStartIndex;
        if (repeat) offset += buf[kGlobalCacheRptStartIndex] - 1;

        // Data
        for (; offset < len; offset++)
        {
            // Convert periodic units to microseconds.
            // Minimum is kGlobalCacheMinUsec for actual GC units.
            uint32_t microseconds =
                std::max(buf[offset] * periodic_time, kGlobalCacheMinUsec);

            // These codes start at an odd index (not even as with sendRaw).
            if (offset & 1)  // Odd bit.
                mark(microseconds);
            else  // Even bit.
                space(microseconds);
        }
    }

    // It's possible that we've ended on a mark(), thus ensure the LED is off.
    ledOff();
}

#endif

#include <iostream>

// Fast I/O to prevent TLE in interactive problems
int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int current_dist;
    std::cin >> current_dist;

    // Loop until we reach the exit (distance 0)
    while (current_dist > 0)
    {
        int res;
        int new_dist;

        // --- Try color 0 ---
        std::cout << "move 0" << std::endl;
        std::cin >> res;
        if (res == 1)
        {
            // Reached the exit, terminate
            break;
        }

        std::cout << "query" << std::endl;
        std::cin >> new_dist;
        if (new_dist < current_dist)
        {
            // Success: moved closer to the exit.
            // Update distance and start finding the path from the new node.
            current_dist = new_dist;
            continue;
        }

        // Failure: moved away from the exit. Backtrack to the previous node.
        std::cout << "move 0" << std::endl;
        std::cin >> res; // Result is not needed, we know we are not at the exit.

        // --- Try color 1 ---
        std::cout << "move 1" << std::endl;
        std::cin >> res;
        if (res == 1)
        {
            // Reached the exit
            break;
        }

        std::cout << "query" << std::endl;
        std::cin >> new_dist;
        if (new_dist < current_dist)
        {
            // Success: moved closer.
            current_dist = new_dist;
            continue;
        }

        // Failure: backtrack.
        std::cout << "move 1" << std::endl;
        std::cin >> res;

        // --- Deduce color 2 ---
        // If both color 0 and 1 lead away from the exit, color 2 must lead towards it.
        std::cout << "move 2" << std::endl;
        std::cin >> res;
        if (res == 1)
        {
            // Reached the exit
            break;
        }

        // We are now one step closer. Update the distance without a query.
        current_dist--;
    }

    return 0;
}

#include <Alembic/Abc/All.h>
#include <Alembic/AbcCoreOgawa/All.h>
#include <Alembic/AbcMaterial/OMaterial.h>
#include <Alembic/AbcMaterial/IMaterial.h>
#include <Alembic/AbcMaterial/MaterialFlatten.h>
#include "PrintMaterial.h"

namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

// Writes a test material hierarchy to an Alembic file
void write()
{
    // Create archive and root object
    Abc::OArchive archive(
            Alembic::AbcCoreOgawa::WriteArchive(), 
            "FlattenMaterial.abc"
    );

    Abc::OObject root(archive, Abc::kTop);

    // Create dummy enclosing object for materials
    Abc::OObject materials(root, "materials");

    // Create parent material
    Mat::OMaterial parentMaterial(materials, "parentMaterial");
    parentMaterial.getSchema().setShader("prman", "surface", "paintedplastic");
    parentMaterial.getSchema().setShader("prman", "displacement", "knobby");

    // Set surface shader parameters
    {
        Abc::OFloatProperty prop(
                parentMaterial.getSchema().getShaderParameters(
                        "prman", "surface"),
                        "Kd");
        prop.set(0.5);
    }

    {
        Abc::OStringProperty prop(
                parentMaterial.getSchema().getShaderParameters(
                        "prman", "surface"), 
                        "texname");
        prop.set("taco");
    }

    // Set displacement shader parameters
    {
        Abc::OFloatProperty prop(
                parentMaterial.getSchema().getShaderParameters(
                        "prman", "displacement"),
                        "height");
        prop.set(0.75);
    }

    // Create child material inheriting from parent
    Mat::OMaterial childMaterial(parentMaterial, "childMaterial");
    childMaterial.getSchema().setShader("prman", "surface",
            "betterpaintedplastic");

    {
        Abc::OStringProperty prop(
                childMaterial.getSchema().getShaderParameters(
                        "prman", "surface"), 
                        "texname");
        prop.set("cheese");
    }
}

// Reads and prints material information
void read()
{
    // Open archive
    Abc::IArchive archive(
            Alembic::AbcCoreOgawa::ReadArchive(),
            "FlattenMaterial.abc"
    );

    Abc::IObject materialsObject(archive.getTop(), "materials");
    Mat::IMaterial parentMaterial(materialsObject, "parentMaterial");
    Mat::IMaterial childMaterial(parentMaterial, "childMaterial");

    std::cout << "----------------------------------------\n";
    std::cout << "LOCAL\n";
    std::cout << "---------------------------\n";
    std::cout << "Local parent material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(parentMaterial.getSchema());

    std::cout << "---------------------------\n";
    std::cout << "Local child material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(childMaterial.getSchema());

    std::cout << "----------------------------------------\n";
    std::cout << "FLATTENED\n";
    printFlattenedMaterial(parentMaterial);
    printFlattenedMaterial(childMaterial);
}

// Main function
int main(int argc, char *argv[])
{
    write();
    read();
    return 0;
}

#include "test_ffb_common.h"

namespace FFBEngineTests {

// Test for issue #42: FFB inversion persistence across presets
TEST_CASE(test_issue_42_ffb_inversion_persistence, "Config") 
{
    std::cout << "\nTest: Issue #42 - FFB Inversion Persistence Across Presets" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);
    Config::LoadPresets();

    // Case 1: Start with Invert = True
    FFBEngineTestAccess::SetInvertForce(engine, true);
    ASSERT_TRUE(engine.m_invert_force);

    // Apply "Default" preset
    Config::ApplyPreset(0, engine);
    ASSERT_TRUE(engine.m_invert_force); // Should remain true

    // Apply "T300" preset (which used to set it to true explicitly)
    int t300_idx = -1;
    for(int i=0; i<(int)Config::presets.size(); i++) 
    {
        if(Config::presets[i].name == "T300") 
        {
            t300_idx = i;
            break;
        }
    }

    if(t300_idx != -1) 
    {
        Config::ApplyPreset(t300_idx, engine);
        ASSERT_TRUE(engine.m_invert_force);
    }

    // Case 2: Start with Invert = False
    FFBEngineTestAccess::SetInvertForce(engine, false);
    ASSERT_FALSE(engine.m_invert_force);

    // Apply "Default" preset
    Config::ApplyPreset(0, engine);
    ASSERT_FALSE(engine.m_invert_force); // Should remain false!

    if(t300_idx != -1) 
    {
        Config::ApplyPreset(t300_idx, engine);
        ASSERT_FALSE(engine.m_invert_force); // Should remain false!
    }

    // Case 3: Verify Preset::UpdateFromEngine doesn't capture it 
    // (indirectly verified by lack of member)
    // But we can check that if we change engine inversion, and update a preset, 
    // then change engine inversion back, applying the preset doesn't revert it.
    Preset user_preset("UserTest", false);
    FFBEngineTestAccess::SetInvertForce(engine, true);
    user_preset.UpdateFromEngine(engine);
    FFBEngineTestAccess::SetInvertForce(engine, false);
    user_preset.Apply(engine);
    ASSERT_FALSE(engine.m_invert_force); // Apply should NOT have changed it to true
}

// Test for issue #42: FFB inversion global persistence (save/load)
TEST_CASE(test_issue_42_ffb_inversion_global_persistence, "Config") 
{
    std::cout << "\nTest: Issue #42 - FFB Inversion Global Persistence (Save/Load)" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);
    std::string test_ini = "test_issue_42_persistence.ini";

    // Case 1: Save as True, Load
    FFBEngineTestAccess::SetInvertForce(engine, true);
    Config::Save(engine, test_ini);

    FFBEngine engine_load;
    FFBEngineTestAccess::SetInvertForce(engine_load, false); // Distort
    Config::Load(engine_load, test_ini);
    ASSERT_TRUE(engine_load.m_invert_force);

    // Case 2: Save as False, Load
    FFBEngineTestAccess::SetInvertForce(engine, false);
    Config::Save(engine, test_ini);

    FFBEngine engine_load2;
    FFBEngineTestAccess::SetInvertForce(engine_load2, true); // Distort
    Config::Load(engine_load2, test_ini);
    ASSERT_FALSE(engine_load2.m_invert_force);

    std::remove(test_ini.c_str());
}

