// Implements logical equivalence (XNOR) for two booleans
bool Bool::bool_dec(const bool b1, const bool b2)
{
    if (b1)
    {
        if (b2)
        {
            return true;
        }
        else
        {
            return false;
        }
    }
    else
    {
        if (b2)
        {
            return false;
        }
        else
        {
            return true;
        }
    }
}

