// Synchronize hover timeout value with game memory
void Tooltip::synchronize_hover_timeout() 
{
    mem::write<int>(0x59E10D, hover_timeout.get());
}

// Synchronize alt+container tooltip behavior
void Tooltip::synchronize_alt_all_containers() 
{
    if (all_containers.get()) 
    {
        // Remove hovered checks for showing tooltips while holding alt for containers
        mem::set(0x416D1D, 0x90, 2);
        mem::set(0x416D22, 0x90, 2);
    } 
    else 
    {
        // Restore original conditional jump instructions
        mem::write<BYTE[2]>(0x416d1d, {0x74, 0x74});
        mem::write<BYTE[2]>(0x416D22, {0x74, 0x6F});
    }
    // Zeal::Game::print_chat("Tooltips for all containers while holding alt: %s", all_containers ? "enabled" : "disabled");
}

// Tooltip constructor - initializes hooks and memory patches
Tooltip::Tooltip(ZealService *zeal) 
{
    // Patch to change jbe to jb for smoother tooltip timer behavior
    mem::write<BYTE>(0x59e112, 0x82);

    // Add /tooltipall command to toggle container tooltips with alt
    zeal->commands_hook->Add("/tooltipall", {}, "Toggle showing all open containers tooltips when holding alt.",
        [this](std::vector<std::string> &args) 
        {
            all_containers.toggle();
            return true;  // Return true to stop the game from processing any further on this command,
                          // false if you want to just add features to an existing cmd
        });

    // Add /tooltiptimer command to set tooltip delay
    zeal->commands_hook->Add("/tooltiptimer", {"/ttimer"}, "Set the time limit before a tooltip appears.",
        [this](std::vector<std::string> &args) 
        {
            int timeout = 0;
            if (args.size() > 1 && Zeal::String::tryParse(args[1], &timeout)) 
            {
                hover_timeout.set(timeout);
                Zeal::Game::print_chat("Tooltip hover timer now set to %i", hover_timeout.get());
            }
            return true;  // Return true to stop the game from processing any further on this command,
                          // false if you want to just add features to an existing cmd
        });
}

