// Function to compute absolute difference between highest and lowest z-values
float computeZRange(float z1, float z2, float z3) {
    float upperBound = std::max({z1, z2, z3});
    float lowerBound = std::min({z1, z2, z3});
    return std::abs(upperBound - lowerBound);
}

