// Generate OpenGL texture setup code for a 3D texture
std::string createOpenGL3DTextureConfig(int wrapMode, int minFilterType, int magFilterType, int texInternalFormat, int textureDimension) {
    std::stringstream glslStream;
    glslStream << "glTexParameteri(GL_TEXTURE_3D, GL_TEXTURE_WRAP_R, " << wrapMode << ");\n";
