// Retrieves a string value from the Windows registry
std::string fetchRegistryString(const std::string& regPath, const std::string& entryName) {
    HKEY hKey;
    std::string result;

    // Attempt to open the specified registry key with read access
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, regPath.c_str(), 0, KEY_READ, &hKey) == ERROR_SUCCESS) {
        DWORD valueType;
        DWORD bufferSize;

        // First query to determine the type and size of the value
        if (RegQueryValueEx(hKey, entryName.c_str(), NULL, &valueType, NULL, &bufferSize) == ERROR_SUCCESS) {
            if (valueType == REG_SZ) {
                // Allocate buffer for the string data
                char* tempBuffer = new char[bufferSize];

                // Retrieve the actual string value
                if (RegQueryValueEx(hKey, entryName.c_str(), NULL, &valueType, 
                                   reinterpret_cast<LPBYTE>(tempBuffer), &bufferSize) == ERROR_SUCCESS) {
                    result = std::string(tempBuffer);
                }

                delete[] tempBuffer;
            }
            // Additional handling for other data types could be added here
        }
        RegCloseKey(hKey);
    }
    return result;
}

