// Process BASIC-style program lines with GOTO/GOSUB support
int main() {
    std::queue<std::string> commands;
    std::stack<int> jumpStack;
    std::string cmd;
    int currentLine = 10;

    while (std::cin >> cmd) {
        commands.push(cmd);
        if (cmd == "GOTO" || cmd == "GOSUB") {
            int target;
            std::cin >> target;
            jumpStack.push(target);
        }
        std::cin >> currentLine;
    }

    while (!commands.empty()) {
        std::cout << currentLine << ' ' << commands.front();
        if (commands.front() == "GOTO" || commands.front() == "GOSUB") {
            std::cout << ' ' << jumpStack.top();
            jumpStack.pop();
        }
        std::cout << std::endl;
        commands.pop();
        currentLine = currentLine + 10;
    }

    return 0;
}

