class ComplexNumber {
private:
    double realPart;
    double imaginaryPart;
public:
    // Initialize complex number with real and imaginary components
    ComplexNumber(double r, double i) : realPart(r), imaginaryPart(i) {}

    // Accessor methods
    double getRealComponent() const { return realPart; }
    double getImaginaryComponent() const { return imaginaryPart; }

    // Add two complex numbers
    ComplexNumber operator+(const ComplexNumber& other) const {
        return ComplexNumber(realPart + other.realPart, imaginaryPart + other.imaginaryPart);
    }

    // Subtract two complex numbers
    ComplexNumber operator-(const ComplexNumber& other) const {
        return ComplexNumber(realPart - other.realPart, imaginaryPart - other.imaginaryPart);
    }

    // Multiply two complex numbers
    ComplexNumber operator*(const ComplexNumber& other) const {
        return ComplexNumber(
            realPart * other.realPart - imaginaryPart * other.imaginaryPart,
            realPart * other.imaginaryPart + imaginaryPart * other.realPart
        );
    }

    // Compute complex conjugate
    ComplexNumber getConjugate() const {
        return ComplexNumber(realPart, -imaginaryPart);
    }
};
