class record
{
public:
    using iter = std::vector<std::string>::const_iterator;
    using len_t = std::vector<std::string>::size_type;

    // Storage for key-value pairs using hash map
    std::unordered_map<std::string, std::string> store;

    // Retrieve value for specified key as type T
    template<typename U>
    U fetch(const std::string& label) const {
        auto pos = store.find(label);
        if (pos != store.end()) {
            try {
                return transform<U>(pos->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Conversion to requested type failed");
            }
        } else {
            throw std::out_of_range("Specified key not found");
        }
    }

    // Retrieve value with fallback default if key missing
    template<typename U>
    U fetch(const std::string& label, const U& fallback) const {
        auto pos = store.find(label);
        if (pos != store.end()) {
            try {
                return transform<U>(pos->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Conversion to requested type failed");
            }
        } else {
            return fallback;
        }
    }

private:
    // Utility to convert string representation to target type
    template<typename U>
    U transform(const std::string& input) const {
        if (std::is_same<U, int>::value) {
            return std::stoi(input);
        } else if (std::is_same<U, double>::value) {
            return std::stod(input);
        } else if (std::is_same<U, std::string>::value) {
            return input;
        } else {
            throw std::invalid_argument("Type conversion not supported");
        }
    }
};

#include <vector>
using namespace std;

// Mark all connected 'L' cells starting from position (row, col) as visited
void traverseIsland(vector<vector<char>>& matrix, int row, int col) {
    // Check boundaries and if current cell is unvisited land ('L')
    if (row < 0 || row >= matrix.size() || col < 0 || col >= matrix[0].size() || matrix[row][col] != 'L') {
        return;
    }

    matrix[row][col] = 'X';  // Mark current cell as visited

    // Explore all 8 neighboring cells (including diagonals)
    traverseIsland(matrix, row + 1, col);     // Down
    traverseIsland(matrix, row - 1, col);     // Up
    traverseIsland(matrix, row, col + 1);     // Right
    traverseIsland(matrix, row, col - 1);     // Left
    traverseIsland(matrix, row + 1, col + 1); // Down-Right diagonal
    traverseIsland(matrix, row - 1, col - 1); // Up-Left diagonal
    traverseIsland(matrix, row + 1, col - 1); // Down-Left diagonal
    traverseIsland(matrix, row - 1, col + 1); // Up-Right diagonal
}

// Count the number of separate land regions ('L' clusters) in the grid
int numberOfLandClusters(vector<vector<char>>& matrix) {
    int clusterCount = 0;

    for (int r = 0; r < matrix.size(); r++) {
        for (int c = 0; c < matrix[0].size(); c++) {
            if (matrix[r][c] == 'L') {
                clusterCount++;
                traverseIsland(matrix, r, c);
            }
        }
    }

    return clusterCount;
}

