// Apply Caesar cipher with reverse shift (decryption-like)
char shiftCharacter(char ch, int shiftAmount) {
    char base = (islower(ch)) ? 'a' : 'A';
    ch = (isalpha(ch)) ? (ch - base + (26 - shiftAmount)) % 26 + base : ch;
    return ch;
}

int main() {
    std::string textLine;
    int shiftValue;

    std::cout << "Please enter a line of text:\n";
    std::getline(std::cin, textLine);

    std::cout << "Enter an integer to shift the characters (1-25):\n";
    std::cin >> shiftValue;

    // Validate shift value
    while (shiftValue < 1 || shiftValue > 25) {
        std::cout << "Invalid shift amount. Please enter a number between 1 and 25:\n";
        std::cin >> shiftValue;
    }

    std::string resultString;
    for (char character : textLine) {
        resultString += shiftCharacter(character, shiftValue);
    }

    std::cout << "Resulting text: " << resultString << std::endl;
    return 0;
}

