class SequentialPrinter {
public:
    SequentialPrinter() : nextNumber(1) {}

    void executeFirst() {
        displayNumber(1);
    }

    void executeSecond() {
        displayNumber(2);
    }

    void executeThird() {
        displayNumber(3);
    }

private:
    int nextNumber;
    std::mutex mtx;
    std::condition_variable cv;

    void displayNumber(int value) {
        std::unique_lock<std::mutex> guard(mtx);
        cv.wait(guard, [this, value] { return nextNumber == value; });
        std::cout << value << std::endl;
        nextNumber++;
        cv.notify_all();
    }
};

TEST(SequentialPrinterTest, OrderVerification) {
    SequentialPrinter printer;
    std::thread worker1(&SequentialPrinter::executeFirst, &printer);
    std::thread worker2(&SequentialPrinter::executeSecond, &printer);
    std::thread worker3(&SequentialPrinter::executeThird, &printer);

    worker1.join();
    worker2.join();
    worker3.join();

    std::string result = testing::internal::GetCapturedStdout();
    ASSERT_EQ(result, "123\n");
}

