// Function to verify if a JSON structure is well-formed
bool checkJSONStructure(Json::Value document) {
    // Serialize the JSON object to a string representation
    Json::StreamWriterBuilder serializer;
    std::string jsonString = Json::writeString(serializer, document);

    // Prepare to parse the string back into a JSON object
    Json::CharReaderBuilder parser;
    std::istringstream inputStream(jsonString);
    Json::Value verifiedJson;
    std::string errorMessage;

    // Attempt to parse the JSON string
    bool parseSuccess = Json::parseFromStream(parser, inputStream, &verifiedJson, &errorMessage);

    if (parseSuccess) {
        // JSON structure is valid
        return true;
    } else {
        // JSON structure has errors
        std::cerr << "JSON parsing error: " << errorMessage << std::endl;
        return false;
    }
}

int main() {
    // Read JSON data from file into the document variable
    std::ifstream inputFile("data.json");
    Json::Value jsonDocument;
    Json::CharReaderBuilder builder;
    std::string jsonText;

    // Read the entire file content
    if (inputFile.is_open()) {
        std::getline(inputFile, jsonText);
        inputFile.close();

        // Parse the JSON text
        std::unique_ptr<Json::CharReader> reader(builder.newCharReader());
        std::string parseError;
        if (!reader->parse(jsonText.c_str(), jsonText.c_str() + jsonText.size(), &jsonDocument, &parseError)) {
            std::cerr << "Failed to read JSON file: " << parseError << std::endl;
            return 1;
        }
    } else {
        std::cerr << "Could not open JSON file." << std::endl;
        return 1;
    }

    // Validate the JSON data using our checking function
    if (checkJSONStructure(jsonDocument)) {
        std::cout << "JSON format is correct." << std::endl;
    } else {
        std::cout << "JSON format is incorrect." << std::endl;
    }

    return 0;
}

