// Compare two floating-point numbers for equality within a given ULP tolerance
bool nearly_equal(const float a, const float b, int max_ulp)
{
    // Convert the floating-point values to their bit-level integer forms
    int a_bits = *reinterpret_cast<const int*>(&a);
    int b_bits = *reinterpret_cast<const int*>(&b);

    // Adjust negative zero representation to match IEEE 754 ordering
    if (a_bits < 0)
        a_bits = std::numeric_limits<int>::max() - a_bits + 1;
    if (b_bits < 0)
        b_bits = std::numeric_limits<int>::max() - b_bits + 1;

    // Compute the absolute difference in terms of ULPs
    int ulp_gap = std::abs(a_bits - b_bits);

    // Determine if the difference is within acceptable bounds
    return ulp_gap <= max_ulp;
}

