template <typename T>
struct WeightBalancedBinaryTree {
  struct TreeNode {
    T data;
    int size;
    TreeNode *leftChild, *rightChild;
  };

  TreeNode *treeRoot;

  // Insert a new element into the tree
  void add(TreeNode *&node, const T &value) {
    if (node == nullptr) {
      node = new TreeNode{value, 1, nullptr, nullptr};
    } else if (value < node->data) {
      add(node->leftChild, value);
    } else {
      add(node->rightChild, value);
    }
    maintain(node);
  }

  // Delete an element from the tree
  void erase(TreeNode *&node, const T &value) {
    if (node == nullptr) return;

    if (value < node->data) {
      erase(node->leftChild, value);
    } else if (value > node->data) {
      erase(node->rightChild, value);
    } else {
      if (node->leftChild == nullptr) {
        TreeNode *temp = node->rightChild;
        delete node;
        node = temp;
      } else if (node->rightChild == nullptr) {
        TreeNode *temp = node->leftChild;
        delete node;
        node = temp;
      } else {
        TreeNode *successor = findMinimum(node->rightChild);
        node->data = successor->data;
        node->size = successor->size;
        erase(node->rightChild, successor->data);
      }
    }
    maintain(node);
  }

  // Find the node with minimum value in a subtree
  TreeNode *findMinimum(TreeNode *node) {
    while (node->leftChild != nullptr) {
      node = node->leftChild;
    }
    return node;
  }

  // Rebalance the tree if necessary
  void maintain(TreeNode *&node) {
    if (node == nullptr) return;

    int leftSize = (node->leftChild == nullptr) ? 0 : node->leftChild->size;
    int rightSize = (node->rightChild == nullptr) ? 0 : node->rightChild->size;

    if (leftSize > 3 * rightSize || rightSize > 3 * leftSize) {
      std::vector<T> elements;
      traverse(node, elements);
      node = construct(elements, 0, elements.size());
    } else {
      node->size = leftSize + rightSize + 1;
    }
  }

  // In-order traversal to collect all elements
  void traverse(TreeNode *node, std::vector<T> &elements) {
    if (node == nullptr) return;
    traverse(node->leftChild, elements);
    elements.push_back(node->data);
    traverse(node->rightChild, elements);
  }

  // Build a balanced tree from sorted elements
  TreeNode *construct(const std::vector<T> &elements, int leftIndex, int rightIndex) {
    if (leftIndex >= rightIndex) return nullptr;

    int middle = (leftIndex + rightIndex) / 2;
    TreeNode *node = new TreeNode{elements[middle], 1, nullptr, nullptr};
    node->leftChild = construct(elements, leftIndex, middle);
    node->rightChild = construct(elements, middle + 1, rightIndex);

    int leftSubtreeSize = (node->leftChild == nullptr) ? 0 : node->leftChild->size;
    int rightSubtreeSize = (node->rightChild == nullptr) ? 0 : node->rightChild->size;
    node->size = leftSubtreeSize + rightSubtreeSize + 1;

    return node;
  }

  // Get the total number of nodes in the tree
  int getSize(TreeNode *node) {
    return (node == nullptr) ? 0 : node->size;
  }

  // Calculate sum of elements within a given range [low, high]
  T getRangeSum(TreeNode *node, const T &low, const T &high) {
    if (node == nullptr) return T();

    if (node->data < low) {
      return getRangeSum(node->rightChild, low, high);
    } else if (node->data > high) {
      return getRangeSum(node->leftChild, low, high);
    } else {
      return node->data + getRangeSum(node->leftChild, low, node->data) +
             getRangeSum(node->rightChild, node->data, high);
    }
  }
};

int main() {
  WeightBalancedBinaryTree<int> tree;
  tree.add(tree.treeRoot, 5);
  tree.add(tree.treeRoot, 3);
  tree.add(tree.treeRoot, 7);
  tree.add(tree.treeRoot, 2);
  tree.add(tree.treeRoot, 4);
  tree.add(tree.treeRoot, 6);
  tree.add(tree.treeRoot, 8);

  std::cout << "Total nodes in tree: " << tree.getSize(tree.treeRoot) << std::endl;
  std::cout << "Sum of values between 3 and 7: "
            << tree.getRangeSum(tree.treeRoot, 3, 7) << std::endl;

  tree.erase(tree.treeRoot, 5);
  std::cout << "Total nodes after deleting 5: " << tree.getSize(tree.treeRoot)
            << std::endl;

  return 0;
}

#include <iostream>

// Check if a binary tree satisfies BST properties
bool checkValidTree(TreeNode* head) {
    return validateTree(head, nullptr, nullptr);
}

bool validateTree(TreeNode* current, TreeNode* lowerBound, TreeNode* upperBound) {
    if (current == nullptr) {
        return true;
    }

    // Check if current node violates BST property
    if ((lowerBound != nullptr && current->val <= lowerBound->val) || 
        (upperBound != nullptr && current->val >= upperBound->val)) {
        return false;
    }

    // Recursively validate left and right subtrees with updated bounds
    return validateTree(current->left, lowerBound, current) && 
           validateTree(current->right, current, upperBound);
}

