enum class SymbolType {
  LocalVar,
  Method,
  Struct
};

enum class ScopeType {
  Module,
  Block
};

struct SymbolRecord {
  std::string identifier;
  SymbolType type;
  std::string sourceFile;
  std::vector<std::pair<ScopeType, std::string>> scopes;

  SymbolRecord(const std::string& id, SymbolType t, const std::string& file,
               std::vector<std::pair<ScopeType, std::string>> sc)
      : identifier(id), type(t), sourceFile(file), scopes(sc) {}
};

class SymbolMonitor {
private:
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> observedSet;
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> accessedSet;

public:
  void observe(const SymbolRecord& rec) {
    for (const auto& scope : rec.scopes) {
      observedSet[scope.second][rec.identifier] = true;
    }
  }

  void access(const SymbolRecord& rec) {
    for (const auto& scope : rec.scopes) {
      accessedSet[scope.second][rec.identifier] = true;
    }
  }

  bool wasObserved(const std::string& scope, const std::string& name) {
    return observedSet[scope][name];
  }

  bool wasAccessed(const std::string& scope, const std::string& name) {
    return accessedSet[scope][name];
  }
};

int main() {
  SymbolMonitor monitor;

  SymbolRecord entry1("Y2", SymbolType::LocalVar, "SourceFile.cpp",
                     {{ScopeType::Module, ""}});
  monitor.observe(entry1);
  monitor.access(entry1);

  SymbolRecord entry2("Y3", SymbolType::LocalVar, "SourceFile.cpp",
                     {{ScopeType::Module, ""},
                      {ScopeType::Module, ""}});
  monitor.observe(entry2);
  monitor.access(entry2);

  // Check symbol monitoring results
  std::cout << "Symbol Y2 observed and accessed in global module: " 
            << monitor.wasObserved("", "Y2") << " " 
            << monitor.wasAccessed("", "Y2") << std::endl;
  std::cout << "Symbol Y3 observed and accessed in global module: " 
            << monitor.wasObserved("", "Y3") << " " 
            << monitor.wasAccessed("", "Y3") << std::endl;

  return 0;
}

