using feature_volume = int***; // Assuming feature_volume is a pointer to a 3D matrix of features

int compute_total_ops(const std::vector<convolution_filter>& filters, const feature_volume data, int begin_idx, int finish_idx) {
    unsigned count = finish_idx - begin_idx + 1;
    assert(finish_idx >= begin_idx);
    assert(count <= filters.size());

    int kernel_h = filters[0].dimensions.height;
    int kernel_w = filters[0].dimensions.width;
    int kernel_z = filters[0].dimensions.depth;

    // Calculate the total number of operations based on the dimensions of the filters and the length of the range
    int total_ops = count * kernel_h * kernel_w * kernel_z;
    return total_ops;
}

