// Determine if there exist two trees with a distance of k between them
bool checkTreeDistance(std::vector<int> positions, int targetDist) {
    std::sort(positions.begin(), positions.end()); // Sort the tree positions in ascending order
    int left = 0;
    int right = positions.size() - 1;

    while (left < right) {
        if (positions[left] + targetDist < positions[right]) {
            left++; // Move to the next tree position from the left
        } else if (positions[left] + targetDist > positions[right]) {
            right--; // Move to the next tree position from the right
        } else {
            return true; // Found two trees with the specified distance
        }
    }
    return false; // No such pair of trees found
}

