#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>

class WorkQueueManager {
public:
    WorkQueueManager(size_t thread_count) : active_(true), active_tasks_(0) {
        for (size_t idx = 0; idx < thread_count; ++idx) {
            workers_.emplace_back([this] { workerLoop(); });
        }
    }

    void process() {
        std::unique_lock<std::mutex> lock(mutex_);
        // When alive_ is true, work_items_ should not be empty after reacquiring the lock
        if (active_) {
            Job job = work_items_.front();
            work_items_.pop();
            lock.unlock();
            ++active_tasks_;
            // Perform the job execution
            job();  // Assuming Job is a callable (function, lambda, functor)
            lock.lock();
            --active_tasks_;
            condition_.notify_one();
        }
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            active_ = false;
        }
        condition_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    using Job = std::function<void()>;
    std::queue<Job> work_items_;
    std::vector<std::thread> workers_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool active_;
    size_t active_tasks_;

    void workerLoop() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !active_ || !work_items_.empty(); });
            if (!active_ && work_items_.empty()) {
                return;
            }
            process();
        }
    }
};

