class StockManager {
private:
    std::map<int, std::pair<std::string, int, double>> stock; // Map to store products with unique identifier as key
public:
    void addProduct(int productId, const std::string& productName, int count, double unitPrice) {
        if (stock.find(productId) != stock.end()) {
            stock[productId].second += count; // Increase quantity if product already exists
        } else {
            stock[productId] = std::make_pair(productName, count, unitPrice); // Add new product to stock
        }
    }

    void deleteProduct(int productId, int amount) {
        if (stock.find(productId) != stock.end()) {
            if (stock[productId].second <= amount) {
                stock.erase(productId); // Remove product if quantity to be deleted exceeds available quantity
            } else {
                stock[productId].second -= amount; // Update quantity
            }
        }
    }

    void showStock() {
        std::cout << "Current Stock:\n";
        for (const auto& entry : stock) {
            std::cout << "ID: " << entry.first << ", Name: " << entry.second.first
                      << ", Count: " << entry.second.second << ", Price: $" << entry.second.third << std::endl;
        }
    }
};

