class InvalidDateFormatException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Invalid date format";
    }
};

class InvalidDateTimeValueException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Invalid date or time value";
    }
};

class Timestamp {
private:
    int year, month, day, hour, minute, second;
public:
    Timestamp(const std::string& timestampStr) {
        std::regex timestampPattern(R"((\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}))");
        std::smatch result;
        if (!std::regex_match(timestampStr, result, timestampPattern)) {
            throw InvalidDateFormatException();
        }
        year = std::stoi(result[1]);
        month = std::stoi(result[2]);
        day = std::stoi(result[3]);
        hour = std::stoi(result[4]);
        minute = std::stoi(result[5]);
        second = std::stoi(result[6]);
        if (!checkDate(year, month, day) || !checkTime(hour, minute, second)) {
            throw InvalidDateTimeValueException();
        }
    }

    void checkTimestamp() {
        if (!checkDate(year, month, day) || !checkTime(hour, minute, second)) {
            throw InvalidDateTimeValueException();
        }
    }

private:
    bool isLeapYear(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    bool checkDate(int y, int m, int d) {
        if (y < 1 || m < 1 || m > 12 || d < 1) {
            return false;
        }
        static const int daysPerMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (m == 2 && isLeapYear(y)) {
            return d <= 29;
        } else {
            return d <= daysPerMonth[m];
        }
    }

    bool checkTime(int h, int min, int sec) {
        return (h >= 0 && h < 24) && (min >= 0 && min < 60) && (sec >= 0 && sec < 60);
    }
};

int main() {
    try {
        Timestamp ts1("2015-13-05 :06:03");
    } catch (const InvalidDateFormatException& e) {
        std::cout << "InvalidDateFormatException caught: " << e.what() << std::endl;
    }

    try {
        Timestamp ts2("2015-13-05 09 06 03");
    } catch (const InvalidDateFormatException& e) {
        std::cout << "InvalidDateFormatException caught: " << e.what() << std::endl;
    }

    try {
        Timestamp ts3("2015-13-05 09:06:03");
        ts3.checkTimestamp();
    } catch (const InvalidDateTimeValueException& e) {
        std::cout << "InvalidDateTimeValueException caught: " << e.what() << std::endl;
    }

    try {
