class ErrorMapper {
public:
    template <typename Callable>
    void convert(Callable action) {
        try {
            action();
        } catch (const std::exception& err) {
            auto pos = errorRegistry.find(typeid(err).name());
            if (pos != errorRegistry.end()) {
                throw pos->second();
            } else {
                throw;
            }
        }
    }

    template <typename Source, typename Target>
    void registerMapping() {
        errorRegistry[typeid(Source).name()] = []() { return Target(); };
    }

private:
    std::map<std::string, std::function<std::exception()>> errorRegistry;
};

