ULONGLONG fileTimeToULL(const FILETIME& ft) {
    return (((ULONGLONG)ft.dwHighDateTime) << 32) | ft.dwLowDateTime;
}

// Global map to store system metrics
std::map<std::string, double> system_metrics;

// Function to compute CPU utilization and update system_metrics
void computeCPUUtilization(const FILETIME& idleTime,
                           const FILETIME& kernelTime,
                           const FILETIME& userTime,
                           const FILETIME& prevIdle,
                           const FILETIME& prevKernel,
                           const FILETIME& prevUser) {
    system_metrics.clear(); // Reset the map before populating

    ULONGLONG uTime = fileTimeToULL(userTime) - fileTimeToULL(prevUser);
    ULONGLONG kTime = fileTimeToULL(kernelTime) - fileTimeToULL(prevKernel);
    ULONGLONG iTime = fileTimeToULL(idleTime) - fileTimeToULL(prevIdle);

    double utilization = 100.0 * (uTime + kTime) / (uTime + kTime + iTime);
    system_metrics["CPU Utilization"] = utilization; // Store result in map
