#include <iostream>

class DataNode {
public:
    int nodeId;
};

class NodeList {
private:
    DataNode* pFirst;
    DataNode* pCurrent;
public:
    NodeList() : pFirst(nullptr), pCurrent(nullptr) {
        // Initialize the list
        // For example, add items to the list
    }

    void InsertNode(int id) {
        // Add a node with the given id to the list
        DataNode* newNode = new DataNode();
        newNode->nodeId = id;
        newNode->next = pFirst;
        pFirst = newNode;
    }

    DataNode* Traverse() {
        if (pCurrent == nullptr) {
            pCurrent = pFirst;
        } else {
            pCurrent = pCurrent->next;
        }
        return pCurrent;
    }
};

class ListWalker {
private:
    NodeList* mpList;
    DataNode* pCurrent;
public:
    ListWalker(NodeList* pList) : mpList(pList), pCurrent(nullptr) {
        // Constructor that takes a pointer to a NodeList object
    }

    DataNode* GetNext() {
        // Method that returns the next node in the list or nullptr if there are no more nodes
        return mpList->Traverse();
    }

    bool HasMore() {
        // Method that returns true if there are more nodes in the list, and false otherwise
        return mpList->Traverse() != nullptr;
    }
};

int main() {
    NodeList* nodeList = new NodeList();
    nodeList->InsertNode(10);
    nodeList->InsertNode(20);
    nodeList->InsertNode(30);

    ListWalker walker(nodeList);

    while (walker.HasMore()) {
        DataNode* node = walker.GetNext();
        std::cout << "Processing node with id: " << node->nodeId << std::endl;
    }

    return 0;
}

