class MethodNotImplementedException : public std::exception {
private:
    std::string methodName;
    int errorNumber;
    std::string details;
public:
    MethodNotImplementedException(const std::string& funcName)
        : methodName(funcName), errorNumber(0), details("") {}
    MethodNotImplementedException(const std::string& funcName, int errCode)
        : methodName(funcName), errorNumber(errCode), details("") {}
    MethodNotImplementedException(const std::string& funcName, int errCode, const std::string& msg)
        : methodName(funcName), errorNumber(errCode), details(msg) {}
    const char* what() const noexcept override {
        std::stringstream ss;
        ss << "Method '" << methodName << "' is not implemented";
        if (errorNumber != 0) {
            ss << " (Error code: " << errorNumber << ")";
        }
        if (!details.empty()) {
            ss << ": " << details;
        }
        return ss.str().c_str();
    }
};

// Verification function to check the behavior of MethodNotImplementedException
void verifyNotImplementedException() {
    try {
        throw MethodNotImplementedException("unimplemented_method");
    } catch (const MethodNotImplementedException& e) {
        // Confirm the exception message
        assert(std::string(e.what()) == "Method 'unimplemented_method' is not implemented");
    }
    try {
        throw MethodNotImplementedException("sample_func", 789);
    } catch (const MethodNotImplementedException& e) {
        // Confirm the exception message
        assert(std::string(e.what()) == "Method 'sample_func' is not implemented (Error code: 789)");
    }
    try {
        throw MethodNotImplementedException("sample_func", 101, "Validate error description");
    } catch (const MethodNotImplementedException& e) {
        // Confirm the exception message
        assert(std::string(e.what()) == "Method 'sample_func' is not implemented (Error code: 101): Validate error description");
    }
}

