#include <mutex>
#include <random>

class ct_RndStore {
private:
    std::mutex mtx_Lock;
    int val_Value;
public:
    // Constructor to initialize val_Value with a random number
    ct_RndStore() {
        std::random_device rng_Source;
        std::mt19937 rng_Generator(rng_Source());
        std::uniform_int_distribution<int> rng_Dist(1, 100);
        val_Value = rng_Dist(rng_Generator);
    }
    // Method to swap random number data between two ct_RndStore instances
    void Exchange(ct_RndStore &ref_Other) {
        mtx_Lock.lock();
        ref_Other.mtx_Lock.lock();
        std::swap(val_Value, ref_Other.val_Value);
        ref_Other.mtx_Lock.unlock();
        mtx_Lock.unlock();
    }
};

