// Count how many times a specific word appears in a given text (case-insensitive)
int countWordOccurrences(const std::string& inputText, const std::string& targetWord) {
    std::string textLower = inputText;
    std::string wordLower = targetWord;

    // Normalize both strings to lowercase for case-insensitive comparison
    std::transform(textLower.begin(), textLower.end(), textLower.begin(), ::tolower);
    std::transform(wordLower.begin(), wordLower.end(), wordLower.begin(), ::tolower);

    int occurrences = 0;
    size_t index = textLower.find(wordLower, 0);

    while (index != std::string::npos) {
        occurrences++;
        index = textLower.find(wordLower, index + wordLower.length());
    }

    return occurrences;
}

int main() {
    std::string sampleText = "This is a sample text. This text contains the word 'this' multiple times. This is a simple example.";
    std::string searchWord = "this";

    int result = countWordOccurrences(sampleText, searchWord);
    std::cout << "Number of occurrences of the word '" << searchWord << "': " << result << std::endl;

    return 0;
}

