#include <climits>
#include <algorithm>

// Compute minimal energy for a given base pair configuration
int computeMinEnergy(int startIdx, int endIdx, CTStructure* structure, EnergyData* params) {
    int minVal = INT_MAX;  // Set initial value to maximum possible

    // Evaluate energy for hairpin loop configuration with specific parameters
    minVal = std::min(minVal, 
        erg4(startIdx, endIdx, endIdx - 1, 2, structure, params, structure->lfce[endIdx - 1]) + 
        penalty(startIdx, endIdx, structure, params) +
        structure->wmb.f(startIdx + 1, endIdx - 2) + 
        params->eparam[5] + params->eparam[6] + params->eparam[10]);

    // Consider stacking interactions and non-canonical pair contributions
    minVal = std::min(minVal, 
        params->tstkm[structure->numseq[startIdx]][structure->numseq[endIdx]]
                     [structure->numseq[startIdx + 1]][structure->numseq[endIdx - 1]] +
        checknp(structure->lfce[startIdx + 1], structure->lfce[endIdx - 1]));

    return minVal;  // Return the computed minimum energy value
}

