void VertexArray::AddBuffer(const VertexBuffer& buffer, const VertexBufferLayout& layout)
{
    Bind();  // Assume Bind() is a function that binds the vertex array for subsequent operations
    const auto& attributes = layout.GetElements();
    unsigned int byteOffset = 0;
    for (unsigned int index = 0; index < attributes.size(); ++index)
    {
        const auto& attr = attributes[index];
        glEnableVertexAttribArray(index);
        glVertexAttribPointer(index, attr.count, attr.type, attr.normalized, layout.GetStride(), (const void*)byteOffset);
        byteOffset += attr.count * VertexBufferElement::GetSizeOfType(attr.type);
    }
    buffer.Bind();  // Assume Bind() is a function that binds the vertex buffer for subsequent operations
    Unbind();  // Assume Unbind() is a function that unbinds the vertex array after operations
}

