class Solution {
private:
    // Recursive helper function to generate all valid expressions
    void generateExpressions(vector<string>& output, const string& digits, int goal, 
                            string& currentExpr, long long prevOperand, long long currentVal, int index) {
        // Base case: reached end of input string
        if (index == digits.length()) {
            if (currentVal == goal) {
                output.push_back(currentExpr);
            }
            return;
        }

        // Try all possible numbers starting from current position
        for (int j = index; j < digits.length(); j++) {
            // Skip numbers with leading zeros (except single "0")
            if (j != index && digits[index] == '0') {
                break;
            }

            string numberStr = digits.substr(index, j - index + 1);
            long long numberVal = stoll(numberStr);

            if (index == 0) {
                // First number in expression - no operator before it
                generateExpressions(output, digits, goal, currentExpr + numberStr, 
                                   numberVal, numberVal, j + 1);
            } else {
                // Try addition, subtraction, and multiplication
                generateExpressions(output, digits, goal, currentExpr + "+" + numberStr, 
                                   numberVal, currentVal + numberVal, j + 1);
                generateExpressions(output, digits, goal, currentExpr + "-" + numberStr, 
                                   -numberVal, currentVal - numberVal, j + 1);
                generateExpressions(output, digits, goal, currentExpr + "*" + numberStr, 
                                   prevOperand * numberVal, (currentVal - prevOperand) + prevOperand * numberVal, j + 1);
            }
        }
    }

public:
    // Main function to find all expressions that evaluate to target
    vector<string> addOperators(string digits, int goal) {
        vector<string> solutions;
        string expression;

        // Try all possible first numbers
        for (int k = 0; k < digits.length(); k++) {
            // Skip numbers with leading zeros (except single "0")
            if (k != 0 && digits[0] == '0') {
                break;
            }

            string firstNum = digits.substr(0, k + 1);
            long long firstVal = stoll(firstNum);
            generateExpressions(solutions, digits, goal, firstNum, firstVal, firstVal, k + 1);
        }

        return solutions;
    }
};

