class TripleReflectionCounter {
private:
    std::vector<int> dataList;
public:
    TripleReflectionCounter(const std::vector<int>& data) : dataList(data) {}

    int countOccurrences(int target) {
        int forwardCount = std::count(dataList.begin(), dataList.end(), target);
        int reverseCount = std::count(dataList.rbegin(), dataList.rend(), target);
        return forwardCount + reverseCount * 3;  // Account for three reflections of the list
    }
};

