// Find the next greater element for each element in the array
std::vector<int> next_larger_element(int size, const std::vector<int>& arr) {
    std::vector<int> output(size, -1);  // Initialize output array with -1
    std::stack<int> indices;  // Stack to store indices of elements
    for (int idx = 0; idx < size; idx++) {
        while (!indices.empty() && arr[idx] > arr[indices.top()]) {
            output[indices.top()] = arr[idx];  // Update output for elements with next larger element
            indices.pop();  // Pop the index as it has been processed
        }
        indices.push(idx);  // Push the current index onto the stack
    }
    return output;
}

