class Solution {
public:
    // Determine if two strings are permutations of each other
    bool AreStringsPermutations(std::string str1, std::string str2) {
        // First check: if lengths differ, they can't be permutations
        if (str1.size() != str2.size()) {
            return false;
        }

        // Sort both strings to compare their character compositions
        std::sort(str1.begin(), str1.end());
        std::sort(str2.begin(), str2.end());

        // If sorted versions are identical, the strings are permutations
        return str1 == str2;
    }
};

