// Load a PNG image from an input stream and convert it to a Bitmap object
Bitmap LoadPNG(std::istream& inputStream)
{
    // Read the entire stream into a string buffer
    std::string dataBuffer((std::istreambuf_iterator<char>(inputStream)), std::istreambuf_iterator<char>());

    // Prepare output buffer for decoded PNG data
    std::vector<unsigned char> pixelData;
    unsigned long imgWidth, imgHeight;

    // Decode PNG data
    int result = decodePNG(pixelData, imgWidth, imgHeight, 
                          reinterpret_cast<const unsigned char*>(dataBuffer.c_str()), 
                          dataBuffer.size());

    if (result != 0) {
        // Log error and return empty bitmap on failure
        Log::Error("Failed to decode PNG: " + std::to_string(result));
        return Bitmap(); // Return default-constructed (empty) Bitmap
    }

    // Create bitmap with decoded dimensions
    Bitmap resultBitmap(imgWidth, imgHeight);

    // Process each pixel from the decoded PNG data
    for (unsigned long row = 0; row < imgHeight; ++row) {
        for (unsigned long col = 0; col < imgWidth; ++col) {
            unsigned long index = (row * imgWidth + col) * 4;

            // Extract RGBA components and set pixel in bitmap
            resultBitmap.SetPixel(col, row, 
                                 Color(pixelData[index], 
                                       pixelData[index + 1], 
                                       pixelData[index + 2], 
                                       pixelData[index + 3]));
        }
    }

    return resultBitmap;
}

