std::pair<cv::Mat, cv::Mat> executeImageProcessing(const ImageSet& source, const ImageSet& target) {
    // Compute pixel-wise product of squared images from both sets
    cv::Mat product_squared = source.imageSquare.mul(target.imageSquare);
    // Compute pixel-wise product of blurred images from both sets
    cv::Mat product_blurred = source.imageBlur.mul(target.imageBlur);
    return std::make_pair(product_squared, product_blurred);
}

