// Compute the Euclidean distance between two 3D points
double computeEuclideanDistance(const std::vector<double>& coord1, const std::vector<double>& coord2) {
    double squaredSum = 0;
    for (size_t index = 0; index < coord1.size(); ++index) {
        squaredSum += pow(coord1[index] - coord2[index], 2);
    }
    return sqrt(squaredSum);
}

