class MonikerRegistry {
private:
    std::unordered_map<unsigned long, std::string> idMap;
    std::unordered_map<std::string, unsigned long> reverseMap;
    unsigned long nextIdentifier = 1;

public:
    // Register a new moniker with an unique identifier
    void registerMoniker(const std::string& strValue) {
        idMap[nextIdentifier] = strValue;
        reverseMap[strValue] = nextIdentifier;
        nextIdentifier++;
    }

    // Get the moniker string associated with an identifier
    std::string getMonikerById(unsigned long ulId) {
        if (idMap.find(ulId) != idMap.end()) {
            return idMap[ulId];
        }
        return "";  // Empty string if identifier not found
    }

    // Remove a moniker entry by its identifier
    void unregisterMoniker(unsigned long ulId) {
        if (idMap.find(ulId) != idMap.end()) {
            reverseMap.erase(idMap[ulId]);
            idMap.erase(ulId);
        }
    }

    // Get the identifier for a given moniker string
    unsigned long getIdForMoniker(const std::string& strValue) {
        if (reverseMap.find(strValue) != reverseMap.end()) {
            return reverseMap[strValue];
        }
        return 0;  // Return 0 if moniker not registered
    }
};

