struct ScalaFpgaRawHeader {
    uint16_t m_minApdOffset;
    uint16_t m_maxApdOffset;
    uint16_t m_frequencyInteger;
    uint16_t m_frequencyFractional;
    uint16_t m_deviceId;
    uint16_t m_reservedHeader7;
};

bool extractHeader(const uint8_t* buffer, size_t bufferSize, ScalaFpgaRawHeader& header) {
    if (bufferSize < sizeof(ScalaFpgaRawHeader)) {
        return false;  // Not enough data to parse the header
    }

    // Read and populate the header fields from the raw byte stream
    header.m_minApdOffset = (buffer[1] << 8) | buffer[0];
    header.m_maxApdOffset = (buffer[3] << 8) | buffer[2];
    header.m_frequencyInteger = (buffer[5] << 8) | buffer[4];
    header.m_frequencyFractional = (buffer[7] << 8) | buffer[6];
    header.m_deviceId = (buffer[9] << 8) | buffer[8];
    header.m_reservedHeader7 = (buffer[11] << 8) | buffer[10];

    return true;  // Successfully parsed the header
}

