// Perform parallel multiway merge on multiple sorted sequences using STXXL
std::vector<int> parallelMultiwayMerge(const std::vector<std::vector<int>>& inputSequences) {
    std::vector<int> mergedResult;

    // Initialize external memory vectors
    stxxl::vector<int> externalInput;

    // Copy all input sequences into the external vector
    for (const auto& seq : inputSequences) {
        externalInput.insert(externalInput.end(), seq.begin(), seq.end());
    }

    stxxl::vector<int> externalOutput;

    // Execute parallel multiway merge algorithm
    stxxl::multiway_merge(externalInput.begin(), externalInput.end(), 
                         externalOutput.begin(), inputSequences.size());

    // Transfer results back to standard vector with pre-allocated space
    mergedResult.reserve(externalOutput.size());
    for (const auto& value : externalOutput) {
        mergedResult.push_back(value);
    }

    return mergedResult;
}

