// Add a key-value pair to the appropriate level in the SSTable structure
void addToSSTable(int levelIndex, const std::string& directoryPath, const std::string& entryKey, const std::string& entryValue, 
                  std::vector<std::vector<ssTable>>& tableLevels, std::vector<int>& labelCounters, 
                  uint64_t& currentTimestamp, uint64_t& currentSize, 
                  std::vector<std::pair<std::string, std::string>>& buffer) {

    // Construct the SSTable file path using the target directory and next available label
    std::string filePath = directoryPath + '/' + std::to_string(labelCounters[levelIndex]) + ".sst";

    // Create and add new SSTable to the specified level
    tableLevels[levelIndex].emplace_back(ssTable::genTable(filePath, currentTimestamp, buffer));

    // Increment the label counter for this level
    ++labelCounters[levelIndex];

    // Reset the buffer and related metadata
    buffer.clear();
    currentTimestamp = 0;
    currentSize = 0;

    // Insert the new key-value pair into the buffer
    buffer.emplace_back(entryKey, entryValue);

    // Update size calculation: value size plus timestamp and size field sizes
    currentSize += entryValue.size() + sizeof(uint64_t) + sizeof(uint32_t);

    // Set timestamp if not already initialized
    if (currentTimestamp == 0) {
        currentTimestamp = getCurrentTimeStamp();  // Assuming a function getCurrentTimeStamp() returns the current timestamp.
    }

    // Sort the buffer entries by key in ascending order
    std::sort(buffer.begin(), buffer.end(), [](const std::pair<std::string, std::string>& firstItem, 
                                               const std::pair<std::string, std::string>& secondItem) {
        return firstItem.first < secondItem.first;
    });

    // Add all sorted key-value pairs to the most recently created SSTable
    for (const auto& entry : buffer) {
        tableLevels[levelIndex].back().addKeyValuePair(entry.first, entry.second);
    }

    // Finalize the SSTable with updated timestamp and size information
    tableLevels[levelIndex].back().updateMetadata(currentTimestamp, currentSize);
}

