void PointCloud::writePLY(std::string filePath, cv::Mat pointCloudData) {
    std::ofstream outputFile(filePath, std::ios::out | std::ios::binary);
    if (!outputFile.is_open()) {
        std::cerr << "Failed to open file for writing: " << filePath << std::endl;
        return;
    }

    int totalPoints = pointCloudData.rows;
    int channelCount = pointCloudData.cols;

    // Write PLY file header
    outputFile << "ply" << std::endl;
    outputFile << "format binary_little_endian 1.0" << std::endl;
    outputFile << "element vertex " << totalPoints << std::endl;
    outputFile << "property float x" << std::endl;
    outputFile << "property float y" << std::endl;
    outputFile << "property float z" << std::endl;
    outputFile << "end_header" << std::endl;

    // Write point cloud data in binary format
    for (int idx = 0; idx < totalPoints; idx++) {
        float xCoord = pointCloudData.at<float>(idx, 0);
        float yCoord = pointCloudData.at<float>(idx, 1);
        float zCoord = pointCloudData.at<float>(idx, 2);

        outputFile.write(reinterpret_cast<const char*>(&xCoord), sizeof(float));
        outputFile.write(reinterpret_cast<const char*>(&yCoord), sizeof(float));
        outputFile.write(reinterpret_cast<const char*>(&zCoord), sizeof(float));
    }

    outputFile.close();
}

