#include <vector>

// Helper function to get the next child node in a DIE tree traversal
TOptional<DwarfNode> NextChild() override
{
    Dwarf_Error error;
    int resultCode;

    // Attempt to get the first child of the current DIE
    if (dwarf_child(mCurrentDie, &mCurrentDie, &error) == DW_DLV_OK) {
        // Save the parent before descending
        mParentStack.push_back(mCurrentDie);
        return TOptional<DwarfNode>(mCurrentDie);
    }

    // Backtrack up the tree until we find a node with unvisited siblings
    while (!mParentStack.empty()) {
        Dwarf_Off currentOffset = dwarf_dieoffset(mCurrentDie);
        Dwarf_Off parentOffset  = dwarf_dieoffset(mParentStack.back());

        if (currentOffset == parentOffset) {
            // We've returned to the parent level
            mCurrentDie = mParentStack.back();
            mParentStack.pop_back();

            // Try to get the next sibling at this level
            if (dwarf_child(mCurrentDie, &mCurrentDie, &error) == DW_DLV_OK) {
                mParentStack.push_back(mCurrentDie);
                return TOptional<DwarfNode>(mCurrentDie);
            }
        } else {
            // Continue backtracking
            mParentStack.pop_back();
        }
    }

    // No more nodes available in the subtree
    return TOptional<DwarfNode>();
}

