// Compute the greatest common divisor using Euclidean method
int computeGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Compute the least common multiple using the GCD
int computeLCM(int a, int b) {
    return a * b / computeGCD(a, b);
}

int main() {
    // Demonstration with sample inputs
    std::cout << "GCD of 12 and 18: " << computeGCD(12, 18) << std::endl; // Expected: 6
    std::cout << "LCM of 12 and 18: " << computeLCM(12, 18) << std::endl; // Expected: 36
