#define CHECK_POINTER_NOT_NULL(ptr) \
    if (ptr == nullptr) { \
        throw std::invalid_argument("Null pointer detected"); \
    }

class PluginRegistry {
private:
    std::vector<std::string> pluginList;
    std::mutex mtx;
public:
    void registerPlugin(const std::string& name) {
        CHECK_POINTER_NOT_NULL(&name);
        std::lock_guard<std::mutex> guard(mtx);
        pluginList.push_back(name);
    }

    void unregisterPlugin(const std::string& name) {
        CHECK_POINTER_NOT_NULL(&name);
        std::lock_guard<std::mutex> guard(mtx);
        pluginList.erase(std::remove(pluginList.begin(), pluginList.end(), name), pluginList.end());
    }

    std::vector<std::string> listPlugins() {
        std::lock_guard<std::mutex> guard(mtx);
        return pluginList;
    }
};

int main() {
    PluginRegistry registry;

    // Register plugins
    registry.registerPlugin("Alpha");
    registry.registerPlugin("Beta");
    registry.registerPlugin("Gamma");

    // Display registered plugins
    std::vector<std::string> currentPlugins = registry.listPlugins();
    for (const auto& item : currentPlugins) {
        std::cout << "Loaded: " << item << std::endl;
    }

    // Unregister a plugin
    registry.unregisterPlugin("Beta");

    // Display plugins after removal
    currentPlugins = registry.listPlugins();
    for (const auto& item : currentPlugins) {
        std::cout << "Loaded: " << item << std::endl;
    }

    return 0;
}

