// Abstract interface for input/output operations
class io_handler_t {
public:
  virtual bool read() = 0;
  virtual bool write() = 0;
  virtual void setFilename(const std::string& path) = 0;
  virtual ~io_handler_t() {}
};

// Singleton factory pattern for IO handler creation
class io_factory_t {
public:
  static io_factory_t& get_instance() {
    static io_factory_t instance;
    return instance;
  }

  using creator_function_t = io_handler_t* (*)();

  bool register_handler(const std::string& name, creator_function_t creator) {
    return handlers_.insert({name, creator}).second;
  }

  io_handler_t* produce(const std::string& kind, const std::string& filepath) {
    auto iter = handlers_.find(kind);
    if (iter != handlers_.end()) {
      io_handler_t* handler = iter->second();
      handler->setFilename(filepath);
      return handler;
    }
    return nullptr;
  }

private:
  io_factory_t() = default;
  std::unordered_map<std::string, creator_function_t> handlers_;
};

// Concrete handler for CSV data files
