class PseudoRandomGenerator {
private:
    mt19937 generator;  // Mersenne Twister pseudo-random generator
    uniform_int_distribution<int> rangeDist;
public:
    PseudoRandomGenerator(int low, int high) 
        : generator(system_clock::now().time_since_epoch().count()), 
          rangeDist(low, high) {}

    int produce() {
        return rangeDist(generator);
    }

    void adjustRange(int newLow, int newHigh) {
        rangeDist = uniform_int_distribution<int>(newLow, newHigh);
    }
};

