// Compute the median of a vector of integers
double calculateMedian(std::vector<int>& values) {
    std::sort(values.begin(), values.end());  // Arrange elements in ascending order
    int size = values.size();
    if (size % 2 == 0) {
        // For even-sized vectors, return the average of the two central elements
        return (static_cast<double>(values[size / 2 - 1]) + static_cast<double>(values[size / 2])) / 2.0;
    } else {
        // For odd-sized vectors, return the middle element
        return static_cast<double>(values[size / 2]);
    }
}

#include <iostream>
#include <vector>

class TicTacToeGame {
private:
    std::vector<std::vector<char>> grid;
    char active_player;
public:
    TicTacToeGame() : grid(3, std::vector<char>(3, ' ')), active_player('X') {}

    void make_move(int pos) {
        int r = (pos - 1) / 3;
        int c = (pos - 1) % 3;
        if (grid[r][c] == ' ') {
            grid[r][c] = active_player;
            active_player = (active_player == 'X') ? 'O' : 'X';
        }
    }

    bool has_won(char player) {
        // Check rows
        for (int i = 0; i < 3; ++i) {
            if (grid[i][0] == player && grid[i][1] == player && grid[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < 3; ++j) {
            if (grid[0][j] == player && grid[1][j] == player && grid[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if ((grid[0][0] == player && grid[1][1] == player && grid[2][2] == player) ||
            (grid[0][2] == player && grid[1][1] == player && grid[2][0] == player)) {
            return true;
        }
        return false;
    }

    bool is_finished() {
        if (has_won('X') || has_won('O')) {
            return true;
        }
        for (int x = 0; x < 3; ++x) {
            for (int y = 0; y < 3; ++y) {
                if (grid[x][y] == ' ') {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
    TicTacToeGame* match = new TicTacToeGame();
    match->make_move(1);
