#include <iostream>

// Custom guarded action transition implementation
template <typename EventType, typename GuardPredicate, typename PerformAction>
class CustomGuardedTransition : public skizzay::fsm::guarded_action_transition<EventType> {
public:
    CustomGuardedTransition(EventType evt, GuardPredicate guard_pred, PerformAction perform_act)
        : skizzay::fsm::guarded_action_transition<EventType>(evt), 
          guard_pred_(guard_pred), 
          perform_act_(perform_act) {}

    bool check_guard() const {
        return guard_pred_();
    }

    void run_action() const {
        perform_act_();
    }

private:
    GuardPredicate guard_pred_;
    PerformAction perform_act_;
};

// Define states and events for the finite state machine
enum class MachineState { INITIAL, FINAL };
enum class Signal { ACTIVATE };

int main() {
    // Setup guard condition and action for the transition
    auto guard_predicate = []() { return true; };
    auto action_handler = []() { std::cout << "Action executed successfully" << std::endl; };

    // Instantiate the custom transition
    CustomGuardedTransition<Signal, decltype(guard_predicate), decltype(action_handler)> 
        my_transition(Signal::ACTIVATE, guard_predicate, action_handler);

    // Initialize the FSM with initial state
    skizzay::fsm::finite_state_machine<MachineState, Signal> machine(MachineState::INITIAL);

    // Add the transition to the FSM
    machine.add_transition(MachineState::INITIAL, Signal::ACTIVATE, MachineState::FINAL, my_transition);

    // Process the event to trigger the transition
    machine.process_event(Signal::ACTIVATE);

    return 0;
}

