class Projectile {
public:
    Projectile(Ogre::Entity* model, Ogre::SceneManager* manager);
    void tick(float elapsed);
    void exertForce(Ogre::Vector2 force);
    void checkBoundaryCollision(int windowWidth, int windowHeight);
private:
    Ogre::SceneNode* projectileNode;
    Ogre::Vector2 projectileSpeed;
    Ogre::Vector2 projectilePos;
};

Projectile::Projectile(Ogre::Entity* model, Ogre::SceneManager* manager) {
    // Initialize projectile
    // Position and scale setup
    projectileNode = manager->getRootSceneNode()->createChildSceneNode();
    projectileNode->setPosition(0, 20, 0); // center screen area
    projectileNode->setScale(0.1f, 0.1f, 0.1f);
    projectileNode->attachObject(model);

    // Initial velocity and position are zero
    projectileSpeed = Ogre::Vector2(0.0f, 0.0f);
    projectilePos = Ogre::Vector2(0.0f, 0.0f);
}

void Projectile::tick(float elapsed) {
    // Update projectile's coordinates using speed and time step
    projectilePos += projectileSpeed * elapsed;
    projectileNode->setPosition(projectilePos.x, 20, projectilePos.y); // Y is vertical axis
}

void Projectile::exertForce(Ogre::Vector2 force) {
    // Apply a force to modify the projectile's velocity
    projectileSpeed += force;
}

void Projectile::checkBoundaryCollision(int windowWidth, int windowHeight) {
    // Handle bouncing off screen edges
    if (projectilePos.x < 0 || projectilePos.x > windowWidth) {
        projectileSpeed.x *= -1; // invert horizontal velocity
    }
    if (projectilePos.y < 0 || projectilePos.y > windowHeight) {
        projectileSpeed.y *= -1; // invert vertical velocity
    }
}

