// Normalize the result of element-wise multiplication of two images to [0,1]
cv::Mat normalizeImage(cv::Mat input1, cv::Mat input2) {
    // Compute element-wise product of input1 and input2
    cv::Mat result = input1.mul(input2);

    // Determine the minimum and maximum intensity values in the result
    double minIntensity, maxIntensity;
    cv::minMaxLoc(result, &minIntensity, &maxIntensity);

    // Scale the pixel values to lie within [0, 1] using min-max normalization
    result = (result - minIntensity) / (maxIntensity - minIntensity);

    return result;
}

