// Device kernel applying odin_max element-wise
__global__ void deviceMaxDemo(int* inputA, int* inputB, int* output, int length) {
  int index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index < length) {
    output[index] = odin_max(inputA[index], inputB[index]);
  }
}

