  cudaMalloc((void**)&gpuArray2, numElements * sizeof(int));
  cudaMalloc((void**)&gpuOutput, numElements * sizeof(int));

  cudaMemcpy(gpuArray1, cpuArray1, numElements * sizeof(int), cudaMemcpyHostToDevice);
