class PerformanceMonitor {
private:
    static std::map<std::string, std::chrono::steady_clock::time_point> startTimeMap;
public:
    static void reset() {
        startTimeMap.clear();
    }

    static void beginMeasurement(const std::string& label) {
        startTimeMap[label] = std::chrono::steady_clock::now();
    }

    static void endMeasurement(const std::string& label) {
        auto it = startTimeMap.find(label);
        if (it != startTimeMap.end()) {
            auto finishTime = std::chrono::steady_clock::now();
            auto startTime = it->second;
            double duration = std::chrono::duration_cast<std::chrono::microseconds>(finishTime - startTime).count();
            std::cerr << "Duration for '" << label << "': " << duration << " µs\n";
            startTimeMap.erase(it);
        }
    }

    static double getCurrentDuration(const std::string& label) {
        auto it = startTimeMap.find(label);
        if (it != startTimeMap.end()) {
            auto currentTime = std::chrono::steady_clock::now();
            auto startTime = it->second;
            return std::chrono::duration_cast<std::chrono::microseconds>(currentTime - startTime).count();
        }
        return 0.0; // Return zero if measurement hasn't started or already completed
    }

    static void displayMetrics() {
        std::cerr << "Active Performance Metrics:\n";
        for (const auto& pair : startTimeMap) {
            std::cerr << "Label '" << pair.first << "': In Progress\n";
        }
    }
};

