class LoggingSystem {
public:
    LoggingSystem(const std::string& loggerName, const std::string& formatString) {
        logInstance_ = spdlog::stdout_color_mt(loggerName);
        logInstance_->set_pattern(formatString);
    }

    void enableConsoleOutput() {
        logInstance_->sinks().emplace_back(std::make_shared<spdlog::sinks::stdout_color_sink_mt>());
    }

    void enableFileOutput(const std::string& filePath) {
        logInstance_->sinks().emplace_back(std::make_shared<spdlog::sinks::basic_file_sink_mt>(filePath, true));
    }

    void write(Severity severity, const std::string& text) {
        switch (severity) {
            case Severity::Debug:
                logInstance_->debug(text);
                break;
            case Severity::Notice:
                logInstance_->info(text);
                break;
            case Severity::Critical:
                logInstance_->error(text);
                break;
        }
    }

private:
    std::shared_ptr<spdlog::logger> logInstance_;
};

int main() {
    LoggingSystem appLogger("ApplicationLogger", "[%Y-%m-%d %H:%M:%S] [%n] [%^%l%$] %v");
