// Binary operation template structure
template <typename T>
struct Operation {
  static T identity;  // Identity element for the binary operation
  // Apply the binary operation to two values
  static T apply(T a, T b) {
    // Define the binary operation logic here
    return a + b;  // Example: Addition operation
  }
};

// Initialize the identity element for the binary operation
template <typename T>
T Operation<T>::identity = 0;  // Example: Identity element for addition is 0

// Generic algorithm to process and transform data
template <typename ForwardIterator1, typename ForwardIterator2, typename Type1, typename Type2, typename Storage>
void computeAndMapData(ForwardIterator1 start1, ForwardIterator1 finish1, 
                       ForwardIterator2 start2, 
                       const Storage& offsets, 
                       const Storage& validIndices, 
                       const Storage& inputValues, 
                       Storage& outputValues) {
  for (; start1 != finish1; ++start1, ++start2) {
    auto result = Operation<Type1>::identity;
    for (const auto& offset : offsets) {
      auto position = *start1 + offset;
      if (validIndices.find(position) == validIndices.end()) {
        continue;
      }
      result = Operation<Type1>::apply(result, inputValues[position]);
    }
    outputValues[*start2] = static_cast<Type2>(result);
  }
}

#include <iostream>
#include <Eigen/Dense>

// Extract region of interest (ROI) data for a specific batch index
Eigen::MatrixXf get_batch_rois(int batch_id, Eigen::MatrixXf ground_truth, Eigen::MatrixXf proposals) {
    // Determine how many ground truth entries belong to the specified batch
    auto gt_count = (ground_truth.col(0).array() == static_cast<float>(batch_id)).count();

    // Allocate matrix for batch-specific ground truth boxes
    Eigen::MatrixXf batch_gt(gt_count, ground_truth.cols());
    for (Eigen::Index idx = 0, k = 0; idx < ground_truth.rows(); ++idx) {
        if (static_cast<int>(ground_truth(idx, 0)) == batch_id)
            batch_gt.row(k++) = ground_truth.row(idx);
    }

    // Determine how many proposals belong to the specified batch
    auto roi_count = (proposals.col(0).array() == static_cast<float>(batch_id)).count();

    // Allocate matrix for batch-specific ROIs (excluding the batch index column)
    Eigen::MatrixXf batch_proposals(roi_count, proposals.cols() - 1);
    for (Eigen::Index idx = 0, k = 0; idx < proposals.rows(); ++idx) {
        if (static_cast<int>(proposals(idx, 0)) == batch_id)
            batch_proposals.row(k++) = proposals.row(idx).rightCols(4);
    }

    return batch_proposals;
}

int main() {
    // Initialize sample ground truth boxes
    Eigen::MatrixXf ground_truth(5, 4);
    ground_truth << 1, 2, 3, 4,
                    2, 3, 4, 5,
                    1, 2, 3, 4,
                    2, 3, 4, 5,
                    3, 4, 5, 6;

    // Initialize sample region proposals with batch indices
    Eigen::MatrixXf proposals(8, 5);
    proposals << 1, 10, 20, 30, 40,
                 2, 15, 25, 35, 45,
                 1, 12, 22, 32, 42,
                 2, 17, 27, 37, 47,
                 3, 11, 21, 31, 41,
                 1, 14, 24, 34, 44,
                 2, 19, 29, 39, 49,
                 3, 16, 26, 36, 46;

    int target_batch = 2;
    Eigen::MatrixXf result = get_batch_rois(target_batch, ground_truth, proposals);

    std::cout << "ROIs for batch " << target_batch << ":\n" << result << std::endl;
    return 0;
}

