    std::vector<int> targetBuffer(3);  // Pre-sized buffer for copied elements
    int segmentIndex = 2;
    int blockSize = 3;

    processPerformance(sourceData, targetBuffer, segmentIndex, blockSize);

    // Output the contents of the target buffer after processing
    for (int value : targetBuffer) {
        std::cout << value << " ";
    }
