FileBrowserDialog *FileBrowserManager::openOrActivateDialog(const Account &account, const ServerRepo &repo) {
    // First, search through all active dialogs to see if one already exists
    for (size_t idx = 0; idx < activeDialogs.size(); ++idx) {
        FileBrowserDialog *existingDialog = activeDialogs[idx];
        if (existingDialog->getAccount() == account && existingDialog->getServerRepo() == repo) {
            // Bring the existing dialog to focus and return it
            existingDialog->activate();
            return existingDialog;
