// Function to render lighting data into camera buffers
void RenderLights(const std::vector<LightData>& lightList, std::vector<CameraConstantBuffer>& bufferList)
{
    for (const auto& currentLight : lightList)
    {
        if (currentLight.m_lightType == ELightType::Directional)
        {
            int targetIndex = currentLight.m_renderTargetOffset;
            CameraConstantBuffer tempBuffer;
            tempBuffer.m_viewProjection = currentLight.m_viewProjection;
            bufferList.push_back(tempBuffer);
        }
        else if (currentLight.m_lightType == ELightType::Point)
        {
            int faceCount = 6;
            // Process point light across six cubemap faces
            for (int faceIndex = 0; faceIndex < faceCount; ++faceIndex)
            {
                CameraConstantBuffer viewProjBuffer;
                // Compute view and projection matrices per cubemap face
                // Example: derive view matrix from light position and direction, then combine with projection
                Vector3 lightPos = currentLight.m_position;
                Vector3 directions[] = { Vector3(1, 0, 0), Vector3(-1, 0, 0), Vector3(0, 1, 0), Vector3(0, -1, 0), Vector3(0, 0, 1), Vector3(0, 0, -1) };
                Vector3 upVector = Vector3(0, 1, 0);
                Matrix viewMatrix = BuildViewMatrix(lightPos, lightPos + directions[faceIndex], upVector);
                Matrix projMatrix = BuildProjectionMatrixForFace(90.0f, 1.0f, 0.1f, 100.0f); // Standard parameters
                viewProjBuffer.m_viewProjection = viewMatrix * projMatrix;
                bufferList.push_back(viewProjBuffer);
            }
        }
    }
}

