// Helper function to find unique combinations that sum up to the target
void combinationSearchHelper(std::vector<int>& elements, int remaining, int index, 
                             std::vector<int>& path, std::vector<std::vector<int>>& allPaths) {
    if (remaining == 0) {
        allPaths.push_back(path);
        return;
    }

    for (int j = index; j < elements.size(); ++j) {
        // Skip duplicate values to avoid repeated combinations
        if (j > index && elements[j] == elements[j - 1]) continue;

        // Early termination if current element exceeds remaining target
        if (elements[j] > remaining) break;

        path.push_back(elements[j]);
        combinationSearchHelper(elements, remaining - elements[j], j + 1, path, allPaths);
        path.pop_back();
    }
}

// Main function to compute all unique combinations that sum to target
std::vector<std::vector<int>> computeUniqueCombinations(std::vector<int>& elements, int target) {
    std::sort(elements.begin(), elements.end());
    std::vector<std::vector<int>> solutions;
    std::vector<int> currentPath;
    combinationSearchHelper(elements, target, 0, currentPath, solutions);
    return solutions;
}

