#include <iostream>

// Helper function to check if two subtrees are mirror images of each other
bool areSubtreesMirrored(TreeNode* leftNode, TreeNode* rightNode) {
    // Both nodes are null - symmetric case
    if (leftNode == nullptr && rightNode == nullptr) {
        return true;
    }

    // One node is null but not the other - asymmetric case
    if (leftNode == nullptr || rightNode == nullptr) {
        return false;
    }

    // Values don't match - not symmetric
    if (leftNode->val != rightNode->val) {
        return false;
    }

    // Recursively check: left's left with right's right AND left's right with right's left
    return areSubtreesMirrored(leftNode->left, rightNode->right) && 
           areSubtreesMirrored(leftNode->right, rightNode->left);
}

// Main function to determine if the entire tree is symmetric
bool checkSymmetry(TreeNode* treeRoot) {
    // An empty tree is considered symmetric
    if (treeRoot == nullptr) {
        return true;
    }

    // Check if left and right subtrees are mirrors of each other
    return areSubtreesMirrored(treeRoot->left, treeRoot->right);
}

