// Computes the memory footprint of a specified process
SIZE_T GetProcessMemoryConsumption(DWORD procId) {
    HANDLE hProc = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, procId);
    if (hProc == NULL) {
        // Error occurred while attempting to open the process
        return 0;
    }
    PROCESS_MEMORY_COUNTERS memCounters;
    if (GetProcessMemoryInfo(hProc, &memCounters, sizeof(memCounters))) {
        CloseHandle(hProc);
        return memCounters.WorkingSetSize;
    } else {
        // Failed to retrieve memory information for the process
        CloseHandle(hProc);
        return 0;
    }
}

