// Compute the squared distance between a moving segment and triangle at time t
template <typename Real>
Real ComputeSquaredSeparation(const Triangle3<Real>* tri, Real time, const Vector3<Real>& vel1, const Segment3<Real>* seg) {
    // Update triangle vertices based on motion
    Vector3<Real> v0 = tri->V[0] + time * vel1;
    Vector3<Real> v1 = tri->V[1] + time * vel1;
    Vector3<Real> v2 = tri->V[2] + time * vel1;

    // Construct transformed geometric objects
    Segment3<Real> movedSeg(seg->Center + time * seg->Direction, seg->Direction, seg->Extent);
    Triangle3<Real> movedTri(v0, v1, v2);

    // Evaluate minimal squared separation
    return DistSegment3Triangle3<Real>(movedSeg, movedTri).GetSquared();
}

