#include <queue>
#include <mutex>
#include <condition_variable>

template <typename DataType>
class ConcurrentQueue {
public:
    void add(const DataType& item) {
        std::unique_lock<std::mutex> guard(mtx_);
        data_.push(item);
        guard.unlock();
        cv_.notify_one();
    }

    bool retrieve(DataType& result) {
        std::unique_lock<std::mutex> guard(mtx_);
        cv_.wait(guard, [this] { return !data_.empty(); });
        if (data_.empty()) {
            return false;
        }
        result = data_.front();
        data_.pop();
        return true;
    }

    bool is_empty() const {
        std::lock_guard<std::mutex> guard(mtx_);
        return data_.empty();
    }

private:
    std::queue<DataType> data_;
    mutable std::mutex mtx_;
    std::condition_variable cv_;
};

