// Token class representing numerical values or operators
class Token {
public:
    using SmartPtr = std::shared_ptr<Token>;
    virtual ~Token() = default;
};

// Numerical token class derived from Token
class NumToken : public Token {
public:
    double data;
    NumToken(double val) : data(val) {}
};

// Function to convert a token to a numerical value
double convert_to_double(Token::SmartPtr tok) {
    return static_cast<NumToken*>(tok.get())->data;
}

// Function to perform addition operation on input tokens
Token::SmartPtr perform_addition(const std::vector<Token::SmartPtr> &operands) {
    double accumulator = 0;
    for (const auto &token : operands) {
        accumulator += convert_to_double(token);
    }
    return std::make_shared<NumToken>(accumulator);
}

// Function to perform subtraction operation on input tokens
Token::SmartPtr perform_subtraction(const std::vector<Token::SmartPtr> &operands) {
    double difference = convert_to_double(operands[0]);
    for (size_t idx = 1; idx < operands.size(); ++idx) {
        difference -= convert_to_double(operands[idx]);
    }
    return std::make_shared<NumToken>(difference);
}

// Function to evaluate the expression and return the final result
double compute_result(const std::vector<Token::SmartPtr> &expr_tokens) {
    // Logic to process the tokens and apply operations in correct order
    // Example: handle operator precedence, parentheses, etc.
