class MortonHashTable {
private:
    size_t itemCount; // Current number of stored entries
public:
    // Constructor and other methods are not shown for brevity
    size_t MemoryFootprint() const
    {
        // Estimate memory usage in bytes considering bucket structure and fingerprint storage
        // Morton3_8 layout: 3 slots per bucket, 8-bit fingerprints → 11.7 bits per entry at 0.95 load
        double bitsPerEntry = 11.7;
        double occupancyRate = 0.95;
        double requiredBits = itemCount * bitsPerEntry / occupancyRate;
        size_t byteCount = static_cast<size_t>(std::ceil(requiredBits / 8.0));
        return byteCount;
    }
};

