// Macro for structured error logging
#define LOG_ERROR_MSG(logger, text, qid, errcode) do { \
    std::ostringstream oss; \
    oss << text; \
    std::string formatted = oss.str(); \
    size_t pos_qid = formatted.find("query_id={}"); \
    if (pos_qid != std::string::npos) { \
        formatted.replace(pos_qid, 13, "query_id=" + std::to_string(qid)); \
    } \
    size_t pos_err = formatted.find("error={}"); \
    if (pos_err != std::string::npos) { \
        formatted.replace(pos_err, 9, "error=" + std::to_string(errcode)); \
    } \
    logger.recordError(formatted); \
} while(0)

// Custom exception type
class RuntimeError {
public:
    RuntimeError(const std::string& desc, int code) {
        std::ostringstream stream;
        stream << desc;
        std::string message = stream.str();
        size_t idx = message.find("error={}");
        if (idx != std::string::npos) {
            message.replace(idx, 8, "error=" + std::to_string(code));
        }
        throw std::runtime_error(message);
    }
};

