#include <fcppt/math/matrix/comparison.hpp>

template <typename Value, fcppt::math::size_type Rows, fcppt::math::size_type Columns>
bool matrix_equality_check(
    fcppt::math::matrix::object<Value, Rows, Columns> const &first_matrix,
    fcppt::math::matrix::object<Value, Rows, Columns> const &second_matrix,
    fcppt::math::matrix::object<Value, Rows, Columns> const &expected)
{
    auto const computed = fcppt::math::matrix::binary_map(
        first_matrix,
        second_matrix,
        [](Value const &lhs, Value const &rhs) { return lhs + rhs; });
    return fcppt::math::matrix::comparison(computed, expected);
}

