#include <functional>
#include <unordered_map>

class BaseTimer {
public:
    virtual ~BaseTimer() {}
    virtual void scheduleTimer(int delay, std::function<void()> handler) = 0;
    virtual void tick(int steps) = 0;
    virtual std::vector<std::function<void()>> retrieveReadyCallbacks() = 0;
};

class HierarchicalWheelTimer : public BaseTimer {
private:
    // Storage for timers organized by wheel positions
    std::vector<std::unordered_map<int, std::function<void()>>> timerWheel;
    int currentPosition;
public:
    HierarchicalWheelTimer() : timerWheel(5), currentPosition(0) {}

    void scheduleTimer(int delay, std::function<void()> handler) override {
        int index = (currentPosition + delay) % timerWheel.size();
        timerWheel[index][delay] = handler;
    }

    void tick(int steps) override {
        currentPosition = (currentPosition + steps) % timerWheel.size();
    }

    std::vector<std::function<void()>> retrieveReadyCallbacks() override {
        std::vector<std::function<void()>> readyCallbacks;
        for (const auto& entry : timerWheel[currentPosition]) {
            readyCallbacks.push_back(entry.second);
        }
        timerWheel[currentPosition].clear();
        return readyCallbacks;
    }
};

