#include <Eigen/Dense>
#include <stdexcept>

Eigen::MatrixXd matrixElementProduct(const Eigen::MatrixXd& matrix1, const Eigen::MatrixXd& matrix2) {
    if ((matrix1.rows() == matrix2.rows()) && (matrix1.cols() == matrix2.cols())) {
        // Scenario A: Identical matrix sizes
        return (matrix1.array() * matrix2.array());
    } else if ((matrix1.rows() == 1) && (matrix1.cols() == matrix2.cols())) {
        // Scenario B: Broadcast row vector from first matrix
        Eigen::Map<Eigen::RowVectorXd> rowVec1(matrix1.data(), matrix1.cols());
        return (matrix2.array().rowwise() * rowVec1.array());
    } else if ((matrix2.rows() == 1) && (matrix1.cols() == matrix2.cols())) {
        // Scenario C: Broadcast row vector from second matrix
        Eigen::Map<Eigen::RowVectorXd> rowVec2(matrix2.data(), matrix2.cols());
        return (matrix1.array().rowwise() * rowVec2.array());
    } else {
        // Error case: incompatible dimensions
        throw std::runtime_error("Dimension mismatch for element-wise multiplication");
    }
}

