#include <algorithm>
#include <iostream>

// Count maximum number of elements from two arrays whose sum is less than or equal to limit
int countMaxPairsUnderThreshold(int nSize, int mSize, int limit, int arr1[], int arr2[]) {
    // Sort both arrays in descending order
    std::sort(arr1, arr1 + nSize, std::greater<int>());
    std::sort(arr2, arr2 + mSize, std::greater<int>());

    int elementCount = 0;
    int currentSum = 0;
    int idxA = 0, idxB = 0;

    // Process pairs first
    while (idxA < nSize && idxB < mSize) {
        if (arr1[idxA] + arr2[idxB] <= limit) {
            currentSum = currentSum + arr1[idxA] + arr2[idxB];
            idxA++;
            idxB++;
            elementCount = elementCount + 2;
        } else if (arr1[idxA] <= limit) {
            currentSum = currentSum + arr1[idxA];
            idxA++;
            elementCount++;
        } else if (arr2[idxB] <= limit) {
            currentSum = currentSum + arr2[idxB];
            idxB++;
            elementCount++;
        } else {
            break;
        }

        if (currentSum > limit) {
            elementCount--;
            break;
        }
    }

    // Process remaining elements from first array
    while (idxA < nSize && arr1[idxA] <= limit) {
        currentSum = currentSum + arr1[idxA];
        idxA++;
        elementCount++;
        if (currentSum > limit) {
            elementCount--;
            break;
        }
    }

    // Process remaining elements from second array
    while (idxB < mSize && arr2[idxB] <= limit) {
        currentSum = currentSum + arr2[idxB];
        idxB++;
        elementCount++;
        if (currentSum > limit) {
            elementCount--;
            break;
        }
    }

    return elementCount;
}

