template <typename RegistryType>
class FilePath {
public:
    FilePath() = default;
    FilePath(const std::string& segment, const FilePath& parent) : segment_(segment), parent_(&parent) {}

    bool isUnique() const {
        if (parent_ == nullptr) {
            return true;  // Root path is always unique
        }
        const auto& existingPaths = parent_->getExistingPaths();
        return existingPaths.find(segment_) == existingPaths.end();
    }

    void display() const {
        if (parent_ != nullptr) {
            parent_->display();
            std::cout << "/" << segment_;
        } else {
            std::cout << "/" << segment_;
        }
    }

private:
    std::string segment_;
    const FilePath* parent_ = nullptr;

    const RegistryType& getExistingPaths() const {
        return RegistryType::getInstance();
    }
};

template <typename T>
class PathRegistry {
public:
    static const PathRegistry& getInstance() {
        static PathRegistry instance;
        return instance;
    }
    std::unordered_set<std::string> existingPaths;
private:
    PathRegistry() = default;
};

