#include <iostream>
#include <thread>
#include <vector>

// Define the thread function signature
typedef void (*ThreadRoutine)(void*);

// Structure to hold thread parameters
struct ThreadData {
    std::thread* activeThread;
    ThreadRoutine handler;
    void* data;
};

// Class to manage threads
class ThreadPoolController {
public:
    // Create a new thread with the specified function
    void spawnThread(ThreadRoutine handler, void* data) {
        ThreadData threadInfo;
        threadInfo.handler = handler;
        threadInfo.data = data;
        threadList.push_back(threadInfo);
    }

    // Start the execution of the created thread
    void launchThread() {
        if (!threadList.empty()) {
            ThreadData& threadInfo = threadList.back();
            threadInfo.activeThread = new std::thread(&ThreadPoolController::runThread, this, &threadInfo);
        }
    }

    // Wait for the thread to finish its execution
    void waitForThread() {
        if (!threadList.empty()) {
            ThreadData& threadInfo = threadList.back();
            if (threadInfo.activeThread->joinable()) {
                threadInfo.activeThread->join();
            }
            delete threadInfo.activeThread;
            threadList.pop_back();
        }
    }

private:
    std::vector<ThreadData> threadList;

    // Function to execute the thread
    void runThread(ThreadData* threadInfo) {
        threadInfo->handler(threadInfo->data);
    }
};

// Example function to be executed by the thread
void sampleFunction(void* param) {
    int* number = static_cast<int*>(param);
    std::cout << "Worker thread running with value: " << *number << std::endl;
}

int main() {
    ThreadPoolController controller;
    int inputValue = 42;
    controller.spawnThread(sampleFunction, &inputValue);
    controller.launchThread();
    controller.waitForThread();
    return 0;
}

