class SimpleStringView {
public:
    // Constructors
    constexpr SimpleStringView() noexcept : ptr_(nullptr), length_(0) {}
    constexpr SimpleStringView(const char* str) noexcept : ptr_(str), length_(std::strlen(str)) {}
    constexpr SimpleStringView(const char* str, size_t len) noexcept : ptr_(str), length_(len) {}

    // Accessors
    constexpr const char* get_data() const noexcept { return ptr_; }
    constexpr size_t get_length() const noexcept { return length_; }

    // Element access
    constexpr char at(size_t index) const { return ptr_[index]; }

    // Comparison
    constexpr bool equals(SimpleStringView other) const noexcept {
        return length_ == other.length_ && std::strncmp(ptr_, other.ptr_, length_) == 0;
    }

    // Substring extraction
    constexpr SimpleStringView substring(size_t start, size_t count = max_size) const {
        if (start > length_) start = length_;
        if (count > length_ - start) count = length_ - start;
        return SimpleStringView(ptr_ + start, count);
    }

    // Character search
    constexpr size_t find_char(char ch, size_t start = 0) const noexcept {
        if (start >= length_) return max_size;
        const char* found = std::strchr(ptr_ + start, ch);
        return found ? static_cast<size_t>(found - ptr_) : max_size;
    }

    static constexpr size_t max_size = static_cast<size_t>(-1);

private:
    const char* ptr_;
    size_t length_;
};

