class FrequencyChartWidget : public QWidget {
public:
  void displayHistogram(const std::vector<int>& dataValues) {
    // Compute frequency distribution from input data
    std::vector<int> freqData(10, 0);  // Use 10 categories as default
    // Fill frequency bins according to input values
    for (int val : dataValues) {
      if (val >= 0 && val < 10) {
        freqData[val]++;
      }
    }
    // Find highest count for proper scaling of bars
    int peakCount = *std::max_element(freqData.begin(), freqData.end());
    // Set up layout parameters for drawing the chart
    int columnWidth = width() / freqData.size();
    int gapSize = 2;
    int leftPos = 0;
    // Prepare painter for rendering
    QPainter renderer(this);
    renderer.setBrush(Qt::darkGreen);  // Choose color for histogram columns
    for (int count : freqData) {
      int colHeight = static_cast<int>(static_cast<double>(count) / peakCount * height());
      renderer.drawRect(leftPos, height() - colHeight, columnWidth - gapSize, colHeight);
      leftPos += columnWidth;
    }
  }
