#include <google/protobuf/io/coded_stream.h>

::google::protobuf::uint8* DiscardRequest::SerializeWithCachedSizesToArray(
    ::google::protobuf::uint8* output_buffer) const {
  // Serialize the 'message' field (field number 1)
  if (has_message()) {
    // Calculate the size of the message string
    const int msg_size = message().length();

    // Encode the field header: field 1 with wire type 2 (length-delimited)
    *output_buffer++ = 0x0A;  // tag byte for field 1, wire format 2

    // Encode the length using varint encoding
    output_buffer = ::google::protobuf::io::CodedOutputStream::WriteVarint32ToArray(
        msg_size, output_buffer);

    // Copy the actual string content to the buffer
    output_buffer = ::google::protobuf::io::CodedOutputStream::WriteStringToArray(
        message(), output_buffer);
  }
  return output_buffer;
}

