// Custom memory management system for tracking allocations
class MemoryManager {
private:
    std::map<void*, size_t> allocationTable; // Stores pointer-to-size mappings

public:
    // Reserve raw memory block of specified size
    void* reserveMemory(size_t bytes) {
        void* address = new char[bytes];
        allocationTable[address] = bytes;
        return address;
    }

    // Release previously reserved memory block
    void releaseMemory(void* address) {
        auto it = allocationTable.find(address);
        if (it != allocationTable.end()) {
            delete[] static_cast<char*>(address);
            allocationTable.erase(it);
        }
    }

    // Create and allocate a single object of type T
    template <typename T>
    T* createObject() {
        return new T();
    }

    // Destroy and deallocate a single object of type T
    template <typename T>
    void destroyObject(T* obj) {
        delete obj;
    }

    // Cleanup all tracked allocations on destruction
    ~MemoryManager() {
        for (const auto& entry : allocationTable) {
            delete[] static_cast<char*>(entry.first);
        }
        allocationTable.clear();
    }
};

int main() {
    MemoryManager manager;

    // Allocate space for an instance of UserClass
    UserClass* userInstance = static_cast<UserClass*>(manager.reserveMemory(sizeof(UserClass)));

    // Create a standalone pointer to UserClass
    UserClass* userPtr = manager.createObject<UserClass>();

    // Allocate space for an instance of DataStruct
    DataStruct* dataInstance = static_cast<DataStruct*>(manager.reserveMemory(sizeof(DataStruct)));

    // Create a standalone pointer to DataStruct
    DataStruct* dataPtr = manager.createObject<DataStruct>();

    // Clean up all allocated resources
    manager.releaseMemory(userInstance);
    manager.destroyObject(userPtr);
    manager.releaseMemory(dataInstance);
    manager.destroyObject(dataPtr);

    return 0;
}

