        case Direction::LEFT:
            if (posX > 0) {
                nextX = posX - 1;  // Move leftward within grid bounds
            }
            break;
        case Direction::RIGHT:
            if (posX < MAX_COLS - 1) {
                nextX = posX + 1;  // Move rightward within grid bounds
            }
            break;
    }

    // Apply new position only if it differs from current location
    if (nextX != posX || nextY != posY) {
        posX = nextX;
        posY = nextY;
    }
}

