double computeTetrahedronVolume(const Coordinate3D& p1, const Coordinate3D& p2, const Coordinate3D& p3, const Coordinate3D& p4) {
  double result = std::abs((1.0 / 6.0) * ((p2.a - p1.a) * ((p3.b - p1.b) * (p4.c - p1.c) - (p3.c - p1.c) * (p4.b - p1.b)) +
                                           (p2.b - p1.b) * ((p3.c - p1.c) * (p4.a - p1.a) - (p3.a - p1.a) * (p4.c - p1.c)) +
                                           (p2.c - p1.c) * ((p3.a - p1.a) * (p4.b - p1.b) - (p3.b - p1.b) * (p4.a - p1.a))));
  return result;
}

