// Perform network stress test by establishing multiple TCP connections and sending packets
void networkStressTest(const std::string& targetHost, int serverPort, size_t connectionCount, size_t bufferSize) {
    std::cout << "Initiating connection stress test with " << connectionCount << " sockets..." << std::endl;

    std::vector<acl::CoreSocket::SOCKET> socketList;

    // Establish connections
    for (size_t index = 0; index < connectionCount; ++index) {
        acl::CoreSocket::SOCKET currentSocket;

        if (!connect_tcp_to(targetHost.c_str(), serverPort, nullptr, &currentSocket)) {
            std::cerr << "Failed to establish connection on socket " << index << std::endl;

            // Cleanup previously opened sockets
            for (auto& existingSocket : socketList) {
                close_socket(existingSocket);
            }
            return;
        }

        if (!set_tcp_socket_options(currentSocket)) {
            std::cerr << "Failed to configure TCP options for socket " << index << std::endl;

            // Cleanup all opened sockets
            for (auto& existingSocket : socketList) {
                close_socket(existingSocket);
            }
            close_socket(currentSocket);
            return;
        }

        socketList.push_back(currentSocket);
    }

    // Transmit data through each established connection
    for (auto& sock : socketList) {
        char* dataBuffer = new char[bufferSize];

        // Initialize buffer with test data
        // ...

        if (send(sock, dataBuffer, bufferSize, 0) != static_cast<int>(bufferSize)) {
            std::cerr << "Transmission error on socket " << sock << std::endl;
            // Continue with remaining sockets despite error
        }

        delete[] dataBuffer;
    }

    // Terminate all connections
    for (auto& sock : socketList) {
        close_socket(sock);
    }
}

