template <typename KeyT, typename ValueT>
class ContainerWithHandles {
public:
    using KeyType = KeyT;
    using ValueType = ValueT;
private:
    std::unordered_map<KeyType, ValueType> storage;
public:
    // Inserts a new element and returns its associated handle
    KeyType insert(const ValueType& value) {
        static KeyType currentId = 0;  // Assuming KeyT supports increment operations
        storage[currentId] = value;
        return currentId++;
    }

    // Accesses the element identified by the provided handle
    ValueType fetch(const KeyType& id) const {
        auto iter = storage.find(id);
        if (iter != storage.end()) {
            return iter->second;
        } else {
            // Specified handle does not exist in the container
            throw std::out_of_range("Invalid handle");
        }
    }

    // Deletes the entry corresponding to the given handle
    void eraseEntry(const KeyType& id) {
        storage.erase(id);
    }
};

