namespace eosio {
  class [[eosio::contract("wlist.token")]] token : public contract {
  public:
    using contract::contract;

    // Structure representing an account with owner and balance
    struct [[eosio::table]] user_account {
      name owner;
      uint64_t balance;
      uint64_t primary_key() const { return owner.value; }
    };

    typedef multi_index<"accounts"_n, user_account> account_table;

    // Contract constructor
    token(name receiver, name code, datastream<const char *> ds)
        : contract(receiver, code, ds) {}

    // Action to move tokens between accounts
    [[eosio::action]]
    void transfer(name sender, name recipient, uint64_t amount) {
      require_auth(sender);

      account_table sender_accounts(get_self(), sender.value);
      auto sender_itr = sender_accounts.find(sender.value);
      eosio_assert(sender_itr != sender_accounts.end(), "Sender account does not exist");
      eosio_assert(sender_itr->balance >= amount, "Insufficient balance");

      account_table recipient_accounts(get_self(), recipient.value);
      auto recipient_itr = recipient_accounts.find(recipient.value);

      if (recipient_itr == recipient_accounts.end()) {
        recipient_accounts.emplace(sender, [&](auto &acc) {
          acc.owner = recipient;
          acc.balance = amount;
        });
      } else {
        recipient_accounts.modify(recipient_itr, same_payer, [&](auto &acc) {
          acc.balance += amount;
        });
      }

      sender_accounts.modify(sender_itr, same_payer, [&](auto &acc) {
        acc.balance -= amount;
      });
    }

    // Action to retrieve the balance of a given account
    [[eosio::action]]
    uint64_t get_balance(name account_owner) {
      account_table accounts(get_self(), account_owner.value);
      auto itr = accounts.find(account_owner.value);
      eosio_assert(itr != accounts.end(), "Account does not exist");
      return itr->balance;
    }
  };
}  // namespace eosio

