enum class SeverityLevel { TRACE, NOTICE, CRITICAL, VERBOSE };

class LoggingSystem {
public:
    void notice(const std::string& msg) {
        record(SeverityLevel::NOTICE, msg);
    }

    void notice(const std::string& msg) {
        record(SeverityLevel::NOTICE, msg);
    }

    void critical(const std::string& msg) {
        record(SeverityLevel::CRITICAL, msg);
    }

    void trace(const std::string& msg) {
        record(SeverityLevel::TRACE, msg);
    }

    void verify(bool expr, const std::string& description) {
        if (!expr) {
            critical("Verification failed: " + description);
            haltExecution();
        }
    }

    void setOutputTarget(std::ostream& target) {
        destination_ = &target;
    }

private:
    std::ostream* destination_ = &std::cout;

    void record(SeverityLevel level, const std::string& msg) {
        std::string severityString;
        switch (level) {
            case SeverityLevel::TRACE:
                severityString = "TRACE";
                break;
            case SeverityLevel::NOTICE:
                severityString = "NOTICE";
                break;
            case SeverityLevel::CRITICAL:
                severityString = "CRITICAL";
                break;
            case SeverityLevel::VERBOSE:
                severityString = "VERBOSE";
                break;
        }
        (*destination_) << "[" << severityString << "] " << msg << std::endl;
    }

    void haltExecution() {
        throw std::runtime_error("Execution stopped due to verification failure");
    }
};

int main() {
    LoggingSystem logger;
    logger.critical("A critical issue has been detected");
    logger.trace("Trace-level diagnostic data");
    logger.setOutputTarget(std::cerr);
    logger.notice("This is a notice message");
    logger.verify(3 * 3 == 10, "Arithmetic check");
    logger.notice("This line should not appear in output");
    return 0;
}

