// Function to compute the maximum weight after connecting ropes with given conditions
int computeMaxWeight(int weights[], int count, int initial) {
    std::sort(weights, weights + count); // Sort the rope weights in ascending order
    int computed[count]; // Array to hold transformed weights

    // Process from largest to smallest original weight
    for (int index = count - 1; index >= 0; index--) {
        computed[index] = weights[index] * initial; // Multiply weight by current multiplier
        initial++; // Increment multiplier for next iteration
    }

    std::sort(computed, computed + count); // Sort the transformed values
    int maxValue = computed[count - 1]; // The last element is the maximum after sorting
    return maxValue;
}

int main() {
    int weights[] = {4, 3, 2, 6};
    int count = 4;
    int initial = 1;

    std::cout << computeMaxWeight(weights, count, initial) << std::endl; // Output: 29
    return 0;
}

