namespace rw {
    namespace math {
        template <typename T>
        class Quaternion {
        public:
            T real, imagX, imagY, imagZ;

            Quaternion(T w, T x, T y, T z) 
                : real(w), imagX(x), imagY(y), imagZ(z) {}

            Quaternion<T> getConjugate() const {
                return Quaternion<T>(real, -imagX, -imagY, -imagZ);
            }

            Quaternion<T> multiply(const Quaternion<T>& rhs) const {
                T resReal = real * rhs.real - imagX * rhs.imagX - imagY * rhs.imagY - imagZ * rhs.imagZ;
                T resImagX = real * rhs.imagX + imagX * rhs.real + imagY * rhs.imagZ - imagZ * rhs.imagY;
                T resImagY = real * rhs.imagY - imagX * rhs.imagZ + imagY * rhs.real + imagZ * rhs.imagX;
                T resImagZ = real * rhs.imagZ + imagX * rhs.imagY - imagY * rhs.imagX + imagZ * rhs.real;
                return Quaternion<T>(resReal, resImagX, resImagY, resImagZ);
            }

            void normalizeQuaternion() {
                T norm = std::sqrt(real * real + imagX * imagX + imagY * imagY + imagZ * imagZ);
                if (norm != static_cast<T>(0)) {
                    real /= norm;
                    imagX /= norm;
                    imagY /= norm;
                    imagZ /= norm;
                }
            }
        };
    } // namespace math
} // namespace rw

