class GridPaths {
private:
    vector<string> matrix;
    int result;

    void explore(int row, int col, int moveRight, int moveDown) {
        // Check if we reached the bottom-right corner
        if (row == matrix.size() - 1 && col == matrix[0].size() - 1) {
            result++;
            return;
        }

        // Move right if possible
        if (moveRight < matrix.size() - 1) {
            explore(row, col + 1, moveRight + 1, moveDown);
        }

        // Move down if possible
        if (moveDown < matrix[0].size() - 1) {
            explore(row + 1, col, moveRight, moveDown + 1);
        }
    }

public:
    int countPaths(int n) {
        matrix.clear();
        string rowPattern;
        rowPattern.push_back('.');

        // Create n rows with single dot each
        for (int index = 0; index < n; index++) {
            matrix.push_back(rowPattern);
        }

        result = 0;
        explore(0, 0, 0, 0);
        return result;
    }
};

