#include <iostream>

// Evaluate accuracy of normal derivative computation using finite differences
void test_normal_derivative_accuracy(double step_size, BicubicPatch* surface_patch, Vector3 reference_normal, int tolerance, Vector3 computed_full_derivative) {
    // Preserve current state before introducing perturbation
    double saved_f = surface_patch->n01->f;
    Vector3 saved_dx = surface_patch->n01->dx;

    // Apply small perturbation to parameter and compute perturbed normal
    surface_patch->n01->f += step_size;
    Vector3 new_normal = surface_patch->calculateNormal();

    // Approximate derivative using forward difference
    Vector3 finite_diff_deriv = (new_normal - reference_normal) / step_size;

    // Restore original f value to maintain patch integrity
    surface_patch->n01->f = saved_f;

    // Determine deviation between numerical approximation and exact derivative
    double discrepancy = (finite_diff_deriv - computed_full_derivative).length();

    // Report comparison outcome based on tolerance threshold
    if (discrepancy < tolerance) {
        std::cout << "Derivative validation successful, residual: " << discrepancy << std::endl;
    } else {
        std::cout << "Derivative validation failed, residual: " << discrepancy << std::endl;
    }

    // Final restoration of dx component
    surface_patch->n01->dx = saved_dx;
}

