using namespace std;

const int MAX_NODES = 1005; // Maximum number of nodes in the graph
int adjMatrix[MAX_NODES][MAX_NODES]; // Adjacency matrix for the graph
int inDegree[MAX_NODES];             // Array to track incoming edges count for each node
int numNodes;                        // Total number of nodes in the graph

// Perform topological sort using Kahn's algorithm
int performTopoSort() {
    vector<int> topoOrder; // Stores the resulting topological sequence
    queue<int> processQueue; // Queue for BFS processing

    // Initialize queue with all nodes having zero in-degree
    for (int node = 0; node < numNodes; node++) {
        if (inDegree[node] == 0) {
            processQueue.push(node);
        }
    }

    // Process nodes in BFS manner
    while (!processQueue.empty()) {
        int currentNode = processQueue.front();
        processQueue.pop();
        topoOrder.push_back(currentNode); // Add current node to result

        // Update neighbors' in-degrees
        for (int neighbor = 0; neighbor < numNodes; neighbor++) {
            if (adjMatrix[currentNode][neighbor] > 0) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) {
                    processQueue.push(neighbor);
                }
            }
        }
    }

    // Check if all nodes were processed (no cycle)
    if (topoOrder.size() != numNodes) {
        return -1; // Cycle detected, topological sort not possible
    } else {
        return topoOrder.size(); // Return count of sorted nodes
    }
}

int main() {
    // Read graph data and initialize in-degrees
    // ...

    int outcome = performTopoSort();
    if (outcome == -1) {
        cout << "Impossible\n";
    } else {
        cout << outcome << '\n';
    }

    return 0;
}

