#include <QTcpSocket>
#include <QByteArray>
#include <QDebug>

void Server::incomingMessage()
{
    // Acquire data from the incoming network packet
    QByteArray data = socket->readAll();

    // Process each connected client to forward the received data
    for (int idx = 0; idx < clients.size(); ++idx) {
        QTcpSocket *targetSocket = clients[idx];

        // Skip the original sender to avoid echoing back
        if (targetSocket != socket) {
            qint64 writtenBytes = targetSocket->write(data);
            if (writtenBytes < 0) {
                // Log write failure for diagnostic purposes
                qDebug() << "Failed to transmit data to client";
            }
        }
    }

    // Verify connection status after message handling
    if (socket->state() == QAbstractSocket::UnconnectedState) {
        // Clean up disconnected client resources
        clients.removeAll(socket);
        socket->deleteLater();
    }
}

