using namespace std;

class MinStack {
private:
    stack<int> dataStack;
    stack<int> auxStack;
public:
    void push(int value) {
        // Insert element into primary stack
        dataStack.push(value);

        // Maintain auxiliary stack for minimum tracking
        if (auxStack.empty() || value <= auxStack.top()) {
            auxStack.push(value);
        }
    }

    void removeTop() {
        // Delete top element from primary stack
        if (dataStack.top() == auxStack.top()) {
            auxStack.pop();
        }
        dataStack.pop();
    }

    int peek() {
        return dataStack.top();
    }

    bool isEmpty() {
        return dataStack.empty();
    }

    int findMin() {
        return auxStack.top();
    }
};

