// Function to compute the m/z values for y-type fragment ions
void computeYFragmentMZs(const std::string& proteinPeptide, std::vector<double>& mzValues) {
    // Define monoisotopic masses for standard amino acids
    std::unordered_map<char, double> residueMasses = {
        {'A', 71.03711},
        {'R', 156.10111},
        {'N', 114.04293},
        {'D', 115.02694},
        {'C', 103.00919},
        {'E', 129.04259},
        {'Q', 128.05858},
        {'G', 57.02146},
        {'H', 137.05891},
        {'I', 113.08406},
        {'L', 113.08406},
        {'K', 128.09496},
        {'M', 131.04049},
        {'F', 147.06841},
        {'P', 97.05276},
        {'S', 87.03203},
        {'T', 101.04768},
        {'W', 186.07931},
        {'Y', 163.06333},
        {'V', 99.06841}
    };

    // Accumulate mass from N-terminus and compute m/z for each y-ion
    double cumulativeMass = 0.0;
    for (int idx = 1; idx < proteinPeptide.size(); ++idx) {
        cumulativeMass += residueMasses[proteinPeptide[idx - 1]];
        mzValues[idx - 1] = (cumulativeMass + 1.0) / 1.0; // charge state = 1
    }
}

