    // Display the resulting m/z values
    for (double val : fragmentMZs) {
        std::cout << val << " ";
    }
    return 0;
}

#include <mutex>
#include <condition_variable>
#include <iostream>
#include <thread>
#include <vector>

class SyncManager {
public:
    void AddSyncPoint(int syncId) {
        std::unique_lock<std::mutex> guard(_mtx);
        _syncIds.push_back(syncId);
        _syncStates.push_back(false);
    }

    void SetSyncPoint(int syncId) {
        std::unique_lock<std::mutex> guard(_mtx);
        auto iter = std::find(_syncIds.begin(), _syncIds.end(), syncId);
        if (iter != _syncIds.end()) {
            size_t pos = std::distance(_syncIds.begin(), iter);
            _syncStates[pos] = true;
            _condVar.notify_all();
        }
    }

    void AwaitSyncPoint(int syncId) {
        std::unique_lock<std::mutex> guard(_mtx);
        auto iter = std::find(_syncIds.begin(), _syncIds.end(), syncId);
        if (iter != _syncIds.end()) {
            size_t pos = std::distance(_syncIds.begin(), iter);
            _condVar.wait(guard, [this, pos]() { return _syncStates[pos]; });
        }
    }

private:
    std::vector<int> _syncIds;
    std::vector<bool> _syncStates;
    std::mutex _mtx;
    std::condition_variable _condVar;
};

int main() {
    SyncManager manager;

    // Initialize synchronization points
    manager.AddSyncPoint(1);
    manager.AddSyncPoint(2);
    manager.AddSyncPoint(3);

    // Trigger synchronization points from separate threads
    std::thread worker1([&manager] { manager.SetSyncPoint(1); });
    std::thread worker2([&manager] { manager.SetSyncPoint(2); });
    std::thread worker3([&manager] { manager.SetSyncPoint(3); });

    worker1.join();
    worker2.join();
    worker3.join();

    // Wait for all synchronization points to be reached
    manager.AwaitSyncPoint(1);
    manager.AwaitSyncPoint(2);
    manager.AwaitSyncPoint(3);

    std::cout << "All synchronization points completed." << std::endl;
    return 0;
}

