#include <cmath>

IntersectionTestResult testIntersection(const Ray& ray) {
    IntersectionTestResult intersectionResult;

    // Compute how aligned the ray direction is with the plane normal
    float alignment = dot(ray.direction, getNormal());

    // Check if ray is parallel to plane (no intersection in that case)
    if (std::fabs(alignment) < 1e-6f) {
        intersectionResult.intersects = false;
        return intersectionResult;
    }

    // Determine how far along the ray we need to travel to reach the plane
    float distanceToPlane = dot(getPlanePoint() - ray.origin, getNormal()) / alignment;

    // If distance is negative, intersection occurs behind the ray origin
    if (distanceToPlane < 0.0f) {
        intersectionResult.intersects = false;
        return intersectionResult;
    }

    // Calculate actual intersection position
    intersectionResult.intersectionPoint = ray.origin + distanceToPlane * ray.direction;
    intersectionResult.intersects = true;
    return intersectionResult;
}

