class File;
class Directory;

// Visitor interface for traversing file system elements
class PathVisitor {
public:
    virtual void visitFile(const File& file) = 0;
    virtual void visitDirectory(const Directory& directory) = 0;
};

// Represents a file in the system
class File {
private:
    std::string fileName;
public:
    File() : fileName("unnamed_file") {}
    File(const std::string& name) : fileName(name) {}

    const std::string& getName() const {
        return fileName;
    }

    void accept(PathVisitor* visitor) const {
        visitor->visitFile(*this);
    }
};

// Represents a directory containing files and subdirectories
class Directory {
private:
    std::vector<File> files;
    std::vector<Directory> subDirectories;
    std::string dirName;
public:
    Directory() : dirName("unnamed_dir") {}
    Directory(const std::string& name) : dirName(name) {}

    const std::string& getName() const {
        return dirName;
    }

    void accept(PathVisitor* visitor) const {
        visitor->visitDirectory(*this);
        for (const auto& file : files) {
            file.accept(visitor);
        }
        for (const auto& subDir : subDirectories) {
            subDir.accept(visitor);
        }
    }

    void addFile(const File& file) {
        files.push_back(file);
    }

    void addSubDirectory(const Directory& directory) {
        subDirectories.push_back(directory);
    }
};

// Visitor that lists all files and directories
class ListVisitor : public PathVisitor {
public:
    void visitFile(const File& file) override {
        std::cout << "File: " << file.getName() << std::endl;
    }

    void visitDirectory(const Directory& directory) override {
        std::cout << "Directory: " << directory.getName() << std::endl;
    }
};

// Visitor that searches for a specific file or directory by name
class SearchVisitor : public PathVisitor {
private:
    std::string targetName;
    bool found = false;
public:
    SearchVisitor(const std::string& name) : targetName(name) {}

    void visitFile(const File& file) override {
        if (file.getName() == targetName) {
            std::cout << "File found: " << targetName << std::endl;
            found = true;
        }
    }

    void visitDirectory(const Directory& directory) override {
        if (directory.getName() == targetName) {
            std::cout << "Directory found: " << targetName << std::endl;
            found = true;
        }
    }

    bool isFound() const {
        return found;
    }
};

int main() {
    Directory rootDir("root");
    File file1("file1"), file2("file2");
    Directory subDir("subdir");

    rootDir.addFile(file1);
    rootDir.addFile(file2);
    rootDir.addSubDirectory(subDir);

    ListVisitor listVisitor;
    rootDir.accept(&listVisitor);

    SearchVisitor searchVisitor("file2");
    rootDir.accept(&searchVisitor);

    if (!searchVisitor.isFound()) {
        std::cout << "File not found" << std::endl;
    }

    return 0;
}

