// Function to gather Plug and Play device identifiers via WMI
void FetchPnPDeviceIdentifiers(std::vector<std::string>& outputList) {
    HRESULT status;

    // Initialize COM runtime
    status = CoInitializeEx(0, COINIT_MULTITHREADED);
    if (FAILED(status)) {
        ErrorLogger::Log("COM initialization", std::to_string(status));
        return;
    }

    // Configure COM security context
    status = CoInitializeSecurity(
        NULL,
        -1,
        NULL,
        NULL,
        RPC_C_AUTHN_LEVEL_DEFAULT,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        NULL,
        EOAC_NONE,
        NULL
    );
    if (FAILED(status)) {
        CoUninitialize();
        ErrorLogger::Log("COM security setup", std::to_string(status));
        return;
    }

    // Acquire WMI locator interface
    IWbemLocator* wmiLocator = NULL;
    status = CoCreateInstance(
        CLSID_WbemLocator,
        0,
        CLSCTX_INPROC_SERVER,
        IID_IWbemLocator,
        reinterpret_cast<LPVOID*>(&wmiLocator)
    );
    if (FAILED(status)) {
        CoUninitialize();
        ErrorLogger::Log("WMI locator instantiation", std::to_string(status));
        return;
    }

    // Connect to WMI namespace
    IWbemServices* wmiService = NULL;
    status = wmiLocator->ConnectServer(
        _bstr_t(L"ROOT\\CIMV2"),
        NULL,
        NULL,
        0,
        NULL,
        0,
        0,
        &wmiService
    );
    wmiLocator->Release(); // Release after use
    if (FAILED(status)) {
        CoUninitialize();
        ErrorLogger::Log("WMI connection", std::to_string(status));
        return;
    }

    // Apply authentication blanket to the service proxy
    status = CoSetProxyBlanket(
        wmiService,
        RPC_C_AUTHN_WINNT,
        RPC_C_AUTHZ_NONE,
        NULL,
        RPC_C_AUTHN_LEVEL_CALL,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        NULL,
        EOAC_NONE
    );
    if (FAILED(status)) {
        wmiService->Release();
        CoUninitialize();
        ErrorLogger::Log("Proxy authentication", std::to_string(status));
        return;
    }

    // Execute WMI query
    IEnumWbemClassObject* resultEnumerator = NULL;
    status = wmiService->ExecQuery(
        bstr_t("WQL"),
        bstr_t("SELECT * FROM Win32_PnPEntity"),
        WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
        NULL,
        &resultEnumerator
    );
    if (FAILED(status)) {
        wmiService->Release();
        CoUninitialize();
        ErrorLogger::Log("WMI query execution", std::to_string(status));
        return;
    }

    // Process query results
    IWbemClassObject* currentItem = NULL;
    ULONG itemsFetched = 0;
    while (resultEnumerator) {
        status = resultEnumerator->Next(WBEM_INFINITE, 1, &currentItem, &itemsFetched);
        if (itemsFetched == 0) break;

        VARIANT deviceIdVariant;
        status = currentItem->Get(L"DeviceID", 0, &deviceIdVariant, 0, 0);
        if (SUCCEEDED(status)) {
            outputList.push_back(std::string(_bstr_t(deviceIdVariant.bstrVal)));
            VariantClear(&deviceIdVariant);
        }
        currentItem->Release();
    }

    // Cleanup resources
    wmiService->Release();
    resultEnumerator->Release();
    CoUninitialize();
}

