namespace cuda {
    // Kernel function to perform element-wise addition of two arrays
    __global__ void computeSum(const float* input1, const float* input2, float* output, size_t length) {
        size_t position = blockIdx.x * blockDim.x + threadIdx.x;
        if (position < length) {
            output[position] = input1[position] + input2[position];
        }
    }

    // Host function to manage memory and launch kernel for array addition
    void executeArrayAddition(const float* sourceA, const float* sourceB, float* destination, size_t count) {
        float *devicePtrA, *devicePtrB, *devicePtrOut;

        cudaMalloc((void**)&devicePtrA, count * sizeof(float));
        cudaMalloc((void**)&devicePtrB, count * sizeof(float));
        cudaMalloc((void**)&devicePtrOut, count * sizeof(float));

        cudaMemcpy(devicePtrA, sourceA, count * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(devicePtrB, sourceB, count * sizeof(float), cudaMemcpyHostToDevice);

        computeSum<<<(count + 127) / 128, 128>>>(devicePtrA, devicePtrB, devicePtrOut, count);

        cudaMemcpy(destination, devicePtrOut, count * sizeof(float), cudaMemcpyDeviceToHost);

        cudaFree(devicePtrA);
        cudaFree(devicePtrB);
        cudaFree(devicePtrOut);
    }
}

