    ComplexNumber operator+(const ComplexNumber& other) const {
        return ComplexNumber(realPart + other.realPart, imagPart + other.imagPart);
    }

    ComplexNumber operator-(const ComplexNumber& other) const {
        return ComplexNumber(realPart - other.realPart, imagPart - other.imagPart);
    }

    ComplexNumber operator*(const ComplexNumber& other) const {
        return ComplexNumber(
            realPart * other.realPart - imagPart * other.imagPart,
            realPart * other.imagPart + imagPart * other.realPart
        );
    }

    ComplexNumber operator/(const ComplexNumber& other) const {
        double denom = other.realPart * other.realPart + other.imagPart * other.imagPart;
        return ComplexNumber(
            (realPart * other.realPart + imagPart * other.imagPart) / denom,
            (imagPart * other.realPart - realPart * other.imagPart) / denom
        );
    }

    ComplexNumber power(int exponent) const {
        double magnitude = std::pow(std::sqrt(realPart * realPart + imagPart * imagPart), exponent);
        double angle = std::atan2(imagPart, realPart);
        return ComplexNumber(magnitude * std::cos(exponent * angle), magnitude * std::sin(exponent * angle));
    }
};

