namespace pbrt {
// Convert quaternion to transformation matrix
Transform Quaternion::ToTransform() const {
    Float x2 = v.x * v.x, y2 = v.y * v.y, z2 = v.z * v.z;
    Float xy = v.x * v.y, xz = v.x * v.z, yz = v.y * v.z;
    // Compute the components of the rotation matrix
    Float matrix[16] = {
        1 - 2 * (y2 + z2), 2 * (xy - v.z * w), 2 * (xz + v.y * w), 0,
        2 * (xy + v.z * w), 1 - 2 * (x2 + z2), 2 * (yz - v.x * w), 0,
        2 * (xz - v.y * w), 2 * (yz + v.x * w), 1 - 2 * (x2 + y2), 0,
        0, 0, 0, 1
    };
    // Construct and return the Transform using the computed values
    return Transform(matrix);
}

