template<typename T, typename size_type>
class podarray {
private:
    T* elements;   // Storage for array elements
    size_type length;  // Number of elements in the array

public:
    // Constructor that creates array from raw pointer and size
    explicit podarray(const T* source, const size_type count) {
        length = count;
        elements = new T[length];
        for (size_type index = 0; index < length; ++index) {
            elements[index] = source[index];
        }
    }

    // Constructor that initializes from proxy object
    template<typename ProxyType>
    explicit podarray(const Proxy<ProxyType>& proxy_obj) {
        length = proxy_obj.get_size();
        elements = new T[length];
        for (size_type index = 0; index < length; ++index) {
            elements[index] = proxy_obj[index];
        }
    }

    // Non-const subscript operator for modification
    T& operator[] (const size_type index) {
        return elements[index];
    }

    // Const subscript operator for read-only access
    T operator[] (const size_type index) const {
        return elements[index];
    }

    // Function call operator for element access (non-const)
    T& operator() (const size_type index) {
        return elements[index];
    }

    // Function call operator for element access (const)
    T operator() (const size_type index) const {
        return elements[index];
    }

    // Method to change the array size
    void resize(const size_type new_size) {
        T* temp_storage = new T[new_size];
        size_type copy_count = (new_size < length) ? new_size : length;
        for (size_type index = 0; index < copy_count; ++index) {
            temp_storage[index] = elements[index];
        }
        delete[] elements;
        elements = temp_storage;
        length = new_size;
    }

    // Method to clear the array
    void clear() {
        delete[] elements;
        elements = nullptr;
        length = 0;
    }

    // Destructor to free memory
    ~podarray() {
        delete[] elements;
    }
};

int main() {
    // Demonstration of podarray functionality
    int initial_data[] = {10, 20, 30, 40, 50, 60, 70};
    podarray<int, std::size_t> myContainer(initial_data, 7);
    std::cout << myContainer[2] << std::endl;  // Output: 30
    myContainer.resize(4);
    std::cout << myContainer[4] << std::endl;  // Output: Undefined behavior/accessing out of bounds
    myContainer.clear();
    return 0;
}

