class CArgsHandler {
public:
    bool Handle(const wchar_t* input) {
        std::wstring args(input);
        std::transform(args.begin(), args.end(), args.begin(), ::tolower); // Normalize to lowercase for case-insensitive matching
        if (args.find(L"help") == 0) {
            ShowHelp();
            return true;
        }
        else if (args.find(L"version") == 0) {
            ShowVersion();
            return true;
        }
        else if (args.find(L"run") == 0) {
            std::wstring filepath = ExtractSingleArg(args, L"run");
            if (!filepath.empty()) {
                RunTarget(filepath);
                return true;
            }
        }
        else if (args.find(L"config") == 0) {
            std::vector<std::wstring> params = ExtractMultipleArgs(args, L"config");
            if (params.size() == 2) {
                ApplyConfig(params[0], params[1]);
                return true;
            }
        }
        // Unknown command or processing failure
        return false;
    }

private:
    void ShowHelp() {
        // Output supported commands and usage instructions
        std::cout << "Supported commands:" << std::endl;
        // Insert detailed help text here
    }

    void ShowVersion() {
        // Print current application version
        std::cout << "Program version A.B.C" << std::endl;
    }

    void RunTarget(const std::wstring& path) {
        // Launch the specified file or script
        // Implement actual execution logic here
    }

    void ApplyConfig(const std::wstring& key, const std::wstring& val) {
        // Modify application configuration using provided key-value pair
        // Implement setting update logic here
    }

    std::wstring ExtractSingleArg(const std::wstring& input, const std::wstring& cmd) {
        size_t idx = input.find(cmd);
        if (idx != std::wstring::npos) {
            return input.substr(idx + cmd.length() + 1); // Skip past command and space
        }
        return L"";
    }

    std::vector<std::wstring> ExtractMultipleArgs(const std::wstring& input, const std::wstring& cmd) {
        std::vector<std::wstring> result;
        size_t idx = input.find(cmd);
        if (idx != std::wstring::npos) {
            std::wstring remainder = input.substr(idx + cmd.length() + 1); // Skip command and space
            size_t nextSpace = remainder.find(L" ");
            if (nextSpace != std::wstring::npos) {
                result.push_back(remainder.substr(0, nextSpace)); // First parameter
                result.push_back(remainder.substr(nextSpace + 1)); // Second parameter
            }
        }
        return result;
    }
};

