class SubComponent {
private:
    std::vector<std::function<void()>> eventHandlers;
public:
    auto registerOnEvent(const std::function<void()>& handler) {
        eventHandlers.push_back(handler);
        return this;
    }
    void processAndNotify() {
        // Perform processing operations
        for (const auto& handler : eventHandlers) {
            handler();
        }
        std::cout << "SubComponent processed and notified" << std::endl;
    }
};

class MainComponent {
private:
    SubComponent* sub;
    std::function<void()> mainCallback;
public:
    MainComponent(SubComponent* s) : sub(s) {}
    void triggerSequence(const std::function<void()>& callback) {
        mainCallback = callback;
        sub->processAndNotify();
        mainCallback();
    }
};

int main() {
    SubComponent sc;
    MainComponent mc(&sc);
    auto cb = EventCallback();
    auto handle_sc = sc.registerOnEvent(cb.ConvertToStdFunction());
    // Process the subcomponent, then execute the main callback
    mc.triggerSequence([] {
        std::cout << "Main component completed" << std::endl;
    });
    return 0;
}

