// Type alias for storing query parameters as key-value pairs
using ParameterMap = std::map<std::string, std::string>;

void FilterArguments(ParameterMap& params, const std::set<std::string>& allowedKeys) {
    // Make a temporary copy to safely iterate while modifying the original map
    ParameterMap tempCopy = params;

    // Traverse through the copied entries and remove disallowed ones from original
    for (auto iter = tempCopy.begin(); iter != tempCopy.end(); ) {
        if (allowedKeys.find(iter->first) == allowedKeys.end()) {
            params.erase(iter++);
        } else {
            ++iter;
        }
    }
}

