// Thread-safe queue implementation using mutex and condition variable
template <typename DataType>
class ConcurrentQueue {
public:
    void add(const DataType& item) {
        std::unique_lock<std::mutex> guard(m_mutex);
        m_dataQueue.push(item);
        guard.unlock();  // Release lock before notification for better performance
        m_notifier.notify_one();
    }

    DataType remove() {
        std::unique_lock<std::mutex> guard(m_mutex);
        m_notifier.wait(guard, [this] { return !m_dataQueue.empty(); });
        DataType value = m_dataQueue.front();
        m_dataQueue.pop();
        return value;
    }

    bool isEmpty() const {
        std::lock_guard<std::mutex> guard(m_mutex);
        return m_dataQueue.empty();
    }

private:
    std::queue<DataType> m_dataQueue;
    mutable std::mutex m_mutex;
    std::condition_variable m_notifier;
};

