// Template class for environment-based configuration options
template <typename T>
class ConfigOption {
public:
    ConfigOption(const std::string& key, const T& initial_value) : option_name(key), current_value(initial_value) {}

    T retrieve() const {
        std::lock_guard<std::mutex> guard(mtx);
        return current_value;
    }

    void update(const T& new_value) {
        std::lock_guard<std::mutex> guard(mtx);
        current_value = new_value;
    }

private:
    std::string option_name;
    T current_value;
    mutable std::mutex mtx;
};

// Centralized thread-safe configuration manager
class ConfigManager {
public:
    template <typename T>
    static T fetch(const std::string& key, const T& fallback_value) {
        if (registry.find(key) == registry.end()) {
            registry[key] = new ConfigOption<T>(key, fallback_value);
        }
        return static_cast<ConfigOption<T>*>(registry[key])->retrieve();
    }

    template <typename T>
    static void assign(const std::string& key, const T& value) {
        if (registry.find(key) == registry.end()) {
            std::cerr << "Warning: Configuration key '" << key << "' does not exist." << std::endl;
            return;
        }
        static_cast<ConfigOption<T>*>(registry[key])->update(value);
    }

private:
    static std::unordered_map<std::string, ConfigOptionBase*> registry;
};

std::unordered_map<std::string, ConfigOptionBase*> ConfigManager::registry;

// Helper function to initialize a configuration option with default value
template <typename T>
void initialize_config_option(const std::string& key, const T& default_value) {
    ConfigManager::fetch<T>(key, default_value);
}

// Demonstration of usage
int main() {
