// Process queries to find k-th smallest element in subarrays
std::vector<int> handleQueries(std::vector<Query>& inputQueries, std::vector<int>& inputNums) {
    std::vector<int> output;
    for (const auto& currentQuery : inputQueries) {
        std::vector<int> tempArray(inputNums.begin() + currentQuery.left, 
                                   inputNums.begin() + currentQuery.right + 1);
        std::sort(tempArray.begin(), tempArray.end());
        output.push_back(tempArray[currentQuery.position - 1]);
    }
    return output;
}

