    smtk::attribute::DefinitionPtr derivedDef = system.createDefinition("DerivedDef");
    smtk::attribute::StringItemDefinitionPtr ditemdef = smtk::attribute::StringItemDefinition::New("Derived Expression");
    derivedDef->addItemDefinition(ditemdef);

    smtk::attribute::DefinitionPtr parentDef = system.createDefinition("ParentDef");

    processAndModifyDefinitions(derivedDef, parentDef);

    return 0;
}

