// Utility for managing callable objects and function delegates
using ActionHandler = std::function<void()>;
template <typename T, typename... Params>
using FunctionSignature = std::function<T(Params...)>;

class FunctionDispatcher
{
public:
    // Assign a zero-argument void function
    void AssignCallback(std::function<void()> callback)
    {
        m_CallbackStorage = callback;
    }

    // Assign a delegate taking int and bool, returning int
    void AssignFunction(FunctionSignature<int, int, bool> func)
    {
        m_FunctionStorage = func;
    }

    // Invoke the stored callback if available
    void TriggerCallback()
    {
        if (m_CallbackStorage)
        {
            m_CallbackStorage();
        }
    }

    // Invoke the stored function with provided arguments
    int InvokeFunction(int value, bool flag)
    {
        if (m_FunctionStorage)
        {
            return m_FunctionStorage(value, flag);
        }
        return -1; // Fallback return when no function is assigned
    }

private:
    std::function<void()> m_CallbackStorage;
    std::function<int(int, bool)> m_FunctionStorage;
};

