template<typename SourceEndpoint, typename DestinationEndpoint>
class ConnectionRoute {
    std::vector<std::pair<SourceEndpoint, DestinationEndpoint>> _route;
public:
    // Method to detect if there are duplicate segments in the route
    bool containsLoop() const {
        std::set<std::pair<SourceEndpoint, DestinationEndpoint>> visited;
        for (const auto& segment : _route) {
            if (visited.find(segment) != visited.end()) {
                return true;  // Duplicate segment detected
            }
            visited.insert(segment);
        }
        return false;  // No duplicates found
    }
};

