#include <iostream>
#include <cstring>

class Text {
private:
    char* data;
public:
    // Initialize from null-terminated string
    Text(const char* cstr) {
        data = new char[strlen(cstr) + 1];
        strcpy(data, cstr);
    }

    // Copy constructor for deep copy
    Text(const Text& source) {
        data = new char[strlen(source.data) + 1];
        strcpy(data, source.data);
    }

    // Overloaded assignment operator
    Text& operator=(const Text& rhs) {
        if (this != &rhs) {
            delete[] data;
            data = new char[strlen(rhs.data) + 1];
            strcpy(data, rhs.data);
        }
        return *this;
    }

    // Overloaded concatenation operator
    Text operator+(const Text& other) const {
        char* temp = new char[strlen(data) + strlen(other.data) + 1];
        strcpy(temp, data);
        strcat(temp, other.data);
        Text combined(temp);
        delete[] temp;
        return combined;
    }

    // Equality comparison
    bool operator==(const Text& other) const {
        return strcmp(data, other.data) == 0;
    }

    // Inequality comparison
    bool operator!=(const Text& other) const {
        return strcmp(data, other.data) != 0;
    }

    // Subscript operator for character access
    char& operator[](size_t pos) {
        return data[pos];
    }

    // Clean up dynamically allocated memory
    ~Text() {
        delete[] data;
    }
};

int main() {
    Text word1("Hello");
    Text word2("World");
    Text combined = word1 + word2;
    std::cout << "combined: " << combined << std::endl;
    std::cout << "word1 == word2: " << (word1 == word2) << std::endl;
    std::cout << "word1 != word2: " << (word1 != word2) << std::endl;
    std::cout << "combined[0]: " << combined[0] << std::endl;
