// Event dispatcher that manages multiple callback handlers
template <typename... Parameters>
class EventDispatcher {
public:
    using HandlerType = std::function<void(Parameters...)>;

    void addHandler(HandlerType handler) {
        handlers_.push_back(handler);
    }

    void trigger(Parameters... parameters) {
        for (const auto& handler : handlers_) {
            handler(parameters...);
        }
    }

private:
    std::vector<HandlerType> handlers_;
};

// Wrapper for a single callback function
template <typename... Parameters>
class CallbackWrapper {
public:
    using HandlerType = std::function<void(Parameters...)>;

    CallbackWrapper(HandlerType callback) : callback_(callback) {}

    void invoke(Parameters... parameters) {
        callback_(parameters...);
    }

    void operator()(Parameters... parameters) {
        callback_(parameters...);
    }

private:
    HandlerType callback_;
};

