// Helper function to find all unique combinations that sum up to target
void explore(std::vector<std::vector<int>>& results, std::vector<int>& currentPath, 
             std::vector<int>& availableNumbers, int remainingSum, int startIndex) {
    if (remainingSum < 0) return;

    if (remainingSum == 0) {
        results.push_back(currentPath);
        return;
    }

    for (int index = startIndex; index < availableNumbers.size(); ++index) {
        // Skip duplicates to avoid repeated combinations
        if (index > startIndex && availableNumbers[index] == availableNumbers[index - 1]) 
            continue;

        currentPath.push_back(availableNumbers[index]);
        explore(results, currentPath, availableNumbers, remainingSum - availableNumbers[index], index + 1);
        currentPath.pop_back();
    }
}

// Main function to compute combination sums
std::vector<std::vector<int>> findCombinations(std::vector<int>& numbers, int desiredSum) {
    std::sort(numbers.begin(), numbers.end());
    std::vector<std::vector<int>> solutions;
    std::vector<int> path;

    explore(solutions, path, numbers, desiredSum, 0);
    return solutions;
}

