#include <vector>
#include <algorithm>

class MemoryManager {
private:
    int capacity;
    std::vector<bool> blockStatus;  // Tracks whether each memory block is in use
public:
    MemoryManager(int capacity) : capacity(capacity), blockStatus(capacity, false) {}

    int requestMemory(int numBlocks) {
        for (int index = 0; index <= capacity - numBlocks; ++index) {
            if (std::all_of(blockStatus.begin() + index, blockStatus.begin() + index + numBlocks, [](bool status) { return !status; })) {
                for (int pos = index; pos < index + numBlocks; ++pos) {
                    blockStatus[pos] = true;  // Mark the region as occupied
                }
                return index;  // Provide the base address of the assigned segment
            }
        }
        return -1;  // Indicates failure to find a contiguous free region
    }

    void releaseMemory(int location) {
        if (location >= 0 && location < capacity) {
            blockStatus[location] = false;  // Free up the memory location
        }
    }
};

