// Fisher-Yates shuffle implementation for randomizing vector elements
template <typename T>
void shuffleArray(std::vector<T>& data) {
    std::random_device randDevice;
    std::mt19937_64 engine(randDevice());
    for (int index = data.size() - 1; index > 0; --index) {
        std::uniform_int_distribution<int> distribution(0, index);
        int position = distribution(engine);
        std::swap(data[index], data[position]);
    }
}

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    shuffleArray(numbers);
    for (int value : numbers) {
        std::cout << value << " ";
    }
    return 0;
}

