bool AckBitField::IsSetCorrespondingAckBit( PacketSN ackSN )
{
    uint32_t diff = 0;
    for ( ; RealtimeSrvHelper::SNGreaterThan(
        latestAckSN_, ackSN++ ); ++diff );
    assert( diff );
    uint32_t byteIdx = ( diff - 1 ) >> 3;
    uint32_t bitIdx = ( diff - 1 ) & 0x7;
    // Verify if the respective ACK bit is set
    // Assuming bitField is a member variable storing the bit field data
    if (byteIdx < bitField.size()) {
        uint8_t byteVal = bitField[byteIdx];
        return (byteVal & (1 << bitIdx)) != 0;
    } else {
        // Address case when byteIdx exceeds valid range
        return false;
    }
}

