std::vector<vk::ImageMemoryBarrier> arrangeImageBarriers(
    const std::vector<vk::ImageMemoryBarrier>& inputPreBarriers,
    const std::vector<vk::ImageMemoryBarrier>& inputPostBarriers) {
  std::map<vk::Image, std::vector<vk::ImageMemoryBarrier>> imageBarriers;

  // Collect pre-barriers grouped by image
  for (const auto& barrier : inputPreBarriers) {
    imageBarriers[barrier.image].push_back(barrier);
  }

  // Collect post-barriers grouped by image
  for (const auto& barrier : inputPostBarriers) {
    imageBarriers[barrier.image].push_back(barrier);
  }

  std::vector<vk::ImageMemoryBarrier> resultBarriers;

  // Process each image's barriers
  for (const auto& pair : imageBarriers) {
    vk::Image img = pair.first;
    const auto& allBarriers = pair.second;

    std::vector<vk::ImageMemoryBarrier> writeBarriers;
    std::vector<vk::ImageMemoryBarrier> readBarriers;

    // Separate barriers based on access mask
    for (const auto& b : allBarriers) {
      if ((b.srcAccessMask & vk::AccessFlagBits::eMemoryWrite) != vk::AccessFlagBits::eNone) {
        writeBarriers.emplace_back(b);
      } else {
        readBarriers.emplace_back(b);
      }
    }

    // Sort write barriers by mip level and array layer
    std::sort(writeBarriers.begin(), writeBarriers.end(),
              [](const vk::ImageMemoryBarrier& a, const vk::ImageMemoryBarrier& b) {
                return std::tie(a.subresourceRange.baseMipLevel, a.subresourceRange.baseArrayLayer) <
                       std::tie(b.subresourceRange.baseMipLevel, b.subresourceRange.baseArrayLayer);
              });

    // Sort read barriers similarly
    std::sort(readBarriers.begin(), readBarriers.end(),
              [](const vk::ImageMemoryBarrier& a, const vk::ImageMemoryBarrier& b) {
                return std::tie(a.subresourceRange.baseMipLevel, a.subresourceRange.baseArrayLayer) <
                       std::tie(b.subresourceRange.baseMipLevel, b.subresourceRange.baseArrayLayer);
              });

    // Append sorted barriers to result
    resultBarriers.insert(resultBarriers.end(), writeBarriers.begin(), writeBarriers.end());
    resultBarriers.insert(resultBarriers.end(), readBarriers.begin(), readBarriers.end());
  }

  return resultBarriers;
}

