class MeanSquaredError {
private:
    double error_value;
public:
    // Constructor and other methods are not shown for brevity
    // Compute the gradient of the MSE loss function
    std::vector<double> gradient(const std::vector<double>& predicted_values, int8_t target_class) const {
        // Construct the one-hot encoded target vector
        size_t num_classes = predicted_values.size();
        std::vector<double> target_vector(num_classes, 0.0);
        target_vector[target_class] = 1.0;

        // Calculate the gradient of the MSE loss function
        std::vector<double> grad_vector(num_classes, 0.0);
        for (size_t idx = 0; idx < num_classes; ++idx) {
            grad_vector[idx] = 2 * (predicted_values[idx] - target_vector[idx]) / num_classes;
        }
        return grad_vector;
    }
};

