#include <stack>

class Solution {
public:
    // Count minimum operations needed to process the array
    int minOperations(std::vector<int>& inputArray) {
        std::stack<int> trackingStack;
        int operationCount = 0;

        for (int currentValue : inputArray) {
            // Remove elements from stack that are greater than current value
            while (!trackingStack.empty() && currentValue < trackingStack.top()) {
                trackingStack.pop();
            }

            // If stack is empty or current value is different and positive
            if (trackingStack.empty() || currentValue > trackingStack.top()) {
                if (currentValue > 0) {
                    operationCount++;
                }
                trackingStack.push(currentValue);
            }
        }

        return operationCount;
    }
};

