// Provide the external declaration for the fuzz target function
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *input_data, size_t input_size);

// Main function to process input files and invoke the fuzz target
int main(int argument_count, char **argument_vector) {
  // Iterate over all command-line arguments starting from index 1
  for (int file_index = 1; file_index < argument_count; ++file_index) {
    std::ifstream input_stream(argument_vector[file_index]);

    // Determine file size by seeking to end and back
    input_stream.seekg(0, input_stream.end);
    size_t file_length = static_cast<size_t>(input_stream.tellg());
    input_stream.seekg(0, input_stream.beg);

    std::cout << "Processing " << file_length << " bytes from " 
              << argument_vector[file_index] << std::endl;

    // Read file contents into a buffer
    std::vector<char> buffer(file_length);
    input_stream.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));

    // Invoke the fuzz target with the file data
    LLVMFuzzerTestOneInput(reinterpret_cast<const uint8_t *>(buffer.data()),
                           buffer.size());

    std::cout << "Target executed successfully" << std::endl;
  }

  std::cout << "All inputs processed" << std::endl;
  return 0;
}

