// Function to determine the two pens with lowest ink levels using queries
void findLowInkPens() {
    int numPens;
    std::cin >> numPens;
    std::list<int> remainingPens;

    // Initialize list with all pen indices (0 to numPens-1)
    for (int idx = 0; idx < numPens; ++idx) {
        remainingPens.push_back(idx);
    }

    // Repeatedly filter candidates by querying pairs until at most 2 remain
    while (remainingPens.size() > 2) {
        std::list<int> nextRoundCandidates;

        for (int currentPen : remainingPens) {
            std::cout << "0 " << currentPen << std::endl;
            int answer;
            std::cin >> answer;

            if (answer == 1) {
                nextRoundCandidates.push_back(currentPen);
            }
        }

        remainingPens = nextRoundCandidates;

        // Stop early if we've narrowed down sufficiently
        if (remainingPens.size() <= 2) {
            break;
        }
    }

    // Handle edge cases where fewer than 2 pens remain
    if (remainingPens.size() < 2) {
        if (remainingPens.empty()) {
            std::cout << "1 0 1" << std::endl;
        } else {
            int firstPen = remainingPens.front();
            int secondPen = (firstPen + 1) % numPens;
            std::cout << "1 " << firstPen << " " << secondPen << std::endl;
        }
        return;
    }

    // Output the final two candidate pens
    int penA = remainingPens.front();
    remainingPens.pop_front();
    int penB = remainingPens.front();
    std::cout << "1 " << penA << " " << penB << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCases;
    std::cin >> testCases;

    while (testCases-- > 0) {
        findLowInkPens();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

// This function constructs a particular layout for the "Kangaroos" challenge.
// The layout forms a 25x25 grid featuring a "dual-toothed comb" pattern.
// This configuration is acyclic (a tree), fulfilling the problem requirements.
// It features a primary horizontal "spine" with multiple perpendicular "prongs"
// attached. This design separates agent motion: agents on the spine mainly
// react to horizontal commands, while those on prongs react to vertical ones.
// Switching between zones demands being at an intersection point and getting
// the right command, which rarely occurs simultaneously across all agents
// when using stochastic inputs. The many cul-de-sacs also hinder agents,
// making it hard for them to cluster together.

void generate_map() {
    int rows = 25;
    int cols = 25;
    std::cout << rows << " " << cols << std::endl;
    std::vector<std::string> grid(rows, std::string(cols, '0'));

    // Position the main spine on a middle row. For rows=25, row 11 is selected.
    int spine_row = rows / 2 - 1;
    for (int col = 0; col < cols; ++col) {
        grid[spine_row][col] = '1';
    }

    // Insert prongs at alternating columns (odd indices here) to prevent
    // interconnection and preserve the tree topology.
    for (int col = 0; col < cols; ++col) {
        if (col % 2 == 1) {
            // Upper prongs, extending from top edge down to the spine.
            for (int row = 0; row < spine_row; ++row) {
                grid[row][col] = '1';
            }
            // Lower prongs, extending from below the spine to bottom edge.
            for (int row = spine_row + 1; row < rows; ++row) {
                grid[row][col] = '1';
            }
        }
    }

    // Output the created layout to console.
    for (int row = 0; row < rows; ++row) {
        std::cout << grid[row] << std::endl;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    generate_map();
    return 0;
}

