#include <vector>
#include <algorithm>

class Solution {
public:
    // Replace adjacent non-coprime elements with their LCM
    std::vector<int> replaceNonCoprimes(std::vector<int>& nums) {
        std::vector<int> stack;

        for (int num : nums) {
            stack.push_back(num);  // Add current element to the working list

            // While we have at least two elements and they share a common factor > 1
            while (stack.size() >= 2 && __gcd(stack.back(), stack[stack.size() - 2]) > 1) {
                long long x = stack.back();
                long long y = stack[stack.size() - 2];
                long long gcd_val = __gcd(x, y);

                // Remove the two elements that are not co-prime
                stack.pop_back();
                stack.pop_back();

                // Insert their LCM in place of the two elements
                stack.push_back((x * y) / gcd_val);
            }
        }

        return stack;
    }
};

