namespace boost {
namespace capy {

// A base class for consuming buffer sequences in a generic way
template<bool IsMutable>
class buffer_consumer
{
public:
    /** The type of buffer returned by the consumer
    */
    using result_type = std::conditional_t<
        IsMutable, mutable_buffer, const_buffer>;

    /** Destructor
    */
    virtual ~buffer_consumer() = default;

    /** Check if there are remaining buffers to consume
        @return `true` if no more buffers remain, `false` otherwise.
    */
    virtual bool is_empty() const noexcept = 0;

    /** Extract the next batch of buffers into the provided array
        @param out Pointer to an array where buffer references will be stored
        @param max_count Maximum number of buffers to copy into the output array

        @return Number of buffers actually copied into the output array
    */
    virtual std::size_t pull(
        result_type* out, std::size_t max_count) = 0;
};

/** Adapter that wraps a BufferSequence to satisfy the buffer_consumer interface
*/
template<class BufferSequence>
class buffer_consumer_adapter : public buffer_consumer<
    is_mutable_buffer_sequence_v<BufferSequence>>
{
    BufferSequence seq_;
    decltype(begin(seq_)) iter_;
    decltype(end(seq_)) limit_;
public:
    template<class T>
    buffer_consumer_adapter(T&& t)
        : seq_(std::forward<T>(t))
        , iter_(begin(seq_))
        , limit_(end(seq_))
    {
    }

    bool is_empty() const noexcept override
    {
        return iter_ == limit_;
    }

    std::size_t pull(typename
        buffer_consumer_adapter::result_type* out, std::size_t max_count) override
    {
        std::size_t count = 0;
        while(iter_ != limit_ && max_count--)
        {
            *out++ = typename buffer_consumer_adapter::result_type(*iter_++);
            ++count;
        }
        return count;
    }
};

