#include <iostream>
#include <vector>
#include <utility>
#include <numeric>

int n, m;
std::vector<int> stacks[60];
std::vector<std::pair<int, int>> operations;

void transfer_ball(int source, int dest) {
    if (source == dest || stacks[source].empty()) {
        return;
    }
    int ball = stacks[source].back();
    stacks[source].pop_back();
    stacks[dest].push_back(ball);
    operations.push_back({source, dest});
}

void transfer_all(int source, int dest) {
    while (!stacks[source].empty()) {
        transfer_ball(source, dest);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::cin >> n >> m;
    for (int i = 1; i <= n; ++i) {
        stacks[i].resize(m);
        for (int j = 0; j < m; ++j) {
            std::cin >> stacks[i][j];
        }
    }

    // Strategy: Sort colors one by one. For color i, move all balls of color i to stack i.
    // Stacks 1 to i-1 are already sorted.
    for (int target_color = 1; target_color <= n; ++target_color) {
        // First, move all balls from unsorted stacks (target_color to n) to the buffer stack (n+1).
        for (int src = target_color; src <= n; ++src) {
            transfer_all(src, n + 1);
        }

        // Now, redistribute balls from n+1.
        // Balls of color target_color go to stack target_color.
        // Balls of other colors k > target_color go to stack k (as temporary storage for the next steps).
        while (!stacks[n + 1].empty()) {
            int current_ball = stacks[n + 1].back();
            if (current_ball == target_color) {
                transfer_ball(n + 1, target_color);
            } else {
                transfer_ball(n + 1, current_ball);
            }
        }

        // At this point, stack target_color is sorted and full.
        // The remaining balls are on their respective destination stacks, ready for the next iteration.
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

