namespace mozjs
{
	GlobalHeapManager::GlobalHeapManager(JSContext* ctx) : m_context(ctx) {}

	std::unique_ptr<GlobalHeapManager> GlobalHeapManager::Create(JSContext* ctx)
	{
		return std::unique_ptr<GlobalHeapManager>(new GlobalHeapManager(ctx));
	}

	void GlobalHeapManager::RegisterUser(IHeapUser* heapUser)
	{
		std::lock_guard<std::mutex> lock(m_user_mutex);
		m_registered_users.emplace(heapUser, heapUser);
	}

	void GlobalHeapManager::UnregisterUser(IHeapUser* heapUser)
	{
		std::lock_guard<std::mutex> lock(m_user_mutex);
		m_registered_users.erase(heapUser);
	}

	uint32_t GlobalHeapManager::Store(JS::HandleValue valueToStore)
	{
		std::lock_guard<std::mutex> lock(m_element_mutex);

		if (!m_free_indices.empty())
		{
			m_free_indices.clear();
		}

		while (m_storage.contains(m_next_id))
		{
			++m_next_id;
		}

		m_storage.emplace(m_next_id, std::make_unique<HeapElement>(valueToStore));
		return m_next_id++;
	}

	uint32_t GlobalHeapManager::Store(JS::HandleObject valueToStore)
	{
		JS::RootedValue jsValue(m_context, JS::ObjectValue(*valueToStore));
		return Store(jsValue);
	}

	uint32_t GlobalHeapManager::Store(JS::HandleFunction valueToStore)
	{
		JS::RootedObject jsObject(m_context, JS_GetFunctionObject(valueToStore));
		return Store(jsObject);
	}

	JS::Heap<JS::Value>& GlobalHeapManager::Get(uint32_t id)
	{
		std::lock_guard<std::mutex> lock(m_element_mutex);

		if (!m_free_indices.empty())
		{
			m_free_indices.clear();
		}

		return *m_storage[id];
	}

	void GlobalHeapManager::Remove(uint32_t id)
	{
		std::lock_guard<std::mutex> lock(m_element_mutex);
		m_free_indices.emplace_back(std::move(m_storage[id]));
		m_storage.erase(id);
	}

	void GlobalHeapManager::Trace(JSTracer* trc)
	{
		std::lock_guard<std::mutex> lock(m_element_mutex);

		for (auto& [index, heapElement] : m_storage)
		{
			JS::TraceEdge(trc, heapElement.get(), "CustomHeap_Global");
		}

		for (auto& heapElement : m_free_indices)
		{
			JS::TraceEdge(trc, heapElement.get(), "CustomHeap_Global");
		}
	}

	void GlobalHeapManager::PrepareForGc()
	{
		std::lock_guard<std::mutex> lock(m_user_mutex);

		for (auto& [id, heapUser] : m_registered_users)
		{
			heapUser->PrepareForGlobalGc();
		}

		m_free_indices.clear();
		m_storage.clear();
	}
}

#include "comms/torchcomms/nccl/TorchWorkNCCL.hpp"

namespace torch::comms {

// Process and clean up completed work items from the queue
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::garbageCollectLocked() {
  TorchWorkNCCL::WorkStatus prev_status = TorchWorkNCCL::WorkStatus::COMPLETED;

  // Iterate through all stream queues to remove finished operations
  auto iter = stream_work_queues_.begin();
  while (iter != stream_work_queues_.end()) {
    auto& operation_queue = iter->second;

    // Process each work item in this stream's queue
    while (!operation_queue.empty()) {
      // Examine the first pending operation
      auto current_work = operation_queue.front();

      // Query the current state of the operation
      TorchWorkNCCL::WorkStatus current_state = current_work->checkStatus();
      prev_status = current_state;

      if (current_state == TorchWorkNCCL::WorkStatus::COMPLETED) {
        // Remove completed operation from the queue
        operation_queue.pop();
      } else if (
          current_state == TorchWorkNCCL::WorkStatus::TIMEDOUT ||
          current_state == TorchWorkNCCL::WorkStatus::ERROR) {
        // Propagate error conditions immediately
        return current_state;
      } else {
        // Operation still running - stop processing this queue
        break;
      }
    }

    // Clean up empty stream queues
    if (operation_queue.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return prev_status;
}

// Thread-safe wrapper for garbage collection
// Synchronization: Protected by work_queues_mutex_ against concurrent access
// from enqueueWork() and other threads
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  return garbageCollectLocked();
}

// Finalize all pending operations and clear resources
// Typically called during shutdown or cleanup
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::finalize() {
  // Defensive locking even though watchdog thread should be stopped
  std::lock_guard<std::mutex> guard(work_queues_mutex_);

  // Default status when no work exists
  TorchWorkNCCL::WorkStatus result = TorchWorkNCCL::WorkStatus::COMPLETED;

  // Process remaining work until queue is empty or terminal state reached
  while (!stream_work_queues_.empty()) {
    result = garbageCollectLocked();
    if (result == TorchWorkNCCL::WorkStatus::ERROR ||
        result == TorchWorkNCCL::WorkStatus::TIMEDOUT ||
        result == TorchWorkNCCL::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure all references are released to prevent memory leaks
  stream_work_queues_.clear();
  return result;
}

// Add new work item to the appropriate stream queue
void TorchWorkNCCLQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCL> operation,
    cudaStream_t device_stream) {
  // Thread-safe insertion into the appropriate stream queue
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  stream_work_queues_[device_stream].push(std::move(operation));
}

