#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    // Remove consecutive anagrams from the input list
    std::vector<std::string> removeAnagrams(std::vector<std::string>& inputWords) {
        // Create frequency maps for each word
        std::vector<std::unordered_map<char, int>> charCounts(inputWords.size());

        // Count characters in each word
        for (int idx = 0; idx < inputWords.size(); idx++) {
            for (char c : inputWords[idx]) {
                charCounts[idx][c]++;
            }
        }

        // Build result list starting with first word
        std::vector<std::string> result;
        result.push_back(inputWords[0]);

        // Compare each word with previous one - only add if not anagram
        for (int j = 1; j < inputWords.size(); j++) {
            if (charCounts[j] != charCounts[j - 1]) {
                result.push_back(inputWords[j]);
            }
        }

        return result;
    }
};

