#include <vector>
#include <algorithm>
using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

class Validator {
public:
    void collectInorder(TreeNode* node, vector<int>& sequence) {
        if (!node) return;
        collectInorder(node->left, sequence);
        sequence.push_back(node->val);
        collectInorder(node->right, sequence);
    }

    bool checkValidBST(TreeNode* root) {
        vector<int> sequence;
        collectInorder(root, sequence);

        // Verify that the sequence is strictly increasing
        for (int idx = 1; idx < sequence.size(); ++idx) {
            if (sequence[idx] <= sequence[idx - 1]) {
                return false;
            }
        }
        return true;
    }
};

