#include "ARM.h"
#include "ARMInstrInfo.h"
#include "ARMMachineFunctionInfo.h"
#include "llvm/ADT/Statistic.h"
#include "llvm/CodeGen/MachineFunctionPass.h"
using namespace llvm;
#define DEBUG_TYPE "dual memory barriers"
STATISTIC(NumDMBsEliminated, "Count of DMBs eliminated");
namespace {
class ARMOptimizeMemoryBarriersPass : public MachineFunctionPass {
public:
  static char ID;
  ARMOptimizeMemoryBarriersPass() : MachineFunctionPass(ID) {}
  bool runOnMachineFunction(MachineFunction &Func) override;
  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }
  StringRef getPassName() const override { return "memory barrier optimization"; }
};
char ARMOptimizeMemoryBarriersPass::ID = 0;
}

// Determines if the given instruction can be safely reordered across a DMB
// This is allowed only when MI has no potential memory accesses or side effects
static bool CanReorderAcrossDMB(const MachineInstr *Instr) {
  return !(Instr->mayLoad() ||
          Instr->mayStore() ||
          Instr->hasUnmodeledSideEffects() ||
          Instr->isCall() ||
          Instr->isReturn());
}

bool ARMOptimizeMemoryBarriersPass::runOnMachineFunction(MachineFunction &MF) {
  if (skipFunction(MF.getFunction()))
    return false;

  std::vector<MachineInstr *> ToDelete;
  int64_t LastDMBImm = -1;

  for (auto &BB : MF) {
    bool NextDMBIsRedundant = false;
    for (auto &Inst : BB) {
      if (Inst.getOpcode() == ARM::DMB) {
        if (NextDMBIsRedundant) {
          // If current DMB's immediate matches previous one, mark for deletion
          if (Inst.getOperand(0).getImm() == LastDMBImm) {
            ToDelete.push_back(&Inst);
          } else {
            // Update tracking with new DMB type
            LastDMBImm = Inst.getOperand(0).getImm();
          }
        } else {
          // First DMB encountered in this region
          NextDMBIsRedundant = true;
          LastDMBImm = Inst.getOperand(0).getImm();
        }
      } else if (!CanReorderAcrossDMB(&Inst)) {
        // Non-reorderable instruction resets redundancy flag
        NextDMBIsRedundant = false;
      }
    }
  }

  bool Modified = false;
  for (auto *Instr : ToDelete) {
    Instr->eraseFromParent();
    ++NumDMBsEliminated;
    Modified = true;
  }
  return Modified;
}

/// createARMOptimizeMemoryBarriersPass - Returns an instance of the double
/// memory barrier elimination pass.
FunctionPass *llvm::createARMOptimizeMemoryBarriersPass() {
  return new ARMOptimizeMemoryBarriersPass();
}

#include "ReduceInstructions.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include <set>
using namespace llvm;

// Exclude instructions that must be preserved to maintain IR validity
static bool mustRetain(const Instruction &Instr) {
  return Instr.isEHPad() || Instr.getType()->isTokenTy() || Instr.isSwiftError();
}

// Eliminate out-of-scope function parameters and adjust call sites accordingly.
// Also discard allocations of such parameters.
static void stripInstructionsFromModule(Oracle &Rng, ReducerWorkItem &Task) {
  Module &Program = Task.getModule();
  std::vector<Instruction *> KeepList;

  for (auto &Func : Program)
    for (auto &Block : Func) {
      // Preserve terminator to keep block structure intact
      KeepList.push_back(Block.getTerminator());

      for (auto &Instr : make_range(Block.begin(), std::prev(Block.end()))) {
        if (mustRetain(Instr) || Rng.shouldKeep())
          KeepList.push_back(&Instr);
      }
    }

  // Convert vector to set for efficient lookup while minimizing rebalancing cost
  std::set<Instruction *> RetainSet(KeepList.begin(), KeepList.end());

  std::vector<Instruction *> DeleteList;
  for (auto &Func : Program)
    for (auto &Block : Func)
      for (auto &Instr : Block)
        if (!RetainSet.count(&Instr)) {
          Instr.replaceAllUsesWith(getDefaultValue(Instr.getType()));
          DeleteList.push_back(&Instr);
        }

  for (auto *Instr : DeleteList)
    Instr->eraseFromParent();
}

void llvm::reduceInstructionsDeltaPass(TestRunner &Runner) {
  runDeltaPass(Runner, stripInstructionsFromModule, "Filtering Instructions");
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>

using namespace std;

// Function to ask query and handle termination condition
int inquire(int x, int y) {
    cout << "? " << x << " " << y << endl;
    int answer;
    cin >> answer;
    if (answer == -1) {
        exit(0);
    }
    return answer;
}

void process() {
    int size;
    if (!(cin >> size)) return;

    // Create array of player identifiers starting from 1
    vector<int> players(size);
    iota(players.begin(), players.end(), 1);

    // Randomize order to improve average-case performance
    mt19937 generator(chrono::steady_clock::now().time_since_epoch().count());
    shuffle(players.begin(), players.end(), generator);

    int culprit = -1;

    // Process players in adjacent pairs to find asymmetric responses
    int pair_limit = (size / 2) * 2;

    for (int idx = 0; idx < pair_limit; idx = idx + 2) {
        int first = players[idx];
        int second = players[idx+1];

        int opinion1 = inquire(first, second); // first's assessment of second
        int opinion2 = inquire(second, first); // second's assessment of first

        if (opinion1 != opinion2) {
            // Found the pair containing the impostor

            int witness;
            // Select a valid witness not involved in the suspect pair
            if (idx == 0) {
                // Use third element as witness when first pair is under investigation
                witness = players[2];
            } else {
                // Use first element as witness otherwise
                witness = players[0];
            }

            int eval1 = inquire(first, witness);   // first's view of witness
            int eval2 = inquire(second, witness);  // second's view of witness

            if (eval1 != eval2) {
                // One is Knight (truth-teller), one is Impostor (liar)
                // Knight says 1 about Impostor, Impostor says 0 about Knight
                if (opinion1 == 0) 
                    culprit = first;
                else 
                    culprit = second;
            } else {
                // Both are liars: Knave and Impostor
                // Knave says 0 about Impostor, Impostor says 1 about Knave
                if (opinion1 == 1) 
                    culprit = first;
                else 
                    culprit = second;
            }

            cout << "! " << culprit << endl;
            return;
        }
    }

    // Handle odd-sized case where last player is the impostor
    if (size % 2 == 1) {
        cout << "! " << players[size-1] << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while(test_cases--) {
            process();
        }
    }
    return 0;
}

