void ThrownEnderpearl::onCollision(HitResult *hitResult)
{
	if (hitResult->entityTarget != nullptr)
	{
		DamageSource *source = DamageSource::thrown(shared_from_this(), ownerEntity);
		hitResult->entityTarget->takeDamage(source, 0);
		delete source;
	}

	for (int index = 0; index < 32; ++index)
	{
		world->spawnParticle(eParticleType_ender, x, y + randomValue->nextDouble() * 2, z, randomValue->nextGaussian(), 0, randomValue->nextGaussian());
