		// If the owner has been removed, then ignore
		shared_ptr<ServerPlayer> player = dynamic_pointer_cast<ServerPlayer>(ownerEntity);
		if (player != nullptr && !player->isRemoved())
		{
			if (!player->connection->isFinished && player->dimension == this->world)
			{
				ownerEntity->moveTo(x, y, z);
				ownerEntity->fallDistance = 0;
				ownerEntity->takeDamage(DamageSource::fall, 5);
			}
		}
		destroy();
	}
}

