}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <tuple>

// Stores the generated edges in the form (source, intermediate, target)
// indicating an edge from source to target via intermediate node
std::vector<std::tuple<int, int, int>> generated_edges;

/**
 * @brief Constructs edges for a specific jump size.
 *
 * For a given jump distance `dist`, this function creates edges i -> i+dist
 * using existing paths of two segments: i -> i+seg1 and i+seg1 -> i+dist,
 * where seg2 = dist - seg1.
 *
 * @param dist The length of the desired jump.
 * @param max_node Maximum vertex index allowed.
 * @param seg1 Length of the first segment in the decomposition.
 * @param seg2 Length of the second segment in the decomposition.
 */
void construct_jump(int dist, int max_node, int seg1, int seg2) {
    if (dist > max_node) return;
    for (int start = 0; start <= max_node - dist; ++start) {
        generated_edges.emplace_back(start, start + seg1, start + dist);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Handle trivial cases
    if (n <= 1) {
        std::cout << 0 << '\n';
        return 0;
    }

    // Determine optimal parameter k to minimize total edges
    // Approximate formula: minimize (2k + n/k^2), solution near n^(1/3)
    int param_k = 1;
    if (n > 0) {
        param_k = static_cast<int>(std::round(std::pow(n, 1.0 / 3.0)));
    }
    // Ensure param_k is at least 2 for meaningful construction
    if (param_k <= 1 && n > 1) {
        param_k = 2;
    }

    // Step 1: Build jumps of lengths 2 through param_k-1
    // Each jump i is built from jumps (i-1) and 1
    for (int len = 2; len < param_k; ++len) {
        construct_jump(len, n, len - 1, 1);
    }

    // Step 2: Build multiples of param_k up to (param_k-1)*param_k
    // First build jump param_k from (param_k-1) and 1
    if (param_k <= n) {
        construct_jump(param_k, n, param_k - 1, 1);
    }
    // Then build i*param_k from (i-1)*param_k and param_k
    for (int mult = 2; mult < param_k; ++mult) {
        construct_jump(mult * param_k, n, (mult - 1) * param_k, param_k);
    }

    // Step 3: Build multiples of param_k^2 up to floor(n / param_k^2) * param_k^2
    int sq_param_k = param_k * param_k;
    if (sq_param_k <= n) {
        construct_jump(sq_param_k, n, (param_k - 1) * param_k, param_k);
    }
    int max_mult = n / sq_param_k;
    for (int mult = 2; mult <= max_mult; ++mult) {
        construct_jump(mult * sq_param_k, n, (mult - 1) * sq_param_k, sq_param_k);
    }

    // Output results
    std::cout << generated_edges.size() << '\n';
    for (const auto& edge : generated_edges) {
        std::cout << std::get<0>(edge) << " "
                  << std::get<1>(edge) << " "
                  << std::get<2>(edge) << '\n';
    }

    return 0;
}

