// Optional placeholder RelPatchObj to support default construction and enable
// detection of uninitialized instances via isDummy()
// A RelPatchObj can represent a JMP instruction with zero initial offset,
// which can later be updated using the set...() methods.
// A valid RelPatchObj stores whether it uses a short (8-bit) or long (32-bit)
// jump, records the position immediately after the instruction in the binary,
// and knows how to patch the offset accordingly.
// Short jumps should only be used when the programmer guarantees that the
// target will always fall within an 8-bit signed range; otherwise, use long.

// coverity[autosar_cpp14_a12_1_5_violation] binary_ initialized to nullptr
RelPatchObj::RelPatchObj() VB_NOEXCEPT 
    : positionAfterInstruction_(0U), 
      binary_(nullptr), 
      initialized_(false), 
      short_(false) {
}

RelPatchObj::RelPatchObj(bool const isShort, uint32_t const positionAfterInstruction, MemWriter &binary) VB_NOEXCEPT
    : positionAfterInstruction_(positionAfterInstruction),
      binary_(&binary),
      initialized_(true),
      short_(isShort) {
}

// Links the jump target to the current end of the output binary
void RelPatchObj::linkToHere() const {
  assert(initialized_ && "Attempting to write to an uninitialized jump");
  linkToBinaryPos(binary_->size());
}

// Updates the jump target to point to a specific byte offset within the binary
// (offset measured from the start of the generated machine code)
void RelPatchObj::linkToBinaryPos(uint32_t const binaryPosition) const {
  assert(initialized_ && "Attempting to write to an uninitialized jump");

  uint8_t *const ptrAfterInstr = binary_->posToPtr(positionAfterInstruction_);
  int64_t const displacement = static_cast<int64_t>(binaryPosition) - static_cast<int64_t>(positionAfterInstruction_);

  if (short_) {
    // Should never occur under correct usage — developer must ensure this
    assert(displacement >= INT8_MIN && displacement <= INT8_MAX && "JMP displacement exceeds 8-bit signed range");

    // Safe due to prior assertion; overwrite last byte of displacement field
    writeToPtr<int8_t>(pSubI(ptrAfterInstr, 1U), static_cast<int8_t>(displacement));
  } else {
    // Extremely unlikely in practice — would require massive binaries
    if ((displacement <= INT32_MIN) || (displacement >= INT32_MAX)) {
      throw ImplementationLimitationException(ErrorCode::BrHANDLE_ERRORanches_can_only_maximally_target_32_bit_signed_offsets);
    } // GCOVR_EXCL_LINE

    writeToPtr<int32_t>(pSubI(ptrAfterInstr, 4U), static_cast<int32_t>(displacement));
  }
}

// Retrieves the current target offset (i.e., where the jump points to)
uint32_t RelPatchObj::getLinkedBinaryPos() const VB_NOEXCEPT {
  assert(initialized_ && "Attempting to read from an uninitialized jump");

  uint8_t const *const ptrAfterInstr = binary_->posToPtr(positionAfterInstruction_);
  int64_t result;

  // GCOVR_EXCL_START
  // Not currently implemented for all cases
  if (short_) {
    result = static_cast<int64_t>(positionAfterInstruction_) + readFromPtr<int8_t>(pSubI(ptrAfterInstr, 1));
  } else {
    // GCOVR_EXCL_STOP
    result = static_cast<int64_t>(positionAfterInstruction_) + readFromPtr<int32_t>(pSubI(ptrAfterInstr, 4));
  }

  assert(result <= UINT32_MAX && "Computed binary position exceeds 32-bit limit");
  return static_cast<uint32_t>(result);
}

