// Implementation of FileOutputStream: opens a file for writing using platform-specific APIs.
// Supports Windows (CreateFile) and Linux/Unix (open/write/close).
// Throws no exceptions explicitly; error handling is currently stubbed.

FileOutputStream::FileOutputStream(const File &sourceFile) : m_fileHandle(INVALID_HANDLE_VALUE)
{
	if (sourceFile.exists() && sourceFile.isDirectory()) {
		// TODO 4J Stu - throw FileNotFoundException
		return;
	}

#ifdef _DURANGO
	m_fileHandle = CreateFile(
		sourceFile.getPath().c_str(),   // filename
		GENERIC_WRITE,                  // desired access
		0,                              // share mode — currently no sharing
		NULL,                           // security attributes — unused
		OPEN_ALWAYS,                    // creation disposition
		FILE_ATTRIBUTE_NORMAL,          // file attributes
		NULL                            // template file — unsupported
	);
#elif defined(__linux__)
	std::wstring wPath = sourceFile.getPath();
	char* ansiPath = new char[wPath.size() + 1];
	std::wcstombs(ansiPath, wPath.c_str(), wPath.size() + 1);
	m_fileHandle = open(ansiPath, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
	delete[] ansiPath;
#else
	m_fileHandle = CreateFile(
		wstringtofilename(sourceFile.getPath()), // filename
		GENERIC_WRITE,                  // desired access
		0,                              // share mode — currently no sharing
		NULL,                           // security attributes — unused
		OPEN_ALWAYS,                    // creation disposition
		FILE_ATTRIBUTE_NORMAL,          // file attributes
		NULL                            // template file — unsupported
	);
#endif

	if (m_fileHandle == INVALID_HANDLE_VALUE) {
		// TODO 4J Stu - proper error reporting or exception
		DWORD errCode = GetLastError();
		(void)errCode; // suppress unused warning
	}
}

FileOutputStream::~FileOutputStream()
{
	if (m_fileHandle != INVALID_HANDLE_VALUE) {
		::close(m_fileHandle);
	}
}

// Writes a single byte to the file stream.
void FileOutputStream::write(unsigned int inputByte)
{
	byte data = static_cast<byte>(inputByte);
#if defined(_WIN32)
	DWORD bytesWritten = 0;
	BOOL success = WriteFile(
		m_fileHandle,
		&data,
		1,
		&bytesWritten,
		NULL
	);
	int result = static_cast<int>(success);
#else // POSIX
	int fd = static_cast<int>(m_fileHandle);
	ssize_t bytesWritten = ::write(fd, &data, 1);
	int result = (bytesWritten == 1) ? 1 : 0;
#endif

	if (result == 0 || bytesWritten != 1) {
		// TODO 4J Stu - handle write failure
	}
}

// Writes an entire byte array to the file.
void FileOutputStream::write(byteArray buffer)
{
#if defined(_WIN32)
	DWORD bytesWritten = 0;
	BOOL success = WriteFile(
		m_fileHandle,
		buffer.data,
		buffer.length,
		&bytesWritten,
		NULL
	);
	int result = static_cast<int>(success);
#else // POSIX
	int fd = static_cast<int>(m_fileHandle);
	ssize_t bytesWritten = ::write(fd, buffer.data, buffer.length);
	int result = (bytesWritten == static_cast<ssize_t>(buffer.length)) ? 1 : 0;
#endif

	if (result == 0 || bytesWritten != static_cast<ssize_t>(buffer.length)) {
		// TODO 4J Stu - handle partial or failed write
	}
}

// Writes a sub-range of a byte array: [offset, offset + length).
void FileOutputStream::write(byteArray buffer, unsigned int startIdx, unsigned int count)
{
	// Ensure requested range fits within buffer bounds
	assert(count <= (buffer.length - startIdx));

#if defined(_WIN32)
	DWORD bytesWritten = 0;
	BOOL success = WriteFile(
		m_fileHandle,
		&buffer[startIdx],
		count,
		&bytesWritten,
		NULL
	);
	int result = static_cast<int>(success);
#else // POSIX
	int fd = static_cast<int>(m_fileHandle);
	ssize_t bytesWritten = ::write(fd, &buffer[startIdx], count);
	int result = (bytesWritten == static_cast<ssize_t>(count)) ? 1 : 0;
#endif

	if (result == 0 || bytesWritten != static_cast<ssize_t>(count)) {
		// TODO 4J Stu - handle partial or failed write
	}
}

// Closes the stream and invalidates the handle.
void FileOutputStream::close()
{
#ifdef _WIN32
	BOOL success = CloseHandle(m_fileHandle);
#else
	int success = ::close(m_fileHandle);
#endif

	if (success == 0) {
		// TODO 4J Stu - handle close error
	}

	// Prevent double-close in destructor
	m_fileHandle = INVALID_HANDLE_VALUE;
}

#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>
using namespace jnsc;

// Test resizing and basic write/read operations
TEST(CircularAudioBufferTest, ResizeAndWriteRead) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 8);
    EXPECT_EQ(audioBuffer.getNumChannels(), 2u);
    EXPECT_EQ(audioBuffer.getBufferSize(), 8u);

    // Perform write and read operations
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(1, 2.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 2.0f);
}

// Test buffer wrap-around behavior when writing beyond capacity
TEST(CircularAudioBufferTest, WrapAround) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    // Write more elements than buffer size to trigger wrap-around
    for (int index = 0; index < 6; ++index)
        audioBuffer.write(0, static_cast<float>(index));

    // Verify most recent values are correctly stored (5, 4, 3, 2)
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 5.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 2.0f);
}

// Test buffer clearing functionality
TEST(CircularAudioBufferTest, Clear) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    audioBuffer.write(0, 1.0f);
    audioBuffer.write(0, 2.0f);
    audioBuffer.clear();

    // After clear, new writes should start fresh
    audioBuffer.write(0, 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
}

// Test multi-channel buffer operations
TEST(CircularAudioBufferTest, MultiChannel) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 4);

    // Fill both channels with sequential data
    for (int sampleIndex = 0; sampleIndex < 4; ++sampleIndex) {
        audioBuffer.write(0, static_cast<float>(sampleIndex));
        audioBuffer.write(1, static_cast<float>(sampleIndex + 10));
    }

    // Verify channel 0 values: [3, 2, 1, 0] (most recent first)
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 13.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 0.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 3), 10.0f);
}

