void FSteamSocketsTaskManager::HandleConnectionStatusUpdate(SteamNetConnectionStatusChangedCallback_t* ConnectionEvent)
{
	// This method is invoked on the Steam OSS's internal thread.
	// The Steam callback system triggers on the OSS's active thread.
	//
	// Due to the callback mechanism, we must preserve a local copy of the data,
	// since the original pointer becomes inaccessible once this function exits.
	MessageQueue.Enqueue(*ConnectionEvent);
}

void FSteamSocketsTaskManager::HandleConnectionStatusUpdateGS(SteamNetConnectionStatusChangedCallback_t* ConnectionEvent)
{
	MessageQueue.Enqueue(*ConnectionEvent);
}

void FSteamSocketsTaskManager::ProcessPendingTasks()
{
	SteamNetConnectionStatusChangedCallback_t EventBuffer;
	while (!MessageQueue.IsEmpty())
	{
		FMemory::Memzero(EventBuffer);
		if (NetworkSocketSubsystem && MessageQueue.Dequeue(EventBuffer))
		{
			NetworkSocketSubsystem->ProcessSocketEvent(&EventBuffer);
		}
		else
		{
			break;
		}
	}
}

