#include "UndoManager.hpp"
#include <iostream>
// NOTE: It might be possible to track net objects through their raw pointer values instead of NetObjIDs, as the NetObjID is just reassigned when moved, and it isn't reallocated.
bool UndoManager::can_undo() {
    return !undoStack.empty();
}
bool UndoManager::can_redo() {
    return !redoStack.empty();
}
void UndoManager::add(const UndoRedoPair& action) {
    add_to_undo(action);
    redoStack.clear();
}
void UndoManager::add_to_undo(const UndoRedoPair& action) {
    if(undoStack.size() == maxQueueSize)
        undoStack.pop_front();
    undoStack.emplace_back(action);
}
void UndoManager::add_to_redo(const UndoRedoPair& action) {
    if(redoStack.size() == maxQueueSize)
        redoStack.pop_front();
    redoStack.emplace_back(action);
}
void UndoManager::perform_undo() {
    if(undoStack.empty())
        return;
    if(!undoStack.back().undo()) {
        reset();
    }
    else {
        add_to_redo(undoStack.back());
        undoStack.pop_back();
    }
}
void UndoManager::perform_redo() {
    if(redoStack.empty())
        return;
    if(!redoStack.back().redo()) {
        reset();
    }
    else {
        add_to_undo(redoStack.back());
        redoStack.pop_back();
    }
}
void UndoManager::reset() {
    redoStack.clear();
    undoStack.clear();
}

