// Helper function to extract the Reverb Plugin instance from an AudioDevice
static ResonanceAudio::FResonanceAudioReverb* RetrieveReverbPluginFromAudioDevice(FAudioDevice* Device)
{
	return static_cast<ResonanceAudio::FResonanceAudioReverb*>(Device->ReverbPluginInterface.Get());
}

void UResonanceAudioBlueprintFunctionLibrary::SetGlobalReverbPreset(UResonanceAudioReverbPluginPreset* Preset)
{
	// Acquire the active Resonance Audio module instance
	ResonanceAudio::FResonanceAudioModule* AudioModule = &FModuleManager::GetModuleChecked<ResonanceAudio::FResonanceAudioModule>("ResonanceAudio");
	TArray<FAudioDevice*>& ActiveAudioDevices = AudioModule->GetRegisteredAudioDevices();

	// Traverse each registered audio device and apply the new reverb preset
	for (FAudioDevice* CurrentDevice : ActiveAudioDevices)
	{
		ResonanceAudio::FResonanceAudioReverb* ReverbPlugin = RetrieveReverbPluginFromAudioDevice(CurrentDevice);
		if (ReverbPlugin != nullptr)
		{
			ReverbPlugin->SetGlobalReverbPluginPreset(Preset);
		}
	}
}

UResonanceAudioReverbPluginPreset* UResonanceAudioBlueprintFunctionLibrary::GetGlobalReverbPreset()
{
	UResonanceAudioReverbPluginPreset* FoundPreset = nullptr;

	// Acquire the active Resonance Audio module instance
	ResonanceAudio::FResonanceAudioModule* AudioModule = &FModuleManager::GetModuleChecked<ResonanceAudio::FResonanceAudioModule>("ResonanceAudio");
	TArray<FAudioDevice*> const& ActiveAudioDevices = AudioModule->GetRegisteredAudioDevices();

	// Retrieve the global reverb preset from the first available device that supports it
	for (FAudioDevice* CurrentDevice : ActiveAudioDevices)
	{
		// Since SetGlobalReverbSettings applies globally, we only need to query one active device
		ResonanceAudio::FResonanceAudioReverb* ReverbPlugin = RetrieveReverbPluginFromAudioDevice(CurrentDevice);
		if (ReverbPlugin != nullptr)
		{
			FoundPreset = ReverbPlugin->GetGlobalReverbPluginPreset();
			break;
		}
	}
	return FoundPreset;
}

