#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Process one test scenario
void process_case() {
    int total_words;
    std::cin >> total_words;

    // Collect distinct words using a set
    std::set<std::string> collected;

    // Try each starting letter from 'a' to 'z'
    for (char start_char = 'a'; start_char <= 'z'; ++start_char) {
        // Early exit if all required words are already collected
        if (collected.size() == total_words) {
            break;
        }

        std::string base(1, start_char);
        long long requested = 1;
        bool prefix_complete = false;

        // Exponential probing to gather words with current prefix
        while (!prefix_complete) {
            // Send query request
            std::cout << "query " << base << " " << requested << std::endl;

            // Receive response
            int received_count;
            std::cin >> received_count;

            // Store the returned words
            for (int idx = 0; idx < received_count; ++idx) {
                std::string temp_word;
                std::cin >> temp_word;
                collected.insert(temp_word);
            }

            // Terminate prefix processing if fewer than requested or max reached
            if (received_count < requested) {
                prefix_complete = true;
            }
            if (requested == total_words) {
                prefix_complete = true;
            }

            // Double the request size for next iteration if needed
            if (!prefix_complete) {
                requested *= 2;
                if (requested > total_words) {
                    requested = total_words;
                }
            }
        }
    }

    // Print final result
    std::cout << "answer";
    for (const auto& w : collected) {
        std::cout << " " << w;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int num_cases;
    std::cin >> num_cases;

    for (int case_idx = 0; case_idx < num_cases; ++case_idx) {
        process_case();
    }

    return 0;
}

