  nanobind::class_<Node>(m, "Node", "Represents a vertex in the motion graph used by planners.")
      .def(nanobind::init<const Eigen::VectorXd&, int>(), "configuration"_a, "parent_index"_a)
      .def_ro("configuration", &Node::config, "The robot configuration (e.g., joint angles).")
      .def_ro("parent_index", &Node::parent_id, "Index of the parent node in the tree.");

  // RRTOptions class binding to configure the planner behavior
  nanobind::class_<RRTOptions>(m, "RRTOptions", "Configuration parameters for the RRT motion planner.")
      .def(nanobind::init<const std::string&, size_t, double, double, double, double, bool>(),
           "joint_group"_a = "", "maximum_nodes"_a = 1000, "connection_radius"_a = 3.0,
           "collision_resolution"_a = 0.05, "goal_sampling_rate"_a = 0.15,
           "time_limit"_a = 0.0, "bidirectional_mode"_a = false)
      .def_rw("joint_group", &RRTOptions::group_name,
              "Name of the robot's joint group to plan for.")
      .def_rw("maximum_nodes", &RRTOptions::max_nodes, "Upper bound on the number of nodes to generate.")
      .def_rw("connection_radius", &RRTOptions::max_connection_distance,
              "Maximum distance between two configurations to attempt connection.")
      .def_rw("collision_resolution", &RRTOptions::collision_check_step_size,
              "Step size for discretizing edges during collision verification.")
      .def_rw("goal_sampling_rate", &RRTOptions::goal_biasing_probability,
              "Likelihood of biasing samples toward the goal configuration.")
      .def_rw("time_limit", &RRTOptions::max_planning_time,
              "Maximum duration allowed for planning, in seconds.")
      .def_rw("bidirectional_mode", &RRTOptions::rrt_connect,
              "Enable bidirectional growth (RRT-Connect) for faster convergence.");

  // Main RRT planner class binding
  nanobind::class_<RRT>(
      m, "RRT", "Motion planner implementing the Rapidly-exploring Random Tree algorithm.")
      .def(nanobind::init<const std::shared_ptr<Scene>, const RRTOptions&>(), "environment"_a,
           "settings"_a)
      .def("plan_path", unwrap_expected(&RRT::plan), "Compute a trajectory from start to goal.", 
           "initial_state"_a, "target_state"_a)
