class CustomXmlReporter : public IReporter
{
    // caching pointers/references to objects of these types - safe to do
    std::ostream&         output_stream;
    const ContextOptions& options;
    const TestCaseData*   current_test_case;
    std::mutex            report_mutex;

public:
    // constructor has to accept the ContextOptions by ref as a single argument
    CustomXmlReporter(const ContextOptions& in)
            : output_stream(*in.cout)
            , options(in)
            , current_test_case(nullptr) {}

    void report_query(const QueryData& /*in*/) override {}
    void test_run_start() override {}
    void test_run_end(const TestRunStats& /*in*/) override {}
    void test_case_start(const TestCaseData& in) override { current_test_case = &in; }

    void test_case_reenter(const TestCaseData& /*in*/) override {}
    void test_case_end(const CurrentTestCaseStats& /*in*/) override {}
    void test_case_exception(const TestCaseException& /*in*/) override {}

    void subcase_start(const SubcaseSignature& /*in*/) override {
        std::lock_guard<std::mutex> guard(report_mutex);
    }

    void subcase_end() override {
        std::lock_guard<std::mutex> guard(report_mutex);
    }

    void log_assert(const AssertData& in) override {
        // don't include successful asserts by default - this is done here
        // instead of in the framework itself because doctest doesn't know
        // if/when a reporter/listener cares about successful results
        if(!in.m_failed && !options.success)
            return;
        // make sure there are no races - this is done here instead of in the
        // framework itself because doctest doesn't know if reporters/listeners
        // care about successful asserts and thus doesn't lock a mutex unnecessarily
        std::lock_guard<std::mutex> guard(report_mutex);
        // ...
    }

    void log_message(const MessageData& /*in*/) override {
        // messages too can be used in a multi-threaded context - like asserts
        std::lock_guard<std::mutex> guard(report_mutex);
        // ...
    }

    void test_case_skipped(const TestCaseData& /*in*/) override {}
};

// "1" is the priority - used for ordering when multiple reporters/listeners are used
REGISTER_REPORTER("custom_xml", 1, CustomXmlReporter);
// registering the same class as a reporter and as a listener is nonsense but it's possible
REGISTER_LISTENER("custom_listener", 1, CustomXmlReporter);

#include <iostream>

// Important! : infinite nesting -> compiler error (size of Element is impossible to compute)
struct ProblematicElement {
    int data;
    ProblematicElement next; // ERROR: a ProblematicElement would contain a ProblematicElement, which contains a ProblematicElement,
                             // so it can't estimate its struct size
};

// Correct way to do it: use a pointer (fixed size) to refer to another element
struct Element {
    int data;
    Element* next; // pointer has fixed size (usually 4 or 8 bytes)
    void display() const {
        std::cout << data;
        if (next != nullptr) {
            std::cout << " -> ";
            next->display();
        }
    }
};

// Self-nested structs/classes are common in data structures such as linked lists and trees,
// but you will learn about those in the Data Structures and Algorithms course next year
int main() {
    Element head{15, nullptr};
    Element middle{25, nullptr};
    Element tail{35, nullptr};
    head.next = &middle;
    middle.next = &tail;
    head.display(); // 15 -> 25 -> 35
    std::cout << "\n";
}

#include <vector>

class Solution {
public:
    bool stoneGame(std::vector<int>& piles) {
        int size = piles.size();
        int oddTotal = 0;
        int evenTotal = 0;

        // Sum elements at odd positions (indices 0, 2, 4...)
        for (int idx = 0; idx < size; idx += 2) {
            oddTotal += piles[idx];
        }

        // Sum elements at even positions (indices 1, 3, 5...)
        for (int idx = 1; idx < size; idx += 2) {
            evenTotal += piles[idx];
        }

        return oddTotal != evenTotal;
    }
};

