#include <iostream>
#include <vector>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long value;
    std::cin >> value;

    // Determine grid dimensions based on bit representation
    // Using 61 rows/columns to handle values up to 10^18
    int size = 100;
    std::vector<std::vector<int>> matrix(size + 1, std::vector<int>(size + 1, 0));

    // Track current active row for path construction
    int active_row = 1;

    // Process each bit from least significant to most significant (0 to 60)
    for (int bit = 0; bit < 61; ++bit) {
        // Establish default transition to next layer
        matrix[active_row][active_row + 1] = 1;

        // If current bit is set, add connections from all previous layers
        if ((value >> bit) & 1) {
            for (int prev = 1; prev < active_row; ++prev) {
                matrix[prev][active_row + 1] = 1;
            }
        }
        active_row++;
    }

    // Connect all active rows to final column
    for (int row = 1; row <= active_row; ++row) {
        matrix[row][active_row] = 1;
    }

    // Output results
    std::cout << active_row << "\n";
    for (int i = 1; i <= active_row; ++i) {
        for (int j = 1; j <= active_row; ++j) {
            std::cout << matrix[i][j];
            if (j != active_row) std::cout << " ";
        }
        std::cout << "\n";
    }

    return 0;
}

