#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // Phase 1: Initialization
    // Input string is represented as sSt
    // Convert S to Q and preserve t with backup using alphabet {A, B, C}
    std::cout << "S=Q#" << std::endl;
    std::cout << "#a=a#A" << std::endl;
    std::cout << "#b=b#B" << std::endl;
    std::cout << "#c=c#C" << std::endl;
    // Now the string becomes `s Q t # t_ABC`

    // Insert marker `N` at start of s
    std::cout << "a=La" << std::endl;
    std::cout << "b=Lb" << std::endl;
    std::cout << "c=Lc" << std::endl;
    std::cout << "L=N" << std::endl;
    // String now is `N s Q t # t_ABC`

    // Phase 2: Main search loop
    // Transition N to O to begin matching
    std::cout << "N=O" << std::endl;

    // Matching transitions:
    std::cout << "OaQa=O" << std::endl;
    std::cout << "ObQb=O" << std::endl;
    std::cout << "OcQc=O" << std::endl;

    // Match success when entire pattern consumed
    std::cout << "OQ#=(return)1" << std::endl;

    // Mismatch handling rules:
    std::cout << "OaQb=G" << std::endl;
    std::cout << "OaQc=G" << std::endl;
    std::cout << "ObQa=G" << std::endl;
    std::cout << "ObQc=G" << std::endl;
    std::cout << "OcQa=G" << std::endl;
    std::cout << "OcQb=G" << std::endl;

    // Mismatch recovery mechanism:
    // G cleans up partial match and restores original t, then advances N's position
    std::cout << "aG=Ga" << std::endl;
    std::cout << "bG=Gb" << std::endl;
    std::cout << "cG=Gc" << std::endl;
    std::cout << "OG=GO" << std::endl; // Move G past previous O position

    // When G reaches beginning of remaining s portion:
    // `prefix G O suffix ...` -> advance search position
    std::cout << "GO=N" << std::endl;

    // Restore t for next attempt
    std::cout << "NaQ=NaU" << std::endl;
    std::cout << "NbQ=NbU" << std::endl;
    std::cout << "NcQ=NcU" << std::endl;
    std::cout << "N#=N_U" << std::endl;

    // U handles restoration process
    std::cout << "Ua=U" << std::endl;
    std::cout << "Ub=U" << std::endl;
    std::cout << "Uc=U" << std::endl;
    std::cout << "U#=V" << std::endl;

    // V copies from backup alphabet
    std::cout << "VA=aV" << std::endl;
    std::cout << "VB=bV" << std::endl;
    std::cout << "VC=cV" << std::endl;

    // Finalize restoration back to Q state
    std::cout << "aV=aQ" << std::endl;
    std::cout << "bV=bQ" << std::endl;
    std::cout << "cV=cQ" << std::endl;
    std::cout << "V=Q" << std::endl;

    // Termination condition when search completes
    std::cout << "NQ=(return)0" << std::endl;

    return 0;
}

