#include <iostream>
#include <vector>
#include <queue>
#include <cmath> // For std::abs

// This code solves LeetCode problem 1046: Last Stone Weight.
// Process: Repeatedly smash the two heaviest stones together.
// If equal, both destroyed; if unequal, the difference remains.
using namespace std;

class Solution {
public:
    int lastStoneWeight(std::vector<int>& stones) {
        // Use a max-heap to efficiently retrieve the largest elements
        std::priority_queue<int> heap;

        // Insert all stone weights into the heap
        for (int weight : stones) {
            heap.push(weight);
        }

        // Continue until fewer than two stones remain
        while (heap.size() >= 2) {
            // Extract the two heaviest stones
            int heavy = heap.top();
            heap.pop();
            int lighter = heap.top();
            heap.pop();

            // If they're not equal, push the difference back
            if (heavy != lighter) {
                heap.push(std::abs(heavy - lighter));
            }
            // If equal, both are destroyed (nothing pushed back)
        }

        // Return the remaining stone's weight or 0 if none left
        return heap.empty() ? 0 : heap.top();
    }
};

