using namespace llvm;

char IntervalPartition::ID = 0;

IntervalPartition::IntervalPartition() : FunctionPass(ID) {
  initializeIntervalPartitionPass(*PassRegistry::getPassRegistry());
}

INITIALIZE_PASS(IntervalPartition, "intervals",
                "Interval Partition Construction", true, true)

//===----------------------------------------------------------------------===//
// IntervalPartition Implementation
//===----------------------------------------------------------------------===//

// Free allocated memory and reset internal state
void IntervalPartition::releaseMemory() {
  for (Interval *interval : Intervals)
    delete interval;
  IntervalMap.clear();
  Intervals.clear();
  RootInterval = nullptr;
}

// Print all intervals to the given output stream
void IntervalPartition::print(raw_ostream &O, const Module*) const {
  for (const Interval *interval : Intervals)
    interval->print(O);
}

// Insert an interval into the partition and register its basic blocks
void IntervalPartition::addIntervalToPartition(Interval *I) {
  Intervals.push_back(I);
  // Register each basic block in this interval
  for (Interval::node_iterator it = I->Nodes.begin(), end = I->Nodes.end();
       it != end; ++it)
    IntervalMap.insert(std::make_pair(*it, I));
}

// Propagate predecessor relationships based on known successors
void IntervalPartition::updatePredecessors(Interval *interval) {
  BasicBlock *header = interval->getHeaderNode();
  for (BasicBlock *successor : interval->Successors)
    getBlockInterval(successor)->Predecessors.push_back(header);
}

// Analyze a function and construct its interval partition
bool IntervalPartition::runOnFunction(Function &F) {
  // Begin interval enumeration (do not take ownership yet)
  function_interval_iterator iter = intervals_begin(&F, false);
  assert(iter != intervals_end(&F) && "No intervals in function!?!?!");

  // Set root interval and add it to the partition
  addIntervalToPartition(RootInterval = *iter);
  ++iter;  // Move past the first interval

  // Add remaining intervals
  for (function_interval_iterator end = intervals_end(&F); iter != end; ++iter)
    addIntervalToPartition(*iter);

  // Fill in predecessor information using successor data
  for (Interval *interval : Intervals)
    updatePredecessors(interval);

  return false;
}

// Construct a reduced interval partition from an existing one
IntervalPartition::IntervalPartition(IntervalPartition &IP, bool)
  : FunctionPass(ID) {
  assert(IP.getRootInterval() && "Cannot operate on empty IntervalPartitions!");

  // Start enumerating intervals from the source partition
  interval_part_interval_iterator iter = intervals_begin(IP, false);
  assert(iter != intervals_end(IP) && "No intervals in interval partition!?!?!");

  // Set root and add first interval
  addIntervalToPartition(RootInterval = *iter);
  ++iter;  // Skip the initial interval

  // Add remaining intervals
  for (interval_part_interval_iterator end = intervals_end(IP); iter != end; ++iter)
    addIntervalToPartition(*iter);

  // Reconstruct predecessor links
  for (Interval *interval : Intervals)
    updatePredecessors(interval);
}

