#include "WasmException.h"
#include "llvm/CodeGen/AsmPrinter.h"
#include "llvm/CodeGen/MachineFunction.h"
#include "llvm/IR/Mangler.h"
#include "llvm/MC/MCContext.h"
#include "llvm/MC/MCStreamer.h"
using namespace llvm;

// Finalize module-level exception handling data
void WasmException::endModule() {
  // These are symbols used to throw/catch C++ exceptions and C longjmps. These
  // symbols have to be emitted somewhere once in the module. Check if each of
  // the symbols has already been created, i.e., we have at least one 'throw' or
  // 'catch' instruction with the symbol in the module, and emit the symbol only
  // if so.
  //
  // But in dynamic linking, it is in general not possible to come up with a
  // module instantiating order in which tag-defining modules are loaded before
  // the importing modules. So we make them undefined symbols here, define tags
  // in the JS side, and feed them to each importing module.
  if (!Asm->isPositionIndependent()) {
    for (const char *SymName : {"__cpp_exception", "__c_longjmp"}) {
      SmallString<60> NameStr;
      Mangler::getNameWithPrefix(NameStr, SymName, Asm->getDataLayout());
      if (Asm->OutContext.lookupSymbol(NameStr)) {
        MCSymbol *ExceptionSym = Asm->GetExternalSymbolSymbol(SymName);
        Asm->OutStreamer->emitLabel(ExceptionSym);
      }
    }
  }
}

// Handle end-of-function exception table emission
void WasmException::endFunction(const MachineFunction *MF) {
  bool ShouldEmitExceptionTable = false;
  for (const LandingPadInfo &Info : MF->getLandingPads()) {
    if (MF->hasWasmLandingPadIndex(Info.LandingPadBlock)) {
      ShouldEmitExceptionTable = true;
      break;
    }
  }
  if (!ShouldEmitExceptionTable)
    return;
  MCSymbol *LSDALabel = emitExceptionTable();
  assert(LSDALabel && ".GCC_exception_table has not been emitted!");
  // Wasm requires every data section symbol to have a .size set. So we emit an
  // end marker and set the size as the difference between the start and the end
  // marker.
  MCSymbol *LSDAEndLabel = Asm->createTempSymbol("GCC_except_table_end");
  Asm->OutStreamer->emitLabel(LSDAEndLabel);
  MCContext &OutContext = Asm->OutStreamer->getContext();
  const MCExpr *SizeExp = MCBinaryExpr::createSub(
      MCSymbolRefExpr::create(LSDAEndLabel, OutContext),
      MCSymbolRefExpr::create(LSDALabel, OutContext), OutContext);
  Asm->OutStreamer->emitELFSize(LSDALabel, SizeExp);
}

// Build the call-site table for WebAssembly exception handling. Note that in
// this context, a "call site" entry actually represents a landing pad rather
// than a specific call instruction. In Wasm EH, the runtime handles stack
// unwinding. After an exception occurs and the stack is unwound, control flow
// transfers to a wasm 'catch' instruction via the VM, after which the
// personality function is invoked from compiler-generated code. See the
// WasmEHPrepare pass for additional details.
void WasmException::computeCallSiteTable(
    SmallVectorImpl<CallSiteEntry> &CallSites,
    SmallVectorImpl<CallSiteRange> &CallSiteRanges,
    const SmallVectorImpl<const LandingPadInfo *> &LandingPads,
    const SmallVectorImpl<unsigned> &FirstActions) {
  MachineFunction &MF = *Asm->MF;
  for (unsigned Index = 0, NumLPads = LandingPads.size(); Index < NumLPads; ++Index) {
    const LandingPadInfo *Info = LandingPads[Index];
    MachineBasicBlock *LPad = Info->LandingPadBlock;
    // Skip LSDA generation for single catch (...) patterns.
    if (!MF.hasWasmLandingPadIndex(LPad))
      continue;
    // Wasm EH must preserve the EH pads ordering established by WasmEHPrepare.
    unsigned LPadIndex = MF.getWasmLandingPadIndex(LPad);
    CallSiteEntry Site = {nullptr, nullptr, Info, FirstActions[Index]};
    if (CallSites.size() < LPadIndex + 1)
      CallSites.resize(LPadIndex + 1);
    CallSites[LPadIndex] = Site;
  }
}

#include "Transform/LowerSelect.h"
#include <llvm/IR/Constants.h>
#include <llvm/IR/Instructions.h>
#include <llvm/IR/Verifier.h>
#include <llvm/Support/Debug.h>
#define DEBUG_TYPE "lower-select"

// Convert a select instruction into conditional branches with explicit if/else paths.
// Generates two fresh basic blocks for the true and false outcomes, linked via
// a conditional branch from the initial block.
static void rewrite(Instruction *Sel) {
  auto *Func = Sel->getFunction();
  auto *OrigBB = Sel->getParent();

  // All instructions before the iterator remain in the original block.
  // An unconditional branch is appended to OrigBB, and subsequent instructions 
  // (including the old terminator) are shifted to a new block. This new block is returned.
  BasicBlock *MergeBB = Sel->getParent()->splitBasicBlock(Sel, "");

  auto *ThenBB = BasicBlock::Create(Sel->getContext(), "", Func, MergeBB);
  BranchInst::Create(MergeBB, ThenBB);

  auto *ElseBB = BasicBlock::Create(Sel->getContext(), "", Func, MergeBB);
  BranchInst::Create(MergeBB, ElseBB);

  OrigBB->getTerminator()->eraseFromParent();
  BranchInst::Create(ThenBB, ElseBB, Sel->getOperand(0), OrigBB);

  auto *Phi = PHINode::Create(Sel->getType(), 2, "", Sel);
  Phi->addIncoming(Sel->getOperand(1), ThenBB);
  Phi->addIncoming(Sel->getOperand(2), ElseBB);

  Sel->replaceAllUsesWith(Phi);
  Sel->eraseFromParent();
}

// New Pass Manager entry point: locate all select instructions (excluding pointer selects)
// and convert them to explicit branching logic.
PreservedAnalyses LowerSelectPass::run(Module &Mod, ModuleAnalysisManager &) {
  std::vector<SelectInst *> SelList;

  for (auto &F : Mod) {
    for (auto &B : F) {
      for (auto &I : B) {
        if (I.getType()->isPointerTy())
          continue;
        if (auto *SI = dyn_cast<SelectInst>(&I)) {
          SelList.push_back(SI);
        }
      }
    }
  }

  if (SelList.empty())
    return PreservedAnalyses::all();

  for (auto *Sel : SelList)
    rewrite(Sel);

  if (verifyModule(Mod, &errs())) {
    llvm_unreachable("Error: Lowerselect fails...");
  }

  // Control flow graph has changed; invalidate most analyses
  return PreservedAnalyses::none();
}

#include <iostream>
