// Test basic array functionality and initialization
void test_array_initialization(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Array Initialization ===" << std::endl;

    std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
    std::shared_ptr<SMTParser::DAGNode> arr = parser->mkArray("myArray", int_sort, int_sort);
    assert(arr);
    assert(parser->toString(arr).find("myArray") != std::string::npos);
    std::cout << "Initialized array: " << parser->toString(arr) << std::endl;
    std::cout << std::endl;
}

// Test array store and select operations with various expressions
void test_array_functionality(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"((as const (Array Int Int)) 5)", "5"},
        {"(store ((as const (Array Int Int)) 5) 3 15)", ""},
        {"(select (store ((as const (Array Int Int)) 5) 3 15) 3)", "15"},
        {"(select (store ((as const (Array Int Int)) 5) 3 15) 7)", "5"},
        {"(= (select (store ((as const (Array Int Int)) 5) 3 15) 3) 15)", "true"},
        {"(store (store ((as const (Array Int Int)) 5) 3 15) 4 20)", ""}
    };

    std::cout << "=== Testing Array Functionality ===" << std::endl;
    for (const auto& item : test_cases) {
        std::cout << "Expression: " << item.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(item.first);
        assert(output);
        std::string actual = parser->toString(output);
        std::cout << "  Output: " << actual << std::endl;
        if (!item.second.empty()) {
            assert(actual == item.second && "array operation result mismatch");
        } else {
            assert(actual.find("store") != std::string::npos || 
                   actual.find("select") != std::string::npos || 
                   actual.find("const") != std::string::npos);
        }
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Array Theory Validation =======" << std::endl;

    SMTParser::ParserPtr smt_parser = SMTParser::newParser();

    test_array_initialization(smt_parser);
    test_array_functionality(smt_parser);

    return 0;
}

