TEST_CASE("time_point2", "[time_point log_msg]") {
    std::shared_ptr<spdlog::sinks::test_sink_st> test_sink(new spdlog::sinks::test_sink_st);
    spdlog::logger logger("test-time_point-variant", test_sink);
    spdlog::source_loc location{};
    std::chrono::system_clock::time_point timestamp{std::chrono::system_clock::now()};
    test_sink->set_pattern("%H.%M.%S.%f");  // interested in the time_point with higher precision
    // all the following should have the same time
    test_sink->set_delay(std::chrono::milliseconds(15));
    for (int index = 0; index < 5; ++index) {
        spdlog::details::log_msg entry{timestamp, location, "test_logger", spdlog::level::warn, "message"};
        test_sink->log(entry);
    }
    logger.log(timestamp, location, spdlog::level::info, "formatted message");
    logger.log(timestamp, location, spdlog::level::info, "formatted message");
    logger.log(timestamp, location, spdlog::level::info, "formatted message");
    logger.log(timestamp, location, spdlog::level::info, "formatted message");
    logger.log(location, spdlog::level::debug,
               "formatted message");  // last line has different time_point
    // now the real test... that the times are the same.
