// Function to optimize I/O performance
void optimize_io() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
}

// Global variables for graph representation and DSATUR-related data
int vertex_count, edge_count;
std::vector<std::vector<bool>> adjacency_matrix;
std::vector<int> clique_assignment;  // Stores the color (clique ID) for each vertex
std::vector<int> complement_degrees;
std::vector<int> saturation_levels;
std::vector<std::vector<bool>> observed_cliques;

// Reads graph input from standard input
void load_graph() {
    std::cin >> vertex_count >> edge_count;
    adjacency_matrix.assign(vertex_count + 1, std::vector<bool>(vertex_count + 1, false));
    for (int idx = 0; idx < edge_count; ++idx) {
        int src, dst;
        std::cin >> src >> dst;
        adjacency_matrix[src][dst] = adjacency_matrix[dst][src] = true;
    }
}

// Applies DSATUR algorithm on the complement graph to solve clique cover
void compute_clique_cover() {
    // Step 1: Compute degrees in the complement graph
    complement_degrees.assign(vertex_count + 1, 0);
    for (int i = 1; i <= vertex_count; ++i) {
        for (int j = i + 1; j <= vertex_count; ++j) {
            if (!adjacency_matrix[i][j]) {
                complement_degrees[i]++;
                complement_degrees[j]++;
            }
        }
    }

    // Initialize DSATUR structures
    clique_assignment.assign(vertex_count + 1, 0);  // 0 means unassigned
    saturation_levels.assign(vertex_count + 1, 0);
    observed_cliques.assign(vertex_count + 1, std::vector<bool>(vertex_count + 2, false));

    // Main loop: assign one vertex per iteration
    for (int step = 0; step < vertex_count; ++step) {
        // Select next vertex: highest saturation, tie-break by degree in complement
        int candidate = -1;
        for (int v = 1; v <= vertex_count; ++v) {
            if (clique_assignment[v] == 0) {  // Unassigned vertex
                if (candidate == -1 || 
                    saturation_levels[v] > saturation_levels[candidate] ||
                    (saturation_levels[v] == saturation_levels[candidate] && 
                     complement_degrees[v] > complement_degrees[candidate])) {
                    candidate = v;
                }
            }
        }
        int selected = candidate;

        // Determine smallest available color not used by neighbors in complement
        std::vector<bool> neighbor_colors(vertex_count + 2, false);
        for (int neighbor = 1; neighbor <= vertex_count; ++neighbor) {
            if (neighbor != selected && !adjacency_matrix[selected][neighbor] && 
                clique_assignment[neighbor] != 0) {
                neighbor_colors[clique_assignment[neighbor]] = true;
            }
        }

        int chosen_color = 1;
        while (neighbor_colors[chosen_color]) {
            ++chosen_color;
        }
        clique_assignment[selected] = chosen_color;

        // Update saturation levels of unassigned neighbors in complement
        for (int neighbor = 1; neighbor <= vertex_count; ++neighbor) {
            if (neighbor != selected && !adjacency_matrix[selected][neighbor] && 
                clique_assignment[neighbor] == 0) {
                if (!observed_cliques[neighbor][chosen_color]) {
                    observed_cliques[neighbor][chosen_color] = true;
                    saturation_levels[neighbor]++;
                }
            }
        }
    }
}

int main() {
    optimize_io();
    load_graph();
    compute_clique_cover();

    for (int i = 1; i <= vertex_count; ++i) {
        std::cout << clique_assignment[i] << "\n";
    }
    return 0;
}

#include <iostream>
#include <rclcpp/rclcpp.hpp>
#include <rclcpp/serialization.hpp>
#include <rslcpp/rslcpp.hpp>
#include <rslcpp_helper_nodes/monitor.hpp>
#include "rslcpp_test/communication_delay/receiver.hpp"
#include "rslcpp_test/communication_delay/sender.hpp"

/// @brief Custom job implementation for the RSLCPP simulation
class SimulationJob : public rslcpp::Job
{
public:
  /// @brief Return the exit code upon job termination
  std::uint8_t get_exit_code() override { return termination_code_; }

  /// @brief Indicate whether the simulation has completed
  bool is_complete() override { return completed_; }

  /// @brief Provide the starting time for the simulation
  rclcpp::Time get_initial_time() override { return rclcpp::Time(10, 0, RCL_ROS_TIME); }

  /// @brief Create and configure ROS 2 nodes for the simulation
  std::vector<rclcpp::Node::SharedPtr> create_and_get_nodes() override
  {
    rclcpp::NodeOptions node_options;
    // Enable intra-process communication for efficiency
    node_options.use_intra_process_comms(true);

    // Instantiate sender, receiver, and monitor nodes
    auto tx_node = std::make_shared<CommunicationDelaySender>(node_options);
    auto rx_node = std::make_shared<ReceiverNode>(node_options);

    // Set up monitor to terminate simulation after timeout
    auto monitor_node = std::make_shared<rslcpp::helper_nodes::SimulationMonitor>(
      [this](rslcpp::exit_code_t code) {
        completed_ = true;
        termination_code_ = code;
      },
      node_options);

    monitor_node->set_parameter(rclcpp::Parameter("timeout_s", 100));

    // Return all active nodes
    return {tx_node, monitor_node, rx_node};
  }

private:
  bool completed_ = false;
  rslcpp::exit_code_t termination_code_ = 0;
};

/// @brief Entry point for running the RSLCPP simulation
int main(int argc, char ** argv)
{
  // Initialize the simulation job
  auto sim_job = std::make_shared<SimulationJob>();

  // Execute the job using the RSLCPP runtime
  auto result_code = rslcpp::run_job(argc, argv, sim_job);

  std::cout << "RSLCPP Simulation completed with Exit Code: " 
            << static_cast<int>(result_code) << std::endl;

  return 0;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSubArray(std::vector<int>& numbers) {
        int size = numbers.size();
        int currentSum = 0;
        int maximumSum = numbers[0];

        for (int index = 0; index < size; ++index) {
            currentSum += numbers[index];
            maximumSum = std::max(currentSum, maximumSum);

            if (currentSum < 0) {
                currentSum = 0;
            }
        }

        return maximumSum;
    }
};

