 * 
 * @param firstSlice First slice in the pair.
 * @param secondSlice Second slice in the pair.
 */
void report(int firstSlice, int secondSlice) {
    std::cout << "! " << firstSlice << " " << secondSlice << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<bool> matched(2 * n + 1, false);
    std::vector<int> candidates;
    int currentCount = 0;

    for (int idx = 1; idx <= 2 * n; ++idx) {
        if (matched[idx]) {
            continue;
        }

        int newCount = ask(idx);

        if (newCount > currentCount) {
            // This is the first occurrence of a new mineral type
            candidates.push_back(idx);
            currentCount = newCount;
        } else {
            // This is the second occurrence — find its match among candidates
            int targetCount = newCount;

            // Search backwards through candidates for matching pair
            for (int k = static_cast<int>(candidates.size()) - 1; k >= 0; --k) {
                int candidate = candidates[k];
                int testResult = ask(candidate);

                if (testResult == targetCount) {
                    // Found the pair: (idx, candidate)
                    report(idx, candidate);
                    matched[idx] = true;
                    matched[candidate] = true;

                    candidates.erase(candidates.begin() + k);
                    currentCount = testResult;
                    break;
                } else {
                    // Restore state by re-querying candidate
                    ask(candidate);
                }
            }
        }
    }

    return 0;
}

