using namespace std;

// Generate prime numbers between 2 and 9999
vector<int> generatePrimes() {
    vector<int> primes;
    int start = 2;
    int limit = 10000;

    for (int num = start; num < limit; num++) {
        bool isPrime = true;
        for (int divisor = start; divisor <= sqrt(num); divisor++) {
            if (num % divisor == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            primes.push_back(num);
        }
    }
    return primes;
}

// Implement the waiter algorithm
vector<int> processWaiter(vector<int> inputStack, int iterations) {
    vector<int> output, tempA, tempB;
    int value;
    vector<int> primes = generatePrimes();  // Precompute primes

    // Process each prime in sequence
    for (int pIndex = 0; pIndex < iterations && pIndex < primes.size(); pIndex++) {
        int currentSize = inputStack.size();

        // Distribute numbers based on divisibility
        for (int idx = 0; idx < currentSize; idx++) {
            value = inputStack.back();

            if (value % primes[pIndex] == 0) {
                tempB.push_back(value);
                inputStack.pop_back();
            } else {
                tempA.push_back(value);
                inputStack.pop_back();
            }
        }

        // Update input stack for next iteration
        inputStack = tempA;
        tempA.clear();

        // Collect divisible numbers to output
        while (!tempB.empty()) {
            output.push_back(tempB.back());
            tempB.pop_back();
        }
    }

    // Add remaining numbers to output
    while (!inputStack.empty()) {
        output.push_back(inputStack.back());
        inputStack.pop_back();
    }

    return output;
}

int main() {
    // Test case setup
    vector<int> testNumbers = {3, 4, 7, 6, 5};
    int numIterations = 4;  // Number of prime divisors to use

    // Run the algorithm
    vector<int> finalResult = processWaiter(testNumbers, numIterations);

    // Display results
    for (int val : finalResult) {
        cout << val << " ";
    }
    cout << endl;

    return 0;
}

#include <vector>

class Solution {
public:
    int pivotIndex(std::vector<int>& values) {
        int size = values.size();
        int overallSum = 0;
        int prefixSum = 0;

        // Calculate the total sum of all elements
        for (int element : values) {
            overallSum += element;
        }

        // Find the pivot index where left sum equals right sum
        for (int index = 0; index < size; index++) {
            if (prefixSum == overallSum - prefixSum - values[index]) {
                return index;
            }
            prefixSum += values[index];
        }

        return -1;
    }
};

