namespace tpa
{
// Adds successors that are "top-level" (Environment only).
// These successors inherit the Context but don't carry a Store update directly
// in the way mem-level nodes do (though they might share the global Env).
void TransferFunction::addTopLevelSuccessors(const ProgramPoint& point, EvalResult& result)
{
	for (auto *const successor: point.getCFGNode()->uses())
		result.addTopLevelProgramPoint(ProgramPoint(point.getContext(), successor));
}

// Adds successors that are "memory-level" (Store consumers).
// These successors must receive the current (possibly updated) Store.
void TransferFunction::addMemLevelSuccessors(const ProgramPoint& point, const Store& store, EvalResult& result)
{
	for (auto *const successor: point.getCFGNode()->succs())
		result.addMemLevelProgramPoint(ProgramPoint(point.getContext(), successor), store);
}

// Main evaluation dispatch loop.
// Delegates to specific node handlers based on the CFGNodeTag.
// Returns an EvalResult containing next steps for the Propagator.
EvalResult TransferFunction::eval(const ProgramPoint& point)
{
	//errs() << "Evaluating " << point.getCFGNode()->getFunction().getName() << "::" << point << "\n";
	EvalResult result;
	switch (point.getCFGNode()->getNodeTag())
	{
		case CFGNodeTag::Entry:
		{
			// Initialize function parameters in the Env
			evalEntryNode(point, result);
			break;
		}
		case CFGNodeTag::Alloc:
		{
			// Handle memory allocation (malloc, alloca, new)
			evalAllocNode(point, result);
			break;
		}
		case CFGNodeTag::Copy:
		{
			// Handle pointer assignment/copy (p = q)
			evalCopyNode(point, result);
			break;
		}
		case CFGNodeTag::Offset:
		{
			// Handle address computation (GEP)
			evalOffsetNode(point, result);
			break;
		}
		case CFGNodeTag::Load:
		{
			// Handle load from memory (p = *q)
			// Requires local Store state
			if (localState != nullptr)
				evalLoadNode(point, result);
			break;
		}
		case CFGNodeTag::Store:
		{
			// Handle store to memory (*p = q)
			// Requires local Store state
			if (localState != nullptr)
				evalStoreNode(point, result);
			break;
		}
		case CFGNodeTag::Call:
		{
			// Handle function calls
			// Requires local Store state
			if (localState != nullptr)
				evalCallNode(point, result);
			break;
		}
		case CFGNodeTag::Ret:
		{
			// Handle return instructions
			// Requires local Store state
			if (localState != nullptr)
				evalReturnNode(point, result);
			break;
		}
	}
	return result;
}
} // namespace tpa

