#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class PermutationHelper {
public:
    void computeNextPermutation(vector<int>& arr) {
        int size = arr.size();
        int pivotIndex = -1;

        // Step 1: Locate the rightmost position where arr[i] < arr[i+1]
        for (int idx = size - 2; idx >= 0; idx--) {
            if (arr[idx] < arr[idx + 1]) {
                pivotIndex = idx;
                break;
            }
        }

        if (pivotIndex == -1) {
            // No pivot found: array is non-increasing, reverse to get smallest permutation
            reverse(arr.begin(), arr.end());
        } else {
            // Step 2: Find the rightmost element greater than arr[pivotIndex]
            for (int jdx = size - 1; jdx > pivotIndex; jdx--) {
                if (arr[jdx] > arr[pivotIndex]) {
                    swap(arr[jdx], arr[pivotIndex]);
                    break;
                }
            }

            // Step 3: Reverse the suffix after the pivot to get the next lexicographically smallest arrangement
            reverse(arr.begin() + pivotIndex + 1, arr.end());
        }
    }
};

int main() {
    PermutationHelper helper;
    vector<int> data = {2, 3, 7, 6, 5, 1};
    helper.computeNextPermutation(data);

    for (int pos = 0; pos < data.size(); pos++) {
        cout << data[pos] << " ";
    }

    return 0;
}

