MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    this->initializeVisualizationWidget();
    // Initialize the initial visual model: a hexagonal grid surface
    this->configureHexGridRendering();

    // Set up a periodic timer to animate the visualization
    auto animationTimer = new QTimer(parent);
    connect(animationTimer, &QTimer::timeout, [this] {
        for (unsigned int idx = 0; idx < this->hexGrid->size(); ++idx) {
            float dist = std::sqrt(hexGrid->d_x[idx] * hexGrid->d_x[idx] + hexGrid->d_y[idx] * hexGrid->d_y[idx]);
            this->radialDistances[idx] = dist;
            this->surfaceValues[idx] = std::sin(waveNumber * dist) / (waveNumber * dist);
        }
        waveNumber += 0.02f;
        if (waveNumber > 8.0f) {
            waveNumber = 1.0f;
        }

        // Signal that the first visual model needs reinitialization
        static_cast<mplot::qt::viswidget<0>*>(this->vwPtr)->set_model_needs_reinit(0);
        // Trigger redraw
        this->vwPtr->update();
    });
    animationTimer->start();
}

MainWindow::~MainWindow() { delete ui; }

void MainWindow::configureHexGridRendering()
{
    // Build the hexagonal lattice
    this->hexGrid = std::make_unique<sm::hexgrid>(0.025f, 14.0f, 0.0f);
    hexGrid->setCircularBoundary(3.5f);

    // Prepare data arrays for visualization
    surfaceValues.resize(hexGrid->size(), 0.0f);
    radialDistances.resize(hexGrid->size(), 0.0f);
    waveNumber = 1.0f;

    // Precompute initial scalar field
    for (unsigned int hi = 0; hi < hexGrid->size(); ++hi) {
        float r = std::sqrt(hexGrid->d_x[hi] * hexGrid->d_x[hi] + hexGrid->d_y[hi] * hexGrid->d_y[hi]);
        radialDistances[hi] = r;
        surfaceValues[hi] = std::sin(waveNumber * r) / (waveNumber * r);
    }

    // Define offset for rendering position
    sm::vec<float, 3> positionOffset = { 0.0f, -0.07f, 0.0f };
    auto hexVis = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hexGrid.get(), positionOffset);

    // Bind model to shaders and context
    static_cast<mplot::qt::viswidget<0>*>(this->vwPtr)->v.bindmodel(hexVis);

    // Attach scalar data to be rendered
    hexVis->setScalarData(&surfaceValues);

    // Move into container of visual models
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> basePtr = std::move(hexVis);
    static_cast<mplot::qt::viswidget<0>*>(this->vwPtr)->visualModels.push_back(std::move(basePtr));
}

void MainWindow::initializeVisualizationWidget()
{
    // Instantiate OpenGL visualization widget
    mplot::qt::viswidget<0>* viewWidget = new mplot::qt::viswidget<0>(this->parentWidget());
    // Enable lighting effects
    viewWidget->v.lightingEffects();

    // Embed in main window layout
    this->ui->mainLayout->addWidget(viewWidget);
    // Store reference for later updates
    this->vwPtr = viewWidget;
}

void MainWindow::on_actionQuit_triggered() { close(); }

