int main()
{
    // Initialize the mplot::Visual scene with specified dimensions and title
    mplot::Visual scene(1024, 768, "Generated using mplot::GraphVisual");

    // Instantiate a GraphVisual object at origin (0,0,0)
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Essential initialization step: link parent and bind internal callbacks
    scene.bindmodel(graph);

    // Prepare x-axis data using vvec (vector-like container with math operations)
    sm::vvec<double> x_vals;
    x_vals.linspace(0, 10, 11);

    // Define y-axis data manually
    sm::vvec<double> y_vals = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure line plot style
    mplot::DatasetStyle line_style(mplot::stylepolicy::lines);
    line_style.linecolour = mplot::colour::crimson;

    // Set fixed y-axis range for visualization
    graph->setlimits_y(0, 10);

    // Assign data to the graph
    graph->setdata(x_vals, y_vals, line_style);

    // Create a second style for vertical reference lines
    mplot::DatasetStyle vert_line_style(mplot::stylepolicy::lines);
    vert_line_style.linecolour = mplot::colour::grey68;
    vert_line_style.linewidth = line_style.linewidth * 0.6f;

    // Compute and draw vertical lines where graph crosses x=3.3
    sm::vvec<double> crossing_ys = graph->add_x_crossing_lines(x_vals, y_vals, 3.3, line_style, vert_line_style);

    size_t count = crossing_ys.size();
    std::stringstream label_stream;

    if (count > 0) {
        // Format crossing points into readable string
        for (size_t idx = 0; idx < count; ++idx) {
            label_stream << std::format("{}{}{:.2f}", 
                ((idx == 0 || idx == count - 1) ? "" : ", "), 
                (idx == count - 1 ? " and " : ""), 
                crossing_ys[idx]);
        }
    } else {
        label_stream << "[no values]";
    }

    // Add descriptive label to the scene
    graph->addLabel(
        std::format("At x=3.3, y = {:s}", label_stream.str()), 
        {0.05f, 0.05f, 0.0f}, 
        mplot::TextFeatures(0.03f)
    );

    // Finalize graph geometry preparation for rendering
    graph->finalize();

    // Transfer ownership of graph to the visual scene
    scene.addVisualModel(graph);

    // Display window and wait for user exit command
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' goes out of scope
    return 0;
}

