namespace {
/// A plugin-based class that accepts multiple Plugin types.
/// Each plugin must implement:
///  1) a constructor accepting `Function &f` (typically scans for candidates)
///  2) a method with signature and name:
///        void execute(std::vector<SelectionInfo> &Selections);
///    which appends its findings to the provided vector.
///
/// Plugins are declared in ValueProfilePlugins.inc
template <class... Ts> class PluginSequence;
/// The type PluginSequenceFinal represents the finalized plugin chain used by
/// ValueProfileCollectorImpl.
using PluginSequenceFinal = PluginSequence<VP_PLUGIN_LIST>;

template <> class PluginSequence<> {
public:
  PluginSequence(Function &F, TargetLibraryInfo &TLI) {}
  void fetch(InstrProfValueKind K, std::vector<SelectionInfo> &Selections) {}
};

template <class PluginType, class... Ts>
class PluginSequence<PluginType, Ts...> : public PluginSequence<Ts...> {
  PluginType PluginInstance;
  using Parent = PluginSequence<Ts...>;
public:
  PluginSequence(Function &F, TargetLibraryInfo &TLI)
      : PluginSequence<Ts...>(F, TLI), PluginInstance(F, TLI) {}
  void fetch(InstrProfValueKind K, std::vector<SelectionInfo> &Selections) {
    if (K == PluginType::Category)
      PluginInstance.execute(Selections);
    Parent::fetch(K, Selections);
  }
};
} // end anonymous namespace

/// ValueProfileCollectorImpl extends the interface of PluginSequenceFinal.
class ValueProfileCollector::ValueProfileCollectorImpl : public PluginSequenceFinal {
public:
  using PluginSequenceFinal::PluginSequenceFinal;
};

ValueProfileCollector::ValueProfileCollector(Function &F,
                                             TargetLibraryInfo &TLI)
    : PImpl(new ValueProfileCollectorImpl(F, TLI)) {}

ValueProfileCollector::~ValueProfileCollector() = default;

std::vector<SelectionInfo>
ValueProfileCollector::fetch(InstrProfValueKind Category) const {
  std::vector<SelectionInfo> Output;
  PImpl->fetch(Category, Output);
  return Output;
}

