#include <iostream>
#include <vector>
#include <stepit/plugin.h>
#include <stepit/pyutils/npz_reader.h>
using namespace stepit;

// Display information about arrays in an NPZ file
int main(int argc, char **argv) {
  if (argc != 2) {
    std::cerr << "Usage: " << argv[0] << " <npz_file>" << std::endl;
    return 1;
  }

  try {
    NpzReader npz(argv[1]);

    // Initialize column width tracking variables
    std::size_t max_name_width     = 4;
    std::size_t max_shape_width    = 5;
    std::vector<std::string> var_names = npz.keys();
    std::vector<std::string> shape_strings;
    std::vector<std::string> dtype_strings;

    // Process each array to determine formatting widths and collect metadata
    for (const auto &key : var_names) {
      max_name_width = std::max(max_name_width, key.length());
      shape_strings.push_back(fmt::format("({})", fmt::join(npz[key].shape, ", ")));
      max_shape_width = std::max(max_shape_width, shape_strings.back().length());
      dtype_strings.push_back(npz[key].dtype);
    }

    // Add padding to column widths
    max_name_width += 2;
    max_shape_width += 2;

    // Print header row
    std::cout << fmt::format("{:<{}}{:<{}}{}\n", "Name", max_name_width, "Shape", max_shape_width, "Dtype")
              << std::string(max_name_width + max_shape_width + 15, '-') << std::endl;

    // Print data rows
    for (std::size_t idx{}; idx < var_names.size(); ++idx) {
      std::cout << fmt::format("{:<{}}{:<{}}{}", var_names[idx], max_name_width, 
                               shape_strings[idx], max_shape_width, dtype_strings[idx])
                << std::endl;
    }

  } catch (const std::exception &err) {
    std::cerr << kRed << "ERROR: " << kClear << err.what() << std::endl;
    return 1;
  }

  return 0;
}

