namespace roboplan {

using namespace nanobind::literals;

void bind_optimal_ik_components(nanobind::module_& m) {
    // Bind base Task class
    nanobind::class_<Task>(m, "Task", "Abstract base interface for IK tasks.")
        .def_ro("alpha", &Task::gain, "Gain parameter for exponential smoothing.")
        .def_ro("w_cost", &Task::weight, "Diagonal weight matrix for cost scaling.")
        .def_ro("mu_lm", &Task::lm_damping, "Levenberg-Marquardt regularization factor.")
        .def_ro("n_vars", &Task::num_variables, "Dimensionality of the optimization space.");

    // FrameTaskOptions configuration struct
    nanobind::class_<FrameTaskOptions>(m, "FrameTaskOptions", "Configuration parameters for pose-based tasks.")
        .def(nanobind::init<double, double, double, double>(), 
             "pos_weight"_a = 2.0,
             "ori_weight"_a = 1.5,
             "filter_gain"_a = 0.8,
             "lev_marq"_a = 0.01)
        .def_rw("pos_weight", &FrameTaskOptions::position_cost, "Relative importance of position tracking.")
        .def_rw("ori_weight", &FrameTaskOptions::orientation_cost, "Relative importance of orientation tracking.")
        .def_rw("filter_gain", &FrameTaskOptions::task_gain, "Smoothing factor for task updates.")
        .def_rw("lev_marq", &FrameTaskOptions::lm_damping, "Damping coefficient for numerical stability.");

    // FrameTask class
    nanobind::class_<FrameTask, Task>(m, "FrameTask",
                                      "Task to drive a specific frame to a desired pose.")
        .def(nanobind::init<const CartesianConfiguration&, int, const FrameTaskOptions&>(),
             "goal_transform"_a, "var_count"_a, "cfg"_a = FrameTaskOptions{})
        .def_ro("link_name", &FrameTask::frame_name, "Name of the kinematic link involved.")
        .def_ro("link_idx", &FrameTask::frame_id, "Internal index in the robot model.")
        .def_ro("goal", &FrameTask::target_pose, "Target SE(3) pose for the frame.")
        .def("setGoalTransform", &FrameTask::setTargetFrameTransform,
             "Update the desired transformation for this task.");

    // ConfigurationTaskOptions
    nanobind::class_<ConfigurationTaskOptions>(m, "ConfigurationTaskOptions",
                                               "Settings for joint-space tracking tasks.")
        .def(nanobind::init<double, double>(), 
             "eta"_a = 0.9,
             "lambda"_a = 1e-4)
        .def_rw("eta", &ConfigurationTaskOptions::task_gain, "Feedback gain for convergence.")
        .def_rw("lambda", &ConfigurationTaskOptions::lm_damping, "Regularization strength.");

    // ConfigurationTask class
    nanobind::class_<ConfigurationTask, Task>(m, "ConfigurationTask",
                                              "Task to steer joints toward a target configuration.")
        .def(nanobind::init<const Eigen::VectorXd&, const Eigen::VectorXd&,
                            const ConfigurationTaskOptions&>(),
             "desired_q"_a, "joint_scales"_a, "params"_a = ConfigurationTaskOptions{})
        .def_rw("desired_q", &ConfigurationTask::target_q, "Reference joint angles.")
        .def_rw("joint_scales", &ConfigurationTask::joint_weights,
                "Per-joint scaling factors for error weighting.");

    // Constraints base class
    nanobind::class_<Constraints>(m, "Constraints", "Base abstraction for IK feasibility conditions.");

    // PositionLimit constraint
    nanobind::class_<PositionLimit, Constraints>(m, "PositionLimit",
                                                 "Hard limits on joint positions.")
        .def(nanobind::init<int, double>(), "dim"_a, "k_pos"_a = 0.5)
        .def_rw("k_pos", &PositionLimit::config_limit_gain,
                "Proportional gain used when enforcing bounds.");

    // VelocityLimit constraint
    nanobind::class_<VelocityLimit, Constraints>(m, "VelocityLimit",
                                                 "Upper bound on joint velocities.")
        .def(nanobind::init<int, double, const Eigen::VectorXd&>(), "state_dim"_a, "step_dt"_a,
             "v_limits"_a)
        .def_rw("step_dt", &VelocityLimit::dt, "Discrete time step duration.")
        .def_rw("v_limits", &VelocityLimit::v_max, "Per-joint velocity caps.");

    // Oink solver binding
    nanobind::class_<Oink>(m, "Oink", "QP-based optimal inverse kinematics solver.")
        .def(nanobind::init<int>(), "num_dof"_a)
        .def(
            "computeDeltaQ",
            [](Oink& self, const std::vector<std::shared_ptr<Task>>& task_list,
               const std::vector<std::shared_ptr<Constraints>>& constraint_list,
               const std::shared_ptr<Scene>& world_state, nanobind::DRef<Eigen::VectorXd> dq_out,
               double reg_strength) {
              auto solution = self.solveIk(task_list, constraint_list, *world_state, dq_out, reg_strength);
              if (!solution.has_value()) {
                throw std::runtime_error("Optimization failed: " + solution.error());
              }
            },
            "tasks"_a, "constraints"_a, "scene"_a, "output_delta_q"_a, "ridge_param"_a = 1e-10,
            "Solves the constrained QP to obtain joint velocities.\n\n"
            "Minimizes a weighted sum of task errors subject to inequality/equality constraints.\n"
            "The solution vector is written directly into the provided output buffer.\n\n"
            "Parameters:\n"
            "  tasks: List of weighted objectives (e.g., FrameTask, ConfigurationTask).\n"
            "  constraints: Enforced physical or operational limits (e.g., PositionLimit).\n"
            "  scene: Current robot state and kinematic tree.\n"
            "  output_delta_q: Pre-sized numpy array (float64, contiguous) receiving the result.\n"
            "  ridge_param: Tikhonov term added to Hessian for invertibility.\n\n"
            "Raises:\n"
            "  RuntimeError if no feasible solution exists.");
}

