// Enable hash support for magic_enum
#define MAGIC_ENUM_ENABLE_HASH
#include <magic_enum/magic_enum_switch.hpp>

// Define a custom color enumeration
enum class Palette { YELLOW, PURPLE, ORANGE };

// Template function with default implementation
template <Palette P>
constexpr std::string_view ProcessValue() {
  return "base";
}

// Specialization for ORANGE
template <>
constexpr std::string_view ProcessValue<Palette::ORANGE>() {
  return "specialized";
}

// Helper type for the visitor pattern - renamed and slightly modified
template <typename... Funcs> struct visitor : Funcs... { using Funcs::operator()...; };
template <typename... Funcs> visitor(Funcs...) -> visitor<Funcs...>;

int main() {
  Palette p = Palette::YELLOW;

  // Lambda that uses the template function
  auto handler = [] (auto value) {
    std::cout << ProcessValue<value>() << std::endl;
  };

  // Apply enum switch with lambda
  magic_enum::enum_switch(handler, p); // prints "base"
  p = Palette::ORANGE;
  magic_enum::enum_switch(handler, p); // prints "specialized"

  // Visitor with explicit enum constants
  auto dispatcher1 = visitor{
    [] (magic_enum::enum_constant<Palette::PURPLE>) {
      std::cout << "Purple selected" << std::endl;
    },
    [] (magic_enum::enum_constant<Palette::YELLOW>) {
      std::cout << "Yellow selected" << std::endl;
    }
  };

  magic_enum::enum_switch(dispatcher1, Palette::ORANGE); // prints nothing
  magic_enum::enum_switch(dispatcher1, Palette::PURPLE); // prints "Purple selected"
  magic_enum::enum_switch(dispatcher1, Palette::YELLOW); // prints "Yellow selected"

  // Visitor with explicit return type and default case
  auto dispatcher2 = visitor{
    [] (magic_enum::enum_constant<Palette::ORANGE>) {
      return "orange branch";
    },
    [] (Palette other) { // fallback case
      auto name = magic_enum::enum_name(other);
      return "fallback: " + std::string{name};
    }
  };

  std::cout << magic_enum::enum_switch<std::string>(dispatcher2, Palette::ORANGE) << std::endl; // prints "orange branch"
  std::cout << magic_enum::enum_switch<std::string>(dispatcher2, Palette::YELLOW) << std::endl; // prints "fallback: YELLOW"

  // Test with invalid enum value
  auto empty_result = magic_enum::enum_switch<std::string>(dispatcher2, static_cast<Palette>(-5));
  assert(empty_result.empty());

  // Provide default value for invalid enum
  std::cout << magic_enum::enum_switch<std::string>(dispatcher2, static_cast<Palette>(-7), "unknown") << std::endl; // prints "unknown"

  // Visitor returning optional values
  auto dispatcher3 = visitor{
    [] (magic_enum::enum_constant<Palette::YELLOW>) -> std::optional<std::string> {
      return "yellow option";
    },
    [] (magic_enum::enum_constant<Palette::PURPLE>) -> std::optional<std::string> {
      return std::nullopt;
    }
  };

  std::cout << std::boolalpha;
  std::cout << magic_enum::enum_switch(dispatcher3, Palette::ORANGE, std::make_optional("default")).value() << std::endl; // prints default: "default"
  std::cout << magic_enum::enum_switch(dispatcher3, Palette::YELLOW, std::make_optional("default")).value() << std::endl; // prints: "yellow option"
  std::cout << magic_enum::enum_switch(dispatcher3, Palette::PURPLE, std::make_optional("default")).has_value() << std::endl; // prints: false

  return 0;
}

