// Minimal implementation for Linux in headless mode
// Avoids LGPL dependencies (GTK3, libappindicator3, libnotify)
// Recommended to launch the app with --no-tray on Linux systems
namespace lemon_tray {

LinuxTray::LinuxTray()
    : should_exit_(false)
{
    // No initialization required in headless mode
}

LinuxTray::~LinuxTray() {
    // No cleanup needed in headless mode
}

bool LinuxTray::initialize(const std::string& application_name, const std::string& icon_file) {
    app_name_ = application_name;
    icon_path_ = icon_file;

    LOG(DEBUG, "LinuxTray") << "Headless mode - system tray unavailable on Linux" << std::endl;
    LOG(DEBUG, "LinuxTray") << "Consider using --no-tray flag for headless execution" << std::endl;

    // Trigger ready callback immediately since no UI setup is necessary
    if (ready_callback_) {
        ready_callback_();
    }

    // Indicate tray is not functional by returning false
    // This prompts the application to switch to --no-tray behavior
    return false;
}

void LinuxTray::run() {
    LOG(DEBUG, "LinuxTray") << "Headless mode - no message loop active" << std::endl;
    // Intentionally empty in headless mode
}

void LinuxTray::stop() {
    LOG(DEBUG, "LinuxTray") << "Headless mode - shutdown initiated" << std::endl;
    should_exit_ = true;
}

void LinuxTray::set_menu(const Menu& menu) {
    LOG(DEBUG, "LinuxTray") << "Headless mode - skipping menu with "
    << menu.items.size() << " entries" << std::endl;
    // Intentionally empty in headless mode
}

void LinuxTray::update_menu() {
    LOG(DEBUG, "LinuxTray") << "Headless mode - ignoring menu update request" << std::endl;
    // Intentionally empty in headless mode
}

void LinuxTray::show_notification(
    const std::string& title,
    const std::string& content,
    NotificationType type)
{
    // Output notification to standard output instead of GUI
    LOG(INFO, "Notification") << title << ": " << content << std::endl;
}

void LinuxTray::set_icon(const std::string& icon_location) {
    icon_path_ = icon_location;
    LOG(DEBUG, "LinuxTray") << "Headless mode - ignoring icon change: " << icon_location << std::endl;
    // Intentionally empty in headless mode
}

void LinuxTray::set_tooltip(const std::string& hint_text) {
    LOG(DEBUG, "LinuxTray") << "Headless mode - ignoring tooltip: " << hint_text << std::endl;
    // Intentionally empty in headless mode
}

void LinuxTray::set_ready_callback(std::function<void()> callback) {
    ready_callback_ = callback;
}

} // namespace lemon_tray
#endif // __linux__ && !__ANDROID__

