#include <iostream>
#include <istream>
#include <ostream>
#include <string>
#include <asio.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cout << "Usage: http_client <hostname> <resource>\n";
      std::cout << "Example:\n";
      std::cout << "  http_client www.boost.org /LICENSE_1_0.txt\n";
      return 1;
    }

    asio::io_context context;

    // Resolve the server address
    tcp::resolver resolver(context);
    auto endpoints = resolver.resolve(argv[1], "http");

    // Create and connect socket
    tcp::socket socket(context);
    asio::connect(socket, endpoints);

    // Build HTTP GET request
    asio::streambuf req_buffer;
    std::ostream req_stream(&req_buffer);
    req_stream << "GET " << argv[2] << " HTTP/1.0\r\n";
    req_stream << "Host: " << argv[1] << "\r\n";
    req_stream << "Accept: */*\r\n";
    req_stream << "Connection: close\r\n\r\n";

    // Send the request
    asio::write(socket, req_buffer);

    // Read status line
    asio::streambuf resp_buffer;
    asio::read_until(socket, resp_buffer, "\r\n");

    // Parse and validate HTTP version and status code
    std::istream resp_stream(&resp_buffer);
    std::string version;
    resp_stream >> version;
    unsigned int code;
    resp_stream >> code;
    std::string msg;
    std::getline(resp_stream, msg);

    if (!resp_stream || version.substr(0, 5) != "HTTP/")
    {
      std::cout << "Invalid response\n";
      return 1;
    }

    if (code != 200)
    {
      std::cout << "Response returned with status code " << code << "\n";
      return 1;
    }

    // Read headers until blank line
    asio::read_until(socket, resp_buffer, "\r\n\r\n");

    // Print headers
    std::string line;
    while (std::getline(resp_stream, line) && line != "\r")
      std::cout << line << "\n";
    std::cout << "\n";

    // Output remaining data in buffer
    if (resp_buffer.size() > 0)
      std::cout << &resp_buffer;

    // Read remaining content until EOF
    asio::error_code err;
    while (asio::read(socket, resp_buffer,
          asio::transfer_at_least(1), err))
      std::cout << &resp_buffer;

    if (err != asio::error::eof)
      throw asio::system_error(err);
  }
  catch (std::exception& ex)
  {
    std::cout << "Error: " << ex.what() << "\n";
  }

  return 0;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxArea(std::vector<int>& heights) {
        // Find maximum water container area using two-pointer approach
        int size = heights.size();
        int left = 0;
        int right = size - 1;
        int bestArea = 0;

        while (left < right) {
            int currentWidth = right - left;
            int currentHeight = std::min(heights[left], heights[right]);
            int currentArea = currentWidth * currentHeight;

            bestArea = std::max(currentArea, bestArea);

            if (heights[left] < heights[right]) {
                left++;
            } else {
                right--;
            }
        }

        return bestArea;
    }
};

