Y_UNIT_TEST_SUITE(ColorizerTestSuite) {
    Y_UNIT_TEST(BasicFunctionalityTest) {
        NColorizer::TColors palette;
        palette.Enable();
        UNIT_ASSERT_STRINGS_EQUAL(EscapeC(palette.BlueColor()), "\\x1B[22;34m");
        UNIT_ASSERT_STRINGS_EQUAL(EscapeC(palette.ForeBlue()), "\\x1B[34m");
        palette.Disable();
        UNIT_ASSERT(palette.BlueColor().empty());
    }

    Y_UNIT_TEST(ResetBehaviorTest) {
        NColorizer::TColors palette;
        palette.Enable();
        // 22;39, not 0, should be used so that only foreground changes
        UNIT_ASSERT_STRINGS_EQUAL(EscapeC(palette.OldColor()), "\\x1B[22;39m");
        UNIT_ASSERT_STRINGS_EQUAL(EscapeC(palette.Reset()), "\\x1B[0m");
        // 22, not 0, should be used to reset boldness
        UNIT_ASSERT_STRINGS_EQUAL(EscapeC(palette.PurpleColor()), "\\x1B[22;35m");
    }

    Y_UNIT_TEST(AnsiOutputTest) {
        UNIT_ASSERT_STRINGS_EQUAL(EscapeC(ToString(NColorizer::BLUE)), "\\x1B[0m\\x1B[0;34m");
        {
            TString buffer;
            TStringOutput output{buffer};
            output << NColorizer::BLUE << "hello!" << NColorizer::RESET;
            UNIT_ASSERT_STRINGS_EQUAL(EscapeC(buffer), "hello!");  // TStringOutput is not tty
        }
        {
            TString buffer;
            TStringOutput output{buffer};
            // Enable this for test purposes. If you're making output of the `AutoColors` constant and this
            // test does not compile, you're free to remove it.
            NColorizer::AutoColors(output).Enable();
            output << NColorizer::BLUE << "hello!" << NColorizer::RESET;
            UNIT_ASSERT_STRINGS_EQUAL(EscapeC(buffer), "\\x1B[0m\\x1B[0;34mhello!\\x1B[0m");  // TStringOutput is not tty
        }
    }

    Y_UNIT_TEST(EscapeSequenceLengthTest) {
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("plain text"), 0);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text\033[0m more"), 4);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("\033[0mtext more"), 4);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text more\033[0m"), 4);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text\033[0;1;2;3m more"), 10);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text\033[0;1;2;3 more"), 0);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text\0330;1;2;3m more"), 0);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text [0;1;2;3m more"), 0);
        UNIT_ASSERT_VALUES_EQUAL(NColorizer::TotalAnsiEscapeCodeLen("text\033[m more"), 3);
    }
}

