#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
#include <iomanip>

// Use a fixed seed for deterministic behavior of the randomized algorithm
std::mt19937 random_gen(42);

void process() {
    int num_participants;
    int num_rounds;
    std::cin >> num_participants >> num_rounds;

    // Initial weights for each participant in the multiplicative weights update scheme
    std::vector<long double> participant_weights(num_participants, 1.0L);

    // Track error count per participant to handle scenarios where b=0
    std::vector<int> error_counts(num_participants, 0);

    for (int round = 0; round < num_rounds; ++round) {
        std::string predictions;
        std::cin >> predictions;
        int predicted_value;

        // Determine the smallest number of errors any participant has accumulated so far
        int least_errors = *std::min_element(error_counts.begin(), error_counts.end());

        // Combined Strategy:
        // If there exists at least one flawless predictor (zero errors), adopt their prediction.
        // This ensures zero errors when the top performer remains flawless (b=0).
        if (least_errors == 0) {
            int first_flawless_index = -1;
            for (int idx = 0; idx < num_participants; ++idx) {
                if (error_counts[idx] == 0) {
                    first_flawless_index = idx;
                    break;
                }
            }
            predicted_value = predictions[first_flawless_index] - '0';
        } else {
            // Otherwise, apply Randomized Weighted Majority approach
            long double weight_for_zero = 0.0L;
            long double weight_for_one = 0.0L;

            for (int idx = 0; idx < num_participants; ++idx) {
                if (predictions[idx] == '0') {
                    weight_for_zero += participant_weights[idx];
                } else {
                    weight_for_one += participant_weights[idx];
                }
            }

            long double combined_weight = weight_for_zero + weight_for_one;

            // Guard against potential underflow where all weights vanish
            if (combined_weight == 0.0L) {
                predicted_value = 0; // fallback prediction
            } else {
                long double probability_of_one = weight_for_one / combined_weight;
                std::uniform_real_distribution<long double> sampler(0.0L, 1.0L);
                if (sampler(random_gen) < probability_of_one) {
                    predicted_value = 1;
                } else {
                    predicted_value = 0;
                }
            }
        }

        std::cout << predicted_value << std::endl;

        int actual_result;
        std::cin >> actual_result;

        // Adjust error counts and weights according to the realized outcome
        for (int idx = 0; idx < num_participants; ++idx) {
            if ((predictions[idx] - '0') != actual_result) {
                error_counts[idx]++;
                // Reduce weight of incorrect predictors by half
                participant_weights[idx] *= 0.5L;
            }
        }
    }
}

