#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to record a swap operation between two positions
struct SwapAction {
    int r1, c1, r2, c2;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int ROWS = 30;

    // Pyramid represented as a vector of vectors
    vector<vector<int>> pyramid(ROWS);

    // Read input data into the pyramid structure
    for (int row = 0; row < ROWS; ++row) {
        pyramid[row].reserve(row + 1);
        for (int col = 0; col <= row; ++col) {
            int value;
            cin >> value;
            pyramid[row].push_back(value);
        }
    }

    vector<SwapAction> operations;
    // Pre-allocate space for operations (safe upper bound)
    operations.reserve(10000);

    // Build min-heap property from bottom to top
    // Start from second-last row and move upward
    for (int level = ROWS - 2; level >= 0; --level) {
        for (int index = 0; index <= level; ++index) {
            int current_row = level;
            int current_col = index;

            // Sift down the element at (current_row, current_col)
            while (current_row < ROWS - 1) {
                int child_row = current_row + 1;
                int left_child_col = current_col;
                int right_child_col = current_col + 1;

                int parent_val = pyramid[current_row][current_col];
                int left_val = pyramid[child_row][left_child_col];
                int right_val = pyramid[child_row][right_child_col];

                // Check if heap property holds: parent <= both children
                if (parent_val <= left_val && parent_val <= right_val) {
                    break;
                }

                // Swap with the smaller child to maintain min-heap property
                if (left_val <= right_val) {
                    operations.push_back({current_row, current_col, child_row, left_child_col});
                    swap(pyramid[current_row][current_col], pyramid[child_row][left_child_col]);
                    current_row = child_row;
                    current_col = left_child_col;
                } else {
                    operations.push_back({current_row, current_col, child_row, right_child_col});
                    swap(pyramid[current_row][current_col], pyramid[child_row][right_child_col]);
                    current_row = child_row;
                    current_col = right_child_col;
                }
            }
        }
    }

    // Print number of swaps followed by each swap operation
    cout << operations.size() << "\n";
    for (const auto& action : operations) {
        cout << action.r1 << " " << action.c1 << " " << action.r2 << " " << action.c2 << "\n";
    }

    return 0;
}

