	void FiberPool::InitializeImplementation(int fiber_count)
	{
		for (std::size_t index = 0; index < fiber_count; ++index)
		{
			ScriptMgr::AddScript(std::make_unique<Script>(&FiberWorker));
		}
	}

	void FiberPool::CleanupImplementation()
	{
		std::lock_guard<std::mutex> guard(m_Mutex);
		while (!m_Jobs.empty())
			m_Jobs.pop();
	}

	void FiberPool::EnqueueTask(std::function<void()> task)
	{
		std::lock_guard<std::mutex> guard(m_Mutex);
		m_Jobs.push(std::move(task));
	}

	void FiberPool::ProcessNextJob()
	{
		std::unique_lock<std::mutex> guard(m_Mutex);
		if (!m_Jobs.empty())
		{
			auto current_task = std::move(m_Jobs.top());
			m_Jobs.pop();
			guard.unlock();
			std::invoke(std::move(current_task));
		}
	}

	void FiberPool::FiberWorker()
	{
		while (g_Running)
		{
			FiberPool::GetSingleton().ProcessNextJob();
			ScriptMgr::Yield();
		}
	}
}

#include <asio/dispatch.hpp>
#include <asio/execution_context.hpp>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <queue>

using asio::dispatch;
using asio::execution_context;

class task_scheduler : public execution_context
{
public:
  // A class that satisfies the Executor requirements.
  class executor_type
  {
  public:
    executor_type(task_scheduler& ctx, int level) noexcept
      : context_(ctx), priority_level_(level)
    {
    }

    task_scheduler& context() const noexcept
    {
      return context_;
    }

    void on_work_started() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }

    void on_work_finished() const noexcept
    {
      // This executor doesn't count work. Instead, the scheduler simply runs
      // until explicitly stopped.
    }

    template <class Func, class Alloc>
    void dispatch(Func&& f, const Alloc& a) const
    {
      enqueue(std::forward<Func>(f), a);
    }

    template <class Func, class Alloc>
    void enqueue(Func f, const Alloc& a) const
    {
      auto p(std::allocate_shared<task_item<Func>>(
            typename std::allocator_traits<
              Alloc>::template rebind_alloc<char>(a),
            priority_level_, std::move(f)));
      std::lock_guard<std::mutex> guard(context_.mutex_);
      context_.tasks_.push(p);
      context_.notify_.notify_one();
    }

    template <class Func, class Alloc>
    void defer(Func&& f, const Alloc& a) const
    {
      enqueue(std::forward<Func>(f), a);
    }

    friend bool operator==(const executor_type& left,
        const executor_type& right) noexcept
    {
      return &left.context_ == &right.context_;
    }

    friend bool operator!=(const executor_type& left,
        const executor_type& right) noexcept
    {
      return &left.context_ != &right.context_;
    }

  private:
    task_scheduler& context_;
    int priority_level_;
  };

  executor_type get_executor(int level = 0) noexcept
  {
    return executor_type(*const_cast<task_scheduler*>(this), level);
  }

  void start()
  {
    std::unique_lock<std::mutex> lock(mutex_);
    for (;;)
    {
      notify_.wait(lock, [&]{ return shutdown_ || !tasks_.empty(); });
      if (shutdown_)
        return;
      auto p(tasks_.top());
      tasks_.pop();
      lock.unlock();
      p->run_(p);
      lock.lock();
    }
  }

  void finish()
  {
    std::lock_guard<std::mutex> lock(mutex_);
    shutdown_ = true;
    notify_.notify_all();
  }

private:
  struct base_task
  {
    int priority_level_;
    void (*run_)(std::shared_ptr<base_task>&);
  };

  template <class Func>
  struct task_item : base_task
  {
    task_item(int pri, Func f) : callback_(std::move(f))
    {
      priority_level_ = pri;
      run_ = [](std::shared_ptr<base_task>& ptr)
      {
        Func temp(std::move(static_cast<task_item*>(ptr.get())->callback_));
        ptr.reset();
        temp();
      };
    }
    Func callback_;
  };

  struct task_comparator
  {
    bool operator()(
        const std::shared_ptr<base_task>& first,
        const std::shared_ptr<base_task>& second)
    {
      return first->priority_level_ < second->priority_level_;
    }
  };

  std::mutex mutex_;
  std::condition_variable notify_;
  std::priority_queue<
    std::shared_ptr<base_task>,
    std::vector<std::shared_ptr<base_task>>,
    task_comparator> tasks_;
  bool shutdown_ = false;
};

int main()
{
  task_scheduler sched;
  auto low_priority = sched.get_executor(0);
  auto medium_priority = sched.get_executor(1);
  auto high_priority = sched.get_executor(2);

  dispatch(low_priority, []{ std::cout << "A\n"; });
  dispatch(low_priority, []{ std::cout << "AA\n"; });
  dispatch(medium_priority, []{ std::cout << "B\n"; });
  dispatch(medium_priority, []{ std::cout << "BB\n"; });
  dispatch(high_priority, []{ std::cout << "C\n"; });
  dispatch(high_priority, []{ std::cout << "CC\n"; });
  dispatch(high_priority, []{ std::cout << "CCC\n"; });
  dispatch(sched.get_executor(-1), [&]{ sched.finish(); });

  sched.start();
}

