#include "Buffer.h"

Buffer::Buffer(unsigned int size) : m_capacity(size), m_position(0), m_limit(size), hasBackingArray(false)
{
}

// Resets this buffer. The position is set to zero, the limit is set to the capacity, and the mark is discarded.
// This method does not actually erase the data in the buffer, but it is named as if it did because it will most often
// be used in situations in which that might as well be the case.
//
// Returns:
// This buffer
Buffer* Buffer::clear()
{
    m_position = 0;
    m_limit = m_capacity;
    return this;
}

// Establishes this buffer's limit. If the position exceeds the new limit then it is adjusted to the new limit.
// If the mark is defined and exceeds the new limit then it is removed.
// Parameters:
// newLimit - The new limit value; must be non-negative and no larger than this buffer's capacity
// Returns:
// This buffer
Buffer* Buffer::limit(unsigned int newLimit)
{
    assert(newLimit <= m_capacity);
    m_limit = newLimit;
    if (m_position > newLimit)
        m_position = newLimit;
    return this;
}

unsigned int Buffer::limit()
{
    return m_limit;
}

// Sets this buffer's position. If the mark is defined and larger than the new position then it is discarded.
// Parameters:
// newPos - The new position value; must be non-negative and no larger than the current limit
// Returns:
// This buffer
Buffer* Buffer::position(unsigned int newPos)
{
    assert(newPos <= m_limit);
    m_position = newPos;
    return this;
}

// Retrieves this buffer's position.
// Returns:
// The position of this buffer
unsigned int Buffer::position()
{
    return m_position;
}

// Computes the count of elements between the current position and the limit.
// Returns:
// The number of elements remaining in this buffer
unsigned int Buffer::remaining()
{
    return m_limit - m_position;
}

