        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
    }
    SECTION("Enable/disable single level") {
        log::enableLevel(Lvl::Debug);
        REQUIRE(log::isLevelEnabled(Lvl::Debug));
        log::disableLevel(Lvl::Debug);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Debug));
    }
    SECTION("Sticky behavior") {
        log::enableLevel<true>(Lvl::Info);
        REQUIRE(log::isLevelEnabled(Lvl::Info));
        log::disableAllLevels();
        REQUIRE(log::isLevelEnabled(Lvl::Info));
        log::disableLevel(Lvl::Info);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Info));
    }
    SECTION("Multiple enable calls") {
        log::enableLevel(Lvl::Trace, Lvl::Trace);
        log::disableLevel(Lvl::Network);
        REQUIRE(log::isLevelEnabled(Lvl::Trace, Lvl::Trace));
        REQUIRE(log::isLevelEnabled(Lvl::Trace));
        REQUIRE(log::isLevelEnabled(Lvl::Trace));
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Trace, Lvl::Trace, Lvl::Network));
        SECTION("Multiple disable calls") {
            log::disableLevel(Lvl::Trace, Lvl::Trace, Lvl::Network);
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Trace, Lvl::Trace));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Trace));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Trace));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Trace, Lvl::Trace, Lvl::Network));
        }
    }
    SECTION("Multiple name-based enable") {
        log::enableLevel("TRACE", "TRACE");
        log::disableLevel("IO");
        REQUIRE(log::isLevelEnabled("TRACE", "TRACE"));
        REQUIRE(log::isLevelEnabled("TRACE"));
        REQUIRE(log::isLevelEnabled("TRACE"));
        REQUIRE_FALSE(log::isLevelEnabled("TRACE", "TRACE", "IO"));
        SECTION("Multiple name-based disable") {
            log::disableLevel("TRACE", "TRACE", "IO");
            REQUIRE_FALSE(log::isLevelEnabled("TRACE", "TRACE"));
            REQUIRE_FALSE(log::isLevelEnabled("TRACE"));
            REQUIRE_FALSE(log::isLevelEnabled("TRACE"));
            REQUIRE_FALSE(log::isLevelEnabled("TRACE", "TRACE", "IO"));
        }
    }
    SECTION("Name-based enable with leading/trailing spaces") {
        log::enableLevel(" TRACE", "TRACE ");
        log::disableLevel(" IO");
        REQUIRE(log::isLevelEnabled("TRACE", "TRACE"));
        REQUIRE(log::isLevelEnabled("TRACE"));
        REQUIRE(log::isLevelEnabled("TRACE"));
        REQUIRE_FALSE(log::isLevelEnabled("TRACE", "TRACE", "IO"));
        SECTION(
            "Name-based disable with leading/trailing spaces") {
            log::disableLevel(" TRACE ", " TRACE ", " IO ");
            REQUIRE_FALSE(log::isLevelEnabled("TRACE", "TRACE"));
            REQUIRE_FALSE(log::isLevelEnabled("TRACE"));
            REQUIRE_FALSE(log::isLevelEnabled("TRACE"));
            REQUIRE_FALSE(log::isLevelEnabled("TRACE", "TRACE", "IO"));
        }
    }
}

