#include <iostream>
using namespace std;

/*
 Definition for singly-linked list.
*/
struct ListNode {
     int val;
     ListNode *next;
     ListNode() : val(0), next(nullptr) {}
     ListNode(int x) : val(x), next(nullptr) {}
     ListNode(int x, ListNode *next) : val(x), next(next) {}
 };

class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        // Base case: If the list is empty or has only one node, no swap needed.
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        // Initialize a dummy node to help with head swapping
        ListNode* sentinel = new ListNode(0);
        sentinel->next = head;

        ListNode* previous = sentinel;  // Pointer to the node before the pair to be swapped
        ListNode* current = head;       // Pointer to the current node
        while (current != nullptr && current->next != nullptr) {
            ListNode* first = current;          // First node of the pair
            ListNode* second = current->next;   // Second node of the pair

            // Swap the pair
            previous->next = second;            // Connect previous node to the second node
            first->next = second->next;         // Connect first node to the next node after the pair
            second->next = first;               // Connect second node to the first node

            // Move pointers forward for the next pair
            previous = first;                   // Move previous to the first node of the current pair
            current = first->next;              // Move current to the next pair's first node
        }
        return sentinel->next;  // Return the new head of the list
    }
};

