using namespace std; // Required for memcmp, memcpy, and memset

class custom_stream
{
public:
  typedef asio::io_context io_context_type;
  typedef custom_stream lowest_layer_type;
  typedef io_context_type::executor_type executor_type;

  custom_stream(asio::io_context& ctx)
    : context_(ctx)
  {
  }

  io_context_type& io_context()
  {
    return context_;
  }

  lowest_layer_type& lowest_layer()
  {
    return *this;
  }

  template <typename Const_Buffers>
  size_t write(const Const_Buffers&)
  {
    return 0;
  }

  template <typename Const_Buffers>
  size_t write(const Const_Buffers&, asio::error_code& ec)
  {
    ec = asio::error_code();
    return 0;
  }

  template <typename Const_Buffers, typename Handler>
  void async_write(const Const_Buffers&, Handler handler)
  {
    asio::error_code error;
    asio::post(context_,
        asio::detail::bind_handler(handler, error, 0));
  }

  template <typename Mutable_Buffers>
  size_t read(const Mutable_Buffers&)
  {
    return 0;
  }

  template <typename Mutable_Buffers>
  size_t read(const Mutable_Buffers&, asio::error_code& ec)
  {
    ec = asio::error_code();
    return 0;
  }

  template <typename Mutable_Buffers, typename Handler>
  void async_read(const Mutable_Buffers&, Handler handler)
  {
    asio::error_code error;
    asio::post(context_,
        asio::detail::bind_handler(handler, error, 0));
  }

private:
  io_context_type& context_;
};

void check_write_buffered_property()
{
  ASIO_CHECK(!asio::is_write_buffered<
      asio::ip::tcp::socket>::value);
  ASIO_CHECK(!asio::is_write_buffered<
      asio::buffered_read_stream<
        asio::ip::tcp::socket> >::value);
  ASIO_CHECK(!!asio::is_write_buffered<
      asio::buffered_write_stream<
        asio::ip::tcp::socket> >::value);
  ASIO_CHECK(!!asio::is_write_buffered<
      asio::buffered_stream<asio::ip::tcp::socket> >::value);
  ASIO_CHECK(!asio::is_write_buffered<custom_stream>::value);
  ASIO_CHECK(!asio::is_write_buffered<
      asio::buffered_read_stream<custom_stream> >::value);
  ASIO_CHECK(!!asio::is_write_buffered<
      asio::buffered_write_stream<custom_stream> >::value);
  ASIO_CHECK(!!asio::is_write_buffered<
      asio::buffered_stream<custom_stream> >::value);
}

ASIO_TEST_SUITE
(
  "is_write_buffered",
  ASIO_TEST_CASE(check_write_buffered_property)
)

