/**
 * @brief Execute the `tri_inv_col_sweep` kernel for half-precision floating-point type.
 *
 * @param [in] input_ptr Pointer to the input data buffer.
 * @param [in] output_ptr Pointer to the output data buffer.
 * @param [in] tiling_param Pointer to the tiling configuration in global memory.
 */
extern "C" __global__ __aicore__ void tri_inv_col_sweep_fp16(GM_ADDR input_ptr, GM_ADDR output_ptr, GM_ADDR tiling_param)
{
    sglang::npu_kernel::TriInvColumnSweepTiling tiling_config;
    sglang::npu_kernel::GetTilingData(&tiling_config, tiling_param);
    sglang::npu_kernel::run_tri_inv_col_sweep<half>(input_ptr, output_ptr, tiling_config.num_elems, tiling_config.matrix_size);
}

/**
 * @brief Execute the `tri_inv_col_sweep` kernel for single-precision floating-point type.
 *
 * @param [in] input_ptr Pointer to the input data buffer.
 * @param [in] output_ptr Pointer to the output data buffer.
 * @param [in] tiling_param Pointer to the tiling configuration in global memory.
 */
extern "C" __global__ __aicore__ void tri_inv_col_sweep_fp32(GM_ADDR input_ptr, GM_ADDR output_ptr, GM_ADDR tiling_param)
{
    sglang::npu_kernel::TriInvColumnSweepTiling tiling_config;
    sglang::npu_kernel::GetTilingData(&tiling_config, tiling_param);
