#include <iostream>

class SavingsAccount {
private:
    double accountBalance;
    mutable int balanceCheckCount;  // this counter needs to increment during constant operations like balance checks, so we declare it mutable
    int activityCount;              // this should only change in non-constant methods
    mutable int totalInteractions;  // this should increment across all method calls
public:
    SavingsAccount() : SavingsAccount(0.0) {}
    explicit SavingsAccount(double openingBalance) : accountBalance(openingBalance), balanceCheckCount(0), activityCount(0), totalInteractions(0) {}

    // Constant member function to retrieve current balance
    double viewBalance() const {
        ++balanceCheckCount;   // permitted due to mutable specifier
        ++totalInteractions;   // also allowed since totalInteractions is mutable
        std::cout << "[BALANCE QUERY] Check number: " << balanceCheckCount << std::endl;
        return accountBalance;
    }

    // Non-constant member function to add funds
    void addFunds(double depositAmount) {
        ++totalInteractions;
        if (depositAmount > 0) {
            accountBalance += depositAmount;
            ++activityCount;
            std::cout << "[DEPOSIT] Value: $" << depositAmount << " | Cumulative Activities: " << activityCount << std::endl;
        }
    }

    // Non-constant member function to remove funds
    void subtractFunds(double withdrawalAmount) {
        ++totalInteractions;
        if (withdrawalAmount > 0 && withdrawalAmount <= accountBalance) {
            accountBalance -= withdrawalAmount;
            ++activityCount;
            std::cout << "[WITHDRAWAL] Value: $" << withdrawalAmount << " | Cumulative Activities: " << activityCount << std::endl;
        } else {
            std::cout << "[WITHDRAWAL] Not enough funds available!" << std::endl;
        }
    }

    // Show summary statistics
    void displaySummary() const {
        ++totalInteractions;   // allowed because totalInteractions is mutable
        std::cout << "Total Operations: " << totalInteractions << std::endl;
        std::cout << "Balance Queries: " << balanceCheckCount << " | Transaction Count: " << activityCount << std::endl;
    }
};

int main() {
    SavingsAccount wallet(1000.0);

    // Querying balance several times (const operation)
    std::cout << "Current Balance: $" << wallet.viewBalance() << std::endl;
    std::cout << "Current Balance: $" << wallet.viewBalance() << std::endl;

    // Executing financial operations
    wallet.addFunds(500);
    wallet.subtractFunds(300);
    wallet.subtractFunds(1500);

    // Additional balance queries
    std::cout << "Current Balance: $" << wallet.viewBalance() << std::endl;

    // Output summary data
    wallet.displaySummary();

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

// Approximate LCS using greedy skip-cost minimization
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string str1, str2;
    if (!(cin >> str1 >> str2)) return 0;

    int len1 = (int)str1.size();
    int len2 = (int)str2.size();

    // Precompute positions for each character (ASCII range)
    vector<int> charPositions1[128];
    vector<int> charPositions2[128];

    for (int idx = 0; idx < len1; ++idx) {
        unsigned char ch = (unsigned char)str1[idx];
        charPositions1[ch].push_back(idx);
    }
    for (int idx = 0; idx < len2; ++idx) {
        unsigned char ch = (unsigned char)str2[idx];
        charPositions2[ch].push_back(idx);
    }

    // Track current position in each character's position list
    vector<int> cursor1(128, 0);
    vector<int> cursor2(128, 0);

    string result;
    result.reserve(min(len1, len2));

    int i = 0, j = 0;
    const int BIG_NUMBER = 2000000000;

    while (i < len1 && j < len2) {
        unsigned char c1 = (unsigned char)str1[i];
        unsigned char c2 = (unsigned char)str2[j];

        if (c1 == c2) {
            result += static_cast<char>(c1);
            ++i;
            ++j;
        } else {
            // Find next occurrence of c1 in str2 starting from j
            int nextPos_c1_in_str2 = -1;
            while (cursor2[c1] < (int)charPositions2[c1].size() && 
                   charPositions2[c1][cursor2[c1]] < j) {
                ++cursor2[c1];
            }
            if (cursor2[c1] < (int)charPositions2[c1].size()) {
                nextPos_c1_in_str2 = charPositions2[c1][cursor2[c1]];
            }

            // Find next occurrence of c2 in str1 starting from i
            int nextPos_c2_in_str1 = -1;
            while (cursor1[c2] < (int)charPositions1[c2].size() && 
                   charPositions1[c2][cursor1[c2]] < i) {
                ++cursor1[c2];
            }
            if (cursor1[c2] < (int)charPositions1[c2].size()) {
                nextPos_c2_in_str1 = charPositions1[c2][cursor1[c2]];
            }

            int cost1 = (nextPos_c1_in_str2 == -1) ? BIG_NUMBER : (nextPos_c1_in_str2 - j);
            int cost2 = (nextPos_c2_in_str1 == -1) ? BIG_NUMBER : (nextPos_c2_in_str1 - i);

            if (cost1 == BIG_NUMBER && cost2 == BIG_NUMBER) {
                // Neither character appears later in the other string
                ++i;
                ++j;
            } else if (cost1 <= cost2) {
                result += static_cast<char>(c1);
                ++i;
                j = nextPos_c1_in_str2 + 1;
            } else {
                result += static_cast<char>(c2);
                i = nextPos_c2_in_str1 + 1;
                ++j;
            }
        }
    }

    cout << result << '\n';
    return 0;
}

