namespace {
    void PerformMadvise(int option, const void* start, size_t length) {
        static const size_t blocksize = NSystemInfo::GetPageSize();
        void* aligned_start = AlignDown(const_cast<void*>(start), blocksize);
        length = AlignUp(length, blocksize);

#if defined(_win_)
        if (!VirtualFree((LPVOID)aligned_start, length, option)) {
            TString error_message(LastSystemErrorText());
            ythrow yexception() << "VirtualFree(" << aligned_start << ", " << length << ", " << option << ")"
                                << " failed with error: " << error_message;
        }
#else
        if (-1 == madvise(aligned_start, length, option)) {
            TString error_message(LastSystemErrorText());
            ythrow yexception() << "madvise(" << aligned_start << ", " << length << ", " << option << ")"
                                << " failed with error: " << error_message;
        }
#endif
    }
} // namespace

void MadviseSequentialAccess(const void* address, size_t bytes) {
#if !defined(_win_)
    PerformMadvise(MADV_SEQUENTIAL, address, bytes);
#endif
}

void MadviseSequentialAccess(TArrayRef<const char> buffer) {
    MadviseSequentialAccess(buffer.data(), buffer.size());
}

