// Interface and visualization objects for robot geometry and collision checking
std::unique_ptr<PinocchioInterface> robotInterface;
std::shared_ptr<PinocchioGeometryInterface> collisionInterface;
std::unique_ptr<GeometryInterfaceVisualization> visualizer;
sensor_msgs::JointState lastJointState;
std::unique_ptr<ros::Publisher> distancePub;

// Callback function to process incoming joint state messages
void jointStateCallback(sensor_msgs::JointStateConstPtr msg) {
  // Skip if no change in joint positions
  if (lastJointState.position == msg->position) {
    return;
  }

  // Update stored joint state
  lastJointState.position = msg->position;

  // Construct configuration vector q: first 3 entries are base pose (fixed to zero), next 6 are arm joints
  Eigen::VectorXd q(9);
  q << 0.0, 0.0, 0.0,
       lastJointState.position[0],
       lastJointState.position[1],
       lastJointState.position[2],
       lastJointState.position[3],
       lastJointState.position[4],
       lastJointState.position[5];

  // Publish current self-collision distances
  visualizer->publishDistances(q);
}

int main(int argc, char** argv) {
  // Initialize ROS node
  ros::init(argc, argv, "collision_distance_viz");
  ros::NodeHandle nh;

  // Load required parameters from ROS parameter server
  std::string urdfPath, taskFile;
  nh.getParam("/task_file", taskFile);
  nh.getParam("/robot_urdf", urdfPath);

  // Load task configuration using property tree
  boost::property_tree::ptree configTree;
  boost::property_tree::read_info(taskFile, configTree);

  // Extract manipulator model type
  ManipulatorModelType robotModelType = mobile_manipulator::loadManipulatorType(taskFile, "model_information.manipulatorModelType");

  // Load list of joints to be removed/fixed
  std::vector<std::string> fixedJointNames;
  loadData::loadStdVector<std::string>(taskFile, "model_information.removeJoints", fixedJointNames, true);

  // Get base frame name
  std::string referenceFrame;
  loadData::loadPtreeValue<std::string>(configTree, referenceFrame, "model_information.baseFrame", false);

  // Build Pinocchio interface based on URDF and model type
  robotInterface.reset(new PinocchioInterface(::ocs2::mobile_manipulator::createPinocchioInterface(urdfPath, robotModelType)));

  // Print model info to stderr for debugging
  std::cerr << "\n #### Robot Model Configuration:";
  std::cerr << "\n #### =============================================================================\n";
  std::cerr << "\n #### manipulatorModelType: " << static_cast<int>(robotModelType);
  std::cerr << "\n #### removeJoints: ";
  for (const auto& name : fixedJointNames) {
    std::cerr << "\"" << name << "\" ";
  }
  std::cerr << "\n #### baseFrame: \"" << referenceFrame << "\"";

  // Load self-collision pair definitions
  std::vector<std::pair<size_t, size_t>> objectCollisionPairs;
  std::vector<std::pair<std::string, std::string>> linkCollisionPairs;
  loadData::loadStdVectorOfPair(taskFile, "selfCollision.collisionObjectPairs", objectCollisionPairs);
  loadData::loadStdVectorOfPair(taskFile, "selfCollision.collisionLinkPairs", linkCollisionPairs);

  // Print loaded collision pairs
  std::cerr << "\nLoaded collision object pairs: ";
  for (const auto& p : objectCollisionPairs) {
    std::cerr << "[" << p.first << ", " << p.second << "] ";
  }
  std::cerr << "\nLoaded collision link pairs: ";
  for (const auto& p : linkCollisionPairs) {
    std::cerr << "[" << p.first << ", " << p.second << "] ";
  }
  std::cerr << std::endl;

  // Initialize geometry interface with collision pairs
  collisionInterface.reset(new PinocchioGeometryInterface(*robotInterface, linkCollisionPairs, objectCollisionPairs));

  // Initialize visualization component
  visualizer.reset(new GeometryInterfaceVisualization(*robotInterface, *collisionInterface, nh, referenceFrame));

  // Subscribe to joint states topic
  ros::Subscriber sub = nh.subscribe("joint_states", 1, &jointStateCallback);

  // Run ROS spin loop
  ros::spin();

  return 0;
}

