    std::for_each(std::execution::par_unseq, data.cbegin(), data.cend(), [](int value) {
        std::cout << value;
    });
    std::cout << " std::execution::par_unseq" << std::endl;

#if __has_include(<poolstl/variant_policy.hpp>)
    for (bool flag : {true, false}) {
        std::for_each(std_par_if(flag), data.cbegin(), data.cend(), [](int value) {
            std::cout << value;
        });
