#include "layoutmanager.hpp"

// Constructor for Rect structure
Rect::Rect(float posX, float posY, float sizeW, float sizeH) : x(posX), y(posY), width(sizeW), height(sizeH) { }

// LayoutManager constructor initializing with initial rectangle
LayoutManager::LayoutManager(float posX, float posY, float sizeW, float sizeH) : m_current(posX, posY, sizeW, sizeH) {
}

// Returns the current layout rectangle
const Rect& LayoutManager::current() const {
    return m_current;
}

// Creates a copy of the current LayoutManager state
LayoutManager LayoutManager::copy() const {
    return LayoutManager(m_current.x, m_current.y, m_current.width, m_current.height);
}

// Apply uniform padding on all sides
void LayoutManager::pad(float amount) {
    pad(amount, amount);
}

// Apply vertical and horizontal padding separately
void LayoutManager::pad(float verticalPadding, float horizontalPadding) {
    m_current.x += horizontalPadding;
    m_current.y += verticalPadding;
    m_current.width -= horizontalPadding * 2;
    m_current.height -= verticalPadding * 2;
}

// Add padding to the left side only
void LayoutManager::padLeft(float amount) {
    m_current.x += amount;
    m_current.width -= amount;
}

// Add padding to the right side only
void LayoutManager::padRight(float amount) {
    m_current.width -= amount;
}

// Add padding to the top side only
void LayoutManager::padUp(float amount) {
    m_current.y += amount;
    m_current.height -= amount;
}

// Add padding to the bottom side only
void LayoutManager::padDown(float amount) {
    m_current.height -= amount;
}

// Apply border inset on all sides
void LayoutManager::border(float thickness) {
    m_current.x += thickness;
    m_current.y += thickness;
    m_current.width -= thickness * 2;
    m_current.height -= thickness * 2;
}

// Create horizontal gap by shifting x and reducing width
void LayoutManager::gapX(float spacing) {
    m_current.x += spacing;
    m_current.width -= spacing;
}

// Create vertical gap by shifting y and reducing height
void LayoutManager::gapY(float spacing) {
    m_current.y += spacing;
    m_current.height -= spacing;
}

// Slice off a top portion of specified height
LayoutManager LayoutManager::sliceTop(float sliceHeight) {
    LayoutManager result(m_current.x, m_current.y, m_current.width, sliceHeight);
    m_current.y += sliceHeight;
    m_current.height -= sliceHeight;
    return result;
}

// Slice off a left portion of specified width
LayoutManager LayoutManager::sliceLeft(float sliceWidth) {
    LayoutManager result(m_current.x, m_current.y, sliceWidth, m_current.height);
    m_current.x += sliceWidth;
    m_current.width -= sliceWidth;
    return result;
}

