namespace Gorgon::Utils {
    void CrashHandler::Backtrace() {
        // Generate stack trace, adjusting for internal frames
        auto stackTrace = cpptrace::generate_trace(skip + 3);

        auto terminal = StdConsole();
        int currentFrame = 0;
        for (const auto& entry : stackTrace.frames) {
            // Extract directory and filename for cleaner display
            std::string fullPath = String::Replace(entry.filename, "\\", "/");
            std::string pathDir = Filesystem::GetDirectory(fullPath);
            if (!pathDir.empty() && *pathDir.rbegin() == '/') {
                pathDir.pop_back();
            }
            std::string dirName = Filesystem::GetFilename(pathDir);
            std::string fileName = Filesystem::GetFilename(fullPath);

            terminal.SetColor(Console::Magenta);

            // Emphasize the frame right after the assertion point
            if (currentFrame == 1) {
                terminal.SetBold(true);
            }

            std::cout << "  [" << currentFrame << "] ";
            terminal.SetBold(false);
            terminal.SetColor(Console::Default);

            if (!entry.symbol.empty()) {
                std::cout << "  In function ";
                terminal.SetColor(Console::Yellow);
                std::cout << entry.symbol << " ";
            }

            terminal.SetColor(Console::Default);
            std::cout << "at ";

            if (currentFrame == 1) {
                terminal.SetColor(Console::Red);
            }

            std::cout << "..." << dirName << "/" << fileName;
            terminal.SetBold(true);

            if (entry.line.has_value()) {
                std::cout << ":" << entry.line.value();
            } else {
                std::cout << ":??";
            }

            std::cout << std::endl;
            terminal.Reset();
            currentFrame++;

            if (currentFrame >= maxDepth) break;
        }
    }

    struct CrashHandler::dumponlytag CrashHandler::DumpOnlyTag;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <cmath>
#include <algorithm>

// Solve the problem with two-phase querying strategy
void process() {
    // Initial query: send 100000 words each of length 1
    std::cout << "? 100000";
    for (int idx = 0; idx < 100000; ++idx) {
        std::cout << " 1";
    }
    std::cout << std::endl;

    long long response1;
    std::cin >> response1;

    if (response1 == -1) { // Handle error condition
        return;
    }

    if (response1 == 1) {
        std::cout << "! 100000" << std::endl;
        return;
    }

    // Compute bounds for word length based on first response
    long long lower_bound = (100000LL + response1 - 1) / response1;
    long long upper_bound = (100000LL - 1) / (response1 - 1);

    if (lower_bound == upper_bound) {
        std::cout << "! " << lower_bound << std::endl;
        return;
    }

    // Second query: construct article to determine exact word count
    long long range_size = upper_bound - lower_bound + 1;
    long long query_size = 2 * (range_size - 1);

    std::cout << "? " << query_size;
    for (long long step = 1; step < range_size; ++step) {
        std::cout << " " << lower_bound << " " << step;
    }
    std::cout << std::endl;

    long long response2;
    std::cin >> response2;

    if (response2 == -1) { // Handle error condition
        return;
    }

    // Derive final answer from second response
    long long result = 2 * upper_bound - lower_bound - response2;
    std::cout << "! " << result << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

