Y_UNIT_TEST_SUITE(TSpinLockTests) {
    template <typename TLockType>
    void ValidateLockBehavior() {
        TLockType mutex;
        UNIT_ASSERT(!mutex.IsLocked());
        mutex.Acquire();
        UNIT_ASSERT(mutex.IsLocked());
        mutex.Release();
        UNIT_ASSERT(!mutex.IsLocked());
        UNIT_ASSERT(mutex.TryAcquire());
        UNIT_ASSERT(mutex.IsLocked());
        UNIT_ASSERT(!mutex.TryAcquire());
        UNIT_ASSERT(mutex.IsLocked());
        mutex.Release();
        UNIT_ASSERT(!mutex.IsLocked());
        // Lockable requirements
        mutex.lock();
        UNIT_ASSERT(mutex.IsLocked());
        UNIT_ASSERT(!mutex.try_lock());
        mutex.unlock();
        UNIT_ASSERT(!mutex.IsLocked());
    }

    Y_UNIT_TEST(TSpinLock_Functionality) {
        ValidateLockBehavior<TSpinLock>();
    }

    Y_UNIT_TEST(TAdaptiveLock_Functionality) {
        ValidateLockBehavior<TAdaptiveLock>();
    }
} // Y_UNIT_TEST_SUITE(TSpinLockTests)

