#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <random>
#include <numeric>

// Use __int128 for intermediate products to prevent overflow.
// This is a GCC/Clang extension commonly used in competitive programming.
using int128 = __int128_t;

// The modulus, read from input.
long long mod_value;
// Computes bits(x) = ceil(log2(x+1)), i.e., number of bits needed to represent x in binary.
inline int count_bits(long long val) {
    if (val == 0) {
        return 0;
    }
    // For non-zero 64-bit integers: 64 - number of leading zeros.
    return 64 - __builtin_clzll(val);
}

// Simulates device timing based on exponentiation steps and bit operations.
long long estimate_time(long long base_val, long long exp_val) {
    long long total_cycles = 0;
    int128 running_product = 1;
    int128 current_base = base_val;

    for (int bit_pos = 0; bit_pos < 60; ++bit_pos) {
        if ((exp_val >> bit_pos) & 1) {
            total_cycles += (count_bits((long long)running_product) + 1) * (count_bits((long long)current_base) + 1);
            running_product = (running_product * current_base) % mod_value;
        }
        total_cycles += (count_bits((long long)current_base) + 1) * (count_bits((long long)current_base) + 1);
        current_base = (current_base * current_base) % mod_value;
    }
    return total_cycles;
}

int main() {
    // Optimize I/O for interactive problems.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Read the public modulus.
    std::cin >> mod_value;

    // Since d is coprime with φ(n) = (p-1)(q-1), and both p-1 and q-1 are even,
    // φ(n) is divisible by 4 → d must be odd. So least significant bit is always 1.
    long long current_guess = 1;

    // Initialize RNG with high-resolution clock seed.
    std::mt19937_64 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<long long> uniform_dist(2, mod_value - 1);

    // Number of samples per bit to improve statistical reliability.
    int trials_per_bit = 400;

    // Recover bits 1 through 59 sequentially.
    for (int position = 1; position < 60; ++position) {
        long double score_accumulator = 0.0L;

        long long guess_without_bit = current_guess;
        long long guess_with_bit = current_guess | (1LL << position);

        for (int trial = 0; trial < trials_per_bit; ++trial) {
            long long random_base = uniform_dist(rng);

            // Query the oracle for actual execution time.
            std::cout << "? " << random_base << std::endl;
            long long measured_time;
            std::cin >> measured_time;

            // Compute predicted times under both hypotheses.
            long long pred_time_zero = estimate_time(random_base, guess_without_bit);
            long long pred_time_one = estimate_time(random_base, guess_with_bit);

            // Accumulate difference in squared errors.
            int128 error_zero = measured_time - pred_time_zero;
            int128 error_one = measured_time - pred_time_one;

            score_accumulator += (long double)(error_zero * error_zero) -
                                 (long double)(error_one * error_one);
        }

        // If hypothesis with bit=1 yields better fit, update candidate.
        if (score_accumulator > 0) {
            current_guess = guess_with_bit;
        }
    }

    // Output recovered private exponent.
    std::cout << "! " << current_guess << std::endl;
    return 0;
