#include "CachingAllocatorHookMock.hpp"
using ::testing::_;
using ::testing::DoAll;
using ::testing::Return;

namespace torch::comms::test {

void CachingAllocatorHookMock::setupDefaultBehaviors() {
  // Configure default behavior for registerComm
  ON_CALL(*this, registerComm(_)).WillByDefault([this](TorchCommNCCLX* comm) {
    registered_comms_set_.insert(comm);
  });

  // Configure default behavior for deregisterComm
  ON_CALL(*this, deregisterComm(_)).WillByDefault([this](TorchCommNCCLX* comm) {
    registered_comms_set_.erase(comm);
  });

  // Configure default behavior for regDeregMem (no-op by default)
  ON_CALL(*this, regDeregMem(_)).WillByDefault(Return());

  // Configure default behavior for registerMemPreHook - update our internal flag
  ON_CALL(*this, registerMemPreHook()).WillByDefault([this]() {
    mem_pre_hook_active_ = true;
  });

  // Invoke registerMemPreHook to mimic DefaultCachingAllocatorHookImpl constructor behavior
  registerMemPreHook();

  // Configure default behavior for clear
  ON_CALL(*this, clear()).WillByDefault([this]() {
    registered_comms_set_.clear();
  });
}

void CachingAllocatorHookMock::reset() {
  // Clear all expectations and reset call counts
  ::testing::Mock::VerifyAndClearExpectations(this);

  // Clear the set of registered communicators
  registered_comms_set_.clear();

  // Reset the memory pre-hook flag
  mem_pre_hook_active_ = false;

  // Reapply default behaviors after reset
  setupDefaultBehaviors();
}

bool CachingAllocatorHookMock::isCommRegistered(TorchCommNCCLX* comm) {
  return registered_comms_set_.find(comm) != registered_comms_set_.end();
}

bool CachingAllocatorHookMock::isMemRegisteredCalled() {
  return mem_pre_hook_active_;
}

