#include "NetworkManager.h"
#include "mock_wifi.h"  // minimal stub, real WiFi types come from test/stubs/WiFi.h

void setUp(void) {}
void tearDown(void) {}

// Verify that a newly instantiated manager starts in disconnected state
void test_network_manager_initialization() {
    NetworkManager netMgr;
    TEST_ASSERT_FALSE(netMgr.isConnected());
    TEST_ASSERT_EQUAL_STRING("", netMgr.getSSID().c_str());
}

// Test AP mode: begin() without stored credentials should trigger START_AP;
// handleClient() processes the command and transitions to AP_MODE.
void test_network_manager_ap_mode_operation() {
    NetworkManager netMgr;
    netMgr.begin();          // queues START_AP (no saved credentials)
    netMgr.handleClient();   // processes START_AP -> state = AP_MODE
    TEST_ASSERT_FALSE(netMgr.isConnected());
    TEST_ASSERT_TRUE(netMgr.getIPAddress().startsWith("192.168.4."));
    TEST_ASSERT_TRUE(netMgr.getSSID().startsWith("ESP32_"));
}

// Confirm that saving credentials stores SSID and schedules connection attempt
void test_network_manager_store_credentials() {
    NetworkManager netMgr;
    netMgr.saveCredentials("MyNetwork", "SecurePass");
    // saveCredentials queues CONNECT; process it so credentials are applied.
    netMgr.handleClient();  // CONNECT -> connect() -> state = CONNECTING
    // getSSID() in non-AP state returns stored ssid
    TEST_ASSERT_EQUAL_STRING("MyNetwork", netMgr.getSSID().c_str());
    TEST_ASSERT_FALSE(netMgr.isConnected());  // WiFi stub never completes connection
}

// Ensure begin() followed by handleClient() runs without crashing and yields IP string
void test_network_manager_begin_safety() {
    NetworkManager netMgr;
    netMgr.begin();
    netMgr.handleClient();
    String ipAddr = netMgr.getIPAddress();
    TEST_ASSERT_TRUE(ipAddr.length() > 0);
}

int runUnityTests() {
    UNITY_BEGIN();
    RUN_TEST(test_network_manager_initialization);
    RUN_TEST(test_network_manager_ap_mode_operation);
    RUN_TEST(test_network_manager_store_credentials);
    RUN_TEST(test_network_manager_begin_safety);
    return UNITY_END();
}

