#define LOCTEXT_NAMESPACE "UOnAcceptHandleSourcesProperties"

void UOnAcceptHandleSourcesProperties::ApplyMethod(const TArray<AActor*>& SourceActors, UInteractiveToolManager* ToolManager)
{
	// Hide or destroy the sources
	if (OnToolAccept != EHandleSourcesMethod::KeepSources)
	{
		bool bRemove = OnToolAccept == EHandleSourcesMethod::DeleteSources;
		if (bRemove)
		{
			ToolManager->BeginUndoTransaction(LOCTEXT("EraseSources", "Erase Sources"));
		}
		else
		{
#if WITH_EDITOR
			ToolManager->BeginUndoTransaction(LOCTEXT("ConcealSources", "Conceal Sources"));
#endif
		}
		for (AActor* Actor : SourceActors)
		{
			if (bRemove)
			{
				Actor->Destroy();
			}
			else
			{
#if WITH_EDITOR
				// Store the actor in the transaction buffer to enable undo/redo functionality, but avoid
				// invoking Modify(), since we do not wish to mark the actor's package as modified and
				// we are only altering temporary, transient properties
				SaveToTransactionBuffer(Actor, false);
				Actor->SetIsTemporarilyHiddenInEditor(true);
#endif
			}
		}
		if (bRemove)
		{
			ToolManager->EndUndoTransaction();
		}
		else
		{
#if WITH_EDITOR
			ToolManager->EndUndoTransaction();
#endif
		}
	}
}

