HRESULT CScene_SaveMessage::OnInitialize( XUIMessageInit* pInitData, BOOL& bHandled )
{
	BindChildControls();
	CXuiSceneBase::DisplayBackground( DEFAULT_XUI_MENU_USER, TRUE );
	CXuiSceneBase::DisplayLogo( DEFAULT_XUI_MENU_USER, TRUE );
	m_okButton.SetWindowText(app.GetString(IDS_CONFIRM_OK));
	m_saveText.SetText(app.GetString(IDS_SAVE_ICON_MESSAGE));
	ui.ConfigureTooltips( DEFAULT_XUI_MENU_USER, IDS_TOOLTIPS_SELECT );
	// 4J-PB - If a signed-in user is connected, begin DLC installation
	for(unsigned int index = 0; index < XUSER_MAX_COUNT; ++index)
	{
		if( (InputManager.IsControllerConnected(index) || ProfileManager.HasUserProfile(index)) ) 
		{
			if(!app.IsDLCInstallationFinished() && !app.IsDLCInstallationQueued()) 
			{
				app.InitiateDLCInstallation(index);
				break;
			}
		}
	}
	// schedule a timeout on the save message screen to proceed after 8 seconds
	XuiSetTimer( m_hObj,0,8000);
	m_bSkipInput=false;
	return S_OK;
}
//----------------------------------------------------------------------------------
// Handles button press events.
//----------------------------------------------------------------------------------
HRESULT CScene_SaveMessage::OnButtonPressed(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
	if(m_bSkipInput) return S_OK;
	// This assumes all buttons are activated using the A button
	ui.PlayButtonFeedback(pNotifyPressData->UserIndex, VK_PAD_A);
	XuiKillTimer(m_hObj,0);
	app.SwitchToScene(XUSER_INDEX_ANY,eUIScene_MainMenu);
	rfHandled = TRUE;
	return S_OK;
}
HRESULT CScene_SaveMessage::OnKeyPress(XUIMessageInput* pInputData, BOOL& rfHandled)
{
	if(m_bSkipInput) return S_OK;
	ui.PlayButtonFeedback(pInputData->UserIndex, pInputData->dwKeyCode);
	return S_OK;
}
// 4J-PB  - added for Compliance requirement:
// Games must enter an interactive state that accepts player input within 20 seconds after the initial start-up sequence. 
// If an animation or cinematic shown during the start-up sequence runs longer than 20 seconds, it must be skippable using the START button or natural input.
HRESULT CScene_SaveMessage::OnTimeout(XUIMessageTimer *pData,BOOL& rfHandled)
{
	m_bSkipInput=true;
	XuiKillTimer(m_hObj,0);
	app.SwitchToScene(XUSER_INDEX_ANY,eUIScene_MainMenu);
	return S_OK;
}

