#include <cstddef>
#include <cstdint>
#include <cstring>
#include "llk_assert.h"

extern "C"
{
#include <gcov.h>
    using gcov_int_t = std::int64_t;

    // External symbols referencing per-translation-unit coverage data from -fprofile-info-section
    extern const struct gcov_info* __gcov_info_begin[];
    extern const struct gcov_info* __gcov_info_limit[];

    // Start and end addresses of the RISC REGION_GCOV area
    // This region holds the actual gcda data, which the host reads and saves to a file.
    extern std::uint8_t __coverage_buffer_start[];
    extern std::uint8_t __coverage_buffer_end[];

    // Placeholder implementations to avoid compilation errors
    void __gcov_merge_add(gcov_int_t*, unsigned)
    {
        LLK_ASSERT(false, "__gcov_merge_add: unexpected call");
    }

    void abort()
    {
        LLK_ASSERT(false, "abort: fatal error");
    }

    std::uint32_t __umodsi3(std::uint32_t dividend, std::uint32_t divisor)
    {
        return dividend % divisor;
    }

    std::uint32_t __udivsi3(std::uint32_t dividend, std::uint32_t divisor)
    {
        return dividend / divisor;
    }

    static void write_to_coverage(const void* source_data, unsigned int size, void*)
    {
        const std::uint8_t* src = static_cast<const std::uint8_t*>(source_data);
        auto* offset_ptr        = reinterpret_cast<std::uint32_t*>(__coverage_buffer_start);
        std::uint8_t* dest      = __coverage_buffer_start + *offset_ptr;

        for (unsigned int idx = 0; idx < size; idx++)
        {
            dest[idx] = src[idx];
        }
        *offset_ptr += size;
    }

    void dump_filename(const char* filename, void*)
    {
        __gcov_filename_to_gcfn(filename, write_to_coverage, nullptr);
    }

    // The first 4 bytes in the coverage buffer store the total number of bytes written
    void gcov_flush(void)
    {
        // Reserve first word for length; start writing after it
        *reinterpret_cast<std::uint32_t*>(__coverage_buffer_start) = 4;

        const struct gcov_info* const* info_ptr = __gcov_info_begin;
        asm volatile("" : "+r"(info_ptr)); // Compiler barrier to prevent optimization

        std::uint16_t num_units = static_cast<std::uint16_t>(__gcov_info_limit - __gcov_info_begin);
        for (std::uint16_t index = 0; index < num_units; index++)
        {
            __gcov_info_to_gcda(info_ptr[index], dump_filename, write_to_coverage, nullptr, nullptr);
        }
    }
}

