#include <vector>
#include <mpi.h>
#include <algorithm>
#include <tuple> // for std::tie
#include <madvoro/Voronoi3D.hpp>
#include "mpi_utils.hpp"
#include "read_points.hpp"
using namespace MadVoro;

int main(int argc, char *argv[])
{
    MPI_Init(&argc, &argv);
    int myRank, numProcs;
    MPI_Comm_rank(MPI_COMM_WORLD, &myRank);
    MPI_Comm_size(MPI_COMM_WORLD, &numProcs);

    // Points located inside and outside the fox domain — essential for constructing boundary faces
    // Need to track which points lie inside the region of interest.
    std::vector<Vector3D> globalPoints;
    std::vector<double> pointFlags;

    if(myRank == 0)
    {
        // Load point data from files
        std::vector<Vector3D> interiorPoints = readPoints("input/points_inside_fox");
        std::vector<Vector3D> exteriorPoints = readPoints("input/points_outside_fox");

        globalPoints.insert(globalPoints.end(), interiorPoints.begin(), interiorPoints.end());
        for(size_t idx = 0; idx < interiorPoints.size(); ++idx) pointFlags.push_back(1.0);

        globalPoints.insert(globalPoints.end(), exteriorPoints.begin(), exteriorPoints.end());
        for(size_t idx = 0; idx < exteriorPoints.size(); ++idx) pointFlags.push_back(0.0);
    }

    // Distribute workload across processes for better performance
    auto [localPoints, localFlags] = SpreadPointsToProcessors(globalPoints, pointFlags);

    // Define bounding box for Voronoi computation
    Vector3D minCorner(-13, -1, -90), maxCorner(15, 80, 70);
    Voronoi3D voronoiMesh(minCorner, maxCorner);

    if(myRank == 0)
    {
        std::cout << "Building Voronoi diagram" << std::endl;
    }

    voronoiMesh.SetVerbosity(true); // Enable progress output during construction
    voronoiMesh.BuildParallel(localPoints);

    // After parallel build, point ordering may change — update flags accordingly
    std::tie(localPoints, localFlags) = GetPointsAfterBuildExchange(voronoiMesh, localPoints, localFlags);

#ifdef MADVORO_WITH_VTK
    std::string outputFilename = "fox.vtu";
    if(myRank == 0)
    {
        std::cout << "Writing VTK file: " << outputFilename << std::endl;
    }

    // Export results to VTK format with per-point 'isInside' attribute
    voronoiMesh.ToVTK(outputFilename, {"isInside"}, {localFlags});
#else
    if(myRank == 0)
    {
        std::cout << "VTK support disabled — skipping visualization export." << std::endl;
    }
#endif

    MPI_Finalize();
}

#include <__config>
#include <__verbose_abort>
#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#ifdef __BIONIC__
#  include <syslog.h>
extern "C" void android_set_abort_message(const char* msg);
#endif   // __BIONIC__
#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
#  include <CrashReporterClient.h>
#endif

_LIBCPP_BEGIN_NAMESPACE_STD

// Custom verbose abort handler for debugging and crash reporting
_LIBCPP_WEAK void __libcpp_verbose_abort(char const* fmt, ...) noexcept {
  // Output the error message to standard error stream first
  {
    va_list args;
    va_start(args, fmt);
    std::vfprintf(stderr, fmt, args);
    va_end(args);
  }

  // Prepare formatted string for crash logging systems
  char* msg_buffer = nullptr;
  (void)msg_buffer;
  va_list args;
  va_start(args, fmt);

#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
  // Format message and set it for iOS/macOS crash reporting
  vasprintf(&msg_buffer, fmt, args);
  CRSetCrashLogMessage(msg_buffer);
#elif defined(__BIONIC__)
  // For Android/Bionic: store message for tombstone and log to system log
  vasprintf(&msg_buffer, fmt, args);
  android_set_abort_message(msg_buffer);

  openlog("libcxx", 0, 0);
  syslog(LOG_CRIT, "%s", msg_buffer);
  closelog();
#endif

  va_end(args);
  std::abort();
}

_LIBCPP_END_NAMESPACE_STD

#include <cstdlib>
#include <iostream>
#include <memory>
#include <utility>
#include "asio.hpp"

using asio::ip::tcp;

class echo_session
  : public std::enable_shared_from_this<echo_session>
{
public:
  echo_session(tcp::socket sock)
    : socket_(std::move(sock))
  {
  }

  void begin()
  {
    perform_read();
  }

private:
  void perform_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_, buffer_size),
        [this, self](std::error_code err, std::size_t bytes_transferred)
        {
          if (!err)
          {
            perform_write(bytes_transferred);
          }
        });
  }

  void perform_write(std::size_t len)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(buffer_, len),
        [this, self](std::error_code err, std::size_t /*bytes_written*/)
        {
          if (!err)
          {
            perform_read();
          }
        });
  }

  tcp::socket socket_;
  static constexpr std::size_t buffer_size = 2048;
  char buffer_[buffer_size];
};

class echo_server
{
public:
  echo_server(asio::io_context& context, unsigned short listening_port)
    : acceptor_(context, tcp::endpoint(tcp::v4(), listening_port))
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(
        [this](std::error_code err, tcp::socket client_socket)
        {
          if (!err)
          {
            std::make_shared<echo_session>(std::move(client_socket))->begin();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_echo_server <port>\n";
      return 1;
    }

    asio::io_context context;
    echo_server server_instance(context, static_cast<unsigned short>(std::atoi(argv[1])));
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
  }

  return 0;
}

#include "asio/buffer.hpp"
#include "asio/connect.hpp"
#include "asio/io_context.hpp"
#include "asio/ip/tcp.hpp"
#include "asio/read_until.hpp"
#include "asio/system_error.hpp"
#include "asio/write.hpp"
#include <cstdlib>
#include <iostream>
#include <string>
using asio::ip::tcp;

//----------------------------------------------------------------------
//
// This class manages socket timeouts by running the io_context using the timed
// io_context::run_for() member function. Each asynchronous operation is given
// a timeout within which it must complete. The socket operations themselves
// use lambdas as completion handlers. For a given socket operation, the client
// object runs the io_context to block thread execution until the operation
// completes or the timeout is reached. If the io_context::run_for() function
// times out, the socket is closed and the outstanding asynchronous operation
// is cancelled.
//
class network_client
{
public:
  void establish_connection(const std::string& hostname, const std::string& port_number,
      std::chrono::steady_clock::duration deadline)
  {
    // Resolve the host name and service to a list of endpoints.
    auto addresses = tcp::resolver(io_context_).resolve(hostname, port_number);
    // Start the asynchronous operation itself. The lambda that is used as a
    // callback will update the error variable when the operation completes.
    // The blocking_udp_client.cpp example shows how you can use std::bind
    // rather than a lambda.
    std::error_code status;
    asio::async_connect(connection_, addresses,
        [&](const std::error_code& result_error,
            const tcp::endpoint& /*result_endpoint*/)
        {
          status = result_error;
        });
    // Run the operation until it completes, or until the timeout.
    execute(deadline);
    // Determine whether a connection was successfully established.
    if (status)
      throw std::system_error(status);
  }

  std::string fetch_line(std::chrono::steady_clock::duration deadline)
  {
    // Start the asynchronous operation. The lambda that is used as a callback
    // will update the error and n variables when the operation completes. The
    // blocking_udp_client.cpp example shows how you can use std::bind rather
    // than a lambda.
    std::error_code status;
    std::size_t bytes_read = 0;
    asio::async_read_until(connection_,
        asio::dynamic_buffer(input_data_), '\n',
        [&](const std::error_code& result_error,
            std::size_t result_n)
        {
          status = result_error;
          bytes_read = result_n;
        });
    // Run the operation until it completes, or until the timeout.
    execute(deadline);
    // Determine whether the read completed successfully.
    if (status)
      throw std::system_error(status);
    std::string line(input_data_.substr(0, bytes_read - 1));
    input_data_.erase(0, bytes_read);
    return line;
  }

  void send_line(const std::string& message,
      std::chrono::steady_clock::duration deadline)
  {
    std::string data = message + "\n";
    // Start the asynchronous operation itself. The lambda that is used as a
    // callback will update the error variable when the operation completes.
    // The blocking_udp_client.cpp example shows how you can use std::bind
    // rather than a lambda.
    std::error_code status;
    asio::async_write(connection_, asio::buffer(data),
        [&](const std::error_code& result_error,
            std::size_t /*result_n*/)
        {
          status = result_error;
        });
    // Run the operation until it completes, or until the timeout.
    execute(deadline);
    // Determine whether the write completed successfully.
    if (status)
      throw std::system_error(status);
  }

private:
  void execute(std::chrono::steady_clock::duration deadline)
  {
    // Restart the io_context, as it may have been left in the "stopped" state
    // by a previous operation.
    io_context_.restart();
    // Block until the asynchronous operation has completed, or timed out. If
    // the pending asynchronous operation is a composed operation, the deadline
    // applies to the entire operation, rather than individual operations on
    // the socket.
    io_context_.run_for(deadline);
    // If the asynchronous operation completed successfully then the io_context
    // would have been stopped due to running out of work. If it was not
    // stopped, then the io_context::run_for call must have timed out.
    if (!io_context_.stopped())
    {
      // Close the socket to cancel the outstanding asynchronous operation.
      connection_.close();
      // Run the io_context again until the operation completes.
      io_context_.run();
    }
  }

  asio::io_context io_context_;
  tcp::socket connection_{io_context_};
  std::string input_data_;
};

//----------------------------------------------------------------------
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 4)
    {
      std::cerr << "Usage: blocking_tcp_client <host> <port> <message>\n";
      return 1;
    }

    network_client client_instance;
    client_instance.establish_connection(argv[1], argv[2], std::chrono::seconds(10));
    auto start_time = std::chrono::steady_clock::now();
    client_instance.send_line(argv[3], std::chrono::seconds(10));

    for (;;)
    {
      std::string received_line = client_instance.fetch_line(std::chrono::seconds(10));
      // Keep going until we get back the line that was sent.
      if (received_line == argv[3])
        break;
    }

    auto end_time = std::chrono::steady_clock::now();
    std::cout << "Round trip time: ";
    std::cout << std::chrono::duration_cast<
      std::chrono::microseconds>(
        end_time - start_time).count();
    std::cout << " microseconds\n";
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }
  return 0;
}

