#include "lib/rocprofiler-sdk/pc_sampling/parser/tests/gfxtest.hpp"
#include <gtest/gtest.h>
#include <cstddef>

/**
 * @brief This test checks the correctness of PC address adjustment on GFX950 under specific conditions.
 */
template <typename RecordType>
class Gfx950PcAdjustment : public MidMacroPCCorrection<GFX950, RecordType>
{
public:
    void generatePCSample(uint64_t program_counter, bool is_mid_macro) override
    {
        // mid_macro flag applies only to stochastic sampling on GFX950
        if constexpr(!std::is_same<RecordType,
                                   rocprofiler_pc_sampling_record_stochastic_v0_t>::value)
        {
            // Disable mid_macro for non-stochastic records
            is_mid_macro = false;
        }
        // Delegate to base class implementation
        MidMacroPCCorrection<GFX950, RecordType>::generatePCSample(program_counter, is_mid_macro);
    };

    uint64_t computeTargetPC(uint64_t program_counter, bool is_mid_macro) override
    {
        // Per hardware specification, when is_mid_macro is true, subtract 2 DWORDs from PC
        return is_mid_macro ? (program_counter - 2 * sizeof(uint32_t)) : program_counter;
    }
};

TEST(pcs_parser, gfx950_validation)
{
    Gfx950PcAdjustment<rocprofiler_pc_sampling_record_host_trap_v0_t>{}.runTest();
    Gfx950PcAdjustment<rocprofiler_pc_sampling_record_stochastic_v0_t>{}.runTest();
    std::cout << "GFX950 Validation Completed." << std::endl;
}

#include <iostream>
using namespace std;

class emp {
private:
    int employeeId;
    char employeeName;
public:
    void readData();
    void displayData();

    class salary {
    private:
        int gross, deduction;
        float basic, houseRent, conveyance, medical, travel, bonus, tax;
    public:
        void getData();
        void compute();
        void showResult();
    };
};

void emp::readData() {
    cout << "Enter employee ID and name: ";
    cin >> employeeId >> employeeName;
}

void emp::salary::getData() {
    cout << "Enter basic salary: ";
    cin >> gross;
}

void emp::salary::compute() {
    basic = 0.4 * gross;
    houseRent = 0.3 * gross;
    conveyance = 0.1 * gross;
    medical = 0.1 * gross;
    travel = 0.05 * gross;
    bonus = 0.05 * gross;
    tax = 0.1 * gross;
}

void emp::displayData() {
    cout << "Employee ID: " << employeeId << ", Name: " << employeeName << endl;
}

void emp::salary::showResult() {
    deduction = tax;
    cout << "Gross Salary: " << gross << ", Net Pay: " << (basic + houseRent + conveyance + medical + travel + bonus - deduction) << endl;
}

int main() {
    emp worker;
    emp::salary payment;

    worker.readData();
    payment.getData();
    payment.compute();
    worker.displayData();
    payment.showResult();

    return 0;
}

