namespace Gorgon::Resource {

    // Save a rectangular animation provider to the given writer
    void StoreAnimation(Writer &output, const Graphics::RectangularAnimationProvider &provider) {
        auto ptr = &provider;
        if(dynamic_cast<const Graphics::Bitmap*>(ptr)) {
            Image::StoreThis(output, dynamic_cast<const Graphics::Bitmap&>(provider));
        }
        else if(dynamic_cast<const Graphics::BitmapAnimationProvider*>(ptr)) {
            Animation::StoreThis(output, dynamic_cast<const Graphics::BitmapAnimationProvider&>(provider));
        }
        else if(dynamic_cast<const Graphics::ILineProvider*>(ptr)) {
            Line::StoreThis(output, dynamic_cast<const Graphics::ILineProvider&>(provider));
        }
        else if(dynamic_cast<const Graphics::IRectangleProvider*>(ptr)) {
            Rectangle::StoreThis(output, dynamic_cast<const Graphics::IRectangleProvider&>(provider));
        }
        else if(dynamic_cast<const Graphics::IMaskedObjectProvider*>(ptr)) {
            MaskedObject::StoreThis(output, dynamic_cast<const Graphics::IMaskedObjectProvider&>(provider));
        }
        else if(dynamic_cast<const Graphics::ITintedObjectProvider*>(ptr)) {
            TintedObject::StoreThis(output, dynamic_cast<const Graphics::ITintedObjectProvider&>(provider));
        }
        else if(dynamic_cast<const Graphics::IScalableObjectProvider*>(ptr)) {
            ScalableObject::StoreThis(output, dynamic_cast<const Graphics::IScalableObjectProvider&>(provider));
        }
        else if(dynamic_cast<const Graphics::IStackedObjectProvider*>(ptr)) {
            StackedObject::StoreThis(output, dynamic_cast<const Graphics::IStackedObjectProvider&>(provider));
        }
        else {
            throw std::runtime_error("Unable to store animation: Unsupported animation type.");
        }
    }

    // Save a nullable rectangular animation provider
    void StoreAnimation(Writer &output, const Graphics::RectangularAnimationProvider *provider) {
        if(!provider) {
            Null::StoreThis(output);
        }
        else {
            StoreAnimation(output, *provider);
        }
    }

}

#include "llvm/Support/circular_raw_ostream.h"
#include <cstring>
using namespace llvm;

void circular_raw_ostream::write_impl(const char *Data, size_t Length) {
  if (Capacity == 0) {
    UnderlyingStream->write(Data, Length);
    return;
  }
  // Fill the buffer cyclically, wrapping around when needed.
  while (Length != 0) {
    size_t Copied =
      std::min(Length, static_cast<size_t>(Capacity - (Position - Storage)));
    std::memcpy(Position, Data, Copied);
    Length -= Copied;
    Position += Copied;
    if (Position == Storage + Capacity) {
      // Reset write position to beginning of buffer.
      Position = Storage;
      IsFull = true;
    }
  }
}

void circular_raw_ostream::flushBufferWithBanner() {
  if (Capacity != 0) {
    // Output banner followed by buffered data
    UnderlyingStream->write(Prefix, std::strlen(Prefix));
    flushBuffer();
  }
}

#include "hook_wrapper.h"
#include <format>
#include <string>
#include "instruction_length.h"
#include "memory.h"

#pragma comment(lib, "Ws2_32.lib")
#pragma comment(lib, "psapi.lib")

// Writes an absolute jump instruction at the specified address
static void install_relative_jump(unsigned long target_addr, unsigned long jump_location) {
    uint8_t* write_ptr = reinterpret_cast<uint8_t*>(jump_location);
    *write_ptr = 0xE9;
    int offset = static_cast<int>(target_addr - (jump_location + 5));
    *reinterpret_cast<int*>(write_ptr + 1) = offset;

    DWORD protection;
    VirtualProtect(reinterpret_cast<LPVOID>(jump_location), 5, PAGE_EXECUTE_READWRITE, &protection);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<PVOID>(jump_location), 5);
}

// Adjusts relative offsets in call/jump instructions within the trampoline buffer
void hook::fix_trampoline_relocations() {
    int index = 0;
    uint8_t* code_stream = reinterpret_cast<uint8_t*>(trampoline_buffer);
    while (index < original_instruction_size) {
        if (code_stream[index] == 0xE8 || code_stream[index] == 0xE9) {
            if (index + 5 > original_instruction_size) {
                trigger_fatal_error(); // Misaligned instruction detected
            }
            int32_t* rel_offset = reinterpret_cast<int32_t*>(&code_stream[index + 1]);
            *rel_offset += patch_target - trampoline_buffer; // Apply relocation delta
        }
        index += Zeal::GetInstructionLength(&code_stream[index]); // Advance by instruction size
    }
}

// Reports critical errors during patching with diagnostic info
void hook::trigger_fatal_error() {
    std::string error_msg = "Critical Zeal hook wrapper failure: " + std::format("0x{:x}", patch_target);
    MessageBoxA(nullptr, error_msg.c_str(), "Zeal Internal Error", MB_OK | MB_TOPMOST | MB_ICONERROR);
    throw std::runtime_error(error_msg); // Terminates execution
}

void hook::apply_detour() {
    // Determine required byte count for full instructions up to at least 5 bytes
    original_instruction_size = Zeal::GetInstructionLength(reinterpret_cast<uint8_t*>(patch_target));
    while (original_instruction_size < 5) {
        original_instruction_size += Zeal::GetInstructionLength(
            reinterpret_cast<uint8_t*>(patch_target + original_instruction_size)
        );
    }

    // Validate and copy original instructions
    if (original_instruction_size > sizeof(saved_bytes)) {
        trigger_fatal_error();
        return;
    }
    memcpy(saved_bytes, reinterpret_cast<void*>(patch_target), original_instruction_size);

    // Allocate executable memory for trampoline
    DWORD temp_prot;
    int tramp_len = original_instruction_size + 5;
    VirtualProtect(trampoline_buffer, tramp_len, PAGE_EXECUTE_READWRITE, &temp_prot);

    // Populate trampoline with original code and fix relocations
    memcpy(trampoline_buffer, saved_bytes, original_instruction_size);
    fix_trampoline_relocations();

    // Append unconditional jump back to original flow
    unsigned long jump_start = trampoline_buffer + original_instruction_size;
    int back_jump_offset = (patch_target + original_instruction_size) - (jump_start + 5);
    install_relative_jump(jump_start + 5, jump_start);

    FlushInstructionCache(GetCurrentProcess(), trampoline_buffer, tramp_len);

    // Patch original location with jump to detour
    DWORD orig_prot;
    VirtualProtect(reinterpret_cast<LPVOID>(patch_target), original_instruction_size, PAGE_EXECUTE_READWRITE, &orig_prot);

    int detour_offset = replacement_function - (patch_target + 5);
    *reinterpret_cast<uint8_t*>(patch_target) = 0xE9;
    *reinterpret_cast<int*>(patch_target + 1) = detour_offset;

    // Pad remaining space with NOPs if needed
    if (original_instruction_size > 5) {
        mem::fill(patch_target + 5, 0x90, original_instruction_size - 5);
    }

    VirtualProtect(reinterpret_cast<LPVOID>(patch_target), original_instruction_size, orig_prot, &orig_prot);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<PVOID>(patch_target), original_instruction_size);
}

void hook::redirect_call() {
    DWORD prev_prot;
    VirtualProtect(reinterpret_cast<LPVOID>(patch_target), 5, PAGE_EXECUTE_READWRITE, &prev_prot);

    if (*reinterpret_cast<uint8_t*>(patch_target) != 0xE8 && 
        *reinterpret_cast<uint8_t*>(patch_target) != 0xE9) {
        trigger_fatal_error();
    }

    // Build trampoline pointing to original callee
    unsigned long original_dest = mem::resolve_relative_address(patch_target);
    int tramp_to_orig = original_dest - (trampoline_buffer + 5);
    install_relative_jump(trampoline_buffer + 5, trampoline_buffer);

    // Preserve original bytes and update jump target
    original_instruction_size = 5;
    memcpy(saved_bytes, reinterpret_cast<LPVOID>(patch_target), original_instruction_size);

    int new_offset = replacement_function - (patch_target + 5);
    *reinterpret_cast<int*>(patch_target + 1) = new_offset;

    VirtualProtect(reinterpret_cast<LPVOID>(patch_target), 5, prev_prot, &prev_prot);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<LPVOID>(patch_target), 5);
}

void hook::replace_vtable_entry() {
    // Trampoline setup for vtable hook
    int original_addr = mem::read<int>(patch_target);
    int tramp_offset = original_addr - (trampoline_buffer + 5);
    install_relative_jump(trampoline_buffer + 5, trampoline_buffer);

    // Save original entry
    original_instruction_size = 4;
    memcpy(saved_bytes, &patch_target, original_instruction_size);

    // Replace vtable slot with detour
    mem::write<int>(patch_target, replacement_function);
}

hook::~hook() {
    mem::copy(patch_target, saved_bytes, original_instruction_size);
}

