int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // This C++ program outputs an A=B-style program for substring matching.
    // The Tid input is disregarded as per problem requirements.
    // The generated A=B program uses a brute-force substring search approach.
    // It systematically tests every possible starting index in string `s`
    // and verifies whether `t` matches at each position.
    //
    // Internal representation:
    // s_processed P s_rem Z t
    // P: Outer loop pointer indicating next starting position in `s`.
    //
    // s_processed a C s_matched s_unmatched Z t
    // C: Active check marker; `a` is the current character being compared.
    // s_matched: Characters of `s` already matched, marked with A,B,C.
    //
    // D,E,F: Transporters for characters a,b,c from `t`.
    // Y: Mismatch recovery state.
    // A,B,C: Matched characters in `s` corresponding to a,b,c.
    // Z: Main delimiter (replaces initial 'S').
    //
    // Complexity: O(|s|*|t|*|s|), but may pass due to test constraints.
    // Rule count stays under 100.
    // String length increases by at most 1 per step, bounded by 2L+10.

    // Initial setup: insert P and Z markers
    std::cout << "S=PZ" << std::endl;

    // Success/failure states
    std::cout << "AZ=(return)1" << std::endl;
    std::cout << "PZ=(return)0" << std::endl;

    // Mismatch handling: revert matched characters
    std::cout << "AY=Ya" << std::endl;
    std::cout << "BY=Yb" << std::endl;
    std::cout << "CY=Yc" << std::endl;
    std::cout << "aY=Ya" << std::endl;
    std::cout << "bY=Yb" << std::endl;
    std::cout << "cY=Yc" << std::endl;
    std::cout << "CY=P" << std::endl;

    // Check completion when C reaches Z
    std::cout << "CZ=AZ" << std::endl;

    // Load characters from t using carriers
    std::cout << "Za=ZDa" << std::endl;
    std::cout << "Zb=ZEb" << std::endl;
    std::cout << "Zc=ZFc" << std::endl;

    // Carrier movement through regular characters
    std::cout << "aD=Da" << std::endl;
    std::cout << "bD=Db" << std::endl;
    std::cout << "cD=Dc" << std::endl;
    std::cout << "aE=Ea" << std::endl;
    std::cout << "bE=Eb" << std::endl;
    std::cout << "cE=Ec" << std::endl;
    std::cout << "aF=Fa" << std::endl;
    std::cout << "bF=Fb" << std::endl;
    std::cout << "cF=Fc" << std::endl;

    // Carrier movement through matched characters
    std::cout << "AD=DA" << std::endl;
    std::cout << "BD=DB" << std::endl;
    std::cout << "CD=DC" << std::endl;
    std::cout << "AE=EA" << std::endl;
    std::cout << "BE=EB" << std::endl;
    std::cout << "CE=EC" << std::endl;
    std::cout << "AF=FA" << std::endl;
    std::cout << "BF=FB" << std::endl;
    std::cout << "CF=FC" << std::endl;

    // Character comparison logic
    std::cout << "CaD=CA" << std::endl;
    std::cout << "CbE=CB" << std::endl;
    std::cout << "CcF=CC" << std::endl;

    // Mismatch transitions
    std::cout << "CaE=Y" << std::endl;
    std::cout << "CaF=Y" << std::endl;
    std::cout << "CbD=Y" << std::endl;
    std::cout << "CbF=Y" << std::endl;
    std::cout << "CcD=Y" << std::endl;
    std::cout << "CcE=Y" << std::endl;

    // Outer loop advancement
    std::cout << "Pa=aC" << std::endl;
    std::cout << "Pb=bC" << std::endl;
    std::cout << "Pc=cC" << std::endl;
    std::cout << "aP=Pa" << std::endl;
    std::cout << "bP=Pb" << std::endl;
    std::cout << "cP=Pc" << std::endl;

    return 0;
}

