// Function to perform a query and get the winner
int runQuery(const std::vector<int>& group) {
    std::cout << "?";
    for (int val : group) {
        std::cout << " " << val;
    }
    std::cout << std::endl;

    int result;
    std::cin >> result;
    if (result == -1) {
        exit(0); // Terminate on error from interactor
    }
    return result;
}

void process() {
    int size;
    std::cin >> size;

    // Maintain list of remaining elements
    std::list<int> available;
    for (int i = 1; i <= size * size; ++i) {
        available.push_back(i);
    }

    std::vector<int> orderedResult;
    int neededCount = size * size - size + 1;

    // Determine top elements one by one
    for (int step = 0; step < neededCount; ++step) {
        std::list<int> contenders = available;

        while (contenders.size() > 1) {
            // Select up to 'size' elements for current race
            std::vector<int> currentRace;
            auto iter = contenders.begin();
            for (int j = 0; j < size && iter != contenders.end(); ++j) {
                currentRace.push_back(*iter);
                ++iter;
            }

            int champ = runQuery(currentRace);

            // Eliminate all non-winners from contenders
            auto iterCont = contenders.begin();
            while (iterCont != contenders.end()) {
                bool eliminated = false;
                if (*iterCont != champ) {
                    for (int rItem : currentRace) {
                        if (*iterCont == rItem) {
                            eliminated = true;
                            break;
                        }
                    }
                }

                if (eliminated) {
                    iterCont = contenders.erase(iterCont);
                } else {
                    ++iterCont;
                }
            }
        }

        int nextBest = contenders.front();
        orderedResult.push_back(nextBest);
        available.remove(nextBest);
    }

    // Output final sorted sequence
    std::cout << "!";
    for (size_t idx = 0; idx < orderedResult.size(); ++idx) {
        std::cout << " " << orderedResult[idx];
    }
    std::cout << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCases;
    std::cin >> testCases;
    while (testCases--) {
        process();
    }

    return 0;
}

#include <vector>

class Solution {
public:
    // Find total count of elements with maximum frequency
    int maxFrequencyElements(std::vector<int>& nums) {
        int frequency[101] = {0};
        int currentMaxFreq = 0;
        int countOfMaxFreq = 0;

        for (int num : nums) {
            frequency[num]++;

            if (frequency[num] == currentMaxFreq) {
                countOfMaxFreq++;
            }

            if (frequency[num] > currentMaxFreq) {
                currentMaxFreq = frequency[num];
                countOfMaxFreq = 1;
            }
        }

        return countOfMaxFreq * currentMaxFreq;
    }
};

