// Modified from kaguya documentation example
// Original author: satoren
// Source: https://github.com/satoren/kaguya
// Distributed under Boost Software License 1.0
struct DataContainer {
	DataContainer() : data_(0) {
	}
	DataContainer(int initial) : data_(initial) {
	}
	int getData() const {
		return data_;
	}
	void setData(int val) {
		data_ = val;
	}
	void methodA() {
		std::cout << "executing methodA" << std::endl;
	}
	void methodB(int param) {
		std::cout << "executing methodB" << std::endl;
	}
private:
	int data_;
};

template <typename U, typename Callback>
inline bool lua_interop_validate(sol::types<U>, lua_State* state,
     int position, sol::type type_tag, Callback&& func_handler,
     sol::stack::usage& tracker) {
	(void)type_tag;
	(void)func_handler;
	tracker.use(1);
	int abs_pos = lua_absindex(state, position);
	bool valid = kaguya::detail::object_wrapper_type_check(state, abs_pos);
	return valid;
}

template <typename U>
inline std::pair<bool, U*> lua_interop_extract(sol::types<U>,
     lua_State* state, int rel_index, void* raw_ptr,
     sol::stack::usage& tracker) {
	int abs_idx = lua_absindex(state, rel_index);
	if (!kaguya::detail::object_wrapper_type_check(state, abs_idx)) {
		return { false, nullptr };
	}
	tracker.use(1);
	kaguya::ObjectWrapperBase* base_obj
	     = kaguya::object_wrapper(state, abs_idx);
	return { true, static_cast<U*>(base_obj->get()) };
}

void setup_sol_bindings(lua_State* L) {
	sol::state_view lua(L);
	lua["process"] = sol::overload(
	     [](DataContainer& container) {
		     std::cout << "invoking single-parameter variant with "
		                  "kaguya-generated DataContainer { "
		               << container.getData() << " }"
		               << std::endl;
		     SOL_ASSERT(container.getData() == 42);
	     },
	     [](DataContainer& container, int additional) {
		     std::cout << "invoking two-parameter variant with "
		                  "kaguya-generated DataContainer { "
		               << container.getData()
		               << " } and integer argument of "
		               << additional << std::endl;
		     SOL_ASSERT(container.getData() == 42);
		     SOL_ASSERT(additional == 7);
	     });
}

void verify_with_sol(lua_State* L) {
	sol::state_view lua(L);
	DataContainer& obj = lua["instance"];
	(void)obj;
	SOL_ASSERT(obj.getData() == 42);
}

int main(int argc, char* argv[]) {
	std::cout << "=== interoperability demonstration (kaguya) ==="
	          << std::endl;
	std::cout << "(adapted from kaguya README examples: "
	             "https://github.com/satoren/kaguya)"
	          << std::endl;
	kaguya::State vm;
	vm["DataContainer"].setClass(
	     kaguya::UserdataMetatable<DataContainer>()
	          .setConstructors<DataContainer(), DataContainer(int)>()
	          .addFunction("retrieve", &DataContainer::getData)
	          .addFunction("assign", &DataContainer::setData)
	          .addOverloadedFunctions(
	               "dispatch", &DataContainer::methodA, &DataContainer::methodB)
	          .addStaticFunction("external_func",
	               [](DataContainer* self, int) { return 2; }));
	setup_sol_bindings(vm.state());
	vm.dostring(R"(
instance = DataContainer.new(42)
process(instance) -- invoke single-argument form
process(instance, 7) -- invoke two-argument form
)");
	verify_with_sol(vm.state());
	return 0;
}

#include <stdio.h>

// Recursive function to solve the Tower of Hanoi puzzle
void hanoiSolver(int disks, char fromRod, char viaRod, char toRod) {
    // Base case: single disk movement
    if (disks == 1) {
        printf("Move disk 1 from %c to %c\n", fromRod, toRod);
        return;
    }

    // Move top (disks-1) disks from source to auxiliary rod
    hanoiSolver(disks - 1, fromRod, toRod, viaRod);

    // Move the largest disk from source to destination
    printf("Move disk %d from %c to %c\n", disks, fromRod, toRod);

    // Move the (disks-1) disks from auxiliary to destination
    hanoiSolver(disks - 1, viaRod, fromRod, toRod);
}

int main() {
    int numberOfDisks;

    // Prompt user for input
    printf("Enter the number of disks: ");
    scanf("%d", &numberOfDisks);

    // Display solution header and execute the solver
    printf("The sequence of moves to solve the Tower of Hanoi for %d disks is:\n", numberOfDisks);
    hanoiSolver(numberOfDisks, 'X', 'Y', 'Z');  // X=source, Y=auxiliary, Z=destination

    return 0;
}

