namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has been modified by comparing
///		current file system metadata with previously recorded values. When
///		a discrepancy is detected, it updates the entry and flags it as changed.
///	@param[inout] targetEntry
///		The entry whose state needs verification and potential update
///	@returns
///		Error status indicating success or failure of the check operation
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &targetEntry) noexcept {
    WIN32_FIND_DATAW fileInfo;
    Error errCode;
    // Acquire the OS-specific path
    Text osFilePath;
    if (errCode = Url::osPath(targetEntry.url(), osFilePath)) return errCode;

    // Use FindFirstFileW to retrieve detailed file info including reparse points
    HANDLE hFind = FindFirstFileW(osFilePath, &fileInfo);

    // Handle error case — likely due to missing file
    if (hFind == INVALID_HANDLE_VALUE) {
        return APERR(GetLastError(), _location,
                     "Failed to determine file change status");
    }

    FindClose(hFind);

    // Assume no change initially
    targetEntry.changed(false);

    // Compare creation time
    auto newCreateTime = _tr<time::SystemStamp>(fileInfo.ftCreationTime);
    if (targetEntry.createTime.get() != newCreateTime) {
        targetEntry.markChanged(LogLevel, "Creation timestamp differs");
        targetEntry.createTime(newCreateTime);
    }

    // Compare modification time
    auto newModifyTime = _tr<time::SystemStamp>(fileInfo.ftLastWriteTime);
    if (targetEntry.modifyTime.get() != newModifyTime) {
        targetEntry.markChanged(LogLevel, "Modification timestamp differs");
        targetEntry.modifyTime(newModifyTime);
    }

    // Update access time only (no change flag)
    auto newAccessTime = _tr<time::SystemStamp>(fileInfo.ftLastAccessTime);
    if (targetEntry.accessTime.get() != newAccessTime) {
        targetEntry.accessTime(newAccessTime);
    }

    // Compare file attributes
    if (targetEntry.attrib() != fileInfo.dwFileAttributes) {
        targetEntry.markChanged(LogLevel, "File attributes have changed");
        targetEntry.attrib(fileInfo.dwFileAttributes);
    }

    // Compute full file size from high/low parts
    uint64_t fileSize =
        (static_cast<uint64_t>(fileInfo.nFileSizeHigh) << 32) |
        fileInfo.nFileSizeLow;

    if (targetEntry.size() != fileSize) {
        targetEntry.markChanged(LogLevel, "File size mismatch");
        targetEntry.size(fileSize);
    }

    // Retrieve disk-allocated size
    auto actualDiskSize = file::getSizeOnDisk(osFilePath, targetEntry.size(), targetEntry.attrib());

    uint64_t storeSizeValue;
    if (actualDiskSize.check()) {
        storeSizeValue = targetEntry.size();  // fallback to logical size
    } else {
        storeSizeValue = *actualDiskSize;
    }

    // Check for discrepancy in storage size
    if (targetEntry.storeSize() != storeSizeValue) {
        targetEntry.markChanged(LogLevel, "Storage allocation size differs");
        targetEntry.storeSize(storeSizeValue);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

