#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

// Function to send a query and receive a response
int sendQuery(int value) {
    std::cout << "? " << value << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Function to output an answer
void reportAnswer(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<bool> matched(2 * n + 1, false);
    std::vector<int> unmatched_list; // Simulates a stack

    int current_unique_count = 0;
    int pairs_completed = 0;

    for (int idx = 1; idx <= 2 * n; ++idx) {
        if (matched[idx]) {
            continue;
        }

        // Toggle slice idx's presence in the device
        int response = sendQuery(idx);
        if (response > current_unique_count) {
            // idx's mate is not in the device. Add idx to the set of unmatched slices.
            unmatched_list.push_back(idx);
            current_unique_count = response;
        } else {
            // response == current_unique_count. idx's mate is in unmatched_list.
            // Let's find it.

            // The number of distinct kinds among the slices in unmatched_list is `current_unique_count`.
            // After inserting idx, the device contains {idx} U unmatched_list, and the number of
            // distinct kinds is still `current_unique_count`. This is our baseline for checks.
            int baseline_kinds = current_unique_count;
            std::vector<int> temporarily_removed;

            while (!unmatched_list.empty()) {
                int candidate = unmatched_list.back();
                unmatched_list.pop_back();

                // Remove candidate to test if it's the mate of idx
                int test_response = sendQuery(candidate);

                // State before this query: device had {idx} U (unmatched_list_at_this_point U {candidate} U temporarily_removed)
                // Kinds = baseline_kinds
                // State after query: device has {idx} U (unmatched_list_at_this_point U temporarily_removed)
                // This remaining set is S_old \ {candidate}.
                // If candidate is the mate of idx, then idx becomes a new, unpaired kind among the remaining slices.
                // Kinds = |S_old \ {candidate}| + 1 = (baseline_kinds - 1) + 1 = baseline_kinds.
                // If candidate is not the mate of idx, idx's mate is still in S_old \ {candidate}.
                // Kinds = |S_old \ {candidate}| = baseline_kinds - 1.

                if (test_response == baseline_kinds) {
                    // candidate is the mate of idx
                    reportAnswer(idx, candidate);
                    pairs_completed++;
                    matched[idx] = true;
                    matched[candidate] = true;

                    // idx is in the device, candidate is not. Remove idx.
                    // The returned value updates current_unique_count for the remaining items.
                    current_unique_count = sendQuery(idx);

                    // Restore the other unmatched items that were temporarily removed
                    for (int item : temporarily_removed) {
                        current_unique_count = sendQuery(item);
                        unmatched_list.push_back(item);
                    }

                    break; 
                } else {
                    // candidate is not the mate, keep it aside temporarily
                    temporarily_removed.push_back(candidate);
                }
            }
        }

        if (pairs_completed == n) {
            break;
        }
    }

    return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int length = digits.size();
        int carry = 1;
        vector<int> result(length, 0);

        for (int index = length - 1; index >= 0; index--) {
            int currentDigit = digits[index];
            currentDigit = currentDigit + carry;
            carry = currentDigit / 10;

            currentDigit = currentDigit % 10;
            result[index] = currentDigit;

            if (carry == 1 && index == 0) {
                result.insert(result.begin(), carry);
            }
        }

        return result;
    }
};

