namespace {
/// NVPTXNormalizeGlobalIdentifiers - Sanitize global symbols for PTX compatibility
class NVPTXNormalizeGlobalIdentifiers : public ModulePass {
public:
  static char ID;
  NVPTXNormalizeGlobalIdentifiers() : ModulePass(ID) {}

  bool processModule(Module &mod) override;

  /// Sanitize identifier names by replacing invalid characters
  std::string sanitizeIdentifier(StringRef identifier);
};
}

char NVPTXNormalizeGlobalIdentifiers::ID = 0;

namespace llvm {
void initializeNVPTXNormalizeGlobalIdentifiersPass(PassRegistry &);
}

INITIALIZE_PASS(NVPTXNormalizeGlobalIdentifiers, "nvptx-normalize-global-idents",
                "Normalize global identifiers for PTX", false, false)

bool NVPTXNormalizeGlobalIdentifiers::processModule(Module &mod) {
  // Process all global variables first
  for (GlobalVariable &global : mod.globals()) {
    if (global.hasLocalLinkage()) {
      global.setName(sanitizeIdentifier(global.getName()));
    }
  }

  // Then handle local functions
  for (Function &func : mod.functions()) {
    if (func.hasLocalLinkage()) {
      func.setName(sanitizeIdentifier(func.getName()));
    }
  }

  return true;
}

std::string NVPTXNormalizeGlobalIdentifiers::sanitizeIdentifier(StringRef identifier) {
  std::string sanitized;
  raw_string_ostream stream(sanitized);

  for (char ch : identifier) {
    if (ch == '.' || ch == '@' || ch == '<' || ch == '>') {
      stream << "_x";
    } else {
      stream << ch;
    }
  }

  return stream.str();
}

ModulePass *llvm::createNVPTXNormalizeGlobalIdentifiersPass() {
  return new NVPTXNormalizeGlobalIdentifiers();
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Converts a character from the set {'A'-'Z', '0'-'9'} to an integer index [0, 35].
inline int char_to_index(char ch) {
    if (ch >= 'A' && ch <= 'Z') {
        return ch - 'A';
    }
    return ch - '0' + 26;
}

// Computes a common subsequence by greedily matching characters from string 'x' in string 'y'.
// This function operates in O(|x| + |y|) time.
std::string compute_greedy(const std::string& x, const std::string& y) {
    // Precompute positions of each character in string 'y' for efficient lookups.
    // indices[k] holds a sorted list of positions where the k-th alphabet character appears in 'y'.
    std::vector<std::vector<int>> indices(36);
    for (int idx = 0; idx < y.size(); ++idx) {
        indices[char_to_index(y[idx])].push_back(idx);
    }

    std::string result;
    // Reserve space to prevent reallocations. Maximum possible LCS length is min(|x|, |y|).
    result.reserve(std::min(x.size(), y.size()));

    int last_index_y = -1;
    // 'pointers' keeps track of current position in each character's position vector.
    std::vector<int> pointers(36, 0);

    for (char ch : x) {
        int char_idx = char_to_index(ch);

        // Advance pointer to find next occurrence of 'ch' in 'y' after 'last_index_y'.
        while (pointers[char_idx] < indices[char_idx].size() &&
               indices[char_idx][pointers[char_idx]] <= last_index_y) {
            pointers[char_idx]++;
        }

        // If a valid position exists, add the character to result and update tracking variables.
        if (pointers[char_idx] < indices[char_idx].size()) {
            result.push_back(ch);
            last_index_y = indices[char_idx][pointers[char_idx]];
            pointers[char_idx]++; // Move to next occurrence for future searches.
        }
    }
    return result;
}

int main() {
    // Optimize I/O for speed with large inputs.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string str1, str2;
    std::cin >> str1 >> str2;

    // Generate two candidate subsequences by running greedy algorithm in both directions.
    std::string candidate1 = compute_greedy(str1, str2);
    std::string candidate2 = compute_greedy(str2, str1);

    // Output the longer of the two candidates.
    if (candidate1.length() >= candidate2.length()) {
        std::cout << candidate1 << '\n';
    } else {
        std::cout << candidate2 << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;

class Solution {
public:
    // Linear search approach for checking target presence
    bool linearSearch(vector<int>& arr, int key) {
        // Handle edge cases: first or last element might be the target
        if(arr[0] == key || arr[arr.size()-1] == key) {
            return true;
        }

        // Check remaining elements sequentially
        for(int idx = 1; idx < arr.size()-1; idx++) {
            if(arr[idx] == key) {
                return true;
            }
        }
        return false;
        // Time Complexity: O(n) - checks each element once
        // Space Complexity: O(1) - no additional memory used
    }

    // Optimized binary search for rotated sorted array with duplicates
    bool binarySearchOptimized(vector<int>& arr, int key) {
        // Initial check for endpoints
        if(arr[0] == key || arr[arr.size()-1] == key) {
            return true;
        }

        int left = 0;
        int right = arr.size() - 1;

        while(left <= right) {
            int middle = left + (right - left)/2;

            // Found the target
            if(arr[middle] == key) {
                return true;
            }

            // Handle duplicates at boundaries and middle
            if((arr[middle] == arr[left]) && (arr[right] == arr[middle])) {
                left++;
                right--;
            }
            else if(arr[left] <= arr[middle]) {
                // Left half is sorted
                if((arr[left] <= key) && (key < arr[middle])) {
                    // Target lies in left sorted portion
                    right = middle - 1;
                }
                else {
                    // Target lies in right portion
                    left = middle + 1;
                }
            }
            else {
                // Right half is sorted
                if((arr[middle] < key) && (key <= arr[right])) {
                    // Target lies in right sorted portion
                    left = middle + 1;
                }
                else {
                    // Target lies in left portion
                    right = middle - 1;
                }
            }
        } 
        return false;
        /*
            Time Complexity: O(log n) - halves search space each iteration
            Space Complexity: O(1) - constant extra space
        */
    }
};

int main() {
    vector<int> data = {2,5,6,0,0,1,2};
    int query1 = 3;
    int query2 = 0;

    Solution solver;

    bool result1 = solver.binarySearchOptimized(data, query1);
    cout << result1 << endl; // Expected: 0 (false)

    bool result2 = solver.binarySearchOptimized(data, query2);
    cout << result2 << endl; // Expected: 1 (true)

    return 0;
}

#include "server.hpp"
#include <boost/bind.hpp>
#include <signal.h>

namespace http {
namespace server {

// Constructor for the HTTP server, initializing network components and signal handlers
server::server(const std::string& host, const std::string& port_number,
    const std::string& document_root)
  : service_context_(),
    termination_signals_(service_context_),
    listening_socket_(service_context_),
    active_connections_(),
    pending_connection_(),
    request_processor_(document_root)
{
  // Set up signal handling for graceful shutdown (SIGINT, SIGTERM, SIGQUIT if available)
  termination_signals_.add(SIGINT);
  termination_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  termination_signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  // Start asynchronous wait for termination signals
  termination_signals_.async_wait(boost::bind(&server::handle_shutdown, this));

  // Configure the acceptor to bind to the specified address and port
  asio::ip::tcp::resolver resolver(service_context_);
  asio::ip::tcp::endpoint bound_endpoint =
    *resolver.resolve(host, port_number).begin();

  listening_socket_.open(bound_endpoint.protocol());
  listening_socket_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  listening_socket_.bind(bound_endpoint);
  listening_socket_.listen();

  // Begin accepting incoming connections
  initiate_accept();
}

// Main execution loop: blocks until all async operations complete
void server::execute()
{
  service_context_.run();
}

// Prepare for next incoming connection by resetting connection object and starting async accept
void server::initiate_accept()
{
  pending_connection_.reset(new connection(service_context_,
        active_connections_, request_processor_));

  listening_socket_.async_accept(pending_connection_->socket(),
      boost::bind(&server::process_accept, this,
        asio::placeholders::error));
}

// Handle completion of an async accept operation
void server::process_accept(const asio::error_code& ec)
{
  // Ignore completion if acceptor was closed (e.g., during shutdown)
  if (!listening_socket_.is_open())
  {
    return;
  }

  if (!ec)
  {
    active_connections_.start(pending_connection_);
  }

  // Continue accepting new connections
  initiate_accept();
}

// Signal handler for graceful shutdown: close acceptor and terminate all connections
void server::handle_shutdown()
{
  listening_socket_.close();
  active_connections_.stop_all();
}

} // namespace server
} // namespace http

