#include <iostream>

class Solution {
public:
    // Find the first bad version in a sequence of versions
    int firstBadVersion(int n) {
        int first_bad = 0;

        // Iterate from the last version backwards
        for (int pos = n; pos >= 1; --pos) {
            if (isBadVersion(pos)) {
                first_bad = pos;
            } else {
                // Stop when we find a good version since we're going backwards
                break;
            }
        }

        return first_bad;
    }
};

