#include "Optimization/ModuleOptimizer.h"
#include <stdexcept>
#include <llvm/Analysis/CGSCCPassManager.h>
#include <llvm/Analysis/LoopAnalysisManager.h>
#include <llvm/IR/Module.h>
#include <llvm/IR/PassManager.h>
#include <llvm/Passes/PassBuilder.h>

namespace llvm_utils {
using namespace llvm;

/// @brief Apply LLVM's standard optimization pipeline to the provided module
/// based on the specified optimization level.
///
/// This function sets up and executes the appropriate sequence of optimization
/// passes using LLVM's PassBuilder, configured for the given optimization level.
///
/// @param modulePtr Pointer to the LLVM module that should be optimized (must not be null)
/// @param optLevel The desired optimization level:
///   - OptimizationLevel::O0: No optimizations (ideal for debugging)
///   - OptimizationLevel::O1: Minimal optimizations
///   - OptimizationLevel::O2: Balanced optimizations (typical for release builds)
///   - OptimizationLevel::O3: Maximum optimizations (may increase binary size)
///
/// @return PreservedAnalyses indicating which analyses remain valid after optimization
///
/// @throws std::invalid_argument if modulePtr is nullptr
auto optimiseModule(Module *modulePtr, OptimizationLevel optLevel)
    -> PreservedAnalyses {
  if (!modulePtr)
    throw std::invalid_argument("Null pointer argument!");

  LoopAnalysisManager loopAM;
  FunctionAnalysisManager funcAM;
  CGSCCAnalysisManager cgsccAM;
  ModuleAnalysisManager modAM;

  PassBuilder pb;
  pb.registerModuleAnalyses(modAM);
  pb.registerCGSCCAnalyses(cgsccAM);
  pb.registerFunctionAnalyses(funcAM);
  pb.registerLoopAnalyses(loopAM);
  pb.crossRegisterProxies(loopAM, funcAM, cgsccAM, modAM);

  return pb.buildPerModuleDefaultPipeline(optLevel).run(*modulePtr, modAM);
}
} // namespace llvm_utils

#include "infiniccl_test.hpp"
#include <iostream>

struct CommandLineOptions {
    infiniDevice_t device_kind;
};

void showHelp() {
    std::cout << "How to use:" << std::endl
              << std::endl;
    std::cout << "infiniccl-test --<device>" << std::endl
              << std::endl;
    std::cout << "  --<device>" << std::endl;
    std::cout << "    Indicate the target device type using --(nvidia|cambricon|ascend|metax|moore|iluvatar|qy|kunlun|hygon|ali)." << std::endl
              << std::endl;
    std::cout << "The application will execute tests on all accessible devices of the chosen device kind."
              << " Control visible device IDs via environment variables like CUDA_VISIBLE_DEVICES.";
    exit(-1);
}

#define HANDLE_DEVICE_OPTION(OPTION, KIND) \
    if (option == OPTION) {                \
        options.device_kind = KIND;        \
    }

CommandLineOptions processArguments(int argc, char *argv[]) {
    if (argc != 2) {
        showHelp();
    }
    if (std::string(argv[1]) == "--help" || std::string(argv[1]) == "-h") {
        showHelp();
    }
    CommandLineOptions options;
    try {
        std::string option = argv[1];
        // clang-format off
        HANDLE_DEVICE_OPTION("--nvidia", INFINI_DEVICE_NVIDIA)
        else HANDLE_DEVICE_OPTION("--cambricon", INFINI_DEVICE_CAMBRICON)
        else HANDLE_DEVICE_OPTION("--ascend", INFINI_DEVICE_ASCEND)
        else HANDLE_DEVICE_OPTION("--metax", INFINI_DEVICE_METAX)
        else HANDLE_DEVICE_OPTION("--moore", INFINI_DEVICE_MOORE)
        else HANDLE_DEVICE_OPTION("--iluvatar", INFINI_DEVICE_ILUVATAR)
        else HANDLE_DEVICE_OPTION("--qy", INFINI_DEVICE_QY)
        else HANDLE_DEVICE_OPTION("--kunlun", INFINI_DEVICE_KUNLUN)
        else HANDLE_DEVICE_OPTION("--hygon", INFINI_DEVICE_HYGON)
        else HANDLE_DEVICE_OPTION("--ali", INFINI_DEVICE_ALI)
        else {
            showHelp();
        }
        // clang-format on
    } catch (...) {
        showHelp();
    }
    return options;
}

int main(int argc, char *argv[]) {
    CommandLineOptions options = processArguments(argc, argv);
    int deviceCount = 0;
    infinirtInit();
    if (infinirtGetDeviceCount(options.device_kind, &deviceCount) != INFINI_STATUS_SUCCESS) {
        std::cout << "Error retrieving number of devices" << std::endl;
        return -1;
    }
    if (deviceCount == 0) {
        std::cout << "No devices detected. Skipping tests." << std::endl;
        return 0;
    } else {
        std::cout << "Detected " << deviceCount << " devices. Executing tests..." << std::endl;
    }
    int errors = 0;
    errors += testAllReduce(options.device_kind, deviceCount);
    return errors;
}

