    // Bind the model to the visual scene — essential for internal setup
    scene.bindmodel(graph);

    // Prepare x-axis data: 11 points from 0 to 10
    sm::vvec<double> abscissae;
    abscissae.linspace(0, 10, 11);

    // Define y-values manually (sampled data)
    sm::vvec<double> ordinates = {4, 7, 3, 8, 2, 1, 5, 6, 9, 2, 0};

    // Configure line style for primary dataset
    mplot::DatasetStyle primary_style(mplot::stylepolicy::lines);
    primary_style.linecolour = mplot::colour::navy;
    primary_style.linewidth = 1.2f;

    // Set fixed y-axis range
    graph->setlimits_y(0, 10);

    // Assign data to the graph
    graph->setdata(abscissae, ordinates, primary_style);

    // Secondary style for horizontal reference line at y=7
    mplot::DatasetStyle ref_line_style(mplot::stylepolicy::lines);
    ref_line_style.linecolour = mplot::colour::slategray;
    ref_line_style.linewidth = primary_style.linewidth * 0.7f;

    // Compute crossing points of the curve with y=7 and draw vertical markers
    sm::vvec<double> crossings = graph->add_y_crossing_lines(abscissae, ordinates, 7, primary_style, ref_line_style);

    // Format annotation string for crossing points
    size_t count = crossings.size();
    std::stringstream msg_stream;
    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            msg_stream << std::format("{}{}{:.2f}", 
                ((idx == 0 || idx == count - 1) ? "" : ", "), 
                (idx == count - 1 ? " and " : ""), 
                crossings[idx]);
        }
    } else {
        msg_stream << "[no intersections]";
    }

    // Place descriptive label in lower-left corner
    graph->addLabel(std::format("y=7 crossed at x = {:s}", msg_stream.str()), 
                    {0.04f, 0.06f, 0.0f}, 
                    mplot::TextFeatures(0.025f));

    // Finalize geometry generation before rendering
    graph->finalize();

    // Transfer ownership of the graph model into the scene
    scene.addVisualModel(graph);

    // Launch interactive window loop
    scene.keepOpen();

    // Automatic cleanup via RAII when 'scene' goes out of scope
    return 0;
}

