bool
bk_util::file_exists (const std::string& filepath)
{
    struct stat info;
    return (stat(filepath.c_str(), &info) == 0);
}

bool
bk_util::file_readable (const std::string& filepath)
{
    if (access(filepath.c_str(), R_OK) != 0) {
        std::cerr << "File access error (" << filepath << "): " << strerror(errno) << std::endl;
        return false;
    }
    return true;
}

/**
 * @brief Extract all non-empty, trimmed lines from a file.
 *
 * This function opens the file located at `filepath`, reads it line by line,
 * trims whitespace from each line, and stores only non-empty results.
 *
 * @note Returns an empty vector if the file is missing, unreadable, or contains
 *       no meaningful content. No exceptions are raised.
 *       Consider using bk_util::file_readable() beforehand to validate access.
 *
 * @param filepath Path to the target file.
 * @return Vector of trimmed, non-empty lines; empty vector on failure or emptiness.
 */
std::vector<std::string>
bk_util::read_lines_from_file(const std::string &filepath)
{
    std::vector<std::string> result;
    if (!std::filesystem::exists(filepath))
        return result;
    std::ifstream input_stream(filepath);
    std::string current_line;
    while (std::getline(input_stream, current_line)) {
        current_line = bk_util::trim_string(current_line);
        if (!current_line.empty())
            result.push_back(current_line);
    }
    return result;
}

void
bk_util::make_file_world_readable(const std::string &filepath)
{
    std::filesystem::permissions(
        filepath,
        std::filesystem::perms::owner_read |
        std::filesystem::perms::owner_write |
        std::filesystem::perms::group_read |
        std::filesystem::perms::others_read,
        std::filesystem::perm_options::add
    );
}

// Wrapper: load file into memory and apply in-memory search logic
std::vector<std::string>
bk_util::find_lines_matching_substring_in_file(
    const std::string &filepath,
    const std::vector<std::string> &patterns_to_match,
    bool case_insensitive,
    size_t max_result_lines_count)
{
    // Load all lines from the file
    std::vector<std::string> loaded_lines = bk_util::read_lines_from_file(filepath);
    // Perform matching against the loaded data
    return bk_util::find_lines_matching_substring_in_vector(
        loaded_lines,
        patterns_to_match,
        case_insensitive,
        max_result_lines_count
    );
}

// Overload for single pattern: convert to vector and reuse existing logic
std::vector<std::string>
bk_util::find_lines_matching_substring_in_file(
    const std::string &filepath,
    const std::string &pattern_to_match,
    bool case_insensitive,
    size_t max_result_lines_count)
{
    return bk_util::find_lines_matching_substring_in_file(
        filepath,
        std::vector<std::string>{ pattern_to_match },
        case_insensitive,
        max_result_lines_count
    );
}

#include <iostream>
#include <vector>

// Helper function for interactive queries
int ask(int left, int right) {
    std::cout << "? " << left << " " << right << std::endl;
    int response;
    std::cin >> response;
    if (response == -1) {
        exit(0);
    }
    return response;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;

    std::vector<int> permutation(size + 1);
    std::vector<int> orResults(size + 1);

    // First phase: get OR values between first element and all others
    for (int idx = 2; idx <= size; ++idx) {
        orResults[idx] = ask(1, idx);
    }

    // Second phase: compute the actual value of first element
    // Using the property that AND of all (p[1]|p[i]) gives p[1]
    int firstValue = -1;  // All bits set initially
    for (int idx = 2; idx <= size; ++idx) {
        if (firstValue == -1) {
            firstValue = orResults[idx];
        } else {
            firstValue &= orResults[idx];
        }
    }
    permutation[1] = firstValue;

    // Third phase: derive remaining elements
    // Since we know p[1] and p[1]|p[i], and one element must be 0,
    // the OR results directly give us the other elements
    for (int idx = 2; idx <= size; ++idx) {
        permutation[idx] = orResults[idx];
    }

    // Output the result
    std::cout << "!";
    for (int idx = 1; idx <= size; ++idx) {
        std::cout << " " << permutation[idx];
    }
    std::cout << std::endl;

    return 0;
}

