  mov_io::addParsers(&mainSrv);
  _3gp_io::addParsers(&mainSrv);
#ifdef MACOSX
  font_io::addParsers(&mainSrv);
#endif

  // Listen on main-specific endpoint
  bool bound = mainSrv.listen(serverKey + "_main");

  app.exec();
