namespace Kernel {

/// @brief Launches a new kernel-mode task from a given function entry point.
/// @note This initializes a fresh stack context; any local state from the caller is not preserved.
/// @param entry_point the starting address of the new task's execution.
/// @param task_id the unique Kernel ID assigned to the new task.
/// @return TRUE if the task was successfully created, FALSE otherwise.
BOOL rtl_create_kernel_task(HAL::StackFramePtr entry_point, const KID task_id) {
  if (!task_id || entry_point == nullptr) return FALSE;
  return KernelTaskHelper::Add(entry_point, task_id);
}

/***********************************************************************************/
/// @brief Spawns a new user-mode process from a specified entry function.
/// @note This creates an isolated address space and scheduling context for the process.
/// @param start_routine the function pointer where the process begins execution.
/// @param name the human-readable identifier for the process.
/// @return the process identifier on success, or kSchedInvalidPID on failure.
/***********************************************************************************/
ProcessID rtl_create_user_process(rtl_start_kind start_routine, const Char* process_name) {
  if (!process_name || *process_name == 0) return kSchedInvalidPID;
  return UserProcessScheduler::The().Spawn(process_name, reinterpret_cast<VoidPtr>(start_routine), nullptr);
}

}  // namespace Kernel

#include "asio/buffer.hpp"
#include "asio/io_context.hpp"
#include "asio/ip/udp.hpp"
#include <cstdlib>
#include <functional>
#include <iostream>

using asio::ip::udp;
using std::placeholders::_1;
using std::placeholders::_2;

//----------------------------------------------------------------------
// This class handles socket operations with timeout control by using 
// io_context::run_for(). Each async operation has a time limit to complete.
// The handlers are bound using std::bind:
//
//   +----------------+
//   |                |
//   |    recv_data   |
//   |                |
//   +----------------+
//           |
//  async_-  |    +------------------+
// receive() |    |                  |
//           +--->| on_receive_done  |
//                |                  |
//                +------------------+
//
// For each socket call, the client runs the io_context until completion or 
// timeout. If run_for() expires, the socket is closed and pending async op 
// is cancelled.
//
class udp_client
{
public:
  udp_client(const udp::endpoint& local_endpoint)
    : sock_(context_, local_endpoint)
  {
  }

  std::size_t recv(asio::mutable_buffer buf,
      std::chrono::steady_clock::duration limit,
      std::error_code& ec)
  {
    std::size_t bytes = 0;
    sock_.async_receive(asio::buffer(buf),
        std::bind(&udp_client::on_recv_complete, _1, _2, &ec, &bytes));

    wait(limit);
    return bytes;
  }

private:
  void wait(std::chrono::steady_clock::duration limit)
  {
    context_.restart();
    context_.run_for(limit);

    if (!context_.stopped())
    {
      sock_.cancel();
      context_.run();
    }
  }

  static void on_recv_complete(
      const std::error_code& err, std::size_t count,
      std::error_code* p_ec, std::size_t* p_count)
  {
    *p_ec = err;
    *p_count = count;
  }

private:
  asio::io_context context_;
  udp::socket sock_;
};
//----------------------------------------------------------------------

int main(int argc, char* argv[])
{
  try
  {
    using namespace std; // For atoi
    if (argc != 3)
    {
      cerr << "Usage: blocking_udp_client <listen_addr> <listen_port>\n";
      return 1;
    }

    udp::endpoint listen_addr(
        asio::ip::make_address(argv[1]),
        atoi(argv[2]));

    udp_client client(listen_addr);

    for (;;)
    {
      char buffer[2048];
      error_code err;
      size_t received = client.recv(asio::buffer(buffer),
          std::chrono::seconds(5), err);

      if (err)
      {
        cout << "Recv failed: " << err.message() << "\n";
      }
      else
      {
        cout << "Got: ";
        cout.write(buffer, received);
        cout << "\n";
      }
    }
  }
  catch (const exception& ex)
