#include "lib/common/demangle.hpp"
#include <gtest/gtest.h>
#include <string_view>
#include <utility>

// Test suite for demangling functionality
TEST(common, demangling)
{
    // This test verifies the cxx_demangle function behavior:
    // - Correctly demangles valid mangled names
    // - Returns original string when demangling fails
    using pair_type = std::pair<std::string_view, std::string_view>;

    for(auto [input_mangled, expected_demangled] :
        {pair_type{"_ZN11rocprofiler8internal18correlation_config22get_unique_internal_idEv",
                   "rocprofiler::internal::correlation_config::get_unique_internal_id()"},
         pair_type{"_ZN11rocprofiler8internal18get_active_configsEv",
                   "rocprofiler::internal::get_active_configs()"},
         pair_type{"_ZN11rocprofiler8internal22get_registered_configsEv",
                   "rocprofiler::internal::get_registered_configs()"},
         pair_type{
             "_ZZN11rocprofiler8internal18correlation_config22get_unique_internal_idEvE2_v",
             "rocprofiler::internal::correlation_config::get_unique_internal_id()::_v"},
         pair_type{"_ZZN11rocprofiler8internal18get_active_configsEvE2_v",
                   "rocprofiler::internal::get_active_configs()::_v"},
         pair_type{"_ZZN11rocprofiler8internal22get_registered_configsEvE2_v",
                   "rocprofiler::internal::get_registered_configs()::_v"}})
    {
        // Check that demangling works correctly
        EXPECT_EQ(rocprofiler::common::cxx_demangle(input_mangled), expected_demangled)
            << "failed to demangle '" << input_mangled << "'";

        // Verify that malformed mangled strings are returned unchanged
        auto invalid_mangled = std::string{"_Z"} + std::string{input_mangled};
        EXPECT_EQ(rocprofiler::common::cxx_demangle(invalid_mangled), invalid_mangled)
            << "demangling succeeded for '" << invalid_mangled << "'";
    }
}

// Test suite for name truncation functionality
TEST(common, truncate)
{
    // This test verifies that truncate_name correctly extracts function names
    // from complex template instantiations

    auto mangled_input = std::string_view{"_ZSt16__do_uninit_copyIPKSt4pairINSt7__cxx1112basic_"
                                          "stringIcSt11char_traitsIcESaIcEEES6_EPS7_ET0_T_SC_SB_"};
    auto full_demangled_output = std::string_view{
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >* "
        "std::__do_uninit_copy<std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > "
        ">*>(std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > const*, "
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >*)"};

    EXPECT_EQ(rocprofiler::common::cxx_demangle(mangled_input), full_demangled_output);
    EXPECT_EQ(rocprofiler::common::truncate_name(full_demangled_output),
              std::string_view{"__do_uninit_copy"});
    EXPECT_EQ(rocprofiler::common::truncate_name(rocprofiler::common::cxx_demangle(mangled_input)),
              std::string_view{"__do_uninit_copy"});
}

#include "WifiTypeConfigurator.h"

std::string WifiTypeConfigurator::setupConnection(TerminalTypeEnum& deviceType) {
    switch (deviceType)
    {
    case TerminalTypeEnum::WiFiClient:
        #if defined(DEVICE_CARDPUTER)
            // Configure cardputer in standalone mode
            initializeCardputerNetwork(); // blocks until successful connection
        #elif defined(DEVICE_STICKS3)
            // Initialize in access point mode
            initializeStickNetwork(); // verify saved credentials
        #elif defined(DEVICE_TEMBEDS3) || defined(DEVICE_TEMBEDS3CC1101)
            // Dedicated setup for embedded variant
            initializeTembedNetwork(display); // waits until a working WiFi link is established
        #elif defined(DEVICE_TDISPLAYS3)
            initializeTdisplayNetwork(display); // blocks until connected to valid network
        #else
            // Generic ESP32 configuration
            initializeS3Network(); // validate stored authentication data
        #endif
        return std::string(WiFi.localIP().toString().c_str());
    case TerminalTypeEnum::WiFiAp: {
        return "";
    }
    default:
        break;
    }
    return "";
}

