// Entry point for the command-line interface client
// Designed for terminal-based interaction and management
int main(int argc, char* argv[]) {
    // Note: Single-instance validation has been relocated to the 'serve' command only
    // This enables commands like status, list, pull, delete, stop to execute even when the server is running
    try {
        lemon::CLIParser cliParser;
        cliParser.parse(argc, argv);
        if (!cliParser.should_proceed()) {
            return cliParser.get_exit_code();
        }

        // Setup logging system
        auto settings = cliParser.get_config();
        auto consoleSink = std::make_shared<AixLog::SinkCout>(AixLog::Filter(AixLog::to_severity(settings.log_verbosity)), "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message");
        AixLog::Log::initialize({consoleSink});

        lemon_tray::TrayApp application(settings, cliParser.get_tray_configuration());
        return application.execute();
    } catch (const std::runtime_error& ex) {
        LOG(ERROR) << "Critical error encountered: " << ex.what() << std::endl;
        return 1;
    } catch (...) {
        LOG(ERROR) << "Unexpected critical error occurred" << std::endl;
        return 1;
    }
}

