std::shared_ptr<MOBase::IFileTree> InstallDialog::getModifiedTree() const
{
  return m_FileTree->root()->item()->filetree();
}

bool InstallDialog::validateContent()
{
  if (!m_Validator) {
    return true;
  }
  return m_Validator->isDataStructureValid(m_FileTree->root()->item()->filetree()) ==
         ModDataValidator::ValidationResult::CORRECT;
}

void InstallDialog::refreshValidationStatus()
{
  if (!m_Validator) {
    m_FileTree->setStyleSheet("QTreeWidget { border: none; }");
    m_StatusLabel->setText(
        tr("Unable to verify the structure of <%1>.").arg(m_DataDirectoryName));
    m_StatusLabel->setToolTip(tr("The active game plugin does not support content validation for <%1>.")
                                   .arg(m_DataDirectoryName));
    m_StatusLabel->setStyleSheet("color: #8B4513;");
  } else if (validateContent()) {
    m_FileTree->setStyleSheet(
        "QTreeWidget { border: 2px solid #006400; border-radius: 3px; }");
    m_StatusLabel->setText(
        tr("Structure of <%1> appears correct.").arg(m_DataDirectoryName));
    m_StatusLabel->setToolTip(
        tr("Structure of <%1> is consistent with expectations for the current game.")
            .arg(m_DataDirectoryName));
    m_StatusLabel->setStyleSheet("color: #006400;");
  } else {
    m_FileTree->setStyleSheet("QTreeWidget { border: 2px solid #FF0000; border-radius: 3px; }");
    m_StatusLabel->setText(
        tr("Structure of <%1> seems invalid.").arg(m_DataDirectoryName));
    m_StatusLabel->setToolTip(
        tr("Structure of <%1> likely does not conform to game requirements.")
            .arg(m_DataDirectoryName));
    m_StatusLabel->setStyleSheet("color: #FF0000;");
  }
}

void InstallDialog::addNewDirectory(ArchiveTreeWidgetItem* node)
{
  // Guard clause: ensure only directories can be used as parents
  if (!node->item()->isDirectory()) {
    showError(tr("Cannot create a subdirectory inside a file."));
    return;
  }

  auto tree = node->item()->filetree();
  bool confirmed = false;
  QString inputName = QInputDialog::getText(this, tr("New Directory Name"), tr("Enter name:"),
                                         QLineEdit::Normal, QString(), &confirmed);
  inputName = inputName.simplified();

  if (confirmed && !inputName.isEmpty()) {
    if (tree->hasEntry(inputName)) {
      showError(tr("An item with this name already exists."));
      return;
    }

    node->setExpanded(true);
    auto* createdNode = m_FileTree->insertDirectory(node, inputName);
    m_FileTree->scrollToItem(createdNode);
  }
}

void InstallDialog::on_treeContent_customContextMenuRequested(QPoint position)
{
  ArchiveTreeWidgetItem* selected =
      static_cast<ArchiveTreeWidgetItem*>(m_FileTree->itemAt(position));
  if (selected == nullptr) {
    return;
  }

  QMenu contextMenu;

  if (selected != m_FileTree->root() && selected->item()->isDirectory()) {
    contextMenu.addAction(tr("Mark as <%1> folder").arg(m_DataDirectoryName),
                   [this, selected]() {
                     m_FileTree->setRootItem(selected);
                   });
  }

  if (m_FileTree->root()->item() != m_DefaultRoot->item()) {
    contextMenu.addAction(tr("Reset <%1> folder").arg(m_DataDirectoryName), [this]() {
      m_FileTree->setRootItem(m_DefaultRoot);
    });
  }

  if (!contextMenu.isEmpty()) {
    contextMenu.addSeparator();
  }

  if (selected->item()->isDirectory()) {
    contextMenu.addAction(tr("Create subdirectory..."), [this, selected]() {
      addNewDirectory(selected);
    });
  } else {
    contextMenu.addAction(tr("&Open File"), [this, selected]() {
      emit openRequested(selected->item().get());
    });
  }

  contextMenu.exec(m_FileTree->mapToGlobal(position));
}

void InstallDialog::on_acceptButton_clicked()
{
  if (!validateContent()) {
    if (QMessageBox::question(
            this, tr("Confirm Installation?"),
            tr("This mod may have been configured incorrectly and might not function properly. "
               "It is recommended to review and adjust the folder layout in the tree view first."),
            QMessageBox::Yes | QMessageBox::No,
            QMessageBox::No) == QMessageBox::No) {
      return;
    }
  }

  accept();
}

void InstallDialog::on_cancelButton_clicked()
{
  reject();
}

