#include <vector>
#include <algorithm>
#include <iostream>

const int MAX_VAL = 10001, MAX_NODES = 6400;
const int BIG_NUM = 1000000007;

// pos_by_val[value] stores 1D indices of positions (i, j) where grid has that value
std::vector<int> pos_by_val[MAX_VAL]; 

// dp[teleports_used][position] = minimum cost
unsigned dp[11][MAX_NODES]; 

// suffix_min[value] = minimum dp[t-1][idx] for all idx with grid value >= value
unsigned suffix_min[MAX_VAL]; 

class Solution {
public:
    // Convert 2D coordinates to 1D index
    static inline int get_index(int row, int col, int cols) { 
        return row * cols + col; 
    }

    static int minCost(std::vector<std::vector<int>>& grid, int max_teleports) {
        const int rows = grid.size(), cols = grid[0].size(), total_cells = rows * cols;
        int max_grid_value = 0;

        // Group cell indices by their grid values
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                const int val = grid[i][j];
                pos_by_val[val].push_back(get_index(i, j, cols));
                max_grid_value = std::max(max_grid_value, val);
            }
        }

        // Initialize DP table with large values
        for (int t = 0; t <= max_teleports; t++) {
            std::fill(dp[t], dp[t] + total_cells, BIG_NUM);
        }

        // Base case: zero teleports - only moving right or down
        dp[0][0] = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                const int pos = get_index(i, j, cols), val = grid[i][j];
                if (i > 0) {
                    dp[0][pos] = std::min(dp[0][pos], dp[0][get_index(i-1, j, cols)] + val);
                }
                if (j > 0) {
                    dp[0][pos] = std::min(dp[0][pos], dp[0][get_index(i, j-1, cols)] + val);
                }
            }
        }

        // DP with teleport operations
        for (int t = 1; t <= max_teleports; t++) {
            // Compute suffix minimums for current teleport count
            unsigned current_min = BIG_NUM;
            for (int val = max_grid_value; val >= 0; val--) {
                for (int position : pos_by_val[val]) {
                    current_min = std::min(current_min, dp[t-1][position]);
                }
                suffix_min[val] = current_min; // teleport option
            }

            // Update DP for current teleport count
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    const int pos = get_index(i, j, cols), val = grid[i][j];

                    // Best between previous teleport count or teleporting here
                    dp[t][pos] = std::min(dp[t-1][pos], suffix_min[val]);

                    // Step from top cell
                    if (i > 0) {
                        dp[t][pos] = std::min(dp[t][pos], dp[t][get_index(i-1, j, cols)] + val);
                    }

                    // Step from left cell
                    if (j > 0) {
                        dp[t][pos] = std::min(dp[t][pos], dp[t][get_index(i, j-1, cols)] + val);
                    }
                }
            }
        }

        int result = dp[max_teleports][total_cells - 1];

        // Clean up for next test case
        for (int val = 1; val <= max_grid_value; val++) {
            pos_by_val[val].clear();
        }

        return result;
    }
};

