void SaveTestFile( const std::string &filePath )
{
    std::cout << "Starting SaveTestFile()" << std::endl;
    AA::MetaData meta;
    AO::WriteArchive writer;

    AA::ObjectWriterPtr childObj;
    AA::ArchiveWriterPtr archive = writer( filePath, meta );

    AA::ObjectWriterPtr root = archive->getTop();
    childObj = root->createChild(
        AA::ObjectHeader( "child0", meta ) );

    std::cout << "Exiting SaveTestFile()" << std::endl;
}
//-*****************************************************************************
void LoadTestFile( const std::string &filePath )
{
    std::cout << "Starting LoadTestFile()" << std::endl;
    AO::ReadArchive reader;

    AA::ObjectReaderPtr loadedChild;
    AA::ArchiveReaderPtr archive = reader( filePath );

    AA::ObjectReaderPtr root = archive->getTop();
    loadedChild = root->getChild( 0 );

    std::cout << "Loaded object full name: " << loadedChild->getFullName()
              << std::endl;
    std::cout << "Finished LoadTestFile()" << std::endl;
}
