#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    // Speed up input/output operations
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int participants, rounds;
    // Read number of participants and wager rounds
    if (cin >> participants >> rounds) {
        // Initialize expert weights to 1.0 each
        vector<double> weights(participants, 1.0);

        // Decay factor for incorrect predictions
        // Lower values penalize mistakes more heavily
        double decay = 0.8; 

        for (int round = 0; round < rounds; ++round) {
            string predictions;
            cin >> predictions;

            // Compute weighted votes for each option
            double vote0 = 0.0;
            double vote1 = 0.0;
            for (int i = 0; i < participants; ++i) {
                if (predictions[i] == '0') {
                    vote0 += weights[i];
                } else {
                    vote1 += weights[i];
                }
            }

            // Make prediction based on weighted majority
            char prediction = (vote1 > vote0) ? '1' : '0';
            cout << prediction << endl; // Ensure output is flushed

            // Get actual result
            char result;
            cin >> result;

            // Update weights for experts who were wrong
            double highestWeight = 0.0;
            for (int i = 0; i < participants; ++i) {
                if (predictions[i] != result) {
                    weights[i] *= decay;
                }
                if (weights[i] > highestWeight) {
                    highestWeight = weights[i];
                }
            }

            // Prevent floating-point underflow by rescaling if needed
            if (highestWeight < 1e-150) {
                for (int i = 0; i < participants; ++i) {
                    weights[i] *= 1e150;
                }
            }
        }
    }
    return 0;
}

