// Wrapper for memcpy to ensure compatibility with older glibc versions
// By using the 2.2.5 symbol version on x86-64 Linux, we avoid requiring glibc 2.14+
// This allows the distributed gem to work on systems with older glibc versions
// (see https://github.com/protocolbuffers/protobuf/issues/2783)
//
// Activation: pass -Wl,-wrap,memcpy as linker flag in extconf.rb

#ifdef __linux__
#if defined(__x86_64__) && defined(__GNU_LIBRARY__)
__asm__(".symver memcpy,memcpy@GLIBC_2.2.5");
void* my_memcpy_wrapper(void* destination, const void* source, size_t count) {
    return memcpy(destination, source, count);
}
#else
void* my_memcpy_wrapper(void* destination, const void* source, size_t count) {
    return memmove(destination, source, count);
}
#endif
#endif

