#include <vector>
#include <algorithm>

class Solution {
public:
    // Rearrange array so that all zeros are moved to the end
    void moveZeroes(std::vector<int>& arr) {
        int len = arr.size();

        // Bubble zeros to the right through adjacent swaps
        for (int pass = 0; pass < len - 1; pass++) {
            for (int idx = 0; idx < len - 1; idx++) {
                if (arr[idx] == 0) {
                    std::swap(arr[idx], arr[idx + 1]);
                }
            }
        }
    }
};

#include <iostream>
#include <climits>
using namespace std;

// Structure representing a node in a binary tree
struct BinaryTreeNode {
     int value;
     BinaryTreeNode *leftChild;
     BinaryTreeNode *rightChild;
     BinaryTreeNode() : value(0), leftChild(nullptr), rightChild(nullptr) {}
     BinaryTreeNode(int x) : value(x), leftChild(nullptr), rightChild(nullptr) {}
     BinaryTreeNode(int x, BinaryTreeNode *left, BinaryTreeNode *right) : value(x), leftChild(left), rightChild(right) {}
};

class Validator {
public:
    bool checkBST(BinaryTreeNode* node, long lowerBound, long upperBound) {
        if (!node) return true; // Null subtree is valid
        // Verify current node respects the allowed range
        if (node->value <= lowerBound || node->value >= upperBound) {
            return false;
        }
        // Validate left and right subtrees with updated bounds
        return checkBST(node->leftChild, lowerBound, node->value) &&
               checkBST(node->rightChild, node->value, upperBound);
    }
    bool validateBinarySearchTree(BinaryTreeNode* root) {
        return checkBST(root, LONG_MIN, LONG_MAX);
    }
};

