#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <random>
#include <chrono>

// Modulus used in the cryptographic computation
long long modulus_n;

// Performs modular multiplication using __int128 to avoid overflow
long long mod_multiply(long long x, long long y, long long mod) {
    return static_cast<long long>((static_cast<__int128>(x) * y) % mod);
}

// Returns the number of bits required to represent x in binary
// For x=0 returns 0; otherwise floor(log2(x)) + 1
int bit_count(long long x) {
    if (x == 0) return 0;
    return 64 - __builtin_clzll(x);
}

// Sends a query with value 'val' and retrieves the response time from device
long long query_device(long long val) {
    std::cout << "? " << val << std::endl;
    long long response_time;
    std::cin >> response_time;
    return response_time;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Read the public modulus
    std::cin >> modulus_n;

    // Secret exponent being recovered, bit by bit
    long long secret_exponent = 0;

    // Random number generator seeded with high-resolution clock
    std::mt19937_64 prng(std::chrono::steady_clock::now().time_since_epoch().count());

    // Recover each bit of the secret exponent from LSB to MSB (0 to 59)
    for (int bit_position = 0; bit_position < 60; ++bit_position) {
        long double accumulated_score = 0.0L;
        const int sample_count = 40;

        for (int sample_index = 0; sample_index < sample_count; ++sample_index) {
            long long base_value = std::uniform_int_distribution<long long>(2, modulus_n - 1)(prng);

            long long observed_total_time = query_device(base_value);

            // Precompute powers: a_i = a^(2^i) mod n
            std::vector<long long> power_sequence(60);
            std::vector<int> power_bit_counts(60);
            power_sequence[0] = base_value;
            for (int i = 1; i < 60; ++i) {
                power_sequence[i] = mod_multiply(power_sequence[i - 1], power_sequence[i - 1], modulus_n);
            }
            for (int i = 0; i < 60; ++i) {
                power_bit_counts[i] = bit_count(power_sequence[i]) + 1;
            }

            // Compute constant part C(a) independent of secret bits
            long long constant_part = 0;
            for (int i = 0; i < 60; ++i) {
                constant_part += static_cast<long long>(power_bit_counts[i]) * power_bit_counts[i];
            }

            long long known_bits = secret_exponent;

            // Compute contribution from already-known lower bits
            long long known_contribution = 0;
            long long running_r = 1;
            for (int i = 0; i < bit_position; ++i) {
                if ((known_bits >> i) & 1) {
                    known_contribution += static_cast<long long>(bit_count(running_r) + 1) * power_bit_counts[i];
                    running_r = mod_multiply(running_r, power_sequence[i], modulus_n);
                }
            }

            long long remaining_r = running_r;
            long long residual_time = observed_total_time - constant_part - known_contribution;

            // Cost contribution if current bit is 1
            long long cost_if_one = static_cast<long long>(bit_count(remaining_r) + 1) * power_bit_counts[bit_position];

            // Statistical test: positive score suggests d_k = 1
            accumulated_score += residual_time - static_cast<long double>(cost_if_one) / 2.0L;
        }

        // Decide bit value based on average score
        if (accumulated_score > 0) {
            secret_exponent |= (1LL << bit_position);
        }
    }

    // Output the recovered secret exponent
    std::cout << "! " << secret_exponent << std::endl;
    return 0;
}

