typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType FDisplayClusterClusterEventsBinaryService::ProcessPacket(const TSharedPtr<FDisplayClusterPacketBinary>& InRequest)
{
	// Validate the incoming packet
	if (!InRequest.IsValid())
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - Invalid request data (nullptr)"), *GetName());
		return IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
	}

	// Translate network packet into internal event representation
	FDisplayClusterClusterEventBinary InternalEvent;
	if (!DisplayClusterNetworkDataConversion::BinaryPacketToBinaryEvent(InRequest, InternalEvent))
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - failed to convert net packet to binary event"), *GetName());
		return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
	}

	// Forward the event internally
	UE_LOG(LogDisplayClusterNetwork, Verbose, TEXT("%s - propagating cluster event for intra-cluster synchronization..."), *GetName());
	EmitClusterEventBinary(InternalEvent);
	return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType();
}

