#define HIP_ERROR_CHECK(expr)                         \
{                                                     \
    const hipError_t err = expr;                      \
    if (err != hipSuccess)                            \
    {                                                 \
        std::cerr << "HIP error " << err              \
                  << ": " << hipGetErrorString(err)   \
                  << " at " << __FILE__ << ":"        \
                  << __LINE__ << std::endl;           \
        std::exit(EXIT_FAILURE);                      \
    }                                                 \
}

// Structure to hold memory pool usage data
struct memPoolStats
{
    std::uint64_t currentReserved;
    std::uint64_t peakReserved;
    std::uint64_t currentUsed;
    std::uint64_t peakUsed;
};

// Retrieve current and peak memory usage metrics from the pool
void fetchMemoryStats(hipMemPool_t pool, struct memPoolStats *stats)
{
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemCurrent, &stats->currentReserved));
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemHigh, &stats->peakReserved));
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemCurrent, &stats->currentUsed));
    HIP_ERROR_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemHigh, &stats->peakUsed));
}

// Reset high-watermark counters to their current values
void resetPeakCounters(hipMemPool_t pool)
{
    std::uint64_t zeroValue = 0;
    HIP_ERROR_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrReservedMemHigh, &zeroValue));
    HIP_ERROR_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrUsedMemHigh, &zeroValue));
}

int main()
{
    hipMemPool_t memoryPool;
    hipDevice_t devId = 0; // Device identifier

    // Set active device
    HIP_ERROR_CHECK(hipSetDevice(devId));

    // Obtain default memory pool for the device
    HIP_ERROR_CHECK(hipDeviceGetDefaultMemPool(&memoryPool, devId));

    // Allocate a 2 MB block from the pool
    std::size_t blockSize = 2 * 1024 * 1024;
    void* buffer;
    HIP_ERROR_CHECK(hipMalloc(&buffer, blockSize));

    // Release the allocated memory back to the pool
    HIP_ERROR_CHECK(hipFree(buffer));

    // Trim the pool's reserved memory to 768 KB
    std::size_t targetSize = 768 * 1024;
    HIP_ERROR_CHECK(hipMemPoolTrimTo(memoryPool, targetSize));

    // Collect and display statistics before resetting peaks
    memPoolStats preStats;
    fetchMemoryStats(memoryPool, &preStats);

    std::cout << "Before resetting high-watermarks:" << std::endl;
    std::cout << "Reserved Memory (current): " << preStats.currentReserved << " bytes" << std::endl;
    std::cout << "Reserved Memory (peak):    " << preStats.peakReserved << " bytes" << std::endl;
    std::cout << "Used Memory (current):     " << preStats.currentUsed << " bytes" << std::endl;
    std::cout << "Used Memory (peak):        " << preStats.peakUsed << " bytes" << std::endl;

    // Reset high-watermark counters
    resetPeakCounters(memoryPool);

    // Collect and display statistics after resetting peaks
    memPoolStats postStats;
    fetchMemoryStats(memoryPool, &postStats);

    std::cout << "After resetting high-watermarks:" << std::endl;
    std::cout << "Reserved Memory (current): " << postStats.currentReserved << " bytes" << std::endl;
    std::cout << "Reserved Memory (peak):    " << postStats.peakReserved << " bytes" << std::endl;
    std::cout << "Used Memory (current):     " << postStats.currentUsed << " bytes" << std::endl;
    std::cout << "Used Memory (peak):        " << postStats.peakUsed << " bytes" << std::endl;

    return EXIT_SUCCESS;
}

