		OnExtendActorDetails.AddRaw(this, &FCodeViewerModule::AppendCodeSection);
	}

	virtual void ShutdownModule() override
	{
		OnExtendActorDetails.RemoveAll(this);
	}
	// End of IModuleInterface implementation

	void AppendCodeSection(IDetailLayoutBuilder& LayoutBuilder, const FGetSelectedActors& SelectedActors)
	{
		ISourceCodeAccessModule* SourceAccessorModule = FModuleManager::GetModulePtr<ISourceCodeAccessModule>("SourceCodeAccess");
		if(SourceAccessorModule != nullptr && SourceAccessorModule->GetAccessor().CanAccessSourceCode())
		{
			TSharedRef< CodeView::SCodeView > ViewerWidget =
				SNew( CodeView::SCodeView )
				.GetSelectedActors( SelectedActors );

			const bool bExpandOnLoad = ViewerWidget->IsReadyToPopulate();

			LayoutBuilder.EditCategory( "CodeViewer", NSLOCTEXT("ActorDetails", "CodeViewerSection", "Code View"), ECategoryPriority::Uncommon )
				.InitiallyCollapsed( !bExpandOnLoad )
				.RestoreExpansionState( false )
				.OnExpansionChanged( FOnBooleanValueChanged::CreateSP( ViewerWidget, &CodeView::SCodeView::OnDetailSectionExpansionChanged ) )
				.AddCustomRow( NSLOCTEXT("ActorDetails", "CodeViewerSection", "Code View") )
				[
					ViewerWidget
				];
		}
	}
};

