#include "server.hpp"
#include <boost/bind.hpp>

namespace http {
namespace server2 {

// Constructor for the HTTP server
server::server(const std::string& host, const std::string& port_str,
    const std::string& document_path, std::size_t thread_pool_size)
  : thread_pool_(thread_pool_size),
    stop_signals_(thread_pool_.get_io_context()),
    tcp_acceptor_(thread_pool_.get_io_context()),
    client_connection_(),
    request_processor_(document_path)
{
  // Set up signal handling for graceful shutdown
  stop_signals_.add(SIGINT);
  stop_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  stop_signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  stop_signals_.async_wait(boost::bind(&server::on_shutdown, this));

  // Configure the TCP acceptor with address resolution and socket options
  asio::ip::tcp::resolver resolver(tcp_acceptor_.get_executor().context());
  asio::ip::tcp::endpoint listening_endpoint =
    *resolver.resolve(host, port_str).begin();

  tcp_acceptor_.open(listening_endpoint.protocol());
  tcp_acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  tcp_acceptor_.bind(listening_endpoint);
  tcp_acceptor_.listen();

  initiate_accept();
}

// Start the server's main event loop
void server::run()
{
  thread_pool_.run();
}

// Prepare for next incoming connection
void server::initiate_accept()
{
  client_connection_.reset(new connection(
        thread_pool_.get_io_context(), request_processor_));

  tcp_acceptor_.async_accept(client_connection_->socket(),
      boost::bind(&server::on_connection_established, this,
        asio::placeholders::error));
}

// Handle successful connection acceptance
void server::on_connection_established(const asio::error_code& error)
{
  if (!error)
  {
    client_connection_->process_request();
  }

  initiate_accept();
}

// Stop all I/O contexts in the pool
void server::on_shutdown()
{
  thread_pool_.stop();
}

