#include <vector>
#include <string>

class ParenthesisGenerator {
public:
    // Generate all valid parenthesis combinations using backtracking
    void backtrack(int openRemaining, int closeRemaining, std::string current, std::vector<std::string>& results) {
        // When no closing parentheses left, we have a complete valid combination
        if (closeRemaining == 0) {
            results.push_back(current);
        }

        // We can add a closing parenthesis only if we have more closing than opening remaining
        if (closeRemaining > openRemaining) {
            backtrack(openRemaining, closeRemaining - 1, current + ")", results);
        }

        // We can add an opening parenthesis if we still have some remaining
        if (openRemaining > 0) {
            backtrack(openRemaining - 1, closeRemaining, current + "(", results);
        }
    }

    std::vector<std::string> generateParenthesis(int n) {
        int openCount = n;
        int closeCount = n;
        std::string initialString = "";
        std::vector<std::string> allCombinations;

        backtrack(openCount, closeCount, initialString, allCombinations);
        return allCombinations;
    }
};

