#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

class timer_printer
{
public:
  timer_printer(asio::io_context& context)
    : interval_timer_(context, asio::chrono::seconds(1)),
      counter_(0)
  {
    interval_timer_.async_wait(boost::bind(&timer_printer::show_count, this));
  }

  ~timer_printer()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

  void show_count()
  {
    if (counter_ < 5)
    {
      std::cout << counter_ << std::endl;
      ++counter_;
      interval_timer_.expires_at(interval_timer_.expiry() + asio::chrono::seconds(1));
      interval_timer_.async_wait(boost::bind(&timer_printer::show_count, this));
    }
  }

private:
  asio::steady_timer interval_timer_;
  int counter_;
};

int main()
{
  asio::io_context service;
  timer_printer instance(service);
  service.run();
  return 0;
}

#define BOOST_TEST_MODULE elias_fano_tests
#include "test_common.hpp"
#include "test_rank_select_common.hpp"
#include <cstdlib>
#include <boost/foreach.hpp>
#include "mapper.hpp"
#include "elias_fano.hpp"

BOOST_AUTO_TEST_CASE(elias_fano_comprehensive)
{
    srand(12345);
    size_t length = 8000;
    {
        // Random bit patterns with varying densities
        for (size_t bits_per_block = 2; bits_per_block < 9; ++bits_per_block) {
            double sparsity = 1.0 / (1 << bits_per_block);
            std::vector<bool> data = random_bit_vector(length, sparsity);
            succinct::bit_vector_builder builder;
            for (size_t idx = 0; idx < data.size(); ++idx) {
                builder.push_back(data[idx]);
            }
            succinct::elias_fano structure(&builder);
            test_equal_bits(data, structure, "Random bit pattern");
            test_rank_select1(data, structure, "Random bit pattern");
            test_delta(structure, "Random bit pattern");
            test_select_enumeration(data, structure, "Random bit pattern");
        }
    }
    {
        // Zero ones bitmap
        succinct::bit_vector_builder builder(length);
        succinct::elias_fano structure(&builder);
        BOOST_REQUIRE_EQUAL(0U, structure.num_ones());
        test_equal_bits(std::vector<bool>(length), structure, "Zero ones bitmap");
        test_select_enumeration(std::vector<bool>(length), structure, "Zero ones bitmap");
    }
    {
        // Single set bit
        std::vector<bool> data(length, 0);
        succinct::bit_vector_builder builder(length);
        builder.set(53, 1);
        data[53] = 1;
        succinct::elias_fano structure(&builder);
        test_equal_bits(data, structure, "Single set bit");
        test_rank_select1(data, structure, "Single set bit");
        test_delta(structure, "Single set bit");
        test_select_enumeration(data, structure, "Single set bit");
        BOOST_REQUIRE_EQUAL(1U, structure.num_ones());
    }
    {
        // All ones bitmap
        std::vector<bool> data(length, 1);
        succinct::bit_vector_builder builder;
        for (size_t pos = 0; pos < length; ++pos) {
            builder.push_back(1);
        }
        succinct::elias_fano structure(&builder);
        test_equal_bits(data, structure, "All ones bitmap");
        test_rank_select1(data, structure, "All ones bitmap");
        test_delta(structure, "All ones bitmap");
        test_select_enumeration(data, structure, "All ones bitmap");
    }
}

