        UNIT_ASSERT_VALUES_EQUAL(lastLineLength, 3);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, false);

        NLastGetopt::Wrap(5, "a b c\n\nd e f h", "", &lastLineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lastLineLength, 1);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, true);

        NLastGetopt::Wrap(5, "a b c\n\n", "", &lastLineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lastLineLength, 0);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, true);

        NLastGetopt::Wrap(5, "\n \na b c", "", &lastLineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lastLineLength, 5);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, true);

        NLastGetopt::Wrap(5, "\nx\na b c", "", &lastLineLength, &containsParagraphs);
        UNIT_ASSERT_VALUES_EQUAL(lastLineLength, 5);
        UNIT_ASSERT_VALUES_EQUAL(containsParagraphs, false);
    }
}

