using namespace llvm;

#define DEBUG_TYPE "ssaupdaterbulk"

/// Helper function to determine the basic block that requires a value for a given use.
/// For PHI nodes, returns the corresponding predecessor block; otherwise, returns the parent block of the instruction.
static BasicBlock *getBlockForUse(Use *U) {
  auto *Inst = cast<Instruction>(U->getUser());
  if (auto *PHI = dyn_cast<PHINode>(Inst))
    return PHI->getIncomingBlock(*U);
  else
    return Inst->getParent();
}

/// Register a new variable for rewriting. Must be called before AddAvailableValue or AddUse.
/// Returns the index assigned to this variable.
unsigned SSAUpdaterBulk::RegisterVariable(StringRef VarName, Type *T) {
  unsigned Idx = Rewrites.size();
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << Idx << ": initialized with Ty = "
                    << *T << ", Name = " << VarName << "\n");
  RewriteInfo Info(VarName, T);
  Rewrites.push_back(Info);
  return Idx;
}

/// Mark a specific value as available in a given block for a particular variable.
void SSAUpdaterBulk::SetAvailableValue(unsigned VarIdx, BasicBlock *BB, Value *Val) {
  assert(VarIdx < Rewrites.size() && "Invalid variable index!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarIdx
                    << ": added new available value " << *Val << " in "
                    << BB->getName() << "\n");
  Rewrites[VarIdx].Defines[BB] = Val;
}

/// Record a use site that should be updated during rewriting.
void SSAUpdaterBulk::RecordUse(unsigned VarIdx, Use *U) {
  assert(VarIdx < Rewrites.size() && "Invalid variable index!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarIdx << ": added a use " << *U->get()
                    << " in " << getBlockForUse(U)->getName() << "\n");
  Rewrites[VarIdx].Uses.push_back(U);
}

// Compute the effective value at a specific block BB for a given rewrite info.
// If no definition exists yet, recursively climb up the dominator tree.
Value *SSAUpdaterBulk::getValueAt(BasicBlock *BB, RewriteInfo &RI, DominatorTree *DT) {
  if (!RI.Defines.count(BB)) {
    if (DT->isReachableFromEntry(BB) && PredCache.get(BB).size()) {
      BasicBlock *IDom = DT->getNode(BB)->getIDom()->getBlock();
      Value *V = getValueAt(IDom, RI, DT);
      RI.Defines[BB] = V;
    } else {
      RI.Defines[BB] = UndefValue::get(RI.Ty);
    }
  }
  return RI.Defines[BB];
}

/// Given sets of UsingBlocks and DefBlocks, compute the set of LiveInBlocks.
/// This identifies all blocks where the value is live-in — i.e., blocks on paths from uses to definitions.
static void
DetermineLiveInBlocks(const SmallPtrSetImpl<BasicBlock *> &UsingBlocks,
                      const SmallPtrSetImpl<BasicBlock *> &DefBlocks,
                      SmallPtrSetImpl<BasicBlock *> &LiveInBlocks,
                      PredIteratorCache &PredCache) {
  // Start with all blocks containing uses.
  SmallVector<BasicBlock *, 64> Worklist(UsingBlocks.begin(), UsingBlocks.end());

  // Propagate liveness backwards through predecessors until fixed point.
  while (!Worklist.empty()) {
    BasicBlock *BB = Worklist.pop_back_val();
    if (!LiveInBlocks.insert(BB).second)
      continue;

    // For each predecessor, check if it defines the value or needs to be explored further.
    for (BasicBlock *Pred : PredCache.get(BB)) {
      if (DefBlocks.count(Pred))
        continue;
      Worklist.push_back(Pred);
    }
  }
}

/// Perform full SSA rewriting: insert PHIs at IDF blocks, fill in their operands, and update all recorded uses.
void SSAUpdaterBulk::RewriteAllUses(DominatorTree *DT,
                                    SmallVectorImpl<PHINode *> *InsertedPHIs) {
  for (auto &RI : Rewrites) {
    // Determine where PHIs need to be inserted by computing IDF over live-in region.
    ForwardIDFCalculator IDF(*DT);
    LLVM_DEBUG(dbgs() << "SSAUpdater: rewriting " << RI.Uses.size()
                      << " use(s)\n");

    // Collect defining and using blocks.
    SmallPtrSet<BasicBlock *, 2> DefBlocks;
    for (auto &Def : RI.Defines)
      DefBlocks.insert(Def.first);

    IDF.setDefiningBlocks(DefBlocks);

    SmallPtrSet<BasicBlock *, 2> UsingBlocks;
    for (Use *U : RI.Uses)
      UsingBlocks.insert(getBlockForUse(U));

    // Compute live-in blocks and IDF.
    SmallVector<BasicBlock *, 32> IDFBlocks;
    SmallPtrSet<BasicBlock *, 32> LiveInBlocks;
    DetermineLiveInBlocks(UsingBlocks, DefBlocks, LiveInBlocks, PredCache);
    IDF.resetLiveInBlocks();
    IDF.setLiveInBlocks(LiveInBlocks);
    IDF.calculate(IDFBlocks);

    // Insert PHI nodes at IDF blocks.
    SmallVector<PHINode *, 4> NewPHIs;
    for (auto *BB : IDFBlocks) {
      IRBuilder<> Builder(BB, BB->begin());
      PHINode *PN = Builder.CreatePHI(RI.Ty, 0, RI.Name);
      RI.Defines[BB] = PN;
      NewPHIs.push_back(PN);
      if (InsertedPHIs)
        InsertedPHIs->push_back(PN);
    }

    // Populate PHI node operands.
    for (auto *PN : NewPHIs) {
      BasicBlock *Parent = PN->getParent();
      for (BasicBlock *Pred : PredCache.get(Parent)) {
        PN->addIncoming(getValueAt(Pred, RI, DT), Pred);
      }
    }

    // Replace original uses with computed values.
    SmallPtrSet<Use *, 4> Handled;
    for (Use *U : RI.Uses) {
      if (!Handled.insert(U).second)
        continue;

      Value *NewVal = getValueAt(getBlockForUse(U), RI, DT);
      Value *OldVal = U->get();
      assert(OldVal && "Use points to null!");

      // Notify value handles about replacement.
      if (OldVal != NewVal && OldVal->hasValueHandle())
        ValueHandleBase::ValueIsRAUWd(OldVal, NewVal);

      LLVM_DEBUG(dbgs() << "SSAUpdater: replacing " << *OldVal << " with " << *NewVal
                        << "\n");
      U->set(NewVal);
    }
  }
}

