#include <vector>

class Solution {
public:
    // Generate Pascal's triangle with specified number of rows
    std::vector<std::vector<int>> generate(int rowsCount) {
        std::vector<std::vector<int>> triangle;
        triangle.push_back({1});

        for(int row = 1; row < rowsCount; row++) {
            std::vector<int> currentRow;
            currentRow.push_back(1);

            // Build the middle elements by summing adjacent elements from previous row
            for(int j = 1; j < triangle.back().size(); j++) {
                currentRow.push_back(triangle.back()[j] + triangle.back()[j - 1]);
            }

            currentRow.push_back(1);
            triangle.push_back(currentRow);
        }

        return triangle;
    }
};

