#include <vector>
#include <unordered_set>
#include <climits>
#include <string>

class Solution {
public:
    // Count distinct palindromic subsequences of length 3 in the given string
    int countPalindromicSubsequence(std::string str) {
        // Track first and last positions for each lowercase letter
        std::vector<int> firstOccurrence(26, INT_MAX);
        std::vector<int> lastOccurrence(26, INT_MIN);

        // Fill the occurrence arrays by scanning the string
        for (int idx = 0; idx < str.length(); idx++) {
            int charPos = str[idx] - 'a';
            firstOccurrence[charPos] = std::min(firstOccurrence[charPos], idx);
            lastOccurrence[charPos] = std::max(lastOccurrence[charPos], idx);
        }

        int result = 0;

        // For each character, find unique middle characters between first and last occurrence
        for (int letter = 0; letter < 26; letter++) {
            // Skip characters that don't appear in the string
            if (firstOccurrence[letter] == INT_MAX || lastOccurrence[letter] == INT_MIN) {
                continue;
            }

            // Collect unique characters between the first and last occurrence
            std::unordered_set<char> middleChars;
            for (int pos = firstOccurrence[letter] + 1; pos < lastOccurrence[letter]; pos++) {
                middleChars.insert(str[pos]);
            }

            // Each unique middle character forms a unique palindrome
            result += middleChars.size();
        }

        return result;
    }
};

