#if AD_TRACER
	MemoryTracer::MemoryTracer()
	{
		REX::W32::InitializeCriticalSection(&criticalSection);
	}

	MemoryTracer::~MemoryTracer()
	{
		REX::W32::DeleteCriticalSection(&criticalSection);
	}

	void MemoryTracer::Add(const void* a_address, size_t a_length, const void* a_caller) noexcept
	{
		REX::W32::EnterCriticalSection(&criticalSection);
		data.insert({ (uintptr_t)a_address, { a_length, (const void*)((uintptr_t)a_caller - REL::Module::GetSingleton()->base()) } });
		REX::W32::LeaveCriticalSection(&criticalSection);
	}

	void MemoryTracer::Remove(const void* a_address) noexcept
	{
		REX::W32::EnterCriticalSection(&criticalSection);
		data.unsafe_erase((uintptr_t)a_address);
		REX::W32::LeaveCriticalSection(&criticalSection);
	}

	void MemoryTracer::Dump() noexcept
	{
		REX::W32::EnterCriticalSection(&criticalSection);
		for (auto& entry : data)
			REX::INFO("[DBG] addr {:016X} size {} caller {:016X}"sv, static_cast<uintptr_t>(entry.first),
				static_cast<size_t>(entry.second.size), static_cast<uintptr_t>((uintptr_t)entry.second.addrCall));
		REX::W32::LeaveCriticalSection(&criticalSection);
	}
#endif
}

