TEST_CASE("file::lock") {
    // Setup a test file for locking tests
    auto filePath = testPath() / "lock_test.txt";
    *file::put(filePath, "abc"_tv);

    // Test 1: Read-locked file should block write/update but allow stat/read
    _using(file::FileStream reader(filePath, file::Mode::READ)) {
        REQUIRE_NOTHROW(file::FileStream(filePath, file::Mode::STAT));
        REQUIRE_NOTHROW(file::FileStream(filePath, file::Mode::READ));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::WRITE));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::UPDATE));
    }

    // Test 2: Write-locked file should block all except stat
    _using(file::FileStream writer(filePath, file::Mode::WRITE)) {
        REQUIRE_NOTHROW(file::FileStream(filePath, file::Mode::STAT));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::READ));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::WRITE));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::UPDATE));
    }

    // Test 3: Update-locked file behaves like write-locked
    _using(file::FileStream updater(filePath, file::Mode::UPDATE)) {
        REQUIRE_NOTHROW(file::FileStream(filePath, file::Mode::STAT));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::READ));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::WRITE));
        REQUIRE_THROWS(file::FileStream(filePath, file::Mode::UPDATE));
    }
}

#include "comms/torchcomms/ncclx/TorchWorkNCCLX.hpp"

namespace torch::comms {

TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollectLocked() {
  TorchWorkNCCLX::WorkStatus prev_status =
      TorchWorkNCCLX::WorkStatus::COMPLETED;

  // Iterate over all stream queues and clean up completed work items
  auto iter = stream_work_queues_.begin();
  while (iter != stream_work_queues_.end()) {
    auto& queue_ref = iter->second;
    while (!queue_ref.empty()) {
      // Examine the earliest pending work item
      auto current_work = queue_ref.front();
      // Query its completion status
      TorchWorkNCCLX::WorkStatus curr_status = current_work->checkStatus();
      prev_status = curr_status;

      if (curr_status == TorchWorkNCCLX::WorkStatus::COMPLETED) {
        // Discard finished work
        queue_ref.pop();
      } else if (
          curr_status == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
          curr_status == TorchWorkNCCLX::WorkStatus::ERROR) {
        // Propagate terminal error state immediately
        return curr_status;
      } else {
        // Work still pending — halt processing for this stream
        break;
      }
    }

    // Remove empty stream queues to avoid unnecessary storage
    if (queue_ref.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return prev_status;
}

// Thread-safety: This function may be invoked by the timeout monitor thread
// concurrently with enqueueWork(). The work_queues_mutex_ provides mutual
// exclusion on access to stream_work_queues_.
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  return garbageCollectLocked();
}

TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::finalize() {
  // Even though the timeout thread may already be joined, we retain locking
  // as a safety measure—defensive programming in case future refactoring
  // alters thread lifecycle ordering. Lock overhead is negligible when idle.
  std::lock_guard<std::mutex> guard(work_queues_mutex_);

  // Default to COMPLETED if no work remains
  TorchWorkNCCLX::WorkStatus result = TorchWorkNCCLX::WorkStatus::COMPLETED;

  while (!stream_work_queues_.empty()) {
    result = garbageCollectLocked();
    if (result == TorchWorkNCCLX::WorkStatus::ERROR ||
        result == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
        result == TorchWorkNCCLX::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure no lingering references remain after finalization
  //
  // NOTE: finalize must release all work object references before returning,
  // otherwise memory leaks or dangling pointers could occur.
  stream_work_queues_.clear();
  return result;
}

void TorchWorkNCCLXQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCLX> task,
    cudaStream_t stream_id) {
  // Append new work to the appropriate per-stream queue
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  stream_work_queues_[stream_id].push(std::move(task));
}

