namespace examples {
static bool parse_txt_entry(rav::dnssd::TxtRecord& txt_record, const std::string& input_value) {
    if (input_value.empty())
        return false;

    const size_t delimiter_pos = input_value.find('=');
    if (delimiter_pos != std::string::npos) {
        txt_record[input_value.substr(0, delimiter_pos)] = input_value.substr(delimiter_pos + 1);
    } else {
        txt_record[input_value] = "";
    }
    return true;
}
}  // namespace examples

int main(int const argc, char* argv[]) {
    rav::set_log_level_from_env();
    rav::do_system_checks();

    std::vector<std::string> arguments;
    for (int idx = 1; idx < argc; ++idx) {
        arguments.emplace_back(argv[idx]);
    }

    // Verify minimum required arguments: service type and port
    if (arguments.size() < 2) {
        std::cout << "Usage error: at least service type and port number are required "
                     "(e.g., _http._tcp 8080 key1=value1 key2=value2)"
                  << std::endl;
        return -1;
    }

    // Extract and validate port number
    int service_port = 0;
    try {
        service_port = std::stoi(arguments[1]);
    } catch (const std::exception& ex) {
        std::cout << "Port number invalid: " << ex.what() << std::endl;
        return -1;
    }

    // Build TXT record from remaining arguments
    rav::dnssd::TxtRecord txt_data;
    for (auto iter = arguments.begin() + 2; iter != arguments.end(); ++iter) {
        examples::parse_txt_entry(txt_data, *iter);
    }

    boost::asio::io_context main_context;
    auto advertiser_ptr = rav::dnssd::Advertiser::create(main_context);
    if (!advertiser_ptr) {
        RAV_LOG_ERROR("No DNS-SD advertiser implementation found for this platform");
        return -1;
    }

    advertiser_ptr->on_error = [](const std::string& msg) {
        RAV_LOG_ERROR("DNS-SD error occurred: {}", msg);
    };

    advertiser_ptr->on_name_conflict = [](const char* reg_type, const char* name) {
        RAV_LOG_CRITICAL("Name conflict detected: {} / {}", reg_type, name);
    };

    const auto registration_id =
        advertiser_ptr->register_service(arguments[0], "Demo service", nullptr, static_cast<uint16_t>(service_port), txt_data, true, true);

    std::thread worker_thread([&main_context] {
        main_context.run();
    });

    RAV_LOG_INFO("Enter key=value to modify TXT record, 'q' to quit, 'r' to re-register...");
    std::string user_input;
    while (true) {
        std::getline(std::cin, user_input);
        if (user_input == "q" || user_input == "Q") {
            break;
        }
        if (user_input == "r" || user_input == "R") {
            advertiser_ptr->unregister_service(registration_id);
            continue;
        }

        try {
            if (examples::parse_txt_entry(txt_data, user_input)) {
                boost::asio::post(main_context, [=, &advertiser_ptr] {
                    advertiser_ptr->update_txt_record(registration_id, txt_data);
                    RAV_LOG_INFO("TXT record successfully updated");
                });
            }
        } catch (const std::exception& err) {
            RAV_LOG_ERROR("TXT update failed: {}", err.what());
        }
    }

    main_context.stop();
    worker_thread.join();
    std::cout << "Terminated" << std::endl;
    return 0;
}

