#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    long long minimumRemoval(std::vector<int>& beans) {
        // Sort the beans array to process efficiently
        std::sort(beans.begin(), beans.end());

        // Calculate total sum of all beans
        long long sumAll = 0;
        for (int beanCount : beans) {
            sumAll += beanCount;
        }

        long long minRemovals = LLONG_MAX;
        int size = beans.size();

        // For each possible target value (beans[i] after sorting)
        for (int idx = 0; idx < size; idx++) {
            // Number of bags from current position to end
            long long remainingBags = size - idx;
            // Target beans per bag is beans[idx]
            long long beansToKeep = 1LL * beans[idx] * remainingBags;
            // Beans to remove = total - beans we keep
            long long removalsNeeded = sumAll - beansToKeep;
            minRemovals = std::min(minRemovals, removalsNeeded);
        }

        return minRemovals;
    }
};

