#include "ReduceFunctions.h"
#include "Delta.h"
#include "Utils.h"
#include "llvm/ADT/STLExtras.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
#include <iterator>
using namespace llvm;

/// Removes all the Defined Functions that aren't referenced in any chunk.
static void extractFunctionsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect functions to be removed: those not in any chunk and without aliases/block addresses
  SmallPtrSet<Constant *, 8> FunctionsToErase;
  for (Function &Func : Program.functions()) {
    // Skip intrinsics unless they're unused or have no useful body for reduction
    if ((!Func.isIntrinsic() || Func.use_empty()) && 
        !hasAliasOrBlockAddressUse(Func) &&
        !O.shouldKeep()) {
      FunctionsToErase.insert(&Func);
    }
  }

  // Remove from used lists first
  removeFromUsedLists(Program, [&FunctionsToErase](Constant *C) {
    return FunctionsToErase.count(C);
  });

  // Batch drop references to minimize external uses
  for (Constant *F : FunctionsToErase)
    F->dropAllReferences();

  // Finally, replace remaining uses and delete the functions
  for (Constant *F : FunctionsToErase) {
    // Replace all *still* remaining uses with default value
    F->replaceAllUsesWith(getDefaultValue(F->getType()));
    // Erase function from module
    cast<Function>(F)->eraseFromParent();
  }
}

void llvm::reduceFunctionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractFunctionsFromModule, "Filtering Functions");
}

#include "ReduceGlobalVars.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"

using namespace llvm;

static bool mustAlwaysRetain(const GlobalVariable &GV) {
  return GV.getName() == "llvm.used" || GV.getName() == "llvm.compiler.used";
}

/// Eliminates all GVs that are not part of the specified chunks.
static void pruneGVsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect GVs that belong to the target chunks
  std::vector<Constant *> PreservedGVs;
  for (auto &GV : Program.globals()) {
    if (mustAlwaysRetain(GV) || O.shouldKeep())
      PreservedGVs.push_back(&GV);
  }

  // Build a set from the collected list to avoid repeated rebalancing
  DenseSet<Constant *> KeepList(PreservedGVs.begin(), PreservedGVs.end());

  // Identify GVs to remove
  DenseSet<Constant *> RemoveList;
  for (auto &GV : Program.globals()) {
    if (!KeepList.count(&GV))
      RemoveList.insert(&GV);
  }

  // Clean up references in used lists
  removeFromUsedLists(Program,
                      [&RemoveList](Constant *C) { return RemoveList.count(C); });

  // Replace and erase removed globals
  for (auto *GV : RemoveList) {
    GV->replaceAllUsesWith(getDefaultValue(GV->getType()));
    cast<GlobalVariable>(GV)->eraseFromParent();
  }
}

void llvm::reduceGlobalsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, pruneGVsFromModule, "Eliminating GlobalVariables");
}

