#include <map>
#include <string>
using namespace std;

int main() {
    multimap<string, int> dataMap; // multimap of integers to strings (device names)

    // Insert key-value pairs using insert()
    dataMap.insert(make_pair("laptop", 800));
    dataMap.insert(make_pair("phone", 600));
    dataMap.insert(make_pair("tablet", 500));
    dataMap.insert(make_pair("tablet", 450));
    dataMap.insert(make_pair("tablet", 400));

    // Insert key-value pairs using emplace()
    dataMap.emplace("charger", 300);
    dataMap.emplace("charger", 250);

    // Print all elements in the multimap
    for(auto item : dataMap) {
        cout << item.first << " " << item.second << endl;
    }
    cout << endl;

    // Display container properties
    cout << dataMap.size() << endl;       // number of elements
    cout << dataMap.max_size() << endl;   // maximum possible size
    cout << dataMap.empty() << endl;      // check if empty (0 = false)
    cout << dataMap.count("tablet") << endl; // count occurrences of "tablet"

    // Erase one occurrence of "laptop" using iterator
    auto it = dataMap.find("laptop");
    if (it != dataMap.end()) {
        dataMap.erase(it);
    }

    // Print after first erase
    for(auto item : dataMap) {
        cout << item.first << " " << item.second << endl;
    }
    cout << endl;

    // Erase all occurrences of "laptop" (should be zero now)
    dataMap.erase("laptop");

    // Final print
    for(auto item : dataMap) {
        cout << item.first << " " << item.second << endl;
    }
    cout << endl;

    return 0;
}

#include <iostream>

int main() {
    // Construct a grid layout designed to hinder synchronization of agents
    // Using a snake-like (boustrophedon) path to maximize expected merging time
    // For a 20x20 grid, this creates a long winding corridor requiring ~O(L^2) steps

    std::cout << "20 20" << std::endl;

    for (int row = 0; row < 20; ++row) {
        if (row % 2 == 0) {
            // Even rows: full horizontal corridors filled with passable cells
            std::cout << "11111111111111111111" << std::endl;
        } else {
            // Odd rows: create turning points for the snake pattern
            // Alternate connection direction to maintain continuous path
            if (row % 4 == 1) {
                // Right-side connector for upward-moving segment
                std::cout << "00000000000000000001" << std::endl;
            } else {
                // Left-side connector for downward-moving segment
                std::cout << "10000000000000000000" << std::endl;
            }
        }
    }

    return 0;
}

