XmlPlaneWriter::XmlPlaneWriter(QFile &outputFile) : XflXmlWriter(outputFile)
{
}

void XmlPlaneWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
}

void XmlPlaneWriter::writeXMLPlane(PlaneXfl const &aircraft, bool bIncludeFoils)
{
    writeStartDocument();
    {
        writeHeader();
        writeStartElement("xflplane");
        writeAttribute("version", "1.0");
        {
            writeComment("For convenience, all field names are case-insensitive, as an exception to the standard xml specification");
            writeComment("Where applicable, default values will be used for all undefined fields");
            writeUnits();
            writeStartElement("Plane");
            {
                writeTextElement("Name", aircraft.name());
                if(aircraft.description().length())
                {
                    writeTextElement("Description", aircraft.description());
                }
                writeTheStyle(aircraft.theStyle());
                if(aircraft.pointMassCount())
                {
                    writeStartElement("Inertia");
                    {
                        for(int pmIndex=0; pmIndex<aircraft.pointMassCount(); pmIndex++)
                        {
                            writePointMass(aircraft.pointMassAt(pmIndex));
                        }
                    }
                    writeEndElement();
                }
                for(int fuseIdx=0; fuseIdx<aircraft.nFuse(); fuseIdx++)
                {
                    if(aircraft.fuseAt(fuseIdx) && aircraft.fuseAt(fuseIdx)->isXflType())
                    {
                        FuseXfl const*pFuselage = dynamic_cast<FuseXfl const*>(aircraft.fuseAt(fuseIdx));
                        writeXflFuse(*pFuselage, aircraft.fusePos(0));
                    }
                }
                for(int wingIdx=0; wingIdx<aircraft.nWings(); wingIdx++)
                {
                    if(aircraft.wingAt(wingIdx))
                    {
                        writeWing(*aircraft.wingAt(wingIdx), aircraft.wingLE(wingIdx), aircraft.rxAngle(wingIdx), aircraft.ryAngle(wingIdx), bIncludeFoils);
                    }
                }
            }
        }
        writeEndElement();
    }
    writeEndDocument();
}

