#include <iostream>
#include <vector>
using namespace std;

// LeetCode 733: Flood Fill - Modified implementation
// This function modifies the color of a region in a 2D pixel grid using DFS
class Solution {
public:
    void fillRegion(vector<vector<int>>& grid, int row, int col, int targetColor, int sourceColor) {
        // Boundary check and condition verification
        if (row < 0 || row >= grid.size() || col < 0 || col >= grid[0].size() || 
            grid[row][col] != sourceColor || grid[row][col] == targetColor) {
            return;
        }

        // Update current pixel with new color
        grid[row][col] = targetColor;

        // Recursively process adjacent pixels (down, up, right, left)
        fillRegion(grid, row + 1, col, targetColor, sourceColor);
        fillRegion(grid, row - 1, col, targetColor, sourceColor);
        fillRegion(grid, row, col + 1, targetColor, sourceColor);
        fillRegion(grid, row, col - 1, targetColor, sourceColor);
    }

    vector<vector<int>> floodFill(vector<vector<int>>& image, int startRow, int startCol, int newColor) {
        // Handle case where new color is same as original color
        if (image[startRow][startCol] == newColor) {
            return image;
        }

        fillRegion(image, startRow, startCol, newColor, image[startRow][startCol]);
        return image;
    }
};

