#include "config.h"
#include "unwind.h"

#ifdef __WASM_EXCEPTIONS__
#include <threads.h>

// WebAssembly-specific personality function implementation
_Unwind_Reason_Code __gxx_personality_wasm0(int version, _Unwind_Action actions,
                                            uint64_t exceptionClass,
                                            _Unwind_Exception *unwind_exception,
                                            _Unwind_Context *context);

// Context structure passed between compiler-generated code and personality function
struct _Unwind_LandingPadContext {
  // Input: provided by compiler-generated code
  uintptr_t lpad_index; // landing pad index in the current function
  uintptr_t lsda;       // Language Specific Data Area address

  // Output: filled by personality function
  uintptr_t selector;   // catch selector or filter value
};

// Thread-local storage for passing context to personality function
thread_local struct _Unwind_LandingPadContext __wasm_lpad_context;

/// Entry point called from landing pads in compiled code
/// This bridges the gap between WebAssembly VM's unwinding and the personality function
_Unwind_Reason_Code _Unwind_CallPersonality(void *exception_ptr) {
  struct _Unwind_Exception *exception_object =
      (struct _Unwind_Exception *)exception_ptr;
  _LIBUNWIND_TRACE_API("_Unwind_CallPersonality(exception_object=%p)",
                       (void *)exception_object);

  // Clear previous selector value
  __wasm_lpad_context.selector = 0;

  // Invoke personality function for cleanup phase only (no two-phase unwinding)
  return __gxx_personality_wasm0(
      1, _UA_SEARCH_PHASE, exception_object->exception_class, exception_object,
      (struct _Unwind_Context *)&__wasm_lpad_context);
}

/// Exception throwing entry point - called by __cxa_throw
_LIBUNWIND_EXPORT _Unwind_Reason_Code
_Unwind_RaiseException(_Unwind_Exception *exception_object) {
  _LIBUNWIND_TRACE_API("_Unwind_RaiseException(exception_object=%p)",
                       (void *)exception_object);

  // Use WebAssembly's native throw instruction
  __builtin_wasm_throw(0, exception_object);
}

/// Called during exception cleanup (e.g., from __cxa_end_catch)
_LIBUNWIND_EXPORT void
_Unwind_DeleteException(_Unwind_Exception *exception_object) {
  _LIBUNWIND_TRACE_API("_Unwind_DeleteException(ex_obj=%p)",
                       (void *)(exception_object));

  if (exception_object->exception_cleanup != NULL)
    (*exception_object->exception_cleanup)(_URC_FOREIGN_EXCEPTION_CAUGHT,
                                           exception_object);
}

/// Set general register value during unwinding
_LIBUNWIND_EXPORT void _Unwind_SetGR(struct _Unwind_Context *context, int index,
                                     uintptr_t value) {
  _LIBUNWIND_TRACE_API("_Unwind_SetGR(context=%p, index=%d, value=%lu)",
                       (void *)context, index, value);

  // Only index 1 is used for setting the selector field
  if (index == 1)
    ((struct _Unwind_LandingPadContext *)context)->selector = value;
}

/// Get instruction pointer from context
_LIBUNWIND_EXPORT uintptr_t _Unwind_GetIP(struct _Unwind_Context *context) {
  // Convert landing pad index to 1-based IP value expected by unwinder
  uintptr_t result =
      ((struct _Unwind_LandingPadContext *)context)->lpad_index + 2;
  _LIBUNWIND_TRACE_API("_Unwind_GetIP(context=%p) => %lu", (void *)context,
                       result);
  return result;
}

/// Not implemented for WebAssembly
_LIBUNWIND_EXPORT void _Unwind_SetIP(struct _Unwind_Context *, uintptr_t) {}

/// Get language-specific data area for current frame
_LIBUNWIND_EXPORT uintptr_t
_Unwind_GetLanguageSpecificData(struct _Unwind_Context *context) {
  uintptr_t result = ((struct _Unwind_LandingPadContext *)context)->lsda;
  _LIBUNWIND_TRACE_API("_Unwind_GetLanguageSpecificData(context=%p) => 0x%lx",
                       (void *)context, result);
  return result;
}

/// Region start not applicable to WebAssembly
_LIBUNWIND_EXPORT uintptr_t _Unwind_GetRegionStart(struct _Unwind_Context *) {
  return 0;
}

#elif defined(__EMSCRIPTEN__)
/// Fallback implementation when WebAssembly exceptions are disabled
/// Prevents linker errors in non-exception builds
_LIBUNWIND_EXPORT _Unwind_Reason_Code
_Unwind_RaiseException(_Unwind_Exception *exception_object __attribute__((unused))) {
  abort();
}
#endif // defined(__WASM_EXCEPTIONS__)

