int main() {
    // Initialize a mplot::Visual rendering context with specified dimensions and title
    mplot::Visual<mplot::gl::version_3_1_es> scene(1024, 768, "mplot::GraphVisual on Raspberry Pi");

    // Instantiate a GraphVisual object with position offset (0,0,0) and obtain unique_ptr
    auto graph = std::make_unique<mplot::GraphVisual<double, mplot::gl::version_3_1_es>>(sm::vec<float>{0,0,0});

    // Essential initialization: establish parent relationship and bind internal functions
    scene.bindmodel(graph);

    // Prepare x-axis data using vvec (vector-like container with mathematical operations)
    sm::vvec<double> abscissa;

    // Generate evenly spaced points from -0.5 to 0.8 with 14 samples
    abscissa.linspace(-0.5, 0.8, 14);

    // Configure the graph to display y = x^3
    graph->setdata(abscissa, abscissa.pow(3));

    // Finalize graph setup: compute OpenGL vertex data for rendering
    graph->finalize();

    // Transfer ownership of the graph model to the visual scene
    scene.addVisualModel(graph);

    // Enter main loop to render and keep window open until user presses 'Ctrl-q'
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' goes out of scope due to RAII
    return 0;
}

