namespace tpa {

void TransferFunction::processEntryNode(const ProgramPoint &entryPoint,
                                        PropagationResult &result) {
  assert(state != nullptr);
  enqueueTopLevelSuccessors(entryPoint, result);
  enqueueMemoryLevelSuccessors(entryPoint, *state, result);

  // Ensure the analysis revisits return targets upon function entry to avoid
  // premature convergence before new return edges are considered.
  //
  // Important: This unconditional enqueue is intentional. The SemiSparsePropagator
  // maintains a memoization cache (Memo) and only re-evaluates the exit node
  // when the store state at that point changes. Thus, although the exit node
  // gets enqueued on each entry visit, redundant work is avoided through
  // memo-table lookups, preserving correctness and termination of the fixpoint.

  auto &controlFlowGraph = entryPoint.getCFGNode()->getCFG();
  if (!controlFlowGraph.hasNoReturn()) {
    result.addTopLevelProgramPoint(
        ProgramPoint(entryPoint.getContext(), controlFlowGraph.getExitNode()));
  }
}

} // namespace tpa

