static std::atomic<bool> gKeepRunning{true};

// Function to be probed — must remain noinline for reliable uprobe detection.
// Declared extern "C" to avoid C++ name mangling and ensure stable symbol names.
// Minimal implementation to maximize invocation rate.
extern "C" __attribute__((noinline)) void probe_target() {
    static volatile int dummy = 0;
    (void)dummy;
}

// Separate caller functions, each representing a unique call site.
// Each thread executes target from its own dedicated caller.
__attribute__((noinline)) void WorkerA() {
    while (gKeepRunning.load(std::memory_order_relaxed)) {
        probe_target();
    }
}

__attribute__((noinline)) void WorkerB() {
    while (gKeepRunning.load(std::memory_order_relaxed)) {
        probe_target();
    }
}

__attribute__((noinline)) void WorkerC() {
    while (gKeepRunning.load(std::memory_order_relaxed)) {
        probe_target();
    }
}

__attribute__((noinline)) void WorkerD() {
    while (gKeepRunning.load(std::memory_order_relaxed)) {
        probe_target();
    }
}

using FuncPtr = void (*)();

static constexpr std::array<FuncPtr, 4> WorkerList = {
    WorkerA,
    WorkerB,
    WorkerC,
    WorkerD,
};

// Bind current thread to specified CPU core.
static void SetCpuAffinity(int cpuId) {
    cpu_set_t mask;
    CPU_ZERO(&mask);
    CPU_SET(cpuId, &mask);
    if (sched_setaffinity(0, sizeof(mask), &mask) != 0) {
        perror("sched_setaffinity");
        // Proceed even if pinning fails; load still gets generated.
    }
}

// Retrieve number of online CPUs.
static int CountOnlineCpus() {
    long count = sysconf(_SC_NPROCESSORS_ONLN);
    if (count <= 0) {
        throw std::runtime_error("failed to determine number of CPUs");
    }
    return static_cast<int>(count > 0 ? count : 1);
}

int main(int argc, const char* argv[]) {
    int runTimeSeconds = 30;
    int threadCount = 0;

    NLastGetopt::TOpts options;
    options.AddLongOption("duration", "Test duration in seconds")
        .RequiredArgument("N")
        .DefaultValue("30")
        .StoreResult(&runTimeSeconds);

    options.AddLongOption("threads", "Number of worker threads (defaults to CPU count)")
        .RequiredArgument("N")
        .DefaultValue("0")
        .StoreResult(&threadCount);

    NLastGetopt::TOptsParseResult(&options, argc, argv);

    const int cpuCount = CountOnlineCpus();
    const int activeThreads = (threadCount > 0) ? threadCount : cpuCount;

    std::vector<std::thread> workers;
    workers.reserve(activeThreads);

    for (int idx = 0; idx < activeThreads; ++idx) {
        int assignedCpu = idx % cpuCount;
        int workerIdx = idx % static_cast<int>(WorkerList.size());
        workers.emplace_back([assignedCpu, workerIdx]() {
            SetCpuAffinity(assignedCpu);
            WorkerList[workerIdx]();
        });
    }

    // Allow workers to run for the configured time.
    sleep(runTimeSeconds);

    gKeepRunning.store(false, std::memory_order_relaxed);

    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}

#include <iostream>

class Solution {
public:
    int solveTowerOfHanoi(int disks, int source, int destination, int auxiliary) {
        // Base case: single disk requires one move
        if (disks == 1) {
            return 1;
        }

        // Recursive case: move n-1 disks to auxiliary, 
        // move largest disk, then move n-1 disks from auxiliary to destination
        int moves = solveTowerOfHanoi(disks - 1, source, auxiliary, destination);
        moves += 1;  // Move the largest disk
        moves += solveTowerOfHanoi(disks - 1, destination, source, auxiliary);

        return moves;
    }
};

