#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string input;
    if (!(cin >> input)) return 0;

    int len = input.size();

    // Store positions of '1's with sentinels at boundaries
    vector<int> onesPos;
    onesPos.reserve(len + 2);
    onesPos.push_back(-1);

    for (int idx = 0; idx < len; ++idx) {
        if (input[idx] == '1') {
            onesPos.push_back(idx);
        }
    }
    onesPos.push_back(len);

    int countOnes = onesPos.size() - 2;
    long long totalZeros = len - countOnes;

    // Calculate gaps between consecutive '1's (including boundaries)
    vector<int> gaps;
    gaps.reserve(countOnes + 1);
    for (size_t j = 0; j < onesPos.size() - 1; ++j) {
        gaps.push_back(onesPos[j+1] - onesPos[j] - 1);
    }

    long long result = 0;

    // Try all possible counts of '1's in substring (k)
    for (int k = 1; ; ++k) {
        long long zerosNeeded = 1LL * k * k;

        // Early termination conditions
        if (zerosNeeded > totalZeros) break;
        if (zerosNeeded + k > len) break;

        // Sum of zeros strictly between the first and last '1' in current window
        long long innerZeros = 0;
        for (int x = 1; x < k; ++x) {
            innerZeros += gaps[x];
        }

        // Slide window over all possible blocks of k consecutive '1's
        for (int i = 0; i <= countOnes - k; ++i) {
            long long remainingZeros = zerosNeeded - innerZeros;

            if (remainingZeros >= 0) {
                // Determine valid range for left extension
                long long minLeft = remainingZeros - gaps[i + k];
                if (minLeft < 0) minLeft = 0;

                long long maxLeft = remainingZeros;
                if (maxLeft > gaps[i]) maxLeft = gaps[i];

                if (maxLeft >= minLeft) {
                    result += (maxLeft - minLeft + 1);
                }
            }

            // Update innerZeros for next window position
            if (i < countOnes - k) {
                innerZeros -= gaps[i + 1];
                innerZeros += gaps[i + k];
            }
        }
    }

    cout << result << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Constructive method to generate a grid with exactly x paths from top-left to bottom-right
// Grid size is fixed at 65x65, sufficient for values up to ~1e18 using binary representation
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long targetPaths;
    if (!(cin >> targetPaths)) return 0;

    const int GRID_SIZE = 65;
    vector<vector<int>> grid(GRID_SIZE, vector<int>(GRID_SIZE, 0));

    // Build base snake pattern:
    // Odd-indexed rows (1-based): fill left side from column 1 to row number
    // Even-indexed rows: fill right side from column (GRID_SIZE - row + 1) to end
    for (int row = 1; row <= GRID_SIZE; ++row) {
        if (row % 2 == 1) {
            for (int col = 1; col <= row; ++col) {
                grid[row-1][col-1] = 1;
            }
        } else {
            for (int col = 0; col < row; ++col) {
                grid[row-1][GRID_SIZE-1-col] = 1;
            }
        }
    }

    // Adjust for the target path count by setting additional cells based on binary digits
    long long remaining = targetPaths - 1;
    for (int row = 2; row <= GRID_SIZE; ++row) {
        if (row % 2 == 1) {
            // For odd rows, extend to the right if current bit is set
            if (remaining & 1LL) {
                for (int col = row + 1; col <= GRID_SIZE; ++col) {
                    grid[row-1][col-1] = 1;
                }
            }
        } else {
            // For even rows, extend to the left if current bit is set
            if (remaining & 1LL) {
                for (int col = 1; col <= GRID_SIZE - row; ++col) {
                    grid[row-1][col-1] = 1;
                }
            }
        }
        remaining >>= 1;
        if (remaining == 0) break;
    }

    cout << GRID_SIZE << "\n";
    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            cout << grid[i][j];
            if (j + 1 < GRID_SIZE) cout << " ";
            else cout << "\n";
        }
    }

    return 0;
}

