#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

int main() {
    // Optimize I/O performance
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    int median1 = size / 2;
    int median2 = size / 2 + 1;

    // Initialize list of potential candidates (1 to size)
    vector<int> possible(size);
    iota(possible.begin(), possible.end(), 1);

    // Store a known discarded pair (one below median, one above median) for padding
    vector<int> known_discarded;

    // Random number generator initialization
    mt19937 engine(chrono::steady_clock::now().time_since_epoch().count());

    // Reduce candidate set until only two remain
    while (possible.size() > 2) {
        // Randomly select two distinct indices from current candidates
        vector<int> indices(possible.size());
        iota(indices.begin(), indices.end(), 0);
        shuffle(indices.begin(), indices.end(), engine);

        int pos1 = indices[0];
        int pos2 = indices[1];

        int candidateA = possible[pos1];
        int candidateB = possible[pos2];

        vector<int> test_set;

        if (possible.size() > 4) {
            // Build query excluding the two selected candidates
            for (size_t i = 0; i < possible.size(); ++i) {
                if ((int)i == pos1 || (int)i == pos2) continue;
                test_set.push_back(possible[i]);
            }
        } else {
            // When only 4 candidates remain, pad with previously discarded pair
            for (size_t i = 0; i < possible.size(); ++i) {
                if ((int)i == pos1 || (int)i == pos2) continue;
                test_set.push_back(possible[i]);
            }
            test_set.push_back(known_discarded[0]);
            test_set.push_back(known_discarded[1]);
        }

        // Output query
        cout << "0 " << test_set.size();
        for (int val : test_set) cout << " " << val;
        cout << endl;

        // Read median response
        int resp1, resp2;
        cin >> resp1 >> resp2;

        if (resp1 == median1 && resp2 == median2) {
            // Medians unchanged: the removed pair must be one small and one large
            if (possible.size() > 4) {
                known_discarded = {candidateA, candidateB};

                // Update candidate list by removing the tested pair
                vector<int> updated;
                for (size_t i = 0; i < possible.size(); ++i) {
                    if ((int)i == pos1 || (int)i == pos2) continue;
                    updated.push_back(possible[i]);
                }
                possible = updated;
            } else {
                // Found the final medians among remaining candidates
                vector<int> result;
                for (size_t i = 0; i < possible.size(); ++i) {
                    if ((int)i == pos1 || (int)i == pos2) continue;
                    result.push_back(possible[i]);
                }
                cout << "1 " << result[0] << " " << result[1] << endl;
                return 0;
            }
        }
        // If medians changed, discard failed — try another random pair in next iteration
    }

    return 0;
}

