namespace SLOT {

LLVMFunction::LLVMFunction(bool t_useMulInsteadOfShift, context &t_context,
                           Function *t_func)
    : useMulInsteadOfShift(t_useMulInsteadOfShift), ctx(t_context), func(t_func),
      varIdx(0), auxVars(t_context) {
  // Mirror the LLVM function signature in the SMT world. Each LLVM
  // argument becomes a Z3 constant with a matching sort; we keep the
  // names identical so later lookups stay straightforward.
  ctx.set_rounding_mode(RNE);
  for (Argument *arg = func->arg_begin(); arg < func->arg_end(); ++arg) {
    if (arg->getType()->isIntegerTy()) {
      // 1-wide integer --> boolean
      if (arg->getType()->getIntegerBitWidth() == 1) {
        vars.insert(
            make_pair(arg->getName().str(),
                      ctx.bool_const(arg->getName().str().c_str())));
      } else {
        // Regular bitvector case
        vars.insert(
            make_pair(arg->getName().str(),
                      ctx.bv_const(arg->getName().str().c_str(),
                                   arg->getType()->getIntegerBitWidth())));
      }
    } else if (arg->getType()->isHalfTy()) {
      vars.insert(
          make_pair(arg->getName().str(),
                    ctx.fpa_const(arg->getName().str().c_str(), 5, 11)));
    } else if (arg->getType()->isFloatTy()) {
      vars.insert(
          make_pair(arg->getName().str(),
                    ctx.fpa_const(arg->getName().str().c_str(), 8, 24)));
    } else if (arg->getType()->isDoubleTy()) {
      vars.insert(
          make_pair(arg->getName().str(),
                    ctx.fpa_const(arg->getName().str().c_str(), 11, 53)));
    } else if (arg->getType()->isFP128Ty()) {
      vars.insert(
          make_pair(arg->getName().str(),
                    ctx.fpa_const(arg->getName().str().c_str(), 15, 113)));
    } else {
      std::string type_str;
      llvm::raw_string_ostream rso(type_str);
      arg->print(rso);
      throw UnsupportedTypeException("unsupported LLVM variable type",
                                     rso.str());
    }
  }
}

// For fp to bv bitcast, create a new variable and constrain it equal at the
// top level
expr LLVMFunction::AddBCVariable(std::unique_ptr<LLVMNode> node) {
  std::string name = "_slot_smtbc_" + std::to_string(varIdx) + "_";
  expr var = ctx.bv_const(name.c_str(), node->Width());
  vars.insert(make_pair(name, var));
  expr constraint = (var.mk_from_ieee_bv(node->SMTSort()) == node->ToSMT());
  auxVars = (varIdx == 0) ? constraint : (auxVars && constraint);
  ++varIdx;
  return var;
}

expr LLVMFunction::ToSMT() {
  // Recurse from the return value down the CFG, combining any additional
  // constraints introduced for helper variables (e.g., bitcasts) so the
  // solver sees the full set of equations.
  expr childExpr =
      LLVMNode::MakeLLVMNode(
          useMulInsteadOfShift, ctx, *this,
          ((ReturnInst *)func->getEntryBlock().getTerminator())
              ->getOperand(0))
          ->ToSMT();
  return (varIdx == 0) ? childExpr : (auxVars && childExpr);
}

