int main()
{
    // Initialize a JSON object with various data types
    const json data =
    {
        {"value", 1}, {"text", "bar"}, {"list", {3, 4}}
    };

    // Access elements using JSON pointers
    std::cout << data.at("/value"_json_pointer) << '\n';
    std::cout << data.at("/text"_json_pointer) << '\n';
    std::cout << data.at("/list"_json_pointer) << '\n';
    std::cout << data.at("/list/0"_json_pointer) << '\n';

    // Handle parse error for invalid array index
    try
    {
        json::const_reference ref = data.at("/list/two"_json_pointer);
    }
    catch (const json::parse_error& err)
    {
        std::cout << err.what() << '\n';
    }

    // Handle out-of-range error for invalid index
    try
    {
        json::const_reference ref = data.at("/list/5"_json_pointer);
    }
    catch (const json::out_of_range& err)
    {
        std::cout << err.what() << '\n';
    }

    // Handle out-of-range error for '-' index
    try
    {
        json::const_reference ref = data.at("/list/-"_json_pointer);
    }
    catch (const json::out_of_range& err)
    {
        std::cout << err.what() << '\n';
    }

    // Handle out-of-range error for missing key
    try
    {
