int main() {
    std::cout << "=== protected_functions_demo ===" << std::endl;
    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // Define Lua functions: one handler and one main function that may fail
    lua_vm.script(R"(
        function error_handler (msg)
            return "Error caught: " .. msg
        end

        function compute_value (val)
            if val < 0 then
                error("negative value encountered")
            end
            return val * 2 + 10
        end
    )");

    // Create a protected function using the handler
    sol::protected_function compute(lua_vm["compute_value"], lua_vm["error_handler"]);

    // Execute with an invalid input to trigger the error path
    sol::protected_function_result outcome = compute(-100);

    if (outcome.valid()) {
        // Execution succeeded
        int result_value = outcome;
        std::cout << "execution successful, result is " << result_value << std::endl;
    } else {
        // Execution failed
        sol::error exception = outcome;
        std::string message = exception.what();
        std::cout << "execution failed, sol::error::what() returns: "
                  << message << std::endl;
        // Expected output: "Error caught: negative value encountered"
    }

    std::cout << std::endl;
    return 0;
}

