/// Instantiate a new interpreter instance.
///
ExecutionEngine *Interpreter::create(std::unique_ptr<Module> M,
                                     std::string *ErrStr) {
  // Ensure the Module completes loading and discard its GVMaterializer.
  if (Error Err = M->materializeAll()) {
    std::string Msg;
    handleAllErrors(std::move(Err), [&](ErrorInfoBase &EIB) {
      Msg = EIB.message();
    });
    if (ErrStr)
      *ErrStr = Msg;
    // An error occurred, so return null
    return nullptr;
  }
  return new Interpreter(std::move(M));
}

//===----------------------------------------------------------------------===//
// Interpreter constructor - Setup initial state
//
Interpreter::Interpreter(std::unique_ptr<Module> M)
    : ExecutionEngine(std::move(M)) {
  memset(&ExitValue.Untyped, 0, sizeof(ExitValue.Untyped));
  // Initialize runtime components
  initializeExecutionEngine();
  initializeExternalFunctions();
  emitGlobals();
  IL = new IntrinsicLowering(getDataLayout());
}

Interpreter::~Interpreter() {
  delete IL;
}

void Interpreter::executeAtExitRoutines () {
  while (!AtExitHandlers.empty()) {
    callFunction(AtExitHandlers.back(), std::nullopt);
    AtExitHandlers.pop_back();
    run();
  }
}

/// run - Begin execution starting from the given function with provided arguments.
///
GenericValue Interpreter::runFunction(Function *F,
                                      ArrayRef<GenericValue> ArgValues) {
  assert (F && "Function pointer F was null when entering run()");
  // Avoid passing more arguments than the function expects. 
  // C programmers often declare main() with fewer parameters than it receives,
  // causing failures in the interpreter when too many are passed.
  // This logic does not account for type mismatches in declarations.
  const size_t NumParams = F->getFunctionType()->getNumParams();
  ArrayRef<GenericValue> EffectiveArgs =
      ArgValues.slice(0, std::min(ArgValues.size(), NumParams));
  // Prepare for the function invocation.
  callFunction(F, EffectiveArgs);
  // Begin executing the function body.
  run();
  return ExitValue;
}

