// Function to perform a query and get the response
int performQuery(int node, int flag, const std::vector<int>& list) {
    std::cout << "? " << node << " " << flag << " " << list.size();
    for (int element : list) {
        std::cout << " " << element;
    }
    std::cout << std::endl;

    int result;
    std::cin >> result;
    if (result == -1) {
        // Terminate on error from interactor
        exit(0);
    }
    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;
    std::vector<int> mapping(size + 1);

    // Phase 1: Determine the mapping using binary search
    std::vector<int> possible_values(size);
    std::iota(possible_values.begin(), possible_values.end(), 1);

    for (int idx = 1; idx <= size; ++idx) {
        std::vector<int> candidates = possible_values;

        while (candidates.size() > 1) {
            int split_point = candidates.size() / 2;
            std::vector<int> subset(candidates.begin(), candidates.begin() + split_point);

            int answer = performQuery(idx, 1, subset);

            if (answer == 1) {
                // Target is in the first half
                candidates.erase(candidates.begin() + split_point, candidates.end());
            } else {
                // Target is in the second half
                candidates.erase(candidates.begin(), candidates.begin() + split_point);
            }
        }
        mapping[idx] = candidates[0];
    }

    // Phase 2: Build adjacency list and find connected component containing room 1
    std::vector<std::vector<int>> graph(size + 1);
    for (int i = 1; i <= size; ++i) {
        graph[i].push_back(mapping[i]);
        graph[mapping[i]].push_back(i);
    }

    std::vector<int> connected_nodes;
    std::vector<bool> seen(size + 1, false);
    std::queue<int> frontier;

    frontier.push(1);
    seen[1] = true;

    while (!frontier.empty()) {
        int current = frontier.front();
        frontier.pop();
        connected_nodes.push_back(current);

        for (int neighbor : graph[current]) {
            if (!seen[neighbor]) {
                seen[neighbor] = true;
                frontier.push(neighbor);
            }
        }
    }

    std::sort(connected_nodes.begin(), connected_nodes.end());

    // Output the result
    std::cout << "! " << connected_nodes.size();
    for (int room : connected_nodes) {
        std::cout << " " << room;
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

// Upper bound for XOR values when n <= 10^7 (since 2^24 > 10^7)
const int MAX_POSSIBLE_XOR = 1 << 24;

// Boolean array to track which XOR results have been seen; zero-initialized by default
bool xor_seen[MAX_POSSIBLE_XOR];

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int limit;
    std::cin >> limit;

    std::vector<int> selected_numbers;
    // Pre-allocate memory to avoid repeated reallocations
    selected_numbers.reserve(3000);

    // Greedy construction of the set: try adding each number from 1 to 'limit'
    for (int candidate = 1; candidate <= limit; ++candidate) {
        bool is_valid = true;

        // Verify that adding 'candidate' doesn't produce a duplicate XOR value
        for (int existing : selected_numbers) {
            if (xor_seen[candidate ^ existing]) {
                is_valid = false;
                break;
            }
        }

        if (is_valid) {
            // Mark all new XOR combinations as seen
            for (int existing : selected_numbers) {
                xor_seen[candidate ^ existing] = true;
            }
            selected_numbers.push_back(candidate);
        }
    }

    // Print the size of the resulting set
    std::cout << selected_numbers.size() << "\n";

    // Print the elements of the set, space-separated
    for (size_t idx = 0; idx < selected_numbers.size(); ++idx) {
        std::cout << selected_numbers[idx];
        if (idx != selected_numbers.size() - 1) {
            std::cout << " ";
        }
    }
    std::cout << "\n";

    return 0;
}

