#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int numSpecial(std::vector<std::vector<int>>& grid) {
        int count = 0;
        for (const auto& line : grid) {
            if (std::accumulate(line.begin(), line.end(), 0) == 1) {
                int pos = std::distance(line.begin(), std::find(line.begin(), line.end(), 1));
                count += (getColValue(grid, pos) == 1);
            }
        }
        return count;        
    }
private:
    int getColValue(const std::vector<std::vector<int>>& matrix, int index) {
        int result = 0;
        for (const auto& row : matrix) {
            result += row[index];
        }
        return result;
    }
};

