SeqArrangeJob::SeqArrangeJob(const Model &model, const DynamicPrintConfig &config, bool only_current_bed)
{
    m_arranger.reset(new SeqArrange(model, config, only_current_bed));
}

void SeqArrangeJob::process(Ctl &ctl)
{
    class JobProcessingException : public std::exception {};

    try
    {
        m_arranger->process_seq_arrange(
            [&](int step)
            {
                ctl.update_status(step, _u8L("Arranging for sequential print"));
                if (ctl.is_cancelled())
                    throw JobProcessingException();
            });
    }
    catch (const JobProcessingException &)
    {
        ctl.update_status(100, ""); // Clear progress indicator.
    }
    catch (const std::exception &)
    {
        ctl.update_status(100, ""); // Clear progress indicator.
        throw;
    }
}

void SeqArrangeJob::finalize(bool was_cancelled, std::exception_ptr &exc_ptr)
{
    // If the operation was cancelled, the cancellation exception was already handled in 'process'.
    // Any other exception will propagate through this point.
    bool has_error = false;
    if (exc_ptr)
    {
        try
        {
            std::rethrow_exception(exc_ptr);
        }
        catch (const ExceptionCannotApplySeqArrange &)
        {
            ErrorDialog dlg(wxGetApp().plater(),
                            _L("The result of the single-bed arrange would scatter "
                               "instances of a single object between several beds, possibly affecting order of printing "
                               "of the non-selected beds. Consider using global arrange across all beds."),
                            false);
            dlg.ShowModal();
            has_error = true;
            exc_ptr = nullptr; // Exception is now handled.
        }
        catch (const Sequential::ObjectTooLargeException &)
        {
            ErrorDialog dlg(wxGetApp().plater(), _L("One of the objects exceeds the bed dimensions."), false);
            dlg.ShowModal();
            has_error = true;
            exc_ptr = nullptr; // Exception is now handled.
        }
        catch (const std::runtime_error &err)
        {
            ErrorDialog dlg(wxGetApp().plater(), GUI::format_wxstr(_L("Internal error: %1%"), err.what()), false);
            dlg.ShowModal();
            has_error = true;
            exc_ptr = nullptr; // Exception is now handled.
        }
    }

    if (!was_cancelled && !has_error)
    {
        Plater::TakeSnapshot snapshot(wxGetApp().plater(), _u8L("Arrange for sequential print"));
        m_arranger->apply_seq_arrange(wxGetApp().model());
        wxGetApp().plater()->canvas3D()->refresh_scene(true, true);
        wxGetApp().obj_list()->refresh_after_undo_redo();
    }

    m_arranger.reset();
}
