#include "sample-string.h"
#include <gtest/gtest.h>

// Verifies behavior of the default constructor
TEST(MyString, DefaultConstructor) {
  const MyString str;
  // Confirms that str.c_string() returns nullptr.
  //
  // <TechnicalDetails>
  //
  // Using NULL instead of
  //
  //   static_cast<const char *>(NULL)
  //
  // would cause a warning in gcc 3.4. This occurs because EXPECT_EQ must
  // determine argument types for printing upon failure. Since NULL is
  // typically #defined as 0, the compiler treats it as an int, but gcc
  // expects NULL to serve as a pointer, triggering a complaint.
  //
  // The underlying issue stems from C++'s absence of a clear distinction
  // between integer zero and null pointer constants—unfortunately, we
  // must accept this limitation.
  //
  // </TechnicalDetails>
  EXPECT_STREQ(nullptr, str.c_string());
  EXPECT_EQ(0u, str.Length());
}

const char kSampleText[] = "Hello, world!";
// Tests the constructor that takes a C-style string
TEST(MyString, ConstructorFromCString) {
  const MyString text(kSampleText);
  EXPECT_EQ(0, strcmp(text.c_string(), kSampleText));
  EXPECT_EQ(sizeof(kSampleText)/sizeof(kSampleText[0]) - 1,
            text.Length());
}

// Tests the copy constructor
TEST(MyString, CopyConstructor) {
  const MyString original(kSampleText);
  const MyString copy = original;
  EXPECT_EQ(0, strcmp(copy.c_string(), kSampleText));
}

// Tests the Set method functionality
TEST(MyString, Set) {
  MyString instance;
  instance.Set(kSampleText);
  EXPECT_EQ(0, strcmp(instance.c_string(), kSampleText));

  // Verify Set works when input pointer matches current internal pointer
  instance.Set(instance.c_string());
  EXPECT_EQ(0, strcmp(instance.c_string(), kSampleText));

  // Test setting MyString to nullptr
  instance.Set(nullptr);
  EXPECT_STREQ(nullptr, instance.c_string());
}

