#include <unistd.h>
#endif

using namespace lemon;

// Flag to indicate shutdown request (thread-safe)
static std::atomic<bool> g_exit_requested(false);
static Server* g_active_server = nullptr;

// Handles termination signals like Ctrl+C, SIGTERM, and SIGHUP
void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
#ifndef _WIN32
        const char* msg = "Shutdown signal received, exiting...\n";
        (void)write(STDOUT_FILENO, msg, 38);
#endif
        // Avoid calling server methods in signal handler to prevent deadlocks
        g_exit_requested = true;
        // Use async-signal-safe _exit() for immediate termination
        _exit(0);
#ifdef SIGHUP
    } else if (sig == SIGHUP) {
        // Ignore SIGHUP to allow daemon-like behavior
        return;
#endif
    }
}

int main(int argc, char** argv) {
    // Ensure only one instance runs at a time
    if (SingleInstance::IsAnotherInstanceRunning("Router")) {
        std::cerr << "Error: Another instance of lemonade-router is already running.\n"
                  << "Only one instance can run at a time." << std::endl;
        return 1;
    }

    try {
        CLIParser parser;
        parser.parse(argc, argv);

        // Handle early exits (e.g., --help, --version, or parsing errors)
        if (!parser.should_continue()) {
            return parser.get_exit_code();
        }

        // Extract configuration
        auto config = parser.get_config();

        // Setup logging
        auto log_sink = std::make_shared<AixLog::SinkCout>(
            AixLog::Filter(AixLog::to_severity(config.log_level)),
            "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message"
        );
        AixLog::Log::init({log_sink});

        // Log startup info
        LOG(INFO) << "Starting Lemonade Server..." << std::endl;
        LOG(INFO) << "  Version: " << LEMON_VERSION_STRING << std::endl;
        LOG(INFO) << "  Port: " << config.port << std::endl;
        LOG(INFO) << "  Host: " << config.host << std::endl;
        LOG(INFO) << "  Log level: " << config.log_level << std::endl;
        if (!config.extra_models_dir.empty()) {
            LOG(INFO) << "  Extra models dir: " << config.extra_models_dir << std::endl;
        }

        // Create and configure the server
        Server server(
            config.port,
            config.host,
            config.log_level,
            config.recipe_options,
            config.max_loaded_models,
            config.extra_models_dir,
            config.no_broadcast,
            config.global_timeout
        );

        // Register signal handlers
        g_active_server = &server;
        std::signal(SIGINT, handle_signal);
        std::signal(SIGTERM, handle_signal);

        // Run the server
        server.run();

        // Cleanup after shutdown
        g_active_server = nullptr;
        return 0;

    } catch (const std::exception& e) {
        LOG(ERROR) << "Error: " << e.what() << std::endl;
        return 1;
    }
}

#include "duckdb/main/extension_entries.hpp"
