namespace duckdb {

static string FindMatchingExtensionForPath(const string &path_pattern) {
	for (const auto &entry : EXTENSION_FILE_PREFIXES) {
		if (StringUtil::StartsWith(path_pattern, entry.name)) {
			return entry.extension;
		}
	}
	return "";
}

void DuckLakeInitializer::VerifyAndLoadRequiredExtension(const string &data_path) {
	// This function will:
	//	1. Determine if a known extension pattern matches the beginning of the data path
	//	2. If so, either load the required extension or produce an appropriate error message
	// NOTE: This function currently duplicates logic from FileSystem::GlobFiles in duckdb/duckdb (v1.3.0)
	// A better long-term approach would be to expose this functionality through the DuckDB C++ API,
	// which would simplify this file and reduce the chance of divergence between codebases.
	string needed_extension = FindMatchingExtensionForPath(data_path);
	if (!needed_extension.empty() && !context.db->ExtensionIsLoaded(needed_extension)) {
		if (!ExtensionHelper::CanAutoloadExtension(needed_extension) ||
		    !Settings::Get<AutoloadKnownExtensionsSetting>(context)) {
			string err_msg = "Data path '" + data_path + "' requires extension '" + needed_extension + "'";
			err_msg = ExtensionHelper::AddExtensionInstallHintToErrorMsg(context, err_msg, needed_extension);
			throw MissingExtensionException(err_msg);
		}
		// Required extension not loaded yet - attempt automatic loading
		ExtensionHelper::AutoLoadExtension(context, needed_extension);
		// Verify that the extension was successfully loaded to avoid infinite loops
		if (!context.db->ExtensionIsLoaded(needed_extension)) {
			throw InternalException("Extension '%s' load appeared successful but extension is still not loaded",
			                        needed_extension);
		}
	}
}

} // namespace duckdb

