atomic<bool> terminateFlag(false); // Flag to stop worker threads

// Forward declaration of EventLoop
struct EventLoop;

// Task type representing an async coroutine
struct AsyncOperation {
    struct promise_type {
        EventLoop* loop;
        AsyncOperation get_return_object() {
            return AsyncOperation{ std::coroutine_handle<promise_type>::from_promise(*this) };
        }
        std::suspend_always initial_suspend() { return {}; }
        struct completion_awaiter {
            bool await_ready() noexcept { return false; }
            void await_suspend(std::coroutine_handle<>) noexcept {}
            void await_resume() noexcept {}
        };
        completion_awaiter final_suspend() noexcept { return {}; }
        void unhandled_exception() {}
        void return_void() {}
    };
    std::coroutine_handle<promise_type> handle;
    AsyncOperation(std::coroutine_handle<promise_type> h) : handle(h) {}
    ~AsyncOperation() {
        if (handle) handle.destroy();
    }
    void submit(EventLoop& loop);
};

// EventLoop to manage coroutines within a thread
struct EventLoop {
    using ScheduledTask = pair<steady_clock::time_point, std::coroutine_handle<>>;
    priority_queue<ScheduledTask, vector<ScheduledTask>, greater<>> pendingTasks;

    void enqueue(std::coroutine_handle<> h) {
        pendingTasks.emplace(steady_clock::now(), h);
    }

    void enqueue_at(std::coroutine_handle<> h, steady_clock::time_point t) {
        pendingTasks.emplace(t, h);
    }

    void process() {
        while (!terminateFlag.load()) {
            if (!pendingTasks.empty()) {
                auto [targetTime, task] = pendingTasks.top();
                if (steady_clock::now() >= targetTime) {
                    pendingTasks.pop();
                    if (!task.done()) {
                        task.resume();
                    }
                } else {
                    auto delay = targetTime - steady_clock::now();
                    if (delay > milliseconds(1)) {
                        this_thread::sleep_for(milliseconds(1));
                    } else {
                        this_thread::yield();
                    }
                }
            } else {
                this_thread::yield();
            }
        }
    }
};

void AsyncOperation::submit(EventLoop& loop) {
    handle.promise().loop = &loop;
    loop.enqueue(handle);
}

// Awaitable for asynchronous sleep
struct DelayAwaiter {
    EventLoop& eventLoop;
    steady_clock::time_point triggerTime;

    DelayAwaiter(EventLoop& el, microseconds duration)
        : eventLoop(el), triggerTime(steady_clock::now() + duration) {}

    bool await_ready() {
        return steady_clock::now() >= triggerTime;
    }

    void await_suspend(std::coroutine_handle<> h) {
        eventLoop.enqueue_at(h, triggerTime);
    }

    void await_resume() {}
};

// Coroutine simulating transaction handling
AsyncOperation transaction_handler(EventLoop& loop, int& throughputCounter) {
    while (!terminateFlag.load()) {
        throughputCounter++;
        co_await DelayAwaiter(loop, microseconds(15));
    }
}

// Worker function running two coroutines per thread
void workerFunction(int id, int& localCounter) {
    EventLoop loop;
    AsyncOperation op1 = transaction_handler(loop, localCounter);
    AsyncOperation op2 = transaction_handler(loop, localCounter);
    op1.submit(loop);
    op2.submit(loop);
    loop.process();
}

int main(int argc, char* argv[]) {
    int threadCount = 4;
    vector<thread> workers;
    vector<int> perThreadCounts(threadCount, 0); // Per-thread counters

    for (int idx = 0; idx < threadCount; ++idx) {
        workers.emplace_back(workerFunction, idx, ref(perThreadCounts[idx]));
    }

    int duration = 10;
    this_thread::sleep_for(seconds(duration));
    terminateFlag.store(true);

    // Join all worker threads
    for (auto& w : workers) {
        w.join();
    }

    // Aggregate results
    int aggregateCount = 0;
    for (int i = 0; i < threadCount; ++i) {
        aggregateCount += perThreadCounts[i];
    }

    // Print throughput
    cout << "Throughput: " << aggregateCount / duration << " txn/sec" << endl;
    return 0;
}

