/// @brief Allocates memory for a new object.
/// @param size the amount of memory to allocate.
/// @return pointer to the allocated memory.
void* operator new(std::size_t size) {
  void* memory = nullptr;
  while (BS->AllocatePool(EfiMemoryType::EfiLoaderData, size, &memory) != kEfiOk);
  return memory;
}

/// @brief Allocates memory for a new array.
/// @param size the number of elements.
/// @return pointer to the allocated memory.
void* operator new[](std::size_t size) {
  void* memory = nullptr;
  BS->AllocatePool(EfiMemoryType::EfiLoaderData, size, &memory);
  return memory;
}

/// @brief Deallocates memory previously allocated by operator new.
/// @param ptr pointer to the memory to deallocate.
void operator delete(void* ptr) noexcept {
  if (!ptr) return;
  BS->FreePool(ptr);
}

/// @brief Deallocates memory previously allocated by operator new[].
/// @param ptr pointer to the memory to deallocate.
void operator delete[](void* ptr) noexcept {
  if (!ptr) return;
  BS->FreePool(ptr);
}

/// @brief Deallocates memory with explicit size (for arrays).
/// @param ptr pointer to the memory to deallocate.
/// @param sz size of the object (unused).
void operator delete(void* ptr, std::size_t sz) noexcept {
  if (!ptr) return;
  NE_UNUSED(sz);
  BS->FreePool(ptr);
}

/// @brief Deallocates array memory with explicit size.
/// @param ptr pointer to the memory to deallocate.
/// @param sz number of elements (unused).
void operator delete[](void* ptr, std::size_t sz) noexcept {
  if (!ptr) return;
  NE_UNUSED(sz);
  BS->FreePool(ptr);
}
#endif  // __BOOTZ_STANDALONE__

#include <iostream>
#include <vector>
#include <utility>
#include <cmath>

// Vector to record the sequence of transfers.
// Each transfer is represented as a pair (source_basket, target_basket).
std::vector<std::pair<int, int>> transferSteps;

/**
 * @brief Recursively computes the steps needed to move N disks from one peg to another.
 * 
 * This function follows the classic Tower of Hanoi solution pattern.
 * 
 * @param count Number of disks to relocate.
 * @param start Peg where the disks currently reside.
 * @param end Target peg for the disks.
 * @param temp Auxiliary peg used during the process.
 */
void computeMoves(int count, int start, int end, int temp) {
    if (count == 0) {
        return;
    }

    // Phase 1: Move top (count-1) disks from start to temp peg, using end as helper.
    computeMoves(count - 1, start, temp, end);

    // Phase 2: Move the largest disk from start to end.
    transferSteps.push_back({start, end});

    // Phase 3: Move the (count-1) disks from temp peg to end, using start as helper.
    computeMoves(count - 1, temp, end, start);
}

int main() {
    // Optimize input/output operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int numberOfDisks;
    std::cin >> numberOfDisks;

    // Initiate the solution: move all disks from peg 1 to peg 3, using peg 2 as auxiliary.
    computeMoves(numberOfDisks, 1, 3, 2);

    // Print total number of moves required.
    std::cout << transferSteps.size() << "\n";

    // Display each individual move.
    for (const auto& step : transferSteps) {
        std::cout << step.first << " " << step.second << "\n";
    }

    return 0;
}

