// Define the start marker for extra counters with specific alignment and section placement
#pragma section(".data$__libfuzzer_extra_countaaa")
ATTRIBUTE_ALIGNED(16)
__declspec(allocate(".data$__libfuzzer_extra_countaaa")) uint8_t
    __start___libfuzzer_extra_counters[16] = {0};

// Example of user-defined counter region (commented out for reference):
//     #pragma section(".data$__libfuzzer_extra_counters")
//     __declspec(allocate(".data$__libfuzzer_extra_counters"))
//         uint8_t any_name_variable[64 * 1024];

// Define the end marker for extra counters, placed just after user region
#pragma section(".data$__libfuzzer_extra_countzzz")
ATTRIBUTE_ALIGNED(1)
__declspec(allocate(".data$__libfuzzer_extra_countzzz")) uint8_t
    __stop___libfuzzer_extra_counters = 0;

// Compute pointer to first byte after the start marker
uint8_t *ExtraCountersBegin() {
  return __start___libfuzzer_extra_counters + sizeof(__start___libfuzzer_extra_counters);
}

// Return address of the stop marker as end boundary
uint8_t *ExtraCountersEnd() { return &__stop___libfuzzer_extra_counters; }

// Clear all extra counters by zeroing memory between boundaries
ATTRIBUTE_NO_SANITIZE_ALL
void ClearExtraCounters() {
  uint8_t *startPtr = ExtraCountersBegin();
  size_t sizeBytes = ExtraCountersEnd() - startPtr;
  SecureZeroMemory(startPtr, sizeBytes);
}

