#include <format>
#include <sm/vec>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

int main()
{
    // Initialize a mplot::Visual window with specified dimensions and title
    mplot::Visual scene(1280, 575, "Created using mplot::GraphVisual");

    // Instantiate a GraphVisual object at spatial origin (0,0,0)
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Essential initialization: link parent context and register internal callbacks
    scene.bindmodel(graph);

    // Prepare x-axis data using vvec (vector-like container with math operations)
    sm::vvec<double> x_coords;
    x_coords.linspace(0, 10, 11);  // Generate 11 points from 0 to 10

    // Define y-axis values manually
    sm::vvec<double> y_values = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure primary dataset style: crimson-colored line
    mplot::DatasetStyle primary_style(mplot::stylepolicy::lines);
    primary_style.linecolour = mplot::colour::crimson;

    // Enforce fixed y-axis range [0, 10]
    graph->setlimits_y(0, 10);

    // Assign data to the graph
    graph->setdata(x_coords, y_values, primary_style);

    // Setup secondary style for horizontal reference line at y=7
    mplot::DatasetStyle horiz_style(mplot::stylepolicy::lines);
    horiz_style.linecolour = mplot::colour::grey68;
    horiz_style.linewidth = primary_style.linewidth * 0.6f;

#ifdef GRAPH_LINES_SIMPLE
    // Add simple crossing lines without annotation
    graph->add_y_crossing_lines(x_coords, y_values, 7, primary_style);
#else
    // Compute exact x-coordinates where graph crosses y=7
    sm::vvec<double> cross_points = graph->add_y_crossing_lines(
        x_coords, y_values, 7, primary_style, horiz_style);

    // Format crossing points into human-readable string
    size_t count = cross_points.size();
    std::stringstream formatter;

    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            formatter << std::format(
                "{}{}{:.2f}",
                ((idx == 0 || idx == count - 1) ? "" : ", "),
                (idx == count - 1) ? " and " : "",
                cross_points[idx]);
        }
    } else {
        formatter << "[no intersections]";
    }

    // Place descriptive label in lower-left corner of plot
    graph->addLabel(
        std::format("y=7 at x = {}", formatter.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures(0.03f));
#endif

    // Finalize rendering setup by computing OpenGL vertex data
    graph->finalize();

    // Transfer ownership of graph model to visual scene
    scene.addVisualModel(graph);

    // Display window and handle user interaction until quit
    scene.keepOpen();

    // Automatic cleanup via RAII when 'scene' destructor runs
    return 0;
}

#include <catch2/catch_test_macros.hpp>
#include <Gorgon/Encoding/LZMA.h>
#include <fstream>
#include <string>
using namespace Gorgon;
using namespace Gorgon::Encoding;

TEST_CASE("LZMA encode and decode vector round-trip", "[LZMA]") {
    // Load README.md from project root
    std::ifstream datafile(TESTDIR "/../../README.md", std::ios::binary);
    REQUIRE(datafile.is_open());
    std::string source((std::istreambuf_iterator<char>(datafile)),
                        std::istreambuf_iterator<char>());
    datafile.close();
    REQUIRE(!source.empty());

    // Transform to byte array
    std::vector<Byte> buffer(source.begin(), source.end());

    SECTION("Using uncompressed size (default mode)") {
        LZMA compressor(true);

        // Encode
        std::vector<Byte> encoded;
        compressor.Encode(buffer, encoded);
        REQUIRE(!encoded.empty());

        // Encoded output must differ in size
        REQUIRE(encoded.size() != buffer.size());

        // Decode
        std::vector<Byte> decoded;
        compressor.Decode(encoded, decoded);

        // Confirm round-trip integrity
        REQUIRE(decoded.size() == buffer.size());
        std::string recovered(decoded.begin(), decoded.end());
        REQUIRE(recovered == source);
    }

    SECTION("Without uncompressed size (end-marker based)") {
        LZMA compressor(false);

        // Encode
        std::vector<Byte> encoded;
        compressor.Encode(buffer, encoded);
        REQUIRE(!encoded.empty());

        // Decode (size unknown, rely on end-of-stream marker)
        std::vector<Byte> decoded;
        compressor.Decode(encoded, decoded);

        // Confirm round-trip integrity
        REQUIRE(decoded.size() == buffer.size());
        std::string recovered(decoded.begin(), decoded.end());
        REQUIRE(recovered == source);
    }

    SECTION("PropertySize returns correct values") {
        LZMA lzmaWithSize(true);
        REQUIRE(lzmaWithSize.PropertySize() == 13); // 5 props + 8 size

        LZMA lzmaNoSize(false);
        REQUIRE(lzmaNoSize.PropertySize() == 5); // 5 props only
    }
}

TEST_CASE("LZMA encode and decode string round-trip", "[LZMA]") {
    std::string source = "Hello, this is a test string for LZMA compression! "
                         "It needs to be long enough to actually compress. "
                         "LZMA compression works best with repeated patterns. "
                         "Repeated patterns. Repeated patterns. Repeated patterns. "
                         "The quick brown fox jumps over the lazy dog. "
                         "The quick brown fox jumps over the lazy dog. "
                         "The quick brown fox jumps over the lazy dog.";

    LZMA compressor;

    // Encode string to byte vector
    std::vector<Byte> encoded;
    compressor.Encode(source, encoded);
    REQUIRE(!encoded.empty());

    // Decode byte vector back to string
    std::string decoded;
    compressor.Decode(encoded, decoded);
    REQUIRE(decoded == source);
}

