	StructHandle = PropertyHandle;

	// Gather the DMX Library TakeRecorder objects currently being edited
	TArray<UObject*> EditedObjects;
	PropertyHandle->GetOuterObjects(EditedObjects);
	RecordersToCustomize.Reserve(EditedObjects.Num());

