bool FDMXLibraryRecorderAddAllPatchesButtonCustomization::IsAddAllEnabled() const
{
	// Enable only if every selected recorder has a valid DMX library assigned
	for (const TWeakObjectPtr<UTakeRecorderDMXLibrarySource>& Recorder : RecordersToCustomize)
	{
		if (!Recorder.IsValid() || !Recorder->IsValidLowLevelFast()
			|| Recorder->DMXLibrary == nullptr || !Recorder->DMXLibrary->IsValidLowLevelFast())
		{
			return false;
		}
	}
	return true;
}

FReply FDMXLibraryRecorderAddAllPatchesButtonCustomization::OnButtonClicked()
{
	check(StructHandle.IsValid() && StructHandle->IsValidHandle());

	// Wrap changes in a transaction for undo support
	{
		const FScopedTransaction Transaction(LOCTEXT("Transaction", "Add All Fixture Patches for Recording"));

		// Notify owners before modification
		StructHandle->NotifyPreChange();

		// Apply changes to each recorder
		for (TWeakObjectPtr<UTakeRecorderDMXLibrarySource>& Recorder : RecordersToCustomize)
		{
			if (Recorder.IsValid() && Recorder->IsValidLowLevelFast())
			{
				Recorder->AddAllPatches();
			}
		}

		// Notify owners after modification
		StructHandle->NotifyPostChange();
	}

	// Final notification to complete property change
	StructHandle->NotifyFinishedChangingProperties();
	return FReply::Handled();
}

