#include <sol/sol.hpp>
#define SOL_ALL_SAFETIES_ON 1

// Demonstration of accessing 'this' pointer in Lua-bound constructors and member functions
int main() {
    // Define a simple structure to bind with Lua
    struct entity {
        // Constructor: receives sol::this_state to access the Lua stack
        entity(sol::this_state state) {
            lua_State* L = state;
            // Retrieve the object at stack index 1 (the instance being constructed)
            sol::stack_object instance(L, 1);
            // Cast to our type and verify it matches the current 'this'
            entity& self = instance.as<entity>();
            SOL_ASSERT(&self == this);
        }

        // Member function: also uses sol::this_state for self-reference
        void process(sol::this_state state) const {
            lua_State* L = state;
            // Stack index 1 holds the calling object
            sol::stack_object obj(L, 1);
            // Extract and validate reference to current instance
            entity& self = obj.as<entity>();
            SOL_ASSERT(&self == this);
        }
    };

    // Initialize Lua environment
    sol::state vm;
    vm.open_libraries(sol::lib::base);

    // Register the entity class with Lua
    vm.new_usertype<entity>("entity",
        sol::constructors<entity(sol::this_state)>(),
        "process",
        &entity::process);

    // Execute Lua script that creates an instance and calls its method
    vm.script(R"(
instance = entity.new()
instance:process()
)");

    return 0;
}

