namespace
{
// Determines whether a CFG node belongs to the top-level category.
// Top-level nodes (Alloc, Copy, Offset) influence only top-level pointers (Env),
// and do not access or modify the memory Store.
bool isTopLevel(const CFGNode* nd)
{
	return nd->isAllocNode() || nd->isCopyNode() || nd->isOffsetNode();
}
} // anonymous namespace

// Attempts to update the memoization cache with new store information.
// Returns true if the stored state for this program point was modified.
// If updated, the point is scheduled onto the worklist for further propagation.
bool SemiSparsePropagator::scheduleOnUpdate(const ProgramPoint& pt, const Store& st)
{
	if (memo.update(pt, st))
	{
		workList.enqueue(pt);
		return true;
	}
	else
		return false;
}

// Handles propagation for top-level operations (Alloc, Copy, Offset).
// Since these don't affect the Store, we directly enqueue the successor point.
// Environment changes occur in-place via TransferFunction/GlobalState.
void SemiSparsePropagator::propagateTop(const EvalSuccessor& succ)
{
	// No store merging needed; just schedule the next point
	workList.enqueue(succ.getProgramPoint());
	//errs() << "\tENQ(T) " << succ.getProgramPoint() << "\n";
}

// Manages propagation for memory-affecting operations (Load, Store, Call, Ret).
// These require merging of Store states before deciding whether to enqueue.
void SemiSparsePropagator::propagateMem(const EvalSuccessor& succ)
{
	const auto *nd = succ.getProgramPoint().getCFGNode();
	assert(!isTopLevel(nd));
	assert(succ.getStore() != nullptr);

	// Determine if the outgoing Store differs from previously recorded state.
	bool scheduled = scheduleOnUpdate(succ.getProgramPoint(), *succ.getStore());
	//if (scheduled)
	//	errs() << "\tENQ(M) " << succ.getProgramPoint() << "\n";
}

// Primary entry for flow propagation.
// Iterates through all successors generated by transfer function evaluation,
// routing each to the correct handler based on node type.
void SemiSparsePropagator::propagate(const EvalResult& result)
{
	for (const auto& succ : result)
	{
		if (succ.isTopLevel())
			propagateTop(succ);
		else
			propagateMem(succ);
	}
}
} // namespace tpa

