InvertedListsIOHook::InvertedListsIOHook(
        const std::string& identifier,
        const std::string& type_name)
        : key(identifier), classname(type_name) {}

namespace {
/// Custom vector that owns and deletes its InvertedListsIOHook elements
struct CallbackRegistry : std::vector<InvertedListsIOHook*> {
    CallbackRegistry() {
#ifndef _WIN32
        push_back(new OnDiskInvertedListsIOHook());
#endif
        push_back(new BlockInvertedListsIOHook());
    }
    ~CallbackRegistry() {
        for (auto item : *this) {
            delete item;
        }
    }
};
static CallbackRegistry inverted_lists_callbacks;
} // namespace

InvertedListsIOHook* InvertedListsIOHook::find_by_code(int code) {
    for (const auto& handler : inverted_lists_callbacks) {
        if (code == fourcc(handler->key)) {
            return handler;
        }
    }
    FAISS_THROW_FMT(
            "read_InvertedLists: could not load ArrayInvertedLists as "
            "%08x (\"%s\")",
            code,
            fourcc_inv_printable(code).c_str());
}

InvertedListsIOHook* InvertedListsIOHook::find_by_type(const std::string& type_name) {
    for (const auto& handler : inverted_lists_callbacks) {
        if (handler->classname == type_name) {
            return handler;
        }
    }
    FAISS_THROW_FMT(
            "read_InvertedLists: could not find type %s",
            type_name.c_str());
}

void InvertedListsIOHook::register_hook(InvertedListsIOHook* hook) {
    inverted_lists_callbacks.push_back(hook);
}

void InvertedListsIOHook::list_hooks() {
    printf("registered %zd InvertedListsIOHooks:\n",
           inverted_lists_callbacks.size());
    for (const auto& hook : inverted_lists_callbacks) {
        printf("%08x %s %s\n",
               fourcc(hook->key.c_str()),
               hook->key.c_str(),
               hook->classname.c_str());
    }
}

InvertedLists* InvertedListsIOHook::read_ArrayInvertedLists(
        IOReader*,
        int,
        size_t,
        size_t,
        const std::vector<size_t>&) const {
    FAISS_THROW_FMT("read to array not implemented for %s", classname.c_str());
}

