using namespace llvm;

PPCXCOFFStreamer::PPCXCOFFStreamer(MCContext &Context,
                                   std::unique_ptr<MCAsmBackend> MAB,
                                   std::unique_ptr<MCObjectWriter> OW,
                                   std::unique_ptr<MCCodeEmitter> Emitter)
    : MCXCOFFStreamer(Context, std::move(MAB), std::move(OW),
                      std::move(Emitter)) {}

// Emit a prefixed instruction with proper alignment to avoid crossing 64-byte boundaries
void PPCXCOFFStreamer::emitPrefixedInstruction(const MCInst &Inst,
                                               const MCSubtargetInfo &STI) {
  // Ensure the prefix does not cross a 64-byte boundary by inserting padding if needed.
  // Insert up to 4 bytes of padding (nops) to align to 64-byte boundary.
  emitCodeAlignment(Align(64), &STI, 4);

  // Now emit the actual prefixed instruction.
  // This will create a new code fragment since previous alignment may have started a new one.
  MCXCOFFStreamer::emitInstruction(Inst, STI);
}

// Override base emitInstruction to handle prefixed instructions specially
void PPCXCOFFStreamer::emitInstruction(const MCInst &Inst,
                                       const MCSubtargetInfo &STI) {
  PPCMCCodeEmitter *Emitter =
      static_cast<PPCMCCodeEmitter *>(getAssembler().getEmitterPtr());

  // Only apply special handling for prefixed instructions
  if (!Emitter->isPrefixedInstruction(Inst)) {
    MCXCOFFStreamer::emitInstruction(Inst, STI);
    return;
  }

  // Handle prefixed instruction with alignment considerations
  emitPrefixedInstruction(Inst, STI);
}

// Factory function to create a PPC XCOFF streamer instance
MCXCOFFStreamer *
llvm::createPPCXCOFFStreamer(MCContext &Context,
                             std::unique_ptr<MCAsmBackend> MAB,
                             std::unique_ptr<MCObjectWriter> OW,
                             std::unique_ptr<MCCodeEmitter> Emitter) {
  return new PPCXCOFFStreamer(Context, std::move(MAB), std::move(OW),
                              std::move(Emitter));
}

#include <iostream>
#include <nlohmann/json.hpp>
using json = nlohmann::json;

int main() {
    // Initialize a JSON array with string values
    const json data_array = {"alpha", "beta", "gamma", "delta"};

    // Print the element at index 2 (third item)
    std::cout << data_array.at(2) << '\n';

    // Handle type_error exception when accessing non-array JSON
    try {
        const json text_value = "This is a string";
        std::cout << text_value.at(0) << '\n';
    }
    catch (const json::type_error& error) {
        std::cout << error.what() << '\n';
    }

    // Handle out_of_range exception when index exceeds bounds
    try {
        std::cout << data_array.at(10) << '\n';
    }
    catch (const json::out_of_range& error) {
        std::cout << error.what() << '\n';
    }

    return 0;
}

