#ifndef Py_GIL_DISABLED
/* Reset all internal object pools
 * During full garbage collection (highest generation), all pooled objects
 * are reclaimed. Keeping pooled objects can prevent arenas from being
 * released back to the OS.
 * Clearing these pools helps return memory to the system sooner.
 */
void
_PyGC_ResetAllPools(PyInterpreterState *state)
{
    _PyObject_ResetFreeLists(&state->object_pool.freelist, 0);
}
#endif

