class handler_callback {
 public:
  std::mutex mtx;
  std::vector<mongodb_handler::SampleCommand> processed_commands;

  void handle(mongodb_handler::SampleCommand request) {
    std::lock_guard<std::mutex> guard(mtx);
    processed_commands.push_back(request);
  }
};

int main() {
  // mongocxx::instance instance;
  // mongodb_handler::MongodbKVTableHandler handler;
  // std::cout << handler.Read(1) << std::endl;
  // std::cout << handler.Write(1, 3) << std::endl;
  // std::cout << handler.Read(1) << std::endl;
  // std::cout << handler.Write(1, 5) << std::endl;
  // std::cout << handler.Read(1) << std::endl;
  // std::cout << handler.Write(3, 13) << std::endl;
  // std::cout << handler.Write(5, 15) << std::endl;
  // std::cout << handler.Read(3) << std::endl;

  auto initialization_time = std::chrono::high_resolution_clock::now();
  const int thread_pool_capacity = 4000;
  handler_callback callback_obj;
  std::function<void(mongodb_handler::SampleCommand)> callback_wrapper = 
      std::bind(&handler_callback::handle, &callback_obj, std::placeholders::_1);
  mongodb_handler::MongodbConnectionThreadPool pool(thread_pool_capacity, callback_wrapper);

  std::srand(static_cast<unsigned>(std::time(nullptr)));
  const int total_requests = 100000;

  auto start_measurement = std::chrono::high_resolution_clock::now();
  for (int index = 0; index < total_requests; ++index) {
    mongodb_handler::SampleCommand cmd{
        static_cast<int>(std::rand() % 2), 
        index, 
        std::rand() % 1000000
    };
    pool.MongodbRequest(cmd);
  }
  pool.Close();

  auto finish_measurement = std::chrono::high_resolution_clock::now();
  auto setup_time = std::chrono::duration_cast<std::chrono::milliseconds>(start_measurement - initialization_time);
  auto processing_time = std::chrono::duration_cast<std::chrono::milliseconds>(finish_measurement - start_measurement);

  std::cout << "Setup Duration: " << setup_time.count() << " ms" << std::endl;
  std::cout << "Setup Throughput: " << thread_pool_capacity * 1000.0 / setup_time.count() << " connections/s" << std::endl;
  std::cout << "Processing Time: " << processing_time.count() << " ms" << std::endl;
  std::cout << "Processing Rate: " << total_requests * 1000.0 / processing_time.count() << " req/s" << std::endl;
  std::cout << "Average MongoDB Latency: " << pool.LatencyMs() << " ms" << std::endl;
  std::cout << "Total Processed Commands: " << callback_obj.processed_commands.size() << std::endl;

  return 0;
}

