// Main function to demonstrate NDB cluster operations with modified identifiers and structure
int main(int argument_count, char **argument_vector) {
  // Validate command-line arguments
  if (argument_count != 3) {
    std::cout << "Usage: <socket mysqld> <connect_string cluster> required.\n";
    exit(-1);
  }

  // Extract connection parameters
  char *mysql_socket = argument_vector[1];
  const char *cluster_connect_string = argument_vector[2];

  // Initialize MySQL connection
  MYSQL mysql_conn;
  mysql_init(&mysql_conn);
  mysql_connect_and_create(mysql_conn, mysql_socket);

  // Initialize NDB subsystem
  ndb_init();

  // Perform NDB scan operations using the cluster connection string
  ndb_run_scan(cluster_connect_string);

  // Cleanup
  ndb_end(0);
  mysql_close(&mysql_conn);
  return 0;
}

// Helper function for NDB operations (renamed from original)
void ndb_run_scan(const char *connectstring) {
  Ndb_cluster_connection cluster_conn(connectstring);

  // Attempt cluster connection with timeout
  if (cluster_conn.connect(4, 5, 1)) {
    std::cout << "Connection to cluster failed within 30 seconds." << std::endl;
    exit(-1);
  }

  // Wait for storage nodes to become ready
  if (cluster_conn.wait_until_ready(30, 0) < 0) {
    std::cout << "Cluster did not become ready within 30 seconds.\n";
    exit(-1);
  }

  // Create NDB instance for database 'ndb_examples'
  Ndb myNdb(&cluster_conn, "ndb_examples");
  if (myNdb.init(1024) == -1) {  // Max 1024 parallel transactions
    APIERROR(myNdb.getNdbError());
    exit(-1);
  }

  /*******************************************
   * Verify table schema                     *
   *******************************************/
  int color_column_index;
  {
    const NdbDictionary::Dictionary *schema_mgr = myNdb.getDictionary();
    const NdbDictionary::Table *table_def = schema_mgr->getTable("api_scan");

    if (table_def == NULL) {
      std::cout << "Failed to retrieve table definition via Dictionary::getTable().";
      exit(-1);
    }

    Car sample_record;
    // Validate column sizes match expected types
    if (table_def->getColumn("COLOR")->getLength() != sizeof(sample_record.color) ||
        table_def->getColumn("BRAND")->getLength() != sizeof(sample_record.brand)) {
      std::cout << "Schema mismatch detected in table definition" << std::endl;
      exit(-1);
    }

    color_column_index = table_def->getColumn("COLOR")->getColumnNo();
  }

  // Populate data into table
  if (populate(&myNdb) > 0) 
    std::cout << "Data population completed successfully!" << std::endl;

  // Display initial data
  if (scan_print(&myNdb) > 0)
    std::cout << "Initial scan display completed successfully!" << std::endl << std::endl;

  // Delete all pink cars
  std::cout << "Deleting all pink vehicles..." << std::endl;
  {
    Car temp_vehicle;
    sprintf(temp_vehicle.color, "Pink");
    if (scan_delete(&myNdb, color_column_index, temp_vehicle.color) > 0)
      std::cout << "Pink vehicle deletion completed successfully!" << std::endl << std::endl;
  }

  // Show updated data after deletions
  if (scan_print(&myNdb) > 0)
    std::cout << "Post-deletion scan display completed successfully!" << std::endl << std::endl;

  // Update all blue cars to black
  {
    Car source_vehicle, target_vehicle;
    sprintf(source_vehicle.color, "Blue");
    sprintf(target_vehicle.color, "Black");

    std::cout << "Updating all " << source_vehicle.color 
              << " vehicles to " << target_vehicle.color 
              << "..." << std::endl;

    if (scan_update(&myNdb, color_column_index, source_vehicle.color, target_vehicle.color) > 0)
      std::cout << "Color update operation completed successfully!" << std::endl << std::endl;
  }

  // Final data verification
  if (scan_print(&myNdb) > 0)
    std::cout << "Final scan display completed successfully!" << std::endl << std::endl;
}

#include "Commands.hpp"
#include "Command.hpp"
#include "LoopedCommand.hpp"
#include "core/backend/ScriptMgr.hpp"

namespace YimMenu
{
	Commands::Commands() :
	    IStateSerializer("commands")
	{
	}

	void Commands::RunScript()
	{
		Commands::EnableBoolCommands();
		while (g_Running)
		{
			Commands::RunLoopedCommands();
			ScriptMgr::Yield();
		}
	}

	void Commands::AddCommandImpl(Command* cmd)
	{
		m_Commands.insert({cmd->GetHash(), cmd});
	}

	void Commands::AddBoolCommandImpl(BoolCommand* cmd)
	{
		m_BoolCommands.push_back(cmd);
	}

	void Commands::AddLoopedCommandImpl(LoopedCommand* cmd)
	{
		m_LoopedCommands.push_back(cmd);
	}

	void Commands::EnableBoolCommandsImpl()
	{
		for (auto& cmd : m_BoolCommands)
			if (cmd->GetState())
				cmd->Initialize();
	}

	void Commands::RunLoopedCommandsImpl()
	{
		for (auto& cmd : m_LoopedCommands)
			if (cmd->GetState() && cmd->IsReady())
				cmd->Tick();
	}

	Command* Commands::GetCommandImpl(joaat_t hash)
	{
		if (auto it = m_Commands.find(hash); it != m_Commands.end())
			return it->second;
		return nullptr;
	}

	void Commands::SaveStateImpl(nlohmann::json& state)
	{
		for (auto& cmd : m_Commands)
		{
			if (!state.contains(cmd.second->GetName()))
				state[cmd.second->GetName()] = nlohmann::json::object();
			cmd.second->SaveState(state[cmd.second->GetName()]);
		}
	}

	void Commands::LoadStateImpl(nlohmann::json& state)
	{
		for (auto& cmd : m_Commands)
		{
			if (state.contains(cmd.second->GetName()))
				cmd.second->LoadState(state[cmd.second->GetName()]);
		}
	}

	void Commands::ShutdownImpl()
	{
		for (auto& cmd : m_LoopedCommands)
			if (cmd->GetState())
				cmd->Shutdown();
	}
}

