// Configuration class to handle relocation modifications
class RelocModifierConfig : public eld::plugin::LinkerPluginConfig {
public:
  RelocModifierConfig(RelocModifier *plugin)
      : LinkerPluginConfig(plugin), pluginRef(plugin) {}

  void Init() override {
    // Register the R_HEX_B22_PCREL relocation type for processing
    std::string relocName = "R_HEX_B22_PCREL";
    uint32_t relocType =
        pluginRef->getLinker()->getRelocationHandler().getRelocationType(relocName);
    pluginRef->getLinker()->registerReloc(relocType);
  }

  // Callback function invoked for each registered relocation
  void RelocCallBack(eld::plugin::Use U) override {
    // Output information about the relocation source
    std::string srcSection = U.getSourceChunk().getName();
    std::cout << "Relocation callback. Source section: " << srcSection
              << ", symbol: " << U.getName() << "\n";

    // Replace symbol name from HelloWorld to HelloQualcomm if matched
    if (U.getSymbol().getName() == "HelloWorld") {
      eld::Expected<eld::plugin::Symbol> newSymbol =
          pluginRef->getLinker()->getSymbol("HelloQualcomm");
      ELDEXP_REPORT_AND_RETURN_VOID_IF_ERROR(
          pluginRef->getLinker(), newSymbol);
      U.resetSymbol(std::move(newSymbol.value()));
    }
  }

private:
  RelocModifier *pluginRef;
};

// Global plugin instances
eld::plugin::Plugin *mainPlugin = nullptr;
eld::plugin::LinkerPluginConfig *mainConfig = nullptr;

extern "C" {
// Register all plugins and configurations provided by this library
bool DLL_A_EXPORT RegisterAll() {
  mainPlugin = new RelocModifier();
  mainConfig = new RelocModifierConfig(
      dynamic_cast<RelocModifier *>(mainPlugin));
  return true;
}

// Return plugin instance by name
eld::plugin::Plugin *getPlugin(const char *name) { return mainPlugin; }

// Return plugin configuration instance by name
eld::plugin::LinkerPluginConfig DLL_A_EXPORT *getPluginConfig(const char *name) {
  return mainConfig;
}

// Clean up resources when plugin library is unloaded
void DLL_A_EXPORT Cleanup() {
  if (mainPlugin)
    delete mainPlugin;
  if (mainConfig)
    delete mainConfig;
}
}

#include "server.hpp"
#include <signal.h>
#include <utility>

namespace http {
namespace server {

// Constructor for the HTTP server, initializing resources and setting up signal handling
server::server(const std::string& host, const std::string& port_number,
    const std::string& document_root)
  : service_context_(1),
    termination_signals_(service_context_),
    tcp_acceptor_(service_context_),
    active_connections_(),
    request_processor_(document_root)
{
  // Set up signal handlers to gracefully terminate the server
  termination_signals_.add(SIGINT);
  termination_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  termination_signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  prepare_for_shutdown();

  // Resolve the provided address and port into an endpoint
  asio::ip::tcp::resolver resolver(service_context_);
  auto endpoints = resolver.resolve(host, port_number);
  asio::ip::tcp::endpoint server_endpoint = *endpoints.begin();

  // Configure and open the acceptor
  tcp_acceptor_.open(server_endpoint.protocol());
  tcp_acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  tcp_acceptor_.bind(server_endpoint);
  tcp_acceptor_.listen();

  initiate_acceptance();
}

// Start the server's main event loop
void server::start() {
  service_context_.run();
}

// Asynchronous accept loop for new connections
void server::initiate_acceptance() {
  tcp_acceptor_.async_accept(
      [this](std::error_code error, asio::ip::tcp::socket client_socket)
      {
        // Exit if acceptor was closed (e.g., during shutdown)
        if (!tcp_acceptor_.is_open()) {
          return;
        }

        if (!error) {
          active_connections_.start(std::make_shared<connection>(
              std::move(client_socket), active_connections_, request_processor_));
        }

        // Continue accepting new connections
        initiate_acceptance();
      });
}

// Setup signal handler to trigger graceful shutdown
void server::prepare_for_shutdown() {
  termination_signals_.async_wait(
      [this](std::error_code /*ignored*/, int signal_number)
      {
        // Close acceptor and stop all active connections
        tcp_acceptor_.close();
        active_connections_.terminate_all();
      });
}

} // namespace server
} // namespace http

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Upper bound on array size as per problem constraints
const int MAX_SIZE = 200005;
int arr[MAX_SIZE];
int size;

// Function to perform a query on range [left, right]
void query(int left, int right, int &mode_val, int &freq) {
    if (left > right) {
        mode_val = -1; 
        freq = -1;
        return;
    }
    cout << "? " << left << " " << right << endl;
    cin >> mode_val >> freq;
    // If invalid response received, terminate to prevent TLE
    if (mode_val == -1) exit(0); 
}

// Recursive function to determine array elements
// left, right: current segment boundaries
// known_mode, known_freq: mode and frequency if already determined, else -1
void solve(int left, int right, int known_mode, int known_freq) {
    if (left > right) return;

    int mode_val, freq;
    if (known_mode != -1) {
        mode_val = known_mode;
        freq = known_freq;
    } else {
        query(left, right, mode_val, freq);
    }

    // Base case: entire segment consists of same value
    if (freq == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            arr[idx] = mode_val;
        }
        return;
    }

    // Query prefix of length (segment_length - freq): [left, right - freq]
    int left_mode, left_freq;
    query(left, right - freq, left_mode, left_freq);

    if (left_mode == mode_val) {
        // Mode remains in left part, recurse accordingly
        solve(left, right - freq, left_mode, left_freq);
        solve(right - freq + 1, right, -1, -1);
        return;
    }

    // Query suffix of length (segment_length - freq): [left + freq, right]
    int right_mode, right_freq;
    query(left + freq, right, right_mode, right_freq);

    if (right_mode == mode_val) {
        // Mode remains in right part, recurse accordingly
        solve(left, left + freq - 1, -1, -1);
        solve(left + freq, right, right_mode, right_freq);
        return;
    }

    // If mode doesn't dominate either end, check for middle concentration
    // Gap exists when 2*freq > segment_length
    if (2 * freq > right - left + 1) {
        for (int idx = right - freq + 1; idx <= left + freq - 1; ++idx) {
            arr[idx] = mode_val;
        }
    }

    // Recurse on both sub-intervals with gathered information
    solve(left, right - freq, left_mode, left_freq);
    solve(left + freq, right, right_mode, right_freq);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> size)) return 0;

    solve(1, size, -1, -1);

    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << arr[i];
    }
    cout << endl;

    return 0;
}

