#include <utility>

using asio::ip::tcp;

//------------------------------------------------------------------------------
// A simplified version of a composed async operation that wraps an existing write operation
template <typename CompletionToken>
auto send_data(tcp::socket& sock,
    const char* data, CompletionToken&& token)
  // Return type depends on the completion token: void for callbacks, 
  // std::future<std::size_t> for use_future, etc.
  -> typename asio::async_result<
    typename std::decay<CompletionToken>::type,
    void(std::error_code, std::size_t)>::return_type
{
  // Forward the token perfectly to preserve semantics (e.g., move-only lambdas)
  return asio::async_write(sock,
      asio::buffer(data, std::strlen(data)),
      std::forward<CompletionToken>(token));
}
//------------------------------------------------------------------------------

void run_callback_test()
{
  asio::io_context ioc;
  tcp::acceptor acc(ioc, {tcp::v4(), 8080});
  tcp::socket client_sock = acc.accept();

  // Use a lambda as the completion handler
  send_data(client_sock, "Callback mode test\r\n",
      [](const std::error_code& ec, std::size_t bytes)
      {
        if (!ec)
        {
          std::cout << bytes << " bytes sent successfully\n";
        }
        else
        {
          std::cout << "Transmission failed: " << ec.message() << "\n";
        }
      });

  ioc.run();
}

//------------------------------------------------------------------------------

void run_future_test()
{
  asio::io_context ioc;
  tcp::acceptor acc(ioc, {tcp::v4(), 8081});
  tcp::socket client_sock = acc.accept();

  // Use use_future to get a future result
  std::future<std::size_t> result = send_data(
      client_sock, "Future-based test\r\n", asio::use_future);

  ioc.run();

  try
  {
    std::size_t transferred = result.get();
    std::cout << transferred << " bytes sent\n";
  }
  catch (const std::exception& ex)
  {
    std::cout << "Exception caught: " << ex.what() << "\n";
  }
}

//------------------------------------------------------------------------------

int main()
{
  run_callback_test();
  run_future_test();
  return 0;
}

