#include "IntBuffer.h"

// Creates a new integer buffer.
// The newly created buffer will have its position at zero, its limit equal to its capacity, and an undefined mark.
// It includes a backing array with an array offset of zero.
//
// Parameters:
// size - The maximum number of integers the buffer can hold
IntBuffer::IntBuffer(unsigned int size) : Buffer(size)
{
	dataArray = new int[size];
	memset(dataArray, 0, sizeof(int) * size);
}

// Constructs a buffer using an existing array as its backing store.
// Parameters:
// size - The buffer's capacity
// externalArray - Pre-allocated integer array to use as storage
IntBuffer::IntBuffer(unsigned int size, int* externalArray) : Buffer(size)
{
	usesExternalArray = true;
	dataArray = externalArray;
}

IntBuffer::~IntBuffer()
{
	if (!usesExternalArray)
		delete[] dataArray;
}

int* IntBuffer::getData()
{
	return dataArray;
}

// Reverses the buffer's state: sets the limit to the current position and resets the position to zero.
// Any existing mark is cleared.
//
// Returns:
// Reference to this buffer for method chaining
IntBuffer* IntBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Reads an integer from a specific location in the buffer.
// Parameters:
// idx - Index of the element to retrieve (must be less than current limit)
// Returns:
// The integer value stored at the specified index
int IntBuffer::get(unsigned int idx)
{
	assert(idx < m_limit);
	return dataArray[idx];
}

// Copies multiple integers into this buffer from a source array.
// If insufficient space remains, no elements are copied and an error condition occurs.
//
// Parameters:
// src - Source array containing values to copy
// startIdx - Starting position in the source array (non-negative and within bounds)
// count - Number of elements to transfer (non-negative and within available range)
// Returns:
// This buffer instance for chaining operations
IntBuffer* IntBuffer::put(intArray* sourceArray, unsigned int startIdx, unsigned int count)
{
	assert(startIdx + count <= sourceArray->length);
	std::copy(sourceArray->data + startIdx, sourceArray->data + startIdx + count, dataArray + m_position);
	m_position += count;
	return this;
}

// Bulk insertion of all elements from a given array.
// Parameters:
// src - Complete array whose contents should be inserted
// Returns:
// This buffer after insertion
IntBuffer* IntBuffer::put(intArray sourceArray)
{
	if (sourceArray.length > remaining())
		assert(false); // TODO 4J Stu - Exception handling needed here?

	std::copy(sourceArray.data, sourceArray.data + sourceArray.length, dataArray + m_position);
	m_position += sourceArray.length;
	return this;
}

// Inserts a single integer at the current position and advances the position.
// Parameters:
// value - Integer value to store
// Returns:
// This buffer for fluent interface usage
IntBuffer* IntBuffer::put(int value)
{
	assert(m_position < m_limit);
	dataArray[m_position++] = value;
	return this;
}

