#include <iostream>
#include <cstdlib>

// Function to send a query to the judge and receive the result
long long ask(long long node, long long steps) {
    std::cout << "? " << node << " " << steps << std::endl;
    long long response;
    std::cin >> response;
    return response;
}

// Function to submit the final answer and verify correctness
void submit(long long cycle_length) {
    std::cout << "! " << cycle_length << std::endl;
    int validation;
    std::cin >> validation;
    if (validation == -1) {
        // Incorrect answer — terminate execution
        std::exit(0);
    }
}

void process() {
    // Obtain a node known to be on the cycle by taking a large jump from node 1
    long long cycle_node = ask(1, 5000000000000000000LL);

    // Step 1: Determine an interval [L, 2L] that contains the cycle length
    long long segment_length = 1;
    long long current_position = ask(cycle_node, 1);

    while (current_position != cycle_node) {
        current_position = ask(current_position, segment_length);
        segment_length *= 2;
    }

    // Now we know the cycle length s satisfies: segment_length/2 < s <= segment_length
    long long left = segment_length / 2 + 1;
    long long right = segment_length;
    long long s = segment_length;

    // Step 2: Binary search within [left, right] to find the minimal cycle length
    while (left <= right) {
        long long mid = left + (right - left) / 2;

        if (mid == 0) { // Safety check — should not occur for valid inputs
            left = 1;
            continue;
        }

        if (ask(cycle_node, mid) == cycle_node) {
            // Found a smaller valid cycle length
            s = mid;
            right = mid - 1;
        } else {
            // Cycle length must be larger than mid
            left = mid + 1;
        }
    }

    submit(s);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process();
    }

    return 0;
}

