using namespace std;

// Topological Sorting:
// Linear ordering of vertices such that for every directed edge u -> v, vertex u comes before v in the ordering.
// Uses: To resolve dependencies, schedule tasks, etc.
class Digraph {
    int numVertices; // Number of vertices
    list<int>* adjacencyList; // Adjacency list representation
public:
    Digraph(int V) {
        numVertices = V;
        adjacencyList = new list<int>[V];
    }

    void addConnection(int from, int to) {
        adjacencyList[from].push_back(to); // Add 'to' to 'from's list
    }

    // Helper method for topological sorting using DFS
    void topoSortHelper(int vertex, vector<bool>& seen, stack<int>& resultStack) {
        seen[vertex] = true;
        for (int adjacent : adjacencyList[vertex]) {
            if (!seen[adjacent]) {
                topoSortHelper(adjacent, seen, resultStack);
            }
        }
        resultStack.push(vertex);
    }

    // Perform topological sort on the graph
    void performTopologicalSort() {
        stack<int> outputStack;
        vector<bool> visited(numVertices, false);

        for (int index = 0; index < numVertices; ++index) {
            if (!visited[index]) {
                topoSortHelper(index, visited, outputStack);
            }
        }

        while (!outputStack.empty()) {
            cout << outputStack.top() << " ";
            outputStack.pop();
        }
    }

    ~Digraph() {
        delete[] adjacencyList;
    }
};

int main() {
    Digraph g(6);
    g.addConnection(5, 2);
    g.addConnection(5, 0);
    g.addConnection(4, 0);
    g.addConnection(4, 1);
    g.addConnection(2, 3);
    g.addConnection(3, 1);

    cout << "Topological Order of the given graph:\n";
    g.performTopologicalSort();
    return 0;
}

// Time Complexity: O(V + E) for topological sort using DFS
// Space Complexity: O(V) for the stack and visited array

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <string>
#include <iostream>
#include <vector>

int main() {
    std::cout << "=== coroutine example ===" << std::endl;
    sol::state lua_vm;
    std::vector<sol::coroutine> task_list;
    lua_vm.open_libraries(sol::lib::base, sol::lib::coroutine);
    sol::thread worker = sol::thread::create(lua_vm);

    lua_vm.set_function("spawn_task",
        [&worker, &task_list](
            sol::function func, sol::variadic_args args) {
            // Always retrieve the state from the worker thread
            sol::state_view worker_state = worker.state();

            // Store the coroutine to maintain its lifetime
            std::size_t idx = task_list.size();
            task_list.emplace_back(worker_state, func);
            sol::coroutine& coro_on_worker = task_list[idx];

            // Execute coroutine with arguments passed from another thread
            // sol handles argument transfer across threads via lua_xmove
            int result = coro_on_worker(args);
            std::cout << "Initial yield: " << result << std::endl;

            // Resume without new arguments (previous ones persist)
            coro_on_worker();
            std::cout << "Final run done: " << result << std::endl;
        });

    lua_vm.script(
        R"(
function worker_task(a, b, c)
	coroutine.yield(30)
	print(a, b, c)
end

function another_task(p, q)
	coroutine.yield(5)
	print(p, q)
end

spawn_task(worker_task, 100, 200, 300)
spawn_task(another_task, 7, 14)
)");

    std::cout << std::endl;
    return 0;
}

