#include <algorithm>
#include "IRsend.h"

// Global Cache constants
const uint16_t kGCMaxRepeats = 50;
const uint32_t kGCMinMicroseconds = 80;
const uint8_t kGCFreqPosition = 0;
const uint8_t kGCRepeatCountPos = kGCFreqPosition + 1;
const uint8_t kGCRepeatOffsetPos = kGCRepeatCountPos + 1;
const uint8_t kGCDataStartPos = kGCRepeatOffsetPos + 1;

#if SEND_GLOBALCACHE
/// Transmit an IR signal using shortened GlobalCache format.
/// Status: STABLE / Verified working.
/// @param[in] dataBuf Array of uint16_t containing the GlobalCache-encoded data.
/// @param[in] dataLen Number of elements in the dataBuf[] array.
/// @note Expects data starting with frequency (Hz), followed by emission count,
///  repeat start offset, then IR timing marks/spaces as period units.
///  Example: "sendir,1:1,1,38000,1,1,9,70,..." becomes [38000,1,1,9,70,...]
/// @see https://irdb.globalcache.com/Home/Database
void IRsend::sendGC(uint16_t dataBuf[], uint16_t dataLen) {
  uint16_t frequency = dataBuf[kGCFreqPosition];  // Frequency in Hz
  enableIROut(frequency);
  uint32_t period_us = calcUSecPeriod(frequency, false);

  // Limit number of repeats to avoid excessive transmission
  uint8_t repeatCount = std::min(
      dataBuf[kGCRepeatCountPos],
      static_cast<uint16_t>(kGCMaxRepeats)
  );

  for (uint8_t r = 0; r < repeatCount; r++) {
    uint16_t currentIndex = kGCDataStartPos;

    // For repetitions after the first, apply the repeat offset
    if (r > 0) {
      currentIndex += dataBuf[kGCRepeatOffsetPos] - 1;
    }

    // Process each timing entry
    for (; currentIndex < dataLen; currentIndex++) {
      // Convert period units to microseconds, enforcing minimum value
      uint32_t duration = std::max(
          dataBuf[currentIndex] * period_us,
          kGCMinMicroseconds
      );

      // Odd indices represent mark (LED on), even indices space (LED off)
      if (currentIndex & 1) {
        mark(duration);
      } else {
        space(duration);
      }
    }
  }

  // Ensure LED is turned off after transmission completes
  ledOff();
}
#endif

#include <iostream>

int main() {
    // Optimize I/O for faster input/output operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int distance;
    std::cin >> distance;

    // Continue until we reach the target (distance becomes 0)
    while (distance > 0) {
        int response;
        int updated_distance;

        // --- Attempt path with color 0 ---
        std::cout << "move 0" << std::endl;
        std::cin >> response;
        if (response == 1) {
            // Target reached, exit loop
            break;
        }

        std::cout << "query" << std::endl;
        std::cin >> updated_distance;
        if (updated_distance < distance) {
            // Progress made: move closer to target
            distance = updated_distance;
            continue;
        }

        // Backtrack after failed attempt with color 0
        std::cout << "move 0" << std::endl;
        std::cin >> response; // Result ignored as backtracking is confirmed

        // --- Attempt path with color 1 ---
        std::cout << "move 1" << std::endl;
        std::cin >> response;
        if (response == 1) {
            // Target reached, exit loop
            break;
        }

        std::cout << "query" << std::endl;
        std::cin >> updated_distance;
        if (updated_distance < distance) {
            // Progress made: move closer to target
            distance = updated_distance;
            continue;
        }

        // Backtrack after failed attempt with color 1
        std::cout << "move 1" << std::endl;
        std::cin >> response; // Result ignored as backtracking is confirmed

        // --- Infer correct path is color 2 ---
        // Since colors 0 and 1 both led away, color 2 must be correct
        std::cout << "move 2" << std::endl;
        std::cin >> response;
        if (response == 1) {
            // Target reached, exit loop
            break;
        }

        // Advance one step closer without querying since only color 2 remains
        distance--;
    }

    return 0;
}

