#include "test_ffb_common.h"
namespace FFBEngineTests {
TEST_CASE(test_issue_42_ffb_inversion_persistence_v2, "Configuration") {
    std::cout << "\nVerification: Issue #42 - Force Feedback Inversion State Retention Across Presets" << std::endl;
    FFBEngine engine;
    SetupEngine(engine);
    Config::LoadPresets();

    // Scenario A: Initialize with Invert enabled
    FFBEngineTestAccess::SetInvertForce(engine, true);
    ASSERT_TRUE(engine.m_invert_force);

    // Load "Default" configuration
    Config::ApplyPreset(0, engine);
    ASSERT_TRUE(engine.m_invert_force); // Must stay true

    // Load "T300" configuration (which previously forced it to true)
    int t300_position = -1;
    for(int idx=0; idx<(int)Config::presets.size(); idx++) {
        if(Config::presets[idx].name == "T300") {
            t300_position = idx;
            break;
        }
    }

    if(t300_position != -1) {
        Config::ApplyPreset(t300_position, engine);
        ASSERT_TRUE(engine.m_invert_force);
    }

    // Scenario B: Initialize with Invert disabled
    FFBEngineTestAccess::SetInvertForce(engine, false);
    ASSERT_FALSE(engine.m_invert_force);

    // Load "Default" configuration
    Config::ApplyPreset(0, engine);
    ASSERT_FALSE(engine.m_invert_force); // Must stay false!

    if(t300_position != -1) {
        Config::ApplyPreset(t300_position, engine);
        ASSERT_FALSE(engine.m_invert_force); // Must stay false!
    }

    // Scenario C: Confirm Preset::UpdateFromEngine does not store inversion state
    // Verified by absence of member variable storing this value.
    // Additional check: if we alter engine inversion, update preset, then revert engine inversion,
    // applying the preset should not restore the original inversion.
    Preset custom_preset("CustomTest", false);
    FFBEngineTestAccess::SetInvertForce(engine, true);
    custom_preset.UpdateFromEngine(engine);
    FFBEngineTestAccess::SetInvertForce(engine, false);
    custom_preset.Apply(engine);
    ASSERT_FALSE(engine.m_invert_force); // Apply must NOT set it back to true
}

TEST_CASE(test_issue_42_ffb_inversion_global_persistence_v2, "Configuration") {
    std::cout << "\nVerification: Issue #42 - Force Feedback Inversion Global Persistence (Save/Restore)" << std::endl;
    FFBEngine engine;
    SetupEngine(engine);
    std::string test_config_file = "test_issue_42_persistence_backup.ini";

    // Scenario A: Save state as True, Restore
    FFBEngineTestAccess::SetInvertForce(engine, true);
    Config::Save(engine, test_config_file);

    FFBEngine restored_engine;
    FFBEngineTestAccess::SetInvertForce(restored_engine, false); // Introduce inconsistency
    Config::Load(restored_engine, test_config_file);
    ASSERT_TRUE(restored_engine.m_invert_force);

    // Scenario B: Save state as False, Restore
    FFBEngineTestAccess::SetInvertForce(engine, false);
    Config::Save(engine, test_config_file);

    FFBEngine restored_engine2;
    FFBEngineTestAccess::SetInvertForce(restored_engine2, true); // Introduce inconsistency
    Config::Load(restored_engine2, test_config_file);
    ASSERT_FALSE(restored_engine2.m_invert_force);

    std::remove(test_config_file.c_str());
}
} // namespace FFBEngineTests

