using namespace std;

// Class to represent distance in feet and inches
class measurement {
	private:
		int ft, inc;
	public:
		void input();
		void display();
		measurement sum(measurement m);
};

void measurement::input() {
	cout << "Enter feet and inches: ";
	cin >> ft >> inc;
}

void measurement::display() {
	cout << ft << " feet " << inc << " inches" << endl;
}

measurement measurement::sum(measurement m) {
	measurement temp;
	temp.ft = ft + m.ft;
	temp.inc = inc + m.inc;
	if(temp.inc >= 12) {
		temp.ft = temp.ft + temp.inc / 12;
		temp.inc = temp.inc % 12;
	}
	return temp;
}

int main() {
	measurement d1, d2, d3;
	d1.input(); d2.input();
	d1.display(); d2.display();
	d3 = d1.sum(d2);
	d3.display();
	return 0;
}

