#include "stock.hpp"

namespace s11n_example {

/// Fetches stock market data from a remote server.
class client
{
public:
  /// Constructor initiates the asynchronous connection process.
  client(asio::io_context& context,
      const std::string& hostname, const std::string& port_number)
    : socket_connection_(context)
  {
    // Convert host name and service into a list of endpoints.
    asio::ip::tcp::resolver resolver(context);
    asio::ip::tcp::resolver::query query(hostname, port_number);
    asio::ip::tcp::resolver::iterator iterator = resolver.resolve(query);

    // Launch asynchronous connection to one of the resolved endpoints.
    asio::async_connect(socket_connection_.socket(), iterator,
        boost::bind(&client::on_connection_complete, this,
          asio::placeholders::error));
  }

  /// Callback invoked when the connect operation finishes.
  void on_connection_complete(const asio::error_code& error)
  {
    if (!error)
    {
      // Connection established successfully. Begin receiving stock data.
      socket_connection_.async_read(stock_data_,
          boost::bind(&client::on_data_received, this,
            asio::placeholders::error));
    }
    else
    {
      // Connection failed. Report the error and terminate.
      std::cerr << error.message() << std::endl;
    }
  }

  /// Callback invoked after reading stock information.
  void on_data_received(const asio::error_code& error)
  {
    if (!error)
    {
      // Display all received stock entries.
      for (std::size_t index = 0; index < stock_data_.size(); ++index)
      {
        std::cout << "Stock entry #" << index << "\n";
        std::cout << "  ticker: " << stock_data_[index].code << "\n";
        std::cout << "  company: " << stock_data_[index].name << "\n";
        std::cout << "  opening: " << stock_data_[index].open_price << "\n";
        std::cout << "  high: " << stock_data_[index].high_price << "\n";
        std::cout << "  low: " << stock_data_[index].low_price << "\n";
        std::cout << "  closing: " << stock_data_[index].last_price << "\n";
        std::cout << "  bid: " << stock_data_[index].buy_price << "\n";
        std::cout << "  bid_vol: " << stock_data_[index].buy_quantity << "\n";
        std::cout << "  ask: " << stock_data_[index].sell_price << "\n";
        std::cout << "  ask_vol: " << stock_data_[index].sell_quantity << "\n";
      }
    }
    else
    {
      std::cerr << error.message() << std::endl;
    }
    // No further operations scheduled — io_context will exit naturally.
  }

private:
  /// Network connection object.
  connection socket_connection_;
  /// Container for parsed stock records.
  std::vector<stock> stock_data_;
};

} // namespace s11n_example

int main(int argc, char* argv[])
{
  try
  {
    // Validate command-line arguments.
    if (argc != 3)
    {
      std::cerr << "Usage: client <host> <port>" << std::endl;
      return 1;
    }

    asio::io_context context;
    s11n_example::client app_client(context, argv[1], argv[2]);
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Exception: " << ex.what() << std::endl;
  }
  return 0;
}

