#define ROCP_REG_VERSION                                                                 \
    ROCPROFILER_REGISTER_COMPUTE_VERSION_2(RCCL_API_TRACE_VERSION_MAJOR,                 \
                                           RCCL_API_TRACE_VERSION_PATCH)
ROCPROFILER_REGISTER_DEFINE_IMPORT(rccl, ROCP_REG_VERSION)

#ifndef ROCP_REG_FILE_NAME
#    define ROCP_REG_FILE_NAME                                                           \
        ::std::string{ __FILE__ }                                                        \
            .substr(::std::string_view{ __FILE__ }.find_last_of('/') + 1)                \
            .c_str()
#endif

namespace rccl
{
namespace
{
auto&
get_api_table_storage()
{
    static auto _table = std::atomic<rcclApiFuncTable*>{ nullptr };
    return _table;
}

void
setup_profiler()
{
    static auto _base_api_table = rcclApiFuncTable{};
    initialize_rccl_api_table(&_base_api_table);

    get_api_table_storage().exchange(&_base_api_table);

    static auto _modified_api_table = rcclApiFuncTable{};
    copy_rccl_api_table(&_modified_api_table, &_base_api_table);

    void* _modified_api_table_ptr = static_cast<void*>(&_modified_api_table);

    rocprofiler_register_library_indentifier_t lib_id{};
    auto status =
        rocprofiler_register_library_api_table("rccl",
                                               &ROCPROFILER_REGISTER_IMPORT_FUNC(rccl),
                                               ROCP_REG_VERSION,
                                               &_modified_api_table_ptr,
                                               1,
                                               &lib_id);

    if(status == 0)
    {
        printf("[%s] rccl identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        auto* current_table = &_base_api_table;
        if(!get_api_table_storage().compare_exchange_strong(current_table,
                                                            &_modified_api_table))
        {
            std::cerr
                << "setup_profiler expected the API table to be the internal "
                   "implementation and yet it is not. something went wrong.\n";
            abort();
        }
    }
    else if(status != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "rccl library failed to register with rocprofiler-register: "
                  << rocprofiler_register_error_string(status) << "\n";
        exit(EXIT_FAILURE);
    }
}

void
ensure_registration()
{
    static auto _flag = std::atomic<bool>{ false };
    if(!_flag.load(std::memory_order_acquire))
    {
        using mutex_type     = std::recursive_mutex;
        using lock_type      = std::unique_lock<mutex_type>;
        static auto _init_flag  = std::once_flag{};
        static auto _lock_mutex = mutex_type{};

        auto lk = lock_type{ _lock_mutex, std::defer_lock };

        if(lk.owns_lock()) return;

        lk.lock();

        std::call_once(_init_flag, setup_profiler);

        _flag.exchange(true, std::memory_order_release);
    }
}
}  // namespace

rcclApiFuncTable*
fetch_api_table()
{
    ensure_registration();
    return get_api_table_storage().load(std::memory_order_relaxed);
}

void
initialize_rccl_hooks()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace rccl

extern "C" {
void
initialize_rccl_hooks(void)
{
    rccl::fetch_api_table()->ncclGetVersion_fn({});
}
}

