        writeWingSail(pWSail, Vector3d());
    }

    writeEndElement();
    writeEndDocument();
}

#include "Python.h"

/* Custom string formatting functions with safety checks.
   These wrappers provide consistent behavior across platforms by ensuring:
   - The output buffer is always null-terminated at str[size-1]
   - No more than 'size' bytes are written (including the terminator)
   - Return values follow a standardized convention regardless of underlying implementation
*/

int
PyOS_snprintf(char *buffer, size_t bufsize, const char *fmt, ...)
{
    int result;
    va_list args;
    va_start(args, fmt);
    result = PyOS_vsnprintf(buffer, bufsize, fmt, args);
    va_end(args);
    return result;
}

int
PyOS_vsnprintf(char *buffer, size_t bufsize, const char *fmt, va_list args)
{
    assert(buffer != NULL);
    assert(bufsize > 0);
    assert(bufsize <= (INT_MAX - 1));
    assert(fmt != NULL);

    int written;  /* Number of characters written, not counting '\0' */

    /* Validate input size to prevent integer overflow in return value */
    if (bufsize > INT_MAX - 1) {
        written = -666;
        goto Finish;
    }

#if defined(_MSC_VER)
    /* Microsoft Visual C++ specific handling */
    written = _vsnprintf(buffer, bufsize, fmt, args);
#else
    /* Standard C99 compliant vsnprintf */
    written = vsnprintf(buffer, bufsize, fmt, args);
#endif

Finish:
    /* Ensure null termination regardless of outcome */
    if (bufsize > 0) {
        buffer[bufsize - 1] = '\0';
    }
    return written;
}

#include "server.hpp"
#include "request.hpp"
#include "reply.hpp"

namespace http {
namespace server4 {

server::server(asio::io_context& context,
    const std::string& host, const std::string& service,
    boost::function<void(const request&, reply&)> handler)
  : request_handler_(handler)
{
  tcp::resolver resolver(context);
  asio::ip::tcp::endpoint target =
    *resolver.resolve(host, service).begin();
  acceptor_.reset(new tcp::acceptor(context, target));
}

// Enable the pseudo-keywords reenter, yield and fork.
#include <asio/yield.hpp>

void server::operator()(asio::error_code err, std::size_t bytes_transferred)
{
  // In this example we keep the error handling code in one place by
  // hoisting it outside the coroutine. An alternative approach would be to
  // check the value of err after each yield for an asynchronous operation.
  if (!err)
  {
    // On reentering a coroutine, control jumps to the location of the last
    // yield or fork. The argument to the "reenter" pseudo-keyword can be a
    // pointer or reference to an object of type coroutine.
    reenter (this)
    {
      // Loop to accept incoming connections.
      do
      {
        // Create a new socket for the next incoming connection.
        socket_.reset(new tcp::socket(acceptor_->get_executor().context()));
        // Accept a new connection. The "yield" pseudo-keyword saves the current
        // line number and exits the coroutine's "reenter" block. We use the
        // server coroutine as the completion handler for the async_accept
        // operation. When the asynchronous operation completes, the io_context
        // invokes the function call operator, we "reenter" the coroutine, and
        // then control resumes at the following line.
        yield acceptor_->async_accept(*socket_, *this);
        // We "fork" by cloning a new server coroutine to handle the connection.
        // After forking we have a parent coroutine and a child coroutine. Both
        // parent and child continue execution at the following line. They can
        // be distinguished using the functions coroutine::is_parent() and
        // coroutine::is_child().
        fork server(*this)();
        // The parent continues looping to accept the next incoming connection.
        // The child exits the loop and processes the connection.
      } while (is_parent());

      // Create the objects needed to receive a request on the connection.
      buffer_.reset(new boost::array<char, 8192>);
      request_.reset(new request);

      // Loop until a complete request (or an invalid one) has been received.
      do
      {
        // Receive some more data. When control resumes at the following line,
        // the err and bytes_transferred parameters reflect the result of the asynchronous
        // operation.
        yield socket_->async_read_some(asio::buffer(*buffer_), *this);
        // Parse the data we just received.
        boost::tie(valid_request_, boost::tuples::ignore)
          = request_parser_.parse(*request_,
              buffer_->data(), buffer_->data() + bytes_transferred);
        // An indeterminate result means we need more data, so keep looping.
      } while (boost::indeterminate(valid_request_));

      // Create the reply object that will be sent back to the client.
      reply_.reset(new reply);
      if (valid_request_)
      {
        // A valid request was received. Call the user-supplied function object
        // to process the request and compose a reply.
        request_handler_(*request_, *reply_);
      }
      else
      {
        // The request was invalid.
        *reply_ = reply::stock_reply(reply::bad_request);
      }

      // Send the reply back to the client.
      yield asio::async_write(*socket_, reply_->to_buffers(), *this);

      // Initiate graceful connection closure.
      socket_->shutdown(tcp::socket::shutdown_both, err);
    }
  }
  // If an error occurs then the coroutine is not reentered. Consequently, no
  // new asynchronous operations are started. This means that all shared_ptr
  // references will disappear and the resources associated with the coroutine
  // will be destroyed automatically after this function call returns.
}

// Disable the pseudo-keywords reenter, yield and fork.
#include <asio/unyield.hpp>

} // namespace server4
} // namespace http

#include <Application.h>
#include <Bitmap.h>
#include <BitmapStream.h>
#include <File.h>
#include <TranslationUtils.h>
#include <TranslatorRoster.h>
#include <iostream>
#include <cstring>

class ImageExporterApp : public BApplication
{
public:
	ImageExporterApp(int argc, char** argv)
		:
		BApplication("application/x-vnd.image-exporter"),
		fArgc(argc),
		fArgv(argv)
	{
	}

	void ReadyToRun() override
	{
		if (fArgc < 2) {
			std::cout << "Usage: " << fArgv[0] << " <source_image>" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		const char* sourcePath = fArgv[1];

		// Load the input image file
		BBitmap* bitmap = BTranslationUtils::GetBitmapFile(sourcePath);
		if (!bitmap) {
			std::cout << "Error: Unable to load image from " << sourcePath << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Wrap the bitmap in a stream for translation
		BBitmapStream bitmapStream(bitmap);

		// Access the default translator roster
		BTranslatorRoster* translatorRoster = BTranslatorRoster::Default();
		if (!translatorRoster) {
			std::cout << "Error: Could not access translator roster" << std::endl;
			delete bitmap;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Export as JPEG
		BFile jpegOutput("output_image.jpg",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
		status_t resultJPEG = translatorRoster->Translate(&bitmapStream, nullptr, nullptr, &jpegOutput, B_JPEG_FORMAT);
		if (resultJPEG != B_OK) {
			std::cout << "JPEG export failed: " << strerror(resultJPEG) << std::endl;
		} else {
			std::cout << "JPEG saved successfully: output_image.jpg" << std::endl;
		}

		// Reset stream position for PNG export
		bitmapStream.Seek(0, SEEK_SET);

		// Export as PNG
		BFile pngOutput("output_image.png",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
		status_t resultPNG = translatorRoster->Translate(&bitmapStream, nullptr, nullptr, &pngOutput, B_PNG_FORMAT);
		if (resultPNG != B_OK) {
			std::cout << "PNG export failed: " << strerror(resultPNG) << std::endl;
		} else {
			std::cout << "PNG saved successfully: output_image.png" << std::endl;
		}

		delete bitmap;
		PostMessage(B_QUIT_REQUESTED); // Terminate application
	}

private:
	int fArgc;
	char** fArgv;
};

int main(int argc, char** argv)
{
	ImageExporterApp app(argc, argv);
	app.Run();
	return 0;
}

