#include <iostream>
#include <istream>
#include <ostream>
#include <string>
#include <asio/ip/tcp.hpp>
using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cout << "Usage: http_client <server> <path>\n";
      std::cout << "Example:\n";
      std::cout << "  http_client www.boost.org /LICENSE_1_0.txt\n";
      return 1;
    }

    tcp::iostream connection_stream;
    // Set timeout for the entire operation to 60 seconds
    connection_stream.expires_after(std::chrono::seconds(60));

    // Connect to the specified server on the HTTP port
    connection_stream.connect(argv[1], "http");

    if (!connection_stream)
    {
      std::cout << "Unable to connect: " << connection_stream.error().message() << "\n";
      return 1;
    }

    // Send HTTP GET request with required headers
    connection_stream << "GET " << argv[2] << " HTTP/1.0\r\n";
    connection_stream << "Host: " << argv[1] << "\r\n";
    connection_stream << "Accept: */*\r\n";
    connection_stream << "Connection: close\r\n\r\n";

    // Read and validate HTTP response
    std::string version_str;
    connection_stream >> version_str;

    unsigned int status_code_val;
    connection_stream >> status_code_val;

    std::string status_text;
    std::getline(connection_stream, status_text);

    if (!connection_stream || version_str.substr(0, 5) != "HTTP/")
    {
      std::cout << "Invalid response\n";
      return 1;
    }

    if (status_code_val != 200)
    {
      std::cout << "Response returned with status code " << status_code_val << "\n";
      return 1;
    }

    // Output response headers until blank line
    std::string header_line;
    while (std::getline(connection_stream, header_line) && header_line != "\r")
      std::cout << header_line << "\n";

    std::cout << "\n";

    // Output remaining content (response body)
    std::cout << connection_stream.rdbuf();
  }
  catch (std::exception& ex)
  {
    std::cout << "Exception: " << ex.what() << "\n";
  }

  return 0;
}

