#include <iostream>
#include <string>
#include <algorithm> // for reverse function
using namespace std;

int main() {
    // Declare a string variable
    string text = "hello world";
    // Display the initial string
    cout << "Text: " << text << endl;  // Outputs: hello world

    // Strings are dynamic and can change size dynamically, unlike fixed-size char arrays
    string text2 = "C++ programming is exciting!";
    cout << text + " " + text2 << endl; // Concatenates strings: "hello world C++ programming is exciting!"
    cout << (text == text2) << endl; // Outputs 0 (false), since strings differ — not possible with char arrays
    cout << (text < text2) << endl; // Outputs 1 (true), lexicographical comparison holds here
    cout << text.length() << endl; // Outputs 11, the number of characters in "hello world"

    // Read a single word from user input
    string inputWord;
    cout << "Enter a word: ";
    cin >> inputWord; // Reads only up to the first whitespace
    cout << "You typed: " << inputWord << endl;

    // Clear any leftover newline in the input buffer
    cin.ignore(); // Ignore the newline left by previous cin

    // Read a full line including spaces
    string sentence;
    cout << "Enter a phrase with spaces: ";
    getline(cin, sentence); // Captures entire line including spaces
    cout << "You entered: " << sentence << endl;

    // Print each character using index-based loop
    for (int idx = 0; idx < text.length(); idx++) {
        cout << text[idx]; // Accesses each character individually
    }
    cout << endl; // Newline after printing all chars

    // Print each character using range-based for loop
    for(char ch : text2){
        cout << ch; // Iterates over each character in text2
    }
    cout << endl; // Newline after printing all chars

    // Reverse the sentence string in-place
    reverse(sentence.begin(), sentence.end()); // Reverses the content of sentence
    cout << "Reversed phrase: " << sentence << endl; // Displays reversed version

    return 0;
}

#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

int main() {
    // Initialize the HIP runtime
    if (auto result = hipInit(0); result != hipSuccess) {
        std::cerr << "HIP runtime initialization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Retrieve the per-thread default stream
    hipStream_t worker_stream = hipStreamPerThread;

    // Allocate device memory using the stream
    void* device_buffer = nullptr;
    std::size_t buffer_size = 2048;  // Changed from 1024 to 2048 bytes

    if (auto err = hipMalloc(&device_buffer, buffer_size); err != hipSuccess) {
        std::cerr << "Device memory allocation failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Asynchronously initialize memory using the stream
    if (auto err = hipMemsetAsync(device_buffer, 0, buffer_size, worker_stream); err != hipSuccess) {
        std::cerr << "Memory initialization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Ensure all operations in the stream are completed
    if (auto err = hipStreamSynchronize(worker_stream); err != hipSuccess) {
        std::cerr << "Stream synchronization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Release the allocated device memory
    if (auto err = hipFree(device_buffer); err != hipSuccess) {
        std::cerr << "Failed to deallocate device memory." << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "All operations completed successfully with per-thread stream." << std::endl;
    return EXIT_SUCCESS;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    unsigned int target;
    std::cin >> target;

    if (target == 1) {
        std::cout << 1 << std::endl;
        std::cout << "HALT PUSH 1 GOTO 1" << std::endl;
        return 0;
    }

    unsigned int steps = (target - 3) / 2 + 1;
    std::vector<int> binary_digits;

    if (steps > 0) {
        unsigned int current = steps;
        while (current > 0) {
            binary_digits.push_back(current % 2);
            current /= 2;
        }
    } else if (steps == 0) {
        // Special case for when steps equals zero
        // This handles edge scenarios in the problem domain
        binary_digits.push_back(0);
    }

    // Ensure we have proper bit representation
    if (binary_digits.empty() && steps > 0) {
        int required_bits = static_cast<int>(std::log2(steps)) + 1;
        unsigned int temp_val = steps;
        for (int pos = 0; pos < required_bits; ++pos) {
            binary_digits.push_back(temp_val % 2);
            temp_val /= 2;
        }
    }

    // Reverse to get MSB first order
    std::reverse(binary_digits.begin(), binary_digits.end());

    // Handle remaining edge cases
    if (steps > 0 && binary_digits.empty()) {
        binary_digits.push_back(1);
    }

    int depth = binary_digits.size();
    if (steps == 0) depth = 0;
    int total_instructions = depth + 3;

    std::cout << total_instructions << std::endl;

    // Initial setup instruction
    std::cout << "POP 1 GOTO 2 PUSH 1 GOTO 2" << std::endl;

    // Process each bit in sequence
    for (int idx = 0; idx < depth; ++idx) {
        int instruction_number = idx + 2;
        if (binary_digits[idx] == 1) {
            std::cout << "HALT PUSH 1 GOTO " << instruction_number + 1 << std::endl;
        } else {
            std::cout << "POP 1 GOTO " << depth + 2 << " PUSH 2 GOTO " << instruction_number + 1 << std::endl;
        }
    }

    // Return mechanism instruction
    std::cout << "POP 1 GOTO 2 PUSH 2 GOTO " << depth + 2 << std::endl;

    // Final termination instruction
    std::cout << "HALT PUSH 99 GOTO " << depth + 2 << std::endl;

    return 0;
}

#include "rslcpp/rslcpp.hpp"
#include <limits>
#include <rslcpp_exceptions/exceptions.hpp>

namespace rslcpp
{
exit_code_t run_simulation(int argc, char ** argv, Job::SharedPtr simulation_job)
{
  // Acquire the time delay backend instance
  time_delay::CallbackBackend & time_backend = time_delay::CallbackBackend::getInstance();

  // Configure RCLCPP initialization options
  rclcpp::InitOptions init_opts;

  // Initialize the ROS2 context
  rclcpp::init(argc, argv, init_opts);

  // Retrieve all nodes from the job
  auto node_list = simulation_job->create_and_get_nodes();

  // Validate that each node is configured to use simulated time
  for (auto & node : node_list) {
    if (!node->get_parameter("use_sim_time").as_bool()) {
      throw exceptions::NodeNotUsingSimTime(node->get_fully_qualified_name());
    }
  }

  // Setup executor with global context
  auto default_context = rclcpp::contexts::get_global_default_context();
  rclcpp::ExecutorOptions exec_opts;
  exec_opts.context = default_context;

  rclcpp::experimental::executors::EventsExecutor executor{
    std::make_unique<rclcpp::experimental::executors::SimpleEventsQueue>(), false,
    exec_opts};

  // Register all nodes with the executor
  for (auto & node : node_list) {
    executor.add_node(node);
  }

  // Initialize simulation time
  auto current_sim_time = simulation_job->get_initial_time();

  // Main simulation loop: continue while job is active and ROS2 context is valid
  while (!simulation_job->get_finished() && rclcpp::ok(default_context)) {
    // Update time delay backend with current simulation time
    time_backend.set_time(current_sim_time.nanoseconds());

    // Synchronize all node clocks to current simulation time
    for (auto & node : node_list) {
      rslcpp::set_clock(current_sim_time, node->get_clock());
    }

    // Process any ready delayed callbacks
    time_backend.execute_ready_delayed_callables();

    // Execute all pending callbacks using a very large timeout
    executor.spin_all(
      std::chrono::hours(
        200 * 365 * 24));  // ~200 years ensures all callbacks are processed

    // Determine next event time
#ifdef RSLCPP__CUSTOM__RCLCPP
    std::chrono::nanoseconds next_timer_time = executor.get_time_until_next_timer();
#else
    // Fallback to 1 ms if custom rclcpp not available
    std::chrono::nanoseconds next_timer_time = std::chrono::milliseconds(1);
#endif

    // Check if no more timers scheduled
    if (next_timer_time == std::chrono::nanoseconds::max()) {
      break;  // End simulation
    }

    // Get next delayed callback time
    rslcpp::time_delay::Duration next_delayed_callback_time =
      time_backend.get_time_until_next_delayed_callable();

    // Compute minimum time step to next event
    rclcpp::Duration time_step_duration =
      (next_delayed_callback_time < next_timer_time.count())
        ? std::chrono::nanoseconds(next_delayed_callback_time)
        : next_timer_time;

    // Advance simulation clock
    current_sim_time += time_step_duration;
  }

  // Retrieve final exit code and shut down
  auto final_exit_code = simulation_job->get_exit_code();
  rclcpp::shutdown();
  return final_exit_code;
}
