void XmlBtPolarWriter::writeBtPolarData(BoatPolar const *boatPolar)
{
   QString tempStr;

   writeStartElement("Polar");
   {
       writeTextElement("Polar_Name", boatPolar->name());
       writeComment("For scripts: if the boat's name is left blank, the analysis will be associated to all available boats");
       writeTextElement("Boat_Name", boatPolar->boatName());
       writeComment("Boat polars are necessarily of the control type");
       writeTheStyle(boatPolar->theStyle());
       writeTextElement("Method", Polar3d::analysisMethod(boatPolar->analysisMethod()));

       writeStartElement("Reference_Dimensions");
       {
           writeComment("Available options are AUTO and CUSTOM");
           writeTextElement("Reference_Dimensions", Polar3d::referenceDimension(boatPolar->referenceDim()));
           writeComment("The following fields are required only if dimensions are set to CUSTOM");
           writeTextElement("Reference_Area", QString::asprintf("%11.5f", boatPolar->referenceArea()*Units::m2toUnit()));
           writeTextElement("Reference_Chord_Length", QString::asprintf("%11.5f", boatPolar->referenceChordLength()*Units::mtoUnit()));
       }
       writeEndElement();

       writeWakeData(*boatPolar);

       tempStr = QString::asprintf("%g, %g, %g", boatPolar->CoG().x*Units::mtoUnit(), 
                                   boatPolar->CoG().y*Units::mtoUnit(), 
                                   boatPolar->CoG().z*Units::mtoUnit());
       writeTextElement("CoG", tempStr);

       writeStartElement("Wind_gradient");
       {
           writeWindSpline(boatPolar->windSpline());
       }
       writeEndElement();

       writeFluidProperties(boatPolar->viscosity(), boatPolar->density());

       if(boatPolar->hasExtraDrag())
           writeExtraDrag(boatPolar->extraDragList());

       writeComment("Min and max values separated by a comma ,");
       writeTextElement("Boat_Speed", QString::asprintf(" %g, %g", boatPolar->VBtMin(), boatPolar->VBtMax()));
       writeTextElement("TWS",        QString::asprintf(" %g, %g", boatPolar->qInfMin(), boatPolar->qInfMax()));
       writeTextElement("TWA",        QString::asprintf(" %g, %g", boatPolar->twaMin(), boatPolar->twaMax()));
       writeTextElement("Phi",        QString::asprintf(" %g, %g", boatPolar->phiMin(), boatPolar->phiMax()));
       writeTextElement("Ry",         QString::asprintf(" %g, %g", boatPolar->RyMin(), boatPolar->RyMax()));

       writeStartElement("SailAngles");
       {
           for(int sailIndex=0; sailIndex<boatPolar->sailAngleSize(); sailIndex++)
           {
               QString tempStr, elementName;
               elementName = QString::asprintf("Sail_%d", sailIndex+1);
               tempStr = QString::asprintf("%.3f,  %.3f", boatPolar->sailAngleMin(sailIndex), boatPolar->sailAngleMax(sailIndex));
               writeTextElement(elementName, tempStr);
           }
       }
       writeEndElement();
   }
   writeEndElement();
}

void XmlBtPolarWriter::writeWindSpline(BSpline const &spline)
{
    writeTextElement("Degree", QString::asprintf("%d", spline.degree()));

    int pointCount = spline.ctrlPointCount();
    for(int i=0; i<pointCount; i++)
    {
        writeTextElement("Point", QString::asprintf("%g, %g", spline.controlPoint(i).x, spline.controlPoint(i).y)); // meters only
    }
}

#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    // Find the maximum absolute sum of any subarray
    int maxAbsoluteSum(std::vector<int>& values) {
        int length = values.size();
        int currentMin = values[0];
        int currentMax = 0;
        int positiveRunning = 0;
        int negativeRunning = 0;

        // First pass: find maximum subarray sum using Kadane's algorithm
        for(int idx = 0; idx < length; idx++) {
            positiveRunning = positiveRunning + values[idx];
            currentMax = std::max(positiveRunning, currentMax);
            if(positiveRunning < 0) {
                positiveRunning = 0;
            }
        }

        // Second pass: find minimum subarray sum
        for(int idx = 0; idx < length; idx++) {
            negativeRunning = negativeRunning + values[idx];
            currentMin = std::min(negativeRunning, currentMin);
            if(negativeRunning > 0) {
                negativeRunning = 0;
            }
        }

        // Return the maximum of the absolute minimum and maximum sums
        int result = std::max(currentMax, std::abs(currentMin));
        return result; 
    }
};

