namespace engine::store::filter::filesys::filesys {
//-----------------------------------------------------------------
// Register the filesys protocol config with the Url system. This
// enables usage of Url::toPath(...), Url::toUrl(...), etc. Note that
// we only supply the osPath as the service manager handles
// generic toPath, toUrl and capability registration
//-----------------------------------------------------------------
static url::UrlConfig urlConfig{
    {//------------------------------------------------------------
     /// @brief
     ///	Specify the protocol identifier
     //------------------------------------------------------------
     .protocol = Type,
     //-------------------------------------------------------------
     /// @brief
     ///	This function transforms a path (with prefix stripped) into
     ///	an absolute file system path suitable for OS operations.
     ///
     ///	For Linux:
     ///		input: ("usr", "dir", "file.txt")
     ///		output: /usr/dir/file.txt
     ///
     ///	For Windows:
     ///		input: ("C:", "dir", "file.txt")
     ///		output: C:\dir\file.txt
     ///
     ///	@param[in] sourceUrl
     ///		The URL object containing the path components
     ///	@param[out] destinationPath
     ///		Receives the platform-specific string representation
     ///	@returns
     ///		Error code indicating success or failure
     //-------------------------------------------------------------
     .osPath = [](const Url &sourceUrl, Text &destinationPath) -> Error {
         // Extract the internal path representation
         Path intermediatePath;
         if (auto errorCode = urlConfig.toPath(sourceUrl, intermediatePath)) return errorCode;
#ifdef ROCKETRIDE_PLAT_WIN
         // On Windows, directly use the platform-specific path string
         destinationPath = intermediatePath.plat();
#else
         // On Unix-like systems, ensure absolute paths start with "/"
         // since URLs may omit the leading slash
         if (!intermediatePath.isAbsolute()) {
             destinationPath = "/" + intermediatePath.plat();
         } else {
             destinationPath = intermediatePath.plat();
         }
#endif
         return {};
     }}};
}  // namespace engine::store::filter::filesys::filesys

