#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>

using asio::bind_executor;
using asio::dispatch;
using asio::get_associated_executor;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;

// Asynchronously reads a single line from an input stream
template <typename CompletionToken>
void async_read_line(std::istream& input_stream, CompletionToken token)
{
  // Create work guard for the handler's associated executor
  auto guard = make_work_guard(token);

  // Schedule asynchronous operation using post
  post([input_stream, guard, token=std::move(token)]() mutable
      {
        std::string buffer;
        std::getline(input_stream, buffer);

        // Execute handler through the associated executor
        dispatch(guard.get_executor(),
            [buffer=std::move(buffer), token=std::move(token)]() mutable
            {
              token(std::move(buffer));
            });
      });
}

// Recursively reads multiple lines until an empty line is encountered
template <typename CompletionToken>
void async_read_lines(std::istream& input_stream, std::string accumulated, CompletionToken token)
{
  // Extract the final handler's executor
  auto executor = get_associated_executor(token);

  // Use bound executor for all operations in the chain
  async_read_line(input_stream,
      bind_executor(executor,
        [&input_stream, text=std::move(accumulated), token=std::move(token)]
        (std::string result) mutable
        {
          if (result.empty())
            token(text);
          else
            async_read_lines(input_stream, text + result + "\n", std::move(token));
        }));
}

int main()
{
  thread_pool worker_pool;
  std::cout << "Please enter text, end with an empty line:\n";

  async_read_lines(std::cin, "",
      bind_executor(worker_pool, [](std::string content)
        {
          std::cout << "Collected lines:\n" << content << "\n";
        }));

  worker_pool.join();
}

#include <iostream>
