// Hotkey detection macro: returns 1 if key is pressed, 0 otherwise
#define IS_KEY_DOWN(VK_CODE) ((GetAsyncKeyState(VK_CODE) & 0x8000) ? 1 : 0)

int main() {
    runtime::RuntimeContext appContext;

    // Initialize the runtime with configuration file
    if (!appContext.initialize("settings.ini")) {
        return 1;
    }

    std::cout << std::endl;

    engine::FishEngine gameEngine(appContext);

    // Handle pause/resume functionality when configured
    if (appContext.config().shouldPause) {
        std::cout << "Press Tab to toggle pause/resume, Esc to quit" << std::endl;

        std::atomic<bool> exitFlag{ false };

        std::thread inputHandler([&gameEngine, &exitFlag]() {
            while (!exitFlag.load()) {
                // Check for Tab key to toggle pause state
                if (IS_KEY_DOWN(VK_TAB)) {
                    gameEngine.togglePause();

                    if (gameEngine.isPaused()) {
                        std::cout << "Game Paused" << std::endl;
                    } else {
                        std::cout << "Game Resumed" << std::endl;
                    }
                }

                // Check for Escape key to stop execution
                if (IS_KEY_DOWN(VK_ESCAPE)) {
                    std::cout << "Shutting down..." << std::endl;
                    gameEngine.stop();
                    break;
                }

                Sleep(100);  // Small delay to reduce CPU usage
            }
        });

        // Run the main game loop
        gameEngine.executeLoop();

        // Signal thread to exit and wait for completion
        exitFlag.store(true);
        if (inputHandler.joinable()) {
            inputHandler.join();
        }
    } else {
        // Run without hotkey handling
        gameEngine.executeLoop();
    }

    return 0;
}

