// Structure definition for Pointer to Member Function representation
typedef struct PTMF
{
    long this_delta;  // adjustment to the this pointer
    long vtbl_offset; // index offset in virtual function table (negative value indicates non-virtual)
    union
    {
        void* func_addr;    // address of static or non-virtual function
        long ventry_offset; // entry index within virtual function table
    } func_data;
} PTMF;

// Null PTMF constant initialization
const PTMF __ptmf_null = { 0, 0, { 0 } };

/* clang-format off */
asm void __ptmf_test(register PTMF* ptmf) {
  nofralloc
  lwz r5, PTMF.this_delta(ptmf)
  lwz r6, PTMF.vtbl_offset(ptmf)
  lwz r7, PTMF.func_data(ptmf)
  li r3, 1
  cmpwi cr0, r5, 0
  cmpwi cr6, r6, 0
  cmpwi cr7, r7, 0
  bnelr cr0
  bnelr cr6
  bnelr cr7
  li r3, 0
  blr
}
asm void __ptmf_scall(...) {
  nofralloc
  lwz r0, PTMF.this_delta(r12)
  lwz r11, PTMF.vtbl_offset(r12)
  lwz r12, PTMF.func_data(r12)
  add r3, r3, r0
  cmpwi r11, 0
  blt @1
  lwzx r12, r3, r12
  lwzx r12, r12, r11
@1 
  mtctr r12
  bctr
}
