#include <iostream>
#include <boost/array.hpp>
#include <asio.hpp>

using asio::ip::udp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: client <host>" << std::endl;
      return 1;
    }

    asio::io_context context;
    udp::resolver resolver(context);
    udp::endpoint target_endpoint =
      *resolver.resolve(udp::v4(), argv[1], "daytime").begin();

    udp::socket sock(context);
    sock.open(udp::v4());

    boost::array<char, 1> request_buffer = {{ 0 }};
    sock.send_to(asio::buffer(request_buffer), target_endpoint);

    boost::array<char, 128> response_buffer;
    udp::endpoint source_endpoint;
    size_t bytes_received = sock.receive_from(
        asio::buffer(response_buffer), source_endpoint);

    std::cout.write(response_buffer.data(), bytes_received);
  }
  catch (std::exception& err)
  {
    std::cerr << err.what() << std::endl;
  }

  return 0;
}

#include "StopCmd.h"
#include <argparse.hpp>
