#include "TuringConfig.h"
#include "LockFile.h"
#include "SystemEventHandler.h"
#include "LogSetup.h"

using namespace db;

StopCmd::StopCmd()
    : _argParser("stop") {
}

StopCmd::~StopCmd() = default;

int StopCmd::execute() {
    LogSetup::setupLogConsole(); // Only initialize the console log
                                 // Since the logfile is not owned by this process
                                 // (not owning lock file)

    TuringConfig settings;
    if (!_rootDir.empty()) {
        settings.setTuringDirectory(fs::Path {_rootDir});
    }
    _rootDir = settings.getTuringDir().get();

    const fs::Path socketPath = settings.getSocketPath();
    if (!socketPath.exists()) {
        spdlog::error("No TuringDB instance seems to be running at {}", _rootDir);
        return EXIT_FAILURE;
    }

    // Issue a STOP request to the server through the Unix socket
    if (!SystemEventHandler::requestStop(socketPath)) {
        spdlog::error("Could not stop the TuringDB instance at {}", _rootDir);
        return EXIT_FAILURE;
    }

    LockFile lockFile;
    lockFile.setPath(settings.getLockFilePath());

    // Wait for the lock file to be released
    // It can take a while if the server was using a load of RAM, or was
    // running long queries
    if (!lockFile.waitUnlock(_waitTime)) {
        spdlog::error("TuringDB at {} did not stop within {} ms", _rootDir, _waitTime);
        return EXIT_FAILURE;
    }

    spdlog::info("Stopped TuringDB instance at {}", _rootDir);
    return EXIT_SUCCESS;
}

std::unique_ptr<StopCmd> StopCmd::create() {
    std::unique_ptr<StopCmd> cmd {new StopCmd()};
    cmd->initialize();
    return cmd;
}

void StopCmd::initialize() {
    _argParser.add_description("Terminates the TuringDB server");
    _argParser.add_argument("-turing-dir")
        .metavar("path")
        .help("Root Turing directory")
        .store_into(_rootDir);
    _argParser.add_argument("-timeout", "-t")
        .metavar("ms")
        .help("Milliseconds to wait for the process to release its lock (default: 3000)")
        .store_into(_waitTime);
}

