    {
        VERIFY(!Monadic::test_safe_div_zero.has_value());
        std::cout << "Verification 5 (safe_div 10 0): SUCCESS" << std::endl;
    }

    // Verification block 6: chained bind ok
    {
        VERIFY(Monadic::test_chain_ok.has_value());
        VERIFY(*Monadic::test_chain_ok == 3);
        std::cout << "Verification 6 (div_then_sub 20 4 2): SUCCESS" << std::endl;
    }

    // Verification block 7: chained bind fail
    {
        VERIFY(!Monadic::test_chain_fail.has_value());
        std::cout << "Verification 7 (div_then_sub 20 0 2): SUCCESS" << std::endl;
    }

    if (testResult == 0) {
        std::cout << "\nAll monadic verifications passed!" << std::endl;
    } else {
        std::cout << "\n" << testResult << " verification(s) failed!" << std::endl;
    }

    return testResult;
}

#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sm/vvec>

int main() {
    // Initialize a visualization window with specified dimensions and title
    mplot::Visual scene(1024, 768, "Created using mplot::GraphVisual");

    // Instantiate a GraphVisual for double-precision data, positioned at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));

    // Essential setup: link the model to the visualizer and register callbacks
    scene.bindmodel(graph);

    // Prepare x-axis data points using vvec (vector with vectorized operations)
    sm::vvec<double> abscissa;

    // Generate 14 evenly spaced points from -0.5 to 0.8
    abscissa.linspace(-0.5, 0.8, 14);

    // Define the function y = x^3 and assign data to the graph
    graph->setdata(abscissa, abscissa.pow(3));

    // Precompute OpenGL vertex data for rendering
    graph->finalize();

    // Transfer ownership of the graph model to the visual scene
    scene.addVisualModel(graph);

    // Display the scene and wait for user to exit (Ctrl-q)
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' destructor runs
    return 0;
}

