#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>

// Global variables for competitive programming convenience
int size_arr;
std::vector<int> arr;
std::vector<int> pos_map;
std::vector<std::pair<int, int>> operations;

// Function to execute an operation and record it
void execute_operation(int a, int b) {
    if (a <= 0 || b <= 0 || a + b >= size_arr) {
        return; // Invalid case — should not occur in correct usage
    }
    operations.push_back({a, b});

    std::vector<int> first_part, second_part, third_part;
    first_part.assign(arr.begin(), arr.begin() + a);
    second_part.assign(arr.begin() + a, arr.end() - b);
    third_part.assign(arr.end() - b, arr.end());

    arr.clear();
    arr.insert(arr.end(), third_part.begin(), third_part.end());
    arr.insert(arr.end(), second_part.begin(), second_part.end());
    arr.insert(arr.end(), first_part.begin(), first_part.end());

    for (int idx = 0; idx < size_arr; ++idx) {
        pos_map[arr[idx]] = idx + 1;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> size_arr;
    arr.resize(size_arr);
    pos_map.resize(size_arr + 1);

    for (int i = 0; i < size_arr; ++i) {
        std::cin >> arr[i];
        pos_map[arr[i]] = i + 1;
    }

    if (size_arr == 3) {
        // Special handling for size 3: reverse if lexicographically smaller
        std::vector<int> reversed_arr = arr;
        std::reverse(reversed_arr.begin(), reversed_arr.end());
        if (reversed_arr < arr) {
            execute_operation(1, 1);
        }
    } else {
        // General case: sort permutation using allowed operations
        for (int target_value = 1; target_value <= size_arr; ++target_value) {
            int current_pos = pos_map[target_value];
            if (current_pos == target_value) {
                continue;
            }

            // Bring element to position 1 via two operations
            if (current_pos > 1) {
                execute_operation(current_pos - 1, 1);
                execute_operation(size_arr - 1, 1);
            }

            // Move element from position 1 to its correct position
            if (target_value > 1) {
                execute_operation(1, size_arr - target_value);
                execute_operation(target_value, 1);
            }
        }
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

