#include <iostream>
#include <vector>
using namespace std;

// Global variables to store the array size and contents
int size;
vector<int> data;

// Recursive function to process range [left, right]
void process(int left, int right) {
    if (left > right) return;

    // Skip already filled positions from both ends
    while (left <= right && data[left] != 0) left++;
    while (right >= left && data[right] != 0) right--;

    if (left > right) return;

    // Query the current segment
    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    // Handle invalid response
    if (value == -1) exit(0);

    // If all elements in range are the same value
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) data[idx] = value;
        return;
    }

    int center = (left + right) / 2;

    // Process left half first
    process(left, center);

    // Use query information to fill known values in right half
    if (data[center] == value) {
        int count = 0;
        int index = center;

        // Count occurrences of 'value' in left segment [left, center]
        while (index >= left && data[index] == value) {
            count++;
            index--;
        }

        // Fill remaining occurrences in right segment starting after center
        int remaining = frequency - count;
        for (int j = 1; j <= remaining; ++j) {
            if (center + j <= size) data[center + j] = value;
        }
    }

    // Process right half
    process(center + 1, right);
}

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> size) {
        data.resize(size + 1, 0); // 1-based indexing

        process(1, size);

        cout << "! ";
        for (int i = 1; i <= size; ++i) {
            cout << data[i] << (i == size ? "" : " ");
        }
        cout << endl;
    }

    return 0;
}

