// Check equality of two boolean values using nested conditions
bool BoolDecBde::eqb_dec(const bool val1, const bool val2) {
  if (Bool::bool_dec(val1, val2)) {
    return true;
  } else {
    return false;
  }
}

// Determine if two boolean values are equal through conditional logic
bool Bool::bool_dec(const bool x, const bool y) {
  if (x) {
    if (y) {
      return true;
    } else {
      return false;
    }
  } else {
    if (y) {
      return false;
    } else {
      return true;
    }
  }
}

#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>
#include <signal.h>
#include "server.hpp"
#include "file_handler.hpp"

int main(int argument_count, char* arguments[])
{
  try
  {
    // Validate command line parameters.
    if (argument_count != 4)
    {
      std::cerr << "Usage: http_server <address> <port> <doc_root>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 80 .\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 80 .\n";
      return 1;
    }

    asio::io_context service_context;

    // Start the server coroutine with provided arguments.
    http::server4::server(service_context, arguments[1], arguments[2],
        http::server4::file_handler(arguments[3]))();

    // Prepare to handle shutdown signals.
    asio::signal_set termination_signals(service_context);
    termination_signals.add(SIGINT);
    termination_signals.add(SIGTERM);
#if defined(SIGQUIT)
    termination_signals.add(SIGQUIT);
#endif // defined(SIGQUIT)

    termination_signals.async_wait(boost::bind(
          &asio::io_context::stop, &service_context));

    // Execute the server event loop.
    service_context.run();
  }
  catch (std::exception& error)
  {
    std::cerr << "exception: " << error.what() << "\n";
  }

  return 0;
}

