Tooltip::~Tooltip() {}

void Tooltip::sync_hover_delay() {
    mem::write<int>(0x59E10D, delay_value.get());
}

void Tooltip::sync_alt_for_containers() {
    if (enable_all_containers.get()) {
        mem::set(0x416D1D, 0x90, 2);  // bypass hover check for alt+container tooltips
        mem::set(0x416D22, 0x90, 2);  // same as above, second instruction patch
    } else {
        mem::write<BYTE[2]>(0x416d1d, {0x74, 0x74});
        mem::write<BYTE[2]>(0x416D22, {0x74, 0x6F});
    }
    // Zeal::Game::print_chat("Alt-container tooltips: %s", enable_all_containers ? "ON" : "OFF");
}

Tooltip::Tooltip(ZealService *service) {
    mem::write<BYTE>(0x59e112, 0x82);  // switch jbe → jb to prevent tooltip flicker when timer disabled

    service->commands_hook->Add("/showalltooltips", {}, "Enable/disable tooltips for all open containers under alt.",
                                [this](std::vector<std::string> &params) {
                                    enable_all_containers.toggle();
                                    return true;  // suppress default game handling
                                });

    service->commands_hook->Add("/delay", {"/tt"}, "Adjust tooltip appearance delay (in ms).",
                                [this](std::vector<std::string> &params) {
                                    int value = 0;
                                    if (params.size() > 1 && Zeal::String::tryParse(params[1], &value)) {
                                        delay_value.set(value);
                                        Zeal::Game::print_chat("Tooltip delay set to %i ms", delay_value.get());
                                    }
                                    return true;  // prevent further command processing
                                });
}

