float computeZSpread(float zA, float zB, float zC) {
    float highest = zA;
    float lowest = zA;

    if (zB > highest) highest = zB;
    if (zC > highest) highest = zC;

    if (zB < lowest) lowest = zB;
    if (zC < lowest) lowest = zC;

    return std::abs(highest - lowest);
