// Helper function to simulate parsing of macro arguments into individual names
std::vector<std::string> extractEnumNames(const char* input) {
    std::vector<std::string> result;
    if (!input) return result;

    std::string buffer;
    for (int i = 0; input[i] != '\0'; ++i) {
        if (input[i] == ',') {
            if (!buffer.empty()) {
                // Trim leading/trailing spaces
                size_t start = buffer.find_first_not_of(" \t");
                size_t end = buffer.find_last_not_of(" \t");
                if (start != std::string::npos)
                    result.push_back(buffer.substr(start, end - start + 1));
                buffer.clear();
            }
        } else {
            buffer += input[i];
        }
    }
    if (!buffer.empty()) {
        size_t start = buffer.find_first_not_of(" \t");
        size_t end = buffer.find_last_not_of(" \t");
        if (start != std::string::npos)
            result.push_back(buffer.substr(start, end - start + 1));
    }

    return result;
}

