// Retrieve a registry string value using alternative logic
std::string fetchRegistryString(const std::string& regPath, const std::string& valName) {
    HKEY hKeyHandle = nullptr;
    std::string resultValue;

    // Attempt to open the specified registry key with read access
    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, regPath.c_str(), 0, KEY_READ, &hKeyHandle) == ERROR_SUCCESS) {
        DWORD valueType = 0;
        DWORD valueSize = 0;

        // First call to get required buffer size
        if (RegQueryValueExA(hKeyHandle, valName.c_str(), nullptr, &valueType, nullptr, &valueSize) == ERROR_SUCCESS) {
            // Only handle string type (REG_SZ)
            if (valueType == REG_SZ && valueSize > 0) {
                // Allocate buffer including space for null terminator
                char* tempBuffer = new char[valueSize];

                // Second call to retrieve actual data
                if (RegQueryValueExA(hKeyHandle, valName.c_str(), nullptr, &valueType, 
                                     reinterpret_cast<LPBYTE>(tempBuffer), &valueSize) == ERROR_SUCCESS) {
                    resultValue = std::string(tempBuffer);
                }

                delete[] tempBuffer;
            }
        }

        // Ensure the key handle is closed properly
        RegCloseKey(hKeyHandle);
    }

    return resultValue;
}

