void setupUnixSocketAddress(int domain, const std::string& path, struct sockaddr_storage& storage) {
    struct sockaddr_un unix_addr;
    unix_addr.sun_family = domain;
    std::memset(unix_addr.sun_path, 0, sizeof(unix_addr.sun_path));
    std::strncpy(unix_addr.sun_path, path.c_str(), sizeof(unix_addr.sun_path) - 1);
    // Ensure null-termination if the path was truncated
    unix_addr.sun_path[sizeof(unix_addr.sun_path) - 1] = '\0';
    // Safely copy to the generic socket address structure
    std::memmove(&storage, &unix_addr, sizeof(unix_addr));
}

