#include <type_traits>
#include <stdexcept>

class group
{
public:
    using const_iterator = std::vector<std::string>::const_iterator;
    using size_type = std::vector<std::string>::size_type;

    // Key-value storage using unordered_map
    std::unordered_map<std::string, std::string> data;

    // Retrieve value by key with type conversion (throws exception if key missing)
    template<typename T>
    T get(const std::string& key) const {
        auto it = data.find(key);
        if (it != data.end()) {
            try {
                return transform<T>(it->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Value cannot be converted to the requested type");
            }
        } else {
            throw std::out_of_range("Key does not exist");
        }
    }

    // Retrieve value by key with default fallback if key missing
    template<typename T>
    T get(const std::string& key, const T& fallback) const {
        auto it = data.find(key);
        if (it != data.end()) {
            try {
                return transform<T>(it->second);
            } catch (const std::invalid_argument&) {
                throw std::invalid_argument("Value cannot be converted to the requested type");
            }
        } else {
            return fallback;
        }
    }

private:
    // Internal helper for type conversion from string
    template<typename T>
    T transform(const std::string& input) const {
        if constexpr (std::is_same_v<T, int>) {
            return std::stoi(input);
        } else if constexpr (std::is_same_v<T, double>) {
            return std::stod(input);
        } else if constexpr (std::is_same_v<T, std::string>) {
            return input;
        } else {
            throw std::invalid_argument("Unsupported type conversion");
        }
    }
};

#include <vector>
using namespace std;

// Helper function to mark all connected 'L' cells starting from (row, col)
void markConnectedRegion(vector<vector<char>>& matrix, int row, int col) {
    // Check boundaries and if current cell is unvisited land ('L')
    if (row < 0 || row >= matrix.size() || col < 0 || col >= matrix[0].size() || matrix[row][col] != 'L') {
        return;
    }

    // Mark current cell as visited by changing it to water ('W')
    matrix[row][col] = 'W';

    // Explore all 8 neighboring directions using recursive calls
    markConnectedRegion(matrix, row + 1, col);     // Down
    markConnectedRegion(matrix, row - 1, col);     // Up
    markConnectedRegion(matrix, row, col + 1);     // Right
    markConnectedRegion(matrix, row, col - 1);     // Left
    markConnectedRegion(matrix, row + 1, col + 1); // Down-Right diagonal
    markConnectedRegion(matrix, row - 1, col - 1); // Up-Left diagonal
    markConnectedRegion(matrix, row + 1, col - 1); // Down-Left diagonal
    markConnectedRegion(matrix, row - 1, col + 1); // Up-Right diagonal
}

// Count the number of connected land regions in the grid
int numberOfLandClusters(vector<vector<char>>& grid) {
    int clusters = 0;
    int rows = grid.size();
    int cols = (rows > 0) ? grid[0].size() : 0;

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == 'L') {
                clusters++;
                markConnectedRegion(grid, r, c);
            }
        }
    }
    return clusters;
}

