#include <iostream>
#include <vector>

class TreeNode {
public:
    TreeNode(std::vector<TreeNode*> descendants, std::pair<int, int> coords) 
        : m_descendants(descendants), coordinates(coords) {}

    void shiftBy(std::pair<int, int> delta) {
        // Update current node's position by the given delta
        coordinates.first += delta.first;
        coordinates.second += delta.second;

        // Propagate the same shift to all descendant nodes
        for (auto& descendant : m_descendants) {
            descendant->shiftBy(delta);
        }
    }

    void moveTo(std::pair<int, int> target) {
        // Compute the required shift to reach the target position
        int dx = target.first - coordinates.first;
        int dy = target.second - coordinates.second;
        std::pair<int, int> delta = std::make_pair(dx, dy);

        // Apply the shift to this node and all descendants
        shiftBy(delta);
    }

private:
    std::pair<int, int> coordinates;
    std::vector<TreeNode*> m_descendants;
};

int main() {
    // Construct a tree structure with parent and children
    TreeNode* leafA = new TreeNode({}, std::make_pair(1, 1));
    TreeNode* leafB = new TreeNode({}, std::make_pair(2, 2));
    TreeNode* root = new TreeNode({leafA, leafB}, std::make_pair(0, 0));

    // Relocate the root node to a new position
    root->moveTo(std::make_pair(3, 3));

    // Deallocate dynamically allocated memory
    delete leafA;
    delete leafB;
    delete root;

    return 0;
}

