// Manages identifiers within namespaces using a nested map structure
class NamespaceManager {
private:
    std::unordered_map<std::string, std::unordered_map<std::string, bool>> namespaceRegistry;

public:
    // Registers an identifier in a specified namespace
    void registerIdentifier(const std::string& nsName, const std::string& idName) {
        namespaceRegistry[nsName][idName] = true;
    }

    // Checks whether an identifier exists in a given namespace
    std::string checkIdentifier(const std::string& nsName, const std::string& idName) {
        auto nsIt = namespaceRegistry.find(nsName);
        if (nsIt != namespaceRegistry.end()) {
            auto idIt = nsIt->second.find(idName);
            if (idIt != nsIt->second.end()) {
                return "Identifier '" + idName + "' found in namespace '" + nsName + "'.";
            }
        }
        return "Identifier '" + idName + "' not found in namespace '" + nsName + "'.";
    }
};

int main() {
    NamespaceManager manager;

    // Register identifiers across different namespaces
    manager.registerIdentifier("namespace1", "identifier1");
    manager.registerIdentifier("namespace1", "identifier2");
    manager.registerIdentifier("namespace2", "identifier3");

    // Perform lookups and print results
    std::cout << manager.checkIdentifier("namespace1", "identifier1") << std::endl;  // Output: Identifier 'identifier1' found in namespace 'namespace1'.
    std::cout << manager.checkIdentifier("namespace1", "identifier3") << std::endl;  // Output: Identifier 'identifier3' not found in namespace 'namespace1'.
    std::cout << manager.checkIdentifier("namespace2", "identifier3") << std::endl;  // Output: Identifier 'identifier3' found in namespace 'namespace2'.

