// Decrypts a single character using Caesar cipher with given shift
char applyCaesarShift(char ch, int shiftAmount) {
    if (!std::isalpha(ch)) {
        return ch;
    }

    char base = std::islower(ch) ? 'a' : 'A';
    // Apply reverse shift (decryption equivalent)
    int originalPos = ch - base;
    int shiftedPos = (originalPos + (26 - shiftAmount % 26)) % 26;
    return static_cast<char>(base + shiftedPos);
}

int main() {
    std::string userInput;
    int shiftValue;

    std::cout << "Enter a line of text:\n";
    std::getline(std::cin, userInput);

    std::cout << "Enter an integer to shift the text (1-25):\n";
    std::cin >> shiftValue;

    // Validate shift value
    while (shiftValue < 1 || shiftValue > 25) {
        std::cout << "Invalid shift value. Please enter an integer between 1 and 25:\n";
        std::cin >> shiftValue;
    }

    std::string resultText;
    for (size_t i = 0; i < userInput.length(); ++i) {
        resultText += applyCaesarShift(userInput[i], shiftValue);
    }

    std::cout << "Encrypted text: " << resultText << std::endl;
    return 0;
}

