#include <thread>
#include <iostream>
#include <gtest/gtest.h>

class PrintInOrder {
public:
    PrintInOrder() : nextExpected(1) {}

    void first() {
        executePrint(1);
    }

    void second() {
        executePrint(2);
    }

    void third() {
        executePrint(3);
    }

private:
    int nextExpected;
    std::mutex mtx;
    std::condition_variable cv;

    void executePrint(int value) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, value] { return nextExpected == value; });

        std::cout << value << std::endl;
        nextExpected++;

        cv.notify_all();
    }
};

TEST(PrintInOrderTest, Foo) {
    PrintInOrder printer;
    std::thread t1(&PrintInOrder::first, &printer);
    std::thread t2(&PrintInOrder::second, &printer);
    std::thread t3(&PrintInOrder::third, &printer);

    t1.join();
    t2.join();
    t3.join();

    std::string result = testing::internal::GetCapturedStdout();
    EXPECT_EQ(result, "123\n");
}

