// Compute the elapsed time in years between two calendar dates
double computeYearDifference(const std::tm& startDate, const std::tm& endDate) {
    std::time_t startTimestamp = std::mktime(const_cast<std::tm*>(&startDate));
    std::time_t endTimestamp = std::mktime(const_cast<std::tm*>(&endDate));
    double durationInSeconds = std::difftime(endTimestamp, startTimestamp);
    const double secondsPerYear = 60.0 * 60.0 * 24.0 * 365.25; // includes leap year adjustment
    return durationInSeconds / secondsPerYear;
}

int main() {
    // Demonstration of computeYearDifference function
    std::tm startDate = {0, 0, 0, 1, 0, 100}; // January 1, 2000
    std::tm endDate = {0, 0, 0, 1, 0, 105};   // January 1, 2005
    double elapsedYears = computeYearDifference(startDate, endDate);
    std::cout << "Elapsed time in years: " << elapsedYears << std::endl;

    // Iterate over container elements while filtering out specific values
    std::vector<int> inputValues = {1, 2, 3, 4, 5};
