// Function to verify JSON structure integrity
bool checkJSONIntegrity(const Json::Value& root) {
    // Convert the JSON object to a string representation
    Json::StreamWriterBuilder builder;
    std::string serialized = Json::writeString(builder, root);

    // Prepare for parsing back from string
    Json::CharReaderBuilder charReader;
    std::istringstream buffer(serialized);
    Json::Value verifiedJson;
    std::string errorMsg;

    // Attempt to parse the serialized JSON
    bool isValid = Json::parseFromStream(charReader, buffer, &verifiedJson, &errorMsg);

