// Channel class implementation for thread-safe message passing
template<typename T>
class Channel {
private:
    std::queue<T> data_queue;
    mutable std::mutex mtx;
    std::condition_variable not_empty;

public:
    void send(const T& value) {
        std::lock_guard<std::mutex> lock(mtx);
        data_queue.push(value);
        not_empty.notify_one();
    }

    T receive() {
        std::unique_lock<std::mutex> lock(mtx);
        not_empty.wait(lock, [this] { return !data_queue.empty(); });
        T value = data_queue.front();
        data_queue.pop();
        return value;
    }
};

// Test case for channel creation and basic communication
TEST(ChannelTest, Creation) {
    Channel<int> channel;
    std::thread sender([&channel] {
        channel.send(42);
    });
    std::thread receiver([&channel] {
        int message = channel.receive();
        ASSERT_EQ(message, 42);
    });
    sender.join();
    receiver.join();
}

