// Compare two floating-point numbers for equality within a given ULP tolerance
bool nearly_equal(const float a, const float b, int max_ulp) {
    // Reinterpret bit patterns as integers to measure ULP difference
    int a_bits = *reinterpret_cast<const int*>(&a);
    int b_bits = *reinterpret_cast<const int*>(&b);

    // Adjust for signed magnitude representation in IEEE 754
    if (a_bits < 0) {
        a_bits = 0x80000000 - a_bits;
    }
    if (b_bits < 0) {
        b_bits = 0x80000000 - b_bits;
    }

    // Compute absolute difference in ULPs
    int diff = std::abs(a_bits - b_bits);

    // Return true if the difference is within the allowed tolerance
    return diff <= max_ulp;
}

