// Weight-balanced binary search tree implementation
template <typename T>
class BalancedBST {
private:
  struct TreeNode {
    T data;
    int subtreeSize;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode(T val) : data(val), subtreeSize(1), 
                      leftChild(nullptr), rightChild(nullptr) {}
  };

  TreeNode* rootPtr;

  // Helper to get current subtree size
  int getSize(TreeNode* node) const {
    return node ? node->subtreeSize : 0;
  }

  // Update subtree size based on children
  void updateSize(TreeNode* node) {
    if (node) {
      node->subtreeSize = getSize(node->leftChild) + 
                          getSize(node->rightChild) + 1;
    }
  }

  // In-order traversal to collect all values
  void traverseInOrder(TreeNode* node, std::vector<T>& storage) const {
    if (!node) return;
    traverseInOrder(node->leftChild, storage);
    storage.push_back(node->data);
    traverseInOrder(node->rightChild, storage);
  }

  // Build a balanced BST from sorted array
  TreeNode* constructBalanced(std::vector<T>& sortedData, int left, int right) {
    if (left >= right) return nullptr;

    int middle = (left + right) / 2;
    TreeNode* newNode = new TreeNode(sortedData[middle]);

    newNode->leftChild = constructBalanced(sortedData, left, middle);
    newNode->rightChild = constructBalanced(sortedData, middle + 1, right);

    updateSize(newNode);
    return newNode;
  }

  // Rebuild the tree when balance factor is violated
  void rebuild(TreeNode*& node) {
    std::vector<T> collectedValues;
    traverseInOrder(node, collectedValues);
    node = constructBalanced(collectedValues, 0, collectedValues.size());
  }

  // Check balance condition and rebuild if necessary
  void maintainBalance(TreeNode*& node) {
    if (!node) return;

    int leftSize = getSize(node->leftChild);
    int rightSize = getSize(node->rightChild);

    // If imbalance exceeds threshold (3:1 ratio)
    if (leftSize > 3 * rightSize || rightSize > 3 * leftSize) {
      rebuild(node);
    } else {
      updateSize(node);
    }
  }

  // Insert value into tree
  void insertValue(TreeNode*& node, const T& value) {
    if (!node) {
      node = new TreeNode(value);
      return;
    }

    if (value < node->data) {
      insertValue(node->leftChild, value);
    } else {
      insertValue(node->rightChild, value);
    }

    maintainBalance(node);
  }

  // Find minimum value node in subtree
  TreeNode* findMinimum(TreeNode* node) {
    while (node && node->leftChild) {
      node = node->leftChild;
    }
    return node;
  }

  // Remove value from tree
  void deleteValue(TreeNode*& node, const T& value) {
    if (!node) return;

    if (value < node->data) {
      deleteValue(node->leftChild, value);
    } else if (value > node->data) {
      deleteValue(node->rightChild, value);
    } else {
      // Node found - handle deletion cases
      if (!node->leftChild) {
        TreeNode* temp = node->rightChild;
        delete node;
        node = temp;
      } else if (!node->rightChild) {
        TreeNode* temp = node->leftChild;
        delete node;
        node = temp;
      } else {
        // Two children case - find inorder successor
        TreeNode* successor = findMinimum(node->rightChild);
        node->data = successor->data;
        deleteValue(node->rightChild, successor->data);
      }
    }

    maintainBalance(node);
  }

  // Calculate sum of values within range [low, high]
  T rangeSumQuery(TreeNode* node, const T& low, const T& high) const {
    if (!node) return T();

    if (node->data < low) {
      return rangeSumQuery(node->rightChild, low, high);
    } else if (node->data > high) {
      return rangeSumQuery(node->leftChild, low, high);
    } else {
      return node->data + 
             rangeSumQuery(node->leftChild, low, node->data) +
             rangeSumQuery(node->rightChild, node->data, high);
    }
  }

public:
  BalancedBST() : rootPtr(nullptr) {}

  ~BalancedBST() {
    clearTree(rootPtr);
  }

  void insert(const T& value) {
    insertValue(rootPtr, value);
  }

  void erase(const T& value) {
    deleteValue(rootPtr, value);
  }

  int countElements() const {
    return getSize(rootPtr);
  }

  T calculateRangeSum(const T& low, const T& high) const {
    return rangeSumQuery(rootPtr, low, high);
  }

private:
  void clearTree(TreeNode* node) {
    if (!node) return;
    clearTree(node->leftChild);
    clearTree(node->rightChild);
    delete node;
  }
};

int main() {
  BalancedBST<int> bst;

  // Insert sample elements
  bst.insert(5);
  bst.insert(3);
  bst.insert(7);
  bst.insert(2);
  bst.insert(4);
  bst.insert(6);
  bst.insert(8);

  std::cout << "Total nodes in tree: " << bst.countElements() << std::endl;
  std::cout << "Sum in range [3, 7]: " << bst.calculateRangeSum(3, 7) << std::endl;

  // Remove an element
  bst.erase(5);
  std::cout << "Nodes after removing 5: " << bst.countElements() << std::endl;

  return 0;
}

