enum class SymbolType {
  Var,
  Func,
  ClassType
};

enum class ScopeType {
  Global,
  ClassScope
};

struct SymbolRecord {
  std::string identifier;
  SymbolType type;
  std::string sourceFile;
  std::vector<std::pair<ScopeType, std::string>> scopes;

  SymbolRecord(const std::string& id, SymbolType t, const std::string& file,
               std::vector<std::pair<ScopeType, std::string>> sc)
      : identifier(id), type(t), sourceFile(file), scopes(sc) {}
};

class SymbolMonitor {
private:
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> observed;
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> referenced;

public:
  void observe(const SymbolRecord& sym) {
    for (const auto& scope : sym.scopes) {
      observed[scope.second][sym.identifier] = true;
    }
  }

  void markUsed(const SymbolRecord& sym) {
    for (const auto& scope : sym.scopes) {
      referenced[scope.second][sym.identifier] = true;
    }
  }

  bool wasObserved(const std::string& scope, const std::string& name) {
    return observed[scope][name];
  }

  bool wasReferenced(const std::string& scope, const std::string& name) {
    return referenced[scope][name];
  }
};

int main() {
  SymbolMonitor monitor;

  SymbolRecord var1("X2", SymbolType::Var, "HeaderName",
                   {{ScopeType::Global, ""}});
  monitor.observe(var1);
  monitor.markUsed(var1);

  SymbolRecord var2("X3", SymbolType::Var, "HeaderName",
                   {{ScopeType::Global, ""},
                    {ScopeType::Global, ""}});
  monitor.observe(var2);
  monitor.markUsed(var2);

  // Output verification results
  std::cout << "Symbol X2 observed and used in global scope: " 
            << monitor.wasObserved("", "X2") << " " 
            << monitor.wasReferenced("", "X2") << std::endl;
  std::cout << "Symbol X3 observed and used in global scope: " 
            << monitor.wasObserved("", "X3") << " " 
            << monitor.wasReferenced("", "X3") << std::endl;

  return 0;
}

