// Determines if a given instance ID can be used (i.e., hasn't been used before)
// Returns true if the instance ID is valid and unique, false otherwise
bool isInstanceIdUsable(int instance_id, std::unordered_set<int>* tracked_ids, bool* result) {
    // Attempt to insert the instance ID into our tracking set
    auto insert_result = tracked_ids->insert(instance_id);

    // If insertion succeeded (second is true), this is a new ID and thus usable
    // If insertion failed (second is false), the ID was already present and not usable
    *result = insert_result.second;

    return *result;
}

