#include <vector>
#include <algorithm>

// Determine if there exist two trees with a distance of exactly k between them
bool canFormTreePair(std::vector<int> tree, int k) {
    std::sort(tree.begin(), tree.end()); // Arrange tree positions in ascending order

    int left = 0;
    int right = static_cast<int>(tree.size()) - 1;

    while (left < right) {
        int currentSum = tree[left] + k;

        if (currentSum < tree[right]) {
            ++left; // Increase left pointer to consider larger values
        } else if (currentSum > tree[right]) {
            --right; // Decrease right pointer to consider smaller values
        } else {
            return true; // Found a valid pair where tree[right] - tree[left] == k
        }
    }

    return false; // No suitable pair found
}

