#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>

class WorkerPool {
public:
    WorkerPool(size_t thread_count) : is_active_(true), active_tasks_(0) {
        for (size_t i = 0; i < thread_count; ++i) {
            workers_.emplace_back([this] { runWorker(); });
        }
    }

    void dispatch() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (is_active_) {
            auto job = std::move(tasks_.front());
            tasks_.pop();
            lock.unlock();
            ++active_tasks_;
            job(); // Execute the job
            lock.lock();
            --active_tasks_;
            cv_.notify_one();
        }
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            is_active_ = false;
        }
        cv_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    using Job = std::function<void()>;
    std::queue<Job> tasks_;
    std::vector<std::thread> workers_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    bool is_active_;
    size_t active_tasks_;

    void runWorker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !is_active_ || !tasks_.empty(); });
            if (!is_active_ && tasks_.empty()) {
                break;
            }
            dispatch();
        }
    }
};

