// Context types for sequence handling options
enum class SequenceContextOption {
    SkipTranslation,
    TranslateSelectionOrNotes,
    ManualFrameConfiguration,
    DisplayAllFrames
};

// Manager class to handle context-based UI actions
class SequenceContextController : public QObject {
    Q_OBJECT
public:
    QCheckBox* skipTranslationCheck;
    QCheckBox* translateSelectionCheck;
    QCheckBox* manualFrameSetupCheck;
    QCheckBox* displayAllFramesCheck;

    // Constructor: initializes the associated checkboxes
    SequenceContextController(QCheckBox* skipTrans, QCheckBox* transSel, QCheckBox* manualSetup, QCheckBox* showAll)
        : skipTranslationCheck(skipTrans), translateSelectionCheck(transSel),
          manualFrameSetupCheck(manualSetup), displayAllFramesCheck(showAll) {}

    // Updates checkbox states based on current context option
    void updateCheckboxStates(SequenceContextOption option) {
        skipTranslationCheck->setChecked(option == SequenceContextOption::SkipTranslation);
        translateSelectionCheck->setChecked(option == SequenceContextOption::TranslateSelectionOrNotes);
        manualFrameSetupCheck->setChecked(option == SequenceContextOption::ManualFrameConfiguration);
        displayAllFramesCheck->setChecked(option == SequenceContextOption::DisplayAllFrames);
    }

    // Triggers the appropriate signal based on the selected context option
    void triggerContextSignal(SequenceContextOption option) {
        switch (option) {
            case SequenceContextOption::SkipTranslation:
                emit action_skipTranslation();
                break;
            case SequenceContextOption::TranslateSelectionOrNotes:
                emit action_translateSelection();
                break;
            case SequenceContextOption::ManualFrameConfiguration:
                emit action_manualFrameSetup();
                break;
            case SequenceContextOption::DisplayAllFrames:
                emit action_displayAllFrames();
                break;
        }
    }

signals:
    void action_skipTranslation();
    void action_translateSelection();
    void action_manualFrameSetup();
    void action_displayAllFrames();
