class Inventory {
private:
    struct ItemInfo {
        std::string name;
        int quantity;
        double price;
    };
    std::map<int, ItemInfo> inventoryItems;

public:
    void addItem(int itemId, const std::string& itemName, int stockCount, double unitCost) {
        auto existingItem = inventoryItems.find(itemId);
        if (existingItem != inventoryItems.end()) {
            existingItem->second.quantity += stockCount;
        } else {
            ItemInfo newItem = {itemName, stockCount, unitCost};
            inventoryItems[itemId] = newItem;
        }
    }

    void removeItem(int itemId, int removalCount) {
        auto itemIterator = inventoryItems.find(itemId);
        if (itemIterator != inventoryItems.end()) {
            if (itemIterator->second.quantity <= removalCount) {
                inventoryItems.erase(itemIterator);
            } else {
                itemIterator->second.quantity -= removalCount;
            }
        }
    }

    void showStock() {
        std::cout << "Current Inventory:\n";
        for (const auto& entry : inventoryItems) {
            std::cout << "ID: " << entry.first 
                      << ", Name: " << entry.second.name
                      << ", Quantity: " << entry.second.quantity
                      << ", Price: $" << entry.second.price << std::endl;
        }
    }
};

int main() {
    Inventory storeInventory;

    // Add initial items
    storeInventory.addItem(1, "Shirt", 50, 25.99);
    storeInventory.addItem(2, "Pants", 30, 39.99);

    // Update existing item with additional stock
    storeInventory.addItem(1, "Shirt", 20, 25.99);

    // Display before removal
    storeInventory.showStock();

    // Remove some items
    storeInventory.removeItem(1, 30);

    // Display after removal
    storeInventory.showStock();

    return 0;
}

