// Custom exception for date parsing errors
class DateParsingError : public std::exception {
public:
    const char* what() const noexcept override {
        return "Date parsing error";
    }
};

// Custom exception for date validation errors
class DateValidationError : public std::exception {
public:
    const char* what() const noexcept override {
        return "Date validation error";
    }
};

// Class representing a date and time
class DateTime {
private:
    int year, month, day;
    int hour, minute, second;

public:
    // Constructor that parses and validates the date-time string
    DateTime(const std::string& input) {
        // Regular expression to match YYYY-MM-DD HH:MM:SS format
        std::regex pattern(R"((\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}))");
        std::smatch result;

        if (!std::regex_match(input, result, pattern)) {
            throw DateParsingError();
        }

        // Extract components from regex match
        year = std::stoi(result[1]);
        month = std::stoi(result[2]);
        day = std::stoi(result[3]);
        hour = std::stoi(result[4]);
        minute = std::stoi(result[5]);
        second = std::stoi(result[6]);

        // Validate the extracted values
        if (!checkDate(year, month, day) || !checkTime(hour, minute, second)) {
            throw DateValidationError();
        }
    }

    // Public method to validate current date/time state
    void check() {
        if (!checkDate(year, month, day) || !checkTime(hour, minute, second)) {
            throw DateValidationError();
        }
    }

private:
    // Determine if a year is a leap year
    bool isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    // Check if the given date is valid
    bool checkDate(int y, int m, int d) {
        if (y <= 0 || m < 1 || m > 12 || d < 1) {
            return false;
        }

        // Days per month array (index 0 unused)
        static const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        // Handle February leap year case
        if (m == 2 && isLeap(y)) {
            return d <= 29;
        }
        return d <= days[m];
    }

    // Check if the given time is valid
    bool checkTime(int h, int min, int sec) {
        return (h >= 0 && h < 24) && 
               (min >= 0 && min < 60) && 
               (sec >= 0 && sec < 60);
    }
};

int main() {
    // Test case 1: Invalid month (13)
    try {
        DateTime dt1("2015-13-05 06:03:00");
    } catch (const DateParsingError& e) {
        std::cout << "DateParsingError caught: " << e.what() << std::endl;
    }

    // Test case 2: Wrong separator (spaces instead of colons)
    try {
        DateTime dt2("2015-13-05 09 06 03");
    } catch (const DateParsingError& e) {
        std::cout << "DateParsingError caught: " << e.what() << std::endl;
    }

    // Test case 3: Valid format but invalid month (13)
    try {
        DateTime dt3("2015-13-05 09:06:03");
        dt3.check();
    } catch (const DateValidationError& e) {
        std::cout << "DateValidationError caught: " << e.what() << std::endl;
    }

    // Test case 4: Fully valid date and time
    try {
        DateTime dt4("2015-12-05 00:06:03");
        dt4.check();
        std::cout << "Valid date and time" << std::endl;
    } catch (const DateValidationError& e) {
        std::cout << "DateValidationError caught: " << e.what() << std::endl;
    }

    return 0;
}

