#include <iostream>
#include <memory>
#include <vector>

class DynamicArray {
private:
    std::unique_ptr<int[]> elements;
    int capacity;

public:
    // Constructor to allocate memory for the array
    DynamicArray(int initialCapacity) : capacity(initialCapacity), elements(new int[initialCapacity]) {}

    // Method to access and modify elements of the array
    int& operator[](int index) {
        if (index < 0 || index >= capacity) {
            throw std::out_of_range("Index out of range");
        }
        return elements[index];
    }

    // Method to resize the array
    void expand(int newCapacity) {
        if (newCapacity == capacity) {
            return;  // No need to change size
        }

        std::unique_ptr<int[]> freshData(new int[newCapacity]);
        int count = (newCapacity < capacity) ? newCapacity : capacity;

        for (int i = 0; i < count; ++i) {
            freshData[i] = elements[i];
        }

        elements = std::move(freshData);
        capacity = newCapacity;
    }

    // Destructor to release the memory
    ~DynamicArray() {
        elements.reset();  // Memory deallocation
    }
};

int main() {
    DynamicArray arr(10);  // Create a dynamic array with capacity 10
    arr[5] = 42;           // Set element at index 5
    std::cout << arr[5] << std::endl;  // Print element at index 5

    arr.expand(15);        // Expand the array to capacity 15
    std::cout << arr[5] << std::endl;  // Print element at index 5 after expansion

    return 0;
}

