#include <exception>
#include <functional>
#include <unordered_map>

class ExceptionTranslator {
public:
    template <typename Callable>
    void process(Callable&& action) {
        try {
            std::forward<Callable>(action)();
        } catch (const std::exception& e) {
            auto lookup = mapping.find(typeid(e).name());
            if (lookup != mapping.end()) {
                throw lookup->second();
            }
            throw;
        }
    }

    template <typename Source, typename Target>
    void registerMapping() {
        mapping[typeid(Source).name()] = []() -> std::exception { return Target(); };
    }

private:
    std::unordered_map<std::string, std::function<std::exception()>> mapping;
};

#define HANDLE_EXCEPTION(translator, codeBlock) translator.process([&]() { codeBlock; })
