// Helper function to convert FILETIME to 64-bit unsigned integer
ULONGLONG fileTimeToULL(const FILETIME& ft) {
    return (static_cast<ULONGLONG>(ft.dwHighDateTime) << 32) | static_cast<ULONGLONG>(ft.dwLowDateTime);
}

// Global container for system status metrics
std::map<std::string, double> systemMetrics;

// Compute CPU utilization and store in global map
void updateCPUStats(const FILETIME& currentIdle, const FILETIME& currentKernel,
                    const FILETIME& currentUser, const FILETIME& prevIdle,
                    const FILETIME& prevKernel, const FILETIME& prevUser) {
    // Reset the metrics collection before computing new values
    systemMetrics.clear();

    // Extract time differences
    ULONGLONG idleDelta = fileTimeToULL(currentIdle) - fileTimeToULL(prevIdle);
    ULONGLONG kernelDelta = fileTimeToULL(currentKernel) - fileTimeToULL(prevKernel);
    ULONGLONG userDelta = fileTimeToULL(currentUser) - fileTimeToULL(prevUser);

    // Total active time (non-idle)
    ULONGLONG activeTime = kernelDelta + userDelta;

    // Avoid division by zero
    if (activeTime + idleDelta == 0) {
        systemMetrics["CPU Usage"] = 0.0;
        return;
    }

    // Calculate percentage usage
    double usagePercent = 100.0 * static_cast<double>(activeTime) / 
                          static_cast<double>(activeTime + idleDelta);

    // Store result in map
    systemMetrics["CPU Usage"] = usagePercent;
}

