#include <iostream>

class Item {
public:
    int mnId;
    Item* Next;

    Item(int id) : mnId(id), Next(nullptr) {}
};

class ItemList {
private:
    Item* mHead;
    Item* mTail;
public:
    ItemList() : mHead(nullptr), mTail(nullptr) {}

    void AddItem(int id) {
        Item* newItem = new Item(id);
        if (mHead == nullptr) {
            mHead = newItem;
            mTail = newItem;
        } else {
            mTail->Next = newItem;
            mTail = newItem;
        }
    }

    Item* GetHead() const {
        return mHead;
    }
};

class CustomIterator {
private:
    Item* mCurrent;
public:
    CustomIterator(Item* pHead) : mCurrent(pHead) {}

    Item* Next() {
        Item* currentItem = mCurrent;
        if (mCurrent != nullptr) {
            mCurrent = mCurrent->Next;
        }
        return currentItem;
    }

    bool HasNext() const {
        return mCurrent != nullptr;
    }
};

int main() {
    ItemList* mpItemList = new ItemList();
    mpItemList->AddItem(1);
    mpItemList->AddItem(2);
    mpItemList->AddItem(3);

    CustomIterator iterator(mpItemList->GetHead());

    while (iterator.HasNext()) {
        Item* pItem = iterator.Next();
        if (pItem != nullptr) {
            std::cout << "Processing item with id: " << pItem->mnId << std::endl;
        }
    }

    delete mpItemList;
    return 0;
}

