// Implementation of Bullet methods
void Bullet::Activate() {
    active = true;
}

void Bullet::Deactivate() {
    active = false;
}

bool Bullet::IsActive() const {
    return active;
}

void Bullet::Ascend() {
    if (pos_y < 150.0f && active) {
        pos_y += speed_val;
    }
}

void Bullet::Descend() {
    if (pos_y > -725.0f && active) {
        pos_y -= speed_val;
    }
}

