class MethodNotImplementedException : public std::exception {
private:
    std::string methodName;
    int errorNumber;
    std::string details;
public:
    MethodNotImplementedException(const std::string& funcName)
        : methodName(funcName), errorNumber(0), details("") {}
    MethodNotImplementedException(const std::string& funcName, int errCode)
        : methodName(funcName), errorNumber(errCode), details("") {}
    MethodNotImplementedException(const std::string& funcName, int errCode, const std::string& msg)
        : methodName(funcName), errorNumber(errCode), details(msg) {}
    const char* what() const noexcept override {
        std::stringstream buffer;
        buffer << "Method '" << methodName << "' is not implemented";
        if (errorNumber != 0) {
            buffer << " (Error code: " << errorNumber << ")";
        }
        if (!details.empty()) {
            buffer << ": " << details;
        }
        return buffer.str().c_str();
    }
};

// Validation function to ensure the exception behaves correctly
void validateNotImplementedException() {
    try {
        throw MethodNotImplementedException("unimplemented_method");
    } catch (const MethodNotImplementedException& ex) {
        // Confirm the exception message format
        assert(std::string(ex.what()) == "Method 'unimplemented_method' is not implemented");
    }
    try {
        throw MethodNotImplementedException("sample_func", 789);
    } catch (const MethodNotImplementedException& ex) {
        // Confirm the exception message with error code
        assert(std::string(ex.what()) == "Method 'sample_func' is not implemented (Error code: 789)");
    }
    try {
        throw MethodNotImplementedException("sample_func", 101, "Additional context");
    } catch (const MethodNotImplementedException& ex) {
        // Confirm the full exception message with all components
        assert(std::string(ex.what()) == "Method 'sample_func' is not implemented (Error code: 101): Additional context");
    }
}

