class ct_RndStore {
private:
    mutable std::mutex co_Mutex;
    int so_Data;

public:
    // Constructor to initialize so_Data with a random number between 1 and 100
    ct_RndStore() : so_Data(0) {
        std::random_device rd;
        std::mt19937 engine(rd());
        std::uniform_int_distribution<int> dist(1, 100);
        std::lock_guard<std::mutex> lock(co_Mutex);
        so_Data = dist(engine);
    }

    // Method to swap random number data between two ct_RndStore instances safely
    void Swap(ct_RndStore &other) {
        // Use std::lock to avoid deadlock when locking both mutexes
        std::lock(co_Mutex, other.co_Mutex);
        std::lock_guard<std::mutex> lock1(co_Mutex, std::adopt_lock);
        std::lock_guard<std::mutex> lock2(other.co_Mutex, std::adopt_lock);

        std::swap(so_Data, other.so_Data);
    }
};

