// Function to count how many times a word appears in a text (case-insensitive)
int countWordOccurrences(const std::string& inputText, const std::string& targetWord) {
    // Create lowercase versions of both strings for comparison
    std::string textCopy = inputText;
    std::string wordCopy = targetWord;

    // Convert each character to lowercase manually
    for (char& c : textCopy) {
        c = std::tolower(static_cast<unsigned char>(c));
    }
    for (char& c : wordCopy) {
        c = std::tolower(static_cast<unsigned char>(c));
    }

    int occurrences = 0;
    size_t index = 0;

    // Search for the word repeatedly in the text
    while ((index = textCopy.find(wordCopy, index)) != std::string::npos) {
        occurrences++;
        index += wordCopy.length();  // Move past the current match
    }

    return occurrences;
}

int main() {
    std::string sampleText = "This is a sample text. This text contains the word 'this' multiple times. This is a simple example.";
    std::string searchWord = "this";

    int result = countWordOccurrences(sampleText, searchWord);
    std::cout << "Number of occurrences of the word '" << searchWord << "': " << result << std::endl;

    return 0;
}

