    // Check conditions in reverse order for early exit optimization
    if (m_module) {
        return; // Module already loaded
    }

    if (!m_AlternativeLoad) {
        return; // Alternative loading disabled
    }

    if (!IsAbsolutePath(m_name)) {
        return; // Not an absolute path
    }

    // Load the module with altered search path
    m_module.reset(static_cast<Module*>(LoadLibraryExA(m_name.c_str(), nullptr, LOAD_WITH_ALTERED_SEARCH_PATH)));
}

