int calculateMinimumEnergy(int position5, int position3, CTStructure* ct, EnergyData* data) {
    int minEnergy = INT_MAX;  // Start with maximum possible value for minimization

    // First calculation path: loop type energy with penalties and stacking terms
    int loopEnergy = erg4(position5, position3, position3 - 1, 2, ct, data, lfce[position3 - 1]);
    int penaltyTerm = penalty(position5, position3, ct, data);
    int loopLengthTerm = wmb.f(position5 + 1, position3 - 2);
    int fixedParams = data->eparam[5] + data->eparam[6] + data->eparam[10];

    minEnergy = std::min(minEnergy, loopEnergy + penaltyTerm + loopLengthTerm + fixedParams);

    // Second calculation path: stacking interactions and non-pairing contributions
    int stackingEnergy = data->tstkm[ct->numseq[position5]][ct->numseq[position3]]
                                  [ct->numseq[position5 + 1]][ct->numseq[position3 - 1]];
    int nonPairingTerm = checknp(lfce[position5 + 1], lfce[position3 - 1]);

    minEnergy = std::min(minEnergy, stackingEnergy + nonPairingTerm);

    return minEnergy;  // Return the minimum energy found across all paths
}

