void VertexArray::AddBuffer(const VertexBuffer& buffer, const VertexBufferLayout& layout)
{
    Bind();  // Bind the vertex array object for use

    const auto& elements = layout.GetElements();
    unsigned int byteOffset = 0;

    for (unsigned int index = 0; index < elements.size(); ++index)
    {
        const auto& currentElement = elements[index];

        glEnableVertexAttribArray(index);
        glVertexAttribPointer(
            index,
            currentElement.count,
            currentElement.type,
            currentElement.normalized,
            layout.GetStride(),
            reinterpret_cast<const void*>(byteOffset)
        );

        byteOffset += currentElement.count * VertexBufferElement::GetSizeOfType(currentElement.type);
    }

    buffer.Bind();   // Bind the vertex buffer to the array
    Unbind();        // Release the vertex array binding
}

