#include <vector>
#include <string>
using namespace std;

class Solution {
private:
    void generateExpressions(vector<string>& results, const string& digits, int goal, 
                            string& currentExpression, long long prevOperand, 
                            long long runningTotal, int currentIndex) {
        // Base case: reached end of digit string
        if (currentIndex == digits.length()) {
            if (runningTotal == goal) {
                results.push_back(currentExpression);
            }
            return;
        }

        // Try all possible numbers starting at currentIndex
        for (int j = currentIndex; j < digits.length(); ++j) {
            // Skip numbers with leading zeros (except single "0")
            if (j != currentIndex && digits[currentIndex] == '0') {
                break;
            }

            string numberStr = digits.substr(currentIndex, j - currentIndex + 1);
            long long currentNumber = stoll(numberStr);

            if (currentIndex == 0) {
                // First number in expression - no operator before it
                generateExpressions(results, digits, goal, 
                                   currentExpression + numberStr, 
                                   currentNumber, currentNumber, j + 1);
            } else {
                // Addition
                generateExpressions(results, digits, goal, 
                                   currentExpression + "+" + numberStr, 
                                   currentNumber, runningTotal + currentNumber, j + 1);

                // Subtraction
                generateExpressions(results, digits, goal, 
                                   currentExpression + "-" + numberStr, 
                                   -currentNumber, runningTotal - currentNumber, j + 1);

                // Multiplication (handle precedence by adjusting previous operand)
                long long newPrev = prevOperand * currentNumber;
                long long newTotal = runningTotal - prevOperand + newPrev;
                generateExpressions(results, digits, goal, 
                                   currentExpression + "*" + numberStr, 
                                   newPrev, newTotal, j + 1);
            }
        }
    }

public:
    vector<string> addOperators(string num, int target) {
        vector<string> validExpressions;
        string expressionBuilder;

        // Start recursion with each possible first number
        for (int i = 0; i < num.length(); ++i) {
            // Avoid numbers with leading zeros
            if (i > 0 && num[0] == '0') {
                break;
            }

            string firstNumStr = num.substr(0, i + 1);
            long long firstValue = stoll(firstNumStr);

            generateExpressions(validExpressions, num, target, 
                               firstNumStr, firstValue, firstValue, i + 1);
        }

        return validExpressions;
    }
};

