class TripleMirrorFreqN {
private:
    std::vector<int> dataList;

public:
    TripleMirrorFreqN(const std::vector<int>& input) : dataList(input) {}

    int calculateMirroredCount(int target) {
        // Count occurrences in forward direction
        int forwardCount = 0;
        for (int element : dataList) {
            if (element == target) {
                forwardCount++;
            }
        }

        // For mirrored versions, we traverse the list backwards
        // and count occurrences (equivalent to counting in reversed list)
        int backwardCount = 0;
        for (auto it = dataList.end(); it != dataList.begin(); ) {
            --it;
            if (*it == target) {
                backwardCount++;
            }
        }

        // Return forward count + 3 times backward count
        return forwardCount + 3 * backwardCount;
    }
};

int main() {
    std::vector<int> sampleData = {1, 2, 3, 0, 4, 0, 3, 2, 1};
    TripleMirrorFreqN processor(sampleData);

    int searchValue = 0;
    int result = processor.calculateMirroredCount(searchValue);

    std::cout << "Frequency of " << searchValue << " in the mirrored list: " << result << std::endl;

    return 0;
}

