// Find the next greater element for each element in the array
std::vector<int> next_larger_element(int n, const std::vector<int>& nums) {
    std::vector<int> answer(n, -1);  // Initialize result vector with -1
    std::stack<int> index_stack;  // Stack to keep track of indices

    for (int position = 0; position < n; ++position) {
        // Process elements from stack while current element is greater
        while (!index_stack.empty() && nums[position] > nums[index_stack.top()]) {
            answer[index_stack.top()] = nums[position];  // Set next larger element
            index_stack.pop();  // Remove processed index
        }
        index_stack.push(position);  // Add current index to stack
    }

    return answer;
}

