// Load a PNG image from an input stream and return a Bitmap object
Bitmap LoadPNG(std::istream& stream)
{
    // Read entire stream into a string buffer
    std::string file_data((std::istreambuf_iterator<char>(stream)), std::istreambuf_iterator<char>());

    // Prepare output buffer for decoded image data
    std::vector<unsigned char> image_data;
    unsigned long img_width = 0, img_height = 0;

    // Decode PNG data using PicoPNG library
    int decode_result = decodePNG(image_data, img_width, img_height, 
                                  reinterpret_cast<const unsigned char*>(file_data.c_str()), 
                                  file_data.length());

    // Check for decoding errors
    if (decode_result != 0) {
        Log::Error("Failed to decode PNG: error code " + std::to_string(decode_result));
        return Bitmap(); // Return default-constructed (empty) bitmap on failure
    }

    // Create bitmap with decoded dimensions
    Bitmap result_bitmap(img_width, img_height);

    // Process each pixel from the decoded RGBA data
    for (unsigned long row = 0; row < img_height; ++row) {
        for (unsigned long col = 0; col < img_width; ++col) {
            unsigned long index = (row * img_width + col) * 4;

            // Extract color components in RGBA order
            unsigned char red   = image_data[index];
            unsigned char green = image_data[index + 1];
            unsigned char blue  = image_data[index + 2];
            unsigned char alpha = image_data[index + 3];

            // Set pixel in bitmap
            result_bitmap.SetPixel(col, row, Color(red, green, blue, alpha));
        }
    }

    return result_bitmap;
}

