namespace phaeton {
    // Enumeration for fundamental data categories
    enum DataType {
        INTEGER,
        DECIMAL,
        TEXTUAL
    };

    class TypeDescriptor {
    private:
        std::string name;
        DataType category;
        std::vector<TypeDescriptor> customTypes;

    public:
        TypeDescriptor(const std::string& typeName, DataType kind) 
            : name(typeName), category(kind) {}

        // Accessor to obtain the type's identifier
        std::string getName() const {
            return name;
        }

        // Function to append a custom-defined type
        void appendCustomType(const TypeDescriptor& type) {
            customTypes.emplace_back(type);
        }

        // Heuristic for determining resulting type from two operands
        TypeDescriptor deduceType(const TypeDescriptor& first, const TypeDescriptor& second) {
            // Determine promoted type based on operand kinds
            // For instance: INTEGER + DECIMAL => DECIMAL
            if (first.category == DECIMAL || second.category == DECIMAL) {
                return TypeDescriptor("DECIMAL", DECIMAL);
            }
            if (first.category == INTEGER && second.category == INTEGER) {
                return TypeDescriptor("INTEGER", INTEGER);
            }
            return TypeDescriptor("TEXTUAL", TEXTUAL);
        }

        // Validation of type compatibility between two operands
        bool validateCompatibility(const TypeDescriptor& left, const TypeDescriptor& right) {
            // Basic compatibility rules: same category or compatible numeric types
            if (left.category == right.category) {
                return true;
            }
            // Allow mixing INTEGER and DECIMAL
            if ((left.category == INTEGER && right.category == DECIMAL) ||
                (left.category == DECIMAL && right.category == INTEGER)) {
                return true;
            }
            return false;
        }
    };
}  // namespace phaeton

