class StockSpanner {
    stack<pair<int, int>> spans; // stores price and consecutive span count

public:
    StockSpanner() {
        // Constructor - no initialization needed for stack
    }

    int next(int currentPrice) {
        int spanLength = 1;

        // Accumulate spans of all previous days with price <= current price
        while (!spans.empty() && spans.top().first <= currentPrice) {
            spanLength += spans.top().second;
            spans.pop();
        }

        // Store current price and its calculated span
        spans.push(make_pair(currentPrice, spanLength));
        return spanLength;
    }
};

