// Perform pixel-wise multiplication operations between corresponding image components
std::pair<cv::Mat, cv::Mat> performImageProcessing(const ImageSet& source, const ImageSet& target) {
    // Create result matrices with same dimensions and type as inputs
    cv::Mat squaredProduct(source.imageSquare.size(), source.imageSquare.type());
    cv::Mat blurredProduct(source.imageBlur.size(), source.imageBlur.type());

    // Compute element-wise products using manual iteration
    for (int y = 0; y < source.imageSquare.rows; ++y) {
        for (int x = 0; x < source.imageSquare.cols; ++x) {
            squaredProduct.at<uchar>(y, x) = source.imageSquare.at<uchar>(y, x) * 
                                             target.imageSquare.at<uchar>(y, x);
        }
    }

    for (int y = 0; y < source.imageBlur.rows; ++y) {
        for (int x = 0; x < source.imageBlur.cols; ++x) {
            blurredProduct.at<uchar>(y, x) = source.imageBlur.at<uchar>(y, x) * 
                                             target.imageBlur.at<uchar>(y, x);
        }
    }

    return std::make_pair(squaredProduct, blurredProduct);
}

