// Simulated span class (simplified version)
template<typename T>
class span {
public:
    span(T* ptr, size_t count) : m_ptr(ptr), m_count(count) {}
    T& operator[](size_t idx) { return m_ptr[idx]; }
    const T& operator[](size_t idx) const { return m_ptr[idx]; }
    size_t size() const { return m_count; }
private:
    T* m_ptr;
    size_t m_count;
};

class VertexArray {
public:
    VertexArray(span<VertexAttribute> attribs) {
        // Calculate the total stride required for the vertex attributes
        int totalStride = 0;
        for (const auto& attrib : attribs) {
            totalStride += attrib.size * getSizeOfType(attrib.type);
        }

        // Generate and bind the vertex array object
        glGenVertexArrays(1, &mVertexArrayID);
        glBindVertexArray(mVertexArrayID);

        // Enable and configure each vertex attribute using while loop instead of for loop
        size_t i = 0;
        int offset = 0;
        while (i < attribs.size()) {
            const auto& attrib = attribs[i];
            glEnableVertexAttribArray(static_cast<GLuint>(i));
            glVertexAttribPointer(static_cast<GLuint>(i), attrib.size, attrib.type, GL_FALSE, 
                                 totalStride, reinterpret_cast<void*>(offset));
            offset += attrib.size * getSizeOfType(attrib.type);
            ++i;
        }

        // Unbind the vertex array
        glBindVertexArray(0);
    }

private:
    GLuint mVertexArrayID;
};

