// Remove a specific card from the hand and return it; if not found, return default Card
Card Hand::removeCard(const Card& targetCard)
{
    auto iter = std::find_if(cards.begin(), cards.end(),
        [&targetCard](const Card& c) { return c == targetCard; });

    if (iter != cards.end())
    {
        Card extracted = *iter;
        cards.erase(iter);
        return extracted;
    }

    // Provide fallback: return an empty/default card instance
    return Card{};
}

// Collect IDs of cards satisfying a given condition
std::list<CardId> Hand::getIds(std::function<bool(const Card&)> condition)
{
    std::list<CardId> resultIds;

    for (const Card& currentCard : cards)
    {
        if (condition(currentCard))
        {
            resultIds.push_back(currentCard.id);
        }
    }

    return resultIds;
}

