// Alternative implementation for building jump instructions
void Asm_x64::build_jmp(LtacNode *node) {
    auto jmp = static_cast<LtacJmp *>(node);

    // Map each operator to its corresponding assembly instruction
    const char* instruction = nullptr;

    switch (jmp->op) {
        case Operator::None: 
            instruction = "\tjmp ";
            break;
        case Operator::Equal: 
            instruction = "\tje ";
            break;
        case Operator::NotEqual: 
            instruction = "\tjne ";
            break;
        case Operator::Greater: 
            instruction = "\tjg ";
            break;
        case Operator::Less: 
            instruction = "\tjl ";
            break;
        case Operator::GreaterEq: 
            instruction = "\tjge ";
            break;
        case Operator::LessEq: 
            instruction = "\tjle ";
            break;
    }

    // Output the selected instruction
    if (instruction != nullptr) {
        writer << instruction;
    }
}

