struct ScalaFpgaRawHeader {
    uint16_t m_minApdOffset;
    uint16_t m_maxApdOffset;
    uint16_t m_frequencyInteger;
    uint16_t m_frequencyFractional;
    uint16_t m_deviceId;
    uint16_t m_reservedHeader7;
};

bool parseHeader(const uint8_t* rawData, size_t dataSize, ScalaFpgaRawHeader& header) {
    // Check if raw data is large enough to contain the full header
    constexpr size_t headerSize = sizeof(ScalaFpgaRawHeader);
    if (dataSize < headerSize) {
        return false;  // Not enough bytes for a complete header
    }

    // Read each 16-bit field in little-endian format using pointer arithmetic
    const uint8_t* ptr = rawData;

    header.m_minApdOffset = static_cast<uint16_t>((ptr[1] << 8) | ptr[0]);
    header.m_maxApdOffset = static_cast<uint16_t>((ptr[3] << 8) | ptr[2]);
    header.m_frequencyInteger = static_cast<uint16_t>((ptr[5] << 8) | ptr[4]);
    header.m_frequencyFractional = static_cast<uint16_t>((ptr[7] << 8) | ptr[6]);
    header.m_deviceId = static_cast<uint16_t>((ptr[9] << 8) | ptr[8]);
    header.m_reservedHeader7 = static_cast<uint16_t>((ptr[11] << 8) | ptr[10]);

    return true;  // Successfully parsed all header fields
}

