class LegoI2C {
private:
    std::vector<uint8_t> m_receive_buffer;
    mutable std::mutex m_buffer_mutex;
public:
    void transmit(uint8_t byte) {
        std::lock_guard<std::mutex> lock(m_buffer_mutex);
        m_receive_buffer.push_back(byte);
    }

    uint8_t receive() {
        std::lock_guard<std::mutex> lock(m_buffer_mutex);
        if (m_receive_buffer.empty()) {
            return 0; // Return default value when buffer is empty
        }
        uint8_t byte = m_receive_buffer.front();
        m_receive_buffer.erase(m_receive_buffer.begin());
        return byte;
    }
};

#include <stxxl/vector>
#include <stxxl/algorithm>
#include <vector>

// Perform parallel multiway merge on sorted sequences using STXXL
std::vector<int> parallelMultiwayMerge(const std::vector<std::vector<int>>& sortedSequences) {
    // Handle empty input case
    if (sortedSequences.empty()) {
        return std::vector<int>();
    }

    // Prepare STXXL vectors
    stxxl::vector<int> mergedInput;
    std::vector<stxxl::vector<int>::iterator> rangeIterators;

    // Flatten all sorted sequences into one STXXL vector while tracking boundaries
    for (const auto& seq : sortedSequences) {
        size_t startPos = mergedInput.size();
        mergedInput.insert(mergedInput.end(), seq.begin(), seq.end());
        size_t endPos = mergedInput.size();
        rangeIterators.push_back(mergedInput.begin() + startPos);
    }
    rangeIterators.push_back(mergedInput.end());

    // Create output vector with appropriate size
    stxxl::vector<int> stxxlOutput(mergedInput.size());

    // Perform parallel multiway merge with correct iterator setup
    stxxl::parallel_multiway_merge(
        rangeIterators.begin(), rangeIterators.end(),
        stxxlOutput.begin(),
        sortedSequences.size()
    );

    // Transfer results back to standard vector
    std::vector<int> result;
    result.resize(stxxlOutput.size());
    for (size_t i = 0; i < stxxlOutput.size(); ++i) {
        result[i] = stxxlOutput[i];
    }

    return result;
}

