// Helper to generate timestamp (assumed to exist elsewhere)
uint64_t getCurrentTimeStamp();

class ssTable {
public:
    static ssTable genTable(const std::string& path, uint64_t ts, const std::vector<std::pair<std::string, std::string>>& kvs);
    void addKeyValuePair(const std::string& key, const std::string& value);
    void updateMetadata(uint64_t ts, size_t size);
};

void addToSSTable(int targetLevel, const std::string& targetDir, const std::string& key, const std::string& val,
                  std::vector<std::vector<ssTable>>& levelArray, std::vector<int>& nextLabel,
                  uint64_t& tmpTimeStamp, uint64_t& tmpSize, std::vector<std::pair<std::string, std::string>>& tmp) {
    // Construct SSTable file path using current label for this level
    std::string sstablePath = targetDir + "/" + std::to_string(nextLabel[targetLevel]) + ".sst";

    // Create new SSTable instance with current batch data
    ssTable newTable = ssTable::genTable(sstablePath, tmpTimeStamp, tmp);
    levelArray[targetLevel].push_back(newTable);

    // Advance label counter for next SSTable at this level
    ++nextLabel[targetLevel];

    // Reset temporary buffer state
    tmp.clear();
    tmpTimeStamp = 0;
    tmpSize = 0;

    // Insert the new key-value pair into the temporary buffer
    tmp.emplace_back(key, val);

    // Accumulate size: value bytes + timestamp (8B) + size field (4B)
    tmpSize += static_cast<uint64_t>(val.size() + sizeof(uint64_t) + sizeof(uint32_t));

    // Initialize timestamp only if not already set
    if (tmpTimeStamp == 0) {
        tmpTimeStamp = getCurrentTimeStamp();
    }

    // Sort entries in ascending order by key
    std::sort(tmp.begin(), tmp.end(),
              [](const auto& lhs, const auto& rhs) { return lhs.first < rhs.first; });

    // Populate the newly created SSTable with sorted key-value pairs
    for (const auto& entry : tmp) {
        levelArray[targetLevel].back().addKeyValuePair(entry.first, entry.second);
    }

    // Finalize metadata for the SSTable
    levelArray[targetLevel].back().updateMetadata(tmpTimeStamp, tmpSize);
}

