// Write point cloud data to a PLY file in binary little-endian format
void PointCloud::writePLY(std::string filePath, cv::Mat pointData) {
  std::ofstream output(filePath, std::ios::out | std::ios::binary);
  if (!output.is_open()) {
    std::cerr << "Error: Could not open file for writing" << std::endl;
    return;
  }

  int totalPoints = pointData.rows;
  int channelCount = pointData.cols;

  // Construct and write the PLY header
  output << "ply\n";
  output << "format binary_little_endian 1.0\n";
  output << "element vertex " << totalPoints << "\n";
  output << "property float x\n";
  output << "property float y\n";
  output << "property float z\n";
  output << "end_header\n";

  // Iterate through each point and write its coordinates
  for (int idx = 0; idx < totalPoints; ++idx) {
    float px = pointData.at<float>(idx, 0);
    float py = pointData.at<float>(idx, 1);
    float pz = pointData.at<float>(idx, 2);

    output.write(reinterpret_cast<const char*>(&px), sizeof(float));
    output.write(reinterpret_cast<const char*>(&py), sizeof(float));
    output.write(reinterpret_cast<const char*>(&pz), sizeof(float));
  }

  output.close();
}

