#include <dwarf.h>
#include <vector>

// Helper function to get DIE offset safely
Dwarf_Off GetDieOffset(Dwarf_Die die) {
    Dwarf_Error err;
    return dwarf_dieoffset(die);
}

TOptional<DwarfNode> NextChild() override
{
    Dwarf_Error error;
    int result;

    // Attempt to get the first child of the current DIE
    if (dwarf_child(mCurrentDie, &mCurrentDie, &error) == DW_DLV_OK) {
        mParents.emplace_back(mCurrentDie);
        return TOptional<DwarfNode>(mCurrentDie);
    }

    // Backtrack through parent nodes to find next sibling or child
    while (!mParents.empty()) {
        Dwarf_Off currentOffset = GetDieOffset(mCurrentDie);
        Dwarf_Off parentOffset = GetDieOffset(mParents.back());

        if (currentOffset == parentOffset) {
            // We've returned to a parent; try its next child
            mCurrentDie = mParents.back();
            mParents.pop_back();

            if (dwarf_child(mCurrentDie, &mCurrentDie, &error) == DW_DLV_OK) {
                mParents.emplace_back(mCurrentDie);
                return TOptional<DwarfNode>(mCurrentDie);
            }
        } else {
            // Move up one level in the tree
            mParents.pop_back();
        }
    }

    // No more children available
    return TOptional<DwarfNode>();
}

