// Perform arithmetic operations based on the given operator
double Compute(double operand1, double operand2, char operation) {
    switch (operation) {
        case '+':
            return operand1 + operand2;
        case '-':
            return operand1 - operand2;
        case '*':
            return operand1 * operand2;
        case '/':
            if (operand2 == 0.0) {
                std::cerr << "Error: Division by zero" << std::endl;
                return 0.0;
            }
            return operand1 / operand2;
        default:
            std::cerr << "Error: Invalid operator" << std::endl;
            return 0.0;
    }
}

int main() {
    // Test cases
    std::cout << Compute(2.0, 3.0, '+') << std::endl;  // Output: 5.0
    std::cout << Compute(5.0, 2.0, '-') << std::endl;  // Output: 3.0
    std::cout << Compute(4.0, 2.0, '*') << std::endl;  // Output: 8.0
    std::cout << Compute(6.0, 3.0, '/') << std::endl;  // Output: 2.0
    std::cout << Compute(8.0, 0.0, '/') << std::endl;  // Output: Error: Division by zero, 0.0
    std::cout << Compute(4.0, 3.0, '%') << std::endl;  // Output: Error: Invalid operator, 0.0
    return 0;
}

