// Calculate GCD using iterative Euclidean algorithm with swapped parameters handling
int greatestCommonDivisor(int a, int b) {
    // Ensure non-negative values for consistent behavior
    if (a < 0) a = -a;
    if (b < 0) b = -b;

    // Handle zero cases explicitly
    if (a == 0) return b;
    if (b == 0) return a;

    // Perform Euclidean algorithm iterations
    while (b != 0) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

// Compute LCM using the relationship: lcm(a,b) = |a*b| / gcd(a,b)
int leastCommonMultiple(int a, int b) {
    if (a == 0 || b == 0) return 0;

    // Use absolute values to handle negative inputs correctly
    int absA = (a < 0) ? -a : a;
    int absB = (b < 0) ? -b : b;

    // Avoid potential overflow by dividing before multiplying
    return absA / greatestCommonDivisor(a, b) * absB;
}

int main() {
    // Test cases demonstrating GCD and LCM calculations
    std::cout << "GCD of 12 and 18: " << greatestCommonDivisor(12, 18) << std::endl; // Output: 6
    std::cout << "LCM of 12 and 18: " << leastCommonMultiple(12, 18) << std::endl;   // Output: 36
    std::cout << "GCD of 15 and 25: " << greatestCommonDivisor(15, 25) << std::endl; // Output: 5
    std::cout << "LCM of 15 and 25: " << leastCommonMultiple(15, 25) << std::endl;   // Output: 75
    std::cout << "GCD of 17 and 31: " << greatestCommonDivisor(17, 31) << std::endl; // Output: 1
    std::cout << "LCM of 17 and 31: " << leastCommonMultiple(17, 31) << std::endl;   // Output: 527

    return 0;
}

