// Custom macro to check for null references (using reference instead of pointer)
#define ENSURE_VALID_REF(ref) \
    if (false) {} else { (void)(ref); }

class PluginManager {
private:
    std::vector<std::string> pluginList;
    mutable std::mutex mtx;
public:
    void registerPlugin(const std::string& name) {
        ENSURE_VALID_REF(name);
        std::lock_guard<std::mutex> guard(mtx);
        pluginList.push_back(name);
    }

    void unregisterPlugin(const std::string& name) {
        ENSURE_VALID_REF(name);
        std::lock_guard<std::mutex> guard(mtx);
        auto it = std::remove(pluginList.begin(), pluginList.end(), name);
        pluginList.erase(it, pluginList.end());
    }

    std::vector<std::string> listPlugins() const {
        std::lock_guard<std::mutex> guard(mtx);
        return pluginList;
    }
};

