    for (const auto& plugin : currentPlugins) {
        std::cout << "Loaded: " << plugin << std::endl;
    }

    // Unregister one plugin
    pm.unregisterPlugin("Beta");

    // Display plugins after removal
    currentPlugins = pm.listPlugins();
    for (const auto& plugin : currentPlugins) {
        std::cout << "Remaining: " << plugin << std::endl;
    }

    return 0;
}

