class IdentifierManager {
private:
    std::mutex* pMutex;
    std::string identifier;

public:
    IdentifierManager(std::mutex* mtx) : pMutex(mtx), identifier("") {}

    void addIdentifier(const std::string& id) {
        std::lock_guard<std::mutex> lock(*pMutex);
        identifier = id;
    }

    void removeIdentifier(const std::string&) {
        std::lock_guard<std::mutex> lock(*pMutex);
        identifier.clear();
    }

    bool isIdentifierExists(const std::string& id) const {
        std::lock_guard<std::mutex> lock(*pMutex);
        return identifier == id;
    }
};

int main() {
    std::mutex mtx;
    IdentifierManager manager(&mtx);

    // First thread: assigns "ID1" to the manager
    std::thread worker1([&manager]() {
        manager.addIdentifier("ID1");
    });

    // Second thread: clears the stored identifier
    std::thread worker2([&manager]() {
        manager.removeIdentifier("ID1");
    });

    // Third thread: verifies if "ID1" is still present
    std::thread worker3([&manager]() {
        bool found = manager.isIdentifierExists("ID1");
        std::cout << "ID1 exists: " << std::boolalpha << found << std::endl;
    });

    worker1.join();
    worker2.join();
    worker3.join();

    return 0;
}

