// Class to generate random integers within a specified range
class RandomIntegerGenerator {
private:
    mt19937 engine;  // Mersenne Twister pseudo-random number engine
    uniform_int_distribution<int> rangeDist;

public:
    // Constructor initializes the generator with given min and max values
    RandomIntegerGenerator(int lowerBound, int upperBound) 
        : engine(duration_cast<milliseconds>(system_clock::now().time_since_epoch()).count()),
          rangeDist(lowerBound, upperBound) {}

    // Generate a single random number within the current range
    int produce() {
        return rangeDist(engine);
    }

    // Update the valid range for generated numbers
    void adjustBounds(int newLower, int newUpper) {
        rangeDist = uniform_int_distribution<int>(newLower, newUpper);
    }
};

int main() {
    // Initialize generator with range [1, 100]
    RandomIntegerGenerator gen(1, 100);

    // Output first batch of 10 random numbers
    for (int count = 0; count < 10; ++count) {
        cout << gen.produce() << " ";
    }
    cout << endl;

    // Adjust range to [50, 150]
    gen.adjustBounds(50, 150);

    // Output second batch of 10 random numbers in the new range
    for (int count = 0; count < 10; ++count) {
        cout << gen.produce() << " ";
    }
    cout << endl;

    return 0;
}

