// Custom transition class that extends guarded_action_transition
template <typename EventT, typename Predicate, typename Callable>
class CustomTransition : public skizzay::fsm::guarded_action_transition<EventT> {
public:
    CustomTransition(EventT evt, Predicate pred, Callable func)
        : skizzay::fsm::guarded_action_transition<EventT>(evt), 
          predicate_(pred), function_(func) {}

    bool check_condition() const override {
        return predicate_();
    }

    void perform_action() const override {
        function_();
    }

private:
    Predicate predicate_;
    Callable function_;
};

// Define custom state and event types
enum class MachineState { INITIAL, FINAL };
enum class Signal { ACTIVATE };

int main() {
    // Define guard condition and action as lambdas
    auto is_allowed = []() -> bool { return true; };
    auto on_execute = []() { std::cout << "Action executed successfully" << std::endl; };

    // Instantiate the custom transition
    CustomTransition<Signal, decltype(is_allowed), decltype(on_execute)> 
        my_transition(Signal::ACTIVATE, is_allowed, on_execute);

    // Initialize the finite state machine
    skizzay::fsm::finite_state_machine<MachineState, Signal> machine(MachineState::INITIAL);

    // Register the transition from INITIAL to FINAL
    machine.add_transition(MachineState::INITIAL, Signal::ACTIVATE, MachineState::FINAL, my_transition);

    // Process the event to trigger the transition
    machine.process_event(Signal::ACTIVATE);

    return 0;
}

