// Normalize the result of element-wise multiplication of two images to [0,1]
cv::Mat normalizeImage(cv::Mat image1, cv::Mat image2) {
    // Compute element-wise product of the input images
    cv::Mat product = image1.mul(image2);

    // Determine the range of pixel values in the product matrix
    double minVal, maxVal;
    cv::minMaxLoc(product, &minVal, &maxVal);

    // Avoid division by zero when all pixels have the same value
    double range = maxVal - minVal;
    if (range == 0) {
        range = 1.0;  // Prevent division by zero
    }

    // Scale and shift pixel values to fit within [0, 1]
    cv::Mat normalized;
    product.convertTo(normalized, CV_64F, 1.0 / range, -minVal / range);

    return normalized;
}

