// Template function to compute maximum of two values (device and host callable)
template <typename T>
__host__ __device__ T odin_max(T a, T b) {
  return (a >= b) ? a : b;
}

// Host-side demonstration using odin_max
void cpuMaxDemo() {
  int x = 10, y = 20;
  int maxValue = odin_max(x, y);
  std::cout << "CPU Max Result: " << maxValue << std::endl;
}

// Device kernel: computes element-wise maximum of two arrays
__global__ void gpuMaxDemo(int* inputA, int* inputB, int* output, int length) {
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx < length) {
    output[idx] = odin_max(inputA[idx], inputB[idx]);
  }
}

int main() {
  // Run CPU demonstration
  cpuMaxDemo();

  // GPU demonstration setup
  const int arraySize = 5;
  int hostData1[arraySize] = {1, 5, 3, 7, 9};
  int hostData2[arraySize] = {4, 2, 8, 6, 0};
  int hostOutput[arraySize];

  int* deviceData1, *deviceData2, *deviceOutput;

  // Allocate memory on device
  cudaMalloc((void**)&deviceData1, arraySize * sizeof(int));
  cudaMalloc((void**)&deviceData2, arraySize * sizeof(int));
  cudaMalloc((void**)&deviceOutput, arraySize * sizeof(int));

  // Copy data from host to device
  cudaMemcpy(deviceData1, hostData1, arraySize * sizeof(int), cudaMemcpyHostToDevice);
  cudaMemcpy(deviceData2, hostData2, arraySize * sizeof(int), cudaMemcpyHostToDevice);

  // Launch kernel with one block containing 'arraySize' threads
  gpuMaxDemo<<<1, arraySize>>>(deviceData1, deviceData2, deviceOutput, arraySize);

  // Synchronize to ensure completion before copying back
  cudaDeviceSynchronize();

  // Copy results back to host
  cudaMemcpy(hostOutput, deviceOutput, arraySize * sizeof(int), cudaMemcpyDeviceToHost);

  // Print GPU results
  std::cout << "GPU Max Results: ";
  for (int i = 0; i < arraySize; ++i) {
    std::cout << hostOutput[i] << " ";
  }
  std::cout << std::endl;

  // Free device memory
  cudaFree(deviceData1);
  cudaFree(deviceData2);
  cudaFree(deviceOutput);

  return 0;
}

