// Apply graph transformation by inserting quantization-related operations
void applyGraphOptimization(Operation* operation, Tensor* sourceTensor, Tensor* targetTensor) {
    // Instantiate new nodes for the transformed subgraph
    Operation* quant_node = new Operation("output_quant");
    Operation* multiply_node = new Operation("mul");
    Operation* maximum_node = new Operation("max");
    Tensor* scaling_factor = new Tensor("alpha");
    Tensor* dequantized_input = new Tensor("input_dequant");

    // Rename the quantization node and wire it into the graph
    std::string original_name = std::string(sourceTensor->name()->string_view());
    quant_node->name(original_name + "/output_quant");
    quant_node->input().connect(maximum_node->output());

    // Establish connections among newly created operations
    multiply_node->input_b().connect(scaling_factor->output());
    multiply_node->input_a().connect(dequantized_input->output());
    maximum_node->input_b().connect(multiply_node->output());
    maximum_node->input_a().connect(dequantized_input->output());

    // Attach the original tensors to the transformed subgraph
    connect_input_tensor(&dequantized_input->input(), sourceTensor);
    connect_output_tensor(targetTensor, &quant_node->output());
}

