// A class that handles value processing differently based on value category
class ValueProcessor {
private:
    int internalValue;
public:
    ValueProcessor() : internalValue(0) {}

    // Overload for lvalue references - adds the value to internal storage
    void handle(int& val) & {
        internalValue += val;
    }

    // Overload for rvalue references - subtracts the value from internal storage
    void handle(int&& val) && {
        internalValue -= val;
    }

    // Getter for accessing the stored value
    int getValue() const {
        return internalValue;
    }
};

int main() {
    ValueProcessor processor1;
    int x = 5;
    processor1.handle(x);  // Binds to lvalue reference overload, adds 5
    std::cout << "Internal value after lvalue handling: " << processor1.getValue() << std::endl;

    ValueProcessor processor2;
    processor2.handle(3);  // Binds to rvalue reference overload, subtracts 3
    std::cout << "Internal value after rvalue handling: " << processor2.getValue() << std::endl;

    return 0;
}

