// Performance measurement utility using high-resolution clock
class TimingMonitor {
private:
    // Map to store start times for different code sections
    static std::map<std::string, std::chrono::high_resolution_clock::time_point> startTimeMap;

public:
    // Reset all timing data
    static void reset() {
        startTimeMap.clear();
    }

    // Record the start time for a named section
    static void beginSection(const std::string& label) {
        startTimeMap[label] = std::chrono::high_resolution_clock::now();
    }

    // Calculate and report elapsed time for a section, then remove it
    static void endSection(const std::string& label) {
        auto iter = startTimeMap.find(label);
        if (iter != startTimeMap.end()) {
            auto finishTime = std::chrono::high_resolution_clock::now();
            auto startTime = iter->second;
            double durationMs = std::chrono::duration_cast<std::chrono::milliseconds>(
                finishTime - startTime).count();
            std::cerr << "Duration for '" << label << "': " << durationMs << " ms\n";
            startTimeMap.erase(iter);
        }
    }

    // Get elapsed time without removing the section (returns 0 if not found)
    static double elapsed(const std::string& label) {
        auto iter = startTimeMap.find(label);
        if (iter != startTimeMap.end()) {
            auto currentTime = std::chrono::high_resolution_clock::now();
            auto startTime = iter->second;
            return std::chrono::duration_cast<std::chrono::milliseconds>(
                currentTime - startTime).count();
        }
        return 0.0;
    }

    // Print status of active timing sections
    static void showActiveSections() {
        std::cerr << "Active Timing Sections:\n";
        for (const auto& pair : startTimeMap) {
            std::cerr << "  '" << pair.first << "' is running\n";
        }
    }
};

