const uint32_t DEFAULT_SEQUENCE = 0xFFFFFFFF;
const size_t SEQUENCE_SIZE = sizeof(uint32_t);

class TxIn {
 private:
  struct OutPoint {
    // Implementation details of OutPoint
  };
  OutPoint prevOut;
  std::vector<uint8_t> scriptSig;
  uint32_t sequence;

 public:
  // Method to serialize the TxIn object into a byte stream
  std::vector<uint8_t> serialize() {
    std::vector<uint8_t> resultBuffer;

    // Serialize the prevOut struct by copying its raw bytes
    const uint8_t* outPointStart = reinterpret_cast<const uint8_t*>(&prevOut);
    const uint8_t* outPointEnd = outPointStart + sizeof(OutPoint);
    resultBuffer.insert(resultBuffer.end(), outPointStart, outPointEnd);

    // Add the scriptSig content to the buffer
    resultBuffer.insert(resultBuffer.end(), scriptSig.begin(), scriptSig.end());

    // Convert sequence to big-endian format before appending
    uint32_t beSequence = htobe32(sequence);
    const uint8_t* seqBytes = reinterpret_cast<const uint8_t*>(&beSequence);
    for (size_t i = 0; i < SEQUENCE_SIZE; ++i) {
      resultBuffer.push_back(seqBytes[i]);
    }

    return resultBuffer;
  }
};

