class Vec3 {
public:
    double x, y, z;

    // Constructor with member initializer list
    Vec3(double a, double b, double c) : x(a), y(b), z(c) {}

    // Overloaded + operator: returns a new Vec3 object
    Vec3 operator+(const Vec3 &rhs) const {
        return Vec3(x + rhs.x, y + rhs.y, z + rhs.z);
    }

    // Overloaded += operator: modifies the current object and returns a reference to it
    Vec3& operator+=(const Vec3 &rhs) {
        x += rhs.x;
        y += rhs.y;
        z += rhs.z;
        return *this;
    }
};

int main() {
    // Initialize two 3D vectors
    Vec3 vectorA(1.0, 2.0, 3.0);
    Vec3 vectorB(4.0, 5.0, 6.0);

    // Perform vector addition using overloaded +
    Vec3 result = vectorA + vectorB;
    std::cout << "Sum: (" << result.x << ", " << result.y << ", " << result.z << ")" << std::endl;

    // Perform in-place addition using overloaded +=
    vectorA += vectorB;
    std::cout << "vectorA after addition: (" << vectorA.x << ", " << vectorA.y << ", " << vectorA.z << ")" << std::endl;

    return 0;
}

