class EngineLog {
public:
    EngineLog(const std::string& loggerName, const std::string& fmt) {
        baseLogger = spdlog::stdout_color_mt(loggerName);
        baseLogger->set_pattern(fmt);
    }

    void enableConsoleOutput() {
        baseLogger->sinks().push_back(std::make_shared<spdlog::sinks::stdout_color_sink_mt>());
    }

    void attachFileOutput(const std::string& filePath) {
        baseLogger->sinks().push_back(std::make_shared<spdlog::sinks::basic_file_sink_mt>(filePath, true));
    }

    void write(Severity severity, const std::string& text) {
        switch (severity) {
            case Severity::Debug:
                baseLogger->info(text);
                break;
            case Severity::Warn:
                baseLogger->warn(text);
                break;
            case Severity::Critical:
                baseLogger->error(text);
                break;
        }
    }

private:
    std::shared_ptr<spdlog::logger> baseLogger;
};

int main() {
    EngineLog systemLogger("SystemLogger", "[%Y-%m-%d %H:%M:%S] [%n] [%^%l%$] %v");
    systemLogger.enableConsoleOutput();
    systemLogger.attachFileOutput("system.log");
    systemLogger.write(Severity::Debug, "System initialized.");
    systemLogger.write(Severity::Warn, "Resource usage high.");
    systemLogger.write(Severity::Critical, "Fatal exception: system halt.");
    return 0;
}

