// Template structure for binary operations with identity element
template <typename T>
struct OperationHandler {
  static T identity;  // Identity value for the operation

  // Apply the binary operation to combine two values
  static T combine(T first, T second) {
    return first + second;  // Default: addition operation
  }
};

// Initialize the identity element (0 for addition)
template <typename T>
T OperationHandler<T>::identity = 0;

// Main processing function - transformed version
template <typename Iter1, typename Iter2, typename ValType1, typename ValType2, typename StorageContainer>
void transformAccumulatedValues(Iter1 start1, Iter1 finish1, Iter2 start2, 
                                const StorageContainer& neighborList, 
                                const StorageContainer& validIndices, 
                                const StorageContainer& inputValue, 
                                StorageContainer& outputValue) {
  // Process each element in the input range
  while (start1 != finish1) {
    // Start with identity element for accumulation
    ValType1 accumulated = OperationHandler<ValType1>::identity;

    // Iterate through neighbors using index-based loop
    for (size_t i = 0; i < neighborList.size(); ++i) {
      auto neighborOffset = neighborList[i];
      auto computedIndex = *start1 + neighborOffset;

      // Skip if index is not in valid set
      if (validIndices.find(computedIndex) == validIndices.end()) {
        continue;
      }

      // Accumulate using the binary operation
      accumulated = OperationHandler<ValType1>::combine(accumulated, inputValue[computedIndex]);
    }

    // Store result after type conversion
    outputValue[*start2] = static_cast<ValType2>(accumulated);

    // Advance iterators
    ++start1;
    ++start2;
  }
}

#include <iostream>
#include <Eigen/Dense>

// Extract region of interest data for a specific batch index
Eigen::MatrixXf get_batch_rois(int batch_id, const Eigen::MatrixXf& ground_truth, const Eigen::MatrixXf& proposals) {
    // Count how many ground truth entries belong to the specified batch
    int gt_count = 0;
    for (int i = 0; i < ground_truth.rows(); ++i) {
        if (static_cast<int>(ground_truth(i, 0)) == batch_id) {
            ++gt_count;
        }
    }

    // Prepare matrix for batch-specific ground truth boxes
    Eigen::MatrixXf batch_gt(gt_count, ground_truth.cols());
    for (int i = 0, j = 0; i < ground_truth.rows(); ++i) {
        if (static_cast<int>(ground_truth(i, 0)) == batch_id) {
            batch_gt.row(j++) = ground_truth.row(i);
        }
    }

    // Count how many proposals belong to the specified batch
    int roi_count = 0;
    for (int i = 0; i < proposals.rows(); ++i) {
        if (static_cast<int>(proposals(i, 0)) == batch_id) {
            ++roi_count;
        }
    }

    // Prepare matrix for batch-specific ROIs (excluding the batch index column)
    Eigen::MatrixXf batch_proposals(roi_count, proposals.cols() - 1);
    for (int i = 0, j = 0; i < proposals.rows(); ++i) {
        if (static_cast<int>(proposals(i, 0)) == batch_id) {
            batch_proposals.row(j++) = proposals.block(i, 1, 1, 4);
        }
    }

    return batch_proposals;
}

int main() {
    // Initialize ground truth boxes: [batch_id, x1, y1, x2, y2]
    Eigen::MatrixXf gt_boxes(5, 4);
    gt_boxes << 1, 2, 3, 4,
                2, 3, 4, 5,
                1, 2, 3, 4,
                2, 3, 4, 5,
                3, 4, 5, 6;

    // Initialize all region proposals: [batch_id, x1, y1, x2, y2]
    Eigen::MatrixXf all_rois(8, 5);
    all_rois << 1, 10, 20, 30, 40,
                2, 15, 25, 35, 45,
                1, 12, 22, 32, 42,
                2, 17, 27, 37, 47,
                3, 11, 21, 31, 41,
                1, 14, 24, 34, 44,
                2, 19, 29, 39, 49,
                3, 16, 26, 36, 46;

    int target_batch = 2;
    Eigen::MatrixXf result = get_batch_rois(target_batch, gt_boxes, all_rois);

    std::cout << "ROIs for batch " << target_batch << ":\n" << result << std::endl;
    return 0;
}

