void extractQueryParts(const std::string& sqlStatement) {
    std::string selectedFields, tableName, filterClause;
    std::istringstream stream(sqlStatement);
    std::string keyword1, keyword2, keyword3;

    // Extract tokens from the SQL query
    stream >> keyword1 >> selectedFields >> keyword2 >> tableName >> keyword3 >> filterClause;

    // Clean up trailing comma in column list if present
    if (!selectedFields.empty() && selectedFields.back() == ',') {
        selectedFields.pop_back();
    }

    // Output parsed components
    std::cout << "Table: " << tableName << std::endl;
    std::cout << "Columns:" << std::endl;

    // Split and print individual columns
    std::istringstream fieldStream(selectedFields);
    std::string fieldName;
    while (std::getline(fieldStream, fieldName, ',')) {
        std::cout << fieldName << std::endl;
    }

    std::cout << "Conditions: " << filterClause << std::endl;
}

int main() {
    std::string sql = "SELECT doctor_id FROM visits WHERE LENGTH(patient_name) > 11";
    extractQueryParts(sql);
    return 0;
}

