void processAudition(const std::vector<int>& sourceNotes, std::vector<int>& targetInputs, int currentStep, int chunkSize) {
    if (currentStep > 0) {
        size_t startIndex = (currentStep - 1) * chunkSize;

        switch (Settings::getAuditionMode()) {
            case AuditionType::NO_AUDITION:
                // No operation for no audition
                break;
            case AuditionType::PERSONAL:
                // Copy a segment of notes from source to target
                for (int i = 0; i < chunkSize; ++i) {
                    if (startIndex + i < sourceNotes.size()) {
                        targetInputs[i] = sourceNotes[startIndex + i];
                    }
                }
                break;
            case AuditionType::COMMUNITY:
                // Indicate that community mode is not supported
                assert(false);
                break;
        }
    }
}

