    std::vector<int> inputs(3);  // Pre-allocated vector for input data
    int step = 2;
    int C = 3;

    processAudition(notes, inputs, step, C);

    // Output the contents of the 'inputs' vector
    for (int note : inputs) {
        std::cout << note << " ";
    }
    std::cout << std::endl;

    return 0;
}

