// Compute derived components from state derivatives and accelerations
std::vector<double> computeStateDerivativeProducts(const DVec<double>& stateDot, 
                                                   const DVec<double>& bodyVel, 
                                                   const DVec<double>& accel) {
    // Isolate translational and rotational parts from state derivative
    DVec<double> transRotPart = stateDot.segment(0, 6);
    DVec<double> jointAccel   = stateDot.segment(6, 12);

    // Prepare result container
    std::vector<double> products;
    products.reserve(6);

    // Compute element-wise products of corresponding entries
    for (int idx = 0; idx < 6; ++idx) {
        products.push_back(transRotPart[idx] * jointAccel[idx]);
    }

    return products;
}

