#include <vector>

// Process light data and generate camera constant buffers for rendering
void RenderLights(const std::vector<LightData>& lights, std::vector<CameraConstantBuffer>& cameraBuffers)
{
    // Iterate through all provided light sources
    for (size_t idx = 0; idx < lights.size(); ++idx)
    {
        const LightData& currentLight = lights[idx];

        if (currentLight.m_lightType == ELightType::Directional)
        {
            // For directional lights, create a single camera buffer with view-projection matrix
            CameraConstantBuffer buffer;
            buffer.m_viewProjection = currentLight.m_viewProjection;
            cameraBuffers.push_back(buffer);
        }
        else if (currentLight.m_lightType == ELightType::Point)
        {
            // Point lights require rendering in 6 directions (cubemap faces)
            const int faceCount = 6;

            // Define the six primary directions for point light sampling
            Vector3 directions[faceCount] = {
                Vector3(1.0f, 0.0f, 0.0f),   // +X
                Vector3(-1.0f, 0.0f, 0.0f),  // -X
                Vector3(0.0f, 1.0f, 0.0f),   // +Y
                Vector3(0.0f, -1.0f, 0.0f),  // -Y
                Vector3(0.0f, 0.0f, 1.0f),   // +Z
                Vector3(0.0f, 0.0f, -1.0f)   // -Z
            };

            // Generate camera buffers for each cubemap face
            for (int faceIdx = 0; faceIdx < faceCount; ++faceIdx)
            {
                CameraConstantBuffer buffer;

                // Compute view matrix: look from light position toward direction
                Vector3 lightPos = currentLight.m_position;
                Vector3 target = lightPos + directions[faceIdx];
                Vector3 upAxis = Vector3(0.0f, 1.0f, 0.0f);

                Matrix view = BuildViewMatrix(lightPos, target, upAxis);
                Matrix proj = BuildPerspectiveMatrix(90.0f, 1.0f, 0.1f, 100.0f);

                buffer.m_viewProjection = view * proj;
                cameraBuffers.push_back(buffer);
            }
        }
    }
}

