      HASH_ALGO_SHA256,
      // Other hash algorithms may be defined here
    };
    enum SignatureAlgorithm {
      SIG_ALGO_ECDSA,
      // Other signature algorithms may be defined here
    };
    HashAlgorithm hash_algorithm;
    SignatureAlgorithm signature_algorithm;
    std::string signature_data;
  };

  bool EncodeDigitallySigned(const DigitallySigned& digitally_signed, std::string* encoded) {
    if (encoded == nullptr) {
      return false;  // Invalid pointer
    }

    // Determine hash algorithm representation
    char hash_char = 'M';  // Default for unknown
    if (digitally_signed.hash_algorithm == DigitallySigned::HASH_ALGO_SHA256) {
      hash_char = 'S';
    }

    // Determine signature algorithm representation
    char sig_char = 'O';  // Default for unknown
    if (digitally_signed.signature_algorithm == DigitallySigned::SIG_ALGO_ECDSA) {
      sig_char = 'E';
    }

    // Construct the encoded string
    *encoded = std::string(1, hash_char) + std::string(1, sig_char) + digitally_signed.signature_data;
    return true;  // Encoding successful
  }
}

