#include <vector>
#include <algorithm>

// Helper function to find unique combinations that sum up to target
void combinationSearch(std::vector<int>& elements, int remaining, int index, 
                       std::vector<int>& path, std::vector<std::vector<int>>& outcomes) {
    if (remaining == 0) {
        outcomes.emplace_back(path);
        return;
    }

    for (int pos = index; pos < elements.size(); ++pos) {
        // Skip duplicate values to avoid repeated combinations
        if (pos > index && elements[pos] == elements[pos - 1]) continue;

        // Early termination if current element exceeds remaining target
        if (elements[pos] > remaining) break;

        path.push_back(elements[pos]);
        combinationSearch(elements, remaining - elements[pos], pos + 1, path, outcomes);
        path.pop_back();
    }
}

// Main function to compute all unique combinations
std::vector<std::vector<int>> generateUniqueCombinations(std::vector<int>& input, int goal) {
    std::sort(input.begin(), input.end());
    std::vector<std::vector<int>> solutions;
    std::vector<int> temporaryPath;
    combinationSearch(input, goal, 0, temporaryPath, solutions);
    return solutions;
}

