// Determine the memory footprint of a specific process by its ID
SIZE_T GetProcessMemoryConsumption(DWORD pid) {
    HANDLE hProc = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!hProc) {
        // Failed to open the process - return zero as error indicator
        return 0;
    }

    PROCESS_MEMORY_COUNTERS memCounters = {0};
    if (GetProcessMemoryInfo(hProc, &memCounters, sizeof(memCounters))) {
        SIZE_T memoryUsed = memCounters.WorkingSetSize;
        CloseHandle(hProc);
        return memoryUsed;
    } else {
        // Failed to retrieve memory information - cleanup and return zero
        CloseHandle(hProc);
        return 0;
    }
}

