template <typename Real>
Real ComputeSquaredDistanceAtTime(const Triangle3<Real>* triangle, Real time, const Vector3<Real>& vel1, const Segment3<Real>* segment) {
    // Compute positions of triangle vertices at time 'time'
    Vector3<Real> v0 = triangle->V[0] + time * vel1;
    Vector3<Real> v1 = triangle->V[1] + time * vel1;
    Vector3<Real> v2 = triangle->V[2] + time * vel1;

    // Construct moved segment by translating its center and preserving orientation/extent
    Vector3<Real> segCenter = segment->Center + time * segment->Direction;
    Segment3<Real> movedSeg;
    movedSeg.Center = segCenter;
    movedSeg.Direction = segment->Direction;
    movedSeg.Extent = segment->Extent;

    // Build the moved triangle from updated vertices
    Triangle3<Real> tri(v0, v1, v2);

    // Compute squared distance between the two geometric objects
    DistanceResult<Real> distResult = DistSegment3Triangle3<Real>(movedSeg, tri);
    return distResult.GetSquared();
}

