#include <queue>
#include <mutex>
#include <condition_variable>

template <typename T>
class ConcurrentQueue {
public:
    void enqueue(const T& item) {
        std::unique_lock<std::mutex> guard(mutex_);
        data_.push(item);
        guard.unlock();
        cv_.notify_one();
    }

    bool dequeue(T& result) {
        std::unique_lock<std::mutex> guard(mutex_);
        cv_.wait(guard, [this] { return !data_.empty(); });

        if (data_.empty()) {
            return false;
        }

        result = data_.front();
        data_.pop();
        return true;
    }

    bool is_empty() const {
        std::lock_guard<std::mutex> guard(mutex_);
        return data_.empty();
    }

private:
    std::queue<T> data_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

