// Base class for tokens in the expression system
class Token {
public:
    using Ptr = std::shared_ptr<Token>;
    virtual ~Token() = default;
};

// Token representing a numeric value
class NumToken : public Token {
public:
    double value;
    NumToken(double val) : value(val) {}
};

// Helper function to extract numeric value from a token
double get_numeric_value(Token::Ptr tok) {
    return static_cast<NumToken*>(tok.get())->value;
}

// Function to compute the sum of multiple tokens
Token::Ptr compute_sum(const std::vector<Token::Ptr> &operands) {
    double total = 0.0;
    size_t idx = 0;
    while (idx < operands.size()) {
        total += get_numeric_value(operands[idx]);
        ++idx;
    }
    return std::make_shared<NumToken>(total);
}

// Function to compute the difference of tokens (left-associative)
Token::Ptr compute_difference(const std::vector<Token::Ptr> &operands) {
    if (operands.empty()) {
        return std::make_shared<NumToken>(0.0);
    }
    double diff = get_numeric_value(operands[0]);
    for (size_t i = 1; i < operands.size(); ++i) {
        diff -= get_numeric_value(operands[i]);
    }
    return std::make_shared<NumToken>(diff);
}

// Main evaluation function that processes tokens and returns final result
double parse_and_compute(const std::vector<Token::Ptr> &expr_tokens) {
    // For this simplified version, we assume all tokens are added together
    // In a full implementation, this would handle operator precedence and parentheses
    Token::Ptr computed = compute_sum(expr_tokens);
    return get_numeric_value(computed);
}

int main() {
    // Construct sample expression tokens: 5 + 3 + 2 + 1
    std::vector<Token::Ptr> expression = {
        std::make_shared<NumToken>(5),
        std::make_shared<NumToken>(3),
        std::make_shared<NumToken>(2),
        std::make_shared<NumToken>(1)
    };

    double final_value = parse_and_compute(expression);
    std::cout << "Final result: " << final_value << std::endl;
    return 0;
}

