class MortonHashTable {
private:
    size_t itemCount; // Number of items stored in the hash table
public:
    // Constructor and other methods are not shown for brevity
    size_t SizeInBytes() const
    {
        // Estimate memory usage in bytes for the hash table structure
        // Based on Morton3_8 layout: 3-slot buckets with 8-bit fingerprints
        // Uses 11.7 bits per item at 0.95 load factor
        const double bitsPerElement = 11.7;
        const double efficiencyFactor = 0.95;

        double requiredBits = itemCount * bitsPerElement / efficiencyFactor;
        size_t byteRequirement = static_cast<size_t>(std::ceil(requiredBits / 8.0));
        return byteRequirement;
    }
};

