// Compute the 3D rotation matrix using ZYX Euler angles (yaw-pitch-roll)
Eigen::Matrix3d computeOrientationMatrix(double phi, double theta, double psi) {
    Eigen::Matrix3d Rx, Ry, Rz, result;

    // Rotation about x-axis (roll)
    Rx << 1.0, 0.0, 0.0,
          0.0, std::cos(phi), -std::sin(phi),
          0.0, std::sin(phi), std::cos(phi);

    // Rotation about y-axis (pitch)
    Ry << std::cos(theta), 0.0, std::sin(theta),
          0.0, 1.0, 0.0,
          -std::sin(theta), 0.0, std::cos(theta);

    // Rotation about z-axis (yaw)
    Rz << std::cos(psi), -std::sin(psi), 0.0,
          std::sin(psi), std::cos(psi), 0.0,
          0.0, 0.0, 1.0;

    // Combine rotations: R = R_z * R_y * R_x
    result = Rz * Ry * Rx;
    return result;
}

int main() {
    // Define Euler angles in radians
    double rollAngle = 0.1;   // Roll angle (phi)
    double pitchAngle = 0.2;  // Pitch angle (theta)
    double yawAngle = 0.3;    // Yaw angle (psi)

    // Compute the rotation matrix
    Eigen::Matrix3d orientationMatrix = computeOrientationMatrix(rollAngle, pitchAngle, yawAngle);

    // Output the resulting rotation matrix
    std::cout << "Rotation Matrix:" << std::endl << orientationMatrix << std::endl;
    return 0;
}

