class Shader {
public:
    unsigned int createAndCompileShader(const char* sourceCode, GLenum shaderType);
};

unsigned int Shader::createAndCompileShader(const char* sourceCode, GLenum shaderType) {
    int compiledSuccessfully;
    char errorLog[512];

    // Create a new shader object of the specified type
    unsigned int shaderObject = glCreateShader(shaderType);

    // Provide the shader source code to OpenGL
    glShaderSource(shaderObject, 1, &sourceCode, nullptr);

    // Attempt to compile the shader
    glCompileShader(shaderObject);

    // Check compilation status
    glGetShaderiv(shaderObject, GL_COMPILE_STATUS, &compiledSuccessfully);

    if (!compiledSuccessfully) {
        // Retrieve and print error message if compilation failed
        glGetShaderInfoLog(shaderObject, 512, nullptr, errorLog);
        std::cerr << "Shader compilation error: " << errorLog << std::endl;
        return 0;  // Indicate failure by returning 0
    }

    // Return the valid shader object ID on success
    return shaderObject;
}

