template <typename T, fcppt::math::size_type Rows, fcppt::math::size_type Cols>
bool compare_matrices(
    fcppt::math::matrix::object<T, Rows, Cols> const &first_matrix,
    fcppt::math::matrix::object<T, Rows, Cols> const &second_matrix,
    fcppt::math::matrix::object<T, Rows, Cols> const &expected)
{
    auto const computed = fcppt::math::matrix::binary_map(
        first_matrix,
        second_matrix,
        [](T const &left, T const &right) { return left + right; });

    return fcppt::math::matrix::comparison(computed, expected);
}

