    void GatewayMain(int argc, char* argv[]) {
        int port = 0;
        bool showHelp = false;

        // Process command line arguments starting from index 1
        for (int idx = 1; idx < argc; ++idx) {
            std::string currentArg = argv[idx];

            // Handle port specification
            if (currentArg == "-p" || currentArg == "--port") {
                if (idx + 1 < argc) {
                    port = std::atoi(argv[idx + 1]);

                    // Validate port number
                    if (port <= 0) {
                        std::cerr << "Error: Invalid port number" << std::endl;
                        return;
                    }

                    // Skip the next argument since we've processed it
                    ++idx;
                } else {
                    std::cerr << "Error: Port number is missing" << std::endl;
                    return;
                }
            }
            // Handle help request
            else if (currentArg == "-h" || currentArg == "--help") {
                showHelp = true;
            }
            // Handle unknown options
            else {
                std::cerr << "Error: Unknown option '" << currentArg << "'" << std::endl;
                return;
            }
        }

        // Display help message if requested
        if (showHelp) {
            std::cout << "Usage: gateway_app [-p <port> | --port <port>] [-h | --help]" << std::endl;
            return;
        }

        // Check if port was specified
        if (port == 0) {
            std::cerr << "Error: Port number is required" << std::endl;
            return;
        }

        // Start server with validated port
        std::cout << "Starting server on port " << port << std::endl;
        // Server initialization and execution logic would go here
    }
}

