    static const std::string cppPrefix;
    static const std::string cPrefix;
public:
    std::string GetRuleWithLanguagePrefix() const {
        if (rule.find("-") != std::string::npos)
            return cppPrefix + rule;
        else if (rule.find(".") != std::string::npos)
            return cPrefix + rule;
        else
            return "";
    }

    bool ContainsCWE() const {
        return (rule.find("CWE") != std::string::npos);
    }
};

