// Abstract base class for timer management
class TimeoutHandler {
public:
    virtual ~TimeoutHandler() {}
    virtual void schedule(int delay, std::function<void()> handler) = 0;
    virtual void tick(int count) = 0;
    virtual std::vector<std::function<void()>> retrieveReadyCallbacks() = 0;
};

// Implementation using hierarchical wheel timer approach
class MultiLevelWheelTimer : public TimeoutHandler {
private:
    // Storage for timer callbacks organized by time slots
    std::vector<std::unordered_map<int, std::function<void()>>> timeSlots;
    int currentOffset;

public:
    MultiLevelWheelTimer() : timeSlots(5), currentOffset(0) {}

    void schedule(int delay, std::function<void()> handler) override {
        int targetSlot = (currentOffset + delay) % timeSlots.size();
        timeSlots[targetSlot][delay] = handler;
    }

    void tick(int steps) override {
        currentOffset = (currentOffset + steps) % timeSlots.size();
    }

    std::vector<std::function<void()>> retrieveReadyCallbacks() override {
        std::vector<std::function<void()>> readyCallbacks;

        for (const auto& entry : timeSlots[currentOffset]) {
            readyCallbacks.push_back(entry.second);
        }

        timeSlots[currentOffset].clear();
        return readyCallbacks;
    }
};

// Factory function to create timer instances
std::shared_ptr<TimeoutHandler> makeTimer() {
    return std::make_shared<MultiLevelWheelTimer>();
}

int main() {
    std::shared_ptr<TimeoutHandler> timerSystem = makeTimer();

    timerSystem->schedule(10, [](){ std::cout << "First timer triggered" << std::endl; });
    timerSystem->schedule(5, [](){ std::cout << "Second timer triggered" << std::endl; });

    timerSystem->tick(5);

    std::vector<std::function<void()>> triggeredCallbacks = timerSystem->retrieveReadyCallbacks();
    for (const auto& func : triggeredCallbacks) {
        func();
    }

    return 0;
}

#include <algorithm>

long long totalProblemsToSolve(long long n, long long k, long long d) {
    // Calculate minimum days needed to complete k problems (ceiling division)
    long long daysNeeded;
    if (d == 0) {
        daysNeeded = 0;
    } else {
        daysNeeded = (k % d == 0) ? (k / d) : (k / d + 1);
    }

    // Total problems across all topics over required days
    long long problemsForAllTopics = n * daysNeeded;

    // Return the maximum between solving all topic problems and meeting the minimum k requirement
    return (problemsForAllTopics > k) ? problemsForAllTopics : k;
}

