#include <string>

std::string convertWindows1252ToUTF8(const std::string& input) {
    std::string result;
    for (size_t i = 0; i < input.length(); ++i) {
        unsigned char ch = static_cast<unsigned char>(input[i]);
        if (ch < 0x80) {
            result += static_cast<char>(ch);
        } else {
            // Mapping table for Windows-1252 extended characters to UTF-8
            static const char* utf8Map[] = {
                "\xe2\x82\xac",  // 0x80: Euro sign
                "\xc5\xa1",      // 0x81: Latin small letter s with caron
                "\xc5\xa3",      // 0x82: Latin small letter t with cedilla
                "\xc5\xbe",      // 0x83: Latin small letter z with caron
                "\xc5\xa0",      // 0x84: Latin capital letter s with caron
                "\xc5\xbd",      // 0x85: Latin capital letter z with caron
                "\xc5\xa2",      // 0x86: Latin capital letter t with cedilla
                "\xc4\x90",      // 0x87: Latin capital letter d with stroke
                "\xc4\x8c",      // 0x88: Latin capital letter c with caron
                "\xc4\x86",      // 0x89: Latin capital letter c with acute
                "\xc4\x8e",      // 0x8a: Latin capital letter d with caron
                "\xc4\x9e",      // 0x8b: Latin capital letter g with breve
                "\xc4\x9c",      // 0x8c: Latin capital letter g with circumflex
                "\xc5\xa4",      // 0x8d: Latin capital letter t with cedilla
                "\xc5\xa6",      // 0x8e: Latin capital letter t with stroke
                "\xc5\x9e",      // 0x8f: Latin capital letter s with cedilla
                "\xc5\x9a",      // 0x90: Latin capital letter s with acute
                "\xc5\x9c",      // 0x91: Latin capital letter s with circumflex
                "\xc5\x9d",      // 0x92: Latin capital letter z with acute
                "\xc5\xbb",      // 0x93: Latin capital letter z with dot above
                "\xc5\xb8"       // 0x94: Latin capital letter y with diaeresis
            };
            const char* utf8Sequence = utf8Map[ch - 0x80];
            while (*utf8Sequence) {
                result += *utf8Sequence++;
            }
        }
    }
    return result;
}

