// Map 2D (eta, phi) coordinates to 3D indices for barrelData
std::vector<int> mapToBarrelIndices(int eta, int phi) {
    std::vector<int> result(3);
    // Compute the first dimension index: phi divided into 8-degree sectors
    result[0] = phi / 8;
    // Compute the second dimension index: eta divided into 8-degree sectors  
    result[1] = eta / 8;
    // Compute the third dimension index: fine-grained position within sector
    result[2] = (phi % 8) * 8 + (eta % 8);
    return result;
}

int main() {
    // Pre-allocate storage arrays for EM and Hadronic calorimeter data
    std::vector<int> emCaloData(72 * 56);   // combEM equivalent
    std::vector<int> hadCaloData(72 * 56);  // combHD equivalent

    // Initialize barrelData as a 3D grid: [9][7][64]
    std::vector<std::vector<std::vector<int>>> barrelGrid(
        9, 
        std::vector<std::vector<int>>(7, std::vector<int>(64, 0))
    );

    // Iterate over all phi and eta bins to populate barrelData
    for (int phiIdx = 0; phiIdx < 72; ++phiIdx) {
        for (int etaIdx = 0; etaIdx < 56; ++etaIdx) {
            // Get the corresponding 3D indices in barrelGrid
            std::vector<int> coords = mapToBarrelIndices(etaIdx, phiIdx);

            // Assign EM and HD values at offset positions
            int baseIndex = coords[2];
            barrelGrid[coords[0]][coords[1]][baseIndex] = emCaloData[phiIdx * 56 + etaIdx];
            barrelGrid[coords[0]][coords[1]][baseIndex + 32] = hadCaloData[phiIdx * 56 + etaIdx];
        }
    }

    return 0;
}

