#include <Eigen/Dense>
#include <stdexcept>

// Performs element-wise multiplication with broadcasting support for row vectors
Eigen::MatrixXd performElementwiseProduct(const Eigen::MatrixXd& matrix1, const Eigen::MatrixXd& matrix2) {
    // Check if matrices have identical dimensions (standard element-wise multiplication)
    if (matrix1.rows() == matrix2.rows() && matrix1.cols() == matrix2.cols()) {
        return matrix1.cwiseProduct(matrix2);
    }
    // Handle case where first matrix is a single row matching column count of second matrix
    else if (matrix1.rows() == 1 && matrix1.cols() == matrix2.cols()) {
        Eigen::RowVectorXd rowVec = matrix1.transpose().segment(0, matrix1.cols());
        return matrix2.array().rowwise() * rowVec.array();
    }
    // Handle case where second matrix is a single row matching column count of first matrix
    else if (matrix2.rows() == 1 && matrix1.cols() == matrix2.cols()) {
        Eigen::RowVectorXd rowVec = matrix2.transpose().segment(0, matrix2.cols());
        return matrix1.array().rowwise() * rowVec.array();
    }
    // Throw exception for incompatible dimensions
    else {
        throw std::invalid_argument("Matrix dimensions are incompatible for element-wise multiplication");
    }
}

