    hpx::parallel::vector<int> data_a(100, 0, exec1);
    hpx::parallel::vector<int> data_b(100, 0, exec2);
    hpx::parallel::vector<int> output(100, 0, exec1);

    // Seed random number generator and fill vectors with values
    std::srand(static_cast<unsigned>(std::time(nullptr)));
    std::for_each(data_a.begin(), data_a.end(), [](int& element) { 
        element = std::rand() % 100; 
    });
    std::for_each(data_b.begin(), data_b.end(), [](int& element) { 
        element = std::rand() % 100; 
    });

    // Compute element-wise sum using parallel transform
    hpx::parallel::transform(exec1, 
                             data_a.begin(), data_a.end(), 
                             data_b.begin(), 
                             output.begin(),
                             [](int x, int y) { return x + y; });

    // Output the resulting vector
    hpx::cout << "Vector sum result: ";
    for (const auto& value : output)
    {
        hpx::cout << value << " ";
    }
    hpx::cout << hpx::endl;

    return hpx::finalize();
}

