// Custom namespace to mimic fc::raw::unpack behavior
namespace custom {
    template <typename T>
    T deserialize(const char* buffer) {
        // Interpret the first sizeof(T) bytes as a little-endian integer
        T value = 0;
        for (size_t i = 0; i < sizeof(T); ++i) {
            value |= static_cast<unsigned char>(buffer[i]) << (8 * i);
        }
        return value;
    }
}

std::chrono::time_point<std::chrono::system_clock> convertToTimePoint(const char* input) {
    using namespace std::chrono;

    // Deserialize seconds from byte array
    int64_t epoch_seconds = custom::deserialize<int64_t>(input);

    // Construct time_point from duration
    system_clock::duration dur{epoch_seconds};
    return time_point<system_clock>{dur};
}

int main() {
    // Example byte array representing 1 second since epoch
    char data[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};

    auto time_point_result = convertToTimePoint(data);

    // Output the number of seconds since epoch
    std::cout << time_point_result.time_since_epoch().count() 
              << " ticks since epoch" << std::endl;

    return 0;
}

