int maxElementsSumLessThanX(int N, int M, int X, int A[], int B[]) {
    // Sort arrays in ascending order for reverse iteration
    sort(A, A + N);
    sort(B, B + M);

    int bestCount = 0;
    int currentSum = 0;

    // Try taking elements from array A first (largest elements)
    for (int i = N - 1; i >= 0; --i) {
        if (A[i] <= X && currentSum + A[i] <= X) {
            currentSum += A[i];
            bestCount++;
        } else {
            break;
        }
    }

    // Try combinations: take some from A, then fill with B
    for (int i = N - 1; i >= 0; --i) {
        int tempSum = A[i];
        int tempCount = 1;

        if (tempSum > X) continue;

        // Add elements from B
        for (int j = M - 1; j >= 0; --j) {
            if (B[j] <= X && tempSum + B[j] <= X) {
                tempSum += B[j];
                tempCount++;
            } else {
                break;
            }
        }

        if (tempCount > bestCount) {
            bestCount = tempCount;
        }
    }

    // Try taking only from array B
    int bOnlySum = 0;
    int bOnlyCount = 0;
    for (int j = M - 1; j >= 0; --j) {
        if (B[j] <= X && bOnlySum + B[j] <= X) {
            bOnlySum += B[j];
            bOnlyCount++;
        } else {
            break;
        }
    }

    if (bOnlyCount > bestCount) {
        bestCount = bOnlyCount;
    }

    return bestCount;
}

