#include <iostream>
#include <thread>
#include <vector>

// Function pointer type for thread execution
using ThreadRoutine = void(*)(void*);

// Container to hold thread-related data
struct ThreadData {
    std::thread* workerThread;
    ThreadRoutine routine;
    void* parameters;
};

// Manager class for handling multiple threads
class ThreadPoolController {
public:
    // Add a new thread task with its arguments
    void addTask(ThreadRoutine routine, void* args) {
        ThreadData data;
        data.routine = routine;
        data.parameters = args;
        pendingTasks.push_back(data);
    }

    // Launch the most recently added task in a separate thread
    void launchTask() {
        if (!pendingTasks.empty()) {
            ThreadData& task = pendingTasks.back();
            task.workerThread = new std::thread(&ThreadPoolController::runTask, this, &task);
        }
    }

    // Synchronize and clean up the completed task
    void completeTask() {
        if (!pendingTasks.empty()) {
            ThreadData& task = pendingTasks.back();
            if (task.workerThread && task.workerThread->joinable()) {
                task.workerThread->join();
            }
            delete task.workerThread;
            pendingTasks.pop_back();
        }
    }

private:
    std::vector<ThreadData> pendingTasks;

    // Internal method to invoke the user-provided function
    void runTask(ThreadData* taskData) {
        taskData->routine(taskData->parameters);
    }
};

// Sample function to demonstrate thread execution
void displayValue(void* input) {
    int* number = static_cast<int*>(input);
    std::cout << "Worker thread processing value: " << *number << std::endl;
}

int main() {
    ThreadPoolController controller;
    int sampleValue = 42;

    controller.addTask(displayValue, &sampleValue);
    controller.launchTask();
    controller.completeTask();

    return 0;
}

#include "SFMLTextureData.h"
