class SFMLTextureAtlasData
{
private:
    // Using vector of pairs instead of separate maps for related data
    struct TextureEntry {
        std::string name;
        sf::Texture texture;
        sf::IntRect region;
    };

    std::vector<TextureEntry> atlasEntries; // Vector to store texture entries

public:
    SFMLTextureAtlasData() = default;
    ~SFMLTextureAtlasData() = default;

    // Load texture and its associated region in one operation
    void loadTexture(const std::string& path, const std::string& name, 
                     int x = 0, int y = 0, int width = 0, int height = 0)
    {
        sf::Texture newTexture;
        if (newTexture.loadFromFile(path))
        {
            // Create entry with provided dimensions or defaults
            TextureEntry entry;
            entry.name = name;
            entry.texture = std::move(newTexture);
            entry.region = sf::IntRect(x, y, width, height);

            // Check if name already exists and update, otherwise add new
            auto it = std::find_if(atlasEntries.begin(), atlasEntries.end(),
                [&name](const TextureEntry& entry) { return entry.name == name; });

            if (it != atlasEntries.end()) {
                *it = std::move(entry);
            } else {
                atlasEntries.push_back(std::move(entry));
            }
        }
    }

    // Retrieve texture region by name
    sf::IntRect getTextureRegion(const std::string& regionName) const
    {
        auto it = std::find_if(atlasEntries.begin(), atlasEntries.end(),
            [&regionName](const TextureEntry& entry) { return entry.name == regionName; });

        if (it != atlasEntries.end()) {
            return it->region;
        }
        return sf::IntRect(0, 0, 0, 0); // Default empty rectangle
    }

    // Retrieve texture by name (new public method added for completeness)
    const sf::Texture* getTexture(const std::string& textureName) const
    {
        auto it = std::find_if(atlasEntries.begin(), atlasEntries.end(),
            [&textureName](const TextureEntry& entry) { return entry.name == textureName; });

        if (it != atlasEntries.end()) {
            return &it->texture;
        }
        return nullptr;
    }

    // Clear all stored data
    void clear()
    {
        atlasEntries.clear();
    }
};

