#include <string>

class HeaderModifier {
public:
    bool UpdateRequestHeader(const std::string& header) {
        // Check if the header contains "User-Agent"
        if (header.find("User-Agent") != std::string::npos) {
            // Replace with a modified User-Agent value
            updatedHeaders += "User-Agent: Custom-Agent\r\n";
            return true;  // Modification occurred
        }
        // Additional rules can be added here as needed
        return false;  // No changes applied to this header
    }

    std::string RetrieveUpdatedHeaders() const {
        return updatedHeaders;
    }

private:
    std::string updatedHeaders;
};

int main() {
    std::string input = "GET /index.html HTTP/1.1\r\nHost: www.example.com\r\nUser-Agent: Mozilla/5.0\r\n\r\n";
    HeaderModifier modifier;
    const char* ptr = input.c_str();
    size_t remaining = input.size();
    bool changed = false;
    std::string resultHeaders;

    while (remaining > 0) {
        std::string currentLine;

        // Extract one line from the input
        while (*ptr != '\r' && *ptr != '\n' && remaining > 0) {
            currentLine += *ptr;
            ++ptr;
            --remaining;
        }

        // Skip the line ending characters (\r\n or \n)
        if (remaining > 0 && (*ptr == '\r' || *ptr == '\n')) {
            if (!currentLine.empty()) {
                if (modifier.UpdateRequestHeader(currentLine)) {
                    changed = true;
                }

                // Add original line to result unless it's been replaced later
                resultHeaders += currentLine;
                resultHeaders += "\r\n";
            }

            ++ptr;
            --remaining;

            // Handle \r\n case specifically
            if (remaining > 0 && *ptr == '\n' && *(ptr - 1) == '\r') {
                ++ptr;
                --remaining;
            }
        }
    }

    // If any modification was made, use the updated headers instead
    if (changed) {
        resultHeaders = modifier.RetrieveUpdatedHeaders();
    }

    std::cout << "Modified Headers:\n" << resultHeaders << std::endl;
    return 0;
}

