// Convert a vector to a formatted string representation
template <typename T>
std::string format_vector(const std::vector<T>& vec) {
    std::ostringstream oss;
    oss << "{ ";

    // Use index-based iteration instead of iterators
    for (size_t idx = 0; idx < vec.size(); ++idx) {
        oss << vec[idx];

        // Add comma and space only if not the last element
        if (idx != vec.size() - 1) {
            oss << ", ";
        }
    }

    oss << " }";
    return oss.str();
}

