// Enumerated logging levels with increasing severity
enum class Severity { TRACE, NOTICE, ALERT, CRITICAL };

class LogSystem {
public:
    void configureThreshold(Severity threshold) {
        minSeverity = threshold;
    }

    void registerStream(std::ostream& stream) {
        sinks.push_back(&stream);
    }

    void emit(Severity level, const std::string& text) {
        if (static_cast<int>(level) >= static_cast<int>(minSeverity)) {
            for (auto* sink : sinks) {
                (*sink) << "[" << severityLabel(level) << "] " << text << "\n";
            }
        }
    }

    void trace(const std::string& msg) { emit(Severity::TRACE, msg); }
    void notice(const std::string& msg) { emit(Severity::NOTICE, msg); }
    void alert(const std::string& msg) { emit(Severity::ALERT, msg); }
    void critical(const std::string& msg) { emit(Severity::CRITICAL, msg); }

private:
    Severity minSeverity = Severity::TRACE;
    std::vector<std::ostream*> sinks;

    std::string severityLabel(Severity sev) {
        switch (sev) {
            case Severity::TRACE:   return "DEBUG";
            case Severity::NOTICE:  return "INFO";
            case Severity::ALERT:   return "WARNING";
            case Severity::CRITICAL:return "ERROR";
        }
        return "UNKNOWN";
    }
};

int main() {
    LogSystem logger;

    // Register standard output
    logger.registerStream(std::cout);

    // Register file output
    std::ofstream logFile("log.txt");
    logger.registerStream(logFile);

    // Set minimum logging level to INFO (NOTICE)
    logger.configureThreshold(Severity::NOTICE);

    // Emit messages at various severity levels
    logger.trace("This is a debug message");
    logger.notice("This is an info message");
    logger.alert("This is a warning message");
    logger.critical("This is an error message");

    logFile.close();
    return 0;
}

