class HistogramWidget : public QWidget {
public:
  void drawHistogram(const std::vector<int>& data) {
    // Create histogram with 10 bins (values 0-9)
    std::vector<int> bins(10, 0);

    // Count occurrences of each value in the input range [0, 9]
    for (int val : data) {
      if (val >= 0 && val < 10) {
        bins[val]++;
      }
    }

    // Find highest count to normalize bar heights
    int maxCount = 0;
    for (int count : bins) {
      if (count > maxCount) {
        maxCount = count;
      }
    }

    // Setup drawing parameters
    int totalBars = static_cast<int>(bins.size());
    int availableWidth = width();
    int eachBarWidth = availableWidth / totalBars;
    int gap = 2;
    int currentX = 0;

    QPainter renderer(this);
    renderer.setBrush(Qt::blue);

    // Draw each bar in the histogram
    for (int count : bins) {
      int normalizedHeight = 0;
      if (maxCount > 0) {
        normalizedHeight = static_cast<int>((static_cast<double>(count) / maxCount) * height());
      }

      int barTopY = height() - normalizedHeight;
      renderer.drawRect(currentX, barTopY, eachBarWidth - gap, normalizedHeight);

      currentX += eachBarWidth;
    }
  }

  void showEvent(QShowEvent* event) override {
    QWidget::showEvent(event);

    // Sample data for demonstration
    std::vector<int> sampleData = {1, 3, 5, 7, 2, 4, 6, 8, 9, 1, 3, 5, 7, 2, 4, 6, 8, 9, 0, 2, 4, 6, 8, 9};
    drawHistogram(sampleData);
  }
};

