#include <google/protobuf/io/coded_stream.h>

// Serialize the DiscardRequest message to a byte array with cached sizes
::google::protobuf::uint8* DiscardRequest::SerializeWithCachedSizesToArray(
    ::google::protobuf::uint8* output_buffer) const {
  // Handle serialization of required field 'message' (field number 1)
  if (has_message()) {
    // Determine the size of the message string
    const int msg_size = message().size();

    // Encode the field header: field tag 1 with wire type 2 (length-delimited)
    *output_buffer++ = 0x0A;  // 0x08 | 0x02 -> field 1, length-delimited

    // Serialize the string length using varint encoding
    output_buffer = ::google::protobuf::io::CodedOutputStream::WriteVarint32ToArray(
        static_cast<::google::protobuf::uint32>(msg_size), output_buffer);

    // Copy the actual string content into the buffer
    output_buffer = ::google::protobuf::io::CodedOutputStream::WriteStringToArray(
        message(), output_buffer);
  }

  // Return updated pointer to end of written data
  return output_buffer;
}

