// Custom memory manager to track and manage dynamic allocations
class MemoryManager {
private:
    std::map<void*, size_t> allocatedBlocks; // Stores pointer-to-size mappings for raw memory blocks

public:
    // Allocate raw memory block and record its size
    void* requestMemory(size_t bytes) {
        void* address = new char[bytes];
        allocatedBlocks[address] = bytes;
        return address;
    }

    // Release a previously allocated raw memory block
    void releaseMemory(void* address) {
        auto it = allocatedBlocks.find(address);
        if (it != allocatedBlocks.end()) {
            delete[] static_cast<char*>(address);
            allocatedBlocks.erase(it);
        }
    }

    // Allocate a single object of type T using default constructor
    template<typename T>
    T* createInstance() {
        return new T();
    }

    // Deallocate a single object created via createInstance
    template<typename T>
    void destroyInstance(T* ptr) {
        delete ptr;
    }

    // Cleanup all remaining tracked allocations on destruction
    ~MemoryManager() {
        for (const auto& entry : allocatedBlocks) {
            delete[] static_cast<char*>(entry.first);
        }
        allocatedBlocks.clear();
    }
};

int main() {
    MemoryManager manager;

    // Forward declarations for incomplete types used below
    class class_A;
    struct struct_S;

    // Simulate allocation of concrete instances (using placeholder types)
    class_A* instanceA = static_cast<class_A*>(manager.requestMemory(sizeof(class_A)));
    class_A* pointerA = manager.createInstance<class_A>();

    struct_S* instanceS = static_cast<struct_S*>(manager.requestMemory(sizeof(struct_S)));
    struct_S* pointerS = manager.createInstance<struct_S>();

    // Properly release all allocated resources
    manager.releaseMemory(instanceA);
    manager.destroyInstance(pointerA);
    manager.releaseMemory(instanceS);
    manager.destroyInstance(pointerS);

    return 0;
}

