#include <cmath>

struct Point3D {
  double x, y, z;
};

// Compute the volume of a tetrahedron using scalar triple product
double calculateTetrahedronVolume(const Point3D& a, const Point3D& b, const Point3D& c, const Point3D& d) {
  // Vectors from vertex a to other vertices
  double abx = b.x - a.x;
  double aby = b.y - a.y;
  double abz = b.z - a.z;

  double acx = c.x - a.x;
  double acy = c.y - a.y;
  double acz = c.z - a.z;

  double adx = d.x - a.x;
  double ady = d.y - a.y;
  double adz = d.z - a.z;

  // Compute cross product of vectors ac and ad
  double cx = acy * adz - acz * ady;
  double cy = acz * adx - acx * adz;
  double cz = acx * ady - acy * adx;

  // Dot product of ab with cross product (scalar triple product)
  double scalarTriple = abx * cx + aby * cy + abz * cz;

  // Volume is absolute value of scalar triple product divided by 6
  return std::abs(scalarTriple) / 6.0;
}

