    for (size_t index = 0; index < totalSockets; ++index) {
        acl::CoreSocket::SOCKET currentSocket;

        // Attempt to establish TCP connection
        if (!connect_tcp_to(host.c_str(), port, nullptr, &currentSocket)) {
            std::cerr << "Failed to open connection socket at index " << index << std::endl;

            // Cleanup previously opened sockets before exiting
            for (auto& existingSocket : socketList) {
                close_socket(existingSocket);
            }
            return;
        }

        // Configure socket options
        if (!set_tcp_socket_options(currentSocket)) {
            std::cerr << "TCP configuration failed for socket at index " << index << std::endl;

            // Cleanup all opened sockets including the current one
            for (auto& existingSocket : socketList) {
                close_socket(existingSocket);
            }
            close_socket(currentSocket);
            return;
        }

        socketList.push_back(currentSocket);
    }

    // Transmit data through each established connection
    for (auto& activeSocket : socketList) {
