// Compute Euclidean distance between two points in n-dimensional space
double calculateEuclideanDistance(const std::vector<double>& firstPoint, const std::vector<double>& secondPoint) {
    double squaredSum = 0.0;
    for (size_t index = 0; index < firstPoint.size(); ++index) {
        double diff = firstPoint[index] - secondPoint[index];
        squaredSum += diff * diff;
    }
    return std::sqrt(squaredSum);
}

