void demo_parallel() {
    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        int total_threads = omp_get_num_threads();

        // Compute work distribution for current thread
        int base_chunk = image_data_size / total_threads;
        int remainder = image_data_size % total_threads;

        // Distribute extra elements to earlier threads
        int offset = (tid < remainder) ? tid : remainder;
        int my_chunk = base_chunk + (tid < remainder ? 1 : 0);
        int my_start = tid * base_chunk + offset;

        // Process assigned portion of image data
        for (int idx = 0; idx < my_chunk; ++idx) {
            process_image_data(image_data[my_start + idx]);
        }
    }
