#include <iostream>
#include <fstream>
#include <sstream>
#include <stdexcept>

enum class SeverityLevel { 
    INFORMATION, 
    WARN, 
    SEVERE, 
    TRACE 
};

class LoggingSystem {
public:
    void logInfo(const std::string& msg) {
        record(SeverityLevel::INFORMATION, msg);
    }

    void logWarning(const std::string& msg) {
        record(SeverityLevel::WARN, msg);
    }

    void logError(const std::string& msg) {
        record(SeverityLevel::SEVERE, msg);
    }

    void logTrace(const std::string& msg) {
        record(SeverityLevel::TRACE, msg);
    }

    void verify(bool check, const std::string& description) {
        if (!check) {
            logError("Assertion error: " + description);
            haltExecution();
        }
    }

    void redirectStream(std::ostream& stream) {
        destination = &stream;
    }

private:
    std::ostream* destination = &std::cout;

    void record(SeverityLevel severity, const std::string& text) {
        std::string tag;
        switch (severity) {
            case SeverityLevel::INFORMATION:
                tag = "INFO";
                break;
            case SeverityLevel::WARN:
                tag = "WARNING";
                break;
            case SeverityLevel::SEVERE:
                tag = "ERROR";
                break;
            case SeverityLevel::TRACE:
                tag = "DEBUG";
                break;
        }
        (*destination) << "[" << tag << "] " << text << '\n';
    }

    void haltExecution() {
        throw std::runtime_error("Execution stopped because of failed assertion");
    }
};

int main() {
    LoggingSystem logger;
    logger.logError("An issue has been detected");
    logger.logTrace("Diagnostic details");
    logger.redirectStream(std::cerr);
    logger.logWarning("Caution notice");
    logger.verify(2 + 2 == 4, "Basic arithmetic check");
    logger.logInfo("This message will be logged");
    return 0;
}

