// Function to compute the maximum possible weight after connecting ropes
int maxWeightAfterConnectingRopes(int weights[], int count, int startMultiplier) {
    // Sort the rope weights in ascending order
    std::sort(weights, weights + count);

    // Array to hold the weighted results
    int processed[count];

    // Process from largest to smallest original weight, multiplying by increasing multipliers
    for (int idx = count - 1; idx >= 0; --idx) {
        processed[idx] = weights[idx] * startMultiplier;
        ++startMultiplier;
    }

    // Sort the processed values to find the maximum
    std::sort(processed, processed + count);

    // The largest value is now at the end of the sorted array
    int maxValue = processed[count - 1];
    return maxValue;
}

int main() {
    int weightArray[] = {4, 3, 2, 6};
    int ropeCount = 4;
    int initialMultiplier = 1;

    std::cout << maxWeightAfterConnectingRopes(weightArray, ropeCount, initialMultiplier) << std::endl;
    return 0;
}

