// Custom exception class for preventing assignment
class AssignmentForbiddenException : public std::runtime_error {
public:
    AssignmentForbiddenException() 
        : std::runtime_error("Assignment from unique_ptr to another is prohibited") {}
};

// Smart pointer implementation that forbids copy assignment
template <typename T>
class exclusive_ptr {
private:
    T* data;

public:
    // Constructor taking ownership of raw pointer
    explicit exclusive_ptr(T* p) : data(p) {}

    // Destructor releases owned resource
    ~exclusive_ptr() {
        delete data;
    }

    // Delete copy constructor and copy assignment operator
    exclusive_ptr(const exclusive_ptr&) = delete;
    exclusive_ptr& operator=(const exclusive_ptr&) = delete;

    // Move operations (optional but good practice)
    exclusive_ptr(exclusive_ptr&& other) noexcept : data(other.data) {
        other.data = nullptr;
    }

    exclusive_ptr& operator=(exclusive_ptr&& other) noexcept {
        if (this != &other) {
            delete data;
            data = other.data;
            other.data = nullptr;
        }
        return *this;
    }

    // Access to managed pointer
    T* get() const { return data; }
};

int main() {
    try {
        // Create two exclusive_ptr instances
        exclusive_ptr<int> ptr1(new int(42));
        exclusive_ptr<int> ptr2(nullptr);

        // Attempt to assign - this will cause compilation error
        // since copy assignment is deleted
        // ptr2 = ptr1; 

        // Instead, demonstrate with a function that tries to copy
        auto attempt_copy = [](const exclusive_ptr<int>& source) {
            // This would fail to compile if we tried to copy
            throw AssignmentForbiddenException();
        };

        // For demonstration, we'll call the function that throws
        attempt_copy(ptr1);

    } catch (const std::exception& e) {
        std::cout << "Caught exception: " << e.what() << std::endl;
    }

    return 0;
}

