namespace rw {
    namespace math {
        template <typename T>
        class Quaternion {
        public:
            T w, x, y, z;

            // Constructor with initial values
            Quaternion(T w_val, T x_val, T y_val, T z_val) 
                : w(w_val), x(x_val), y(y_val), z(z_val) {}

            // Returns the conjugate of the quaternion
            Quaternion<T> getConjugate() const {
                return Quaternion<T>(w, -x, -y, -z);
            }

            // Multiplies this quaternion with another and returns the result
            Quaternion<T> combine(const Quaternion<T>& rhs) const {
                T resW = w * rhs.w - x * rhs.x - y * rhs.y - z * rhs.z;
                T resX = w * rhs.x + x * rhs.w + y * rhs.z - z * rhs.y;
                T resY = w * rhs.y - x * rhs.z + y * rhs.w + z * rhs.x;
                T resZ = w * rhs.z + x * rhs.y - y * rhs.x + z * rhs.w;
                return Quaternion<T>(resW, resX, resY, resZ);
            }

            // Normalizes the quaternion in-place (if non-zero magnitude)
            void scaleToUnit() {
                T len = std::sqrt(w * w + x * x + y * y + z * z);
                if (len > 0) {
                    w /= len;
                    x /= len;
                    y /= len;
                    z /= len;
                }
            }
        };
    } // namespace math
} // namespace rw

