#include <vector>
#include <string>
using namespace std;

class GridPaths {
private:
    vector<string> maze;
    int pathCount;

    void explore(int row, int col, int maxRow, int maxCol) {
        // Reached destination (bottom-right corner)
        if (row == maxRow && col == maxCol) {
            pathCount++;
            return;
        }

        // Move right if possible
        if (col < maxCol) {
            explore(row, col + 1, maxRow, maxCol);
        }

        // Move down if possible
        if (row < maxRow) {
            explore(row + 1, col, maxRow, maxCol);
        }
    }

public:
    int calculateRoutes(int size) {
        // Initialize the maze with '.' characters
        maze.clear();
        string row;
        for (int i = 0; i < size; i++) {
            row += '.';
        }

        // Create size x size grid
        for (int i = 0; i < size; i++) {
            maze.push_back(row);
        }

        pathCount = 0;
        int limit = size - 1;
        explore(0, 0, limit, limit);
        return pathCount;
    }
};

