// Convert a depth pixel to corresponding pixel in another camera's view
std::pair<int, int> mapDepthToOtherCamera(const rs2::depth_intrinsics& depth_intrin,
                                          const rs2::video_stream_profile& other_intrin,
                                          const rs2::depth_frame& depth_frame,
                                          const rs2::video_stream_profile& other_profile,
                                          const rs2::align& aligner,
                                          const rs2::context& ctx) {
    // Define sample depth coordinates (e.g., center-ish region)
    int depth_x = 100;
    int depth_y = 150;

    // Align depth frame to match other stream
    rs2::depth_frame aligned_depth = aligner.process(depth_frame);

    // Prepare input pixel and output point arrays
    float depth_uv[2] = {static_cast<float>(depth_x), static_cast<float>(depth_y)};
    float depth_xyz[3];

    // Get depth value at the specified pixel
    float depth_value = aligned_depth.get_distance(depth_x, depth_y);

    // Convert pixel + depth to 3D world point (in depth camera frame)
    rs2_deproject_pixel_to_point(depth_xyz, &depth_intrin, depth_uv, depth_value);

    // Compute transformation matrix from depth to other camera (assuming external calibration)
    rs2_extrin depth_to_other = depth_intrin.extrin.to(other_intrin);

    // Transform 3D point into other camera's coordinate system
    float other_xyz[3];
    rs2_transform_point_to_point(other_xyz, &depth_to_other, depth_xyz);

    // Project 3D point back to 2D pixel coordinates in other camera
    float other_uv[2];
    rs2_project_point_to_pixel(other_uv, &other_intrin, other_xyz);

    // Round to nearest integer pixel coordinates
    int final_x = static_cast<int>(other_uv[0] + 0.5f);
    int final_y = static_cast<int>(other_uv[1] + 0.5f);

    return std::make_pair(final_x, final_y);
}

