// Verify the normal derivative computation using finite differences
void test_normal_derivative_accuracy(double step_size, BicubicPatch* surface_patch, Vector3 reference_normal, int tolerance, Vector3 expected_full_derivative) {
    // Preserve original state for later restoration
    double saved_f = surface_patch->n01->f;
    Vector3 saved_dx = surface_patch->n01->dx;

    // Apply perturbation to parameter f
    surface_patch->n01->f += step_size;
    Vector3 new_normal = surface_patch->calculateNormal();

    // Compute finite difference approximation of the derivative
    Vector3 finite_diff_deriv = (new_normal - reference_normal) / step_size;

    // Restore original parameter values
    surface_patch->n01->f = saved_f;
    surface_patch->n01->dx = saved_dx;

    // Determine deviation between numerical and analytical derivatives
    double deviation = (finite_diff_deriv - expected_full_derivative).magnitude();

    // Report verification outcome based on tolerance threshold
    if (deviation < tolerance) {
        std::cout << "Derivative verification successful. Error: " << deviation << std::endl;
    } else {
        std::cout << "Derivative verification failed. Error: " << deviation << std::endl;
    }
}

