using namespace std;

const int MAX_NODES = 1005; // Maximum number of vertices

int adjMatrix[MAX_NODES][MAX_NODES]; // Adjacency matrix for the graph
int inDegree[MAX_NODES];             // In-degree count for each vertex
int vertexCount;                     // Total number of vertices

// Perform Kahn's algorithm for topological sorting
int performTopoSort() {
    vector<int> topoOrder; // Resulting topological sequence
    queue<int> zeroQueue;  // Queue for vertices with zero in-degree

    // Initialize: enqueue all vertices with zero in-degree
    for (int i = 0; i < vertexCount; ++i) {
        if (inDegree[i] == 0) {
            zeroQueue.push(i);
        }
    }

    // Process vertices using BFS
    while (!zeroQueue.empty()) {
        int current = zeroQueue.front();
        zeroQueue.pop();
        topoOrder.push_back(current);

        // Check all possible neighbors
        for (int neighbor = 0; neighbor < vertexCount; ++neighbor) {
            if (adjMatrix[current][neighbor] != 0) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) {
                    zeroQueue.push(neighbor);
                }
            }
        }
    }

    // Detect cycle: if not all vertices are processed, there's a cycle
    if (topoOrder.size() != static_cast<size_t>(vertexCount)) {
        return -1;
    }

    return static_cast<int>(topoOrder.size());
}

int main() {
    // Input graph and in-degrees would be read here
    // ...

    int outcome = performTopoSort();

    if (outcome == -1) {
        cout << "Impossible\n";
    } else {
        cout << outcome << '\n';
    }

    return 0;
}

