#include <QTcpSocket>
#include <QByteArray>
#include <QDebug>

void Server::incomingMessage()
{
    // Retrieve the data sent through the socket
    QByteArray receivedData = socket->readAll();

    // Loop over each connected client to forward the message
    for (int i = 0; i < clients.size(); ++i) {
        QTcpSocket* currentClient = clients[i];

        // Skip forwarding to the original sender
        if (currentClient != socket) {
            qint64 sentBytes = currentClient->write(receivedData);
            if (sentBytes < 0) {
                // Log failure in sending to this client
                qDebug() << "Failed to write data to client";
            }
        }
    }

    // Verify if the connection has been terminated
    if (socket->state() == QAbstractSocket::UnconnectedState) {
        // Clean up disconnected client
        clients.removeAll(socket);
        socket->deleteLater();
    }
}

