using namespace std;

// Custom stack implementation that supports retrieving the minimum element in O(1) time
class MinStack {
private:
    stack<int> dataStack;   // Stores all elements
    stack<int> minData;     // Stores minimum elements at each level

public:
    // Push an element onto the stack
    void push(int value) {
        dataStack.push(value);

        // If minData is empty or the new value is less than or equal to current minimum, push to minData
        if (minData.empty() || value <= minData.top()) {
            minData.push(value);
        }
    }

    // Remove the top element from the stack
    void pop() {
        // If the top element is the current minimum, remove it from minData as well
        if (!dataStack.empty() && dataStack.top() == minData.top()) {
            minData.pop();
        }

        // Always remove from the main data stack
        if (!dataStack.empty()) {
            dataStack.pop();
        }
    }

    // Return the top element of the stack
    int peek() {
        return dataStack.top();
    }

    // Check if the stack is empty
    bool isEmpty() {
        return dataStack.empty();
    }

    // Retrieve the minimum element in the stack
    int findMin() {
        return minData.top();
    }
};

#include <type_traits>

// Enum to specify caching behavior for functor objects
enum class CacheFunctorObject : bool { cached = true, not_cached = false };

// Task wrapper class that holds and executes a callable object
template <typename ResultType, bool IsReadOnly, CacheFunctorObject CachingStrategy, typename Callable>
class WorkItem {
public:
    // Execute the stored callable and return its result
    ResultType run() {
        return stored_callable_;
    }

private:
    Callable stored_callable_;
};

// Factory function for creating WorkItem without explicit parameters
template <typename Callable>
constexpr auto create_WorkItem() {
    using Result = std::invoke_result_t<Callable>;
    return WorkItem<Result, true, CacheFunctorObject::not_cached, Callable>();
}

// Factory function for creating WorkItem with explicit type specification
template <typename T, 
          std::conditional_t<std::is_class<T>::value, T&, T> parameter, 
          typename Callable>
constexpr auto create_WorkItem(Callable&& callable) {
    return WorkItem<T, 
                    std::is_const<T>::value, 
                    CacheFunctorObject::not_cached, 
                    Callable>(std::forward<Callable>(callable));
}

