// Function to compute y-ion fragment masses (m/z values)
void computeYIonMasses(const std::string& seq, std::vector<double>& result) {
    // Amino acid residue masses (monoisotopic)
    std::unordered_map<char, double> residueMasses = {
        {'A', 71.03711}, {'R', 156.10111}, {'N', 114.04293}, {'D', 115.02694},
        {'C', 103.00919}, {'E', 129.04259}, {'Q', 128.05858}, {'G', 57.02146},
        {'H', 137.05891}, {'I', 113.08406}, {'L', 113.08406}, {'K', 128.09496},
        {'M', 131.04049}, {'F', 147.06841}, {'P', 97.05276}, {'S', 87.03203},
        {'T', 101.04768}, {'W', 186.07931}, {'Y', 163.06333}, {'V', 99.06841}
    };

    double cumulativeMass = 0.0;
    size_t len = seq.length();

    // Iterate through the sequence from N-terminus to C-terminus (excluding full peptide)
    for (size_t idx = 0; idx < len - 1; ++idx) {
        cumulativeMass += residueMasses[seq[idx]];
        // y_ion mass = cumulative mass + H (proton), charge assumed 1 -> m/z = mass/1
        result[idx] = cumulativeMass + 1.007825; // more precise proton mass
    }
}

int main() {
    std::string peptide = "PEPTIDE";
    std::vector<double> yIonMZs(peptide.length() - 1, 0.0);

    computeYIonMasses(peptide, yIonMZs);

    // Print the resulting y-ion m/z values
    for (double mz : yIonMZs) {
        std::cout << mz << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <mutex>
#include <condition_variable>
#include <iostream>
#include <thread>
#include <vector>

class SyncManager {
public:
    void AddSyncPoint(int id) {
        std::unique_lock<std::mutex> lock(_mtx);
        _syncIds.push_back(id);
        _syncStatus.push_back(false);
    }

    void SetSyncPoint(int id) {
        std::unique_lock<std::mutex> lock(_mtx);
        auto iter = std::find(_syncIds.begin(), _syncIds.end(), id);
        if (iter != _syncIds.end()) {
            size_t pos = std::distance(_syncIds.begin(), iter);
            _syncStatus[pos] = true;
            _cond.notify_all();
        }
    }

    void AwaitSyncPoint(int id) {
        std::unique_lock<std::mutex> lock(_mtx);
        auto iter = std::find(_syncIds.begin(), _syncIds.end(), id);
        if (iter != _syncIds.end()) {
            size_t pos = std::distance(_syncIds.begin(), iter);
            _cond.wait(lock, [this, pos]() { return _syncStatus[pos]; });
        }
    }

private:
    std::vector<int> _syncIds;
    std::vector<bool> _syncStatus;
    std::mutex _mtx;
    std::condition_variable _cond;
};

int main() {
    SyncManager manager;

    // Register synchronization points
    manager.AddSyncPoint(10);
    manager.AddSyncPoint(20);
    manager.AddSyncPoint(30);

    // Trigger each sync point from separate threads
    std::thread worker1([&manager] { manager.SetSyncPoint(10); });
    std::thread worker2([&manager] { manager.SetSyncPoint(20); });
    std::thread worker3([&manager] { manager.SetSyncPoint(30); });

    worker1.join();
    worker2.join();
    worker3.join();

    // Wait for all sync points to be ready
    manager.AwaitSyncPoint(10);
    manager.AwaitSyncPoint(20);
    manager.AwaitSyncPoint(30);

    std::cout << "All synchronization points reached." << std::endl;
    return 0;
}

