#include <cmath>

// Check if a ray intersects with a plane and compute the intersection point
IntersectionTestResult testIntersection(const Ray& ray) {
    IntersectionTestResult result;

    // Compute denominator: dot product of ray direction and plane normal
    float denominator = dot(ray.direction, getNormal());

    // Avoid division by zero — treat as parallel if too small
    if (std::fabs(denominator) < 1e-6f) {
        result.intersects = false;
        return result;
    }

    // Compute parametric distance along the ray to the plane
    float paramT = dot(getPlanePoint() - ray.origin, getNormal()) / denominator;

    // Discard intersections behind the ray origin
    if (paramT < 0.0f) {
        result.intersects = false;
        return result;
    }

    // Compute actual 3D intersection point
    result.intersectionPoint = ray.origin + paramT * ray.direction;
    result.intersects = true;

    return result;
}

