// Helper to safely release COM interfaces
template<typename T>
void SafeRelease(T*& ptr) {
    if (ptr != nullptr) {
        ptr->Release();
        ptr = nullptr;
    }
}

// Extracts PnP device identifiers using WMI
void FetchPnPDeviceIdentifiers(std::vector<std::string>& outDeviceList) {
    HRESULT hr = S_OK;

    // Initialize COM runtime with multithreading support
    hr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
    if (FAILED(hr)) {
        Diagnostics::LogFailure("COM initialization", std::to_string(hr));
        return;
    }

    // Configure COM security context for impersonation
    hr = CoInitializeSecurity(
        nullptr,
        -1,
        nullptr,
        nullptr,
        RPC_C_AUTHN_LEVEL_DEFAULT,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        nullptr,
        EOAC_NONE,
        nullptr
    );
    if (FAILED(hr)) {
        CoUninitialize();
        Diagnostics::LogFailure("COM security setup", std::to_string(hr));
        return;
    }

    // Acquire WMI locator interface
    IWbemLocator* pWmiLocator = nullptr;
    hr = CoCreateInstance(
        CLSID_WbemLocator,
        nullptr,
        CLSCTX_INPROC_SERVER,
        IID_IWbemLocator,
        reinterpret_cast<void**>(&pWmiLocator)
    );
    if (FAILED(hr)) {
        CoUninitialize();
        Diagnostics::LogFailure("WMI locator instantiation", std::to_string(hr));
        return;
    }

    // Connect to WMI namespace
    IWbemServices* pWmiServices = nullptr;
    hr = pWmiLocator->ConnectServer(
        _bstr_t(L"ROOT\\CIMV2"),
        nullptr,
        nullptr,
        0,
        nullptr,
        0,
        0,
        &pWmiServices
    );
    SafeRelease(pWmiLocator); // Locator no longer needed after connection

    if (FAILED(hr)) {
        CoUninitialize();
        Diagnostics::LogFailure("WMI namespace connection", std::to_string(hr));
        return;
    }

    // Apply proxy blanket for authentication/authorization
    hr = CoSetProxyBlanket(
        pWmiServices,
        RPC_C_AUTHN_WINNT,
        RPC_C_AUTHZ_NONE,
        nullptr,
        RPC_C_AUTHN_LEVEL_CALL,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        nullptr,
        EOAC_NONE
    );
    if (FAILED(hr)) {
        SafeRelease(pWmiServices);
        CoUninitialize();
        Diagnostics::LogFailure("Proxy blanket configuration", std::to_string(hr));
        return;
    }

    // Execute WQL query to enumerate Plug and Play devices
    IEnumWbemClassObject* pResultEnum = nullptr;
    hr = pWmiServices->ExecQuery(
        _bstr_t(L"WQL"),
        _bstr_t(L"SELECT * FROM Win32_PnPEntity"),
        WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
        nullptr,
        &pResultEnum
    );
    if (FAILED(hr)) {
        SafeRelease(pWmiServices);
        CoUninitialize();
        Diagnostics::LogFailure("WMI query execution", std::to_string(hr));
        return;
    }

    // Iterate over results and extract DeviceID property
    IWbemClassObject* pItem = nullptr;
    ULONG fetchedCount = 0;
    while (true) {
        hr = pResultEnum->Next(WBEM_INFINITE, 1, &pItem, &fetchedCount);
        if (FAILED(hr) || fetchedCount == 0) {
            break;
        }

        VARIANT deviceIdVar;
        VariantInit(&deviceIdVar);

        hr = pItem->Get(L"DeviceID", 0, &deviceIdVar, nullptr, nullptr);
        if (SUCCEEDED(hr) && V_VT(&deviceIdVar) == VT_BSTR) {
            _bstr_t bstrId(deviceIdVar.bstrVal);
            outDeviceList.emplace_back(static_cast<char*>(bstrId));
        }

        VariantClear(&deviceIdVar);
        SafeRelease(pItem);
    }

    // Cleanup resources
    SafeRelease(pResultEnum);
    SafeRelease(pWmiServices);
    CoUninitialize();
}

