namespace cuda {
    // Kernel function to compute element-wise sum of two arrays
    __global__ void computeArraySum(const float* inputX, const float* inputY, float* output, size_t length) {
        size_t position = blockIdx.x * blockDim.x + threadIdx.x;
        if (position < length) {
            output[position] = inputX[position] + inputY[position];
        }
    }

    // Host function to manage memory and launch kernel for array addition
    void executeElementwiseAddition(const float* sourceA, const float* sourceB, float* destination, size_t count) {
        float *deviceInputA, *deviceInputB, *deviceOutput;

        // Allocate device memory
        cudaMalloc((void**)&deviceInputA, count * sizeof(float));
        cudaMalloc((void**)&deviceInputB, count * sizeof(float));
        cudaMalloc((void**)&deviceOutput, count * sizeof(float));

        // Copy data from host to device
        cudaMemcpy(deviceInputA, sourceA, count * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(deviceInputB, sourceB, count * sizeof(float), cudaMemcpyHostToDevice);

        // Launch kernel with appropriate grid and block dimensions
        int blockSize = 256;
        int gridSize = (count + blockSize - 1) / blockSize;
        computeArraySum<<<gridSize, blockSize>>>(deviceInputA, deviceInputB, deviceOutput, count);

        // Copy result back to host
        cudaMemcpy(destination, deviceOutput, count * sizeof(float), cudaMemcpyDeviceToHost);

        // Release device memory
        cudaFree(deviceInputA);
        cudaFree(deviceInputB);
        cudaFree(deviceOutput);
    }
}

