#include <cmath>

class ZComplex {
private:
    double re;
    double im;
public:
    ZComplex(double re, double im) : re(re), im(im) {}

    ZComplex add(const ZComplex& other) const {
        return ZComplex(re + other.re, im + other.im);
    }

    ZComplex subtract(const ZComplex& other) const {
        return ZComplex(re - other.re, im - other.im);
    }

    ZComplex multiply(const ZComplex& other) const {
        return ZComplex(re * other.re - im * other.im, re * other.im + im * other.re);
    }

    ZComplex divide(const ZComplex& other) const {
        double denom = other.re * other.re + other.im * other.im;
        return ZComplex((re * other.re + im * other.im) / denom, (im * other.re - re * other.im) / denom);
    }

    ZComplex power(int exponent) const {
        double magnitude = std::sqrt(re * re + im * im);
        double angle = std::atan2(im, re);
        double r = std::pow(magnitude, exponent);
        return ZComplex(r * std::cos(exponent * angle), r * std::sin(exponent * angle));
    }
};

