// Convert quaternion to transformation matrix using alternative computation path
Transform Quaternion::ToTransform() const {
    // Precompute squared components and cross-products
    Float vx2 = v.x * v.x;
    Float vy2 = v.y * v.y;
    Float vz2 = v.z * v.z;

    Float vxy = v.x * v.y;
    Float vxz = v.x * v.z;
    Float vyz = v.y * v.z;

    // Compute matrix entries using rearranged expressions for numerical stability
    Float m00 = 1.0f - 2.0f * (vy2 + vz2);
    Float m01 = 2.0f * (vxy - v.z * w);
    Float m02 = 2.0f * (vxz + v.y * w);

    Float m10 = 2.0f * (vxy + v.z * w);
    Float m11 = 1.0f - 2.0f * (vx2 + vz2);
    Float m12 = 2.0f * (vyz - v.x * w);

    Float m20 = 2.0f * (vxz - v.y * w);
    Float m21 = 2.0f * (vyz + v.x * w);
    Float m22 = 1.0f - 2.0f * (vx2 + vy2);

    // Construct the full 4x4 transformation matrix
    Float elements[16] = {
        m00, m01, m02, 0,
        m10, m11, m12, 0,
        m20, m21, m22, 0,
        0,   0,   0,   1
    };

    return Transform(elements);
}

}

