// Compute how many elements in array 'a' are less than each query value
vector<int> countElementsLessThanX(int a[], int n, int queries[], int q) {
    vector<int> result;

    // Create a copy of the original array to avoid modifying it
    vector<int> sortedArray(a, a + n);
    sort(sortedArray.begin(), sortedArray.end());

    for (int i = 0; i < q; i++) {
        // Use upper_bound to find the first element greater than queries[i]
        auto it = upper_bound(sortedArray.begin(), sortedArray.end(), queries[i]);
        int count = distance(sortedArray.begin(), it); // Calculate number of elements less than queries[i]
        result.push_back(count);
    }

    return result;
}

