struct GUID
{
    unsigned long Data1;
    unsigned short Data2;
    unsigned short Data3;
    unsigned char Data4[8];
};

// Convert a 32-character hex string to a GUID structure
GUID hexStringToGuid(const std::string& hexStr)
{
    if (hexStr.length() != 32) {
        throw std::invalid_argument("Hex string must be exactly 32 characters");
    }

    GUID guid = {0};

    // Process each byte individually using index-based loop
    for (int idx = 0; idx < 16; ++idx) {
        // Extract two hex characters and convert to byte value
        std::string pair = hexStr.substr(idx * 2, 2);
        unsigned char byteVal = static_cast<unsigned char>(
            std::stoi(pair, nullptr, 16)
        );
        guid.Data4[idx] = byteVal;
    }

    return guid;
}

