// A simplified array wrapper class that manages dynamic memory
template<typename T, typename IndexType>
class SimpleArray {
private:
    T* elements;     // Pointer to the underlying storage
    IndexType count; // Number of elements currently stored

public:
    // Initialize with raw data and size
    explicit SimpleArray(const T* source, const IndexType n) 
        : count(n), elements(nullptr) {
        if (n > 0) {
            elements = new T[n];
            for (IndexType idx = 0; idx < n; ++idx) {
                elements[idx] = source[idx];
            }
        }
    }

    // Copy from another compatible container-like object
    template<typename Source>
    explicit SimpleArray(const Source& src) 
        : count(src.size()), elements(nullptr) {
        if (count > 0) {
            elements = new T[count];
            for (IndexType idx = 0; idx < count; ++idx) {
                elements[idx] = src[idx];
            }
        }
    }

    // Non-const element access by index
    T& at(IndexType idx) {
        return elements[idx];
    }

    // Const element access by index
    T at(IndexType idx) const {
        return elements[idx];
    }

    // Alternative indexing syntax using parentheses
    T& operator()(IndexType idx) {
        return elements[idx];
    }

    // Read-only alternative indexing syntax
    T operator()(IndexType idx) const {
        return elements[idx];
    }

    // Resize the internal storage, preserving existing elements where possible
    void resize(IndexType new_size) {
        if (new_size == count) return;

        T* temp = new T[new_size];
        IndexType copy_count = (new_size < count) ? new_size : count;

        for (IndexType i = 0; i < copy_count; ++i) {
            temp[i] = elements[i];
        }

        delete[] elements;
        elements = temp;
        count = new_size;
    }

    // Clear the array: release memory and reset state
    void clear() {
        delete[] elements;
        elements = nullptr;
        count = 0;
    }

    // Destructor ensures proper cleanup
    ~SimpleArray() {
        delete[] elements;
    }

    // Helper to get current size
    IndexType length() const {
        return count;
    }
};

int main() {
    // Demonstration of the SimpleArray class
    int initial_data[] = {10, 20, 30, 40, 50};
    SimpleArray<int, std::size_t> myData(initial_data, 5);

    std::cout << myData.at(2) << std::endl;   // Output: 30
    myData.resize(3);
    // Accessing beyond new size is undefined behavior
    // std::cout << myData.at(4) << std::endl; // Would be unsafe

    myData.clear();
    return 0;
}

