class CCommandLineProcessor {
public:
    bool HandleInput(const wchar_t* input) {
        std::wstring cmdline(input);
        // Normalize to lowercase for case-insensitive matching
        std::transform(cmdline.begin(), cmdline.end(), cmdline.begin(),
                       [](wchar_t c) { return std::tolower(c); });

        if (cmdline.compare(0, 4, L"help") == 0) {
            ShowHelp();
            return true;
        }
        else if (cmdline.compare(0, 7, L"version") == 0) {
            ShowVersion();
            return true;
        }
        else if (cmdline.compare(0, 7, L"execute") == 0) {
            std::wstring target = ExtractSingleArgument(cmdline, L"execute");
            if (!target.empty()) {
                RunFile(target);
                return true;
            }
        }
        else if (cmdline.compare(0, 8, L"settings") == 0) {
            std::vector<std::wstring> options = ExtractMultipleArguments(cmdline, L"settings");
            if (options.size() == 2) {
                ConfigureSettings(options[0], options[1]);
                return true;
            }
        }

        // Command not recognized or invalid format
        return false;
    }

private:
    void ShowHelp() {
        std::cout << "Supported commands:" << std::endl;
        // Additional help text can be added here
    }

    void ShowVersion() {
        std::cout << "Program version 1.0.0" << std::endl;
    }

    void RunFile(const std::wstring& path) {
        // Placeholder for file execution logic
    }

    void ConfigureSettings(const std::wstring& key, const std::wstring& val) {
        // Placeholder for settings configuration logic
    }

    std::wstring ExtractSingleArgument(const std::wstring& fullInput, const std::wstring& cmd) {
        size_t idx = fullInput.find(cmd);
        if (idx != std::wstring::npos) {
            size_t start = idx + cmd.length();
            if (start < fullInput.length() && fullInput[start] == L' ') {
                ++start; // Skip the space after command
            }
            return (start < fullInput.length()) ? fullInput.substr(start) : L"";
        }
        return L"";
    }

    std::vector<std::wstring> ExtractMultipleArguments(const std::wstring& fullInput, const std::wstring& cmd) {
        std::vector<std::wstring> result;
        size_t idx = fullInput.find(cmd);
        if (idx != std::wstring::npos) {
            size_t start = idx + cmd.length();
            if (start < fullInput.length() && fullInput[start] == L' ') {
                ++start;
            }
            if (start >= fullInput.length()) return result;

            std::wstring rest = fullInput.substr(start);
            size_t firstSpace = rest.find(L' ');
            if (firstSpace != std::wstring::npos) {
                result.push_back(rest.substr(0, firstSpace));
                size_t secondStart = firstSpace + 1;
                if (secondStart < rest.length()) {
                    result.push_back(rest.substr(secondStart));
                }
            }
        }
        return result;
    }
};

