class Child {
private:
    std::vector<std::function<void()>> drainCloseCallbacks;
public:
    auto registerOnDrainClose(const std::function<void()>& callback) {
        drainCloseCallbacks.emplace_back(callback);
        return this;
    }

    void executeDrainAndClose() {
        // Perform draining operations
        for (const auto& cb : drainCloseCallbacks) {
            cb();
        }
        std::cout << "Child drained and closed" << std::endl;
    }
};

class Parent {
private:
    Child* childRef;
    std::function<void()> parentCallback;
public:
    Parent(Child* c) : childRef(c) {}

    void initiateDrainProcess(const std::function<void()>& callback) {
        parentCallback = callback;
        childRef->executeDrainAndClose();
        parentCallback();
    }
};

int main() {
    Child c;
    Parent p(&c);
    auto cb = Callback();
    auto handle_c = c.registerOnDrainClose(cb.AsStdFunction());

    // Drain the child, then the parent
