typedef std::map<std::string, std::string> QueryArgumentMap;

void RemoveExtraArguments(QueryArgumentMap& queryArgs, const std::set<std::string>& setName) {
    // Create a vector of keys to remove instead of modifying map during iteration
    std::vector<std::string> keysToRemove;

    // Collect all keys that should be removed (not in setName)
    for (const auto& pair : queryArgs) {
        if (setName.find(pair.first) == setName.end()) {
            keysToRemove.push_back(pair.first);
        }
    }

    // Remove the collected keys from the original map
    for (const auto& key : keysToRemove) {
        queryArgs.erase(key);
    }
}

