        if (str) {
            size_t len = strlen(str);
            data = new char[len + 1];
            strcpy(data, str);
        } else {
            data = nullptr;
        }
    }

    DinString(const DinString& other) {
        if (other.data) {
            size_t len = strlen(other.data);
            data = new char[len + 1];
            strcpy(data, other.data);
        } else {
            data = nullptr;
        }
    }

    ~DinString() {
        delete[] data;
    }

    DinString& operator=(const DinString& other) {
        if (this != &other) {
            delete[] data;
            if (other.data) {
                size_t len = strlen(other.data);
                data = new char[len + 1];
                strcpy(data, other.data);
            } else {
                data = nullptr;
            }
        }
        return *this;
    }

    const char* c_str() const { return data ? data : ""; }
