// Type III Clone: Modified logic using different control flow and variable naming
class EString {
public:
    EString(const char* str = "") : data(str ? new char[strlen(str) + 1]() : nullptr) {
        if (data && str) strcpy(data, str);
    }

    ~EString() { delete[] data; }

    EString& operator<<(const char* str) {
        if (!data) {
            data = new char[strlen(str) + 1];
            strcpy(data, str);
        } else {
            size_t oldLen = strlen(data);
            char* newData = new char[oldLen + strlen(str) + 1];
            strcpy(newData, data);
            strcat(newData, str);
            delete[] data;
            data = newData;
        }
        return *this;
    }

    const char* c_str() const { return data ? data : ""; }
    size_t length() const { return data ? strlen(data) : 0; }

private:
    char* data;
};

