        std::lock_guard<std::mutex> guard(access_mutex);
        current_value = new_value;
    }

private:
    std::string option_name;
    T current_value;
    mutable std::mutex access_mutex;
};

// Global configuration registry
class ConfigRegistry {
public:
    // Retrieve an option value, creating if necessary
    template <typename T>
    static T fetch(const std::string& key, const T& fallback) {
        std::lock_guard<std::mutex> lock(registry_mutex);

        auto iter = config_store.find(key);
        if (iter == config_store.end()) {
            config_store[key] = std::make_unique<ConfigOption<T>>(key, fallback);
            return fallback;
        }

        return static_cast<ConfigOption<T>*>(iter->second.get())->retrieve();
    }

    // Update an option value
    template <typename T>
    static void assign(const std::string& key, const T& value) {
        std::lock_guard<std::mutex> lock(registry_mutex);

        auto iter = config_store.find(key);
        if (iter == config_store.end()) {
            std::cerr << "Warning: Configuration key '" << key << "' does not exist." << std::endl;
            return;
        }

        static_cast<ConfigOption<T>*>(iter->second.get())->update(value);
    }

private:
    static std::map<std::string, std::unique_ptr<OptionBase>> config_store;
    static std::mutex registry_mutex;
};

std::map<std::string, std::unique_ptr<OptionBase>> ConfigRegistry::config_store;
std::mutex ConfigRegistry::registry_mutex;

// Helper function to initialize options with defaults
template <typename T>
void initialize_option(const std::string& key, const T& default_val) {
    ConfigRegistry::fetch<T>(key, default_val);
}

