// Function to process and modify attribute definitions
void processDefinitions(smtk::attribute::DefinitionPtr targetDef, smtk::attribute::DefinitionPtr sourceDef) {
    // Ensure both definitions are valid before proceeding
    if (targetDef && sourceDef) {
        // Look for an item named "Expression String" in the target definition
        smtk::attribute::StringItemDefinitionPtr exprItem = 
            std::dynamic_pointer_cast<smtk::attribute::StringItemDefinition>(
                targetDef->findItemDefinition("Expression String"));

        // If not found, create and add it
        if (!exprItem) {
            exprItem = smtk::attribute::StringItemDefinition::New("Expression String");
            targetDef->addItemDefinition(exprItem);
        }

        // Search for an item named "Base String" in the source definition
        smtk::attribute::StringItemDefinitionPtr baseItem = 
            std::dynamic_pointer_cast<smtk::attribute::StringItemDefinition>(
                sourceDef->findItemDefinition("Base String"));

        // If found, remove it from the source definition
        if (baseItem) {
            sourceDef->removeItemDefinition(baseItem);
        }
    }
}

