    }

    // Assign a delegate with signature int(int, bool)
    void AssignFunction(FunctionSignature<int, int, bool> func)
    {
        m_Function = std::move(func);
    }

    // Invoke the stored callback if it exists
    void InvokeCallback()
    {
        if (m_Callback)
        {
            m_Callback();
        }
    }

    // Invoke the stored function with provided arguments
