int main() {
    std::ifstream file_stream("input.txt");
    if (!file_stream) {
        std::cerr << "Input file not found" << std::endl;
        return 1;
    }

    std::vector<int> numbers;
    std::string current_line;

    while (std::getline(file_stream, current_line)) {
        size_t pos = 0;
        std::string token;

        while ((pos = current_line.find(' ')) != std::string::npos || 
               (pos = current_line.find('\t')) != std::string::npos || 
               !current_line.empty()) {

            // Extract number by removing delimiters
            size_t start = current_line.find_first_not_of(" \t");
            if (start == std::string::npos) break;

            size_t end = current_line.find_first_of(" \t", start);
            token = current_line.substr(start, end == std::string::npos ? end : end - start);
            current_line = end == std::string::npos ? "" : current_line.substr(end);

            if (token.empty()) continue;

            char* endptr;
            errno = 0;
            long val = std::strtol(token.c_str(), &endptr, 10);

            if (errno != 0 || *endptr != '\0') {
                std::cerr << "Invalid input format" << std::endl;
                return 1;
            }

            numbers.push_back(static_cast<int>(val));
        }
    }

    file_stream.close();

    std::ofstream result_file("output.txt");
    if (!result_file) {
        std::cerr << "Failed to open output file" << std::endl;
        return 1;
    }

    for (size_t i = 0; i < numbers.size(); ++i) {
        result_file << numbers[i] * numbers[i] << "\n";
    }

    result_file.close();
    return 0;
}

