#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class TaskManager {
public:
    TaskManager() : active(true) {}

    void beginProcessing() {
        workerThread = std::thread([this] { this->process(); });
    }

    void enqueueTask(void (*func)()) {
        std::lock_guard<std::mutex> guard(queueMutex);
        taskQueue.push(func);
        conditionVar.notify_one();
    }

    void process() {
        while (active) {
            std::unique_lock<std::mutex> lock(queueMutex);
            conditionVar.wait(lock, [this] { return !taskQueue.empty() || !active; });

            if (!taskQueue.empty()) {
                auto currentTask = taskQueue.front();
                taskQueue.pop();
                lock.unlock();  // Unlock before executing the task

                currentTask();  // Execute the task
            }
        }
    }

    ~TaskManager() {
        active = false;
        conditionVar.notify_one();  // Wake up the processing thread to terminate
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    std::queue<void (*)()> taskQueue;
    std::mutex queueMutex;
    std::condition_variable conditionVar;
    std::thread workerThread;
    bool active;
};

