#include <iostream>
#include <cstring>

class MyString {
private:
    char* data;
public:
    // Constructor from C-style string
    MyString(const char* str) {
        size_t len = strlen(str);
        data = new char[len + 1];
        strcpy(data, str);
    }

    // Copy constructor
    MyString(const MyString& other) {
        size_t len = strlen(other.data);
        data = new char[len + 1];
        strcpy(data, other.data);
    }

    // Assignment operator
    MyString& operator=(const MyString& rhs) {
        if (this != &rhs) {
            delete[] data;
            size_t len = strlen(rhs.data);
            data = new char[len + 1];
            strcpy(data, rhs.data);
        }
        return *this;
    }

    // Concatenation operator
    MyString operator+(const MyString& other) const {
        size_t totalLen = strlen(data) + strlen(other.data);
        char* temp = new char[totalLen + 1];
        strcpy(temp, data);
        strcat(temp, other.data);
        MyString result(temp);
        delete[] temp;
        return result;
    }

    // Comparison operators
    bool operator==(const MyString& other) const {
        return strcmp(data, other.data) == 0;
    }

    bool operator!=(const MyString& other) const {
        return strcmp(data, other.data) != 0;
    }

    // Indexing operator
    char& operator[](size_t index) {
        return data[index];
    }

    // Const version for const objects
    const char& operator[](size_t index) const {
        return data[index];
    }

    // Destructor
    ~MyString() {
        delete[] data;
    }

    // Helper function to print the string
    const char* c_str() const {
        return data;
    }
};

// Overload << operator for easy output
std::ostream& operator<<(std::ostream& os, const MyString& str) {
    os << str.c_str();
    return os;
}

int main() {
    MyString s1("Hello");
    MyString s2("World");
    MyString s3 = s1 + s2;
    std::cout << "s3: " << s3 << std::endl;
    std::cout << "s1 == s2: " << (s1 == s2) << std::endl;
    std::cout << "s1 != s2: " << (s1 != s2) << std::endl;
    std::cout << "s3[0]: " << s3[0] << std::endl;
    return 0;
}

