    for (const auto& existingComponent : currentComponents) {
        if (existingComponent.id() == newDemandComponent.id()) {  // Use ID comparison instead of direct equality
            found = true;
            break;
        }
    }

    // Ensure the component was successfully added
    if (!found) {
        throw std::runtime_error("Failed to verify demand component addition");
    }
}

