void Asteroid::calculateDeformedResultantRadius() {
    GLfloat currentMax = BASE_RADIUS;  // Start with the base radius as the initial maximum
    int pointCount = this->asteroidPoints.size();

    // Iterate through all asteroid points to find the furthest extent
    for (int index = 0; index < pointCount; ++index) {
        Point currentPoint = this->asteroidPoints[index];

        // Compute radial distance from origin using Euclidean norm
        GLfloat radialDistance = std::sqrt(
            currentPoint.x * currentPoint.x + 
            currentPoint.y * currentPoint.y + 
            currentPoint.z * currentPoint.z
        );

        // Update the maximum radius if this point is farther out
        if (radialDistance > currentMax) {
            currentMax = radialDistance;
        }
    }

    // Store or use the computed deformed radius as needed
    this->deformedRadius = currentMax;
}

