#include <vector>
#include <algorithm>
#include <stack>

std::vector<std::vector<int>> combinationSum(std::vector<int>& candidates, int target) {
    std::sort(candidates.begin(), candidates.end());
    std::vector<std::vector<int>> result;

    // Stack to simulate recursion: stores {current_combination, current_sum, start_index}
    std::stack<std::tuple<std::vector<int>, int, int>> stk;
    stk.push({{}, 0, 0});

    while (!stk.empty()) {
        auto [combo, current_sum, start] = stk.top();
        stk.pop();

        if (current_sum == target) {
            result.push_back(combo);
            continue;
        }

        if (current_sum > target) {
            continue;
        }

        for (int idx = start; idx < candidates.size(); ++idx) {
            // Skip duplicates
            if (idx > start && candidates[idx] == candidates[idx - 1]) {
                continue;
            }

            std::vector<int> new_combo = combo;
            new_combo.push_back(candidates[idx]);

            // Push state for next iteration
            stk.push({new_combo, current_sum + candidates[idx], idx + 1});
        }
    }

    return result;
}

