// Custom smart pointer implementation with reference counting
template<typename T>
class CustomSharedPtr {
private:
    T* ptr;
    int* refCount;

    void release() {
        if (refCount) {
            (*refCount)--;
            if (*refCount == 0) {
                delete ptr;
                delete refCount;
            }
        }
    }

public:
    explicit CustomSharedPtr(T* p = nullptr) : ptr(p), refCount(nullptr) {
        if (ptr) {
            refCount = new int(1);
        }
    }

    CustomSharedPtr(const CustomSharedPtr& other) : ptr(other.ptr), refCount(other.refCount) {
        if (refCount) {
            (*refCount)++;
        }
    }

    CustomSharedPtr& operator=(const CustomSharedPtr& other) {
        if (this != &other) {
            release();
            ptr = other.ptr;
            refCount = other.refCount;
            if (refCount) {
                (*refCount)++;
            }
        }
        return *this;
    }

    ~CustomSharedPtr() {
        release();
    }

    T& operator*() const {
        return *ptr;
    }

    T* operator->() const {
        return ptr;
    }

    bool isValid() const {
        return ptr != nullptr;
    }
};

int main() {
    // Create first shared pointer and initialize with value 5
    CustomSharedPtr<int> firstPtr(new int(5));

    // Create second shared pointer by copying the first one
    CustomSharedPtr<int> secondPtr = firstPtr;

    // Dereference and print values - both point to same memory location
    std::cout << *firstPtr << std::endl;   // Output: 5
    std::cout << *secondPtr << std::endl;  // Output: 5

    // Modify value through first pointer
    *firstPtr = 10;

    // Both pointers reflect the change since they share the same object
    std::cout << *firstPtr << std::endl;   // Output: 10
    std::cout << *secondPtr << std::endl;  // Output: 10

    return 0;  // Automatic cleanup when both shared pointers go out of scope
}

#include <vector>
#include <algorithm>

class MemoryManager {
private:
    int capacity;
    std::vector<bool> blockStatus;  // Tracks whether each memory block is in use

public:
    MemoryManager(int totalBlocks) : capacity(totalBlocks), blockStatus(totalBlocks, false) {}

    int findAndReserve(int requiredBlocks) {
        for (int start = 0; start <= capacity - requiredBlocks; ++start) {
            bool isFree = true;
            for (int k = 0; k < requiredBlocks && isFree; ++k) {
                if (blockStatus[start + k]) {
                    isFree = false;
                }
            }
            if (isFree) {
                for (int pos = start; pos < start + requiredBlocks; ++pos) {
                    blockStatus[pos] = true;
                }
                return start;
            }
        }
        return -1;
    }

    void release(int location) {
        if (location >= 0 && location < capacity) {
            blockStatus[location] = false;
        }
    }
};

