    void enqueueVideoRequest(const VideoRequest& request) {
        std::lock_guard<std::mutex> guard(requestMutex);
        requestsMap[request.getRequestID()] = request;
    }

    void executePendingRequests() {
        std::vector<std::thread> workerThreads;

        for (const auto& pair : requestsMap) {
            workerThreads.emplace_back(&VideoRequestor::handleSingleRequest, this, pair.first);
        }

        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

