// Shuffle a vector using Fisher-Yates algorithm with alternative RNG setup
template <typename T>
void fisherYatesShuffle(std::vector<T>& arr) {
    // Use a different random number generator seed source
    std::random_device rd;
    std::mt19937_64 rng(rd());

    // Start from the last element and move backwards
    for (size_t idx = arr.size(); idx > 1; --idx) {
        // Generate random index in [0, idx-1]
        std::uniform_int_distribution<size_t> dist(0, idx - 1);
        size_t pos = dist(rng);

        // Swap elements at positions idx-1 and pos
        std::swap(arr[idx - 1], arr[pos]);
    }
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    fisherYatesShuffle(data);

    // Output the shuffled elements
    for (const int& value : data) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

