class Stack {
private:
    std::vector<T> m_Elements;
    size_t m_Size;

public:
    Stack() : m_Size(0) {}

    void push(const T& value, bool allowOverride) {
        if (allowOverride || m_Elements.empty()) {
            m_Elements.push_back(value);
        } else {
            T combined = mergeValues(m_Elements.back(), value);
            m_Elements.push_back(combined);
        }
        m_Size = m_Elements.size();
    }

    T mergeValues(const T& first, const T& second) {
        // Generic merging logic - for numeric types this would add them
        // For other types, appropriate combination logic should be implemented
        // This is a placeholder requiring T to have appropriate operators
