    }

    // Additional utility functions for completeness
    const T& top() const {
        if (m_Elements.empty()) {
            throw std::runtime_error("Stack is empty");
        }
        return m_Elements.back();
    }

    void pop() {
        if (!m_Elements.empty()) {
            m_Elements.pop_back();
            m_Size = m_Elements.size();
