};

bool AckBitField::IsSetCorrespondingAckBit(PacketSN ackSN)
{
    uint32_t distance = 0;
    PacketSN currentSN = ackSN;

    while (RealtimeSrvHelper::SNGreaterThan(latestAckSN_, currentSN))
    {
        ++distance;
        ++currentSN;
    }

    if (distance == 0) 
    {
        return false;
    }

    uint32_t index = distance - 1;
    uint32_t bytePosition = index >> 3;
    uint32_t bitPosition = index & 0x7;

    if (bytePosition >= bitField.size())
    {
        return false;
    }

    uint8_t targetByte = bitField[bytePosition];
    uint8_t mask = static_cast<uint8_t>(1U << bitPosition);
    return (targetByte & mask) != 0;
}

