#include <type_traits>
#include <limits>

// Helper to compute index recursively
template<typename T, typename Seq, std::size_t N = 0>
struct IndexHelper;

// Base case: empty sequence - type not found
template<typename T, template<typename...> class Seq, std::size_t N>
struct IndexHelper<T, Seq<>, N> : std::integral_constant<std::size_t, std::numeric_limits<std::size_t>::max()> {};

// Recursive case: first element matches
template<typename T, template<typename...> class Seq, typename First, typename... Rest, std::size_t N>
struct IndexHelper<T, Seq<First, Rest...>, N> 
    : std::conditional_t<
        std::is_same_v<T, First>,
        std::integral_constant<std::size_t, N>,
        IndexHelper<T, Seq<Rest...>, N + 1>
      > {};

// Main Index trait
template<typename T, template<typename...> class Seq, typename... Ts>
struct Index : IndexHelper<T, Seq<Ts...>> {};

// Contains trait using helper
template<typename T, template<typename...> class Seq, typename... Ts>
struct Contains : IndexHelper<T, Seq<Ts...>, 0> {
    static constexpr bool value = (IndexHelper<T, Seq<Ts...>, 0>::value != std::numeric_limits<std::size_t>::max());
};

