#include <algorithm>

// Reorganize Vulkan image memory barriers by grouping them per image and ordering by subresource range
std::vector<vk::ImageMemoryBarrier> organizeImageMemoryBarriers(
    const std::vector<vk::ImageMemoryBarrier>& preBarriersInput,
    const std::vector<vk::ImageMemoryBarrier>& postBarriersInput) {

  // Map each image to its associated barriers
  std::map<vk::Image, std::vector<vk::ImageMemoryBarrier>> imageToBarriers;

  // Collect all pre-barriers into the map
  for (const auto& barrier : preBarriersInput) {
    imageToBarriers[barrier.image].push_back(barrier);
  }

  // Collect all post-barriers into the map
  for (const auto& barrier : postBarriersInput) {
    imageToBarriers[barrier.image].push_back(barrier);
  }

  std::vector<vk::ImageMemoryBarrier> result;

  // Process each image's barriers separately
  for (const auto& [imageHandle, barriers] : imageToBarriers) {
    std::vector<vk::ImageMemoryBarrier> writeBarriers;
    std::vector<vk::ImageMemoryBarrier> readBarriers;

    // Separate barriers based on access type
    for (const auto& b : barriers) {
      if ((b.srcAccessMask & vk::AccessFlagBits::eMemoryWrite) != vk::AccessFlags{}) {
        writeBarriers.push_back(b);
      } else {
        readBarriers.push_back(b);
      }
    }

    // Sort write barriers by subresource range
    std::sort(writeBarriers.begin(), writeBarriers.end(),
              [](const vk::ImageMemoryBarrier& a, const vk::ImageMemoryBarrier& b) {
                return std::tie(a.subresourceRange.baseMipLevel, a.subresourceRange.baseArrayLayer) <
                       std::tie(b.subresourceRange.baseMipLevel, b.subresourceRange.baseArrayLayer);
              });

    // Sort read barriers similarly
    std::sort(readBarriers.begin(), readBarriers.end(),
              [](const vk::ImageMemoryBarrier& a, const vk::ImageMemoryBarrier& b) {
                return std::tie(a.subresourceRange.baseMipLevel, a.subresourceRange.baseArrayLayer) <
                       std::tie(b.subresourceRange.baseMipLevel, b.subresourceRange.baseArrayLayer);
              });

    // Append sorted barriers to final list: writes first, then reads
    result.insert(result.end(), writeBarriers.begin(), writeBarriers.end());
    result.insert(result.end(), readBarriers.begin(), readBarriers.end());
  }

  return result;
}

case opcode::relative_jump_if_false:
{
  // Read the jump offset from the instruction stream
  std::int32_t jump_offset = ip.read<std::int32_t>();

  // Check if we should perform the conditional jump
  bool condition_met = false;
  if (!co.stack.empty()) {
    std::uint8_t top_value = co.stack.top< std::uint8_t >();
    condition_met = (top_value == 0);
