QString processString(const QString &input) {
    // Convert input to UnicodeString and apply NFC normalization
    UnicodeString unicodeInput = UnicodeString::fromUTF8(input.toUtf8().constData());
    unicodeInput = unicodeInput.unormalize(UNORM_NFC);

    // Transform all characters to uppercase
    unicodeInput = unicodeInput.toUpper();

    // Search for occurrences of "QT" and replace with "qatomicstring"
    UnicodeString searchPattern = "QT";
    UnicodeString replaceWith = "qatomicstring";
    int32_t pos = 0;
    while ((pos = unicodeInput.indexOf(searchPattern, pos)) != -1) {
        unicodeInput.remove(pos, searchPattern.length());
        unicodeInput.insert(pos, replaceWith);
        pos += replaceWith.length();
    }

