// A generic stack implementation using a linked list structure
template <typename T>
class Stack {
private:
    // Internal node structure to hold data and pointer to next node
    struct StackNode {
        T element;
        StackNode* link;
        StackNode(const T& val) : element(val), link(nullptr) {}
    };

    StackNode* head;  // Points to the top of the stack

public:
    // Constructor initializes an empty stack
    Stack() : head(nullptr) {}

    // Destructor to clean up remaining nodes (not in original but good practice)
    ~Stack() {
        while (!empty()) {
            pop();
        }
    }

    // Add an element to the top of the stack
    void push(const T& value) {
        StackNode* newNode = new StackNode(value);
        newNode->link = head;
        head = newNode;
    }

    // Remove and return the top element from the stack
    T pop() {
        if (head == nullptr) {
            throw std::out_of_range("Stack is empty");
        }
        T value = head->element;
        StackNode* temp = head;
        head = head->link;
        delete temp;
        return value;
    }

    // Return the top element without removing it
    T peek() const {  // Renamed from 'top' to 'peek' for clarity
        if (head == nullptr) {
            throw std::out_of_range("Stack is empty");
        }
        return head->element;
    }

    // Check whether the stack contains any elements
    bool isEmpty() const {  // Renamed from 'empty' to 'isEmpty'
        return head == nullptr;
    }
};

