class MSE {
private:
    double loss;
public:
    // Constructor and other methods are not shown for brevity
    // Compute the derivative of the MSE loss function
    std::vector<double> deriv(const std::vector<double>& prediction, int8_t expected_int) const {
        // Convert expected integer to one-hot vector
        size_t class_count = prediction.size();
        std::vector<double> target_vector(class_count, 0.0);
        target_vector[static_cast<size_t>(expected_int)] = 1.0;

        // Calculate gradient of mean squared error
        std::vector<double> grad_vector(class_count);
        for (size_t idx = 0; idx < class_count; ++idx) {
            grad_vector[idx] = 2.0 * (prediction[idx] - target_vector[idx]) / static_cast<double>(class_count);
        }
        return grad_vector;
    }
};

