    // Record how many times each element appears in the first vector
    for (const std::string& item : inputA) {
        frequency[item]++;
    }

    // Check elements from second vector against recorded frequencies
    for (const std::string& item : inputB) {
        if (frequency.find(item) != frequency.end() && frequency[item] > 0) {
            output.push_back(item);
            frequency[item]--;
        }
    }

    return output;
}

