// Abstract command interface
class Command {
public:
    virtual ~Command() = default;
    virtual void perform() = 0;
    virtual void reverse() = 0;
    virtual void repeat() = 0;
};

// Concrete implementation for full selection operation
class FullSelectCommand : public Command {
private:
    std::vector<Item> currentSelection;     // Holds the current set of selected items
    std::vector<Item> priorState;           // Stores the state before last operation

public:
    FullSelectCommand(const std::vector<Item>& initialItems) 
        : currentSelection(initialItems) {}

    void perform() override {
        // Capture previous state before changing selection
        priorState = currentSelection;

        // Replace with complete list of available items
        currentSelection = fetchAllItems();

        std::cout << "Complete selection applied" << std::endl;
    }

    void reverse() override {
        // Restore previous selection state
        currentSelection = priorState;
        std::cout << "Previous selection restored" << std::endl;
    }

    void repeat() override {
        // Reapply the full selection
        perform();
    }

private:
    std::vector<Item> fetchAllItems() {
        // Retrieve all possible items from the application context
        // Implementation details omitted
        return std::vector<Item>();
    }
};

int main() {
    std::vector<Item> initialItems = { /* Initialize with some items */ };
    FullSelectCommand selector(initialItems);

    // Apply full selection
    selector.perform();

    // Revert to previous selection
    selector.reverse();

    // Reapply full selection again
    selector.repeat();

