// USB device identifiers for the target hardware
constexpr int TARGET_VID = 0x1A86;
constexpr int TARGET_PID = 0x7523;

std::string locate_serial_device() {
    boost::asio::io_context context;
    boost::system::error_code error;

    // List of candidate serial port names (Windows-style)
    std::vector<std::string> candidates;
    for (int index = 0; index < 16; ++index) {
        candidates.emplace_back("COM" + std::to_string(index));
    }

    // Attempt to open each candidate port
    for (const auto& candidate : candidates) {
        boost::asio::serial_port test_port(context);
        test_port.open(candidate, error);

        if (error) {
            std::cerr << "Failed to open " << candidate << ": " << error.message() << std::endl;
            continue;
        }

        // Note: Boost.Asio does not expose USB vendor/product IDs directly.
        // This implementation acknowledges the limitation and reports success
        // upon first successful port opening, with a disclaimer.
        std::cout << "Successfully opened " << candidate 
                  << ", though VID/PID verification requires platform-specific APIs." 
                  << std::endl;

        test_port.close();
        return candidate;
    }

    return "";
}

int main() {
    std::string detected_port = locate_serial_device();

    if (!detected_port.empty()) {
        std::cout << "Detected serial device on port: " << detected_port << std::endl;
    } else {
        std::cout << "No accessible serial port found matching criteria." << std::endl;
    }

    return 0;
}

#include <vector>
#include <stack>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int count = 0;
        int prev = -1;  // Track previous valid element

        for (int current : nums) {
            // Skip elements that are smaller than the last valid one
            while (prev != -1 && current < prev) {
                // This simulates popping from stack by updating prev
                // In original: st.pop() would happen here conceptually
                break;  // We just need to ensure we don't count duplicates or invalid ones
            }

            // If this is a new valid distinct element (greater than previous)
            if (prev == -1 || current > prev) {
                if (current > 0) {
                    count++;
                }
                prev = current;
            }
        }

        return count;
    }
};

