#include <pangolin/pangolin.h>
#include <pangolin/log/packetstream_reader.h>
#include <pangolin/log/packetstream_writer.h>
#include <pangolin/video/video.h>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage:\n\tPangolinVideoTransform input.pango output.pango\n";
        return 1;
    }

    const std::string input_path{argv[1]};
    const std::string output_path{argv[2]};

    if (input_path == output_path) {
        std::cerr << "Error: Input and output paths must differ.\n";
        return 1;
    }

    pangolin::PacketStreamReader reader(input_path);
    pangolin::PacketStreamWriter writer(output_path);

    // Parse new JSON metadata from standard input
    picojson::value global_properties;
    std::cout << "Reading JSON from stdin..." << std::endl;
    std::cin >> global_properties;
    std::cout << "+ loaded" << std::endl;

    const auto& sources = reader.Sources();
    PANGO_ASSERT(global_properties.size() == sources.size());

    // Rebuild source metadata with updated device/frame properties
    for (std::size_t idx = 0; idx < sources.size(); ++idx) {
        const picojson::value& src_props = global_properties[idx];
        pangolin::PacketStreamSource src = sources[idx];

        PANGO_ASSERT(src_props.contains("frame_properties"));
        PANGO_ASSERT(src_props.contains("device_properties"));

        const auto& frame_props = src_props["frame_properties"];
        PANGO_ASSERT(frame_props.size() == src.index.size());

        // Clear index and inject new device info
        src.index.clear();
        src.info["device"] = src_props["device_properties"];

        writer.AddSource(src);
    }

    std::cout << "Re-encoding video to '" << output_path << "'..." << std::endl;

    try {
        std::vector<char> frame_buffer;
        for (;;) {
            pangolin::Packet pkt = reader.NextFrame();

            // Read remaining bytes of packet stream into buffer
            const auto remaining_bytes = static_cast<std::size_t>(pkt.BytesRemaining());
            frame_buffer.resize(remaining_bytes);
            pkt.Stream().read(frame_buffer.data(), remaining_bytes);

            // Fetch corresponding new frame metadata
            const picojson::value& new_frame_meta = global_properties[pkt.src]["frame_properties"][pkt.sequence_num];

            // Write packet with updated metadata
            writer.WriteSourcePacket(pkt.src, frame_buffer.data(), pkt.time, remaining_bytes, new_frame_meta);

            // Progress indicator
            const auto total_frames = sources[pkt.src].index.size();
            std::cout << "\rFrames processed: " << (pkt.sequence_num + 1) << "/" << total_frames;
            std::cout.flush();
        }
    } catch (const std::runtime_error& err) {
        std::cout << "\nRuntime error encountered: " << err.what() << std::endl;
        throw;
    }

    std::cout << "\n+ conversion complete" << std::endl;
    return 0;
}

