// Forward declare the "fuzz target" interface.
// We deliberately keep this interface simple and header-free.
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

// Process input files and feed their contents to the fuzz target
int main(int argc, char **argv) {
  // Skip the program name (index 0)
  for (int fileIndex = 1; fileIndex < argc; ++fileIndex) {
    std::ifstream inputFile(argv[fileIndex]);

    if (!inputFile.is_open()) {
      std::cerr << "Error: Could not open file " << argv[fileIndex] << std::endl;
      continue;
    }

    // Determine file size by seeking to end and back
    inputFile.seekg(0, std::ios::end);
    std::streampos fileSize = inputFile.tellg();
    inputFile.seekg(0, std::ios::beg);

    std::cout << "Reading " << static_cast<size_t>(fileSize) 
              << " bytes from " << argv[fileIndex] << std::endl;

    // Create buffer with exact file size
    std::vector<char> buffer(static_cast<size_t>(fileSize));

    // Read file content into buffer
    inputFile.read(buffer.data(), fileSize);

    // Pass data to fuzz target
    LLVMFuzzerTestOneInput(reinterpret_cast<const uint8_t *>(buffer.data()),
                           buffer.size());

    std::cout << "Execution successful" << std::endl;
  }

  std::cout << "Execution finished" << std::endl;
  return 0;
}

