void process_case() {
    int total_pens;
    std::cin >> total_pens;

    std::vector<int> remaining;
    for (int i = 0; i < total_pens; ++i) {
        remaining.push_back(i);
    }

    while (remaining.size() > 2) {
        std::vector<int> survivors;

        for (int idx : remaining) {
            std::cout << "0 " << idx << std::endl;
            std::cout.flush();

            int answer;
            std::cin >> answer;

            if (answer == 1) {
                survivors.push_back(idx);
            }
        }

        remaining = survivors;

        if (remaining.size() <= 2) {
            break;
        }
    }

    // Handle edge cases where we might have fewer than 2 candidates
    if (remaining.size() < 2) {
        if (remaining.empty()) {
            std::cout << "1 0 1" << std::endl;
        } else {
            int first_pen = remaining[0];
            int second_pen = (first_pen + 1) % total_pens;
            std::cout << "1 " << first_pen << " " << second_pen << std::endl;
        }
        return;
    }

    int pen_a = remaining[0];
    int pen_b = remaining[1];
    std::cout << "1 " << pen_a << " " << pen_b << std::endl;
}

