        process_case();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

// This program constructs a 20x20 grid map for the "Kangaroos" challenge.
// The layout features a central horizontal corridor (the "backbone") with
// vertical corridors ("teeth") extending upward and downward at alternating columns.
// This design enforces spatial separation: movement along the backbone is primarily
// horizontal, while side corridors restrict motion to vertical directions.
// Random commands are unlikely to synchronize agents across these disjoint paths,
// and dead-ends in the teeth further hinder aggregation.

void generateMap() {
    const int rows = 20;
    const int cols = 20;

    std::cout << rows << " " << cols << "\n";

    // Initialize grid with empty cells
    std::vector<std::string> grid(rows, std::string(cols, '0'));

    // Position the main horizontal corridor near the middle
    const int spineRow = rows / 2 - 1;

    // Construct the horizontal spine
    for (int col = 0; col < cols; ++col) {
        grid[spineRow][col] = '1';
    }

    // Add vertical branches at even-numbered columns
    for (int col = 0; col < cols; col += 2) {
        // Extend upward from the spine
        for (int row = 0; row < spineRow; ++row) {
            grid[row][col] = '1';
        }
        // Extend downward from the spine
        for (int row = spineRow + 1; row < rows; ++row) {
            grid[row][col] = '1';
        }
    }

    // Output the final map configuration
    for (int row = 0; row < rows; ++row) {
        std::cout << grid[row] << "\n";
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    generateMap();

    return 0;
}

