#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> replaceNonCoprimes(std::vector<int>& nums) {
        std::vector<int> stack;

        for (int current : nums) {
            stack.push_back(current);

            // Keep merging adjacent non-coprime elements from the end
            while (stack.size() >= 2) {
                int last = stack.back();
                int secondLast = stack[stack.size() - 2];
                int gcdValue = std::gcd(last, secondLast);

                if (gcdValue <= 1) {
                    break;  // Elements are coprime, stop merging
                }

                // Remove the two elements
                stack.pop_back();
                stack.pop_back();

                // Insert their LCM in place
                long long lcm = static_cast<long long>(last) * secondLast / gcdValue;
                stack.push_back(static_cast<int>(lcm));
            }
        }

        return stack;
    }
};

