    int buffers[] = {1, 2, 3, 4, 5};
    std::size_t total_buffers = sizeof(buffers) / sizeof(buffers[0]);

    // Initialize consumer state
    std::size_t current_index = 0;
    int accumulated_sum = 0;

    // Process buffers until exhausted
    while (current_index < total_buffers) {
        // Extract next buffer value and accumulate
        accumulated_sum += buffers[current_index];
