int n, m;
std::vector<int> towers[60];
std::vector<std::pair<int, int>> operations;

void transfer_ball(int source, int dest) {
    if (source == dest || towers[source].empty()) {
        return;
    }
    int ball = towers[source].back();
    towers[source].pop_back();
    towers[dest].push_back(ball);
    operations.push_back({source, dest});
}

void clear_tower(int src, int dst) {
    while (!towers[src].empty()) {
        transfer_ball(src, dst);
    }
}

