    std::cin.tie(nullptr);

    std::cin >> n >> m;
    for (int idx = 1; idx <= n; ++idx) {
        towers[idx].resize(m);
        for (int pos = 0; pos < m; ++pos) {
            std::cin >> towers[idx][pos];
        }
    }

    // Process each color in order: ensure pillar i contains only balls of color i
    for (int target_color = 1; target_color <= n; ++target_color) {
        // Move all contents from pillars target_color to n into the auxiliary tower (n+1)
        for (int src = target_color; src <= n; ++src) {
            clear_tower(src, n + 1);
        }

        // Now distribute balls from the auxiliary tower back to appropriate destinations
        while (!towers[n + 1].empty()) {
            int current_ball = towers[n + 1].back();
            if (current_ball == target_color) {
                transfer_ball(n + 1, target_color);
            } else {
                transfer_ball(n + 1, current_ball);
            }
        }

        // After this iteration, pillar 'target_color' is correctly filled with balls of color 'target_color'
    }

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

