namespace mozjs
{
    GlobalHeapManager::GlobalHeapManager(JSContext* ctx)
        : m_context(ctx), m_nextId(0) {}

    std::unique_ptr<GlobalHeapManager> GlobalHeapManager::Create(JSContext* ctx)
    {
        return std::make_unique<GlobalHeapManager>(ctx);
    }

    void GlobalHeapManager::RegisterUser(IHeapUser* heapUser)
    {
        std::scoped_lock lock(m_userMutex);
        m_registeredUsers.insert(heapUser);
    }

    void GlobalHeapManager::UnregisterUser(IHeapUser* heapUser)
    {
        std::scoped_lock lock(m_userMutex);
        m_registeredUsers.erase(heapUser);
    }

    uint32_t GlobalHeapManager::Store(JS::HandleValue valueToStore)
    {
        std::scoped_lock lock(m_storageMutex);

        // Clear any stale unused entries before allocating new ones
        if (!m_staleEntries.empty())
        {
            m_staleEntries.clear();
        }

        // Find next available ID
        uint32_t candidateId = m_nextId;
        while (m_entries.find(candidateId) != m_entries.end())
        {
            ++candidateId;
        }
        m_nextId = candidateId + 1;

        m_entries[candidateId] = std::make_unique<HeapElement>(valueToStore);
        return candidateId;
    }

    uint32_t GlobalHeapManager::Store(JS::HandleObject valueToStore)
    {
        JS::RootedValue jsValue(m_context, JS::ObjectValue(*valueToStore));
        return Store(jsValue);
    }

    uint32_t GlobalHeapManager::Store(JS::HandleFunction valueToStore)
    {
        JS::RootedObject jsObject(m_context, JS_GetFunctionObject(valueToStore));
        return Store(jsObject);
    }

    JS::Heap<JS::Value>& GlobalHeapManager::Get(uint32_t id)
    {
        std::scoped_lock lock(m_storageMutex);

        // Ensure no stale entries remain
        if (!m_staleEntries.empty())
        {
            m_staleEntries.clear();
        }

        auto it = m_entries.find(id);
        if (it == m_entries.end())
        {
            throw std::runtime_error("Attempted to access non-existent heap element");
        }

        return *(it->second);
    }

    void GlobalHeapManager::Remove(uint32_t id)
    {
        std::scoped_lock lock(m_storageMutex);

        auto it = m_entries.find(id);
        if (it != m_entries.end())
        {
            m_staleEntries.push_back(std::move(it->second));
            m_entries.erase(it);
        }
    }

    void GlobalHeapManager::Trace(JSTracer* trc)
    {
        std::scoped_lock lock(m_storageMutex);

        for (auto& [key, elem] : m_entries)
        {
            JS::TraceEdge(trc, elem.get(), "CustomHeap_Global");
        }

        for (auto& elem : m_staleEntries)
        {
            JS::TraceEdge(trc, elem.get(), "CustomHeap_Global");
        }
    }

    void GlobalHeapManager::PrepareForGc()
    {
        std::scoped_lock userLock(m_userMutex);
        for (auto* user : m_registeredUsers)
        {
            if (user)
            {
                user->PrepareForGlobalGc();
            }
        }

        std::scoped_lock storageLock(m_storageMutex);
        m_staleEntries.clear();
        m_entries.clear();
    }
}

#include "comms/torchcomms/nccl/TorchWorkNCCL.hpp"

namespace torch::comms {

TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::garbageCollectLocked() {
  TorchWorkNCCL::WorkStatus prev_status = TorchWorkNCCL::WorkStatus::COMPLETED;

  // Iterate over all stream queues
  for (auto iter = stream_work_queues_.begin(); iter != stream_work_queues_.end(); ) {
    auto& work_list = iter->second;

    // Process each work item in this stream’s queue
    while (!work_list.empty()) {
      auto current_work = work_list.front();
      TorchWorkNCCL::WorkStatus current_state = current_work->checkStatus();
      prev_status = current_state;

      if (current_state == TorchWorkNCCL::WorkStatus::COMPLETED) {
        work_list.pop();
        // Continue checking next item
      } else if (
          current_state == TorchWorkNCCL::WorkStatus::TIMEDOUT ||
          current_state == TorchWorkNCCL::WorkStatus::ERROR) {
        // Propagate terminal error state immediately
        return current_state;
      } else {
        // Stop processing this stream’s queue on non-terminal states
        break;
      }
    }

    // Remove empty stream queues from the map
    if (work_list.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return prev_status;
}

// Thread-safety: This method is called from the timeout watchdog thread while
// the main thread may be enqueuing work via enqueueWork(). The
// work_queues_mutex_ ensures proper synchronization — both garbageCollect() and
// enqueueWork() acquire the mutex before accessing stream_work_queues_.
TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  return garbageCollectLocked();
}

TorchWorkNCCL::WorkStatus TorchWorkNCCLQueue::finalize() {
  // Defensive locking even though timeout thread should be joined already
  std::lock_guard<std::mutex> guard(work_queues_mutex_);

  TorchWorkNCCL::WorkStatus final_status = TorchWorkNCCL::WorkStatus::COMPLETED;

  // Keep cleaning until queue is empty or terminal status reached
  for (; !stream_work_queues_.empty(); ) {
    final_status = garbageCollectLocked();

    if (final_status == TorchWorkNCCL::WorkStatus::ERROR ||
        final_status == TorchWorkNCCL::WorkStatus::TIMEDOUT ||
        final_status == TorchWorkNCCL::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure no lingering references remain to avoid leaks
  stream_work_queues_.clear();
  return final_status;
}

void TorchWorkNCCLQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCL> work,
    cudaStream_t stream) {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  stream_work_queues_[stream].push(std::move(work));
}

