    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}

TEST(PythonVersionParsing, TryScanVersion) {
    struct TestCase {
        TString Input;
        bool ExpectedSuccess;
        TPythonVersion ExpectedResult;
    };

    std::vector<TestCase> cases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };

    for (const auto& test : cases) {
        TMaybe<TPythonVersion> actual = TryScanVersion(
            TConstArrayRef<char>{test.Input.data(), test.Input.size()}
        );

        if (test.ExpectedSuccess) {
            ASSERT_TRUE(actual.Defined()) 
                << "Expected to parse version from: '" << test.Input << "'";

            // Format expected and actual versions as strings for clearer error messages
            TString expStr = std::to_string(test.ExpectedResult.MajorVersion) + "." +
                             std::to_string(test.ExpectedResult.MinorVersion) + "." +
                             std::to_string(test.ExpectedResult.MicroVersion);
            TString actStr = std::to_string(actual->MajorVersion) + "." +
                             std::to_string(actual->MinorVersion) + "." +
                             std::to_string(actual->MicroVersion);

            EXPECT_EQ(actual->MajorVersion, test.ExpectedResult.MajorVersion)
                << "Major version mismatch for input '" << test.Input << "' (expected: " << expStr << ", got: " << actStr << ")";
            EXPECT_EQ(actual->MinorVersion, test.ExpectedResult.MinorVersion)
                << "Minor version mismatch for input '" << test.Input << "' (expected: " << expStr << ", got: " << actStr << ")";
            EXPECT_EQ(actual->MicroVersion, test.ExpectedResult.MicroVersion)
                << "Micro version mismatch for input '" << test.Input << "' (expected: " << expStr << ", got: " << actStr << ")";
        } else {
            EXPECT_FALSE(actual.Defined())
                << "Should not have parsed version from: '" << test.Input << "'";
        }
    }
}

