#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> removeAnagrams(std::vector<std::string>& words) {
        if (words.empty()) return {};

        std::vector<std::string> result;
        result.push_back(words[0]);

        for (size_t i = 1; i < words.size(); ++i) {
            // Create frequency maps for current and previous word
            std::unordered_map<char, int> freqCurrent, freqPrevious;

            for (char c : words[i]) {
                freqCurrent[c]++;
            }
            for (char c : words[i-1]) {
                freqPrevious[c]++;
            }

            // Compare frequency maps - if different, add current word
            if (freqCurrent != freqPrevious) {
                result.push_back(words[i]);
            }
        }

        return result;
    }
};

