// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

class Validator {
public:
    void collectInOrder(TreeNode* node, vector<int>& result) {
        if (node == nullptr) return;
        collectInOrder(node->left, result);
        result.push_back(node->val);
        collectInOrder(node->right, result);
    }

    bool checkBinarySearchTree(TreeNode* root) {
        vector<int> sequence;
        collectInOrder(root, sequence);

        // Verify that the in-order traversal yields strictly increasing values
        for (size_t idx = 1; idx < sequence.size(); ++idx) {
            if (sequence[idx] <= sequence[idx - 1]) {
                return false;
            }
        }
        return true;
    }
};

