using namespace llvm;

#define DEBUG_TYPE "double barriers"
STATISTIC(NumDMBsRemoved, "Number of DMBs removed");

namespace {
class ARMOptimizeBarriersPass : public MachineFunctionPass {
public:
  static char ID;
  ARMOptimizeBarriersPass() : MachineFunctionPass(ID) {}

  bool runOnMachineFunction(MachineFunction &Fn) override;

  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }

  StringRef getPassName() const override { 
    return "barrier optimization pass"; 
  }
};

char ARMOptimizeBarriersPass::ID = 0;
}

// Determines if a machine instruction can be reordered across a DMB barrier.
// An instruction is considered safe to move if it does not involve memory operations,
// side effects, calls, or returns.
static bool IsSafeToMoveAcrossDMB(const MachineInstr *Instr) {
  // Check for any operation that would prevent reordering
  if (Instr->mayLoad() || Instr->mayStore() ||
      Instr->hasUnmodeledSideEffects() ||
      Instr->isCall() || Instr->isReturn()) {
    return false;
  }
  return true;
}

bool ARMOptimizeBarriersPass::runOnMachineFunction(MachineFunction &MF) {
  if (skipFunction(MF.getFunction()))
    return false;

  std::vector<MachineInstr *> CandidatesForRemoval;
  int64_t LastDMBType = -1;
  bool NextDMBIsCandidate = false;

  // Traverse all basic blocks and their instructions
  for (auto &Block : MF) {
    for (auto &Instr : Block) {
      if (Instr.getOpcode() == ARM::DMB) {
        int64_t CurrentDMBType = Instr.getOperand(0).getImm();

        if (NextDMBIsCandidate) {
          // A previous DMB was seen; check if current one can be removed
          if (CurrentDMBType == LastDMBType) {
            CandidatesForRemoval.push_back(&Instr);
          } else {
            // Different type: update tracking but keep scanning
            LastDMBType = CurrentDMBType;
          }
        } else {
          // First DMB encountered in this region
          NextDMBIsCandidate = true;
          LastDMBType = CurrentDMBType;
        }
      } else if (!IsSafeToMoveAcrossDMB(&Instr)) {
        // Non-reorderable instruction resets the candidate flag
        NextDMBIsCandidate = false;
      }
    }
  }

  bool Modified = false;
  for (auto *Instr : CandidatesForRemoval) {
    Instr->eraseFromParent();
    ++NumDMBsRemoved;
    Modified = true;
  }

  return Modified;
}

/// createARMOptimizeBarriersPass - Returns an instance of the barrier
/// optimization pass.
FunctionPass *llvm::createARMOptimizeBarriersPass() {
  return new ARMOptimizeBarriersPass();
}

#include "ReduceInstructions.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include <vector>
#include <unordered_set>
using namespace llvm;

// Determine if an instruction must be preserved regardless of reduction strategy
static bool mustPreserve(const Instruction &I) {
  // Preserve exception handling pads, token-typed instructions, and Swift error operations
  return I.isEHPad() || I.getType()->isTokenTy() || I.isSwiftError();
}

// Collect all instructions that should not be removed during reduction
static std::vector<Instruction*> collectSafeInstructions(Module &M, const Oracle &O) {
  std::vector<Instruction*> safeList;

  for (auto &Function : M) {
    for (auto &BasicBlock : Function) {
      // Always keep terminators to maintain basic block structure
      safeList.push_back(BasicBlock.getTerminator());

      // Process non-terminator instructions
      auto termPos = std::prev(BasicBlock.end());
      for (auto iter = BasicBlock.begin(); iter != termPos; ++iter) {
        Instruction &inst = *iter;
        if (mustPreserve(inst) || O.shouldKeep()) {
          safeList.push_back(&inst);
        }
      }
    }
  }

  return safeList;
}

// Replace uses of an instruction with a default value and mark for deletion
static void prepareForRemoval(Instruction *I, std::vector<Instruction*> &deletionQueue) {
  I->replaceAllUsesWith(getDefaultValue(I->getType()));
  deletionQueue.push_back(I);
}

// Main reduction routine: remove non-critical instructions from the module
static void extractInstrFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &program = WorkItem.getModule();

  // First pass: collect all instructions that must be preserved
  auto safeInstructions = collectSafeInstructions(program, O);

  // Convert to set for efficient lookup
  std::unordered_set<Instruction*> keepSet(safeInstructions.begin(), safeInstructions.end());

  // Second pass: identify instructions for removal
  std::vector<Instruction*> toRemove;
  for (auto &function : program) {
    for (auto &basicBlock : function) {
      for (auto &instruction : basicBlock) {
        if (keepSet.find(&instruction) == keepSet.end()) {
          prepareForRemoval(&instruction, toRemove);
        }
      }
    }
  }

  // Final pass: actually remove the instructions
  for (auto *inst : toRemove) {
    inst->eraseFromParent();
  }
}

void llvm::reduceInstructionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractInstrFromModule, "Reducing Instructions");
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

// Function to ask a query and handle termination
int query(int x, int y) {
    cout << "? " << x << " " << y << endl;
    int result;
    cin >> result;
    if (result == -1) {
        exit(0);
    }
    return result;
}

void findImpostor() {
    int size;
    if (!(cin >> size)) return;

    // Create list of player IDs from 1 to size
    vector<int> players(size);
    iota(players.begin(), players.end(), 1);

    // Shuffle players to randomize order for better average performance
    mt19937 engine(chrono::steady_clock::now().time_since_epoch().count());
    shuffle(players.begin(), players.end(), engine);

    int impostor = -1;

    // Process players in adjacent pairs
    int maxPairIndex = size - (size % 2);

    for (int idx = 0; idx < maxPairIndex; idx += 2) {
        int first = players[idx];
        int second = players[idx + 1];

        // Get mutual opinions between the two players
        int opinionA = query(first, second);
        int opinionB = query(second, first);

        // If opinions differ, one of them is the impostor
        if (opinionA != opinionB) {
            // Choose a witness who's definitely not in this pair
            int witness;
            if (idx > 0) {
                witness = players[0];  // Safe since first pair hasn't been processed yet
            } else {
                witness = players[2];  // Safe as long as n >= 3
            }

            // Ask both players about the witness
            int opinionFirst = query(first, witness);
            int opinionSecond = query(second, witness);

            if (opinionFirst != opinionSecond) {
                // One is truthful (Knight), one is lying (Impostor)
                // Knight says 1 about Impostor, Impostor lies and says 0
                if (opinionA == 0) {
                    impostor = first;
                } else {
                    impostor = second;
                }
            } else {
                // Both gave same answer about witness → both lying (Knave & Impostor)
                // Knave sees Impostor as Knight and lies (says 0)
                // Impostor sees Knave as Knave and lies (says 1)
                if (opinionA == 1) {
                    impostor = first;
                } else {
                    impostor = second;
                }
            }

            cout << "! " << impostor << endl;
            return;
        }
    }

    // If no asymmetric pair found and size is odd, leftover is impostor
    if (size % 2 == 1) {
        cout << "! " << players.back() << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            findImpostor();
        }
    }

    return 0;
}

