void ThrownEnderpearl::onHit(HitResult *hitResult)
{
	// Handle hit on an entity
	if (nullptr != hitResult->entity)
	{
		DamageSource *src = DamageSource::thrown(shared_from_this(), owner);
		hitResult->entity->hurt(src, 0);
		delete src;
	}

	// Emit ender particles around impact point
	for (int idx = 0; idx < 32; ++idx)
	{
		level->addParticle(
			eParticleType_ender,
			x,
			y + random->nextDouble() * 2.0,
			z,
			random->nextGaussian(),
			0.0,
			random->nextGaussian()
		);
	}

	// Server-side behavior only
	if (level->isClientSide)
		return;

	// Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered: TU8: Code: Gameplay: The title crashes on Host's console when Client Player leaves the game before the Ender Pearl thrown by him touches the ground.
	shared_ptr<ServerPlayer> playerPtr = dynamic_pointer_cast<ServerPlayer>(owner);
	if (!playerPtr || playerPtr->removed)
		return;

	ServerPlayer *player = playerPtr.get();
	if (player->connection->done || player->level != level)
		return;

	// Teleport owner to pearl location and apply fall damage
	owner->teleportTo(x, y, z);
	owner->fallDistance = 0.0f;
	owner->hurt(DamageSource::fall, 5);

	// Clean up the pearl after use
	remove();
}

