void U4MLManager::ConfigureAsServer(FRPCServer& Server)
{
	// Setup logging for server configuration
	UE_LOG(LogUE4ML, Verbose, TEXT("Setting up server-side RPC handlers"));

	// Register shared (common) functions first
	AddCommonFunctions(Server);

#if WITH_RPCLIB
	// Manual world tick toggle handler
	Server.bind("enable_manual_world_tick", [this](bool bEnableManualTick) {
		SetManualWorldTickEnabled(bEnableManualTick);
	});
	Librarian.AddRPCFunctionDescription(
		TEXT("enable_manual_world_tick"),
		TEXT("(), Controls whether the world runs in real time or manually via step/request_world_tick. Default: real time.")
	);

	// World tick request handler — rewritten using do-while instead of while loop,
	// and with inverted condition for clarity
	Server.bind("request_world_tick", [this](int32 RequestedTicks, bool bShouldBlock) {
		if (!bTickWorldManually) return;

		StepsRequested = RequestedTicks;
		do
		{
			if (StepsRequested <= 0) break;
			FPlatformProcess::Sleep(0.0f);
		} while (bShouldBlock);

		return;
	});
	Librarian.AddRPCFunctionDescription(
		TEXT("request_world_tick"),
		TEXT("(int RequestedTicks, bool bShouldBlock), Triggers RequestedTicks number of world ticks if manual mode is active. Blocks until completion if bShouldBlock is true.")
	);

	// Session termination handler — renamed lambda parameter for variety
	Server.bind("close_session", [this]() {
		U4MLManager::Get().SetSession(nullptr);
	});
	Librarian.AddRPCFunctionDescription(
		TEXT("close_session"),
		TEXT("(), Terminates the active session and detaches all associated agents.")
	);
#endif // WITH_RPCLIB

	// Delegate to session if present
	if (Session.IsValid())
	{
		Session->ConfigureAsServer();
	}

	// Notify listeners that server functions have been added
	OnAddServerFunctions.Broadcast(Server);
}

