#include <iostream>
#include <vector>
#include <cmath>
#include <tuple>

// Stores the generated edges in the form (source, intermediate, target)
std::vector<std::tuple<int, int, int>> edge_list;

/**
 * @brief Adds a set of edges representing jumps of length 'jump_len'
 *        using intermediate vertices at distance 'first_hop' from source.
 * 
 * For each valid start vertex i, adds edge (i -> i + jump_len) justified by
 * existing path i -> (i + first_hop) -> (i + jump_len), where second hop length = jump_len - first_hop.
 */
void generate_jumps(int jump_len, int max_vertex, int first_hop_length) {
    if (jump_len > max_vertex) return;

    for (int start = 0; start <= max_vertex - jump_len; ++start) {
        edge_list.emplace_back(start, start + first_hop_length, start + jump_len);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Handle trivial cases: no edges needed for graphs with <= 1 vertex
    if (n <= 1) {
        std::cout << 0 << "\n";
        return 0;
    }

    // Determine optimal parameter k to minimize total edges
    // Approximate optimal k ≈ n^(1/3)
    int k = static_cast<int>(std::round(std::cbrt(n)));
    if (k < 2 && n > 1) k = 2; // Ensure k >= 2 for meaningful decomposition

    // Step 1: Build small jumps [2, k-1]
    for (int len = 2; len < k; ++len) {
        generate_jumps(len, n, len - 1);
    }

    // Step 2: Build multiples of k: {k, 2k, ..., (k-1)k}
    if (k <= n) {
        generate_jumps(k, n, k - 1);
    }
    for (int multiplier = 2; multiplier < k; ++multiplier) {
        generate_jumps(multiplier * k, n, (multiplier - 1) * k);
    }

    // Step 3: Build multiples of k^2: {k^2, 2k^2, ..., A*k^2}, where A = floor(n/k^2)
    int square_k = k * k;
    if (square_k <= n) {
        generate_jumps(square_k, n, (k - 1) * k);
    }

    int max_multiplier = n / square_k;
    for (int mult = 2; mult <= max_multiplier; ++mult) {
        generate_jumps(mult * square_k, n, (mult - 1) * square_k);
    }

    // Output results
    std::cout << edge_list.size() << "\n";
    for (const auto& edge : edge_list) {
        std::cout << std::get<0>(edge) << " "
                  << std::get<1>(edge) << " "
                  << std::get<2>(edge) << "\n";
    }

    return 0;
}

