namespace sdb {
namespace {

// A singleton instance used to monitor system-wide resource usage
GlobalResourceMonitor gResourceMonitor;

}  // namespace

int64_t GlobalResourceMonitor::current() const noexcept {
  return _currentVal.load(std::memory_order_relaxed);
}

GlobalResourceMonitor::Stats GlobalResourceMonitor::stats() const noexcept {
  return Stats{
    .global_exceeded = 
      _globalExceedCount.load(std::memory_order_relaxed),
    .local_exceeded = 
      _localExceedCount.load(std::memory_order_relaxed)
  };
}

void GlobalResourceMonitor::trackGlobalViolation() noexcept {
  _globalExceedCount.fetch_add(1, std::memory_order_relaxed);
}

void GlobalResourceMonitor::trackLocalViolation() noexcept {
  _localExceedCount.fetch_add(1, std::memory_order_relaxed);
}

/// Attempt to increase memory usage by <delta> bytes.
/// Returns false if the operation would exceed the configured limit (if any).
/// Otherwise, atomically updates the current usage and returns true.
bool GlobalResourceMonitor::increaseMemoryUsage(int64_t delta) noexcept {
  SDB_ASSERT(delta >= 0);

  if (_maxLimit == 0) {
    // No limit enforced: simply accumulate
    _currentVal.fetch_add(delta, std::memory_order_relaxed);
    return true;
  }

  // Enforce limit using compare-and-swap loop
  int64_t oldVal = _currentVal.load(std::memory_order_relaxed);
  while (true) {
    int64_t newVal = oldVal + delta;
    if (newVal > _maxLimit) [[unlikely]] {
      return false;  // Would exceed limit
    }
    if (_currentVal.compare_exchange_weak(oldVal, newVal,
                                          std::memory_order_relaxed)) {
      return true;   // Successfully updated
    }
    // CAS failed: retry with updated oldVal
  }
}

void GlobalResourceMonitor::decreaseMemoryUsage(int64_t delta) noexcept {
  SDB_ASSERT(delta >= 0);
  _currentVal.fetch_sub(delta, std::memory_order_relaxed);
}

void GlobalResourceMonitor::forceUpdateMemoryUsage(int64_t delta) noexcept {
  _currentVal.fetch_add(delta, std::memory_order_relaxed);
}

GlobalResourceMonitor& GlobalResourceMonitor::instance() noexcept {
  return gResourceMonitor;
}

}  // namespace sdb

