// Default constructor: creates an uninitialized patch object (used for optional initialization)
RelPatchObj::RelPatchObj() VB_NOEXCEPT 
    : positionAfterInstruction_(0U), 
      binary_(nullptr), 
      initialized_(false), 
      short_(false) {
}

// Constructor with full parameters: initializes a valid patch object
RelPatchObj::RelPatchObj(bool const isShort, uint32_t const posAfterInstr, MemWriter &binary) VB_NOEXCEPT
    : positionAfterInstruction_(posAfterInstr),
      binary_(&binary),
      initialized_(true),
      short_(isShort) {
}

// Link the jump to the current end of the binary buffer
void RelPatchObj::linkToHere() const {
  assert(initialized_ && "Attempting to apply relocation to an uninit'd jump");
  linkToBinaryPos(binary_->size());
}

// Patch the jump target to a specific offset within the binary
void RelPatchObj::linkToBinaryPos(uint32_t const targetOffset) const {
  assert(initialized_ && "Attempting to write to an uninitialized jump");

  uint8_t* const instrEndPtr = binary_->posToPtr(positionAfterInstruction_);
  int64_t const displacement = static_cast<int64_t>(targetOffset) - static_cast<int64_t>(positionAfterInstruction_);

  if (short_) {
    // Enforce range constraint at runtime (should be guaranteed by caller)
    if (displacement < INT8_MIN || displacement > INT8_MAX) {
      throw std::runtime_error("JMP offset exceeds 8-bit signed range");
    }
    // Write signed 8-bit displacement just before the instruction end
    writeToPtr<int8_t>(pSubI(instrEndPtr, 1U), static_cast<int8_t>(displacement));
  } else {
    // Check for 32-bit overflow (unlikely in practice)
    if (displacement <= INT32_MIN || displacement >= INT32_MAX) {
      throw ImplementationLimitationException(ErrorCode::BrHANDLE_ERRORanches_can_only_maximally_target_32_bit_signed_offsets);
    }
    // Write signed 32-bit displacement four bytes before instruction end
    writeToPtr<int32_t>(pSubI(instrEndPtr, 4U), static_cast<int32_t>(displacement));
  }
}

// Retrieve the current target offset of this jump
uint32_t RelPatchObj::getLinkedBinaryPos() const VB_NOEXCEPT {
  assert(initialized_ && "Attempting to read from an uninitialized jump");

  uint8_t const* const instrEndPtr = binary_->posToPtr(positionAfterInstruction_);
  int64_t result;

  if (short_) {
    int8_t const disp8 = readFromPtr<int8_t>(pSubI(instrEndPtr, 1));
    result = static_cast<int64_t>(positionAfterInstruction_) + disp8;
  } else {
    int32_t const disp32 = readFromPtr<int32_t>(pSubI(instrEndPtr, 4));
    result = static_cast<int64_t>(positionAfterInstruction_) + disp32;
  }

  assert(result >= 0 && result <= UINT32_MAX && "Computed target offset out of range");
  return static_cast<uint32_t>(result);
}

