namespace {
    ULONG_PTR g_gdiplusToken = 0;

    class GdiplusInitializer : public initquit {
    public:
        void on_init() override {
            // Initialize GDI+ subsystem
            Gdiplus::GdiplusStartupInput startupInput;
            Gdiplus::GdiplusStartup(&g_gdiplusToken, &startupInput, nullptr);

            // Pre-initialize PlaybackStateManager to register callbacks early
            nowbar::PlaybackStateManager::get();

            // Set up artwork bridge for online cover art support
            init_artwork_bridge();
        }

        void on_quit() override {
            // Deregister artwork callback first
            shutdown_artwork_bridge();

            // Perform orderly shutdown of static components
            // ControlPanelCore must be shut down before PlaybackStateManager
            nowbar::ControlPanelCore::shutdown();
            nowbar::PlaybackStateManager::shutdown();

            // Clean up GDI+ resources
            if (g_gdiplusToken) {
                Gdiplus::GdiplusShutdown(g_gdiplusToken);
                g_gdiplusToken = 0;
            }
        }
    };

    static initquit_factory_t<GdiplusInitializer> g_gdiplus_init;
