// Helper function to convert wide string path to narrow char* for POSIX systems
static std::string wstringToNarrow(const std::wstring& wstr) {
    if (wstr.empty()) return {};
    size_t len = wcstombs(nullptr, wstr.c_str(), 0);
    if (len == static_cast<size_t>(-1)) return {};
    std::string result(len, '\0');
    wcstombs(&result[0], wstr.c_str(), len + 1);
    return result;
}

// Helper to throw on invalid file handle (placeholder for exception handling)
[[noreturn]] static void throwFileException(const std::string& msg) {
    throw std::runtime_error(msg);
}

FileOutputStream::FileOutputStream(const File &file) : m_fileHandle(INVALID_HANDLE_VALUE) {
    // Early check: reject directories
    if (file.exists() && file.isDirectory()) {
        throwFileException("Cannot open directory as file output stream");
    }

#ifdef _DURANGO
    std::string pathA = wstringToNarrow(file.getPath());
    m_fileHandle = CreateFileA(
        pathA.c_str(),
        GENERIC_WRITE,
        0, // no sharing
        nullptr,
        OPEN_ALWAYS,
        FILE_ATTRIBUTE_NORMAL,
        nullptr
    );
#elif defined(__linux__)
    std::string pathA = wstringToNarrow(file.getPath());
    int fd = ::open(pathA.c_str(), O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        throwFileException("Failed to open file for writing");
    }
    m_fileHandle = reinterpret_cast<void*>(fd);
#else
    std::string pathA = wstringToNarrow(file.getPath());
    m_fileHandle = CreateFileA(
        pathA.c_str(),
        GENERIC_WRITE,
        0,
        nullptr,
        OPEN_ALWAYS,
        FILE_ATTRIBUTE_NORMAL,
        nullptr
    );
#endif

    if (m_fileHandle == INVALID_HANDLE_VALUE) {
        throwFileException("FileOutputStream: Unable to open file for writing");
    }
}

FileOutputStream::~FileOutputStream() noexcept {
    close();
}

void FileOutputStream::write(unsigned int b) {
    byte value = static_cast<byte>(b);

#if defined(_WIN32)
    DWORD written = 0;
    BOOL ok = WriteFile(
        m_fileHandle,
        &value,
        1,
        &written,
        nullptr
    );
    if (!ok || written != 1) {
        throwFileException("Write failed: single byte");
    }
#else
    int fd = static_cast<int>(reinterpret_cast<uintptr_t>(m_fileHandle));
    ssize_t written = ::write(fd, &value, 1);
    if (written != 1) {
        throwFileException("Write failed: single byte (POSIX)");
    }
#endif
}

void FileOutputStream::write(const byteArray& b) {
    write(b, 0, b.size()); // delegate to offset/length version
}

void FileOutputStream::write(const byteArray& b, unsigned int offset, unsigned int length) {
    if (offset + length > b.size()) {
        throwFileException("Buffer overflow in write(): offset + length exceeds buffer size");
    }

#if defined(_WIN32)
    DWORD written = 0;
    BOOL ok = WriteFile(
        m_fileHandle,
        b.data() + offset,
        static_cast<DWORD>(length),
        &written,
        nullptr
    );
    if (!ok || written != length) {
        throwFileException("Write failed: partial or zero bytes written");
    }
#else
    int fd = static_cast<int>(reinterpret_cast<uintptr_t>(m_fileHandle));
    ssize_t written = ::write(fd, b.data() + offset, length);
    if (written != static_cast<ssize_t>(length)) {
        throwFileException("Write failed: incomplete write (POSIX)");
    }
#endif
}

void FileOutputStream::close() noexcept {
    if (m_fileHandle == INVALID_HANDLE_VALUE) {
        return; // already closed
    }

#if defined(_WIN32)
    CloseHandle(m_fileHandle);
#else
    int fd = static_cast<int>(reinterpret_cast<uintptr_t>(m_fileHandle));
    ::close(fd);
#endif

    m_fileHandle = INVALID_HANDLE_VALUE;
}

#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>

using namespace jnsc;

// Test buffer resizing and basic write/read operations
TEST(CircularAudioBufferTest, ResizeAndWriteRead) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 8);

    ASSERT_EQ(audioBuffer.getNumChannels(), 2u);
    ASSERT_EQ(audioBuffer.getBufferSize(), 8u);

    // Write sample values to each channel
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(1, 2.0f);

    // Verify the written values are correctly read back
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 2.0f);
}

// Test circular behavior when writing beyond buffer capacity
TEST(CircularAudioBufferTest, WrapAround) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    // Overwrite data to trigger wrap-around effect
    for (int idx = 0; idx < 6; ++idx)
        audioBuffer.write(0, static_cast<float>(idx));

    // After 6 writes into a size-4 buffer: [2,3,4,5] with 5 being most recent
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 5.0f);  // latest
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 2.0f);
}

// Test clearing the buffer and subsequent writes
TEST(CircularAudioBufferTest, Clear) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    audioBuffer.write(0, 1.0f);
    audioBuffer.write(0, 2.0f);
    audioBuffer.clear();

    // After clear, new data should start fresh
    audioBuffer.write(0, 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
}

// Test multi-channel buffer behavior
TEST(CircularAudioBufferTest, MultiChannel) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 4);

    // Fill both channels with distinct sequences
    for (int step = 0; step < 4; ++step) {
        audioBuffer.write(0, static_cast<float>(step));
        audioBuffer.write(1, static_cast<float>(step + 10));
    }

    // Verify latest values per channel
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 13.0f);

    // Verify oldest values still accessible via offset
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 0.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 3), 10.0f);
}

#include "SteamSocketsTaskManager.h"
#include "SteamSocketsSubsystem.h"

void FSteamSocketsTaskManager::OnConnectionStatusChanged(SteamNetConnectionStatusChangedCallback_t* SteamConnectionMessage)
{
	// This method is invoked on the Steam OSS's internal thread.
	// As per Steam's callback mechanism, we must copy the data immediately,
	// since the provided pointer will become invalid after returning.
	MessageQueue.Enqueue(*SteamConnectionMessage);
}

void FSteamSocketsTaskManager::OnConnectionStatusChangedGS(SteamNetConnectionStatusChangedCallback_t* SteamConnectionMessage)
{
	// Similar to the above, enqueue a copy of the message for later processing
	MessageQueue.Enqueue(*SteamConnectionMessage);
}

void FSteamSocketsTaskManager::Tick()
{
	SteamNetConnectionStatusChangedCallback_t CallbackData;
	// Process all queued events until the queue is empty
	while (!MessageQueue.IsEmpty())
	{
		// Reset the local buffer before use
		FMemory::Memzero(CallbackData);

		// Attempt to dequeue and handle the next message
		if (SocketSubsystem && MessageQueue.Dequeue(CallbackData))
		{
			SocketSubsystem->SteamSocketEventHandler(&CallbackData);
		}
		else
		{
			// Exit loop if dequeuing fails (e.g., race condition or corruption)
			break;
		}
	}
}

