// Helper function to add two integers
inline int add_two_integers(int a, int b) {
    return a + b;
}

// Function to prepend a prefix to a string
inline std::string format_with_prefix(std::string text) {
    return "output: " + text;
}

int main() {
    std::cout << "=== function overloading ===" << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // Overload multiple functions under the same name "process"
    // Ensure each overload has distinct parameter types
    lua_vm.set_function("process", 
        sol::overload(
            [](int value) { return value; }, 
            format_with_prefix, 
            add_two_integers
        )
    );

    // Execute Lua script using overloaded function
