// Helper function to extract the Reverb plugin instance from an audio device
static ResonanceAudio::FResonanceAudioReverb* ExtractReverbPlugin(FAudioDevice* Device)
{
	return static_cast<ResonanceAudio::FResonanceAudioReverb*>(Device->ReverbPluginInterface.Get());
}

void UResonanceAudioBlueprintFunctionLibrary::SetGlobalReverbPreset(UResonanceAudioReverbPluginPreset* NewPreset)
{
	// Access the active Resonance Audio module
	ResonanceAudio::FResonanceAudioModule& AudioModule = FModuleManager::GetModuleChecked<ResonanceAudio::FResonanceAudioModule>("ResonanceAudio");
	TArray<FAudioDevice*>& ActiveDevices = AudioModule.GetRegisteredAudioDevices();

	// Apply the new preset to all devices that support reverb
	for (FAudioDevice* Device : ActiveDevices)
	{
		ResonanceAudio::FResonanceAudioReverb* ReverbInstance = ExtractReverbPlugin(Device);
		if (ReverbInstance != nullptr)
		{
			ReverbInstance->SetGlobalReverbPluginPreset(NewPreset);
		}
	}
}

UResonanceAudioReverbPluginPreset* UResonanceAudioBlueprintFunctionLibrary::GetGlobalReverbPreset()
{
	UResonanceAudioReverbPluginPreset* FoundPreset = nullptr;

	// Retrieve the Resonance Audio module and its registered devices
	ResonanceAudio::FResonanceAudioModule& AudioModule = FModuleManager::GetModuleChecked<ResonanceAudio::FResonanceAudioModule>("ResonanceAudio");
	TArray<FAudioDevice*> const& DeviceList = AudioModule.GetRegisteredAudioDevices();

	// Search for the first device with a valid reverb plugin to fetch the current preset
	for (FAudioDevice* Device : DeviceList)
	{
		ResonanceAudio::FResonanceAudioReverb* ReverbPlugin = ExtractReverbPlugin(Device);
		if (ReverbPlugin != nullptr)
		{
			FoundPreset = ReverbPlugin->GetGlobalReverbPluginPreset();
			break; // Stop after finding the first available preset
		}
	}

	return FoundPreset;
}

