#include "yaml-cpp/eventhandler.h"
#include "yaml-cpp/yaml.h"  // IWYU pragma: keep

struct Configuration {
  bool inputProvided;
  std::string inputFile;
};

Configuration ProcessArguments(int argc, char** argv) {
  Configuration cfg;
  std::vector<std::string> argumentList(argv + 1, argv + argc);
  cfg.inputProvided = (argc > 1);
  if (cfg.inputProvided) {
    cfg.inputFile = argv[1];
  }
  return cfg;
}

class SilentHandler : public YAML::EventHandler {
 public:
  void OnDocumentStart(const YAML::Mark&) override {}
  void OnDocumentEnd() override {}
  void OnNull(const YAML::Mark&, YAML::anchor_t) override {}
  void OnAlias(const YAML::Mark&, YAML::anchor_t) override {}
  void OnScalar(const YAML::Mark&, const std::string&, YAML::anchor_t,
                const std::string&) override {}
  void OnSequenceStart(const YAML::Mark&, const std::string&, YAML::anchor_t,
                       YAML::EmitterStyle::value) override {}
  void OnSequenceEnd() override {}
  void OnMapStart(const YAML::Mark&, const std::string&, YAML::anchor_t,
                  YAML::EmitterStyle::value) override {}
  void OnMapEnd() override {}
};

void ProcessInput(std::istream& stream) {
  try {
    YAML::Node document = YAML::Load(stream);
    std::cout << document << "\n";
  } catch (const YAML::Exception& error) {
    std::cerr << error.what() << "\n";
  }
}

int main(int argc, char** argv) {
  Configuration config = ProcessArguments(argc, argv);

  if (config.inputProvided) {
    std::ifstream fileStream(config.inputFile);
    if (fileStream.is_open()) {
      ProcessInput(fileStream);
      fileStream.close();
    } else {
      std::cerr << "Error: Could not open file '" << config.inputFile << "'\n";
      return 1;
    }
  } else {
    ProcessInput(std::cin);
  }

  return 0;
}

