#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Process one test case by discovering words through queries
void processTestCase() {
    int totalWords;
    std::cin >> totalWords;

    // Store discovered words in a set for uniqueness
    std::set<std::string> discovered;

    // Try each starting character from 'a' to 'z'
    for (char startChar = 'a'; startChar <= 'z'; ++startChar) {
        // Early exit if we've found all required words
        if (discovered.size() >= totalWords) {
            break;
        }

        // Build prefix string from current character
        std::string currentPrefix = std::string(1, startChar);

        // Exponential probing strategy
        int probeSize = 1;
        bool prefixExhausted = false;

        while (!prefixExhausted) {
            // Submit query with current prefix and requested count
            std::cout << "query " << currentPrefix << " " << probeSize << std::endl;

            // Read response
            int receivedCount;
            std::cin >> receivedCount;

            // Extract the words returned in this response
            for (int idx = 0; idx < receivedCount; ++idx) {
                std::string word;
                std::cin >> word;
                discovered.insert(word);
            }

            // Determine if we've exhausted this prefix
            if (receivedCount < probeSize || probeSize == totalWords) {
                prefixExhausted = true;
            } else {
                // Double the probe size for next iteration
                probeSize *= 2;
                if (probeSize > totalWords) {
                    probeSize = totalWords;
                }
            }
        }
    }

    // Output the collected words
    std::cout << "answer";
    for (const std::string& word : discovered) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCaseCount;
    std::cin >> testCaseCount;

    while (testCaseCount-- > 0) {
        processTestCase();
    }

    return 0;
}

