void init_rrt(nanobind::module_& m) {
  // Node class binding: represents a vertex in the motion graph
  nanobind::class_<Node>(m, "Node", "A node in the search tree used by planning algorithms.")
      .def(nanobind::init<const Eigen::VectorXd&, int>(), "configuration"_a, "parent_index"_a)
      .def_ro("configuration", &Node::config, "The robot's joint configuration stored at this node.")
      .def_ro("parent_index", &Node::parent_id, "Index of the parent node in the tree.");

  // RRTOptions class binding: configuration parameters for the RRT planner
  nanobind::class_<RRTOptions>(m, "RRTOptions", "Configuration settings for the RRT motion planner.")
      .def(nanobind::init<const std::string&, size_t, double, double, double, double, bool>(),
           "joint_group"_a = "", "maximum_nodes"_a = 1000u, "connection_radius"_a = 3.0,
           "collision_resolution"_a = 0.05, "goal_sampling_rate"_a = 0.15,
           "time_limit"_a = 0.0, "bidirectional_mode"_a = false)
      .def_rw("joint_group", &RRTOptions::group_name,
              "Name of the robot's kinematic group to plan for.")
      .def_rw("maximum_nodes", &RRTOptions::max_nodes, "Upper bound on the number of nodes to generate.")
      .def_rw("connection_radius", &RRTOptions::max_connection_distance,
              "Maximum Euclidean distance in configuration space for connecting nodes.")
      .def_rw("collision_resolution", &RRTOptions::collision_check_step_size,
              "Incremental step size used during collision verification along paths.")
      .def_rw("goal_sampling_rate", &RRTOptions::goal_biasing_probability,
              "Frequency (as a probability) of biasing samples toward the goal configuration.")
      .def_rw("time_limit", &RRTOptions::max_planning_time,
              "Maximum duration allowed for planning, in seconds.")
      .def_rw("bidirectional_mode", &RRTOptions::rrt_connect,
              "Enable bidirectional RRT-Connect strategy if true.");

  // RRT class binding: main motion planning algorithm implementation
  nanobind::class_<RRT>(
      m, "RRT", "Motion planner implementing the Rapidly-exploring Random Tree algorithm.")
      .def(nanobind::init<const std::shared_ptr<Scene>, const RRTOptions&>(), "environment"_a,
           "settings"_a)
      .def("plan_path", unwrap_expected(&RRT::plan), "Compute a trajectory between start and goal.", 
           "initial_config"_a, "target_config"_a)
      .def("seed_rng", &RRT::setRngSeed, "Initialize the random number generator with a fixed seed.",
           "value"_a)
      .def("extract_trees", &RRT::getNodes,
           "Retrieve both trees' node collections for debugging or visualization.");
}

