#include <vector>

class Solution {
public:
    bool stoneGame(std::vector<int>& piles) {
        int totalOdd = 0;
        int totalEven = 0;
        int size = piles.size();

        // Calculate sum of stones at odd positions (0-indexed: indices 0, 2, 4...)
        for (int idx = 0; idx < size; idx += 2) {
            totalOdd += piles[idx];
        }

        // Calculate sum of stones at even positions (0-indexed: indices 1, 3, 5...)
        for (int idx = 1; idx < size; idx += 2) {
            totalEven += piles[idx];
        }

        // Alice can always choose to pick all odd-positioned or all even-positioned piles
        // So she picks the group with more stones, guaranteeing her win
        return totalOdd != totalEven;
    }
};

