#include <iostream>
#include <vector>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long target_value;
    std::cin >> target_value;

    // Determine how many rows we'll need based on bit processing
    const int MAX_ROWS = 100;
    std::vector<std::vector<int>> adjacency(MAX_ROWS + 2, std::vector<int>(MAX_ROWS + 2, 0));

    int current_layer = 1;

    // Process each bit position from least significant to most significant
    for (int bit_pos = 0; bit_pos < 61; ++bit_pos) {
        // Always add the default transition to next layer
        adjacency[current_layer][current_layer + 1] = 1;

        // If current bit is set, add direct connections from all previous layers
        if ((target_value >> bit_pos) & 1LL) {
            for (int prev_layer = 1; prev_layer < current_layer; ++prev_layer) {
                adjacency[prev_layer][current_layer + 1] = 1;
            }
        }

        current_layer++;
    }

    // Connect all active layers to the final column
    for (int layer = 1; layer <= current_layer; ++layer) {
        adjacency[layer][current_layer] = 1;
    }

    // Output dimensions and adjacency matrix
    std::cout << current_layer << "\n";
    for (int row = 1; row <= current_layer; ++row) {
        for (int col = 1; col <= current_layer; ++col) {
            std::cout << adjacency[row][col];
            if (col < current_layer) std::cout << " ";
        }
        std::cout << "\n";
    }

    return 0;
}

