    void initialize_logging() {
#ifdef RC_LOGGING
        std::error_code err;

        // Ensure the root directory exists
        std::filesystem::create_directories(ReCraftCore::GetRootDir(), err);

        // Handle existing log file: move current log to .last.txt
        const std::string root_dir = ReCraftCore::GetRootDir();
        const std::string log_path = root_dir + "/log.txt";
        const std::string backup_path = root_dir + "/log.last.txt";

        if (std::filesystem::exists(log_path, err)) {
            if (std::filesystem::exists(backup_path, err)) {
                std::filesystem::remove(backup_path, err);
            }
            std::filesystem::rename(log_path, backup_path, err);
        }

        // Open new log file
        log_stream.open(log_path);
#endif
    }

    void finalize_logging() {
#ifdef RC_LOGGING
        close_log_file();
#endif
    }

    void record_crash(const std::string& message) {
        std::ofstream crash_file(ReCraftCore::GetRootDir() + "/crash.txt");
        if (crash_file.is_open()) {
            crash_file << message;
            crash_file.close();
