#include <iostream>
#include <vector>
#include <queue>
#include <cmath>

// Solution for LeetCode problem 1046: Last Stone Weight
// Simulates smashing the two heaviest stones repeatedly until at most one remains
using namespace std;

class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        // Use a max-heap (priority queue) to efficiently retrieve the largest stones
        priority_queue<int> heap;

        // Insert all stone weights into the heap
        for (int weight : stones) {
            heap.push(weight);
        }

        // Process stones until fewer than two remain
        while (heap.size() >= 2) {
            // Extract the two heaviest stones
            int heavy = heap.top();
            heap.pop();
            int lighter = heap.top();
            heap.pop();

            // If they're not equal, push the difference back
            if (heavy != lighter) {
                heap.push(abs(heavy - lighter));
            }
            // If equal, both are destroyed (nothing pushed back)
        }

        // Return the remaining stone's weight or 0 if none remain
        return heap.empty() ? 0 : heap.top();
    }
};

