using namespace llvm;

char IntervalPartition::ID = 0;

IntervalPartition::IntervalPartition() : FunctionPass(ID) {
  initializeIntervalPartitionPass(*PassRegistry::getPassRegistry());
}

INITIALIZE_PASS(IntervalPartition, "intervals",
                "Interval Partition Construction", true, true)

//===----------------------------------------------------------------------===//
// IntervalPartition Implementation
//===----------------------------------------------------------------------===//

void IntervalPartition::releaseMemory() {
  // Deallocate all interval objects stored in the list
  for (size_t idx = 0; idx < Intervals.size(); ++idx)
    delete Intervals[idx];

  IntervalMap.clear();
  Intervals.clear();
  RootInterval = nullptr;
}

void IntervalPartition::print(raw_ostream &O, const Module*) const {
  for (unsigned i = 0; i < Intervals.size(); ++i)
    Intervals[i]->print(O);
}

// insertIntervalIntoStructure - Insert an interval into internal storage and
// register each contained basic block as mapped to this interval.
void IntervalPartition::insertIntervalIntoStructure(Interval *intervalObj) {
  Intervals.push_back(intervalObj);

  // For every basic block in this interval, record its mapping
  for (auto nodeIt = intervalObj->Nodes.begin(), endIt = intervalObj->Nodes.end();
       nodeIt != endIt; ++nodeIt) {
    IntervalMap.emplace(*nodeIt, intervalObj);
  }
}

// propagatePredecessorInfo - After constructing intervals, fill in predecessor
// lists using known successor relationships.
void IntervalPartition::propagatePredecessorInfo(Interval *currentInt) {
  BasicBlock *headerBB = currentInt->getHeaderNode();
  for (BasicBlock *succBB : currentInt->Successors) {
    Interval *succInterval = getBlockInterval(succBB);
    succInterval->Predecessors.push_back(headerBB);
  }
}

// runOnFunction - Construct initial-level interval partition for given function
bool IntervalPartition::runOnFunction(Function &funcRef) {
  // Begin iteration over intervals; pass false because we assume ownership
  function_interval_iterator iterStart = intervals_begin(&funcRef, false);
  assert(iterStart != intervals_end(&funcRef) && "No intervals found in function!");

  // First interval becomes root
  insertIntervalIntoStructure(RootInterval = *iterStart);
  ++iterStart;

  // Process remaining intervals
  function_interval_iterator iterEnd = intervals_end(&funcRef);
  for (; iterStart != iterEnd; ++iterStart) {
    insertIntervalIntoStructure(*iterStart);
  }

  // Populate predecessor info based on successor data
  for (size_t k = 0; k < Intervals.size(); ++k) {
    propagatePredecessorInfo(Intervals[k]);
  }

  return false;
}

// IntervalPartition constructor (from existing partition)
// Builds reduced interval partition from another IntervalPartition instance.
IntervalPartition::IntervalPartition(IntervalPartition &sourceIP, bool /*unused*/)
  : FunctionPass(ID) {
  assert(sourceIP.getRootInterval() && "Cannot process empty IntervalPartition!");

  // Start interval iteration on source partition
  interval_part_interval_iterator partIterBegin = intervals_begin(sourceIP, false);
  assert(partIterBegin != intervals_end(sourceIP) && "Source has no intervals!");

  // First interval is root
  insertIntervalIntoStructure(RootInterval = *partIterBegin);
  ++partIterBegin;

  // Add rest of intervals
  interval_part_interval_iterator partIterEnd = intervals_end(sourceIP);
  for (; partIterBegin != partIterEnd; ++partIterBegin) {
    insertIntervalIntoStructure(*partIterBegin);
  }

  // Propagate predecessor information
  for (unsigned j = 0; j < Intervals.size(); ++j) {
    propagatePredecessorInfo(Intervals[j]);
  }
}

