using namespace llvm;

// Finalize module-level exception metadata
void WasmException::endModule() {
  // For non-position-independent builds, emit symbols for C++ exceptions and C longjmps.
  // These are only emitted if they were referenced somewhere in the module.
  //
  // In dynamic linking scenarios, we avoid defining them here; instead, they're
  // declared undefined and defined externally (e.g., in JS).
  if (!Asm->isPositionIndependent()) {
    const char* ExceptionSymbols[] = {"__cpp_exception", "__c_longjmp"};
    for (const auto* SymbolName : ExceptionSymbols) {
      SmallString<60> MangledName;
      Mangler::getNameWithPrefix(MangledName, SymbolName, Asm->getDataLayout());

      if (MCSymbol* Sym = Asm->OutContext.lookupSymbol(MangledName)) {
        MCSymbol* ExnSym = Asm->GetExternalSymbolSymbol(SymbolName);
        Asm->OutStreamer->emitLabel(ExnSym);
      }
    }
  }
}

// Handle per-function exception table emission
void WasmException::endFunction(const MachineFunction* Func) {
  bool NeedsLandingPadTable = false;
  for (const LandingPadInfo& Info : Func->getLandingPads()) {
    if (Func->hasWasmLandingPadIndex(Info.LandingPadBlock)) {
      NeedsLandingPadTable = true;
      break;
    }
  }

  if (!NeedsLandingPadTable)
    return;

  MCSymbol* TableStart = emitExceptionTable();
  assert(TableStart && ".GCC_exception_table symbol missing!");

  // Emit end marker and compute size for ELF .size directive
  MCSymbol* TableEnd = Asm->createTempSymbol("GCC_except_table_end");
  Asm->OutStreamer->emitLabel(TableEnd);

  MCContext& Context = Asm->OutStreamer->getContext();
  const MCExpr* SizeExpr = MCBinaryExpr::createSub(
      MCSymbolRefExpr::create(TableEnd, Context),
      MCSymbolRefExpr::create(TableStart, Context),
      Context);

  Asm->OutStreamer->emitELFSize(TableStart, SizeExpr);
}

// Construct call-site table for WebAssembly exception handling
//
// Note: In Wasm EH, each entry corresponds to a landing pad (not a call site),
// because unwinding is handled by the VM. After stack unwinding, control transfers
// via 'catch' instructions, and the personality function runs from compiled code.
void WasmException::computeCallSiteTable(
    SmallVectorImpl<CallSiteEntry>& Sites,
    SmallVectorImpl<CallSiteRange>& Ranges,
    const SmallVectorImpl<const LandingPadInfo*>& Pads,
    const SmallVectorImpl<unsigned>& FirstActions) {

  MachineFunction& MF = *Asm->MF;
  unsigned PadCount = Pads.size();

  for (unsigned Idx = 0; Idx < PadCount; ++Idx) {
    const LandingPadInfo* PadInfo = Pads[Idx];
    MachineBasicBlock* LPadBB = PadInfo->LandingPadBlock;

    // Skip landing pads not assigned an index (e.g., single catch(...))
    if (!MF.hasWasmLandingPadIndex(LPadBB))
      continue;

    unsigned PadIndex = MF.getWasmLandingPadIndex(LPadBB);
    CallSiteEntry Entry = {nullptr, nullptr, PadInfo, FirstActions[Idx]};

    if (Sites.size() <= PadIndex)
      Sites.resize(PadIndex + 1);

    Sites[PadIndex] = Entry;
  }
}

#include "Transform/LowerSelect.h"
#include <llvm/IR/Constants.h>
#include <llvm/IR/Instructions.h>
#include <llvm/IR/Verifier.h>
#include <llvm/Support/Debug.h>
#define DEBUG_TYPE "lower-select"

// Convert a select instruction to conditional branches + phi node.
// Splits the original block after the select, creates two successor blocks,
// and inserts a phi at the select's position to merge results.
static void rewriteSelectToBranches(Instruction *sel) {
  Function *func = sel->getFunction();
  BasicBlock *origBB = sel->getParent();

  // Split the block right after the select instruction.
  // Instructions *after* 'sel' move to the new block (PhiBB).
  BasicBlock *mergeBB = origBB->splitBasicBlock(sel, "");

  // Create dedicated blocks for true/false arms.
  BasicBlock *trueArm = BasicBlock::Create(sel->getContext(), "select.true", func, mergeBB);
  BasicBlock *falseArm = BasicBlock::Create(sel->getContext(), "select.false", func, mergeBB);

  // Each arm unconditionally jumps to the merge point.
  BranchInst::Create(mergeBB, trueArm);
  BranchInst::Create(mergeBB, falseArm);

  // Replace original terminator with conditional branch on condition operand.
  origBB->getTerminator()->eraseFromParent();
  BranchInst::Create(trueArm, falseArm, sel->getOperand(0), origBB);

  // Insert phi node to combine values from both arms.
  PHINode *phi = PHINode::Create(sel->getType(), 2, "", sel);
  phi->addIncoming(sel->getOperand(1), trueArm);
  phi->addIncoming(sel->getOperand(2), falseArm);

  // Redirect all uses of the select to the phi node, then delete select.
  sel->replaceAllUsesWith(phi);
  sel->eraseFromParent();
}

// Main pass logic: collect non-pointer selects, rewrite them, verify module.
PreservedAnalyses LowerSelectPass::run(Module &mod, ModuleAnalysisManager &) {
  std::vector<SelectInst *> candidates;

  // Traverse all functions, blocks, and instructions to find eligible selects.
  for (Function &F : mod) {
    if (F.isDeclaration()) continue;
    for (BasicBlock &BB : F) {
      for (Instruction &I : BB) {
        // Skip pointer-type selects (as per original policy)
        if (I.getType()->isPointerTy()) continue;

        if (SelectInst *SI = dyn_cast<SelectInst>(&I)) {
          candidates.push_back(SI);
        }
      }
    }
  }

  if (candidates.empty())
    return PreservedAnalyses::all();

  // Perform transformation on each collected select.
  for (SelectInst *sel : candidates)
    rewriteSelectToBranches(sel);

  // Verify integrity post-transformation.
  if (verifyModule(mod, &errs())) {
    llvm_unreachable("Error: Lowerselect fails...");
  }

  // CFG has changed; preserve nothing.
  return PreservedAnalyses::none();
}

