// Verify array initialization and fundamental functionality
void validate_array_initialization(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Array Initialization ===" << std::endl;

    std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
    std::shared_ptr<SMTParser::DAGNode> arr = parser->mkArray("sampleArray", int_sort, int_sort);
    assert(arr);
    std::string arr_str = parser->toString(arr);
    assert(arr_str.find("sampleArray") != std::string::npos);
    std::cout << "Initialized array: " << arr_str << std::endl;
    std::cout << std::endl;
}

// Validate array store and select operations
void validate_array_functionality(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"((as const (Array Int Int)) 0)", "0"},
        {"(store ((as const (Array Int Int)) 0) 1 10)", ""},
        {"(select (store ((as const (Array Int Int)) 0) 1 10) 1)", "10"},
        {"(select (store ((as const (Array Int Int)) 0) 1 10) 2)", "0"},
        {"(= (select (store ((as const (Array Int Int)) 0) 1 10) 1) 10)", "true"},
        {"(store (store ((as const (Array Int Int)) 0) 1 10) 2 20)", ""}
    };

    std::cout << "=== Validating Array Functionality ===" << std::endl;
    for (const auto& test_case : test_cases) {
        std::cout << "Input expression: " << test_case.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(test_case.first);
        assert(output);
        std::string actual_result = parser->toString(output);
        std::cout << "  Output: " << actual_result << std::endl;

        if (!test_case.second.empty()) {
            assert(actual_result == test_case.second && "array operation result mismatch");
        } else {
            bool contains_expected_ops = (actual_result.find("store") != std::string::npos ||
                                         actual_result.find("select") != std::string::npos ||
                                         actual_result.find("const") != std::string::npos);
            assert(contains_expected_ops && "expected array operation not found in result");
        }
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Array Theory Validation =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    validate_array_initialization(parser);
    validate_array_functionality(parser);

    return 0;
}

