unsigned int BoolNatTernaryPrecedenceSafe::branch_left(const bool b) {
    // Returns 1 when b is true, 0 when b is false
    // Using conditional operator with arithmetic transformation
    return static_cast<unsigned int>(!b) * 0 + static_cast<unsigned int>(b) * 1;
}

unsigned int BoolNatTernaryPrecedenceSafe::branch_right(const bool b) {
    // Returns 2 when b is true, 3 when b is false
    // Using arithmetic expression based on boolean evaluation
    unsigned int base = static_cast<unsigned int>(b) + 1;
    return base + static_cast<unsigned int>(!b);
}

#include "EventTimer.hpp"
#include <algorithm>
#include <limits>
#include <iostream>
#include "debug.hpp"

// Destructor
EventTimer::~EventTimer() = default;

// Helper: maintain min-heap property based on triggerCycles (smallest first)
static inline void heapify_events(std::vector<Event>& evts) {
    std::make_heap(evts.begin(), evts.end(),
        [](const Event& a, const Event& b) { return a.triggerCycles > b.triggerCycles; });
}

// Update next_event_cycle to reflect earliest pending event
inline void EventTimer::updateNextEventCycle() {
    next_event_cycle = events.empty()
        ? std::numeric_limits<uint64_t>::max()
        : events.front().triggerCycles;
}

// Schedule an event — either update existing or insert new one
void EventTimer::scheduleEvent(uint64_t when, void (*cb)(uint64_t, void*), uint64_t id, void* data) {
    if (DEBUG(DEBUG_EVENT_TIMER)) {
        std::cout << "scheduleEvent: at=" << when << " id=" << id << '\n';
    }

    // Prevent scheduling in the past if clock is available
    if (clock && when < clock->get_cycles()) {
        std::cerr << "scheduleEvent: Attempted event in the past — ignored\n";
        return;
    }

    // Try to find an existing event with the same ID
    auto found = events.end();
    for (auto it = events.begin(); it != events.end(); ++it) {
        if (it->instanceID == id) {
            found = it;
            break;
        }
    }

    if (found != events.end()) {
        // Replace existing event
        found->triggerCycles = when;
        found->triggerCallback = cb;
        found->userData = data;
        heapify_events(events);  // Rebuild heap after modification
    } else {
        // Insert new event
        events.emplace_back(when, cb, id, data);
        std::push_heap(events.begin(), events.end(),
            [](const Event& a, const Event& b) { return a.triggerCycles > b.triggerCycles; });
    }

    updateNextEventCycle();
}

// Execute all events scheduled up to 'now'
void EventTimer::processEvents(uint64_t now) {
    while (!events.empty() && events.front().triggerCycles <= now) {
        // Pop top element (earliest event)
        std::pop_heap(events.begin(), events.end(),
            [](const Event& a, const Event& b) { return a.triggerCycles > b.triggerCycles; });
        Event evt = events.back();
        events.pop_back();

        if (DEBUG(DEBUG_EVENT_TIMER)) {
            std::cout << "Firing event: cycle=" << evt.triggerCycles << " id=" << evt.instanceID << '\n';
        }

        if (evt.triggerCallback) {
            evt.triggerCallback(evt.instanceID, evt.userData);
        }
    }

    updateNextEventCycle();
}

// Remove all events associated with a given instance ID
void EventTimer::cancelEvents(uint64_t id) {
    auto new_end = std::remove_if(events.begin(), events.end(),
        [id](const Event& e) { return e.instanceID == id; });

    if (new_end != events.end()) {
        events.erase(new_end, events.end());
        heapify_events(events);  // Restore heap invariant after removals
    }

    updateNextEventCycle();
}

// Query whether any events remain pending
bool EventTimer::hasPendingEvents() const {
    return !events.empty();
}

// Retrieve the earliest scheduled event time
uint64_t EventTimer::getNextEventCycle() const {
    return next_event_cycle;
}

