// Custom job implementation for deterministic simulation execution
class SimulationJob : public rslcpp::Job
{
public:
  // Override to provide exit status upon job termination
  std::uint8_t get_exit_code() override { return termination_code_; }

  // Indicate whether the simulation has completed
  bool get_finished() override { return is_complete_; }

  // Specify the starting time for the simulation (ROS time)
  rclcpp::Time get_initial_time() override { return rclcpp::Time(10, 0, RCL_ROS_TIME); }

  // Construct and configure nodes required for the simulation
  std::vector<rclcpp::Node::SharedPtr> create_and_get_nodes() override
  {
    rclcpp::NodeOptions node_config;
    node_config.use_intra_process_comms(true);

    // Instantiate communication components
    auto sender = std::make_shared<CommunicationDelaySender>(node_config);
    auto receiver = std::make_shared<ReceiverNode>(node_config);

    // Set up monitoring with timeout handling
    auto monitor = std::make_shared<rslcpp::helper_nodes::SimulationMonitor>(
      [this](rslcpp::exit_code_t code) {
        is_complete_ = true;
        termination_code_ = code;
      },
      node_config);

    monitor->set_parameter(rclcpp::Parameter("timeout_s", 100));

    return {sender, receiver, monitor};
  }

private:
  bool is_complete_ = false;
  rslcpp::exit_code_t termination_code_ = 0;
};

// Entry point for running the simulation
int main(int argc, char ** argv)
{
  auto job_instance = std::make_shared<SimulationJob>();
  auto result = rslcpp::run_job(argc, argv, job_instance);

  std::cout << "Simulation completed with exit code: " 
            << static_cast<int>(result) << std::endl;

  return 0;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSubArray(std::vector<int>& nums) {
        int n = nums.size();
        int maxSum = nums[0];
        int currentMax = nums[0];

        for (int i = 1; i < n; ++i) {
            // Either extend the existing subarray or start new from current element
            currentMax = std::max(nums[i], currentMax + nums[i]);
            maxSum = std::max(maxSum, currentMax);
        }

        return maxSum;
    }
};

