// Timer used to enforce async execution time limits
static Core::Timer asyncExecutionTimeout(CTRPF::Milliseconds(5000));

// Resets the async timeout timer
void Core::AsyncRestartClock() {
    asyncExecutionTimeout.Reset();
}

// Hook function called periodically during coroutine execution
void Core::_AsyncTimeLimitHook(lua_State *L, lua_Debug *ar) {
    if (asyncExecutionTimeout.HasExpired())
        luaL_error(L, "Async coroutine exceeded execution time (5000 ms)");
}

// ============================================================================
// Async Module Implementation
// ============================================================================

/*
- Creates a reusable asynchronous task from a Lua function.
  The function is stored for later invocation.
## func: function
## return: AsyncTask
### Async.create
*/
static int l_Async_Create(lua_State *L) {
    luaL_argcheck(L, lua_isfunction(L, 1), 1, "expected function");

    lua_newtable(L);
    lua_pushvalue(L, 1); // duplicate function reference
    lua_setfield(L, -2, "_funcRef");

    luaC_setmetatable(L, "AsyncTask");
    return 1;
}

/*
- Schedules a Lua function as an async task in the game loop.
  Runs until completion or timeout.
## func: function
### Async.run
*/
static int l_Async_Run(lua_State *L) {
    luaL_argcheck(L, lua_isfunction(L, 1), 1, "expected function");

    lua_State *coro = lua_newthread(L);
    lua_pushvalue(L, 1);
    lua_xmove(L, coro, 1);

    // Set up timeout hook: triggers every 100 bytecode instructions
    lua_sethook(coro, Core::_AsyncTimeLimitHook, LUA_MASKCOUNT, 100);

    Scheduler::getInstance().EnqueueTask(L, -1);
    lua_pop(L, 1); // remove coroutine from stack

    return 0;
}

/*
- Suspends current async task for specified duration (or indefinitely if omitted).
## seconds: number? (default: 0)
## return: boolean (always true on resume)
### Async.wait
*/
static int l_Async_Wait(lua_State *L) {
    if (!Scheduler::getInstance().IsCurrentTaskValid(L)) {
        return luaL_error(L, "must be called from within an async task");
    }

    const int argCount = lua_gettop(L);
    if (argCount > 0) {
        if (!lua_isnumber(L, 1))
            return luaL_error(L, "bad #1 argument type (expected number)");

        double duration = lua_tonumber(L, 1);
        if (duration < 0.0)
            return luaL_error(L, "invalid wait duration (negative value)");

        return Scheduler::getInstance().ScheduleWait(
            L,
            UniqueAlloc::make_unique<AsyncWaitHandler>(static_cast<float>(duration))
        );
    } else {
        // Wait once (zero duration)
        return Scheduler::getInstance().ScheduleWait(
            L,
            UniqueAlloc::make_unique<AsyncWaitHandler>(0.0f)
        );
    }
}

// ============================================================================
// Metatable registration for AsyncTask
// ============================================================================
static void RegisterAsyncTaskMetatable(lua_State *L) {
    luaL_newmetatable(L, "AsyncTask");

    // __index table
    lua_newtable(L);
    lua_setfield(L, -2, "__index");

    // __newindex handler
    lua_pushcfunction(L, luaC_invalid_newindex);
    lua_setfield(L, -2, "__newindex");

    // __name field
    lua_pushstring(L, "AsyncTask");
    lua_setfield(L, -2, "__name");

    lua_pop(L, 1); // pop metatable
}

// ============================================================================
// Module Registration
// ============================================================================
bool Core::RegisterAsyncModule(lua_State *L) {
    RegisterAsyncTaskMetatable(L);

    lua_newtable(L);

    // Bind methods
    lua_pushcfunction(L, l_Async_Run);
    lua_setfield(L, -2, "run");

    lua_pushcfunction(L, l_Async_Create);
    lua_setfield(L, -2, "create");

    lua_pushcfunction(L, l_Async_Wait);
    lua_setfield(L, -2, "wait");

    lua_setglobal(L, "Async");
    return true;
}

