#include <vector>

// Helper function to send a query and get the response
int performQuery(int slice) {
    std::cout << "? " << slice << std::endl;
    int result;
    std::cin >> result;
    if (result == -1) {
        exit(0); // Handle judge error by terminating
    }
    return result;
}

// Function to output a matched pair
void reportMatch(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Track which slices have been paired
    std::vector<bool> isPaired(2 * n + 1, false);

    // Store indices of currently unmatched slices
    std::vector<int> currentUnmatched;

    // Keep track of the current number of distinct kinds
    int distinctCount = 0;

    for (int idx = 1; idx <= 2 * n; ++idx) {
        if (isPaired[idx]) {
            continue;
        }

        // Query the effect of adding this slice
        int newDistinct = performQuery(idx);

        if (newDistinct > distinctCount) {
            // This slice introduces a new kind — it's a "starter"
            currentUnmatched.push_back(idx);
            distinctCount = newDistinct;
        } else {
            // This slice completes a pair with some existing unmatched slice

            // We'll search backwards through unmatched candidates
            for (int pos = currentUnmatched.size() - 1; pos >= 0; --pos) {
                int candidate = currentUnmatched[pos];

                // Temporarily check if candidate pairs with idx
                int testResult = performQuery(candidate);

                if (testResult == newDistinct) {
                    // Found matching pair: idx and candidate
                    reportMatch(idx, candidate);

                    // Mark both as paired
                    isPaired[idx] = true;
                    isPaired[candidate] = true;

                    // Remove candidate from unmatched list
                    currentUnmatched.erase(currentUnmatched.begin() + pos);

                    // Restore distinct count to pre-query level
                    distinctCount = testResult;
                    break;
                } else {
                    // Not a match — restore state by querying again
                    performQuery(candidate);
                }
            }
        }
    }

    return 0;
}

