// Generate list of prime numbers up to 10000
vector<int> generatePrimes() {
    vector<int> primes;
    const int limit = 10000;

    for (int candidate = 2; candidate < limit; ++candidate) {
        bool isPrime = true;
        int sqrtCandidate = static_cast<int>(sqrt(candidate));

        for (int divisor = 2; divisor <= sqrtCandidate; ++divisor) {
            if (candidate % divisor == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            primes.push_back(candidate);
        }
    }

    return primes;
}

// Process the waiter problem with modified logic
vector<int> processWaiter(vector<int> inputStack, int iterations) {
    vector<int> finalOutput;
    vector<int> stackA, stackB;
    vector<int> primes = generatePrimes();

    // Process each prime number for the specified number of iterations
    for (int i = 0; i < iterations && i < primes.size(); ++i) {
        int currentSize = inputStack.size();

        // Distribute elements between stacks based on divisibility
        for (int k = 0; k < currentSize; ++k) {
            int value = inputStack.back();
            inputStack.pop_back();

            if (value % primes[i] == 0) {
                stackB.push_back(value);
            } else {
                stackA.push_back(value);
            }
        }

        // Add divisible numbers (stackB) to output in correct order
        while (!stackB.empty()) {
            finalOutput.push_back(stackB.back());
            stackB.pop_back();
        }

        // Prepare for next iteration: stackA becomes new input stack
        inputStack = stackA;
        stackA.clear();
    }

    // Append remaining numbers to output
    while (!inputStack.empty()) {
        finalOutput.push_back(inputStack.back());
        inputStack.pop_back();
    }

    return finalOutput;
}

int main() {
    // Test case setup
    vector<int> testNumbers = {3, 4, 7, 6, 5};
    int numIterations = 4;

    // Execute processing
    vector<int> outputSequence = processWaiter(testNumbers, numIterations);

    // Display results
    for (int val : outputSequence) {
        cout << val << " ";
    }
    cout << endl;

    return 0;
}

class Solution {
public:
    int pivotIndex(vector<int>& nums) {
        int n = nums.size();
        int rightSum = 0;
        int leftSum = 0;

        // Calculate total sum first
        for (int i = 0; i < n; ++i) {
            rightSum += nums[i];
        }

        // Iterate to find pivot index
        for (int i = 0; i < n; ++i) {
            rightSum -= nums[i];  // Subtract current element from right sum
            if (leftSum == rightSum) {
                return i;
            }
            leftSum += nums[i];   // Add current element to left sum
        }

        return -1;
    }
};

