    // Helper to append successor nodes based on CFG structure
    void appendTopLevelSuccessors(const ProgramPoint& point, EvalResult& result)
    {
        const auto* node = point.getCFGNode();
        for (const auto* next : node->getPredecessors())  // Note: logically reversed direction for top-level
            result.addTopLevelProgramPoint(ProgramPoint(point.getContext(), next));
    }

    // Helper to propagate memory-level successors with updated Store
    void appendMemLevelSuccessors(const ProgramPoint& point, const Store& currentStore, EvalResult& result)
    {
        const auto* node = point.getCFGNode();
        for (const auto* next : node->getSuccessors())
            result.addMemLevelProgramPoint(ProgramPoint(point.getContext(), next), currentStore);
    }

    // Core evaluation routine — routes execution depending on node type
    EvalResult TransferFunction::evaluate(const ProgramPoint& point)
    {
        EvalResult outcome;

        switch (point.getCFGNode()->getKind())
        {
            case CFGNodeTag::FunctionEntry:
            {
                processEntryConfiguration(point, outcome);
                break;
            }
            case CFGNodeTag::Allocation:
            {
                processAllocation(point, outcome);
                break;
            }
            case CFGNodeTag::Assignment:
            {
                processCopyOperation(point, outcome);
                break;
            }
            case CFGNodeTag::AddressCalculation:
            {
                processGEPComputation(point, outcome);
                break;
            }
            case CFGNodeTag::MemoryRead:
            {
                if (nullptr != currentState)
                    processLoad(point, outcome);
                break;
            }
            case CFGNodeTag::MemoryWrite:
            {
                if (nullptr != currentState)
                    processStore(point, outcome);
                break;
            }
            case CFGNodeTag::Invocation:
            {
                if (nullptr != currentState)
                    processCall(point, outcome);
                break;
            }
            case CFGNodeTag::Termination:
            {
                if (nullptr != currentState)
                    processReturn(point, outcome);
                break;
            }
        }

        return outcome;
    }

    // Overloaded entry points for backward compatibility
    void TransferFunction::eval(const ProgramPoint& pp, EvalResult& res)
    {
        res = evaluate(pp);
    }

} // namespace tpa

