#include <vector>
#include <algorithm>
using namespace std;

class PermutationHelper {
public:
    void generateNextPermutation(vector<int>& sequence) {
        int size = sequence.size();
        int pivotIndex = -1;

        // Step 1: Locate the rightmost position where an element is smaller than its successor
        for (int idx = size - 2; idx >= 0; --idx) {
            if (sequence[idx] < sequence[idx + 1]) {
                pivotIndex = idx;
                break;
            }
        }

        if (pivotIndex == -1) {
            // No valid pivot found — sequence is in descending order; reverse to get smallest permutation
            reverse(sequence.begin(), sequence.end());
        } else {
            // Step 2: Find the rightmost element larger than the pivot
            for (int jdx = size - 1; jdx > pivotIndex; --jdx) {
                if (sequence[jdx] > sequence[pivotIndex]) {
                    swap(sequence[jdx], sequence[pivotIndex]);
                    break;
                }
            }

            // Step 3: Sort the suffix in ascending order (equivalent to reversing since it's in descending order)
            reverse(sequence.begin() + pivotIndex + 1, sequence.end());
        }
    }
};

int main() {
    PermutationHelper helper;
    vector<int> data = {2, 3, 7, 6, 5, 1};
    helper.generateNextPermutation(data);

    for (int k = 0; k < data.size(); ++k) {
        cout << data[k] << " ";
    }
    return 0;
}

