MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    this->initializeVisualizationWidget();
    // Initialize the first visual model: HexGrid-based surface
    this->configureHexGridRendering();

    // Set up periodic update timer using a lambda for dynamic data refresh
    QTimer* updater = new QTimer(this);
    connect(updater, &QTimer::timeout, [this]() {
        unsigned int idx = 0;
        while (idx < this->hexGrid->num()) {
            float xCoord = hexGrid->d_x[idx];
            float yCoord = hexGrid->d_y[idx];
            radialDist[idx] = std::sqrt(xCoord * xCoord + yCoord * yCoord);
            // Compute Bessel-like oscillatory pattern
            float argument = kParam * radialDist[idx];
            if (argument != 0.0f) {
                surfaceData[idx] = std::sin(argument) / argument;
            } else {
                surfaceData[idx] = 1.0f; // limit as r -> 0
            }
            ++idx;
        }

        kParam += 0.02f;
        if (kParam > 8.0f) {
            kParam = 1.0f;
        }

        // Signal that the first visual model needs reinitialization
        auto* vwPtr = static_cast<mplot::qt::viswidget<0>*>(pVisWidget);
        vwPtr->set_model_needs_reinit(0);

        // Trigger redraw
        pVisWidget->update();
    });

    updater->start();
}

MainWindow::~MainWindow() { delete ui; }

void MainWindow::configureHexGridRendering()
{
    // Construct hexagonal grid with specified spacing and radius
    hexGrid = std::make_unique<sm::hexgrid>(0.02f, 15.0f, 0.0f);
    hexGrid->setCircularBoundary(4.0f);

    // Prepare storage for computed scalar field
    surfaceData.assign(hexGrid->num(), 0.0f);
    radialDist.assign(hexGrid->num(), 0.0f);
    kParam = 1.0f;

    // Precompute initial data
    unsigned int hi = 0;
    while (hi < hexGrid->num()) {
        float x = hexGrid->d_x[hi];
        float y = hexGrid->d_y[hi];
        radialDist[hi] = std::sqrt(x * x + y * y);
        float arg = kParam * radialDist[hi];
        surfaceData[hi] = (arg == 0.0f) ? 1.0f : std::sin(arg) / arg;
        ++hi;
    }

    // Define offset for rendering position
    sm::vec<float, 3> renderOffset = { 0.0f, -0.05f, 0.0f };
    auto hgv = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hexGrid.get(), renderOffset);

    // Bind model to shader context before finalizing
    auto* vw = static_cast<mplot::qt::viswidget<0>*>(pVisWidget);
    vw->v.bindmodel(hgv);

    // Attach scalar data to visualizer
    hgv->setScalarData(&surfaceData);

    // Transfer ownership to main list of visuals
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> baseModel = std::move(hgv);
    vw->newvisualmodels.push_back(std::move(baseModel));
}

void MainWindow::initializeVisualizationWidget()
{
    // Instantiate OpenGL visualization widget
    mplot::qt::viswidget<0>* vw = new mplot::qt::viswidget<0>(this->parentWidget());

    // Enable lighting effects for better visual appearance
    vw->v.lightingEffects();

    // Embed into main window layout
    ui->verticalLayout->addWidget(vw);
    pVisWidget = vw;
}

void MainWindow::on_actionQuit_triggered() { close(); }

