#include <iostream>
#include <cmath>

// Recursive function to solve the Tower of Hanoi problem
// Moves n disks from source peg to target peg using auxiliary peg
void hanoi(int disks, int source, int target, int auxiliary) {
    if (disks <= 0) {
        return;
    }

    // Move top (disks-1) disks from source to auxiliary peg
    hanoi(disks - 1, source, auxiliary, target);

    // Move the largest disk from source to target
    std::cout << source << " " << target << "\n";

    // Move (disks-1) disks from auxiliary to target peg
    hanoi(disks - 1, auxiliary, target, source);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int diskCount;
    std::cin >> diskCount;

    // Calculate total moves: 2^n - 1
    long long totalMoves = (1LL << diskCount) - 1;
    std::cout << totalMoves << "\n";

    // Execute the solution: move all disks from peg 1 to peg 3 using peg 2 as auxiliary
    hanoi(diskCount, 1, 3, 2);

    return 0;
}

#include <format>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sstream>

int main()
{
    // Initialize the rendering window with title and dimensions
    mplot::Visual scene(1024, 768, "Made with mplot::GraphVisual");

    // Instantiate a GraphVisual for double-precision data at origin
    auto graphView = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Link the graph to the visual context (required initialization)
    scene.bindmodel(graphView);

    // Prepare x-axis data: values from 0 to 10 in steps of 1
    sm::vvec<double> xData;
    xData.linspace(0.0, 10.0, 11);

    // Define y-axis data manually (as original 'x' was used for y-axis in input)
    sm::vvec<double> yData = {5.0, 8.0, 2.0, 9.0, 1.0, 2.0, 4.0, 5.0, 8.0, 3.0, 1.0};

    // Configure line plot style
    mplot::DatasetStyle lineStyle(mplot::stylepolicy::lines);
    lineStyle.linecolour = mplot::colour::crimson;

    // Enforce y-axis range [0, 10]
    graphView->setlimits_y(0.0, 10.0);

    // Feed data into the graph
    graphView->setdata(yData, xData, lineStyle);  // Note: swapped order to match original semantics

    // Style for vertical crossing lines
    mplot::DatasetStyle vertLineStyle(mplot::stylepolicy::lines);
    vertLineStyle.linecolour = mplot::colour::grey68;
    vertLineStyle.linewidth = lineStyle.linewidth * 0.6f;

    // Compute intersections with vertical line x = 3.3
    sm::vvec<double> crossingYs = graphView->add_x_crossing_lines(yData, xData, 3.3, lineStyle, vertLineStyle);

    // Format crossing points into readable string
    std::ostringstream oss;
    if (!crossingYs.empty()) {
        size_t count = crossingYs.size();
        for (size_t idx = 0; idx < count; ++idx) {
            if (idx == 0 || idx == count - 1) {
                oss << "";
            } else {
                oss << ", ";
            }
            if (idx == count - 1) {
                oss << " and ";
            }
            oss << std::format("{:.2f}", crossingYs[idx]);
        }
    } else {
        oss << "[no values]";
    }

    // Add annotation label at bottom-left corner
    graphView->addLabel(
        std::format("At x=3.3, y = {}", oss.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures{0.03f}
    );

    // Finalize internal geometry computation
    graphView->finalize();

    // Transfer ownership of graph model to scene
    scene.addVisualModel(std::move(graphView));

    // Launch interactive viewer loop
    scene.keepOpen();

    // Memory cleanup handled automatically via RAII (unique_ptr in Visual)
    return 0;
}

#include "ValueProfileCollector.h"
#include "ValueProfilePlugins.inc"
#include "llvm/ProfileData/InstrProf.h"

using namespace llvm;

namespace {

// Helper template to chain multiple plugins together
template <typename...> class PluginSequence;

// Final instantiation of the plugin sequence used by ValueProfileCollectorImpl
using PluginSequenceFinal = PluginSequence<VP_PLUGIN_LIST>;

// Base case: empty plugin sequence does nothing
template <> class PluginSequence<> {
public:
  PluginSequence(Function &, TargetLibraryInfo &) {}
  void collect(InstrProfValueKind, std::vector<CandidateInfo> &) {}
};

// Recursive case: process first plugin, then delegate to rest
template <typename FirstPlugin, typename... Rest>
class PluginSequence<FirstPlugin, Rest...> : private PluginSequence<Rest...> {
  FirstPlugin instance;
  using Parent = PluginSequence<Rest...>;

public:
  PluginSequence(Function &func, TargetLibraryInfo &info)
      : Parent(func, info), instance(func, info) {}

  void collect(InstrProfValueKind kind, std::vector<CandidateInfo> &out) {
    if (kind == FirstPlugin::Category)
      instance.process(out);
    Parent::collect(kind, out);
  }
};

} // anonymous namespace

// Implementation class that inherits the plugin chaining behavior
class ValueProfileCollector::ValueProfileCollectorImpl 
    : public PluginSequenceFinal {
public:
  using PluginSequenceFinal::PluginSequenceFinal;
};

// Constructor initializes the implementation object
ValueProfileCollector::ValueProfileCollector(Function &F,
                                             TargetLibraryInfo &TLI)
    : PImpl(std::make_unique<ValueProfileCollectorImpl>(F, TLI)) {}

// Destructor is defaulted
ValueProfileCollector::~ValueProfileCollector() = default;

// Public interface to retrieve candidates for a given value kind
std::vector<CandidateInfo>
ValueProfileCollector::get(InstrProfValueKind type) const {
  std::vector<CandidateInfo> output;
  PImpl->collect(type, output);
  return output;
}

