using namespace nanobind::literals;

void init_optimal_ik(nanobind::module_& m) {
    // Helper lambda to bind common Task attributes
    auto bind_task_base = [](nanobind::class_<Task>& cls) {
        cls.def_ro("gain", &Task::gain)
           .def_ro("weight", &Task::weight)
           .def_ro("lm_damping", &Task::lm_damping)
           .def_ro("num_variables", &Task::num_variables);
    };

    // Bind base Task class
    nanobind::class_<Task> task_cls(m, "Task", "Abstract base class for IK tasks.");
    bind_task_base(task_cls);

    // FrameTaskOptions binding with custom constructor aliasing
    nanobind::class_<FrameTaskOptions> fto_cls(m, "FrameTaskOptions", "Parameters for FrameTask.");
    fto_cls.def(nanobind::init<double, double, double, double>(),
                "position_cost"_a = 1.0,
                "orientation_cost"_a = 1.0,
                "task_gain"_a = 1.0,
                "lm_damping"_a = 0.0);
    fto_cls.def_rw("position_cost", &FrameTaskOptions::position_cost);
    fto_cls.def_rw("orientation_cost", &FrameTaskOptions::orientation_cost);
    fto_cls.def_rw("task_gain", &FrameTaskOptions::task_gain);
    fto_cls.def_rw("lm_damping", &FrameTaskOptions::lm_damping);

    // FrameTask binding
    nanobind::class_<FrameTask, Task> ft_cls(m, "FrameTask",
                                             "Task to reach a target pose for a specified frame.");
    ft_cls.def(nanobind::init<const CartesianConfiguration&, int, const FrameTaskOptions&>(),
               "target_pose"_a, "num_variables"_a, "options"_a = FrameTaskOptions{});
    ft_cls.def_ro("frame_name", &FrameTask::frame_name);
    ft_cls.def_ro("frame_id", &FrameTask::frame_id);
    ft_cls.def_ro("target_pose", &FrameTask::target_pose);
    ft_cls.def("setTargetFrameTransform", &FrameTask::setTargetFrameTransform);

    // ConfigurationTaskOptions binding
    nanobind::class_<ConfigurationTaskOptions> cto_cls(m, "ConfigurationTaskOptions",
                                                       "Parameters for ConfigurationTask.");
    cto_cls.def(nanobind::init<double, double>(), "task_gain"_a = 1.0, "lm_damping"_a = 0.0);
    cto_cls.def_rw("task_gain", &ConfigurationTaskOptions::task_gain);
    cto_cls.def_rw("lm_damping", &ConfigurationTaskOptions::lm_damping);

    // ConfigurationTask binding
    nanobind::class_<ConfigurationTask, Task> ct_cls(m, "ConfigurationTask",
                                                     "Task to reach a target joint configuration.");
    ct_cls.def(nanobind::init<const Eigen::VectorXd&, const Eigen::VectorXd&,
                              const ConfigurationTaskOptions&>(),
               "target_q"_a, "joint_weights"_a, "options"_a = ConfigurationTaskOptions{});
    ct_cls.def_rw("target_q", &ConfigurationTask::target_q);
    ct_cls.def_rw("joint_weights", &ConfigurationTask::joint_weights);

    // Constraints base class
    nanobind::class_<Constraints> con_cls(m, "Constraints", "Abstract base class for IK constraints.");

    // PositionLimit constraint
    nanobind::class_<PositionLimit, Constraints> poslim_cls(m, "PositionLimit",
                                                            "Constraint to enforce joint position limits.");
    poslim_cls.def(nanobind::init<int, double>(), "num_variables"_a, "gain"_a = 1.0);
    poslim_cls.def_rw("config_limit_gain", &PositionLimit::config_limit_gain);

    // VelocityLimit constraint
    nanobind::class_<VelocityLimit, Constraints> velim_cls(m, "VelocityLimit",
                                                           "Constraint to enforce joint velocity limits.");
    velim_cls.def(nanobind::init<int, double, const Eigen::VectorXd&>(),
                  "num_variables"_a, "dt"_a, "v_max"_a);
    velim_cls.def_rw("dt", &VelocityLimit::dt);
    velim_cls.def_rw("v_max", &VelocityLimit::v_max);

    // Oink solver binding with wrapped solveIk method
    nanobind::class_<Oink> oink_cls(m, "Oink", "Optimal Inverse Kinematics solver.");
    oink_cls.def(nanobind::init<int>(), "num_variables"_a);

    oink_cls.def(
        "solveIk",
        [](Oink& solver,
           const std::vector<std::shared_ptr<Task>>& task_list,
           const std::vector<std::shared_ptr<Constraints>>& constraint_list,
           const std::shared_ptr<Scene>& scene_ref,
           nanobind::DRef<Eigen::VectorXd> out_delta_q,
           double reg_weight) {
            auto outcome = solver.solveIk(task_list, constraint_list, *scene_ref, out_delta_q, reg_weight);
            if (!outcome.has_value()) {
                throw std::runtime_error("IK solve failed: " + outcome.error());
            }
        },
        "tasks"_a, "constraints"_a, "scene"_a, "delta_q"_a, "regularization"_a = 1e-12,
        "Solve inverse kinematics for given tasks and constraints.\n\n"
        "Solves a QP optimization problem to compute the joint velocity that minimizes\n"
        "weighted task errors while satisfying all constraints. The result is written\n"
        "directly into the provided delta_q buffer.\n\n"
        "Args:\n"
        "    tasks: List of weighted tasks to optimize for.\n"
        "    constraints: List of constraints to satisfy.\n"
        "    scene: Scene containing robot model and state.\n"
        "    delta_q: Pre-allocated numpy array for output (size = num_variables).\n"
        "             Must be a contiguous float64 array. Modified in-place.\n"
        "    regularization: Tikhonov regularization weight for the QP Hessian.\n"
        "                    Higher values improve numerical stability but may reduce\n"
        "                    task tracking accuracy. Default: 1e-12.\n\n"
        "Raises:\n"
        "    RuntimeError: If the QP solver fails to find a solution.\n\n"
        "Example:\n"
        "    delta_q = np.zeros(oink.num_variables)\n"
        "    oink.solveIk(tasks, constraints, scene, delta_q)");
}

