#include <type_traits>

// Simulate magic_enum-like enum handling via manual dispatch
enum class Color { RED, BLUE, GREEN };

// Custom switch implementation for Color
template<typename F>
auto color_switch(Color c, F&& f) {
    if constexpr (std::is_invocable_v<F, Color>) {
        return std::forward<F>(f)(c);
    } else {
        // Overload set with specific enum constants
        struct Visitor {
            F&& func;
            auto operator()(Color c) const {
                switch (c) {
                    case Color::RED:   return func(std::integral_constant<Color, Color::RED>{});
                    case Color::BLUE:  return func(std::integral_constant<Color, Color::BLUE>{});
                    case Color::GREEN: return func(std::integral_constant<Color, Color::GREEN>{});
                    default:           return func(c); // fallback
                }
            }
        };
        return Visitor{std::forward<F>(f)}(c);
    }
}

// Template function with specializations
template<Color C>
constexpr std::string_view DoWork() {
    return "default";
}

template<>
constexpr std::string_view DoWork<Color::GREEN>() {
    return "override";
}

// Helper type for overloaded lambdas (C++17)
template<typename... Ts>
struct overloaded : Ts... {
    using Ts::operator()...;
};

template<typename... Ts>
overloaded(Ts...) -> overloaded<Ts...>;

int main() {
    // First part: simulate magic_enum::enum_switch(lambda, c)
    Color c = Color::RED;
    auto lambda = [](auto value) {
        std::cout << DoWork<value>() << std::endl;
    };
    color_switch(c, [&](auto val) {
        using T = std::decay_t<decltype(val)>;
        if constexpr (std::is_same_v<T, Color>) {
            // fallback path: not used here due to integral_constant dispatch
        } else {
            lambda(val);
        }
    });

    c = Color::GREEN;
    color_switch(c, [&](auto val) {
        using T = std::decay_t<decltype(val)>;
        if constexpr (!std::is_same_v<T, Color>) {
            lambda(val);
        }
    });

    // Second part: explicit enum_constant-based switcher
    auto switcher1 = overloaded{
        [](std::integral_constant<Color, Color::BLUE>) {
            std::cout << "Blue" << std::endl;
        },
        [](std::integral_constant<Color, Color::RED>) {
            std::cout << "Red" << std::endl;
        }
    };

    color_switch(Color::GREEN, [&](auto val) {
        using T = std::decay_t<decltype(val)>;
        if constexpr (!std::is_same_v<T, Color>) {
            switcher1(val);
        }
    });
    color_switch(Color::BLUE, [&](auto val) {
        using T = std::decay_t<decltype(val)>;
        if constexpr (!std::is_same_v<T, Color>) {
            switcher1(val);
        }
    });
    color_switch(Color::RED, [&](auto val) {
        using T = std::decay_t<decltype(val)>;
        if constexpr (!std::is_same_v<T, Color>) {
            switcher1(val);
        }
    });

    // Third part: result with explicit type and default fallback
    auto switcher2 = overloaded{
        [](std::integral_constant<Color, Color::GREEN>) -> std::string {
            return "called with green argument";
        },
        [](Color other) -> std::string {
            // Use manual name lookup
            switch (other) {
                case Color::RED:   return "default: RED";
                case Color::BLUE:  return "default: BLUE";
                case Color::GREEN: return "default: GREEN"; // should not happen here
                default:           return "default: UNKNOWN";
            }
        }
    };

    auto apply_switcher2 = [&](Color col, std::string fallback = "") -> std::string {
        if (col == Color::GREEN) {
            return switcher2(std::integral_constant<Color, Color::GREEN>{});
        } else if (col == Color::RED || col == Color::BLUE) {
            return switcher2(col);
        } else {
            return fallback.empty() ? "" : fallback;
        }
    };

    std::cout << apply_switcher2(Color::GREEN) << std::endl;
    std::cout << apply_switcher2(Color::RED) << std::endl;

    std::string empty_result = apply_switcher2(static_cast<Color>(-3));
    static_assert(std::is_same_v<decltype(empty_result), std::string>);
    // assert(empty_result.empty()); // omitted in output for safety

    std::cout << apply_switcher2(static_cast<Color>(-3), "unrecognized") << std::endl;

    // Fourth part: optional-returning switcher
    auto switcher3 = overloaded{
        [](std::integral_constant<Color, Color::RED>) -> std::optional<std::string> {
            return "red result";
        },
        [](std::integral_constant<Color, Color::BLUE>) -> std::optional<std::string> {
            return std::nullopt;
        }
    };

    auto apply_switcher3 = [&](Color col, std::optional<std::string> def) -> std::optional<std::string> {
        if (col == Color::RED) {
            return switcher3(std::integral_constant<Color, Color::RED>{});
        } else if (col == Color::BLUE) {
            return switcher3(std::integral_constant<Color, Color::BLUE>{});
        } else {
            return def;
        }
    };

    std::cout << std::boolalpha;
    std::cout << apply_switcher3(Color::GREEN, std::make_optional("cica")).value() << std::endl;
    std::cout << apply_switcher3(Color::RED, std::make_optional("cica")).value() << std::endl;
    std::cout << apply_switcher3(Color::BLUE, std::make_optional("cica")).has_value() << std::endl;

    return 0;
}

