LinuxTray::LinuxTray()
    : should_exit_(false)
{
    // No initialization required in headless mode
}

LinuxTray::~LinuxTray() {
    // No cleanup needed in headless mode
}

bool LinuxTray::initialize(const std::string& app_name, const std::string& icon_path) {
    app_name_ = app_name;
    icon_path_ = icon_path;

    LOG(DEBUG, "LinuxTray") << "Operating in headless mode - system tray unavailable on Linux" << std::endl;
    LOG(DEBUG, "LinuxTray") << "Recommend using --no-tray command-line option for optimal operation" << std::endl;

    // Notify caller that initialization completed (but tray is not functional)
    if (ready_callback_) {
        ready_callback_();
    }

    // Explicitly signal that the tray service is not operational
    return false;
}

void LinuxTray::run() {
    LOG(DEBUG, "LinuxTray") << "Headless execution - no event loop active" << std::endl;
    // Intentionally empty: no message loop in headless mode
}

void LinuxTray::stop() {
    LOG(DEBUG, "LinuxTray") << "Initiating shutdown in headless mode" << std::endl;
    should_exit_ = true;
}

void LinuxTray::set_menu(const Menu& menu) {
    LOG(DEBUG, "LinuxTray") << "Headless mode - discarding menu with "
    << menu.items.size() << " entries" << std::endl;
    // Silently ignore menu configuration
}

void LinuxTray::update_menu() {
    LOG(DEBUG, "LinuxTray") << "Headless mode - skipping menu update" << std::endl;
    // No action taken in headless environment
}

void LinuxTray::show_notification(
    const std::string& title,
    const std::string& message,
    NotificationType type)
{
    // Redirect notification to standard output instead of GUI
    LOG(INFO, "Notification") << "[" << title << "] " << message << std::endl;
}

