    icon_path_ = icon_path;
    LOG(DEBUG, "LinuxTray") << "Headless mode - icon ignored: " << icon_path << std::endl;
    // Icon changes have no effect in headless mode
}

void LinuxTray::set_tooltip(const std::string& tooltip) {
    LOG(DEBUG, "LinuxTray") << "Headless mode - tooltip ignored: " << tooltip << std::endl;
    // Tooltip updates are discarded in headless mode
}

void LinuxTray::set_ready_callback(std::function<void()> callback) {
    ready_callback_ = callback;
}

