#include <iostream>
#include <string>
#include <asio.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: sync_client <hostname> <resource_path>\n";
            std::cerr << "Example:\n";
            std::cerr << "  sync_client www.boost.org /LICENSE_1_0.txt\n";
            return 1;
        }

        asio::io_context io_ctx;

        // Resolve the hostname and service
        tcp::resolver resolver(io_ctx);
        auto endpoints = resolver.resolve(argv[1], "http");

        // Establish connection
        tcp::socket sock(io_ctx);
        asio::connect(sock, endpoints);

        // Build HTTP GET request
        asio::streambuf req_buf;
        std::ostream req_stream(&req_buf);
        req_stream << "GET " << argv[2] << " HTTP/1.0\r\n"
                   << "Host: " << argv[1] << "\r\n"
                   << "Accept: */*\r\n"
                   << "Connection: close\r\n\r\n";

        // Send the complete request
        asio::write(sock, req_buf);

        // Read status line
        asio::streambuf resp_buf;
        asio::read_until(sock, resp_buf, "\r\n");

        std::istream resp_stream(&resp_buf);
        std::string version;
        unsigned int code;
        std::getline(resp_stream, version); // consume rest of line after version

        // Parse status line properly
        resp_stream.clear();
        resp_stream.str(""); // reset stream state
        resp_stream << &resp_buf;
        resp_stream >> version >> code;
        std::getline(resp_stream, version); // get status message

        // Validate response
        if (version.substr(0, 5) != "HTTP/" || code != 200) {
            std::cerr << "Error: Invalid or non-OK HTTP response (code " << code << ")\n";
            return 1;
        }

        // Read headers until blank line
        asio::read_until(sock, resp_buf, "\r\n\r\n");

        // Output headers
        std::string header_line;
        while (std::getline(resp_stream, header_line) && header_line != "\r") {
            if (!header_line.empty() && header_line.back() == '\r')
                header_line.pop_back();
            std::cout << header_line << "\n";
        }
        std::cout << "\n";

        // Output remaining body content
        if (resp_buf.size() > 0)
            std::cout << &resp_buf;

        // Continue reading until EOF
        asio::error_code ec;
        while (asio::read(sock, resp_buf, asio::transfer_at_least(1), ec)) {
            std::cout << &resp_buf;
        }

        if (ec != asio::error::eof) {
            throw asio::system_error(ec);
        }
    }
    catch (const std::exception& ex) {
        std::cerr << "Exception: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxArea(std::vector<int>& height) {
        int n = height.size();
        int left = 0;
        int right = n - 1;
        int maximumArea = 0;

        while (left < right) {
            int currentWidth = right - left;
            int currentHeight = std::min(height[left], height[right]);
            int currentArea = currentWidth * currentHeight;

            if (currentArea > maximumArea) {
                maximumArea = currentArea;
            }

            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maximumArea;
    }
};

