#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>
#include <iomanip>

// Use a fixed seed for reproducibility of the random process
std::mt19937_64 rng(42);

void run_simulation() {
    int participants, rounds;
    std::cin >> participants >> rounds;

    // Initialize weights and error counts for each participant
    std::vector<long double> expert_weights(participants, 1.0L);
    std::vector<int> error_counts(participants, 0);

    for (int round = 0; round < rounds; ++round) {
        std::string predictions;
        std::cin >> predictions;

        int current_prediction;

        // Determine minimum number of errors among all participants
        int least_errors = *std::min_element(error_counts.begin(), error_counts.end());

        if (least_errors == 0) {
            // Follow the first expert with zero errors so far
            int idx = 0;
            while (idx < participants && error_counts[idx] != 0) {
                ++idx;
            }
            current_prediction = (predictions[idx] == '1') ? 1 : 0;
        } else {
            // Compute weighted votes for outcomes 0 and 1
            long double vote_for_zero = 0.0L;
            long double vote_for_one = 0.0L;

            for (int i = 0; i < participants; ++i) {
                if (predictions[i] == '0') {
                    vote_for_zero += expert_weights[i];
                } else {
                    vote_for_one += expert_weights[i];
                }
            }

            long double combined_weight = vote_for_zero + vote_for_one;

            if (combined_weight == 0.0L) {
                current_prediction = 0; // fallback prediction
            } else {
                long double chance_of_one = vote_for_one / combined_weight;
                std::uniform_real_distribution<long double> uniform_dist(0.0L, 1.0L);
                current_prediction = (uniform_dist(rng) < chance_of_one) ? 1 : 0;
            }
        }

        std::cout << current_prediction << std::endl;

        int actual_result;
        std::cin >> actual_result;

        // Update weights and error counts based on actual outcome
        for (int i = 0; i < participants; ++i) {
            int expert_guess = predictions[i] - '0';
            if (expert_guess != actual_result) {
                error_counts[i]++;
                expert_weights[i] *= 0.5L; // Reduce weight by half for incorrect experts
            }
        }
    }
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    run_simulation();

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent a swap operation between two positions
struct Operation {
    int from_row, from_col;
    int to_row, to_col;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int ROWS = 30;
    vector<vector<int>> pyramid(ROWS);

    // Read input pyramid data
    for (int row = 0; row < ROWS; ++row) {
        pyramid[row].reserve(row + 1);
        for (int col = 0; col <= row; ++col) {
            int value;
            cin >> value;
            pyramid[row].push_back(value);
        }
    }

    vector<Operation> operations;
    // Pre-allocate space for operations (safe upper bound)
    operations.reserve(10000);

    // Build min-heap property from bottom to top
    // Start from second-to-last row and move upward
    for (int r = ROWS - 2; r >= 0; --r) {
        for (int c = 0; c <= r; ++c) {
            int current_r = r;
            int current_c = c;

            // Sift down the element at (current_r, current_c)
            while (current_r < ROWS - 1) {
                int child_r = current_r + 1;
                int left_c = current_c;
                int right_c = current_c + 1;

                int parent_val = pyramid[current_r][current_c];
                int left_child_val = pyramid[child_r][left_c];
                int right_child_val = pyramid[child_r][right_c];

                // Check if heap property holds: parent <= both children
                if (parent_val <= left_child_val && parent_val <= right_child_val) {
                    break;
                }

                // Determine which child is smaller for swapping
                if (left_child_val <= right_child_val) {
                    // Swap with left child
                    operations.push_back({current_r, current_c, child_r, left_c});
                    swap(pyramid[current_r][current_c], pyramid[child_r][left_c]);

                    // Move down to left child position
                    current_r = child_r;
                    current_c = left_c;
                } else {
                    // Swap with right child
                    operations.push_back({current_r, current_c, child_r, right_c});
                    swap(pyramid[current_r][current_c], pyramid[child_r][right_c]);

                    // Move down to right child position
                    current_r = child_r;
                    current_c = right_c;
                }
            }
        }
    }

    // Output number of operations followed by each operation
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.from_row << " " << op.from_col << " "
             << op.to_row << " " << op.to_col << "\n";
    }

    return 0;
}

