namespace YimMenu
{
    void FiberPool::InitializeImpl(int fiber_count)
    {
        for (std::size_t index = 0; index < static_cast<std::size_t>(fiber_count); ++index)
        {
            ScriptMgr::AddScript(std::make_unique<Script>(&ScriptEntry));
        }
    }

    void FiberPool::CleanupImpl()
    {
        std::lock_guard<std::mutex> guard(m_Mutex);
        while (!m_Jobs.empty())
            m_Jobs.pop();
    }

    void FiberPool::EnqueueImpl(std::function<void()> task)
    {
        std::lock_guard<std::mutex> guard(m_Mutex);
        m_Jobs.push(std::move(task));
    }

    void FiberPool::Process()
    {
        std::unique_lock<std::mutex> guard(m_Mutex);
        if (!m_Jobs.empty())
        {
            auto work_item = std::move(m_Jobs.top());
            m_Jobs.pop();
            guard.unlock();
            std::invoke(std::move(work_item));
        }
    }

    void FiberPool::WorkerLoop()
    {
        while (g_Running)
        {
            FiberPool::GetInstance().Process();
            ScriptMgr::Yield();
        }
    }
}

#include <asio/dispatch.hpp>
#include <asio/execution_context.hpp>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <vector>

using asio::dispatch;
using asio::execution_context;

class priority_scheduler : public execution_context
{
public:
  class executor_type
  {
  public:
    executor_type(priority_scheduler& ctx, int pri) noexcept
      : context_(ctx), priority_level_(pri)
    {
    }

    priority_scheduler& context() const noexcept
    {
      return context_;
    }

    void on_work_started() const noexcept {}
    void on_work_finished() const noexcept {}

    template <class Func, class Alloc>
    void dispatch(Func&& f, const Alloc& a) const
    {
      submit(std::forward<Func>(f), a);
    }

    template <class Func, class Alloc>
    void post(Func f, const Alloc& a) const
    {
      auto p = std::allocate_shared<task_wrapper>(
        typename std::allocator_traits<
          Alloc>::template rebind_alloc<char>(a),
        priority_level_, std::move(f));

      std::lock_guard<std::mutex> guard(context_.queue_mutex_);
      context_.task_list_.push_back(p);
      context_.task_condition_.notify_one();
    }

    template <class Func, class Alloc>
    void defer(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }

    friend bool operator==(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ == &b.context_;
    }

    friend bool operator!=(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ != &b.context_;
    }

  private:
    priority_scheduler& context_;
    int priority_level_;
  };

  executor_type get_executor(int pri = 0) noexcept
  {
    return executor_type(*const_cast<priority_scheduler*>(this), pri);
  }

  void run()
  {
    std::unique_lock<std::mutex> lock(queue_mutex_);

    while (true)
    {
      task_condition_.wait(lock, [this]{
        return shutdown_flag_ || !task_list_.empty();
      });

      if (shutdown_flag_)
        break;

      // Sort tasks by priority (highest first)
      std::sort(task_list_.begin(), task_list_.end(),
        [](const std::shared_ptr<task_base>& a,
           const std::shared_ptr<task_base>& b) {
          return a->priority_value_ < b->priority_value_;
        });

      // Get highest priority task
      auto top_task = task_list_.back();
      task_list_.pop_back();

      lock.unlock();
      top_task->run_task_(top_task);
      lock.lock();
    }
  }

  void stop()
  {
    std::lock_guard<std::mutex> guard(queue_mutex_);
    shutdown_flag_ = true;
    task_condition_.notify_all();
  }

private:
  struct task_base
  {
    int priority_value_;
    void (*run_task_)(std::shared_ptr<task_base>&);
  };

  template <class Func>
  struct task_wrapper : task_base
  {
    task_wrapper(int pri, Func fn) : stored_function_(std::move(fn))
    {
      priority_value_ = pri;
      run_task_ = [](std::shared_ptr<task_base>& t) {
        Func temp_func(std::move(static_cast<task_wrapper*>(t.get())->stored_function_));
        t.reset();
        temp_func();
      };
    }

    Func stored_function_;
  };

  struct task_comparator
  {
    bool operator()(const std::shared_ptr<task_base>& left,
                   const std::shared_ptr<task_base>& right) const
    {
      return left->priority_value_ > right->priority_value_;
    }
  };

  mutable std::mutex queue_mutex_;
  std::condition_variable task_condition_;
  std::vector<std::shared_ptr<task_base>> task_list_;
  bool shutdown_flag_ = false;
};

int main()
{
  priority_scheduler scheduler;
  auto low_priority = scheduler.get_executor(0);
  auto medium_priority = scheduler.get_executor(1);
  auto high_priority = scheduler.get_executor(2);

  dispatch(low_priority, []{ std::cout << "1\n"; });
  dispatch(low_priority, []{ std::cout << "11\n"; });
  dispatch(medium_priority, []{ std::cout << "2\n"; });
  dispatch(medium_priority, []{ std::cout << "22\n"; });
  dispatch(high_priority, []{ std::cout << "3\n"; });
  dispatch(high_priority, []{ std::cout << "33\n"; });
  dispatch(high_priority, []{ std::cout << "333\n"; });
  dispatch(scheduler.get_executor(-1), [&]{ scheduler.stop(); });

  scheduler.run();
}

