#include "stdafx.h"
#include "Buffer.h"

Buffer::Buffer(unsigned int capacity) : m_capacity(capacity), m_pos(0), m_upperBound(capacity), hasBackingArray(false)
{
}

// Resets buffer state: position becomes 0, upper bound set to capacity
// Note: Actual data isn't cleared, just the management indices
Buffer* Buffer::clear()
{
    m_pos = 0;
    m_upperBound = m_capacity;
    return this;
}

// Adjusts the upper boundary of accessible elements
// If current position exceeds new boundary, it's adjusted downward
// Mark (if present) exceeding new boundary is implicitly ignored
Buffer* Buffer::limit(unsigned int newLimit)
{
    assert(newLimit <= m_capacity);
    m_upperBound = newLimit;

    // Ensure position stays within bounds
    if (m_pos > newLimit)
        m_pos = newLimit;

    return this;
}

unsigned int Buffer::limit() const
{
    return m_upperBound;
}

// Changes the current access point within the buffer
Buffer* Buffer::position(unsigned int newPos)
{
    assert(newPos <= m_upperBound);
    m_pos = newPos;
    return this;
}

unsigned int Buffer::position() const
{
    return m_pos;
}

// Calculates how many elements remain until the boundary is reached
unsigned int Buffer::remaining() const
{
    return m_upperBound - m_pos;
}

#include "test.h"
TEST_CASE("log::Levels") {
    SECTION("String-to-enum conversion") {
        for (auto level : Lvl{}) {
            auto enumVal = EnumIndex(level);
            REQUIRE(log::mapLogLevel(_ts(enumVal)) == level);
        }
    }
    SECTION("Case-insensitive string parsing") {
        for (auto level : Lvl{}) {
            auto enumVal = EnumIndex(level);
            auto upperStr = _ts(enumVal).upperCase();
            REQUIRE(log::mapLogLevel(upperStr) == level);
        }
    }
    SECTION("Initial state verification") {
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
        log::enableLevel("dev,perf");
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
    }
    SECTION("Enable and disable single level") {
        log::enableLevel(Lvl::Work);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableLevel(Lvl::Work);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
    }
    SECTION("Sticky enable behavior") {
        log::enableLevel<true>(Lvl::Work);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableAllLevels();
        REQUIRE(log::isLevelEnabled(Lvl::Work)); // Sticky bit keeps it enabled
        log::disableLevel(Lvl::Work);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
    }
    SECTION("Redundant enable operations") {
        log::enableLevel(Lvl::Work, Lvl::Work);
        log::disableLevel(Lvl::File);
        REQUIRE(log::isLevelEnabled(Lvl::Work, Lvl::Work));
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work, Lvl::File));

        SECTION("Redundant disable operations") {
            log::disableLevel(Lvl::Work, Lvl::Work, Lvl::File);
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work, Lvl::File));
        }
    }
    SECTION("String-based redundant enabling") {
        log::enableLevel("WORK", "WORK");
        log::disableLevel("CONNECTION");
        REQUIRE(log::isLevelEnabled("WORK", "WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));

        SECTION("String-based redundant disabling") {
            log::disableLevel("WORK", "WORK", "CONNECTION");
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));
        }
    }
    SECTION("String-based enabling with whitespace handling") {
        log::enableLevel(" WORK", " WORK ");
        log::disableLevel(" CONNECTION");
        REQUIRE(log::isLevelEnabled("WORK", "WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));

        SECTION("String-based disabling with whitespace handling") {
            log::disableLevel(" WORK ", " WORK ", " CONNECTION ");
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK"));
