// Main entry point for beesd management utility
int main(int argc, char *argv[]) {
    // Validate command line arguments
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <start|stop|restart|status> <uuid>\n";
        return 1;
    }

    // Extract command and UUID from arguments
    std::string action = argv[1];
    std::string bee_id = argv[2];

    // Execute the requested operation
    if (action == "start") {
        if (bk_mgmt::beesstart(bee_id)) {
            std::cout << "Started beesd for " << bee_id << std::endl;
        } else {
            std::cerr << "Failed to start beesd for " << bee_id << std::endl;
        }
    }
    else if (action == "stop") {
        if (bk_mgmt::beesstop(bee_id)) {
            std::cout << "Stopped beesd for " << bee_id << std::endl;
        } else {
            std::cerr << "Failed to stop beesd for " << bee_id << std::endl;
        }
    }
    else if (action == "restart") {
        if (bk_mgmt::beesrestart(bee_id)) {
            std::cout << "Restarted beesd for " << bee_id << std::endl;
        } else {
            std::cerr << "Failed to restart beesd for " << bee_id << std::endl;
        }
    }
    else if (action == "status") {
        std::string current_status = bk_mgmt::beesstatus(bee_id);
        std::cout << "Status: " << current_status << std::endl;
    }
    else {
        std::cerr << "Invalid command: " << action << std::endl;
        return 1;
    }

    return 0;
}

