/**
 * @brief Launch the column-sweep inversion kernel for half-precision inputs.
 *
 * @param vec_in  Pointer to the input tensor in global memory.
 * @param vec_out Pointer to the output tensor in global memory.
 * @param tiling_gm Pointer to the tiling configuration in global memory.
 */
extern "C" __global__ __aicore__ void tri_inv_col_sweep_fp16(GM_ADDR vec_in, GM_ADDR vec_out, GM_ADDR tiling_gm)
{
    // Load and unpack tiling parameters
    sglang::npu_kernel::TriInvColumnSweepTiling config;
    sglang::npu_kernel::LoadTilingConfiguration(&config, tiling_gm);

    // Extract key dimensions from tiling metadata
    const auto elem_count = config.total_elements;
    const auto mat_dim    = config.dimension;

    // Dispatch kernel with explicit type
    sglang::npu_kernel::ExecuteColumnSweep<half>(vec_in, vec_out, elem_count, mat_dim);
}

/**
 * @brief Launch the column-sweep inversion kernel for single-precision inputs.
 *
 * @param vec_in  Pointer to the input tensor in global memory.
 * @param vec_out Pointer to the output tensor in global memory.
 * @param tiling_gm Pointer to the tiling configuration in global memory.
 */
extern "C" __global__ __aicore__ void tri_inv_col_sweep_fp32(GM_ADDR vec_in, GM_ADDR vec_out, GM_ADDR tiling_gm)
{
    // Load and unpack tiling parameters
    sglang::npu_kernel::TriInvColumnSweepTiling config;
    sglang::npu_kernel::LoadTilingConfiguration(&config, tiling_gm);

    // Extract key dimensions from tiling metadata
    const auto elem_count = config.total_elements;
    const auto mat_dim    = config.dimension;

    // Dispatch kernel with explicit type
    sglang::npu_kernel::ExecuteColumnSweep<float>(vec_in, vec_out, elem_count, mat_dim);
}

#include <iostream>

class FinancialAccount {
private:
    double currentBalance;
    mutable int balanceQueryCount;   // Tracks how many times balance is checked, even in const methods
    int activityCount;               // Counts actual financial operations (deposit/withdraw)
    mutable int totalActivityCount;  // Counts all interactions with the account

public:
    FinancialAccount() : FinancialAccount(0.0) {}
    explicit FinancialAccount(double initialAmount) 
        : currentBalance(initialAmount), 
          balanceQueryCount(0), 
          activityCount(0), 
          totalActivityCount(0) {}

    // Read-only method to view balance
    double viewBalance() const {
        ++balanceQueryCount;
        ++totalActivityCount;
        std::cout << "[VIEW BALANCE] Query count: " << balanceQueryCount << std::endl;
        return currentBalance;
    }

    // Method to add funds
    void addFunds(double amount) {
        ++totalActivityCount;
        if (amount > 0) {
            currentBalance += amount;
            ++activityCount;
            std::cout << "[ADD FUNDS] Amount: $" << amount << " | Total Activities: " << activityCount << std::endl;
        }
    }

    // Method to remove funds
    void removeFunds(double amount) {
        ++totalActivityCount;
        if (amount > 0 && amount <= currentBalance) {
            currentBalance -= amount;
            ++activityCount;
            std::cout << "[REMOVE FUNDS] Amount: $" << amount << " | Total Activities: " << activityCount << std::endl;
        } else {
            std::cout << "[REMOVE FUNDS] Insufficient funds!" << std::endl;
        }
    }

    // Display summary statistics
    void displaySummary() const {
        ++totalActivityCount;
        std::cout << "Total Operations: " << totalActivityCount << std::endl;
        std::cout << "Balance Queries: " << balanceQueryCount << " | Financial Activities: " << activityCount << std::endl;
    }
};

int main() {
    FinancialAccount wallet(1000.0);

    // Multiple balance checks
    std::cout << "Current Balance: $" << wallet.viewBalance() << std::endl;
    std::cout << "Current Balance: $" << wallet.viewBalance() << std::endl;

    // Execute transactions
    wallet.addFunds(500);
    wallet.removeFunds(300);
    wallet.removeFunds(1500);

    // Final balance check
    std::cout << "Current Balance: $" << wallet.viewBalance() << std::endl;

    // Show overall stats
    wallet.displaySummary();

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

// Approximate LCS via greedy skip-cost minimization
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    if (!(cin >> s1 >> s2)) return 0;

    int len1 = s1.size();
    int len2 = s2.size();

    // Precompute positions for each character (ASCII range)
    vector<int> positions1[128];
    vector<int> positions2[128];

    for (int idx = 0; idx < len1; ++idx) {
        unsigned char ch = static_cast<unsigned char>(s1[idx]);
        positions1[ch].push_back(idx);
    }
    for (int idx = 0; idx < len2; ++idx) {
        unsigned char ch = static_cast<unsigned char>(s2[idx]);
        positions2[ch].push_back(idx);
    }

    // Track current position in each character's position list
    int cursor1[128] = {0};
    int cursor2[128] = {0};

    string result;
    result.reserve(min(len1, len2));

    int i = 0, j = 0;
    const int MAX_COST = 1'000'000'000;

    while (i < len1 && j < len2) {
        unsigned char c1 = static_cast<unsigned char>(s1[i]);
        unsigned char c2 = static_cast<unsigned char>(s2[j]);

        if (c1 == c2) {
            result += s1[i];
            ++i;
            ++j;
        } else {
            // Find next occurrence of c1 in s2 starting from j
            int next_pos_c1_in_s2 = -1;
            while (cursor2[c1] < static_cast<int>(positions2[c1].size()) &&
                   positions2[c1][cursor2[c1]] < j) {
                ++cursor2[c1];
            }
            if (cursor2[c1] < static_cast<int>(positions2[c1].size())) {
                next_pos_c1_in_s2 = positions2[c1][cursor2[c1]];
            }

            // Find next occurrence of c2 in s1 starting from i
            int next_pos_c2_in_s1 = -1;
            while (cursor1[c2] < static_cast<int>(positions1[c2].size()) &&
                   positions1[c2][cursor1[c2]] < i) {
                ++cursor1[c2];
            }
            if (cursor1[c2] < static_cast<int>(positions1[c2].size())) {
                next_pos_c2_in_s1 = positions1[c2][cursor1[c2]];
            }

            int cost_for_c1 = (next_pos_c1_in_s2 == -1) ? MAX_COST : (next_pos_c1_in_s2 - j);
            int cost_for_c2 = (next_pos_c2_in_s1 == -1) ? MAX_COST : (next_pos_c2_in_s1 - i);

            if (cost_for_c1 == MAX_COST && cost_for_c2 == MAX_COST) {
                // Neither character appears later in the other string
                ++i;
                ++j;
            } else if (cost_for_c1 <= cost_for_c2) {
                // Prefer matching c1: add it to result and advance accordingly
                result += s1[i];
                ++i;
                j = next_pos_c1_in_s2 + 1;
            } else {
                // Prefer matching c2: add it to result and advance accordingly
                result += s2[j];
                i = next_pos_c2_in_s1 + 1;
                ++j;
            }
        }
    }

    cout << result << '\n';
    return 0;
}

