// Manual definitions for older libc headers compatibility (e.g., Ubuntu 12.04)
#ifndef MADV_DONTDUMP
    #define MADV_DONTDUMP 16 /* Exclude pages from core dump */
#endif
#ifndef MADV_DODUMP
    #define MADV_DODUMP 17 /* Revert earlier MADV_DONTDUMP */
#endif

namespace {
    void PerformMadvise(int advice, const void* ptr, size_t len) {
        static const size_t pageSz = NSystemInfo::GetPageSize();
        void* alignedStart = AlignDown(const_cast<void*>(ptr), pageSz);
        size_t alignedLen = AlignUp(len, pageSz);

#if defined(_win_)
        if (!VirtualFree(alignedStart, alignedLen, advice)) {
            TString errorMsg(LastSystemErrorText());
            ythrow yexception() << "VirtualFree(" << alignedStart << ", " << alignedLen << ", " << advice << ") failed: " << errorMsg;
        }
#else
        if (-1 == madvise(alignedStart, alignedLen, advice)) {
            TString errorMsg(LastSystemErrorText());
            ythrow yexception() << "madvise(" << alignedStart << ", " << alignedLen << ", " << advice << ") failed: " << errorMsg;
        }
#endif
    }
} // anonymous namespace

// Sequential access hints
void MadviseSequentialAccess(const void* addr, size_t count) {
#if !defined(_win_)
    PerformMadvise(MADV_SEQUENTIAL, addr, count);
#endif
}

void MadviseSequentialAccess(TArrayRef<const char> buffer) {
    MadviseSequentialAccess(buffer.data(), buffer.size());
}

void MadviseSequentialAccess(TArrayRef<const ui8> buffer) {
    MadviseSequentialAccess(buffer.data(), buffer.size());
}

// Random access hints
void MadviseRandomAccess(const void* addr, size_t count) {
#if !defined(_win_)
    PerformMadvise(MADV_RANDOM, addr, count);
#endif
}

void MadviseRandomAccess(TArrayRef<const char> buffer) {
    MadviseRandomAccess(buffer.data(), buffer.size());
}

void MadviseRandomAccess(TArrayRef<const ui8> buffer) {
    MadviseRandomAccess(buffer.data(), buffer.size());
}

// Memory eviction / release hints
void MadviseEvict(const void* addr, size_t count) {
#if defined(_win_)
    PerformMadvise(MEM_DECOMMIT, addr, count);
#elif defined(_linux_) || defined(_cygwin_)
    PerformMadvise(MADV_DONTNEED, addr, count);
#else // FreeBSD, macOS, etc.
    PerformMadvise(MADV_FREE, addr, count);
#endif
}

void MadviseEvict(TArrayRef<const char> buffer) {
    MadviseEvict(buffer.data(), buffer.size());
}

void MadviseEvict(TArrayRef<const ui8> buffer) {
    MadviseEvict(buffer.data(), buffer.size());
}

// Core dump exclusion / inclusion
void MadviseExcludeFromCoreDump(const void* addr, size_t count) {
#if defined(_darwin_)
    Y_UNUSED(addr);
    Y_UNUSED(count);
#elif !defined(_win_)
    PerformMadvise(MADV_DONTDUMP, addr, count);
#endif
}

void MadviseExcludeFromCoreDump(TArrayRef<const char> buffer) {
    MadviseExcludeFromCoreDump(buffer.data(), buffer.size());
}

void MadviseExcludeFromCoreDump(TArrayRef<const ui8> buffer) {
    MadviseExcludeFromCoreDump(buffer.data(), buffer.size());
}

void MadviseIncludeIntoCoreDump(const void* addr, size_t count) {
#if defined(_darwin_)
    Y_UNUSED(addr);
    Y_UNUSED(count);
#elif !defined(_win_)
    PerformMadvise(MADV_DODUMP, addr, count);
#endif
}

void MadviseIncludeIntoCoreDump(TArrayRef<const char> buffer) {
    MadviseIncludeIntoCoreDump(buffer.data(), buffer.size());
}

void MadviseIncludeIntoCoreDump(TArrayRef<const ui8> buffer) {
    MadviseIncludeIntoCoreDump(buffer.data(), buffer.size());
}

