// Last received joint state message
sensor_msgs::JointState lastJointStateMsg;

// Publisher for visualization topics
std::unique_ptr<ros::Publisher> pubPublisher;

// Helper: prints vector elements in brackets separated by semicolons
auto printPairs = [](const auto& container, const std::string& label) {
    std::cerr << label << ": ";
    std::for_each(container.begin(), container.end(), [&](const auto& p) {
        std::cerr << "[" << p.first << ", " << p.second << "] ; ";
    });
    std::cerr << std::endl;
};

// Callback function for incoming joint states
void jointStateCallback(sensor_msgs::JointStateConstPtr msg) {
    // Skip if no change in positions
    if (lastJointStateMsg.position == msg->position) return;

    lastJointStateMsg.position = msg->position;

    // Construct configuration vector q: first 3 entries zero (base), rest from joints
    Eigen::VectorXd q(9);
    q.head<3>().setZero();  // base pose components
    std::transform(msg->position.begin(), msg->position.end(),
                   q.data() + 3,
                   [](double val) { return val; });

    visualizerPtr->publishDistances(q);
}

int main(int argc, char** argv) {
    ros::init(argc, argv, "distance_visualization");
    ros::NodeHandle nh;

    // Load required file paths
    std::string urdfFilePath, taskConfigPath;
    nh.getParam("/taskFile", taskConfigPath);
    nh.getParam("/urdfFile", urdfFilePath);

    // Parse task configuration file
    boost::property_tree::ptree configTree;
    boost::property_tree::read_info(taskConfigPath, configTree);

    // Extract manipulator type
    ManipulatorModelType robotModelType = loadManipulatorType(taskConfigPath, "model_information.manipulatorModelType");

    // Load list of joints to remove
    std::vector<std::string> excludedJointNames;
    loadData::loadStdVector<std::string>(taskConfigPath, "model_information.removeJoints", excludedJointNames, true);

    // Get base frame name
    std::string worldFrameName;
    loadData::loadPtreeValue<std::string>(configTree, worldFrameName, "model_information.baseFrame", false);

    // Build pinocchio interface
    modelInterfacePtr.reset(new PinocchioInterface(::ocs2::mobile_manipulator::createPinocchioInterface(urdfFilePath, robotModelType)));

    // Print model info summary
    std::cerr << "\n #### Model Information:";
    std::cerr << "\n #### =============================================================================\n";
    std::cerr << "\n #### model_information.manipulatorModelType: " << static_cast<int>(robotModelType);
    std::cerr << "\n #### model_information.removeJoints: ";
    for (const auto& name : excludedJointNames) {
        std::cerr << "\"" << name << "\" ";
    }
    std::cerr << "\n #### model_information.baseFrame: \"" << worldFrameName << "\"";

    // Self-collision pair definitions
    std::vector<std::pair<size_t, size_t>> objectCollisionPairs;
    std::vector<std::pair<std::string, std::string>> linkCollisionPairs;

    loadData::loadStdVectorOfPair(taskConfigPath, "selfCollision.collisionObjectPairs", objectCollisionPairs);
    loadData::loadStdVectorOfPair(taskConfigPath, "selfCollision.collisionLinkPairs", linkCollisionPairs);

    printPairs(objectCollisionPairs, "Loaded collision object pairs");
    printPairs(linkCollisionPairs, "Loaded collision link pairs");

    // Initialize geometry interface
    geometryInterfacePtr.reset(
        new PinocchioGeometryInterface(*modelInterfacePtr, linkCollisionPairs, objectCollisionPairs));

    // Initialize visualizer
    visualizerPtr.reset(new GeometryInterfaceVisualization(*modelInterfacePtr, *geometryInterfacePtr, nh, worldFrameName));

    // Subscribe to joint states
    ros::Subscriber sub = nh.subscribe("joint_states", 1, &jointStateCallback);

    // Run ROS spin loop
    ros::spin();

    return 0;
}

