#define POOLSTL_STD_SUPPLEMENT
#include <poolstl/poolstl.hpp>

#if __has_include(<poolstl/variant_policy.hpp>)
#include <poolstl/variant_policy.hpp>

using std_exec_variant = std::variant<std::execution::parallel_policy, 
                                      std::execution::sequenced_policy>;

/**
 * Custom variant-based policy selector mimicking poolstl::par_if behavior
 * but using standard execution policies.
 */
poolstl::variant_policy<std_exec_variant> custom_par_selector(bool use_parallel) {
    if (use_parallel) {
        return poolstl::variant_policy(std_exec_variant(std::execution::par));
    } else {
        return poolstl::variant_policy(std_exec_variant(std::execution::seq));
    }
}
#endif

int main() {
    // Check whether poolSTL's parallel policy is identical to std's
    if (std::is_same_v<std::execution::parallel_policy, poolstl::execution::parallel_policy>) {
        std::cout << "Using poolSTL supplement" << std::endl;
    } else {
        std::cout << "Using native par" << std::endl;
    }

    std::vector<int> data = {0, 1, 2, 3, 4, 5};

    // Sequential execution
    std::for_each(std::execution::seq, data.cbegin(), data.cend(), [](int val) {
        std::cout << val;
    });
    std::cout << " seq" << std::endl;

    // Parallel execution
    std::for_each(std::execution::par, data.cbegin(), data.cend(), [](int val) {
        std::cout << val;
    });
    std::cout << " par" << std::endl;

    // Parallel with unsequenced execution
    std::for_each(std::execution::par_unseq, data.cbegin(), data.cend(), [](int val) {
        std::cout << val;
    });
    std::cout << " par_unseq" << std::endl;

#if __has_include(<poolstl/variant_policy.hpp>)
    // Test custom policy selector
    for (bool flag : {true, false}) {
        auto policy = custom_par_selector(flag);
        std::for_each(policy, data.cbegin(), data.cend(), [](int val) {
            std::cout << val;
        });
        std::cout << " custom_par(" << std::to_string(flag) << ")" << std::endl;
    }
#endif

    return 0;
}

