// tag::decl[]
bool is_short_timeout(pugi::xml_node node)
{
    return node.attribute("Timeout").as_int() < 20;
}

struct has_remote_permission
{
    bool operator()(pugi::xml_attribute attr) const
    {
        return std::strcmp(attr.name(), "AllowRemote") == 0;
    }

    bool operator()(pugi::xml_node node) const
    {
        return node.attribute("AllowRemote").as_bool();
    }
};
// end::decl[]

int main()
{
    pugi::xml_document doc;
    if (!doc.load_file("xgconsole.xml")) 
        return -1;

    pugi::xml_node tools = doc.child("Profile").child("Tools");

    // tag::find[]
    // Locate direct child using custom predicate
    std::cout << tools.find_child(has_remote_permission()).attribute("Filename").value() << std::endl;

    // Locate any descendant node (depth-first search) using predicate
    std::cout << doc.find_node(has_remote_permission()).attribute("Filename").value() << std::endl;

    // Locate attribute using predicate on the last child of tools
    std::cout << tools.last_child().find_attribute(has_remote_permission()).value() << std::endl;

    // Demonstrate using a function pointer instead of a functor
    std::cout << tools.find_child(is_short_timeout).attribute("Filename").value() << std::endl;
    // end::find[]
}
