namespace Gorgon::Utils {

    void CrashHandler::Backtrace() {
        // Capture stack trace, adjusting skip count to bypass internal handling
        auto rawTrace = cpptrace::generate_trace(skip + 2);

        StdConsole console;
        int currentFrame = 0;
        const int maxFramesToShow = depth;

        for (const auto& entry : rawTrace.frames) {
            if (currentFrame >= maxFramesToShow) break;

            // Normalize path separators and extract components
            std::string normalizedPath = String::Replace(entry.filename, "\\", "/");

            std::string directoryPath = Filesystem::GetDirectory(normalizedPath);
            // Trim trailing slash if present
            if (!directoryPath.empty() && directoryPath.back() == '/') {
                directoryPath.pop_back();
            }
            std::string baseDirName = Filesystem::GetFilename(directoryPath);
            std::string fileName = Filesystem::GetFilename(normalizedPath);

            console.SetColor(Console::Magenta);

            // Emphasize second frame (frame index 1) as it follows the assert call
            bool isEmphasized = (currentFrame == 1);
            if (isEmphasized) {
                console.SetBold(true);
            }

            std::cout << "  [" << currentFrame << "] ";
            console.SetBold(false);
            console.SetColor(Console::Default);

            if (!entry.symbol.empty()) {
                std::cout << "  In function ";
                console.SetColor(Console::Yellow);
                std::cout << entry.symbol << " ";
            }
            console.SetColor(Console::Default);

            std::cout << "at ";
            if (isEmphasized) {
                console.SetColor(Console::Red);
            }

            std::cout << "..." << baseDirName << "/" << fileName;
            console.SetBold();

            if (entry.line.has_value()) {
                std::cout << ":" << entry.line.value();
            } else {
                std::cout << ":??";
            }

            std::cout << std::endl;
            console.Reset();

            ++currentFrame;
        }
    }

    struct CrashHandler::dumponlytag CrashHandler::DumpOnlyTag;

}

#include <iostream>
#include <vector>
#include <numeric>
#include <cmath>
#include <algorithm>

void process() {
    // First interaction: send 100000 words each of length 1
    std::cout << "? 100000";
    for (int idx = 0; idx < 100000; ++idx) {
        std::cout << " 1";
    }
    std::cout << std::endl;

    long long response1;
    std::cin >> response1;

    if (response1 == -1) { // Handle error condition
        return;
    }

    if (response1 == 1) {
        std::cout << "! 100000" << std::endl;
        return;
    }

    // Compute bounds based on first response
    long long lower_bound = (100000LL + response1 - 1) / response1;
    long long upper_bound = (100000LL - 1) / (response1 - 1);

    if (lower_bound == upper_bound) {
        std::cout << "! " << lower_bound << std::endl;
        return;
    }

    // Second interaction: construct article with varying lengths
    long long range_size = upper_bound - lower_bound + 1;
    long long query_count = 2 * (range_size - 1);

    std::cout << "? " << query_count;
    for (long long step = 1; step < range_size; ++step) {
        std::cout << " " << lower_bound << " " << step;
    }
    std::cout << std::endl;

    long long response2;
    std::cin >> response2;

    if (response2 == -1) { // Handle error condition
        return;
    }

    // Derive final answer from second response
    long long result_word_count = 2 * upper_bound - lower_bound - response2;
    std::cout << "! " << result_word_count << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

