using asio::ip::tcp;

// Generate current time string
std::string get_current_time()
{
  using namespace std;
  time_t current = time(0);
  return ctime(&current);
}

// Connection handler class for TCP communication
class tcp_session
  : public boost::enable_shared_from_this<tcp_session>
{
public:
  typedef boost::shared_ptr<tcp_session> sptr;

  static sptr make(asio::io_context& ctx)
  {
    return sptr(new tcp_session(ctx));
  }

  tcp::socket& get_socket()
  {
    return sock_;
  }

  void begin()
  {
    data_ = get_current_time();
    asio::async_write(sock_, asio::buffer(data_),
        boost::bind(&tcp_session::on_write, shared_from_this(),
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

private:
  tcp_session(asio::io_context& ctx)
    : sock_(ctx)
  {
  }

  void on_write(const asio::error_code& /*ec*/, size_t /*transferred*/)
  {
    // Write completed - no action needed
  }

  tcp::socket sock_;
  std::string data_;
};

// Server class to accept incoming connections
class tcp_acceptor
{
public:
  tcp_acceptor(asio::io_context& ctx)
    : acc_(ctx, tcp::endpoint(tcp::v4(), 13))
  {
    initiate_accept();
  }

private:
  void initiate_accept()
  {
    tcp_session::sptr client = tcp_session::make(acc_.get_executor().context());
    acc_.async_accept(client->get_socket(),
        boost::bind(&tcp_acceptor::on_client_connected, this, client,
          asio::placeholders::error));
  }

  void on_client_connected(tcp_session::sptr client, const asio::error_code& ec)
  {
    if (!ec)
    {
      client->begin();
    }
    initiate_accept();
  }

  tcp::acceptor acc_;
};

int main()
{
  try
  {
    asio::io_context context;
    tcp_acceptor server(context);
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << ex.what() << std::endl;
  }
  return 0;
}

#include <library/cpp/testing/unittest/registar.h>
#include "spinlock.h"

Y_UNIT_TEST_SUITE(TSpinLockTests) {
    template <typename TLockType>
    void ValidateLockBehavior() {
        TLockType mutex;

        // Initial state checks
        UNIT_ASSERT(!mutex.IsLocked());

        // Acquire and verify locked state
        mutex.Acquire();
        UNIT_ASSERT(mutex.IsLocked());

        // Release and verify unlocked state
        mutex.Release();
        UNIT_ASSERT(!mutex.IsLocked());

        // TryAcquire test sequence
        UNIT_ASSERT(mutex.TryAcquire());
        UNIT_ASSERT(mutex.IsLocked());
        UNIT_ASSERT(!mutex.TryAcquire());  // Should fail when already locked
        UNIT_ASSERT(mutex.IsLocked());

        // Final release
        mutex.Release();
        UNIT_ASSERT(!mutex.IsLocked());

        // Standard Lockable interface compliance
        mutex.lock();
        UNIT_ASSERT(mutex.IsLocked());
        UNIT_ASSERT(!mutex.try_lock());   // try_lock should fail while locked
        mutex.unlock();
        UNIT_ASSERT(!mutex.IsLocked());
    }

    Y_UNIT_TEST(TSpinLock_Functionality) {
        ValidateLockBehavior<TSpinLock>();
    }

    Y_UNIT_TEST(TAdaptiveLock_Functionality) {
        ValidateLockBehavior<TAdaptiveLock>();
    }
} // Y_UNIT_TEST_SUITE(TSpinLockTests)

