#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <random>
#include <numeric>

// Use __int128 for intermediate products to avoid overflow.
using int128 = __int128_t;

long long modulus;
inline int bit_count(long long x) {
    if (x == 0) return 0;
    return 64 - __builtin_clzll(x);
}

long long estimate_duration(long long base, long long exponent_guess) {
    long long total_duration = 0;
    int128 accumulator = 1;
    int128 current_base = base;

    for (int position = 0; position < 60; ++position) {
        if ((exponent_guess >> position) & 1) {
            total_duration += (bit_count((long long)accumulator) + 1) * 
                              (bit_count((long long)current_base) + 1);
            accumulator = (accumulator * current_base) % modulus;
        }
        total_duration += (bit_count((long long)current_base) + 1) * 
                          (bit_count((long long)current_base) + 1);
        current_base = (current_base * current_base) % modulus;
    }

    return total_duration;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> modulus;

    // Since d is coprime with φ(n), and φ(n) is even, d must be odd
    long long current_d = 1;

    // Initialize RNG with high-resolution clock
    std::mt19937_64 prng(std::chrono::steady_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<long long> range(2, modulus - 1);

    const int trials_per_bit = 400;

    // Determine each bit from position 1 to 59
    for (int bit_pos = 1; bit_pos < 60; ++bit_pos) {
        long double cumulative_score = 0.0L;

        long long guess_without_bit = current_d;
        long long guess_with_bit = current_d | (1LL << bit_pos);

        for (int trial = 0; trial < trials_per_bit; ++trial) {
            long long sample_base = range(prng);

            std::cout << "? " << sample_base << "\n";
            long long measured_time;
            std::cin >> measured_time;

            long long predicted_time_0 = estimate_duration(sample_base, guess_without_bit);
            long long predicted_time_1 = estimate_duration(sample_base, guess_with_bit);

            int128 error_0 = measured_time - predicted_time_0;
            int128 error_1 = measured_time - predicted_time_1;

            cumulative_score += static_cast<long double>(error_0) * error_0 -
                                static_cast<long double>(error_1) * error_1;
        }

        if (cumulative_score > 0) {
            current_d = guess_with_bit;
        }
    }

    std::cout << "! " << current_d << "\n";
    return 0;
}

