            std::cout << "Tool:";

            // Print all attributes of the current Tool node
            pugi::xml_attribute attr = tool.first_attribute();
            while (attr)
            {
                std::cout << " " << attr.name() << "=" << attr.value();
                attr = attr.next_attribute();
