#include "CachingAllocatorHookMock.hpp"
using ::testing::_;
using ::testing::DoAll;
using ::testing::Return;

namespace torch::comms::test {

void CachingAllocatorHookMock::setupDefaultBehaviors() {
  // Configure default behavior for registerComm: add communicator to tracking set
  ON_CALL(*this, registerComm(_)).WillByDefault([this](TorchCommNCCLX* comm) {
    registered_comms_.emplace(comm);
  });

  // Configure default behavior for deregisterComm: remove communicator from tracking set
  ON_CALL(*this, deregisterComm(_)).WillByDefault([this](TorchCommNCCLX* comm) {
    registered_comms_.erase(comm);
  });

  // Configure default behavior for regDeregMem: perform no operation
  ON_CALL(*this, regDeregMem(_)).WillByDefault(Return());

  // Configure default behavior for registerMemPreHook: update internal flag
  ON_CALL(*this, registerMemPreHook()).WillByDefault([this]() {
    mem_pre_hook_registered_ = true;
  });

  // Trigger initial registration of memory pre-hook (mimicking DefaultCachingAllocatorHookImpl)
  registerMemPreHook();

  // Configure default behavior for clear: empty the communicator registry
  ON_CALL(*this, clear()).WillByDefault([this]() {
    registered_comms_.clear();
  });
}

void CachingAllocatorHookMock::reset() {
  // Clear all Google Mock expectations and reset call counts
  ::testing::Mock::VerifyAndClearExpectations(this);

  // Reset internal state
  registered_comms_.clear();
  mem_pre_hook_registered_ = false;

  // Reapply default behaviors after reset
  setupDefaultBehaviors();
}

bool CachingAllocatorHookMock::isCommRegistered(TorchCommNCCLX* comm) {
  return registered_comms_.count(comm) > 0;
}

bool CachingAllocatorHookMock::isMemRegisteredCalled() {
  return mem_pre_hook_registered_;
}

