// Helper: Check if IP starts with prefix using manual string comparison
bool ipStartsWith(const String& ip, const char* prefix) {
    size_t prefixLen = strlen(prefix);
    if (ip.length() < prefixLen) return false;
    for (size_t i = 0; i < prefixLen; ++i) {
        if (ip[i] != prefix[i]) return false;
    }
    return true;
}

// Test: New manager instance should be unconnected and have empty SSID
void test_network_manager_init() {
    NetworkManager netMgr;
    TEST_ASSERT_FALSE(netMgr.isConnected());
    String ssid = netMgr.getSSID();
    TEST_ASSERT_EQUAL(0U, ssid.length());
}

// Test: AP mode activation when no credentials are saved
void test_network_manager_ap_mode() {
    NetworkManager netMgr;
    netMgr.begin();              // Triggers deferred START_AP command
    netMgr.processPendingTasks(); // Replaces handleClient() to process queued actions

    TEST_ASSERT_FALSE(netMgr.isConnected());
    String ipAddr = netMgr.getIPAddress();
    TEST_ASSERT_TRUE(ipStartsWith(ipAddr, "192.168.4."));
    String ssid = netMgr.getSSID();
    TEST_ASSERT_TRUE(ssid.startsWith("ESP32_"));
}

// Test: Credential saving triggers connection attempt
void test_network_manager_save_credentials() {
    NetworkManager netMgr;
    netMgr.storeCredentials("TestSSID", "TestPassword");
    netMgr.processPendingTasks(); // Simulates CONNECT → CONNECTING transition

    TEST_ASSERT_EQUAL_STRING("TestSSID", netMgr.getSSID().c_str());
    TEST_ASSERT_FALSE(netMgr.isConnected()); // Mock WiFi never completes connection
}

// Test: begin() + processing does not crash and yields non-empty IP
void test_network_manager_no_crash_on_begin() {
    NetworkManager netMgr;
    netMgr.begin();
    netMgr.processPendingTasks();

    String ip = netMgr.getIPAddress();
    TEST_ASSERT_GREATER_THAN(0, ip.length());
}

