#define LOCTEXT_NAMESPACE "UOnAcceptHandleSourcesProperties"

void UOnAcceptHandleSourcesProperties::ApplyMethod(const TArray<AActor*>& Actors, UInteractiveToolManager* ToolManager)
{
	// Process source actors based on the selected action
	if (OnToolAccept != EHandleSourcesMethod::KeepSources)
	{
		const bool bShouldDelete = (OnToolAccept == EHandleSourcesMethod::DeleteSources);

#if WITH_EDITOR
		const FString TransactionName = bShouldDelete 
			? LOCTEXT("RemoveSources", "Remove Sources").ToString() 
			: LOCTEXT("HideSources", "Hide Sources").ToString();
		ToolManager->BeginUndoTransaction(TransactionName);
#endif

		for (AActor* Actor : Actors)
		{
			if (bShouldDelete)
			{
				Actor->Destroy();
			}
			else
			{
#if WITH_EDITOR
				// Store current state in transaction buffer for undo/redo support
				// Avoid calling Modify() to prevent package dirtiness since we only modify transient data
				SaveToTransactionBuffer(Actor, /*bMarkAsModified=*/false);
				Actor->SetIsTemporarilyHiddenInEditor(true);
#endif
			}
		}

#if WITH_EDITOR
		ToolManager->EndUndoTransaction();
#endif
	}
}

