//----------------------------------------------------------------------------------
// Initializes the scene: sets up UI elements, starts DLC install if needed,
// configures tooltips, and schedules automatic navigation after timeout.
//----------------------------------------------------------------------------------
HRESULT CScene_SaveMessage::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
	BindControls();
	CXuiSceneBase::ShowBackground(DEFAULT_XUI_MENU_USER, TRUE);
	CXuiSceneBase::ShowLogo(DEFAULT_XUI_MENU_USER, TRUE);

	m_button.SetText(app.GetString(IDS_CONFIRM_OK));
	m_SaveMessage.SetText(app.GetString(IDS_SAVE_ICON_MESSAGE));
	ui.SetTooltips(DEFAULT_XUI_MENU_USER, IDS_TOOLTIPS_SELECT);

	// 4J-PB - Attempt to begin DLC installation for any active user profile
	for (unsigned int userSlot = 0; userSlot < XUSER_MAX_COUNT; ++userSlot)
	{
		if (InputManager.IsPadConnected(userSlot) || ProfileManager.IsSignedIn(userSlot))
		{
			if (!app.DLCInstallProcessCompleted() && !app.DLCInstallPending())
			{
				app.StartInstallDLCProcess(userSlot);
				break;
			}
		}
	}

	// Schedule automatic transition after 8 seconds
	XuiSetTimer(m_hObj, 1, 8000);
	m_bSkipInput = false;

	return S_OK;
}

//----------------------------------------------------------------------------------
// Handles button press events (e.g., A button on controller).
//----------------------------------------------------------------------------------
HRESULT CScene_SaveMessage::OnNotifyPressEx(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
	if (m_bSkipInput) return S_OK;

	// Simulate key press animation using the user index and virtual key
	ui.AnimateKeyPress(pNotifyPressData->UserIndex, VK_PAD_A);
	XuiKillTimer(m_hObj, 1);
	app.NavigateToScene(XUSER_INDEX_ANY, eUIScene_MainMenu);
	rfHandled = TRUE;
	return S_OK;
}

//----------------------------------------------------------------------------------
// Handles keyboard input (e.g., for PC testing or keyboard support).
//----------------------------------------------------------------------------------
HRESULT CScene_SaveMessage::OnKeyDown(XUIMessageInput* pInputData, BOOL& rfHandled)
{
	if (m_bSkipInput) return S_OK;

	ui.AnimateKeyPress(pInputData->UserIndex, pInputData->dwKeyCode);
	return S_OK;
}

//----------------------------------------------------------------------------------
// Timer callback: handles forced navigation after timeout (compliance requirement).
// Ensures game doesn't hang during startup longer than allowed.
//----------------------------------------------------------------------------------
HRESULT CScene_SaveMessage::OnTimer(XUIMessageTimer* pData, BOOL& rfHandled)
{
	m_bSkipInput = true;
	XuiKillTimer(m_hObj, 1);
	app.NavigateToScene(XUSER_INDEX_ANY, eUIScene_MainMenu);
	rfHandled = TRUE;
	return S_OK;
}

