namespace FFBEngineTests {
TEST_CASE(test_tooltip_line_lengths, "UI") {
    std::cout << "\nTest: ToolTip Line Lengths (Issue #179)" << std::endl;

    const size_t MAX_ALLOWED_LENGTH = 80;
    int error_count = 0;

    for (const char* tooltip_ptr : Tooltips::ALL) {
        if (tooltip_ptr == nullptr) continue;

        std::string tooltip_str(tooltip_ptr);
        std::istringstream stream(tooltip_str);
        std::string current_line;

        while (std::getline(stream, current_line, '\n')) {
            if (current_line.size() > MAX_ALLOWED_LENGTH) {
                std::cout << "  [FAIL] Line exceeds maximum length (" 
                          << current_line.size() << " chars) in tooltip starting with: \""
                          << tooltip_str.substr(0, 20) << "...\"" << std::endl;
                std::cout << "         Actual line: " << current_line << std::endl;
                error_count++;
            }
        }
    }

    if (error_count > 0) {
        std::cout << "  Total violations: " << error_count << std::endl;
    }

    ASSERT_TRUE(error_count == 0);
}
