// Global XRT device instance
xrt::device npu_device_global;

int main(int argc, char* argv[]) {
    #ifdef __WINDOWS__
    SetConsoleOutputCP(CP_UTF8);
    SetConsoleCP(CP_UTF8);
    SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_LOWEST);
    #endif

    // Parse command-line arguments into a local configuration object
    struct Config {
        std::string model_tag;
        bool short_prompt = true;
        bool preemption = false;
    } cfg;

    arg_utils::po::options_description desc("Supported options");
    desc.add_options()
        ("model,m", arg_utils::po::value<std::string>()->required(), "Path to model file")
        ("Short,s", arg_utils::po::value<bool>()->default_value(true), "Use short prompt")
        ("Preemption,p", arg_utils::po::value<bool>()->default_value(false), "Enable preemption");

    arg_utils::po::store(arg_utils::po::parse_command_line(argc, argv, desc), vm);
    arg_utils::po::notify(vm);

    cfg.model_tag = vm["model"].as<std::string>();
    cfg.short_prompt = vm["Short"].as<bool>();
    cfg.preemption = vm["Preemption"].as<bool>();

    std::cout << "Selected model: " << cfg.model_tag << "\n";

    // Resolve paths
    const std::string bin_path = utils::get_executable_directory();
    const std::string models_root = utils::get_models_directory();
    const std::string config_file_path = bin_path + "/model_list.json";

    model_list loader(config_file_path, models_root);

    header_print("info", "Initializing chat model...");
    const std::string model_path = loader.get_model_path(cfg.model_tag);
    const auto& info_pair = loader.get_model_info(cfg.model_tag);
    nlohmann::json model_metadata = info_pair.second;

    std::cout << "Model location: " << model_path << "\n";

    // Initialize device before model loading
    npu_device_global = xrt::device(0);
    AutoModel* chat_ptr = new Qwen2(&npu_device_global);

    // Load model with given parameters
    chat_ptr->load_model(model_path, model_metadata, -1, cfg.preemption);
    chat_ptr->set_topp(0.8f);
    chat_ptr->set_temperature(0.7f);
    chat_ptr->set_repetition_penalty(1.01f);
    chat_ptr->set_frequency_penalty(1.01f);

    chat_meta_info_t meta_info;
    lm_uniform_input_t uniformed_input;

    if (cfg.short_prompt) {
        uniformed_input.prompt = "Hello";
        std::cout << "Prompt: " << uniformed_input.prompt << "\n";
        std::cout << "Response: ";
        chat_ptr->start_total_timer();
        std::string reply = chat_ptr->generate_with_prompt(meta_info, uniformed_input, 32, std::cout);
        chat_ptr->stop_total_timer();
        std::cout << "\n\n" << chat_ptr->show_profile() << "\n";
    } else {
        std::ifstream prompt_file("../../../prompt.txt", std::ios::binary);
        if (!prompt_file.is_open()) {
            std::cerr << "Error: Could not open prompt file\n";
            delete chat_ptr;
            return 1;
        }

        uniformed_input.prompt.clear();
        prompt_file.seekg(0, std::ios::end);
        uniformed_input.prompt.resize(prompt_file.tellg());
        prompt_file.seekg(0, std::ios::beg);
        prompt_file.read(uniformed_input.prompt.data(), uniformed_input.prompt.size());
        prompt_file.close();

        std::cout << "Prompt:\n" << uniformed_input.prompt << "\n";
        std::cout << "Response: ";
        chat_ptr->start_total_timer();
        std::string reply = chat_ptr->generate_with_prompt(meta_info, uniformed_input, 1024, std::cout);
        chat_ptr->stop_total_timer();
        std::cout << "\n\n" << chat_ptr->show_profile() << "\n";
    }

    // Retrieve and display generation history
    auto [text_history, token_ids] = chat_ptr->get_history();
    std::cout << "Token count in history: " << token_ids.size() << "\n\n";

    // Cleanup
    delete chat_ptr;
    return 0;
}

