extern "C"
{
#include <gcov.h>

    using gcov_counter_t = std::int64_t;

    // External references to coverage metadata sections
    extern const struct gcov_info* __gcov_info_begin[];
    extern const struct gcov_info* __gcov_info_limit[];

    // Memory region reserved for storing raw gcda data
    extern std::uint8_t __coverage_buffer_start[];
    extern std::uint8_t __coverage_buffer_end[];

    // Stub implementations required by gcov runtime
    void __gcov_merge_add(gcov_counter_t*, unsigned)
    {
        LLK_ASSERT(false, "__gcov_merge_add: unexpected call");
    }

    void abort()
    {
        LLK_ASSERT(false, "abort: fatal error");
    }

    std::uint32_t __umodsi3(std::uint32_t dividend, std::uint32_t divisor)
    {
        return dividend % divisor;
    }

    std::uint32_t __udivsi3(std::uint32_t numerator, std::uint32_t denominator)
    {
        return numerator / denominator;
    }

    // Helper function to copy data into the coverage buffer
    static void record_coverage_data(const void* src_ptr, unsigned int size, void*)
    {
        const std::uint8_t* source = static_cast<const std::uint8_t*>(src_ptr);
        std::uint32_t* offset_ptr  = reinterpret_cast<std::uint32_t*>(__coverage_buffer_start);
        std::uint8_t* dest         = __coverage_buffer_start + *offset_ptr;

        for (unsigned int idx = 0; idx < size; ++idx)
        {
            dest[idx] = source[idx];
        }

        *offset_ptr += size;
    }

    // Callback used during gcda generation to handle filename writing
    void dump_gcov_filename(const char* path, void*)
    {
        __gcov_filename_to_gcfn(path, record_coverage_data, nullptr);
    }

    // Main entry point to dump all coverage data into the reserved memory region
    void emit_coverage(void)
    {
        // Initialize byte counter at start of coverage buffer
        *reinterpret_cast<std::uint32_t*>(__coverage_buffer_start) = 4U;

        const struct gcov_info* const* cursor = __gcov_info_begin;
        asm volatile("" : "+r"(cursor)); // Compiler barrier

        std::uint16_t unit_count = static_cast<std::uint16_t>(__gcov_info_limit - __gcov_info_begin);

        for (std::uint16_t i = 0; i < unit_count; ++i)
        {
            __gcov_info_to_gcda(cursor[i], dump_gcov_filename, record_coverage_data, nullptr, nullptr);
        }
    }
}

