// Base class with virtual function f()
class Parent {
public:
    virtual void show() {
        std::cout << "parent::show()\n";
    }
};

// First derived class overriding the virtual function
class Child : public Parent {
public:
    virtual void show() override {
        std::cout << "child::show()\n";
    }
};

// Second level derived class also overriding the virtual function
class GrandChild : public Child {
public:
    virtual void show() override {
        std::cout << "grandchild::show()\n";
    }
};

// Function accepting a pointer to the base class and calling its virtual method
void display(Parent* ptr) {
    ptr->show();
}

int main() {
    Child obj;
    display(&obj);
    return 0;
}

#include <vector>
#include <mpi.h>
#include <algorithm>
#include <tuple>
#include <madvoro/Voronoi3D.hpp>
#include "mpi_utils.hpp"
#include "read_points.hpp"

using namespace MadVoro;

int main(int argc, char* argv[]) {
    MPI_Init(&argc, &argv);

    int myRank, totalRanks;
    MPI_Comm_rank(MPI_COMM_WORLD, &myRank);
    MPI_Comm_size(MPI_COMM_WORLD, &totalRanks);

    std::vector<Vector3D> globalPointList;
    std::vector<double> pointInsideFlags;

    if (myRank == 0) {
        // Load point sets from files
        std::vector<Vector3D> interiorPoints = readPoints("input/points_inside_fox");
        std::vector<Vector3D> exteriorPoints = readPoints("input/points_outside_fox");

        // Pre-allocate space to avoid repeated reallocations
        globalPointList.reserve(interiorPoints.size() + exteriorPoints.size());
        pointInsideFlags.reserve(interiorPoints.size() + exteriorPoints.size());

        // Append interior points and mark as inside (1)
        globalPointList.insert(globalPointList.end(), 
                               interiorPoints.begin(), interiorPoints.end());
        for (size_t idx = 0; idx < interiorPoints.size(); ++idx) {
            pointInsideFlags.push_back(1.0);
        }

        // Append exterior points and mark as outside (0)
        globalPointList.insert(globalPointList.end(), 
                               exteriorPoints.begin(), exteriorPoints.end());
        for (size_t idx = 0; idx < exteriorPoints.size(); ++idx) {
            pointInsideFlags.push_back(0.0);
        }
    }

    // Distribute points and flags across processes
    std::pair<std::vector<Vector3D>, std::vector<double>> localData;
    localData = SpreadPointsToProcessors(globalPointList, pointInsideFlags);
    auto& localPoints = localData.first;
    auto& localInsideFlags = localData.second;

    // Define bounding box for Voronoi domain
    Vector3D lowerCorner(-13.0, -1.0, -90.0);
    Vector3D upperCorner(15.0, 80.0, 70.0);
    Voronoi3D voronoi(lowerCorner, upperCorner);

    if (myRank == 0) {
        std::cout << "Building parallel Voronoi diagram..." << std::endl;
    }

    voronoi.SetVerbosity(true);  // Enable verbose build logging
    voronoi.BuildParallel(localPoints);

    // After parallel build, point ordering may have changed due to redistribution.
    // Re-synchronize point positions and their 'inside' status using helper function.
    std::vector<Vector3D> updatedPoints;
    std::vector<double> updatedInsideFlags;
    std::tie(updatedPoints, updatedInsideFlags) = 
        GetPointsAfterBuildExchange(voronoi, localPoints, localInsideFlags);

#ifdef MADVORO_WITH_VTK
    const std::string vtkOutputFile = "fox.vtu";
    if (myRank == 0) {
        std::cout << "Writing VTK output to: " << vtkOutputFile << std::endl;
    }
    // Export to VTK with per-point scalar field 'isInside'
    voronoi.ToVTK(vtkOutputFile, {"isInside"}, {updatedInsideFlags});
#else
    if (myRank == 0) {
        std::cout << "VTK support not compiled in — skipping VTK export." << std::endl;
    }
#endif

    MPI_Finalize();
    return 0;
}

#include <__config>
#include <__verbose_abort>
#include <cstdarg>
#include <cstdio>
#include <cstdlib>

#ifdef __BIONIC__
#  include <syslog.h>
extern "C" void android_set_abort_message(const char* msg);
#endif

#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
#  include <CrashReporterClient.h>
#endif

_LIBCPP_BEGIN_NAMESPACE_STD

// Custom implementation of verbose abort with equivalent semantics
_LIBCPP_WEAK void __libcpp_verbose_abort(char const* fmt, ...) noexcept {
    // First, print directly to standard error using variadic args
    va_list args;
    va_start(args, fmt);
    std::vfprintf(stderr, fmt, args);
    va_end(args);

    // Now prepare formatted string for crash logging systems
    char* msg_buffer = nullptr;
    va_list ap;
    va_start(ap, fmt);

#if defined(__APPLE__) && __has_include(<CrashReporterClient.h>)
    // Allocate and store message for crash reporting on Apple platforms
    vasprintf(&msg_buffer, fmt, ap);
    CRSetCrashLogMessage(msg_buffer);
#elif defined(__BIONIC__)
    // Handle Android/Bionic: set abort message and log to syslog
    vasprintf(&msg_buffer, fmt, ap);
    android_set_abort_message(msg_buffer);

    // Open connection to system logger and write critical-level message
    openlog("libc++", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_CRIT, "%s", msg_buffer);
    closelog();
#endif

    va_end(ap);

    // Terminate program execution
    std::abort();
}

_LIBCPP_END_NAMESPACE_STD

#include <cstdlib>
#include <iostream>
#include <memory>
#include <utility>
#include "asio.hpp"

using asio::ip::tcp;

// Echo session class handling client communication
class echo_session
  : public std::enable_shared_from_this<echo_session>
{
public:
  echo_session(tcp::socket sock)
    : socket_(std::move(sock))
  {
  }

  void begin()
  {
    initiate_read();
  }

private:
  void initiate_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_, buffer_size),
        [this, self](const std::error_code& err, std::size_t bytes_transferred)
        {
          if (!err)
          {
            respond(bytes_transferred);
          }
        });
  }

  void respond(std::size_t size)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(buffer_, size),
        [this, self](const std::error_code& err, std::size_t /*bytes_sent*/)
        {
          if (!err)
          {
            initiate_read();
          }
        });
  }

  tcp::socket socket_;
  static constexpr std::size_t buffer_size = 1024;
  char buffer_[buffer_size];
};

// Server class accepting incoming connections
class echo_server
{
public:
  echo_server(asio::io_context& ctx, unsigned short port_num)
    : acceptor_(ctx, tcp::endpoint(tcp::v4(), port_num))
  {
    await_connection();
  }

private:
  void await_connection()
  {
    acceptor_.async_accept(
        [this](const std::error_code& err, tcp::socket new_socket)
        {
          if (!err)
          {
            std::make_shared<echo_session>(std::move(new_socket))->begin();
          }
          await_connection();
        });
  }

  tcp::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: async_tcp_echo_server <port>\n";
      return 1;
    }

    asio::io_context context;
    unsigned short port = static_cast<unsigned short>(std::atoi(argv[1]));
    echo_server server_instance(context, port);

    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
    return 1;
  }

  return 0;
}

#include <asio.hpp>
#include <asio/buffer.hpp>
#include <asio/connect.hpp>
#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/read_until.hpp>
#include <asio/system_error.hpp>
#include <asio/write.hpp>
#include <cstdlib>
#include <iostream>
#include <string>
#include <chrono>

using asio::ip::tcp;

class client_connection
{
public:
    void establish_connection(const std::string& hostname, const std::string& port_number,
        std::chrono::steady_clock::duration deadline_duration)
    {
        // Resolve the hostname and port to a sequence of endpoints
        tcp::resolver resolver(io_context_);
        auto endpoint_iterator = resolver.resolve(hostname, port_number);

        // Initiate asynchronous connection with a lambda handler
        std::error_code ec;
        asio::async_connect(socket_, endpoint_iterator,
            [&](const std::error_code& ec_connect, const tcp::endpoint&) {
                ec = ec_connect;
            });

        // Enforce timeout using run_for
        enforce_timeout(deadline_duration);

        // Check if connection succeeded
        if (ec) {
            throw std::system_error(ec);
        }
    }

    std::string fetch_line(std::chrono::steady_clock::duration deadline_duration)
    {
        std::error_code ec;
        std::size_t bytes_read = 0;

        // Asynchronous read until newline delimiter
        asio::async_read_until(socket_,
            asio::dynamic_buffer(buffer_), '\n',
            [&](const std::error_code& ec_read, std::size_t n) {
                ec = ec_read;
                bytes_read = n;
            });

        // Apply timeout constraint
        enforce_timeout(deadline_duration);

        if (ec) {
            throw std::system_error(ec);
        }

        // Extract line and update buffer
        std::string extracted_line(buffer_.substr(0, bytes_read - 1));
        buffer_.erase(0, bytes_read);
        return extracted_line;
    }

    void send_line(const std::string& message, std::chrono::steady_clock::duration deadline_duration)
    {
        std::string payload = message + "\n";
        std::error_code ec;

        // Asynchronous write operation
        asio::async_write(socket_, asio::buffer(payload),
            [&](const std::error_code& ec_write, std::size_t) {
                ec = ec_write;
            });

        // Enforce time limit
        enforce_timeout(deadline_duration);

        if (ec) {
            throw std::system_error(ec);
        }
    }

private:
    void enforce_timeout(std::chrono::steady_clock::duration duration)
    {
        io_context_.restart();
        io_context_.run_for(duration);

        if (!io_context_.stopped())
        {
            // Cancel pending operations by closing socket
            socket_.close();

            // Wait for cancellation to take effect
            io_context_.run();
        }
    }

    asio::io_context io_context_;
    tcp::socket socket_{io_context_};
    std::string buffer_;
};

int main(int argc, char* argv[])
{
    try
    {
        if (argc != 4)
        {
            std::cerr << "Usage: blocking_tcp_client <host> <port> <message>\n";
            return 1;
        }

        client_connection conn;
        conn.establish_connection(argv[1], argv[2], std::chrono::seconds(10));

        auto start_time = std::chrono::steady_clock::now();
        conn.send_line(argv[3], std::chrono::seconds(10));

        // Echo back until receiving the same message we sent
        for (;;)
        {
            std::string response = conn.fetch_line(std::chrono::seconds(10));
            if (response == argv[3])
                break;
        }

        auto end_time = std::chrono::steady_clock::now();
        auto duration_us = std::chrono::duration_cast<std::chrono::microseconds>(
            end_time - start_time).count();

        std::cout << "Round trip time: " << duration_us << " microseconds\n";
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error occurred: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

