/**
 * @brief Test fixture for verifying PC address correction on GFX950.
 * This class customizes PC correction behavior based on record type.
 */
template <typename RecordType>
class Gfx950PcCorrectionTest : public MidMacroPCCorrection<GFX950, RecordType>
{
public:
    // Override method to generate PC sample with conditional mid_macro handling
    void producePcSample(uint64_t programCounter, bool isMidMacro) override
    {
        // For non-stochastic records, mid_macro flag should be ignored (set false)
        if constexpr (!std::is_same_v<RecordType, rocprofiler_pc_sampling_record_stochastic_v0_t>)
        {
            isMidMacro = false;
        }

        // Delegate to base class implementation
        MidMacroPCCorrection<GFX950, RecordType>::producePcSample(programCounter, isMidMacro);
    }

    // Override method to compute expected corrected PC value
    uint64_t deriveTargetPc(uint64_t rawPc, bool isMidMacro) override
    {
        // If mid_macro mode is active, subtract 2 DWORDs (8 bytes) from PC
        return isMidMacro ? (rawPc - 2u * sizeof(uint32_t)) : rawPc;
    }
};

// Define test case for GFX950 PC correction
TEST(pcs_parser, gfx950_test)
{
    // Run tests for both record types
    Gfx950PcCorrectionTest<rocprofiler_pc_sampling_record_host_trap_v0_t>{}.run();
    Gfx950PcCorrectionTest<rocprofiler_pc_sampling_record_stochastic_v0_t>{}.run();

    std::cout << "GFX950 validation completed successfully." << std::endl;
}

#include <iostream>
