using namespace std;

class Employee {
private:
    int id;
    string name;
public:
    void readData();
    void displayData();

    class Salary {
    private:
        float basic, houseRent, conveyance, medical, travel, deduction;
        float gross, netPay;
    public:
        void setData();
        void compute();
        void showResult();
    };
};

void Employee::readData() {
    cout << "Enter employee ID and name: ";
    cin >> id;
    cin.ignore(); // ignore newline
    getline(cin, name);
}

void Employee::displayData() {
    cout << "Employee ID: " << id << ", Name: " << name << endl;
}

void Employee::Salary::setData() {
    cout << "Enter base salary: ";
    cin >> basic;
}

void Employee::Salary::compute() {
    houseRent = 0.1f * basic;
    conveyance = 0.1f * basic;
    medical = 0.1f * basic;
    travel = 0.1f * basic;
    deduction = 0.1f * basic;
    gross = basic + houseRent + conveyance + medical + travel;
    netPay = gross - deduction;
}

void Employee::Salary::showResult() {
    cout << "Gross Salary: " << gross << ", Net Pay: " << netPay << endl;
}

int main() {
    Employee worker;
    Employee::Salary payment;

    worker.readData();
    payment.setData();
    payment.compute();
    worker.displayData();
    payment.showResult();

    return 0;
}

