#include <cmath>
#include <gtest/gtest.h>
#include <jonssonic/core/nonlinear/wave_shaper_processor.h>
using namespace jnsc;

// Alias for a float-based hardclip wave shaper
using HardClipStage = WaveShaperProcessor<float, WaveShaperType::HardClip>;

TEST(WaveShaperProcessor, DefaultConstruction) {
    HardClipStage processor;
    SUCCEED(); // Confirms successful default construction
}

TEST(WaveShaperProcessor, PrepareAndReset) {
    HardClipStage processor;
    processor.prepare(2, 44100.0f);
    processor.setInputGain(2.0_lin, true);
    processor.setOutputGain(0.5_lin, true);
    processor.setBias(0.1, true);
    processor.setAsymmetry(0.2, true);
    processor.reset();
    SUCCEED();
}

TEST(WaveShaperProcessor, ProcessSample) {
    HardClipStage processor;
    processor.prepare(1, 44100.0f);
    processor.setInputGain(1.0_lin, true);
    processor.setOutputGain(1.0_lin, true);
    processor.setBias(0.0f, true);
    processor.setAsymmetry(0.0f, true);

    // Identity behavior within [-1, 1]
    EXPECT_FLOAT_EQ(processor.processSample(0, 0.5f), 0.5f);
    EXPECT_FLOAT_EQ(processor.processSample(0, -0.5f), -0.5f);

    // Clamping outside [-1, 1]
    EXPECT_FLOAT_EQ(processor.processSample(0, 2.0f), 1.0f);
    EXPECT_FLOAT_EQ(processor.processSample(0, -2.0f), -1.0f);
}

TEST(WaveShaperProcessor, ParameterEffects) {
    HardClipStage processor;
    processor.prepare(1, 44100.0f);

    // Input gain test: amplify and clip
    processor.setInputGain(2.0_lin, true);
    EXPECT_FLOAT_EQ(processor.processSample(0, 0.5f), 1.0f); // 0.5 * 2 = 1 → clipped

    // Output gain test: scale after clipping
    processor.setInputGain(1.0_lin, true);
    processor.setOutputGain(0.5_lin, true);
    EXPECT_FLOAT_EQ(processor.processSample(0, 1.0f), 0.5f); // 1 → clip to 1, then *0.5

    // Bias test: shift input before clipping
    processor.setOutputGain(1.0_lin, true);
    processor.setBias(1.0, true);
    EXPECT_FLOAT_EQ(processor.processSample(0, 0.0f), 1.0f); // 0 + 1 = 1 → clipped

    // Asymmetry: positive side (amplify more)
    processor.setBias(0.0f, true);
    processor.setAsymmetry(1.0f, true);
    EXPECT_FLOAT_EQ(processor.processSample(0, 0.5f), 1.0f); // 0.5 * (1 + 1) = 1 → clipped

    // Asymmetry: negative side (attenuate more)
    processor.setAsymmetry(1.0f, true);
    EXPECT_FLOAT_EQ(processor.processSample(0, -0.5f), 0.0f); // -0.5 * (1 - 1) = 0
}

