namespace Gorgon::Resource {

    // Define a mapping from type-check predicate to corresponding save function
    using TypeCheckFn = bool(*)(const void*);
    using SaveHandlerFn = void(*)(Writer&, const Graphics::RectangularAnimationProvider&);

    constexpr auto MakeSaveTable() {
        return std::array<std::pair<TypeCheckFn, SaveHandlerFn>, 8>{{
            { [](const void* p) { return dynamic_cast<const Graphics::Bitmap*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { Image::SaveThis(w, static_cast<const Graphics::Bitmap&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::BitmapAnimationProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { Animation::SaveThis(w, static_cast<const Graphics::BitmapAnimationProvider&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::ILineProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { Line::SaveThis(w, static_cast<const Graphics::ILineProvider&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::IRectangleProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { Rectangle::SaveThis(w, static_cast<const Graphics::IRectangleProvider&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::IMaskedObjectProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { MaskedObject::SaveThis(w, static_cast<const Graphics::IMaskedObjectProvider&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::ITintedObjectProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { TintedObject::SaveThis(w, static_cast<const Graphics::ITintedObjectProvider&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::IScalableObjectProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { ScalableObject::SaveThis(w, static_cast<const Graphics::IScalableObjectProvider&>(obj)); } },

            { [](const void* p) { return dynamic_cast<const Graphics::IStackedObjectProvider*>(static_cast<const Graphics::RectangularAnimationProvider*>(p)); },
              [](Writer& w, const Graphics::RectangularAnimationProvider& obj) { StackedObject::SaveThis(w, static_cast<const Graphics::IStackedObjectProvider&>(obj)); } }
        }};
    }

    void Initialize() {
        DataItem::InitializeLoaders();
    }

    void SaveAnimation(Writer &writer, const Graphics::RectangularAnimationProvider &object) {
        static const auto saveTable = MakeSaveTable();

        const void* basePtr = &object;
        bool found = false;

        for (const auto& [checker, saver] : saveTable) {
            if (checker(basePtr)) {
                saver(writer, object);
                found = true;
                break;
            }
        }

        if (!found) {
            throw std::runtime_error("Cannot save animation: Unsupported animation type.");
        }
    }

    void SaveAnimation(Writer &writer, const Graphics::RectangularAnimationProvider *object) {
        if (!object) {
            Null::SaveThis(writer);
        } else {
            SaveAnimation(writer, *object);
        }
    }

}

#include "llvm/Support/circular_raw_ostream.h"
#include <cstring>
using namespace llvm;

void circular_raw_ostream::write_impl(const char *Ptr, size_t Size) {
  if (BufferSize == 0) {
    TheStream->write(Ptr, Size);
    return;
  }

  // Handle buffering with wrap-around logic
  while (Size > 0) {
    size_t remaining = BufferSize - static_cast<size_t>(Cur - BufferArray);
    size_t to_copy = (Size < remaining) ? Size : remaining;

    std::memcpy(Cur, Ptr, to_copy);
    Cur += to_copy;
    Ptr += to_copy;
    Size -= to_copy;

    if (Cur == BufferArray + BufferSize) {
      Cur = BufferArray;
      Filled = true;
    }
  }
}

void circular_raw_ostream::flushBufferWithBanner() {
  if (BufferSize != 0) {
    TheStream->write(Banner, std::strlen(Banner));
    flushBuffer();
  }
}

#include "hook_wrapper.h"
#include <format>
#include <string>
#include "instruction_length.h"
#include "memory.h"

#pragma comment(lib, "Ws2_32.lib")
#pragma comment(lib, "psapi.lib")

// Writes an absolute jump instruction (E9 rel32) at the specified address
static void install_relative_branch(uintptr_t target_addr, void* write_location, size_t branch_len) {
    uint8_t* dst = static_cast<uint8_t*>(write_location);
    *dst = 0xE9; // JMP opcode
    int32_t offset = static_cast<int32_t>(target_addr - (reinterpret_cast<uintptr_t>(dst) + 5));
    *reinterpret_cast<int32_t*>(dst + 1) = offset;

    DWORD protection;
    VirtualProtect(dst, branch_len, PAGE_EXECUTE_READWRITE, &protection);
    FlushInstructionCache(GetCurrentProcess(), dst, branch_len);
}

// Adjusts relative offsets in CALL/JMP instructions within the trampoline
void hook::patch_trampoline_offsets() {
    size_t idx = 0;
    uint8_t* code_stream = reinterpret_cast<uint8_t*>(trampoline);

    while (idx < orig_byte_count) {
        if (code_stream[idx] == 0xE8 || code_stream[idx] == 0xE9) {
            if (idx + 5 > orig_byte_count) {
                fatal_error(); // Malformed instruction sequence
            }

            int32_t* rel_ptr = reinterpret_cast<int32_t*>(code_stream + idx + 1);
            *rel_ptr += static_cast<int32_t>(patch_address - trampoline);
        }

        idx += Zeal::InstructionLength(code_stream + idx);
    }
}

// Reports critical failure during patching with diagnostic info
void hook::fatal_error() {
    std::string err_msg = "Critical Zeal hook wrapper error: " + std::format("0x{:x}", patch_address);
    MessageBoxA(nullptr, err_msg.c_str(), "Zeal Fatal Error", MB_OK | MB_ICONERROR | MB_TOPMOST);
    throw std::runtime_error("Hook patching failed");
}

// Main hooking routine: redirects execution to replacement function
void hook::detour() {
    // Determine minimum number of bytes needed for full instruction alignment
    size_t total_bytes_needed = 0;
    unsigned char const* base = reinterpret_cast<unsigned char const*>(patch_address);

    do {
        total_bytes_needed += Zeal::InstructionLength(base + total_bytes_needed);
    } while (total_bytes_needed < 5);

    orig_byte_count = total_bytes_needed;

    if (orig_byte_count > sizeof(original_bytes)) {
        fatal_error();
        return;
    }

    // Backup original instructions
    memcpy(original_bytes, reinterpret_cast<void const*>(patch_address), orig_byte_count);

    // Prepare trampoline memory region
    DWORD old_prot;
    size_t tramp_size = orig_byte_count + 5;
    VirtualProtect(trampoline_bytes, tramp_size, PAGE_EXECUTE_READWRITE, &old_prot);

    // Copy original code into trampoline and fix internal jumps
    memcpy(trampoline_bytes, original_bytes, orig_byte_count);
    patch_trampoline_offsets();

    // Append unconditional jump back to original code after copied bytes
    uintptr_t tramp_jump_loc = reinterpret_cast<uintptr_t>(trampoline_bytes) + orig_byte_count;
    uintptr_t next_orig_instr = patch_address + orig_byte_count;
    int32_t back_offset = static_cast<int32_t>(next_orig_instr - (tramp_jump_loc + 5));
    install_relative_branch(next_orig_instr, reinterpret_cast<void*>(tramp_jump_loc), 5);

    // Patch original location with jump to detour
    VirtualProtect(reinterpret_cast<void*>(patch_address), orig_byte_count, PAGE_EXECUTE_READWRITE, &old_prot);

    uintptr_t detour_entry = replacement_callee_addr;
    int32_t hook_offset = static_cast<int32_t>(detour_entry - (patch_address + 5));
    *reinterpret_cast<uint8_t*>(patch_address) = 0xE9;
    *reinterpret_cast<int32_t*>(patch_address + 1) = hook_offset;

    // Fill remaining space with NOPs if more than 5 bytes were overwritten
    if (orig_byte_count > 5) {
        memset(reinterpret_cast<void*>(patch_address + 5), 0x90, orig_byte_count - 5);
    }

    VirtualProtect(reinterpret_cast<void*>(patch_address), orig_byte_count, old_prot, &old_prot);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<void*>(patch_address), orig_byte_count);
}

// Specialized hooking for CALL instructions only
void hook::replace_call() {
    DWORD protect;
    VirtualProtect(reinterpret_cast<void*>(patch_address), 5, PAGE_EXECUTE_READWRITE, &protect);

    if (*reinterpret_cast<uint8_t*>(patch_address) != 0xE8 && *reinterpret_cast<uint8_t*>(patch_address) != 0xE9) {
        fatal_error();
    }

    // Build trampoline pointing to original call target
    uintptr_t original_target = mem::instruction_to_absolute_address(patch_address);
    install_relative_branch(original_target, trampoline, 5);

    // Save original bytes and prepare for redirection
    orig_byte_count = 5;
    memcpy(original_bytes, reinterpret_cast<void*>(patch_address), orig_byte_count);

    // Redirect to new callee
    int32_t new_rel = static_cast<int32_t>(replacement_callee_addr - (patch_address + 5));
    *reinterpret_cast<int32_t*>(patch_address + 1) = new_rel;

    VirtualProtect(reinterpret_cast<void*>(patch_address), 5, protect, &protect);
    FlushInstructionCache(GetCurrentProcess(), reinterpret_cast<void*>(patch_address), 5);
}

// Hook vtable entry by replacing pointer with detour address
void hook::replace_vtable() {
    // Trampoline points to original vtable target
    int32_t original_target = *reinterpret_cast<int32_t*>(patch_address);
    install_relative_branch(static_cast<uintptr_t>(original_target), trampoline, 5);

    // Store original pointer for restore
    orig_byte_count = 4;
    memcpy(original_bytes, &patch_address, orig_byte_count);

    // Replace vtable slot with detour address
    mem::write<int>(patch_address, replacement_callee_addr);
}

// Destructor restores original bytes at hooked site
hook::~hook() {
    mem::copy(patch_address, original_bytes, orig_byte_count);
}

#include <vector>
#include <string>

std::vector<int> search(std::string &pat, std::string &txt) {
    std::vector<int> result;

    // Handle edge cases
    if (pat.empty() || txt.empty() || pat.length() > txt.length()) {
        return result;
    }

    int pattern_len = pat.length();
    int text_len = txt.length();

    // Check each possible starting position in the text
    for (int start_pos = 0; start_pos <= text_len - pattern_len; ++start_pos) {
        bool match_found = true;

        // Compare pattern with substring starting at current position
        for (int char_idx = 0; char_idx < pattern_len; ++char_idx) {
            if (txt[start_pos + char_idx] != pat[char_idx]) {
                match_found = false;
                break;
            }
        }

        if (match_found) {
            result.push_back(start_pos);
        }
    }

    return result;
}

