// Perform a query and return the winner's ID
int performQuery(const std::vector<int>& participants) {
    std::cout << "?";
    for (int id : participants) {
        std::cout << " " << id;
    }
    std::cout << std::endl;

    int result;
    std::cin >> result;

    if (result == -1) {
        std::exit(0); // Terminate on error from interactor
    }

    return result;
}

void processTestCase() {
    int n;
    std::cin >> n;

    // Initialize list with all possible IDs: 1 to n*n
    std::list<int> availableIds;
    for (int i = 1; i <= n * n; ++i) {
        availableIds.push_back(i);
    }

    std::vector<int> sortedResult;
    int neededCount = n * n - n + 1;

    // Determine top 'neededCount' fastest elements
    for (int step = 0; step < neededCount; ++step) {
        std::list<int> currentCandidates = availableIds;

        // Reduce candidates down to one using races of size n
        while (currentCandidates.size() > 1) {
            std::vector<int> raceParticipants;
            auto iter = currentCandidates.begin();

            // Gather up to n participants for this race
            for (int count = 0; count < n && iter != currentCandidates.end(); ++count, ++iter) {
                raceParticipants.push_back(*iter);
            }

            int raceWinner = performQuery(raceParticipants);

            // Remove all losers (everyone except the winner) from candidates
            auto candIter = currentCandidates.begin();
            while (candIter != currentCandidates.end()) {
                bool eliminated = false;

                // Check if this candidate was in the race and didn't win
                if (*candIter != raceWinner) {
                    for (int p : raceParticipants) {
                        if (*candIter == p) {
                            eliminated = true;
                            break;
                        }
                    }
                }

                if (eliminated) {
                    candIter = currentCandidates.erase(candIter);
                } else {
                    ++candIter;
                }
            }
        }

        // The last remaining candidate is the next fastest
        int nextFastest = currentCandidates.front();
        sortedResult.push_back(nextFastest);

        // Remove this element from the full set of available IDs
        availableIds.remove(nextFastest);
    }

    // Output final sorted sequence
    std::cout << "!";
    for (size_t idx = 0; idx < sortedResult.size(); ++idx) {
        std::cout << " " << sortedResult[idx];
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCases;
    std::cin >> testCases;

    while (testCases--) {
        processTestCase();
    }

    return 0;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxFrequencyElements(std::vector<int>& nums) {
        // First pass: count frequencies of all elements
        int frequencyCount[101] = {0};
        for (int element : nums) {
            frequencyCount[element]++;
        }

        // Find the maximum frequency value
        int highestFrequency = 0;
        for (int i = 1; i <= 100; ++i) {
            highestFrequency = std::max(highestFrequency, frequencyCount[i]);
        }

        // Second pass: count how many elements have the maximum frequency
        int countOfMaxFreqElements = 0;
        for (int i = 1; i <= 100; ++i) {
            if (frequencyCount[i] == highestFrequency) {
                countOfMaxFreqElements++;
            }
        }

        // Return total occurrences of elements with maximum frequency
        return countOfMaxFreqElements * highestFrequency;
    }
};

