// Replicates ABC class from original — same interface, renamed members
struct DataHolder {
    DataHolder() : stored_value_(0) {}
    explicit DataHolder(int val) : stored_value_(val) {}

    int get() const { return stored_value_; }
    void set(int v) { stored_value_ = v; }

    void actionA() {
        std::cout << "executing actionA" << std::endl;
    }

    void actionB(int x) {
        std::cout << "executing actionB" << std::endl;
    }

private:
    int stored_value_;
};

// Custom interop type-checking for sol2 ↔ kaguya
template <typename U, typename FuncHandler>
inline bool lua_interop_verify(sol::types<U>, lua_State* L,
    int pos, sol::type /*unused*/, FuncHandler&& /*unused*/,
    sol::stack::record& tracker) {

    tracker.use(1);
    int abs_idx = lua_absindex(L, pos);

    // Use kaguya's internal type verification
    bool match = kaguya::detail::object_wrapper_type_check(L, abs_idx);
    return match;
}

// Retrieve wrapped object pointer via interop
template <typename U>
inline std::pair<bool, U*> lua_interop_fetch(sol::types<U>,
    lua_State* L, int pos, void* /*raw_ptr*/, sol::stack::record& tracker) {

    int abs_idx = lua_absindex(L, pos);

    if (!kaguya::detail::object_wrapper_type_check(L, abs_idx)) {
        return { false, nullptr };
    }

    tracker.use(1);
    kaguya::ObjectWrapperBase* wrapper_base = kaguya::object_wrapper(L, abs_idx);
    return { true, static_cast<U*>(wrapper_base->get()) };
}

// Function object versions of the lambdas used in original
struct SingleArgHandler {
    void operator()(DataHolder& obj) const {
        std::cout << "invoking single-arg handler on DataHolder { "
                  << obj.get() << " }" << std::endl;
        SOL_ASSERT(obj.get() == 24);
    }
};

struct DualArgHandler {
    void operator()(DataHolder& obj, int extra) const {
        std::cout << "invoking dual-arg handler on DataHolder { "
                  << obj.get() << " } with integer " << extra << std::endl;
        SOL_ASSERT(obj.get() == 24);
        SOL_ASSERT(extra == 5);
    }
};

// Register sol2 bindings into given lua_State*
void setup_sol_bindings(lua_State* L) {
    sol::state_view lua(L);

    // Bind overloaded function 'process'
    lua["process"] = sol::overload(
        SingleArgHandler{},
        DualArgHandler{}
    );
}

// Verify state after execution
void validate_result(lua_State* L) {
    sol::state_view lua(L);
    DataHolder& ref = lua["instance"];
    (void)ref;
    SOL_ASSERT(ref.get() == 24);
}

int main(int argc, char* argv[]) {
    std::cout << "=== interop demo (kaguya + sol2) ===" << std::endl;
    std::cout << "(adapted from satoren/kaguya README)" << std::endl;

    kaguya::State vm;
    vm["DataHolder"].setClass(
        kaguya::UserdataMetatable<DataHolder>()
            .setConstructors<DataHolder(), DataHolder(int)>()
            .addFunction("retrieve", &DataHolder::get)
            .addFunction("assign", &DataHolder::set)
            .addOverloadedFunctions("run",
                &DataHolder::actionA, &DataHolder::actionB)
            .addStaticFunction("static_test",
                [](DataHolder*, int) { return 42; }));

    setup_sol_bindings(vm.state());

    // Simulate Lua script execution directly in C++
    // Original: obj = ABC.new(24); f(obj); f(obj, 5);
    vm.dostring(R"(instance = DataHolder.new(24))");
    vm.dostring(R"(process(instance))");
    vm.dostring(R"(process(instance, 5))");

    // Validate results
    validate_result(vm.state());

    return 0;
}

