// Recursive function to solve Tower of Hanoi using different parameter names and structure
void solveHanoi(int disks, char startRod, char tempRod, char endRod) {
    // Base case: single disk movement
    if (disks == 1) {
        std::cout << "Move disk 1 from " << startRod << " to " << endRod << std::endl;
        return;
    }

    // Recursively move top (disks-1) disks to temporary rod
    solveHanoi(disks - 1, startRod, endRod, tempRod);

    // Move the largest disk to destination
    std::cout << "Move disk " << disks << " from " << startRod << " to " << endRod << std::endl;

    // Move the (disks-1) disks from temporary rod to destination
    solveHanoi(disks - 1, tempRod, startRod, endRod);
}

int main() {
    int numberOfDisks;

    // Input number of disks
    std::cout << "Enter the number of disks: ";
    std::cin >> numberOfDisks;

    // Display solution sequence
    std::cout << "The sequence of moves to solve the Tower of Hanoi for " 
              << numberOfDisks << " disks is:" << std::endl;

    // Solve the puzzle: rods A, B, C correspond to start, temp, end
    solveHanoi(numberOfDisks, 'A', 'B', 'C');

    return 0;
}

