#include <engLib/eng.h>
namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has undergone modifications by
///		comparing metadata such as timestamps, file attributes, and size.
///		Any discrepancies trigger an update via entry.markChanged<> and
///		subsequent field updates.
///	@param[inout] targetEntry
///		The entry whose state is to be verified and updated if needed
///	@returns
///		Error code indicating success or failure
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &targetEntry) noexcept {
    WIN32_FIND_DATAW fileInfo;
    Error errCode;

    // Acquire OS-specific path for the URL
    Text osPath;
    if (errCode = Url::osPath(targetEntry.url(), osPath)) return errCode;

    // Use FindFirstFileW to retrieve detailed file info, including reparse points
    HANDLE hFind = FindFirstFileW(osPath.c_str(), &fileInfo);
    if (hFind == INVALID_HANDLE_VALUE) {
        DWORD lastErr = GetLastError();
        return APERR(lastErr, _location,
                     "Failed to retrieve file status information");
    }
    FindClose(hFind);

    // Assume no change unless proven otherwise
    targetEntry.changed(false);

    // Compare creation time
    auto newCreateTime = _tr<time::SystemStamp>(fileInfo.ftCreationTime);
    if (targetEntry.createTime.get() != newCreateTime) {
        targetEntry.markChanged(LogLevel, "Creation timestamp mismatch");
        targetEntry.createTime(newCreateTime);
    }

    // Compare last modification time
    auto newModifyTime = _tr<time::SystemStamp>(fileInfo.ftLastWriteTime);
    if (targetEntry.modifyTime.get() != newModifyTime) {
        targetEntry.markChanged(LogLevel, "Modification timestamp mismatch");
        targetEntry.modifyTime(newModifyTime);
    }

    // Update access time only (no change flag)
    auto newAccessTime = _tr<time::SystemStamp>(fileInfo.ftLastAccessTime);
    if (targetEntry.accessTime.get() != newAccessTime) {
        targetEntry.accessTime(newAccessTime);
    }

    // Compare file attributes
    if (targetEntry.attrib() != fileInfo.dwFileAttributes) {
        targetEntry.markChanged(LogLevel, "File attributes altered");
        targetEntry.attrib(fileInfo.dwFileAttributes);
    }

    // Compute full file size from high/low parts
    uint64_t logicalSize =
        (static_cast<uint64_t>(fileInfo.nFileSizeHigh) << 32) |
        static_cast<uint64_t>(fileInfo.nFileSizeLow);
    if (targetEntry.size() != logicalSize) {
        targetEntry.markChanged(LogLevel, "Logical file size differs");
        targetEntry.size(logicalSize);
    }

    // Retrieve physical (on-disk) size
    auto diskSizeResult = file::getSizeOnDisk(osPath, targetEntry.size(),
                                              targetEntry.attrib());
    uint64_t storeSize;
    if (diskSizeResult.check()) {
        // Fallback to logical size if on-disk size unavailable
        storeSize = targetEntry.size();
    } else {
        storeSize = *diskSizeResult;
    }

    // Compare and update stored size if necessary
    if (targetEntry.storeSize() != storeSize) {
        targetEntry.markChanged(LogLevel, "Physical storage size changed");
        targetEntry.storeSize(storeSize);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

