#include <iostream>
#include <vector>
#include <stack>

// Query function: sends request for slice x and returns count of distinct types
int performQuery(int item) {
    std::cout << "? " << item << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Output function: reports found pair
void reportPair(int first, int second) {
    std::cout << "! " << first << " " << second << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Track which items have been paired
    std::vector<bool> isPaired(2 * n + 1, false);

    // Stack to hold currently unpaired items
    std::stack<int> unpairedItems;

    int currentDistinctCount = 0;
    int totalPairsFound = 0;

    for (int position = 1; position <= 2 * n; ++position) {
        if (isPaired[position]) {
            continue;
        }

        // Try adding current item to the device
        int response = performQuery(position);

        if (response > currentDistinctCount) {
            // New unique type found - add to unpaired stack
            unpairedItems.push(position);
            currentDistinctCount = response;
        } else {
            // Response same as before - mate must be in unpaired stack

            int baselineCount = currentDistinctCount;
            std::vector<int> tempStorage;

            while (!unpairedItems.empty()) {
                int candidate = unpairedItems.top();
                unpairedItems.pop();

                // Test if removing candidate changes the distinct count
                int testResponse = performQuery(candidate);

                // If removing candidate doesn't decrease distinct count,
                // then candidate was the mate of our current item
                if (testResponse == baselineCount) {
                    // Found the pair!
                    reportPair(position, candidate);
                    totalPairsFound++;
                    isPaired[position] = true;
                    isPaired[candidate] = true;

                    // Remove current item from device to reset state
                    currentDistinctCount = performQuery(position);

                    // Restore other candidates back to device
                    for (int restored : tempStorage) {
                        currentDistinctCount = performQuery(restored);
                        unpairedItems.push(restored);
                    }

                    break;
                } else {
                    // Not the mate, save for later restoration
                    tempStorage.push_back(candidate);
                }
            }
        }

        if (totalPairsFound == n) {
            break;
        }
    }

    return 0;
}

