class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int n = digits.size();
        vector<int> result = digits;

        // Add 1 to the last digit
        result[n-1] += 1;

        // Process carry from right to left
        for (int i = n - 1; i > 0; --i) {
            if (result[i] >= 10) {
                result[i] -= 10;
                result[i-1] += 1;
            } else {
                break; // No more carry, exit early
            }
        }

        // Handle carry at the first digit
        if (result[0] >= 10) {
            result[0] -= 10;
            result.insert(result.begin(), 1);
        }

        return result;
    }
};

