    std::cout << data.at("/array"_json_pointer) << '\n';
    std::cout << data.at("/array/1"_json_pointer) << '\n';

    // Modify values via JSON pointers
    data.at("/string"_json_pointer) = "bar";
    std::cout << data["string"] << '\n';

    data.at("/array/1"_json_pointer) = 21;
    std::cout << data["array"] << '\n';

    // Handle various error cases
    try {
        json::reference ref = data.at("/array/01"_json_pointer);
