namespace {
/// NVPTXAssignValidGlobalNames - Ensures global symbols have valid PTX identifiers
class NVPTXAssignValidGlobalNames : public ModulePass {
public:
  static char ID;
  NVPTXAssignValidGlobalNames() : ModulePass(ID) {}

  bool runOnModule(Module &M) override;

  /// Sanitize a symbol name by replacing invalid characters for PTX
  std::string sanitizeSymbol(StringRef original);
};
}

char NVPTXAssignValidGlobalNames::ID = 0;

namespace llvm {
void initializeNVPTXAssignValidGlobalNamesPass(PassRegistry &);
}

INITIALIZE_PASS(NVPTXAssignValidGlobalNames, "nvptx-assign-valid-global-names",
                "Assign valid PTX names to globals", false, false)

bool NVPTXAssignValidGlobalNames::runOnModule(Module &M) {
  // Process all global variables with local linkage
  for (auto &GV : M.globals()) {
    if (GV.hasLocalLinkage()) {
      GV.setName(sanitizeSymbol(GV.getName()));
    }
  }

  // Process all functions with local linkage
  for (auto &F : M.functions()) {
    if (F.hasLocalLinkage()) {
      F.setName(sanitizeSymbol(F.getName()));
    }
  }

  return true;
}

std::string NVPTXAssignValidGlobalNames::sanitizeSymbol(StringRef input) {
  std::string result;
  raw_string_ostream stream(result);

  for (unsigned char ch : input) {
    switch (ch) {
      case '.':
      case '@':
      case '<':
      case '>':
        stream << "_$_";
        break;
      default:
        stream << ch;
    }
  }

  return stream.str();
}

ModulePass *llvm::createNVPTXAssignValidGlobalNamesPass() {
  return new NVPTXAssignValidGlobalNames();
}

#include <iostream>
