#include <vector>
#include <algorithm>

// Converts a character from the set {'A'-'Z', '0'-'9'} to an integer in range [0, 35]
inline int char_to_index(char c) {
    if (c >= 'A' && c <= 'Z') {
        return static_cast<int>(c - 'A');
    }
    return static_cast<int>(c - '0') + 26;
}

// Constructs a common subsequence by scanning string 'a' and greedily matching characters in string 'b'
std::string build_common_subseq(const std::string& src, const std::string& target) {
    // Build lookup table: for each character, store all its positions in 'target'
    std::vector<std::vector<int>> char_positions(36);
    for (int idx = 0; idx < static_cast<int>(target.size()); ++idx) {
        char_positions[char_to_index(target[idx])].push_back(idx);
    }

    std::string result;
    result.reserve(std::min(src.size(), target.size()));

    int last_matched_idx = -1;
    std::vector<int> next_pos(36, 0); // tracks current position in each character's list

    for (char ch : src) {
        int id = char_to_index(ch);

        // Advance pointer for this character until we find a position > last_matched_idx
        while (next_pos[id] < static_cast<int>(char_positions[id].size()) &&
               char_positions[id][next_pos[id]] <= last_matched_idx) {
            ++next_pos[id];
        }

        // If found a valid match, include it in result
        if (next_pos[id] < static_cast<int>(char_positions[id].size())) {
            result.push_back(ch);
            last_matched_idx = char_positions[id][next_pos[id]];
            ++next_pos[id]; // advance for next occurrence of same char
        }
    }

    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string str_a, str_b;
    std::cin >> str_a >> str_b;

    // Generate two candidate subsequences by trying both directions
    std::string candidate1 = build_common_subseq(str_a, str_b);
    std::string candidate2 = build_common_subseq(str_b, str_a);

    // Choose the longer one (or first if equal length)
    if (candidate1.length() >= candidate2.length()) {
        std::cout << candidate1 << '\n';
    } else {
        std::cout << candidate2 << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

class SearchRotatedArray {
public:
    // Linear scan approach to check for target presence
    bool linearCheck(vector<int>& arr, int val) {
        // Early checks for first and last elements
        if (arr.empty()) return false;
        if (arr[0] == val || arr[arr.size()-1] == val) 
            return true;

        // Scan remaining elements
        for (int idx = 1; idx < (int)arr.size()-1; ++idx) {
            if (arr[idx] == val) 
                return true;
        }
        return false;
    }

    // Optimized binary search for rotated sorted array with duplicates
    bool efficientSearch(vector<int>& arr, int val) {
        if (arr.empty()) return false;

        // Check boundary elements first
        if (arr[0] == val || arr.back() == val) 
            return true;

        int left = 0;
        int right = arr.size() - 1;

        while (left <= right) {
            int middle = left + (right - left) / 2;

            // Found the target
            if (arr[middle] == val) 
                return true;

            // Handle duplicates at boundaries and middle
            if (arr[left] == arr[middle] && arr[right] == arr[middle]) {
                ++left;
                --right;
            }
            // Left half is sorted
            else if (arr[left] <= arr[middle]) {
                if (arr[left] <= val && val < arr[middle]) {
                    right = middle - 1;
                } else {
                    left = middle + 1;
                }
            }
            // Right half is sorted
            else {
                if (arr[middle] < val && val <= arr[right]) {
                    left = middle + 1;
                } else {
                    right = middle - 1;
                }
            }
        }
        return false;
    }
};

int main() {
    vector<int> data = {2,5,6,0,0,1,2};
    int query1 = 3;
    int query2 = 0;

    SearchRotatedArray solver;

    bool result1 = solver.efficientSearch(data, query1);
    cout << result1 << endl; // Expected: 0 (false)

    bool result2 = solver.efficientSearch(data, query2);
    cout << result2 << endl; // Expected: 1 (true)

    return 0;
}

#include "server.hpp"
#include <boost/bind.hpp>
#include <signal.h>

namespace http {
namespace server {

// Alternative constructor implementation: initializes members and sets up signal handling & acceptor
server::server(const std::string& addr_str, const std::string& port_str,
    const std::string& doc_root)
  : io_context_(),
    signals_(io_context_),
    acceptor_(io_context_),
    connection_manager_(),
    new_connection_(),
    request_handler_(doc_root)
{
  // Handle termination signals — same safety applies as before
  signals_.add(SIGINT);
  signals_.add(SIGTERM);
#if defined(SIGQUIT)
  signals_.add(SIGQUIT);
#endif

  // Use lambda instead of boost::bind for clarity (equivalent semantics)
  signals_.async_wait([this](const asio::error_code& /*ec*/, int signal_number) {
    handle_stop_signal(signal_number);
  });

  // Resolve endpoint and configure acceptor
  asio::ip::tcp::resolver resolver(io_context_);
  auto endpoints = resolver.resolve(addr_str, port_str);
  auto ep = *endpoints.begin();

  acceptor_.open(ep.protocol());
  acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  acceptor_.bind(ep);
  acceptor_.listen();

  initiate_accept();
}

void server::run()
{
  // Run event loop until stopped
  io_context_.run();
}

// Start waiting for a new incoming connection
void server::initiate_accept()
{
  new_connection_.reset(new connection(io_context_,
        connection_manager_, request_handler_));
  acceptor_.async_accept(new_connection_->socket(),
      [this](const asio::error_code& ec) {
        this->on_new_connection(ec);
      });
}

// Called when an incoming connection is accepted
void server::on_new_connection(const asio::error_code& err)
{
  if (!acceptor_.is_open()) {
    return;
  }

  if (!err) {
    connection_manager_.start(new_connection_);
  }

  // Continue accepting more connections
  initiate_accept();
}

// Signal handler: gracefully shuts down the server
void server::handle_stop_signal(int sig)
{
  (void)sig; // unused parameter, suppress warning
  stop_server_gracefully();
}

void server::stop_server_gracefully()
{
  // Close acceptor to prevent further accepts
  acceptor_.close();
  // Terminate all active connections
  connection_manager_.stop_all();
}

} // namespace server
} // namespace http

