#include "Optimization/ModuleOptimizer.h"
#include <stdexcept>
#include <llvm/Analysis/CGSCCPassManager.h>
#include <llvm/Analysis/LoopAnalysisManager.h>
#include <llvm/IR/Module.h>
#include <llvm/IR/PassManager.h>
#include <llvm/Passes/PassBuilder.h>

namespace llvm_utils {
using namespace llvm;

/// @brief Apply LLVM's standard optimization pipeline to the provided module.
///
/// This function executes a sequence of transformation passes determined by
/// the selected optimization level (O0-O3). It sets up analysis managers for
/// different scopes (module, function, loop, etc.) and registers them with
/// the PassBuilder to ensure proper analysis caching and invalidation.
///
/// @param modulePtr Pointer to the LLVM module that will be optimized (cannot be null)
/// @param level     Desired optimization level:
///   - OptimizationLevel::O0: Disable optimizations (for debugging)
///   - OptimizationLevel::O1: Minimal optimizations
///   - OptimizationLevel::O2: Balanced optimizations (typical release setting)
///   - OptimizationLevel::O3: Maximum optimizations (may expand code size)
///
/// @return PreservedAnalyses indicating which analyses remain valid post-optimization
///
/// @throws std::invalid_argument if modulePtr is nullptr
auto optimiseModule(Module *modulePtr, OptimizationLevel level)
    -> PreservedAnalyses {
  if (!modulePtr)
    throw std::invalid_argument("Null pointer passed as module argument!");

  // Initialize analysis managers for different scopes
  LoopAnalysisManager loopAM;
  FunctionAnalysisManager funcAM;
  CGSCCAnalysisManager cgsccAM;
  ModuleAnalysisManager moduleAM;

  // Set up pass builder and register all required analyses
  PassBuilder pb;
  pb.registerModuleAnalyses(moduleAM);
  pb.registerCGSCCAnalyses(cgsccAM);
  pb.registerFunctionAnalyses(funcAM);
  pb.registerLoopAnalyses(loopAM);
  pb.crossRegisterProxies(loopAM, funcAM, cgsccAM, moduleAM);

  // Construct and execute the default per-module optimization pipeline
  return pb.buildPerModuleDefaultPipeline(level).run(*modulePtr, moduleAM);
}
} // namespace llvm_utils

#include "infiniccl_test.hpp"
#include <iostream>
#include <string>
#include <vector>

struct ParsedArgs {
    infiniDevice_t device_type;
};

void printUsage() {
    std::cout << "Usage:\n\n";
    std::cout << "infiniccl-test --<device>\n\n";
    std::cout << "  --<device>\n";
    std::cout << "    Specify the device type: --(nvidia|cambricon|ascend|metax|moore|iluvatar|qy|kunlun|hygon|ali).\n\n";
    std::cout << "The program will run tests on all visible devices of the specified device type.\n"
              << "Use environment variables such as CUDA_VISIBLE_DEVICES to limit visible device IDs.\n";
    std::exit(-1);
}

ParsedArgs parseArgs(int argc, char *argv[]) {
    // Validate argument count and help flags
    if (argc != 2) {
        printUsage();
    }

    std::string input = argv[1];
    if (input == "--help" || input == "-h") {
        printUsage();
    }

    ParsedArgs result{};

    // Define mapping from string flag to device enum
    const std::vector<std::pair<std::string, infiniDevice_t>> deviceMap = {
        {"--nvidia",   INFINI_DEVICE_NVIDIA},
        {"--cambricon",INFINI_DEVICE_CAMBRICON},
        {"--ascend",   INFINI_DEVICE_ASCEND},
        {"--metax",    INFINI_DEVICE_METAX},
        {"--moore",    INFINI_DEVICE_MOORE},
        {"--iluvatar", INFINI_DEVICE_ILUVATAR},
        {"--qy",       INFINI_DEVICE_QY},
        {"--kunlun",   INFINI_DEVICE_KUNLUN},
        {"--hygon",    INFINI_DEVICE_HYGON},
        {"--ali",      INFINI_DEVICE_ALI}
    };

    bool matched = false;
    for (const auto& [flag, dev] : deviceMap) {
        if (input == flag) {
            result.device_type = dev;
            matched = true;
            break;
        }
    }

    if (!matched) {
        printUsage();
    }

    return result;
}

int main(int argc, char *argv[]) {
    ParsedArgs args = parseArgs(argc, argv);

    int deviceCount = 0;
    infinirtInit();

    if (infinirtGetDeviceCount(args.device_type, &deviceCount) != INFINI_STATUS_SUCCESS) {
        std::cerr << "Error: Failed to retrieve device count." << std::endl;
        return -1;
    }

    if (deviceCount == 0) {
        std::cout << "No devices found. Skipping tests." << std::endl;
        return 0;
    } else {
        std::cout << "Detected " << deviceCount << " device(s). Proceeding with tests..." << std::endl;
    }

    int errors = testAllReduce(args.device_type, deviceCount);
    return errors;
}

#include <iostream>

// Base abstract interface A
struct InterfaceA {
  virtual void performActionA() = 0;
};

// Base abstract interface B
struct InterfaceB {
  virtual void performActionB() = 0;
};

// Concrete implementation providing both interfaces
struct DualImplementation : InterfaceA, InterfaceB {
  void performActionA() override {}
  void performActionB() override {}
};

// Base class with default behavior
struct BaseWithBehavior {
  virtual void executeDefault() {}
};

// Full implementation inheriting from both dual and base
struct CompleteImplementation : BaseWithBehavior, DualImplementation {
  void performActionA() override {}
  void performActionB() override {}
  void executeDefault() override {}
};

// Function accepting InterfaceA reference
void invokeActionA(InterfaceA& ia) {
  ia.performActionA();
}

// Function accepting InterfaceB reference
void invokeActionB(InterfaceB& ib) {
  ib.performActionB();
}

// Function accepting BaseWithBehavior reference
void invokeDefault(BaseWithBehavior& bc) {
  bc.executeDefault();
}

int main() {
  CompleteImplementation fullObj;
  invokeActionA(fullObj);
  invokeActionB(fullObj);
  invokeDefault(fullObj);
  return 0;
}

