int main()
{
    // Initialize the visualization window
    mplot::Visual scene{1024, 768, "Made with mplot::GraphVisual"};

    // Instantiate GraphVisual at origin; bind to scene
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});
    scene.bindmodel(graph);

    // Prepare x-axis data: 11 points from 0 to 10 inclusive
    sm::vvec<double> abscissas;
    abscissas.linspace(0.0, 10.0, 11);

    // Define y-values manually
    sm::vvec<double> ordinates = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure primary line style
    mplot::DatasetStyle primaryStyle{mplot::stylepolicy::lines};
    primaryStyle.linecolour = mplot::colour::crimson;

    // Set y-axis range explicitly
    graph->setlimits_y(0.0, 10.0);

    // Feed data into the graph
    graph->setdata(abscissas, ordinates, primaryStyle);

    // Secondary style for horizontal reference line at y=7
    mplot::DatasetStyle refLineStyle{mplot::stylepolicy::lines};
    refLineStyle.linecolour = mplot::colour::grey68;
    refLineStyle.linewidth = primaryStyle.linewidth * 0.6f;

    // Compute crossing points of the curve with y=7 and draw vertical markers
    sm::vvec<double> crossings = graph->add_y_crossing_lines(abscissas, ordinates, 7.0, primaryStyle, refLineStyle);

    // Format crossing positions as human-readable string
    std::ostringstream oss;
    const size_t count = crossings.size();
    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            if (idx == 0 || idx == count - 1)
                oss << "";
            else
                oss << ", ";
            if (idx == count - 1)
                oss << " and ";
            oss << std::format("{:.2f}", crossings[idx]);
        }
    } else {
        oss << "[no values]";
    }

    // Add annotation label in bottom-left corner
    graph->addLabel(
        std::format("y=7 at x = {}", oss.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures{0.03f}
    );

    // Finalize geometry generation before adding to scene
    graph->finalize();

    // Transfer ownership of graph to scene
    scene.addVisualModel(std::move(graph));

    // Launch interactive rendering loop
    scene.keepOpen();

    // Memory cleanup handled automatically via RAII
    return 0;
}

