#include "sax.h"
using namespace NConfig;

namespace {
    class TSaxWrapper : public IConfig, public IConfig::IValue {
    public:
        inline TSaxWrapper(const TConfig& cfg)
            : Config_(cfg)
        {
        }

        void DoForEach(IFunc* func) override {
            if (Config_.IsA<TArray>()) {
                const TArray& arr = Config_.Get<TArray>();
                for (size_t idx = 0; idx < arr.size(); ++idx) {
                    TSaxWrapper child(arr[idx]);
                    func->Consume(ToString(idx), &child);
                }
            } else if (Config_.IsA<TDict>()) {
                const TDict& dict = Config_.Get<TDict>();
                for (const auto& entry : dict) {
                    TSaxWrapper child(entry.second);
                    func->Consume(entry.first, &child);
                }
            }
        }

        TString AsString() override {
            if (Config_.IsA<TArray>()) {
                TSaxWrapper firstItem(Config_.Get<TArray>()[0]);
                return firstItem.AsString();
            }
            return Config_.As<TString>();
        }

        bool AsBool() override {
            return Config_.As<bool>();
        }

        IConfig* AsSubConfig() override {
            return this;
        }

        bool IsContainer() const override {
            return Config_.IsA<TArray>() || Config_.IsA<TDict>();
        }

        void DumpJson(IOutputStream& stream) const override {
            Config_.DumpJson(stream);
        }

        void DumpLua(IOutputStream& stream) const override {
            Config_.DumpLua(stream);
        }

    private:
        TConfig Config_;
    };
}

namespace NConfig {
    THolder<IConfig> ConfigParser(IInputStream& in, const TGlobals& globals) {
        return MakeHolder<TSaxWrapper>(TConfig::FromStream(in, globals));
    }
}

