// Helper to avoid code duplication in short-prompt mode
void run_single_inference(
    AutoModel* chat,
    const std::string& prompt,
    const std::vector<std::string>& image_paths,
    int max_tokens,
    bool print_header = true) {

    if (print_header) {
        std::cout << "Prompt: " << prompt << std::endl;
        std::cout << "Response: ";
    } else {
        std::cout << "Response: ";
    }

    chat->start_total_timer();
    lm_uniform_input_t input;
    input.prompt = prompt;
    input.images = image_paths;

    chat_meta_info_t meta;
    std::string result = chat->generate_with_prompt(meta, input, max_tokens, std::cout);
    chat->stop_total_timer();

    std::cout << std::endl << std::endl;
    std::cout << chat->show_profile() << std::endl;
}

int main(int argc, char* argv[]) {
#ifdef _WIN32
    SetConsoleOutputCP(CP_UTF8);
    SetConsoleCP(CP_UTF8);
    SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_LOWEST);
#endif

    // Parse command-line arguments
    arg_utils::po::options_description opts("Allowed options");
    arg_utils::po::variables_map vm;
    opts.add_options()
        ("model,m", arg_utils::po::value<std::string>()->required(), "Model file")
        ("Short,s", arg_utils::po::value<bool>()->default_value(true), "Use short prompt")
        ("Preemption,p", arg_utils::po::value<bool>()->default_value(false), "Enable preemption");

    arg_utils::po::store(arg_utils::po::parse_command_line(argc, argv, opts), vm);
    arg_utils::po::notify(vm);

    std::string model_tag = vm["model"].as<std::string>();
    bool use_short_prompt = vm["Short"].as<bool>();
    bool enable_preemption = vm["Preemption"].as<bool>();

    std::cout << "Model: " << model_tag << std::endl;

    std::string binary_path = utils::get_executable_directory();
    std::string models_root = utils::get_models_directory();
    std::string config_path = binary_path + "/model_list.json";

    model_list model_registry(config_path, models_root);

    header_print("info", "Initializing chat model...");
    std::string model_file = model_registry.get_model_path(model_tag);
    auto [_, info_json] = model_registry.get_model_info(model_tag);

    std::cout << "Model path: " << model_file << std::endl;

    // Initialize device and model
    npu_device_global = xrt::device(0);
    AutoModel* chat = new Qwen2VL(&npu_device_global);

    chat->load_model(model_file, info_json, -1, enable_preemption);
    chat->set_topk(1);
    chat->set_topp(0.8f);
    chat->set_temperature(0.7f);
    chat->set_repetition_penalty(1.01f);
    chat->set_frequency_penalty(1.01f);

    lm_uniform_input_t uniformed_input;

    if (use_short_prompt) {
        uniformed_input.prompt = "What is this?";
        std::vector<std::string> img_paths = {"../../../tb_files/panda.png"};

        // Run three times with same prompt/image
        for (int i = 0; i < 3; ++i) {
            run_single_inference(chat, uniformed_input.prompt, img_paths, 1024, i == 0);
        }
    } else {
        std::ifstream prompt_file("../../../../prompt.txt", std::ios::binary);
        if (!prompt_file.is_open()) {
            std::cerr << "Failed to open prompt file" << std::endl;
            delete chat;
            return 1;
        }

        prompt_file.seekg(0, std::ios::end);
        size_t size = prompt_file.tellg();
        prompt_file.seekg(0, std::ios::beg);

        uniformed_input.prompt.resize(size);
        prompt_file.read(&uniformed_input.prompt[0], static_cast<std::streamsize>(size));
        prompt_file.close();

        std::cout << "Prompt: " << uniformed_input.prompt << std::endl;
        run_single_inference(chat, uniformed_input.prompt, {}, 1024, false);
    }

    // Output history stats
    auto [_, history_ids] = chat->get_history();
    std::cout << "History length: " << history_ids.size() << std::endl;
    std::cout << std::endl;

    delete chat;
    return 0;
}

