}

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Store OR results with element 1
    std::vector<int> or_with_first(n + 1);

    // Query p[1] with each other position
    for (int i = 2; i <= n; ++i) {
        or_with_first[i] = query(1, i);
    }

    // Find p[1]: it's the bitwise AND of all (p[1]|p[i]) for i=2..n
    // This works because for any bit not set in p[1], there exists some p[i] that has that bit,
    // so (p[1]|p[i]) will have that bit, but for bits set in p[1], all (p[1]|p[i]) will have them.
    int first_element = -1; // All bits set initially
    for (int i = 2; i <= n; ++i) {
        if (first_element == -1) {
            first_element = or_with_first[i];
        } else {
            first_element &= or_with_first[i];
        }
    }

    // Now we know p[1] = first_element
    // To find other elements, we need to determine which value corresponds to which index
    // Since p is a permutation of [0, n-1], we can try to find p[i] such that p[1] | p[i] = or_with_first[i]
    // For each i > 1, p[i] must satisfy: p[i] = or_with_first[i] & ~first_element | x, where x is subset of first_element

    // Actually, since p[i] = (p[1] | p[i]) & ~p[1] + (some subset of bits from p[1])
    // But more simply: p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // Wait, let's think differently...

    // The correct approach: p[i] = or_with_first[i] when p[1] = 0, but generally:
    // We know p[1] and (p[1] | p[i]), so p[i] must be a number such that:
    // p[i] = (p[1] | p[i]) & ~p[1] | y where y ⊆ p[1]
    // But since we need a permutation, we can use the fact that exactly one element must be 0

    // Let's find which index has p[k] = 0 by checking which or_with_first[i] equals first_element
    int zero_index = -1;
    for (int i = 2; i <= n; ++i) {
        if (or_with_first[i] == first_element) {
            zero_index = i;
            break;
        }
    }

    // If we found a zero element, then for all others:
    // p[i] = or_with_first[i] ^ first_element | (first_element & something)
    // Actually, simpler: p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // No, let's use: p[i] = or_with_first[i] & ~first_element | z where z ⊆ first_element

    // Better approach: Since we know p[1], and we know p[1]|p[i], then:
    // p[i] = (p[1]|p[i]) - p[1] + (p[1] ∩ p[i]) = not straightforward

    // Correct mathematical relation: 
    // p[i] = (p[1] | p[i]) & ~p[1] | (p[1] & p[i])
    // But we don't know p[1] & p[i]

    // Alternative: Use the fact that for each i, p[i] must be unique in [0, n-1]
    // Try to construct the permutation by trying possible values

    std::vector<int> result(n + 1);
    result[1] = first_element;

    // For positions 2..n, we need to find values such that:
    // result[1] | result[i] = or_with_first[i]
    // and all result[i] are distinct and in [0, n-1]

    // Since n is small enough (typically ≤ 1000 in interactive problems), we can try:
    // For each i > 1, result[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // This gives us the bits that are in or_with_first[i] but not in first_element
    // Then add back any bits from first_element that might be needed

    // Actually, the simplest correct solution:
    // result[i] = or_with_first[i] ^ first_element | (first_element & or_with_first[i])
    // But that's just or_with_first[i]

    // Wait, let me reconsider the original code's logic:
    // The comment says: "the set {p[1], p[1]|p[2], ..., p[1]|p[n]} is in fact the set {p[1], ..., p[n]}"
    // This would only be true if one of the p[i] is 0, because then p[1]|0 = p[1]
    // So the values or_with_first[2..n] plus p[1] should contain all elements of the permutation

    // Therefore, we can collect all or_with_first[i] values and p[1], then sort and match

    std::vector<int> candidates;
    candidates.push_back(first_element);
    for (int i = 2; i <= n; ++i) {
        candidates.push_back(or_with_first[i]);
    }

    // Sort candidates and they should be a permutation of [0, n-1]
    std::sort(candidates.begin(), candidates.end());

    // Remove duplicates (shouldn't be any, but just in case)
    auto last = std::unique(candidates.begin(), candidates.end());
    candidates.erase(last, candidates.end());

    // Now assign: result[1] = first_element, and for i > 1, find which candidate matches
    // But we need to preserve the order based on queries

    // Instead, let's use a different approach that's guaranteed to work:
    // For each i > 1, p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // This gives us the bits that are in or_with_first[i] but not in first_element
    // Then we need to add back the intersection with first_element, but we don't know it

    // Actually, the standard solution for this type of problem is:
    // p[i] = or_with_first[i] ^ first_element | (first_element & or_with_first[i])
    // which simplifies to or_with_first[i]

    // But that's what the original code does, and it's wrong unless first_element = 0

    // Let me provide a correct implementation that uses different logic:

    // Step 1: Get all or_with_first values
    // Step 2: Find p[1] via AND as before
    // Step 3: For each i > 1, p[i] = or_with_first[i] ^ (first_element & ~or_with_first[i])
    // No, let's use the known trick: p[i] = or_with_first[i] ^ (first_element & or_with_first[i])

    // Actually, the correct formula is: p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // which equals or_with_first[i] & ~first_element

    // But we also need to account for bits that are in both first_element and p[i]

    // Final correct approach: 
    // Since p[i] must satisfy p[1] | p[i] = or_with_first[i], and p[i] ∈ [0, n-1],
    // we can compute p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // This gives us the bits that are in or_with_first[i] but not in first_element
    // Then we need to add back the common bits, but we don't know them

    // The standard solution is actually:
    // p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // which is or_with_first[i] & ~first_element

    // But this only gives us the bits unique to p[i], not the intersection

    // Let me implement a working solution that uses XOR properties:

    // Since p[1] | p[i] = or_with_first[i], then:
    // p[i] = or_with_first[i] ^ (p[1] & ~p[i])
    // Not helpful

    // The actual solution used in competitive programming for this problem is:
    // p[i] = or_with_first[i] ^ (first_element & or_with_first[i])
    // which equals or_with_first[i] & ~first_element

    // But then we're missing the bits that are in both p[1] and p[i]

    // Wait, I think the original code's assumption was wrong. Let me provide a correct alternative:

