    // This is equivalent to or_with_first[i] & ~first_element

    // But then how do we get the full p[i]? We need to know which bits from first_element are in p[i]

    // Ah! The key insight: since p is a permutation of [0, n-1], and we know p[1],
    // the set {or_with_first[2], ..., or_with_first[n]} ∪ {p[1]} contains all elements of p
    // So we can create a multiset of expected values [0, n-1] and match

    // Let's implement that:

    std::vector<int> perm(n);
    for (int i = 0; i < n; ++i) {
        perm[i] = i;
    }

    // Collect all known values: p[1] and or_with_first[2..n]
    std::vector<int> known_values;
    known_values.push_back(first_element);
    for (int i = 2; i <= n; ++i) {
