namespace Kernel {

/// @brief Launches a kernel-level task from a given entry point.
/// @details Allocates and initializes a new kernel task context using provided stack frame and identifier.
/// @param entry_point Pointer to the task's initial execution context (stack frame).
/// @param task_id Unique kernel identifier for the new task.
/// @return TRUE if task creation succeeded, FALSE otherwise.
BOOL rtl_create_kernel_task(HAL::StackFramePtr entry_point, const KID task_id) {
  // Validate inputs: reject null task ID or invalid stack frame
  if (!task_id || entry_point == nullptr) return FALSE;

  // Delegate task registration to helper class
  return KernelTaskHelper::Add(entry_point, task_id);
}

/***********************************************************************************/
/// @brief Spawns a user-space process using a specified entry function.
/// @details Sets up necessary infrastructure for user-mode execution, including name validation.
/// @param start_func Function pointer representing the process entry point.
/// @param label Human-readable name assigned to the process.
/// @return Valid process ID on success, kSchedInvalidPID on failure.
/***********************************************************************************/
ProcessID rtl_create_user_process(rtl_start_kind start_func, const Char* label) {
  // Ensure process name is non-null and non-empty
  if (!label || *label == 0) return kSchedInvalidPID;

  // Use singleton scheduler to spawn new user process
  return UserProcessScheduler::The().Spawn(label, 
                                           reinterpret_cast<VoidPtr>(start_func), 
                                           nullptr);
}

}  // namespace Kernel

#include "asio/buffer.hpp"
#include "asio/io_context.hpp"
#include "asio/ip/udp.hpp"
#include <cstdlib>
#include <functional>
#include <iostream>
#include <chrono>

using asio::ip::udp;
using std::placeholders::_1;
using std::placeholders::_2;

// A UDP client that receives data with a timeout mechanism
class udp_receiver
{
public:
  udp_receiver(const udp::endpoint& local_endpoint)
    : socket_(io_context_, local_endpoint)
  {
  }

  // Receives data into the provided buffer, waiting up to 'timeout' duration
  // Returns number of bytes received; sets 'error' accordingly
  std::size_t recv(asio::mutable_buffer buffer,
                   std::chrono::steady_clock::duration limit,
                   std::error_code& ec)
  {
    std::size_t bytes_read = 0;

    // Initiate async receive with bound handler
    socket_.async_receive(asio::buffer(buffer),
        [this, &ec, &bytes_read](const std::error_code& e, std::size_t len) {
          handle_recv(e, len, &ec, &bytes_read);
        });

    // Wait for completion or timeout
    wait_for_completion(limit);

    return bytes_read;
  }

private:
  void wait_for_completion(std::chrono::steady_clock::duration max_wait)
  {
    io_context_.restart();

    // Run until work done or timeout
    auto elapsed = io_context_.run_for(max_wait);

    // If not finished within timeout, cancel and wait again
    if (elapsed == 0)
    {
      socket_.cancel();
      io_context_.run(); // Wait for cancellation to take effect
    }
  }

  static void handle_recv(const std::error_code& err,
                          std::size_t bytes_transferred,
                          std::error_code* target_ec,
                          std::size_t* target_bytes)
  {
    *target_ec = err;
    *target_bytes = bytes_transferred;
  }

private:
  asio::io_context io_context_;
  udp::socket socket_;
};

//----------------------------------------------------------------------

int main(int argc, char* argv[])
{
  try
  {
    using namespace std; // For atoi

    if (argc != 3)
    {
      cerr << "Usage: blocking_udp_client <listen_addr> <listen_port>\n";
      return 1;
    }

    udp::endpoint listen_addr(
        asio::ip::make_address(argv[1]),
        static_cast<unsigned short>(atoi(argv[2])));

    udp_receiver receiver(listen_addr);

    for (;;)
    {
      char payload[1024];
      std::error_code err;

      size_t got = receiver.recv(asio::buffer(payload),
                                 std::chrono::seconds(10), err);

      if (err)
      {
        cout << "Receive failed: " << err.message() << "\n";
      }
      else
      {
        cout << "Received: ";
        cout.write(payload, got);
        cout << "\n";
      }
    }
  }
  catch (const exception& ex)
  {
    cerr << "Error: " << ex.what() << "\n";
    return 1;
  }

  return 0;
}

#include "lib/common/demangle.hpp"
