// Test suite for demangling and name truncation utilities
namespace {

// Helper alias for clarity
using mangled_pair = std::pair<std::string_view, std::string_view>;

}  // namespace

TEST(common, demangling)
{
    // This test verifies that cxx_demangle correctly processes valid C++ mangled names
    // and leaves invalid ones unchanged (pass-through behavior).
    const std::array<mangled_pair, 6> test_cases{{
        {"_ZN11rocprofiler8internal18correlation_config22get_unique_internal_idEv",
         "rocprofiler::internal::correlation_config::get_unique_internal_id()"},
        {"_ZN11rocprofiler8internal18get_active_configsEv",
         "rocprofiler::internal::get_active_configs()"},
        {"_ZN11rocprofiler8internal22get_registered_configsEv",
         "rocprofiler::internal::get_registered_configs()"},
        {"_ZZN11rocprofiler8internal18correlation_config22get_unique_internal_idEvE2_v",
         "rocprofiler::internal::correlation_config::get_unique_internal_id()::_v"},
        {"_ZZN11rocprofiler8internal18get_active_configsEvE2_v",
         "rocprofiler::internal::get_active_configs()::_v"},
        {"_ZZN11rocprofiler8internal22get_registered_configsEvE2_v",
         "rocprofiler::internal::get_registered_configs()::_v"}
    }};

    for (const auto& [mangled_name, expected_demangled] : test_cases) {
        // Confirm correct demangling of valid input
        EXPECT_EQ(rocprofiler::common::cxx_demangle(mangled_name), expected_demangled)
            << "Failed to demangle: '" << mangled_name << "'";

        // Introduce artificial corruption by prepending extra '_Z' and verify pass-through
        const std::string corrupted_input = std::string{"_Z"} + std::string{mangled_name};
        EXPECT_EQ(rocprofiler::common::cxx_demangle(corrupted_input), corrupted_input)
            << "Unexpected success on malformed input: '" << corrupted_input << "'";
    }
}

TEST(common, truncate)
{
    // Verify that truncate_name extracts the core function name from a fully-qualified template instantiation.
    const std::string_view mangled_input{
        "_ZSt16__do_uninit_copyIPKSt4pairINSt7__cxx1112basic_"
        "stringIcSt11char_traitsIcESaIcEEES6_EPS7_ET0_T_SC_SB_"};

    const std::string_view fully_expanded{
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >* "
        "std::__do_uninit_copy<std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > "
        ">*>(std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> >, std::__cxx11::basic_string<char, std::char_traits<char>, "
        "std::allocator<char> > > const*, std::pair<std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> >, std::__cxx11::basic_string<char, "
        "std::char_traits<char>, std::allocator<char> > > const*, "
        "std::pair<std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> "
        ">, std::__cxx11::basic_string<char, std::char_traits<char>, std::allocator<char> > >*)"};

    // Step 1: Demangle and confirm full expansion matches expected
    EXPECT_EQ(rocprofiler::common::cxx_demangle(mangled_input), fully_expanded);

    // Step 2: Extract function name from full signature
    EXPECT_EQ(rocprofiler::common::truncate_name(fully_expanded),
              std::string_view{"__do_uninit_copy"});

    // Step 3: Combine demangle + truncate in one pipeline
    EXPECT_EQ(rocprofiler::common::truncate_name(
                  rocprofiler::common::cxx_demangle(mangled_input)),
              std::string_view{"__do_uninit_copy"});
}

