// Entry point for the command-line interface client
// Designed for terminal-based interaction and system tray integration
int main(int argc, char* argv[]) {
    // Single-instance enforcement is handled only in serve mode,
    // enabling other operations (status, list, pull, delete, stop) to execute concurrently
    try {
        lemon::CLIParser cli_parser;
        cli_parser.parse(argc, argv);

        if (!cli_parser.should_proceed()) {
            return cli_parser.get_return_code();
        }

        // Setup logging infrastructure
        auto settings = cli_parser.get_configuration();
        auto console_sink = std::make_shared<AixLog::SinkCout>(
            AixLog::Filter(AixLog::to_severity(settings.log_verbosity)),
            "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message"
        );
        AixLog::Log::initialize({console_sink});

        lemon_tray::TrayApplication application(settings, cli_parser.get_tray_configuration());
        return application.execute();
    } catch (const std::runtime_error& ex) {
        LOG(ERROR) << "Critical runtime error: " << ex.what() << std::endl;
        return 1;
    } catch (...) {
        LOG(ERROR) << "Unexpected critical error occurred" << std::endl;
        return 1;
    }
}

