std::shared_ptr<MOBase::IFileTree> InstallDialog::getModifiedTree() const
{
  return m_ArchiveTree->getRoot()->getEntry()->getFileTree();
}

bool InstallDialog::validateContent() const
{
  if (!m_Validator) {
    return true;
  }
  return m_Validator->isDataStructureValid(m_ArchiveTree->getRoot()->getEntry()->getFileTree()) ==
         ModDataChecker::ValidationResult::CORRECT;
}

void InstallDialog::refreshValidationFeedback()
{
  if (!m_Validator) {
    m_ArchiveTree->setStyleSheet("QTreeWidget { border: none; }");
    m_StatusMessage->setText(
        tr("Unable to inspect contents of <%1>.").arg(m_DataDirectoryName));
    m_StatusMessage->setToolTip(tr("The active game plugin does not support content validation for <%1>.")
                                   .arg(m_DataDirectoryName));
    m_StatusMessage->setStyleSheet("color: #556b2f;");
  } else if (validateContent()) {
    m_ArchiveTree->setStyleSheet(
        "QTreeWidget { border: 1px solid #006400; border-radius: 3px; }");
    m_StatusMessage->setText(
        tr("Contents of <%1> appear valid.").arg(m_DataDirectoryName));
    m_StatusMessage->setToolTip(
        tr("Contents of <%1> conform to expected structure for this game.")
            .arg(m_DataDirectoryName));
    m_StatusMessage->setStyleSheet("color: #006400;");
  } else {
    m_ArchiveTree->setStyleSheet("QTreeWidget { border: 1px solid #8b0000; border-radius: 3px; }");
    m_StatusMessage->setText(
        tr("Contents of <%1> do not seem valid.").arg(m_DataDirectoryName));
    m_StatusMessage->setToolTip(
        tr("Contents of <%1> likely violate expected layout for this game.")
            .arg(m_DataDirectoryName));
    m_StatusMessage->setStyleSheet("color: #8b0000;");
  }
}

void InstallDialog::addSubdirectoryTo(ArchiveTreeWidgetItem* targetItem)
{
  // Defensive check — should never trigger with proper menu context:
  if (!targetItem->getEntry()->isDirectory()) {
    displayError(tr("Cannot create a folder inside a file."));
    return;
  }

  auto treeRef = targetItem->getEntry()->getFileTree();
  bool confirmed = false;
  QString inputName = QInputDialog::getText(this,
                                            tr("New Folder Name"),
                                            tr("Enter name for new directory:"),
                                            QLineEdit::Normal,
                                            QString(),
                                            &confirmed);
  inputName = inputName.trimmed();

  if (confirmed && !inputName.isEmpty()) {
    if (treeRef->hasChild(inputName)) {
      displayError(tr("A file or folder with that name already exists."));
      return;
    }

    targetItem->expand();
    ArchiveTreeWidgetItem* createdItem = m_ArchiveTree->insertDirectory(targetItem, inputName);
    m_ArchiveTree->scrollToItem(createdItem);
  }
}

void InstallDialog::handleContextMenu(QPoint screenPos)
{
  ArchiveTreeWidgetItem* clickedItem =
      static_cast<ArchiveTreeWidgetItem*>(m_ArchiveTree->itemAt(screenPos));
  if (!clickedItem) {
    return;
  }

  QPopup menu(this);

  // Contextual actions based on item type and state
  if (clickedItem != m_ArchiveTree->getRoot() && clickedItem->getEntry()->isDirectory()) {
    menu.addAction(tr("Mark as <%1> folder").arg(m_DataDirectoryName),
                   [this, clickedItem]() {
                     m_ArchiveTree->markAsRoot(clickedItem);
                   });
  }

  if (m_ArchiveTree->getRoot()->getEntry() != m_DefaultRoot->getEntry()) {
    menu.addAction(tr("Reset <%1> folder").arg(m_DataDirectoryName), [this]() {
      m_ArchiveTree->resetRoot(m_DefaultRoot);
    });
  }

  if (!menu.isEmpty()) {
    menu.addSeparator();
  }

  if (clickedItem->getEntry()->isDirectory()) {
    menu.addAction(tr("Create subfolder..."), [this, clickedItem]() {
      addSubdirectoryTo(clickedItem);
    });
  } else {
    menu.addAction(tr("&Open File"), [this, clickedItem]() {
      emit requestFileOpen(clickedItem->getEntry().get());
    });
  }

  menu.exec(m_ArchiveTree->viewport()->mapToGlobal(screenPos));
}

void InstallDialog::on_acceptButton_pressed()
{
  if (!validateContent()) {
    if (QMessageBox::question(
            this,
            tr("Proceed Anyway?"),
            tr("This mod appears to be improperly configured and may fail at runtime. "
               "We recommend correcting the folder hierarchy before proceeding."),
            QMessageBox::Ignore | QMessageBox::Abort,
            QMessageBox::Abort) == QMessageBox::Abort) {
      return;
    }
  }

  accept();
}

void InstallDialog::on_cancelButton_pressed()
{
  reject();
}

