// Forward declarations
void RenderFrame();

// Application state
static bool displayDemoWindow = true;
static bool displaySecondaryWindow = false;
static ImVec4 backgroundColor = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

int main(int argc, char** argv) {
    // Initialize GLUT window
    glutInit(&argc, argv);

#ifdef __FREEGLUT_EXT_H__
    glutSetOption(GLUT_ACTION_ON_WINDOW_CLOSE, GLUT_ACTION_GLUTMAINLOOP_RETURNS);
#endif

    glutInitDisplayMode(GLUT_RGBA | GLUT_DOUBLE | GLUT_MULTISAMPLE);
    glutInitWindowSize(1280, 720);
    glutCreateWindow("Dear ImGui GLUT+OpenGL2 Example");

    // Register rendering callback
    glutDisplayFunc(RenderFrame);

    // Initialize Dear ImGui context
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO(); (void)io;

    // Enable keyboard navigation
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;

    // Apply dark color scheme
    ImGui::StyleColorsDark();

    // Setup platform and renderer backends
    ImGui_ImplGLUT_Init();
    ImGui_ImplOpenGL2_Init();

    // Install GLUT input handlers
    ImGui_ImplGLUT_InstallFuncs();

    // Main loop execution
    glutMainLoop();

    // Cleanup resources
    ImGui_ImplOpenGL2_Shutdown();
    ImGui_ImplGLUT_Shutdown();
    ImGui::DestroyContext();

    return 0;
}

void RenderFrame() {
    // Begin new frame for all systems
    ImGui_ImplOpenGL2_NewFrame();
    ImGui_ImplGLUT_NewFrame();
    ImGui::NewFrame();

    ImGuiIO& io = ImGui::GetIO();

    // 1. Display the main demo window
    if (displayDemoWindow)
        ImGui::ShowDemoWindow(&displayDemoWindow);

    // 2. Create a custom application window
    {
        static float sliderValue = 0.0f;
        static int buttonClickCount = 0;

        ImGui::Begin("Hello, world!");
        ImGui::Text("This is some useful text.");

        ImGui::Checkbox("Show Demo Window", &displayDemoWindow);
        ImGui::Checkbox("Show Secondary Window", &displaySecondaryWindow);

        ImGui::SliderFloat("Adjust Value", &sliderValue, 0.0f, 1.0f);
        ImGui::ColorEdit3("Background Color", (float*)&backgroundColor);

        if (ImGui::Button("Increment Counter"))
            buttonClickCount++;

        ImGui::SameLine();
        ImGui::Text("Counter: %d", buttonClickCount);

        ImGui::Text("Performance: %.3f ms/frame (%.1f FPS)", 
                    1000.0f / io.Framerate, io.Framerate);
        ImGui::End();
    }

    // 3. Optional secondary window
    if (displaySecondaryWindow) {
        ImGui::Begin("Additional Window", &displaySecondaryWindow);
        ImGui::Text("Greetings from the second window!");

        if (ImGui::Button("Dismiss")) {
            displaySecondaryWindow = false;
        }

        ImGui::End();
    }

    // Finalize and render
    ImGui::Render();

    glViewport(0, 0, (GLsizei)io.DisplaySize.x, (GLsizei)io.DisplaySize.y);
    glClearColor(backgroundColor.x * backgroundColor.w,
                 backgroundColor.y * backgroundColor.w,
                 backgroundColor.z * backgroundColor.w,
                 backgroundColor.w);
    glClear(GL_COLOR_BUFFER_BIT);

    ImGui_ImplOpenGL2_RenderDrawData(ImGui::GetDrawData());

    glutSwapBuffers();
    glutPostRedisplay();
}

#include <vector>
#include <algorithm>
#include <iostream>

using namespace std;

const int M = 1e4 + 1, NN = 6400;
const int INF = 1e9 + 7;

// x_pos[x] stores 1D indices of positions (i, j) where grid[i][j] == x
vector<int> x_pos[M]; 
// dp[t][idx] represents minimum cost with at most t teleports ending at position idx
unsigned dp[11][NN]; 
// suffixMin[x] will store minimum dp[t-1][idx] for all positions with value >= x
unsigned suffixMin[M]; 

class Solution {
public:
    // Convert 2D coordinates to 1D index
    static inline int getIdx(int i, int j, int cols) { 
        return i * cols + j; 
    }

    static int minCost(vector<vector<int>>& grid, int maxTeleports) {
        const int rows = grid.size(), cols = grid[0].size(), totalCells = rows * cols;
        int maxValue = 0;

        // Group cell indices by their grid values
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                const int val = grid[i][j];
                x_pos[val].push_back(getIdx(i, j, cols));
                maxValue = max(maxValue, val);
            }
        }

        // Initialize DP table with INF
        for (int t = 0; t <= maxTeleports; t++) {
            fill(dp[t], dp[t] + totalCells, INF);
        }

        // Base case: no teleport allowed (t=0)
        dp[0][0] = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                const int pos = getIdx(i, j, cols);
                const int val = grid[i][j];

                if (i > 0) {
                    dp[0][pos] = min(dp[0][pos], dp[0][getIdx(i-1, j, cols)] + val);
                }
                if (j > 0) {
                    dp[0][pos] = min(dp[0][pos], dp[0][getIdx(i, j-1, cols)] + val);
                }
            }
        }

        // Fill DP table for increasing number of teleports
        for (int t = 1; t <= maxTeleports; t++) {
            // Compute suffix minimums for teleport transition
            unsigned currentMin = INF;
            for (int val = maxValue; val >= 0; val--) {
                for (int position : x_pos[val]) {
                    currentMin = min(currentMin, dp[t-1][position]);
                }
                suffixMin[val] = currentMin;
            }

            // Update DP for current teleport count
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    const int pos = getIdx(i, j, cols);
                    const int val = grid[i][j];

                    // Option 1: Use teleport to any cell with same value
                    dp[t][pos] = min(dp[t-1][pos], suffixMin[val]);

                    // Option 2: Move from top cell
                    if (i > 0) {
                        dp[t][pos] = min(dp[t][pos], dp[t][getIdx(i-1, j, cols)] + val);
                    }

                    // Option 3: Move from left cell
                    if (j > 0) {
                        dp[t][pos] = min(dp[t][pos], dp[t][getIdx(i, j-1, cols)] + val);
                    }
                }
            }
        }

        int result = dp[maxTeleports][totalCells - 1];

        // Clean up for next test case
        for (int val = 1; val <= maxValue; val++) {
            x_pos[val].clear();
        }

        return result;
    }
};

