//-*****************************************************************************
namespace AO = Alembic::AbcCoreOgawa;
namespace AA = Alembic::AbcCoreAbstract;

//-*****************************************************************************
void CreateArchive(const std::string& archivePath)
{
    std::cout << "Starting archive creation..." << std::endl;
    AA::MetaData meta;
    AO::WriteArchive writerFactory;

    // Prepare the top-level object before closing scope
    AA::ObjectWriterPtr childObj;
    AA::ArchiveWriterPtr archive = writerFactory(archivePath, meta);
    AA::ObjectWriterPtr root = archive->getTop();

    childObj = root->createChild(
        AA::ObjectHeader("child0", meta));

    std::cout << "Archive creation completed." << std::endl;
}

//-*****************************************************************************
void LoadArchive(const std::string& archivePath)
{
    std::cout << "Loading archive: " << archivePath << std::endl;
    AO::ReadArchive readerFactory;

    AA::ObjectReaderPtr loadedChild;
    AA::ArchiveReaderPtr archive = readerFactory(archivePath);
    AA::ObjectReaderPtr root = archive->getTop();

    loadedChild = root->getChild(0);
    std::cout << "Loaded child full name: " << loadedChild->getFullName() 
              << std::endl;
    std::cout << "Archive loading finished." << std::endl;
}

//-*****************************************************************************
int main(int, char**)
{
    const std::string testFile("octessence58.abc");
    CreateArchive(testFile);
    LoadArchive(testFile);
    return 0;
}

#include <dolphin.h>
