// Initialize performance monitoring counters
void PMBegin(void) {
    // Reset all performance monitor registers
    PPCMtmmcr0(0);
    PPCMtmmcr1(0);
    PPCMtpmc1(0);
    PPCMtpmc2(0);
    PPCMtpmc3(0);
    PPCMtpmc4(0);

    // Configure performance monitor for cycle counting and instruction metrics
    PPCMtmmcr0(0x4F);
    PPCMtmmcr1(0x78800000);
}

// Disable performance monitoring by clearing control registers
void PMEnd(void) {
    PPCMtmmcr0(0);
    PPCMtmmcr1(0);
}

// Read the cycle counter value
u32 PMCycles(void) {
    return PPCMfpmc1();
}

// Read L1 instruction fetch misses
u32 PML1FetchMisses(void) {
    return PPCMfpmc2();
}

// Read cycles lost due to L1 cache misses
u32 PML1MissCycles(void) {
    return PPCMfpmc3();
}

// Read total instructions executed
u32 PMInstructions(void) {
    return PPCMfpmc4();
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Speed up I/O operations
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (cin >> n >> m) {
        // Initialize weights for each participant as 1.0
        vector<double> weights(n, 1.0);

        // Decay factor for incorrect predictions
        const double decay = 0.8;

        for (int round = 0; round < m; ++round) {
            string predictions;
            cin >> predictions;

            // Compute weighted sums for '0' and '1'
            double sum0 = 0.0;
            double sum1 = 0.0;
            for (int i = 0; i < n; ++i) {
                if (predictions[i] == '0') {
                    sum0 += weights[i];
                } else {
                    sum1 += weights[i];
                }
            }

            // Decide prediction based on which side has higher weight
            char predicted = (sum1 > sum0) ? '1' : '0';
            cout << predicted << '\n';

            // Read actual result
            char result;
            cin >> result;

            // Update weights: reduce those who were wrong
            double highestWeight = 0.0;
            for (int i = 0; i < n; ++i) {
                if (predictions[i] != result) {
                    weights[i] *= decay;
                }
                if (weights[i] > highestWeight) {
                    highestWeight = weights[i];
                }
            }

            // Prevent underflow by rescaling if needed
            if (highestWeight < 1e-150) {
                for (int i = 0; i < n; ++i) {
                    weights[i] *= 1e150;
                }
            }
        }
    }
    return 0;
}

