// Wrapper to ensure compatibility with older glibc versions on x86-64 Linux
// By using the 2.2.5 version of memcpy, we avoid requiring glibc >= 2.14.
// This is achieved by linking with -Wl,-wrap,memcpy in extconf.rb.
#ifdef __linux__
#if defined(__x86_64__) && defined(__GNU_LIBRARY__)
__asm__(".symver memcpy,memcpy@GLIBC_2.2.5");
void* __wrap_memcpy(void* destination, const void* source, size_t size) {
    return memcpy(destination, source, size);
}
#else
void* __wrap_memcpy(void* destination, const void* source, size_t size) {
    return memmove(destination, source, size);
}
#endif
#endif

