using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *leftNode, TreeNode *rightNode) : val(x), left(leftNode), right(rightNode) {}
};

class BinarySearchTreeValidator {
public:
    bool validateBST(TreeNode* currentNode, long lowerBound, long upperBound) {
        // Base case: an empty subtree is valid
        if (currentNode == nullptr) return true;

        // Check if current node violates BST property
        if (currentNode->val <= lowerBound || currentNode->val >= upperBound) {
            return false;
        }

        // Recursively validate left and right subtrees with updated bounds
        bool leftValid = validateBST(currentNode->left, lowerBound, currentNode->val);
        bool rightValid = validateBST(currentNode->right, currentNode->val, upperBound);

        return leftValid && rightValid;
    }

    bool isValidBST(TreeNode* root) {
        return validateBST(root, static_cast<long>(LONG_MIN), static_cast<long>(LONG_MAX));
    }
};

