#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <chrono>

// Global modulus for the computation
long long modulus;

// Modular multiplication using __int128 to avoid overflow
long long mod_multiply(long long x, long long y, long long m) {
    return static_cast<long long>((static_cast<__int128>(x) * y) % m);
}

// Computes bit-length of a positive integer: floor(log2(x)) + 1; returns 0 for x == 0
int count_bits(long long val) {
    if (val == 0) return 0;
    return 64 - __builtin_clzll(val);
}

// Queries the device with value 'a' and reads back the measured time
long long query_device(long long a) {
    std::cout << "? " << a << std::endl;
    long long response_time;
    std::cin >> response_time;
    return response_time;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Read modulus from input
    std::cin >> modulus;

    // Secret exponent accumulator
    long long secret_exponent = 0;

    // Random number generator seeded with high-resolution clock
    std::mt19937_64 prng(std::chrono::steady_clock::now().time_since_epoch().count());

    // Recover each bit of the secret exponent (assume up to 60 bits)
    for (int position = 0; position < 60; ++position) {
        long double evidence_score = 0.0L;
        const int sample_count = 40;

        for (int trial = 0; trial < sample_count; ++trial) {
            // Generate random base in [2, modulus-1]
            long long base_value = std::uniform_int_distribution<long long>(2, modulus - 1)(prng);

            // Query total execution time for this base
            long long observed_time = query_device(base_value);

            // Precompute powers: a^(2^i) mod n for i = 0..59
            std::vector<long long> power_sequence(60);
            std::vector<int> power_bitlengths(60);

            power_sequence[0] = base_value;
            for (int idx = 1; idx < 60; ++idx) {
                power_sequence[idx] = mod_multiply(power_sequence[idx - 1], power_sequence[idx - 1], modulus);
            }

            // Compute bit lengths of each power + 1
            for (int idx = 0; idx < 60; ++idx) {
                power_bitlengths[idx] = count_bits(power_sequence[idx]) + 1;
            }

            // Constant term C(a): sum of squared bit lengths
            long long constant_term = 0;
            for (int idx = 0; idx < 60; ++idx) {
                constant_term += static_cast<long long>(power_bitlengths[idx]) * power_bitlengths[idx];
            }

            // Track current residue and known contribution D_known
            long long accumulated_residue = 1;
            long long known_contribution = 0;

            for (int idx = 0; idx < position; ++idx) {
                if ((secret_exponent >> idx) & 1LL) {
                    known_contribution += static_cast<long long>(count_bits(accumulated_residue) + 1) * power_bitlengths[idx];
                    accumulated_residue = mod_multiply(accumulated_residue, power_sequence[idx], modulus);
                }
            }

            // Remaining time after subtracting known parts
            long long residual_time = observed_time - constant_term - known_contribution;

            // Hypothetical contribution if bit at 'position' is 1
            long long hypothetical_contribution = static_cast<long long>(count_bits(accumulated_residue) + 1) * power_bitlengths[position];

            // Accumulate statistical evidence favoring bit=1
            evidence_score += static_cast<long double>(residual_time) - static_cast<long double>(hypothetical_contribution) / 2.0L;
        }

        // Decide bit value based on cumulative evidence
        if (evidence_score > 0.0L) {
            secret_exponent |= (1LL << position);
        }
    }

    // Output recovered secret exponent
    std::cout << "! " << secret_exponent << std::endl;
    return 0;
}

