//////////////////////////////////////////////////////////////////////////////////////////////
// IDisplayClusterSessionListener
//////////////////////////////////////////////////////////////////////////////////////////////
typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType
FDisplayClusterClusterEventsBinaryService::HandleIncomingPacket(const TSharedPtr<FDisplayClusterPacketBinary>& incoming)
{
	// Validate input
	if (!incoming.IsValid())
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - Received null packet"), *GetName());
		return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType{};
	}

	// Decode binary packet into internal event structure
	FDisplayClusterClusterEventBinary decodedEvent;
	if (!DisplayClusterNetworkDataConversion::BinaryPacketToBinaryEvent(incoming, decodedEvent))
	{
		UE_LOG(LogDisplayClusterNetwork, Error, TEXT("%s - Failed to decode binary packet into cluster event"), *GetName());
		return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType{};
	}

	// Log and forward for internal replication
	UE_LOG(LogDisplayClusterNetwork, Verbose, TEXT("%s - Forwarding cluster event internally..."), *GetName());
	ReplicateClusterEventBinary(decodedEvent);

	return typename IDisplayClusterSessionPacketHandler<FDisplayClusterPacketBinary, false>::ReturnType{};
}

