#define HIP_CHECK(expression)                        \
{                                                    \
    const hipError_t status = expression;            \
    if (status != hipSuccess)                        \
    {                                                \
        std::cerr << "HIP error " << status          \
                << ": " << hipGetErrorString(status) \
                << " at " << __FILE__ << ":"         \
                << __LINE__ << std::endl;            \
        std::exit(EXIT_FAILURE);                     \
    }                                                \
}

// Structure to hold memory pool usage metrics
struct MemoryStats
{
    std::uint64_t currentReserved;
    std::uint64_t peakReserved;
    std::uint64_t currentUsed;
    std::uint64_t peakUsed;
};

// Retrieve current and high-watermark memory usage from the pool
void fetchMemoryStats(hipMemPool_t pool, MemoryStats* stats)
{
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemCurrent, &stats->currentReserved));
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrReservedMemHigh,   &stats->peakReserved));
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemCurrent,    &stats->currentUsed));
    HIP_CHECK(hipMemPoolGetAttribute(pool, hipMemPoolAttrUsedMemHigh,       &stats->peakUsed));
}

// Reset high-watermark counters to match current values
void resetWatermarks(hipMemPool_t pool)
{
    std::uint64_t zero = 0;
    HIP_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrReservedMemHigh, &zero));
    HIP_CHECK(hipMemPoolSetAttribute(pool, hipMemPoolAttrUsedMemHigh,    &zero));
}

int main()
{
    hipMemPool_t memPool;
    const int deviceId = 0;

    // Set active device
    HIP_CHECK(hipSetDevice(deviceId));

    // Obtain default memory pool for the device
    HIP_CHECK(hipDeviceGetDefaultMemPool(&memPool, deviceId));

    // Perform a test allocation and deallocation
    const std::size_t allocSize = 1 * 1024 * 1024; // 1 MiB
    void* buffer;
    HIP_CHECK(hipMalloc(&buffer, allocSize));
    HIP_CHECK(hipFree(buffer));

    // Trim pool to desired size
    const std::size_t targetSize = 512 * 1024; // 512 KiB
    HIP_CHECK(hipMemPoolTrimTo(memPool, targetSize));

    // Collect and display statistics before reset
    MemoryStats preReset;
    fetchMemoryStats(memPool, &preReset);

    std::cout << "Before resetting watermarks:" << std::endl;
    std::cout << "Reserved (current): " << preReset.currentReserved << " bytes\n";
    std::cout << "Reserved (peak):    " << preReset.peakReserved    << " bytes\n";
    std::cout << "Used (current):     " << preReset.currentUsed     << " bytes\n";
    std::cout << "Used (peak):        " << preReset.peakUsed        << " bytes\n";

    // Reset high-watermark counters
    resetWatermarks(memPool);

    // Collect and display statistics after reset
    MemoryStats postReset;
    fetchMemoryStats(memPool, &postReset);

    std::cout << "\nAfter resetting watermarks:" << std::endl;
    std::cout << "Reserved (current): " << postReset.currentReserved << " bytes\n";
    std::cout << "Reserved (peak):    " << postReset.peakReserved    << " bytes\n";
    std::cout << "Used (current):     " << postReset.currentUsed     << " bytes\n";
    std::cout << "Used (peak):        " << postReset.peakUsed        << " bytes\n";

    return EXIT_SUCCESS;
}

