namespace http {
namespace server2 {

server::server(const std::string& address, const std::string& port,
    const std::string& doc_root, std::size_t pool_size)
  : io_context_pool_(pool_size),
    signals_(io_context_pool_.get_io_context()),
    acceptor_(io_context_pool_.get_io_context()),
    new_connection_(),
    request_handler_(doc_root)
{
  // Set up signal handling for graceful shutdown
  signals_.add(SIGINT);
  signals_.add(SIGTERM);
#if defined(SIGQUIT)
  signals_.add(SIGQUIT);
#endif

  // Start asynchronous wait for termination signals
  signals_.async_wait([this](const asio::error_code& /*ec*/, int /*signal_number*/) {
    handle_stop();
  });

  // Configure network endpoint and acceptor
  asio::ip::tcp::resolver resolver(acceptor_.get_executor().context());
  auto endpoints = resolver.resolve(address, port);
  asio::ip::tcp::endpoint ep = *endpoints.begin();

  acceptor_.open(ep.protocol());
  acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  acceptor_.bind(ep);
  acceptor_.listen();

  // Begin accepting incoming connections
  initiate_accept();
}

void server::run()
{
  io_context_pool_.run();
}

void server::initiate_accept()
{
  new_connection_.reset(new connection(
        io_context_pool_.get_io_context(), request_handler_));
  acceptor_.async_accept(new_connection_->socket(),
      [this](const asio::error_code& ec) {
        handle_new_connection(ec);
      });
}

void server::handle_new_connection(const asio::error_code& error)
{
  if (!error)
  {
    new_connection_->start();
  }
  // Continue accepting more connections
  initiate_accept();
}

void server::handle_stop()
{
  io_context_pool_.stop();
}

