#include <vector>
#include <string>
#include <stack>

class Solution {
public:
    std::vector<std::string> generateParenthesis(int n) {
        std::vector<std::string> result;

        // Using a stack to simulate recursion iteratively
        // Each element stores: current_string, open_remaining, close_remaining
        struct State {
            std::string str;
            int open_left;
            int close_left;
        };

        std::stack<State> stk;
        stk.push({"", n, n});

        while (!stk.empty()) {
            State current = stk.top();
            stk.pop();

            // If no more parentheses to add, we have a complete valid combination
            if (current.close_left == 0) {
                result.push_back(current.str);
                continue;
            }

            // If we can add a closing parenthesis (more opens used than closes)
            if (current.close_left > current.open_left) {
                stk.push({current.str + ")", current.open_left, current.close_left - 1});
            }

            // If we can add an opening parenthesis (still some left)
            if (current.open_left > 0) {
                stk.push({current.str + "(", current.open_left - 1, current.close_left});
            }
        }

        return result;
    }
};

