#include <iostream>
#include <asio.hpp>
#include <functional>

// A class that prints incrementing numbers with a one-second delay between each
class delayed_printer
{
public:
  delayed_printer(asio::io_context& context)
    : timer_(context, asio::chrono::seconds(1)),
      counter_(0)
  {
    start_timer();
  }

  ~delayed_printer()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

private:
  void start_timer()
  {
    timer_.async_wait(std::bind(&delayed_printer::handle_timeout, this));
  }

  void handle_timeout()
  {
    if (counter_ < 5)
    {
      std::cout << counter_ << std::endl;
      ++counter_;

      // Reschedule the timer for one second later
      timer_.expires_at(timer_.expiry() + asio::chrono::seconds(1));
      start_timer();
    }
  }

  asio::steady_timer timer_;
  int counter_;
};

int main()
{
  asio::io_context io_context;
  delayed_printer printer(io_context);
  io_context.run();
  return 0;
}

