// Helper to fill a bit_vector_builder from a bool vector
void populate_builder(succinct::bit_vector_builder& builder, const std::vector<bool>& bits) {
    for (bool bit : bits) {
        builder.push_back(bit);
    }
}

BOOST_AUTO_TEST_CASE(random_bitmaps)
{
    std::srand(42);
    constexpr size_t total_bits = 10000;

    for (size_t shift = 1; shift < 8; ++shift) {
        double ones_ratio = 1.0 / (1ULL << shift);
        std::vector<bool> pattern = random_bit_vector(total_bits, ones_ratio);

        succinct::bit_vector_builder bf;
        populate_builder(bf, pattern);

        succinct::elias_fano ef(&bf);
        test_equal_bits(pattern, ef, "Random bitmap");
        test_rank_select1(pattern, ef, "Random bitmap");
        test_delta(ef, "Random bitmap");
        test_select_enumeration(pattern, ef, "Random bitmap");
    }
}

