#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

// Leetcode 2099. Find Subsequence of Length K With the Largest Sum
class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        // Pair each number with its original index
        vector<pair<int, int>> indexedNums;
        for (int i = 0; i < nums.size(); ++i) {
            indexedNums.push_back(make_pair(nums[i], i));
        }

        // Sort by value in descending order to find largest elements
        sort(indexedNums.begin(), indexedNums.end(), 
             [](const pair<int, int>& x, const pair<int, int>& y) {
                 return x.first > y.first;
             });

        // Select the top k elements
        vector<pair<int, int>> topK(indexedNums.begin(), indexedNums.begin() + k);

        // Reorder selected elements by their original positions to preserve subsequence order
        sort(topK.begin(), topK.end(),
             [](const pair<int, int>& x, const pair<int, int>& y) {
                 return x.second < y.second;
             });

        // Extract values in correct order
        vector<int> result;
        for (const auto& p : topK) {
            result.push_back(p.first);
        }

        return result;
    }
};

#include <iostream>
#include <type_traits>

// Helper type traits to mimic the behavior of toml::detail traits
namespace detail {

    // Check if type has 'iterator' member
    template<typename T, typename = void>
    struct has_iterator : std::false_type {};

    template<typename T>
    struct has_iterator<T, std::void_t<typename T::iterator>> : std::true_type {};

    // Check if type has 'value_type' member
    template<typename T, typename = void>
    struct has_value_type : std::false_type {};

    template<typename T>
    struct has_value_type<T, std::void_t<typename T::value_type>> : std::true_type {};

    // Check if type has 'key_type' member
    template<typename T, typename = void>
    struct has_key_type : std::false_type {};

    template<typename T>
    struct has_key_type<T, std::void_t<typename T::key_type>> : std::true_type {};

    // Check if type has 'mapped_type' member
    template<typename T, typename = void>
    struct has_mapped_type : std::false_type {};

    template<typename T>
    struct has_mapped_type<T, std::void_t<typename T::mapped_type>> : std::true_type {};

    // Container detection: must have iterator and value_type but NOT key_type/mapped_type
    template<typename T>
    struct is_container : std::integral_constant<bool,
        has_iterator<T>::value && 
        has_value_type<T>::value &&
        !has_key_type<T>::value &&
        !has_mapped_type<T>::value> {};

    // Map detection: must have key_type and mapped_type
    template<typename T>
    struct is_map : std::integral_constant<bool,
        has_key_type<T>::value &&
        has_mapped_type<T>::value> {};
}

// Simple index sequence implementation
namespace cxx {
    template<std::size_t... Is>
    struct index_sequence {};

    template<std::size_t N, std::size_t... Is>
    struct make_index_sequence_impl : make_index_sequence_impl<N-1, N-1, Is...> {};

    template<std::size_t... Is>
    struct make_index_sequence_impl<0, Is...> {
        using type = index_sequence<Is...>;
    };

    template<std::size_t N>
    using make_index_sequence = typename make_index_sequence_impl<N>::type;
}

int main() {
    // Test has_iterator trait
    static_assert(detail::has_iterator<std::list<int>>::value, "list should have iterator");
    static_assert(detail::has_iterator<std::forward_list<int>>::value, "forward_list should have iterator");
    static_assert(detail::has_iterator<std::deque<int>>::value, "deque should have iterator");
    static_assert(detail::has_iterator<std::vector<int>>::value, "vector should have iterator");
    static_assert(detail::has_iterator<std::set<int>>::value, "set should have iterator");
    static_assert(detail::has_iterator<std::unordered_set<std::string>>::value, "unordered_set should have iterator");
    static_assert(detail::has_iterator<std::array<int, 10>>::value, "array should have iterator");
    static_assert(detail::has_iterator<std::map<std::string, int>>::value, "map should have iterator");
    static_assert(detail::has_iterator<std::unordered_map<std::string, int>>::value, "unordered_map should have iterator");

    // Test has_value_type trait
    static_assert(detail::has_value_type<std::list<int>>::value, "list should have value_type");
    static_assert(detail::has_value_type<std::forward_list<int>>::value, "forward_list should have value_type");
    static_assert(detail::has_value_type<std::deque<int>>::value, "deque should have value_type");
    static_assert(detail::has_value_type<std::vector<int>>::value, "vector should have value_type");
    static_assert(detail::has_value_type<std::array<int, 10>>::value, "array should have value_type");
    static_assert(detail::has_value_type<std::set<int>>::value, "set should have value_type");
    static_assert(detail::has_value_type<std::unordered_set<std::string>>::value, "unordered_set should have value_type");
    static_assert(detail::has_value_type<std::map<std::string, int>>::value, "map should have value_type");
    static_assert(detail::has_value_type<std::unordered_map<std::string, int>>::value, "unordered_map should have value_type");

    // Test has_key_type and has_mapped_type traits
    static_assert(detail::has_key_type<std::map<std::string, int>>::value, "map should have key_type");
    static_assert(detail::has_key_type<std::unordered_map<std::string, int>>::value, "unordered_map should have key_type");
    static_assert(detail::has_mapped_type<std::map<std::string, int>>::value, "map should have mapped_type");
    static_assert(detail::has_mapped_type<std::unordered_map<std::string, int>>::value, "unordered_map should have mapped_type");

    // Test is_container trait
    static_assert(detail::is_container<std::list<int>>::value, "list should be container");
    static_assert(detail::is_container<std::forward_list<int>>::value, "forward_list should be container");
    static_assert(detail::is_container<std::deque<int>>::value, "deque should be container");
    static_assert(detail::is_container<std::vector<int>>::value, "vector should be container");
    static_assert(detail::is_container<std::array<int, 10>>::value, "array should be container");
    static_assert(detail::is_container<std::set<int>>::value, "set should be container");
    static_assert(detail::is_container<std::unordered_set<std::string>>::value, "unordered_set should be container");
    static_assert(!detail::is_container<std::map<std::string, int>>::value, "map should not be container");
    static_assert(!detail::is_container<std::unordered_map<std::string, int>>::value, "unordered_map should not be container");

    // Test is_map trait
    static_assert(detail::is_map<std::map<std::string, int>>::value, "map should be map");
    static_assert(detail::is_map<std::unordered_map<std::string, int>>::value, "unordered_map should be map");

    // Test make_index_sequence
    static_assert(std::is_same_v<toml::cxx::make_index_sequence<0>, toml::cxx::index_sequence<>>, "");
    static_assert(std::is_same_v<toml::cxx::make_index_sequence<1>, toml::cxx::index_sequence<0>>, "");
    static_assert(std::is_same_v<toml::cxx::make_index_sequence<2>, toml::cxx::index_sequence<0,1>>, "");
    static_assert(std::is_same_v<toml::cxx::make_index_sequence<3>, toml::cxx::index_sequence<0,1,2>>, "");
    static_assert(std::is_same_v<toml::cxx::make_index_sequence<4>, toml::cxx::index_sequence<0,1,2,3>>, "");

    std::cout << "All compile-time checks passed!" << std::endl;
    return 0;
}

