// Factory function template to create thread-safe workers
template<typename WorkerType>
static TSharedRef<IPlasticSourceControlWorker, ESPMode::ThreadSafe> CreateNewWorker()
{
	return MakeShareable(new WorkerType());
}

void FPlasticSourceControlModule::StartupModule()
{
	// Initialize and register all supported source control operations
	auto& provider = PlasticSourceControlProvider;

	provider.RegisterWorker("Connect",        FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticConnectWorker>));
	provider.RegisterWorker("CheckOut",       FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticCheckOutWorker>));
	provider.RegisterWorker("UpdateStatus",   FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticUpdateStatusWorker>));
	provider.RegisterWorker("MarkForAdd",     FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticMarkForAddWorker>));
	provider.RegisterWorker("Delete",         FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticDeleteWorker>));
	provider.RegisterWorker("Revert",         FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticRevertWorker>));
	provider.RegisterWorker("RevertUnchanged",FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticRevertUnchangedWorker>));
	provider.RegisterWorker("RevertAll",      FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticRevertAllWorker>));
	provider.RegisterWorker("MakeWorkspace",  FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticMakeWorkspaceWorker>));
	provider.RegisterWorker("Sync",           FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticSyncWorker>));
	provider.RegisterWorker("CheckIn",        FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticCheckInWorker>));
	provider.RegisterWorker("Copy",           FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticCopyWorker>));
	provider.RegisterWorker("Resolve",        FGetPlasticSourceControlWorker::CreateStatic(&CreateNewWorker<FPlasticResolveWorker>));

	// Load user preferences from config
	PlasticSourceControlSettings.LoadSettings();

	// Register this module's provider with the global source control system
	IModularFeatures::Get().RegisterModularFeature("SourceControl", &PlasticSourceControlProvider);
}

void FPlasticSourceControlModule::ShutdownModule()
{
	// Clean up resources before module unloads
	if (PlasticSourceControlProvider.IsOpen())
	{
		PlasticSourceControlProvider.Close();
	}

	// Remove registration from modular features system
	IModularFeatures::Get().UnregisterModularFeature("SourceControl", &PlasticSourceControlProvider);
}

void FPlasticSourceControlModule::SaveSettings()
{
	// Avoid saving settings during automated builds or commandlet execution
	if (FApp::IsUnattended() || IsRunningCommandlet())
	{
		return;
	}

	PlasticSourceControlSettings.SaveSettings();
}

