#include <iostream>

// Module-like interface simulation for Karm.Core:base.panic
namespace Karm {

    // Renamed enum with same semantics
    enum class ErrorTrigger {
        TRACE,
        FATAL
    };

    // Alias for handler function pointer — renamed type and parameter order preserved
    using ErrorHandler = void (*)(ErrorTrigger, char const*, unsigned long);

    // Static storage — renamed variable
    static ErrorHandler errorHandler = nullptr;

    // Public API: register custom error handler
    void installErrorHandler(ErrorHandler handler) {
        errorHandler = handler;
    }

    // Internal dispatch — renamed function and logic slightly refactored
    void trigger(ErrorTrigger kind, char const* text, unsigned long size) {
        if (errorHandler != nullptr) {
            errorHandler(kind, text, size);
        } else {
            // No handler registered — fallback to immediate termination
            __builtin_trap();
        }
    }

    // Overloads for debug messages — renamed functions and logic reused
    void trace(char const* text, unsigned long size) {
        trigger(ErrorTrigger::TRACE, text, size);
    }

    void trace(char const* text) {
        // Compute length manually instead of relying on cstrLen
        unsigned long len = 0;
        while (text[len] != '\0') ++len;
        trace(text, len);
    }

    // Panic overloads — renamed and reordered logic
    [[noreturn]] void abort(char const* text, unsigned long size) {
        trigger(ErrorTrigger::FATAL, text, size);
        __builtin_unreachable();
    }

    [[noreturn]] void abort(char const* text) {
        // Inline string length computation
        unsigned long len = 0;
        while (text[len]) ++len;
        abort(text, len);
    }

    // Specialized abort cases — renamed and hardcoded strings
    [[noreturn]] void missingImplementation() {
        abort("not implemented", 15);
    }

    [[noreturn]] void impossiblePath() {
        abort("unreachable", 11);
    }

    // Breakpoint support — renamed macro guards and compiler-specific intrinsics
    void halt() {
#ifdef CK_DEBUG_MODE
#    ifdef __clang__
        __builtin_debugtrap();
#    elif defined(__GNUC__)
        __builtin_trap(); // TODO: switch to __builtin_debugtrap() when supported
#    elif defined(_MSC_VER)
        __debugbreak();
#    else
#        error "Unsupported toolchain"
#    endif
#endif
    }

