#include <vector>
#include <algorithm>

class Solution {
public:
    int maxProfit(std::vector<int>& prices) {
        if (prices.empty()) return 0;

        int currentMin = prices[0];
        int bestGain = 0;

        for (int i = 1; i < prices.size(); ++i) {
            // Update the minimum price seen so far
            if (prices[i] < currentMin) {
                currentMin = prices[i];
            }

            // Calculate potential profit if sold today
            int todayProfit = prices[i] - currentMin;

            // Update maximum profit if current is better
            if (todayProfit > bestGain) {
                bestGain = todayProfit;
            }
        }

        return bestGain;
    }
};

