using namespace llvm;

#define DEBUG_TYPE "ssaupdaterbulk"

// Helper: Determine the basic block associated with a use.
// For PHI nodes, returns the incoming block; otherwise, the parent block.
static BasicBlock *getBlockForUse(Use *U) {
  Instruction *UserInst = cast<Instruction>(U->getUser());
  if (PHINode *Phi = dyn_cast<PHINode>(UserInst))
    return Phi->getIncomingBlock(*U);
  return UserInst->getParent();
}

// Register a new variable to be rewritten.
unsigned SSAUpdaterBulk::RegisterVariable(StringRef VarName, Type *ElemType) {
  unsigned Idx = Rewrites.size();
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << Idx << ": initialized with Ty = "
                    << *ElemType << ", Name = " << VarName << "\n");
  RewriteDescriptor Desc(VarName, ElemType);
  Rewrites.emplace_back(std::move(Desc));
  return Idx;
}

// Mark a value as defined in a specific block.
void SSAUpdaterBulk::MarkDefinition(unsigned VarIdx, BasicBlock *BB, Value *Val) {
  assert(VarIdx < Rewrites.size() && "Invalid variable index!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarIdx
                    << ": registered definition " << *Val << " at "
                    << BB->getName() << "\n");
  Rewrites[VarIdx].Definitions[BB] = Val;
}

// Record a use site for later rewriting.
void SSAUpdaterBulk::RecordUse(unsigned VarIdx, Use *U) {
  assert(VarIdx < Rewrites.size() && "Invalid variable index!");
  LLVM_DEBUG(dbgs() << "SSAUpdater: Var=" << VarIdx << ": recorded use " << *U->get()
                    << " in " << getBlockForUse(U)->getName() << "\n");
  Rewrites[VarIdx].Uses.push_back(U);
}

// Compute the effective value at a given block by walking up dominator tree.
Value *SSAUpdaterBulk::getValueAt(BasicBlock *BB, RewriteDescriptor &Desc, DominatorTree *DT) {
  auto It = Desc.Definitions.find(BB);
  if (It == Desc.Definitions.end()) {
    if (DT->isReachableFromEntry(BB) && !PredCache.get(BB).empty()) {
      BasicBlock *ImmediateDom = DT->getNode(BB)->getIDom()->getBlock();
      Value *Val = getValueAt(ImmediateDom, Desc, DT);
      Desc.Definitions[BB] = Val;
    } else {
      Desc.Definitions[BB] = UndefValue::get(Desc.Type);
    }
  }
  return Desc.Definitions[BB];
}

// Compute set of blocks where a value is live-in, given definitions and uses.
static void
DetermineLiveInRegions(const SmallPtrSetImpl<BasicBlock *> &UseBlocks,
                       const SmallPtrSetImpl<BasicBlock *> &DefBlocks,
                       SmallPtrSetImpl<BasicBlock *> &LiveIn,
                       PredIteratorCache &PredCache) {
  // Initialize worklist with all blocks that have uses.
  SmallVector<BasicBlock *, 64> Worklist(UseBlocks.begin(), UseBlocks.end());

  while (!Worklist.empty()) {
    BasicBlock *Current = Worklist.pop_back_val();

    // Skip if already processed.
    if (!LiveIn.insert(Current).second)
      continue;

    // Propagate to predecessors unless they define the value.
    for (BasicBlock *Pred : PredCache.get(Current)) {
      if (DefBlocks.count(Pred))
        continue;
      Worklist.push_back(Pred);
    }
  }
}

// Perform full rewrite: insert PHIs, fill them, replace uses.
void SSAUpdaterBulk::RewriteAllUses(DominatorTree *DT,
                                    SmallVectorImpl<PHINode *> *InsertedPHIs) {
  for (auto &Desc : Rewrites) {
    LLVM_DEBUG(dbgs() << "SSAUpdater: processing " << Desc.Uses.size() << " use(s)\n");

    // Step 1: Gather defining and using blocks.
    SmallPtrSet<BasicBlock *, 2> DefSet;
    for (const auto &Pair : Desc.Definitions)
      DefSet.insert(Pair.first);

    SmallPtrSet<BasicBlock *, 2> UseSet;
    for (Use *U : Desc.Uses)
      UseSet.insert(getBlockForUse(U));

    // Step 2: Compute live-in blocks.
    SmallVector<BasicBlock *, 32> IDFBlocks;
    SmallPtrSet<BasicBlock *, 32> LiveInSet;
    DetermineLiveInRegions(UseSet, DefSet, LiveInSet, PredCache);

    // Step 3: Compute iterated dominance frontier.
    ForwardIDFCalculator IDF(*DT);
    IDF.setDefiningBlocks(DefSet);
    IDF.resetLiveInBlocks();
    IDF.setLiveInBlocks(LiveInSet);
    IDF.calculate(IDFBlocks);

    // Step 4: Insert PHI nodes at IDF blocks.
    SmallVector<PHINode *, 4> NewPhis;
    for (BasicBlock *BB : IDFBlocks) {
      IRBuilder<> Builder(BB, BB->begin());
      PHINode *PN = Builder.CreatePHI(Desc.Type, 0, Desc.Name);
      Desc.Definitions[BB] = PN;
      NewPhis.push_back(PN);
      if (InsertedPHIs)
        InsertedPHIs->push_back(PN);
    }

    // Step 5: Populate PHI node operands.
    for (PHINode *PN : NewPhis) {
      BasicBlock *Parent = PN->getParent();
      for (BasicBlock *Pred : PredCache.get(Parent)) {
        PN->addIncoming(getValueAt(Pred, Desc, DT), Pred);
      }
    }

    // Step 6: Replace all recorded uses.
    SmallPtrSet<Use *, 4> Handled;
    for (Use *U : Desc.Uses) {
      if (!Handled.insert(U).second)
        continue;

      BasicBlock *UserBB = getBlockForUse(U);
      Value *Replacement = getValueAt(UserBB, Desc, DT);
      Value *Old = U->get();
      assert(Old && "Use points to null!");

      if (Old != Replacement && Old->hasValueHandle())
        ValueHandleBase::ValueIsRAUWd(Old, Replacement);

      LLVM_DEBUG(dbgs() << "SSAUpdater: replacing " << *Old << " with " << *Replacement << "\n");
      U->set(Replacement);
    }
  }
}

