#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> generate(int rows) {
        std::vector<std::vector<int>> triangle;
        if (rows <= 0) return triangle;

        triangle.push_back({1});
        for (int row = 1; row < rows; ++row) {
            std::vector<int> currentRow;
            currentRow.push_back(1);

            const std::vector<int>& previousRow = triangle[row - 1];
            for (int col = 1; col < static_cast<int>(previousRow.size()); ++col) {
                currentRow.push_back(previousRow[col] + previousRow[col - 1]);
            }
            currentRow.push_back(1);
            triangle.push_back(currentRow);
        }
        return triangle;
    }
};

