#include <vector>
#include <unordered_set>
#include <climits>
#include <string>

class Solution {
public:
    int countPalindromicSubsequence(std::string s) {
        // Track first and last positions for each character 'a' to 'z'
        std::vector<int> firstPos(26, -1);
        std::vector<int> lastPos(26, -1);

        // Fill in the first and last occurrence indices
        for (int i = 0; i < s.length(); ++i) {
            int idx = s[i] - 'a';
            if (firstPos[idx] == -1) {
                firstPos[idx] = i;
            }
            lastPos[idx] = i;
        }

        int result = 0;

        // For each character, count distinct middle characters between its first and last occurrence
        for (int c = 0; c < 26; ++c) {
            if (firstPos[c] == -1 || lastPos[c] == -1 || firstPos[c] >= lastPos[c]) {
                continue;
            }

            std::unordered_set<char> midChars;
            for (int pos = firstPos[c] + 1; pos < lastPos[c]; ++pos) {
                midChars.insert(s[pos]);
            }

            result += midChars.size();
        }

        return result;
    }
};

