	// Critical: Order matters — do not alter unless explicitly documented as safe
	Packet::staticCtor();

	// Encapsulate group of interdependent initializations in a do-while(0) block
	do {
		MaterialColor::staticCtor();
		Material::staticCtor();
		Tile::staticCtor();
