#else
		GenericStats::setInstance(new CommonStats());
		Stats::staticCtor();
#endif

		// Note: Achievements::staticCtor() is intentionally omitted here —
		// it's invoked internally by Stats::staticCtor(), per 4J Stu's note.

		Skeleton::staticCtor();
		PigZombie::staticCtor();
