#include <AdMemoryTracer.h>
#include <REX/REX/LOG.h>
#include <REL/Module.h>

namespace Addictol
{
#if AD_TRACER
	MemoryTracer::MemoryTracer() noexcept
	{
		REX::W32::InitializeCriticalSection(&criticalSection);
	}

	MemoryTracer::~MemoryTracer() noexcept
	{
		REX::W32::DeleteCriticalSection(&criticalSection);
	}

	void MemoryTracer::Add(const void* a_ptr, size_t a_size, const void* a_callerAddress) noexcept
	{
		REX::W32::EnterCriticalSection(&criticalSection);
		const auto baseOffset = REL::Module::GetSingleton()->base();
		data.emplace(
			reinterpret_cast<uintptr_t>(a_ptr),
			MemoryInfo{ a_size, reinterpret_cast<const void*>(reinterpret_cast<uintptr_t>(a_callerAddress) - baseOffset) }
		);
		REX::W32::LeaveCriticalSection(&criticalSection);
	}

	void MemoryTracer::Remove(const void* a_ptr) noexcept
	{
		REX::W32::EnterCriticalSection(&criticalSection);
		data.erase(reinterpret_cast<uintptr_t>(a_ptr));
		REX::W32::LeaveCriticalSection(&criticalSection);
	}

	void MemoryTracer::Dump() noexcept
	{
		REX::W32::EnterCriticalSection(&criticalSection);
		for (const auto& entry : data)
		{
			REX::INFO(
				"[DBG] ptr {:016X} size {} called {:016X}"sv,
				entry.first,
				entry.second.size,
				reinterpret_cast<uintptr_t>(entry.second.addrCall)
			);
		}
		REX::W32::LeaveCriticalSection(&criticalSection);
	}
#endif
}

