  void DeviceProviderProxy::PerformInitialSetup() {
    bool bWineDetected = Util::IsRunningOnWine();

    Util::DriverLog("PlayStation VR2 Toolkit - v{}.{}.{} [{}]",
                    DRIVER_VERSION_MAJOR,
                    DRIVER_VERSION_MINOR,
                    DRIVER_VERSION_PATCH,
                    DRIVER_VERSION_BRANCH);

#if DRIVER_IS_PRERELEASE
    Util::DriverLog("You are using a pre-release build of PlayStation VR2 Toolkit, please report any issues that may occur to the developers!");
#elif DRIVER_IS_EXPERIMENTAL
    Util::DriverLog("You are using an experimental build of PlayStation VR2 Toolkit, please report any issues that may occur to the developers!");
#endif

    if (!HookLib::Initialize()) {
      MessageBoxW(nullptr,
                  L"MinHook initialization failed, please report this to the developers!",
                  L"PlayStation VR2 Toolkit (DriverEx)",
                  MB_ICONERROR | MB_OK);
    }

    if (bWineDetected) {
      Util::DriverLog("PlayStation VR2 Toolkit has detected itself running on Wine, compatibility patches will be applied.");
    }

    ApplyPatches();
    InitializeSystems();
  }

  void DeviceProviderProxy::ApplyPatches() {
    HmdDriverLoader* pHmdDriverLoader = HmdDriverLoader::Instance();
    bool bWineDetected = Util::IsRunningOnWine();

    // Patch: Skip signature verification
    INSTALL_STUB_RET0(reinterpret_cast<void*>(pHmdDriverLoader->GetBaseAddress() + 0x134FF0)); // VrDialogManager::VerifyLibrary

    // Conditional patching for overlay/dialog/detection bypass
    bool bDisableOverlay = VRSettings::GetBool(STEAMVR_SETTINGS_DISABLE_OVERLAY, SETTING_DISABLE_OVERLAY_DEFAULT_VALUE);
    bool bDisableSense   = VRSettings::GetBool(STEAMVR_SETTINGS_DISABLE_SENSE,   SETTING_DISABLE_SENSE_DEFAULT_VALUE);
    bool bDisableDialog  = VRSettings::GetBool(STEAMVR_SETTINGS_DISABLE_DIALOG,  SETTING_DISABLE_DIALOG_DEFAULT_VALUE);

    if (bDisableOverlay || bDisableSense || bWineDetected) {
      INSTALL_STUB(reinterpret_cast<void*>(pHmdDriverLoader->GetBaseAddress() + 0x12F830)); // VrDialogManager::CreateDashboardProcess
    }

    if (bDisableDialog || bDisableSense || bWineDetected) {
      INSTALL_STUB(reinterpret_cast<void*>(pHmdDriverLoader->GetBaseAddress() + 0x130020)); // VrDialogManager::CreateDialogProcess
    }

    CaesarManagerHooks::InstallHooks();
    HmdDeviceHooks::InstallHooks();
    UsbThreadHooks::InstallHooks();
  }

  void DeviceProviderProxy::InitializeSystems() {
    IpcServer::Instance()->Initialize();
    TriggerEffectManager::Instance()->Initialize();
  }

