TEST_CASE("file::lock") {
    // Setup test file with initial content
    auto targetPath = testPath() / "file.txt";
    *file::put(targetPath, "xyz"_tv);

    // Test 1: Read-locked file should block write/update but allow stat/read
    _using(file::FileStream readOnlyStream(targetPath, file::Mode::READ)) {
        REQUIRE_NOTHROW(file::FileStream(targetPath, file::Mode::STAT));
        REQUIRE_NOTHROW(file::FileStream(targetPath, file::Mode::READ));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::WRITE));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::UPDATE));
    }

    // Test 2: Write-locked file should block all access except stat
    _using(file::FileStream writeOnlyStream(targetPath, file::Mode::WRITE)) {
        REQUIRE_NOTHROW(file::FileStream(targetPath, file::Mode::STAT));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::READ));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::WRITE));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::UPDATE));
    }

    // Test 3: Update-locked file should behave like write-locked
    _using(file::FileStream updateOnlyStream(targetPath, file::Mode::UPDATE)) {
        REQUIRE_NOTHROW(file::FileStream(targetPath, file::Mode::STAT));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::READ));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::WRITE));
        REQUIRE_THROWS(file::FileStream(targetPath, file::Mode::UPDATE));
    }
}

#include "comms/torchcomms/ncclx/TorchWorkNCCLX.hpp"

namespace torch::comms {

TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollectLocked() {
  TorchWorkNCCLX::WorkStatus final_status = TorchWorkNCCLX::WorkStatus::COMPLETED;

  // Iterate over all stream queues
  for (auto iter = stream_work_queues_.begin(); iter != stream_work_queues_.end(); ) {
    auto& work_list = iter->second;

    // Process each work item in this stream's queue
    while (!work_list.empty()) {
      auto current_work = work_list.front();
      auto current_status = current_work->checkStatus();

      final_status = current_status;

      if (current_status == TorchWorkNCCLX::WorkStatus::COMPLETED) {
        work_list.pop();
        // Continue processing next item
      } else if (
          current_status == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
          current_status == TorchWorkNCCLX::WorkStatus::ERROR) {
        // Propagate error or timeout immediately
        return current_status;
      } else {
        // Work is not yet ready; stop scanning this stream's queue
        break;
      }
    }

    // After processing, remove empty stream queues from map
    if (work_list.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return final_status;
}

// Thread-safe wrapper using mutex lock
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  return garbageCollectLocked();
}

// Finalize: drain remaining work and clean up resources
TorchWorkNCCLX::WorkStatus TorchWorkNCCLXQueue::finalize() {
  // Defensive locking even if watchdog thread is likely already joined
  std::lock_guard<std::mutex> guard(work_queues_mutex_);

  TorchWorkNCCLX::WorkStatus result = TorchWorkNCCLX::WorkStatus::COMPLETED;

  // Keep garbage-collecting until queue is empty or terminal state reached
  while (!stream_work_queues_.empty()) {
    result = garbageCollectLocked();
    if (result == TorchWorkNCCLX::WorkStatus::ERROR ||
        result == TorchWorkNCCLX::WorkStatus::TIMEDOUT ||
        result == TorchWorkNCCLX::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure no dangling references remain — avoid leaks
  stream_work_queues_.clear();
  return result;
}

// Enqueue new work associated with a given CUDA stream
void TorchWorkNCCLXQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkNCCLX> work,
    cudaStream_t stream_id) {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  stream_work_queues_[stream_id].push(std::move(work));
}

} // namespace torch::comms

