#include <boost/asio/post.hpp>
#include <thread>

namespace examples {

// Parse key=value pair into TXT record; returns false if input is empty or malformed
bool parse_key_value_into_txt(rav::dnssd::TxtRecord& txt, const std::string& raw) {
    if (raw.empty()) return false;

    auto eq_pos = raw.find('=');
    if (eq_pos != std::string::npos) {
        txt[raw.substr(0, eq_pos)] = raw.substr(eq_pos + 1);
    } else {
        // If no '=', treat entire string as key with empty value
        txt[raw] = "";
    }
    return true;
}

} // namespace examples

int main(int argc, char* argv[]) {
    rav::set_log_level_from_env();
    rav::do_system_checks();

    std::vector<std::string> cmdline_args;
    for (int idx = 1; idx < argc; ++idx) {
        cmdline_args.push_back(argv[idx]);
    }

    // Validate minimum required arguments: service type and port
    if (cmdline_args.size() < 2) {
        std::cerr << "Usage: <service_type> <port> [key1=value1] [key2=value2] ..." << std::endl;
        return -1;
    }

    // Extract and validate port number
    int raw_port = 0;
    try {
        raw_port = std::stoi(cmdline_args[1]);
    } catch (...) {
        std::cerr << "Error: invalid port '" << cmdline_args[1] << "'" << std::endl;
        return -1;
    }

    // Build TXT record from remaining arguments
    rav::dnssd::TxtRecord txt_entries;
    for (size_t i = 2; i < cmdline_args.size(); ++i) {
        examples::parse_key_value_into_txt(txt_entries, cmdline_args[i]);
    }

    // Initialize ASIO context and advertiser
    boost::asio::io_context io_ctx;
    auto advertiser_opt = rav::dnssd::Advertiser::create(io_ctx);
    if (!advertiser_opt) {
        RAV_LOG_ERROR("No DNS-SD backend available on this platform");
        return -1;
    }

    auto& advertiser = *advertiser_opt;

    // Set up callbacks
    advertiser.on_error = [](const std::string& msg) {
        RAV_LOG_ERROR("DNS-SD error: {}", msg);
    };

    advertiser.on_name_conflict = [](const char* svc_type, const char* svc_name) {
        RAV_LOG_CRITICAL("Name conflict detected: {} / {}", svc_type, svc_name);
    };

    // Register service
    const auto reg_id = advertiser.register_service(
        cmdline_args[0],                     // service type
        "Example Service",                   // instance name
        nullptr,                             // host (default)
        static_cast<uint16_t>(raw_port),     // port
        txt_entries,                         // initial TXT
        true,                                // enable wildcard subtypes
        true                                 // enable update support
    );

    // Run ASIO in background thread
    std::thread worker([&io_ctx] {
        io_ctx.run();
    });

    RAV_LOG_INFO("Service registered. Commands: 'q' to quit, 'r' to unregister, 'key=value' to update TXT");

    std::string input_line;
    while (true) {
        std::getline(std::cin, input_line);
        if (input_line == "q" || input_line == "Q") {
            break;
        }
        if (input_line == "r" || input_line == "R") {
            advertiser.unregister_service(reg_id);
            continue;
        }

        try {
            rav::dnssd::TxtRecord new_entry;
            if (examples::parse_key_value_into_txt(new_entry, input_line)) {
                // Post update to ASIO thread to avoid race conditions
                boost::asio::post(io_ctx, [&advertiser, reg_id, new_entry = std::move(new_entry)]() mutable {
                    advertiser.update_txt_record(reg_id, new_entry);
                    RAV_LOG_INFO("TXT record updated with: {}", input_line);
                });
            }
        } catch (const std::exception& ex) {
            RAV_LOG_ERROR("Exception during TXT update: {}", ex.what());
        }
    }

    // Cleanup
    io_ctx.stop();
    worker.join();
    std::cout << "Terminated." << std::endl;
    return 0;
}

