#include <mbedtls/md5.h>
#include <mbedtls/sha1.h>

// Helper macros assumed to be defined elsewhere:
// #define SMEMCPY memcpy
// #define MEMCPY  memcpy

/**
 * Convert a password into an MD5-based key using SNMPv3 algorithm.
 * Implements RFC 3414 Section A.2.1 (Password-to-Key for MD5).
 */
void
snmpv3_password_to_key_md5(
  const u8_t *pwd,         /* IN: user's password string */
  size_t      pwd_len,     /* IN: length of password in bytes */
  const u8_t *eng_id,      /* IN: pointer to snmpEngineID */
  u8_t        eng_len,     /* IN: length of snmpEngineID */
  u8_t       *out_key)     /* OUT: 16-byte buffer for resulting key */
{
  mbedtls_md5_context ctx;
  u8_t temp_buf[64];
  u32_t idx = 0;
  u8_t j;
  u32_t total_bytes = 0;

  mbedtls_md5_init(&ctx);
  mbedtls_md5_starts(&ctx);

  /****************************************************/
  /* Process 1 MiB (1,048,576 bytes) of repeated data */
  /****************************************************/
  while (total_bytes < 1048576) {
    u8_t *write_ptr = temp_buf;
    for (j = 0; j < 64; ++j) {
      // Cycle through password characters as needed
      *write_ptr++ = pwd[idx++ % pwd_len];
    }
    mbedtls_md5_update(&ctx, temp_buf, 64);
    total_bytes += 64;
  }

  mbedtls_md5_finish(&ctx, out_key);  // Finalize MD5 digest
  mbedtls_md5_free(&ctx);

  /********************************************************/
  /* Localize key using engine ID: [key || engID || key] */
  /********************************************************/
  SMEMCPY(temp_buf, out_key, 16);
  MEMCPY(temp_buf + 16, eng_id, eng_len);
  SMEMCPY(temp_buf + 16 + eng_len, out_key, 16);

  mbedtls_md5_init(&ctx);
  mbedtls_md5_starts(&ctx);
  mbedtls_md5_update(&ctx, temp_buf, 32 + eng_len);
  mbedtls_md5_finish(&ctx, out_key);
  mbedtls_md5_free(&ctx);
}

/**
 * Convert a password into a SHA-1-based key using SNMPv3 algorithm.
 * Implements RFC 3414 Section A.2.2 (Password-to-Key for SHA-1).
 */
void
snmpv3_password_to_key_sha(
  const u8_t *pwd,          /* IN: user's password string */
  size_t      pwd_len,      /* IN: length of password in bytes */
  const u8_t *eng_id,       /* IN: pointer to snmpEngineID */
  u8_t        eng_len,      /* IN: length of snmpEngineID */
  u8_t       *out_key)      /* OUT: 20-byte buffer for resulting key */
{
  mbedtls_sha1_context ctx;
  u8_t temp_buf[72];
  u32_t idx = 0;
  u8_t j;
  u32_t total_bytes = 0;

  mbedtls_sha1_init(&ctx);
  mbedtls_sha1_starts(&ctx);

  /******************************************************/
  /* Accumulate 1 MiB (1,048,576 bytes) of password data */
  /******************************************************/
  while (total_bytes < 1048576) {
    u8_t *wr_ptr = temp_buf;
    for (j = 0; j < 64; ++j) {
      // Wrap around password if exhausted
      *wr_ptr++ = pwd[idx++ % pwd_len];
    }
    mbedtls_sha1_update(&ctx, temp_buf, 64);
    total_bytes += 64;
  }

  mbedtls_sha1_finish(&ctx, out_key);  // Finalize SHA-1 digest
  mbedtls_sha1_free(&ctx);

  /*********************************************************/
  /* Localize key using engine ID: [key || engID || key]   */
  /* Buffer size must accommodate: 20 + eng_len + 20 bytes */
  /*********************************************************/
  SMEMCPY(temp_buf, out_key, 20);
  MEMCPY(temp_buf + 20, eng_id, eng_len);
  SMEMCPY(temp_buf + 20 + eng_len, out_key, 20);

  mbedtls_sha1_init(&ctx);
  mbedtls_sha1_starts(&ctx);
  mbedtls_sha1_update(&ctx, temp_buf, 40 + eng_len);
  mbedtls_sha1_finish(&ctx, out_key);
  mbedtls_sha1_free(&ctx);
}

