#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    long long minimumRemoval(std::vector<int>& beans) {
        std::sort(beans.begin(), beans.end());

        long long totalSum = 0;
        for (int bean : beans) {
            totalSum += bean;
        }

        long long minRemovals = LLONG_MAX;
        int size = beans.size();

        for (int index = 0; index < size; ++index) {
            long long currentBeanValue = beans[index];
            long long remainingBeansCount = size - index;
            long long targetTotal = currentBeanValue * remainingBeansCount;
            long long removalsNeeded = totalSum - targetTotal;

            if (removalsNeeded < minRemovals) {
                minRemovals = removalsNeeded;
            }
        }

        return minRemovals;
    }
};

