using namespace llvm;

// Removes functions that are not part of the target chunks
static void extractFunctionsFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();

  // Collect candidate functions for removal
  SmallPtrSet<Constant *, 8> FunctionsToDrop;

  for (auto &Func : Program.functions()) {
    // Skip intrinsics unless they're unused and have no alias/block address references
    bool ShouldConsider = !Func.isIntrinsic() || Func.use_empty();

    if (ShouldConsider && !hasAliasOrBlockAddressUse(Func) && !O.shouldKeep()) {
      FunctionsToDrop.insert(&Func);
    }
  }

  // Remove from used lists first
  removeFromUsedLists(Program, [&](Constant *C) -> bool {
    return FunctionsToDrop.contains(C);
  });

  // Clear function bodies in batch to minimize external references
  for (Constant *F : FunctionsToDrop) {
    F->dropAllReferences();
  }

  // Final cleanup: replace remaining uses and erase functions
  for (Constant *F : FunctionsToDrop) {
    // Substitute with default value for type
    F->replaceAllUsesWith(getDefaultValue(F->getType()));

    // Remove function from module entirely
    cast<Function>(F)->eraseFromParent();
  }
}

void llvm::reduceFunctionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractFunctionsFromModule, "Eliminating Functions");
}

#include "ReduceGlobalVars.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"

using namespace llvm;

// Helper function to determine if a global variable must be preserved unconditionally
static bool isEssentialGlobal(const GlobalVariable &GV) {
  StringRef name = GV.getName();
  return name == "llvm.used" || name == "llvm.compiler.used";
}

/// Eliminates global variables not belonging to the selected test chunks
static void pruneUnusedGlobals(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &M = WorkItem.getModule();

  // Collect global variables that should be retained
  std::vector<Constant *> candidatesToRetain;
  for (auto &G : M.globals()) {
    if (isEssentialGlobal(G) || O.shouldKeep())
      candidatesToRetain.push_back(&G);
  }

  // Convert vector to DenseSet for efficient lookup
  DenseSet<Constant *> keepSet(candidatesToRetain.begin(), candidatesToRetain.end());

  // Identify globals to remove: those not in keepSet
  DenseSet<Constant *> removalList;
  for (auto &G : M.globals()) {
    if (!keepSet.count(&G))
      removalList.insert(&G);
  }

  // Clean up references from llvm.used / llvm.compiler.used lists
  removeFromUsedLists(M,
    [&removalList](Constant *C) { return removalList.contains(C); });

  // Replace and erase removed globals
  for (auto *GV : removalList) {
    GV->replaceAllUsesWith(getDefaultValue(GV->getType()));
    cast<GlobalVariable>(GV)->eraseFromParent();
  }
}

void llvm::reduceGlobalsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, pruneUnusedGlobals, "Eliminating Unused GlobalVariables");
}

