using namespace std;

int main() {
    multimap<string, int> devicePrices; // multimap storing device names and their prices

    // Insert initial device-price pairs using insert()
    devicePrices.insert(make_pair("headphones", 100));
    devicePrices.insert(make_pair("mouse", 200));
    devicePrices.insert(make_pair("keyboard", 300));
    devicePrices.insert(make_pair("monitor", 400));
    devicePrices.insert(make_pair("monitor", 500));
    devicePrices.insert(make_pair("monitor", 600));
    devicePrices.insert(make_pair("monitor", 700));

    // Add more entries using emplace()
    devicePrices.emplace("tablet", 400);
    devicePrices.emplace("tablet", 500);
    devicePrices.emplace("tablet", 600);

    // Display all entries in the multimap
    for (auto entry : devicePrices) {
        cout << entry.first << " " << entry.second << endl;
    }
    cout << endl;

    // Output container properties
    cout << devicePrices.size() << endl;       // number of elements
    cout << devicePrices.max_size() << endl;   // maximum possible size
    cout << devicePrices.empty() << endl;      // 1 if empty, 0 otherwise

    // Count occurrences of a specific key
    cout << devicePrices.count("headphones") << endl;

    // Remove one occurrence of "headphones" using iterator
    auto it = devicePrices.find("headphones");
    if (it != devicePrices.end()) {
        devicePrices.erase(it);
    }

    // Display remaining entries after first erase
    for (auto entry : devicePrices) {
        cout << entry.first << " " << entry.second << endl;
    }
    cout << endl;

    // Attempt to remove all occurrences of "headphones" again
    devicePrices.erase("headphones");

    // Display final state of the multimap
    for (auto entry : devicePrices) {
        cout << entry.first << " " << entry.second << endl;
    }
    cout << endl;

    return 0;
}

#include <iostream>

int main() {
    // Construct a grid that forces agents to traverse a long snake-like path,
    // maximizing the expected synchronization time by simulating a 1D random walk.
    // For a 20x20 grid, we create a winding corridor using alternating row directions.

    std::cout << "20 20" << std::endl;

    for (int row = 0; row < 20; ++row) {
        if (row % 2 == 0) {
            // Even-indexed rows: full horizontal corridors
            std::cout << "11111111111111111111" << std::endl;
        } else {
            // Odd-indexed rows: only one opening to enable turning
            // Alternating connection points create the serpentine path
            if ((row - 1) % 4 == 0) {
                // Right-side connector (e.g., row 1, 5, 9, ...)
                std::cout << "00000000000000000001" << std::endl;
            } else {
                // Left-side connector (e.g., row 3, 7, 11, ...)
                std::cout << "10000000000000000000" << std::endl;
            }
        }
    }

    return 0;
}

