XmlPlaneWriter::XmlPlaneWriter(QFile &XFile) : XflXmlWriter(XFile)
{
}

void XmlPlaneWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
}

void XmlPlaneWriter::writeXMLPlane(PlaneXfl const &plane, bool bWriteFoils)
{
    writeStartDocument();
    {
        writeHeader();
        writeStartElement("xflplane");
        writeAttribute("version", "1.0");

        // Add informational comments
        writeComment("All field names are case-insensitive for user convenience, deviating from strict XML standards");
        writeComment("Missing fields will automatically use predefined default values");

        writeUnits();

        writeStartElement("Plane");
        {
            // Write basic plane information
            writeTextElement("Name", plane.name());

            if (!plane.description().isEmpty()) {
                writeTextElement("Description", plane.description());
            }

            // Write styling information
            writeTheStyle(plane.theStyle());

            // Handle point masses and inertia data
            if (plane.pointMassCount() > 0) {
                writeStartElement("Inertia");
                {
                    for (int ipm = 0; ipm < plane.pointMassCount(); ++ipm) {
                        writePointMass(plane.pointMassAt(ipm));
                    }
                }
                writeEndElement();
            }

            // Process fuselages
            for (int ifuse = 0; ifuse < plane.nFuse(); ++ifuse) {
                if (plane.fuseAt(ifuse) && plane.fuseAt(ifuse)->isXflType()) {
                    FuseXfl const* pFuseXfl = dynamic_cast<FuseXfl const*>(plane.fuseAt(ifuse));
                    writeXflFuse(*pFuseXfl, plane.fusePos(0));
                }
            }

            // Process wings
            for (int iw = 0; iw < plane.nWings(); ++iw) {
                if (plane.wingAt(iw)) {
                    writeWing(*plane.wingAt(iw), 
                              plane.wingLE(iw), 
                              plane.rxAngle(iw), 
                              plane.ryAngle(iw), 
                              bWriteFoils);
                }
            }
        }
        writeEndElement(); // End Plane element
    }
    writeEndDocument();
}

