FTakeRecorderStateProvider::FTakeRecorderStateProvider()
{
	// Register callback for when the take recorder is initialized
	UTakeRecorder::OnRecordingInitialized().AddRaw(this, &FTakeRecorderStateProvider::HandleRecorderInit);
}

void FTakeRecorderStateProvider::HandleRecorderInit(UTakeRecorder* RecorderInstance)
{
	if (RecorderInstance)
	{
		// Set up callbacks for recording lifecycle events
		RecorderInstance->OnRecordingStarted().AddRaw(this, &FTakeRecorderStateProvider::HandleRecordingBegin);
		RecorderInstance->OnRecordingCancelled().AddRaw(this, &FTakeRecorderStateProvider::HandleRecordingEnd);
		RecorderInstance->OnRecordingFinished().AddRaw(this, &FTakeRecorderStateProvider::HandleRecordingEnd);
	}

	// Initialize state to exit
	CurrentState = EStageCriticalStateEvent::Exit;
}

void FTakeRecorderStateProvider::HandleRecordingBegin(UTakeRecorder* RecorderInstance)
{
	// Only transition if currently in Exit state
	if (CurrentState == EStageCriticalStateEvent::Exit)
	{
		TakeName = RecorderInstance->GetSequence()->GetFName();
		CurrentState = EStageCriticalStateEvent::Enter;

		// Send reliable message indicating critical state entry
		IStageDataProvider::SendMessage<FCriticalStateProviderMessage>(
			EStageMessageFlags::Reliable, 
			CurrentState, 
			TakeName
		);
	}
}

void FTakeRecorderStateProvider::HandleRecordingEnd(UTakeRecorder* /*RecorderInstance*/)
{
	// Only transition if currently in Enter state
	if (CurrentState == EStageCriticalStateEvent::Enter)
	{
		CurrentState = EStageCriticalStateEvent::Exit;

		// Send reliable message indicating critical state exit
		IStageDataProvider::SendMessage<FCriticalStateProviderMessage>(
			EStageMessageFlags::Reliable, 
			CurrentState, 
			TakeName
		);
	}
}
#endif // WITH_EDITOR

