#include <vector>
using namespace std;

// LeetCode 733: Flood Fill - Alternative implementation using iterative DFS with explicit stack
class Solution {
public:
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int newColor) {
        // If the new color is the same as the original, no changes needed
        if (image[sr][sc] == newColor) {
            return image;
        }

        int rows = image.size();
        int cols = image[0].size();
        int originalColor = image[sr][sc];

        // Use a stack for depth-first search
        vector<pair<int, int>> stack;
        stack.push_back({sr, sc});

        while (!stack.empty()) {
            auto [row, col] = stack.back();
            stack.pop_back();

            // Check boundaries and color match
            if (row < 0 || row >= rows || col < 0 || col >= cols || image[row][col] != originalColor) {
                continue;
            }

            // Update the color
            image[row][col] = newColor;

            // Add neighboring cells to the stack
            stack.push_back({row + 1, col});
            stack.push_back({row - 1, col});
            stack.push_back({row, col + 1});
            stack.push_back({row, col - 1});
        }

        return image;
    }
};

