// Replaced bool.h with standard header and renamed some types for clarity
namespace wasm_eh {

// Renamed exception-related structures and functions for Type III clone
struct Unwind_Exception;
struct Unwind_Context;

enum Unwind_Reason_Code {
  _URC_NO_REASON = 0,
  _URC_FOREIGN_EXCEPTION_CAUGHT = 1,
  _URC_HANDLER_FOUND = 2,
  _URC_INSTALL_CONTEXT = 3,
  _URC_CONTINUE_UNWIND = 4
};

enum Unwind_Action {
  _UA_SEARCH_PHASE = 1,
  _UA_CLEANUP_PHASE = 2,
  _UA_HANDLER_FRAME = 4,
  _UA_FORCE_UNWIND = 8
};

// Renamed context structure to avoid direct duplication
struct LandingPadContext {
  // Input: landing pad index and LSDA address
  std::uintptr_t lp_index; 
  std::uintptr_t lsda_addr;      

  // Output: selector value computed by personality function
  std::uintptr_t sel_value; 
};

// Thread-local storage for landing pad context (same semantics)
thread_local LandingPadContext current_lpad_context;

// Personality function declaration (renamed symbol)
_Unwind_Reason_Code __cxx_personality_wasm(int ver, _Unwind_Action acts,
                                           std::uint64_t exc_class,
                                           Unwind_Exception *exc_obj,
                                           Unwind_Context *ctx);

// Replacement for _Unwind_CallPersonality – renamed logic and variables
_Unwind_Reason_Code invoke_personality(void *exc_ptr) {
  Unwind_Exception *exc_obj = static_cast<Unwind_Exception*>(exc_ptr);

  // Reset selector before calling personality
  current_lpad_context.sel_value = 0;

  // Perform only cleanup phase (no two-phase unwinding in WebAssembly)
  return __cxx_personality_wasm(
      1, _UA_SEARCH_PHASE, exc_obj->exception_class, exc_obj,
      reinterpret_cast<Unwind_Context*>(&current_lpad_context));
}

// Replacement for _Unwind_RaiseException – uses same mechanism but renamed
void raise_exception(Unwind_Exception *exc_obj) {
  // Use WebAssembly exception throwing instruction
  __builtin_wasm_throw(0, exc_obj);
}

// Replacement for _Unwind_DeleteException – renamed function and parameters
void delete_exception(Unwind_Exception *exc_obj) {
  if (exc_obj->exception_cleanup != nullptr) {
    (*exc_obj->exception_cleanup)(_URC_FOREIGN_EXCEPTION_CAUGHT, exc_obj);
  }
}

// Replacement for _Unwind_SetGR – updated parameter names and logic
void set_general_register(Unwind_Context *ctx, int reg_idx, std::uintptr_t val) {
  // Only register index 1 is used for selector
  if (reg_idx == 1) {
    reinterpret_cast<LandingPadContext*>(ctx)->sel_value = val;
  }
}

// Replacement for _Unwind_GetIP – adjusted computation
std::uintptr_t get_instruction_pointer(Unwind_Context *ctx) {
  // Adjust landing pad index to produce 1-based IP value
  std::uintptr_t ip_val = reinterpret_cast<LandingPadContext*>(ctx)->lp_index + 2;
  return ip_val;
}

// Placeholder for unused _Unwind_SetIP
void set_instruction_pointer(Unwind_Context *, std::uintptr_t) {}

// Replacement for _Unwind_GetLanguageSpecificData – renamed fields
std::uintptr_t get_language_specific_data(Unwind_Context *ctx) {
  return reinterpret_cast<LandingPadContext*>(ctx)->lsda_addr;
}

// Placeholder for unused _Unwind_GetRegionStart
std::uintptr_t get_region_start(Unwind_Context *) {
  return 0;
}

} // namespace wasm_eh

// Conditional compilation for non-exception builds
#ifdef __EMSCRIPTEN__
void raise_exception_with_abort(wasm_eh::Unwind_Exception *exc_obj) {
  // Fallback behavior when exceptions are disabled
  std::abort();
}
