int main()
{
    // Initialize a 3D visualization window with specified dimensions and title
    mplot::Visual<mplot::gl::version_3_1_es> scene(1024, 768, "mplot::GraphVisual on Raspberry Pi");

    // Construct a GraphVisual instance for double-precision data, positioned at origin
    auto graph = std::make_unique<mplot::GraphVisual<double, mplot::gl::version_3_1_es>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Establish the parent-child relationship between the visual scene and graph model
    scene.bindmodel(graph);

