    sm::vvec<double> abscissae;

    // Generate evenly spaced points from -0.5 to 0.8 across 14 samples
    abscissae.linspace(-0.5, 0.8, 14);

    // Configure the graph to display cubic function y = x^3
    graph->setdata(abscissae, abscissae.pow(3));

    // Precompute OpenGL vertex data required for rendering
    graph->finalize();

    // Integrate the graph into the scene, transferring ownership of the model
    scene.addVisualModel(graph);

    // Enter interactive rendering loop until user exits via Ctrl-q
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' destructor handles the owned GraphVisual resource
    return 0;
}

