namespace tpa {

void TransferFunction::evalEntryNode(const ProgramPoint &pp,
                                     EvalResult &evalResult) {
  // Ensure local state is properly initialized before proceeding
  assert(localState != nullptr);

  // Propagate top-level and memory-level successors from current point
  addTopLevelSuccessors(pp, evalResult);
  addMemLevelSuccessors(pp, *localState, evalResult);

  // To ensure the analysis doesn't prematurely converge before return edges 
  // are fully processed, we proactively enqueue the function's exit node 
  // upon entering any function that may return.
  //
  // Note: This unconditional enqueue is intentional. The SemiSparsePropagator
  // maintains a memoization cache (Memo) and will only re-evaluate the exit 
  // node if its store state has actually changed. Thus, redundant work is 
  // avoided through memoization while preserving correctness and termination.
  const auto &cfg = pp.getCFGNode()->getCFG();
  if (!cfg.hasNoReturnPath()) {
    evalResult.enqueueTopLevelProgramPoint(
        ProgramPoint(pp.getContext(), cfg.getExitBlock()));
  }
}

} // namespace tpa

