// Global flag to signal worker threads to stop
static std::atomic<bool> gRunning{true};

// Target function for uprobe testing — must be noinline and extern "C"
extern "C" __attribute__((noinline)) void target_func() {
    static volatile int dummy = 0;
    (void)dummy; // Prevent optimization
}

// Caller functions — each provides a unique call site for stack diversity
__attribute__((noinline)) void WorkerLoopA() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

__attribute__((noinline)) void WorkerLoopB() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

__attribute__((noinline)) void WorkerLoopC() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

__attribute__((noinline)) void WorkerLoopD() {
    while (gRunning.load(std::memory_order_relaxed)) {
        target_func();
    }
}

using TWorkerFn = void (*)();

// Array of distinct worker entry points
static constexpr std::array<TWorkerFn, 4> Workers = {
    WorkerLoopA,
    WorkerLoopB,
    WorkerLoopC,
    WorkerLoopD,
};

// Bind current thread to specified CPU core
static void AffinityToCore(int coreId) {
    cpu_set_t mask;
    CPU_ZERO(&mask);
    CPU_SET(coreId, &mask);
    if (sched_setaffinity(0, sizeof(mask), &mask) != 0) {
        perror("sched_setaffinity");
        // Continue execution even on failure
    }
}

// Query number of online CPUs
static int OnlineCpuCount() {
    long n = sysconf(_SC_NPROCESSORS_ONLN);
    if (n <= 0) {
        throw std::runtime_error("Failed to determine number of CPUs");
    }
    return static_cast<int>(n);
}

int main(int argc, const char* argv[]) {
    int runTimeSec = 30;
    int threadCount = 0;

    NLastGetopt::TOpts options;
    options.AddLongOption("duration", "Test duration in seconds")
        .RequiredArgument("SECONDS")
        .DefaultValue("30")
        .StoreResult(&runTimeSec);

    options.AddLongOption("threads", "Number of worker threads (0 = auto, defaults to CPU count)")
        .RequiredArgument("COUNT")
        .DefaultValue("0")
        .StoreResult(&threadCount);

    NLastGetopt::TOptsParseResult(&options, argc, argv);

    const int cpus = OnlineCpuCount();
    const int workers = (threadCount > 0) ? threadCount : cpus;

    std::vector<std::thread> pool;
    pool.reserve(workers);

    for (int i = 0; i < workers; ++i) {
        int core = i % cpus;
        int fnIdx = i % static_cast<int>(Workers.size());
        pool.emplace_back([core, fnIdx]() {
            AffinityToCore(core);
            Workers[fnIdx]();
        });
    }

    // Allow workload to run for configured time
    sleep(runTimeSec);

    // Signal termination and wait for completion
    gRunning.store(false, std::memory_order_relaxed);
    for (auto& th : pool) {
        th.join();
    }

    return 0;
}

