class Solution {
  public:
    // Calculate minimum moves for Tower of Hanoi using iterative approach
    int towerOfHanoi(int n, int from, int to, int aux) {
        // Using the mathematical formula: 2^n - 1
        if (n <= 0) {
            return 0;
        }

        int moves = 1;
        for (int i = 1; i < n; ++i) {
            moves = moves * 2 + 1;
        }

        return moves;
    }
};

