namespace ap::time {

// Format a system timestamp into a human-readable string using a format specification
Text formatDateTime(SystemStamp time, const Text &formatSpec) noexcept {
    // Convert to seconds precision before formatting
    auto secTime = std::chrono::time_point_cast<std::chrono::seconds>(time);
    return date::format(formatSpec, secTime);
}

// Parse a formatted date-time string back into a SystemStamp
ErrorOr<SystemStamp> parseDateTime(const Text &inputStr, const Text &formatSpec) noexcept {
    std::string buffer{inputStr};
    std::istringstream stream(buffer);

    // Use milliseconds resolution for intermediate parsing
    date::sys_time<std::chrono::milliseconds> parsedTime;

    // Workaround: Avoid ambiguity between date::parse and std::chrono::from_stream in newer VS versions
    // Instead of relying on date::parse, manually invoke from_stream with explicit parameters
    // This avoids compilation errors introduced by stricter C++20 compliance in MSVC 16.10+
    auto fmtStr = formatSpec.to_string(); // assuming Text has .to_string()
    auto result = date::from_stream(stream, fmtStr.c_str(), parsedTime,
                                    /* abbrev */ nullptr, /* offset */ nullptr);

    if (!stream || result.fail()) {
        return Error{
            Ec::StringParse,
            "Failed to parse date/time: '" + inputStr.to_string() +
                "' using format: '" + formatSpec.to_string() + "'"
        };
    }

    return SystemStamp{parsedTime};
}

