#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    if (!(cin >> s)) return 0;

    int n = s.length();

    // Collect positions of '1's with sentinels
    vector<int> ones_positions;
    ones_positions.reserve(n + 2);
    ones_positions.push_back(-1);

    for (int i = 0; i < n; ++i) {
        if (s[i] == '1') {
            ones_positions.push_back(i);
        }
    }
    ones_positions.push_back(n);

    int count_ones = ones_positions.size() - 2;
    long long total_zeros = n - count_ones;

    // Compute gaps between consecutive '1's (including before first and after last)
    vector<long long> gaps;
    gaps.reserve(count_ones + 1);
    for (size_t idx = 0; idx < ones_positions.size() - 1; ++idx) {
        gaps.push_back(ones_positions[idx + 1] - ones_positions[idx] - 1);
    }

    long long result = 0;

    // Try all possible numbers of '1's in substring (k)
    for (int k = 1; ; ++k) {
        long long required_zeros = 1LL * k * k;

        // Early termination conditions
        if (required_zeros > total_zeros) break;
        if (required_zeros + k > n) break;

        // Calculate initial inner zeros for the first window of k ones
        long long inner_zeros = 0;
        for (int j = 1; j < k; ++j) {
            inner_zeros += gaps[j];
        }

        // Slide window over all possible blocks of k ones
        for (int start_idx = 0; start_idx <= count_ones - k; ++start_idx) {
            long long needed_ext = required_zeros - inner_zeros;

            if (needed_ext >= 0) {
                // Determine valid range for left extension
                long long min_left = (needed_ext > gaps[start_idx + k]) ? (needed_ext - gaps[start_idx + k]) : 0;
                long long max_left = (needed_ext < gaps[start_idx]) ? needed_ext : gaps[start_idx];

                if (max_left >= min_left) {
                    result += (max_left - min_left + 1);
                }
            }

            // Update inner_zeros for next window
            if (start_idx < count_ones - k) {
                inner_zeros -= gaps[start_idx + 1];
                inner_zeros += gaps[start_idx + k];
            }
        }
    }

    cout << result << endl;
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long target_paths;
    if (!(std::cin >> target_paths)) return 0;

    const int GRID_SIZE = 65;
    std::vector<std::vector<int>> grid(GRID_SIZE, std::vector<int>(GRID_SIZE, 0));

    // Construct base snake pattern: alternating left/right blocks per row
    for (int row = 1; row <= GRID_SIZE; ++row) {
        if (row % 2 == 1) {
            // Odd rows: fill from left side up to 'row' columns
            for (int col = 0; col < row; ++col) {
                grid[row-1][col] = 1;
            }
        } else {
            // Even rows: fill from right side up to 'row' columns
            for (int col = GRID_SIZE - row; col < GRID_SIZE; ++col) {
                grid[row-1][col] = 1;
            }
        }
    }

    // Adjust paths based on binary representation of (target_paths - 1)
    long long remaining = target_paths - 1;

    for (int row = 2; row <= GRID_SIZE; ++row) {
        if (remaining & 1LL) {
            if (row % 2 == 1) {
                // For odd rows, extend to the right beyond the initial block
                for (int col = row; col < GRID_SIZE; ++col) {
                    grid[row-1][col] = 1;
                }
            } else {
                // For even rows, extend to the left beyond the initial block
                for (int col = 0; col < GRID_SIZE - row; ++col) {
                    grid[row-1][col] = 1;
                }
            }
        }
        remaining >>= 1;
        if (remaining == 0) break;
    }

    std::cout << GRID_SIZE << "\n";
    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            std::cout << grid[i][j];
            if (j + 1 < GRID_SIZE) std::cout << " ";
        }
        std::cout << "\n";
    }

    return 0;
}

