#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Define target median positions
    int m1_target = n / 2;
    int m2_target = n / 2 + 1;

    // Initialize candidate list with indices 1..n
    vector<int> candidates(n);
    iota(candidates.begin(), candidates.end(), 1);

    // Store a known (small, large) pair for padding when needed
    vector<int> safe_pair;

    // Random generator setup
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    while (candidates.size() > 2) {
        // Shuffle indices to randomly select two distinct elements
        vector<int> idxs(candidates.size());
        iota(idxs.begin(), idxs.end(), 0);
        shuffle(idxs.begin(), idxs.end(), rng);

        int i1 = idxs[0], i2 = idxs[1];
        int val1 = candidates[i1], val2 = candidates[i2];

        vector<int> query;

        if (candidates.size() > 4) {
            // Build query excluding the two selected values
            for (size_t i = 0; i < candidates.size(); ++i) {
                if (i != i1 && i != i2) {
                    query.push_back(candidates[i]);
                }
            }
        } else {
            // Exactly 4 candidates left: need padding to make query size 4
            for (size_t i = 0; i < candidates.size(); ++i) {
                if (i != i1 && i != i2) {
                    query.push_back(candidates[i]);
                }
            }
            // Add previously stored safe pair as padding
            query.push_back(safe_pair[0]);
            query.push_back(safe_pair[1]);
        }

        // Output query
        cout << "0 " << query.size();
        for (int x : query) cout << " " << x;
        cout << endl;

        // Read response
        int resp_m1, resp_m2;
        cin >> resp_m1 >> resp_m2;

        if (resp_m1 == m1_target && resp_m2 == m2_target) {
            if (candidates.size() > 4) {
                // The excluded pair is confirmed to be one small and one large — safe to discard
                safe_pair = {val1, val2};

                // Update candidates by removing the two tested values
                vector<int> remaining;
                for (size_t i = 0; i < candidates.size(); ++i) {
                    if (i != i1 && i != i2) {
                        remaining.push_back(candidates[i]);
                    }
                }
                candidates = remaining;
            } else {
                // Found the medians among the kept ones
                vector<int> result;
                for (size_t i = 0; i < candidates.size(); ++i) {
                    if (i != i1 && i != i2) {
                        result.push_back(candidates[i]);
                    }
                }
                cout << "1 " << result[0] << " " << result[1] << endl;
                return 0;
            }
        }
        // If not successful, loop again to try another random pair
    }

    return 0;
}

