// Helper to determine if type is floating-point (FP) or integer
inline bool isFPType(Type* t) {
    return t->isHalfTy() || t->isFloatTy() || t->isDoubleTy() || t->isFP128Ty();
}

LLVMFunction::LLVMFunction(bool t_shiftToMultiply, context &t_scx,
                           Function *t_contents)
    : shiftToMultiply(t_shiftToMultiply), scx(t_scx), contents(t_contents),
      varCounter(0), extraVariables(t_scx) {
  scx.set_rounding_mode(RNE);

  // Iterate over function arguments using index-based traversal for variety
  auto argIt = contents->arg_begin();
  auto argEnd = contents->arg_end();
  while (argIt != argEnd) {
    Argument* arg = &*argIt;
    Type* ty = arg->getType();

    std::string name = arg->getName().str();

    if (ty->isIntegerTy()) {
      unsigned width = ty->getIntegerBitWidth();
      if (width == 1) {
        variables.emplace(name, scx.bool_const(name.c_str()));
      } else {
        variables.emplace(name, scx.bv_const(name.c_str(), width));
      }
    } else if (isFPType(ty)) {
      unsigned expBits, sigBits;
      if (ty->isHalfTy()) { expBits = 5;  sigBits = 11; }
      else if (ty->isFloatTy()) { expBits = 8;  sigBits = 24; }
      else if (ty->isDoubleTy()) { expBits = 11; sigBits = 53; }
      else /* FP128 */ { expBits = 15; sigBits = 113; }

      variables.emplace(name, scx.fpa_const(name.c_str(), expBits, sigBits));
    } else {
      std::string type_str;
      llvm::raw_string_ostream rso(type_str);
      arg->print(rso);
      throw UnsupportedTypeException("unsupported LLVM variable type", rso.str());
    }

    ++argIt;
  }
}

expr LLVMFunction::AddBCVariable(std::unique_ptr<LLVMNode> contents) {
  std::ostringstream oss;
  oss << "_slot_smtbc_" << varCounter << "_";
  std::string name = oss.str();

  unsigned width = contents->Width();
  expr var = scx.bv_const(name.c_str(), width);
  variables.emplace(name, var);

  expr constraint = (var.mk_from_ieee_bv(contents->SMTSort()) == contents->ToSMT());
  extraVariables = (varCounter == 0) ? constraint : (extraVariables && constraint);
  ++varCounter;

  return var;
}

expr LLVMFunction::ToSMT() {
  // Get terminator of entry block and extract return operand
  BasicBlock& entry = contents->getEntryBlock();
  Instruction* term = entry.getTerminator();
  ReturnInst* ret = static_cast<ReturnInst*>(term);
  Value* retOp = ret->getOperand(0);

  // Build node from return value and convert to SMT
  expr childExpr = LLVMNode::MakeLLVMNode(shiftToMultiply, scx, *this, retOp)->ToSMT();

  // Combine with any extra constraints if present
  return (varCounter == 0) ? childExpr : (extraVariables && childExpr);
}

