/// Factory function to instantiate an interpreter with the given module.
ExecutionEngine *Interpreter::create(std::unique_ptr<Module> M,
                                     std::string *ErrStr) {
  // Ensure full materialization of the module and capture any errors.
  if (Error Err = M->materializeAll()) {
    std::string ErrorMsg;
    handleAllErrors(std::move(Err), [&](ErrorInfoBase &EIB) {
      ErrorMsg = EIB.message();
    });
    if (ErrStr) {
      *ErrStr = std::move(ErrorMsg);
    }
    return nullptr; // Return null on failure
  }

  return new Interpreter(std::move(M));
}

//===----------------------------------------------------------------------===//
// Constructor: Initialize interpreter state
//
Interpreter::Interpreter(std::unique_ptr<Module> M)
    : ExecutionEngine(std::move(M)) {
  std::memset(&ExitValue.Untyped, 0, sizeof(ExitValue.Untyped));

  // Perform backend initialization steps
  initializeExecutionEngine();
  initializeExternalFunctions();
  emitGlobals();

  // Create intrinsic lowering helper
  IL = new IntrinsicLowering(getDataLayout());
}

Interpreter::~Interpreter() {
  delete IL;
}

void Interpreter::runAtExitHandlers() {
  while (!AtExitHandlers.empty()) {
    callFunction(AtExitHandlers.back(), std::nullopt);
    AtExitHandlers.pop_back();
    run();
  }
}

/// Execute a function with provided arguments.
GenericValue Interpreter::runFunction(Function *F,
                                      ArrayRef<GenericValue> ArgValues) {
  assert(F && "Null function pointer passed to runFunction");

  // Avoid passing more arguments than the function expects.
  // This guards against mismatches due to common C programming practices
  // where main() is declared with fewer parameters than actually passed.
  const size_t ParamCount = F->getFunctionType()->getNumParams();
  const size_t EffectiveArgCount = std::min(ArgValues.size(), ParamCount);

  ArrayRef<GenericValue> TrimmedArgs = ArgValues.slice(0, EffectiveArgCount);

  // Initiate execution
  callFunction(F, TrimmedArgs);
  run();

  return ExitValue;
}

