// Function to perform a query and return the response
int performQuery(int u, int k, const std::vector<int>& s) {
    std::cout << "? " << u << " " << k << " " << s.size();
    for (int room : s) {
        std::cout << " " << room;
    }
    std::cout << std::endl;

    int response;
    std::cin >> response;

    if (response == -1) {
        // Handle error condition as per problem requirements
        exit(0);
    }

    return response;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<int> a(n + 1);

    // Phase 1: Determine the mapping using binary search
    std::vector<int> possible_values(n);
    std::iota(possible_values.begin(), possible_values.end(), 1);

    for (int i = 1; i <= n; ++i) {
        std::vector<int> candidates = possible_values;

        while (candidates.size() > 1) {
            int split_point = candidates.size() / 2;
            std::vector<int> left_half(candidates.begin(), candidates.begin() + split_point);

            int result = performQuery(i, 1, left_half);

            if (result == 1) {
                // Target is in the left half
                candidates.resize(split_point);
            } else {
                // Target is in the right half
                candidates.erase(candidates.begin(), candidates.begin() + split_point);
            }
        }

        a[i] = candidates[0];
    }

    // Phase 2: Build adjacency list from the mapping
    std::vector<std::vector<int>> graph(n + 1);
    for (int i = 1; i <= n; ++i) {
        graph[i].push_back(a[i]);
        graph[a[i]].push_back(i);
    }

    // Phase 3: BFS traversal starting from node 1
    std::vector<int> reachable_nodes;
    std::vector<bool> seen(n + 1, false);
    std::queue<int> frontier;

    frontier.push(1);
    seen[1] = true;

    while (!frontier.empty()) {
        int current = frontier.front();
        frontier.pop();
        reachable_nodes.push_back(current);

        for (int neighbor : graph[current]) {
            if (!seen[neighbor]) {
                seen[neighbor] = true;
                frontier.push(neighbor);
            }
        }
    }

    // Sort the result for consistent output format
    std::sort(reachable_nodes.begin(), reachable_nodes.end());

    // Output the final answer
    std::cout << "! " << reachable_nodes.size();
    for (int node : reachable_nodes) {
        std::cout << " " << node;
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

// Max possible XOR value for n <= 10^7. 2^24 > 10^7.
const int MAX_XOR = 1 << 24;

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Use a vector to store the selected numbers
    std::vector<int> selected;
    selected.reserve(3000);

    // Track which XOR values have been used
    std::vector<bool> xor_used(MAX_XOR, false);

    // Greedily build the set by checking each number from 1 to n
    for (int candidate = 1; candidate <= n; ++candidate) {
        bool valid = true;

        // Check if this candidate creates a duplicate XOR with any existing element
        for (int existing : selected) {
            int current_xor = candidate ^ existing;
            if (xor_used[current_xor]) {
                valid = false;
                break;
            }
        }

        // If valid, add it to our set and mark new XORs as used
        if (valid) {
            for (int existing : selected) {
                xor_used[candidate ^ existing] = true;
            }
            selected.push_back(candidate);
        }
    }

    // Output the size and elements of the resulting set
    std::cout << selected.size() << "\n";
    for (size_t idx = 0; idx < selected.size(); ++idx) {
        std::cout << selected[idx];
        if (idx != selected.size() - 1) {
            std::cout << " ";
        }
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <stack>
using namespace std;

int main() {
    // Initialize three stacks: s, s1 (default), and s2 (copy of s1)
    stack<int> s;
    stack<int> s1;
    stack<int> s2(s1);

    // Fill stack 's' with values 1 through 6
    s.push(1);
    s.push(2);
    s.push(3);
    s.push(4);
    s.emplace(5);
    s.emplace(6);

    // Fill stack 's1' with values 7 through 10
    s1.push(7);
    s1.push(8);
    s1.push(9);
    s1.push(10);

    // Swap contents of s and s1
    s2.swap(s1);

    // Output top element and size of s1 after swap
    cout << "s1: " << s1.top() << endl;     // Top is now 10
    cout << "s1 size: " << s1.size() << endl; // Size is 4

    // Output top element and size of s2 after swap
    cout << "s2: " << s2.top() << endl;     // Top is now 7
    cout << "s2 size: " << s2.size() << endl; // Size is 4

    // Remove top element from s (which is now 6)
    s.pop();
    cout << "Top element: " << s.top() << endl; // Now 5

    // Show current size and emptiness status
    cout << "Size of stack: " << s.size() << endl; // 5 elements remain
    cout << "Is stack empty? " << (s.empty() ? "Yes" : "No") << endl;

    // Pop and print all remaining elements
    while (!s.empty()) {
        cout << s.top() << " ";
        s.pop();
    }
    cout << endl;

    // Final size check after full pop
    cout << "Size of stack after popping all elements: " << s.size() << endl;

    return 0;
}

