#include "../backend/src/QuantumRegister.hpp"
#include <benchmark/benchmark.h>
#include <iostream>

// Benchmark for Hadamard Gate operation focusing on memory bandwidth limitations
static void BM_HadamardMemoryTest(benchmark::State &state) {
  int qubit_count = state.range(0);

  // Initialize quantum register outside the timing loop to exclude allocation overhead
  try {
    QuantumRegister qr(qubit_count);

    for (auto _ : state) {
      // Apply Hadamard gate to first qubit - this is a memory-bound operation
      qr.applyHadamard(0);

      // Prevent compiler optimizations and ensure memory operations are preserved
      benchmark::DoNotOptimize(qr.getStateVector().data());
      benchmark::ClobberMemory();
    }

    // Compute memory throughput metrics
    // Each state vector element is 16 bytes (complex<double>), total elements = 2^N
    // The applyHadamard operation reads and writes each affected element once
    // For single-qubit gate: processes half the state space (2^(N-1) pairs)
    // Total data movement: 4 * 2^(N-1) * 16 bytes = 2^N * 32 bytes = 2 * size_of_state_vector
    double total_bytes = static_cast<double>(1ULL << qubit_count) * 16.0 * 2.0;
    state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) * 
                            static_cast<int64_t>(total_bytes));

  } catch (const std::exception &e) {
    state.SkipWithError("Insufficient memory or initialization error");
  }
}

// Register benchmarks with different system sizes
BENCHMARK(BM_HadamardMemoryTest)
    ->Arg(20)   // ~16 MB state vector
    ->Arg(25)   // ~512 MB state vector  
    ->Arg(28)   // ~4 GB state vector
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

