#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    int numSpecial(const std::vector<std::vector<int>>& mat) {
        int count = 0;

        for (int r = 0; r < static_cast<int>(mat.size()); ++r) {
            int rowSum = 0;
            for (int c = 0; c < static_cast<int>(mat[r].size()); ++c) {
                rowSum += mat[r][c];
            }

            if (rowSum == 1) {
                int colPos = -1;
                for (int c = 0; c < static_cast<int>(mat[r].size()); ++c) {
                    if (mat[r][c] == 1) {
                        colPos = c;
                        break;
                    }
                }

                if (colPos != -1) {
                    int colSum = 0;
                    for (int r2 = 0; r2 < static_cast<int>(mat.size()); ++r2) {
                        colSum += mat[r2][colPos];
                    }

                    if (colSum == 1) {
                        count++;
                    }
                }
            }
        }

        return count;
    }
};

