SeqArrangeJob::SeqArrangeJob(const Model &model, const DynamicPrintConfig &config, bool only_current_bed)
{
    m_arranger = std::make_unique<SeqArrange>(model, config, only_current_bed);
}

void SeqArrangeJob::process(Ctl &ctl)
{
    struct JobCancelled : public std::exception {};

    try {
        m_arranger->run_sequential_arrange(
            [&](int pct) {
                ctl.set_progress(pct, _u8L("Arranging for sequential print"));
                if (ctl.is_cancel_requested()) {
                    throw JobCancelled{};
                }
            }
        );
    }
    catch (const JobCancelled &) {
        ctl.set_progress(100, ""); // Clear status after cancellation
    }
    catch (const std::exception &) {
        ctl.set_progress(100, ""); // Hide progress indicator on error
        throw;
    }
}

void SeqArrangeJob::finalize(bool was_cancelled, std::exception_ptr &err_ptr)
{
    bool failure_occurred = false;

    if (err_ptr) {
        try {
            std::rethrow_exception(err_ptr);
        }
        catch (const ExceptionCannotApplySeqArrange &) {
            ErrorDialog(wxGetApp().plater(),
                        _L("The result of the single-bed arrange would scatter "
                           "instances of a single object between several beds, possibly affecting order of printing "
                           "of the non-selected beds. Consider using global arrange across all beds."),
                        false).ShowModal();
            failure_occurred = true;
            err_ptr = nullptr;
        }
        catch (const Sequential::ObjectTooLargeException &) {
            ErrorDialog(wxGetApp().plater(), _L("One of the objects is too large to fit the bed."), false).ShowModal();
            failure_occurred = true;
            err_ptr = nullptr;
        }
        catch (const std::runtime_error &e) {
            ErrorDialog(wxGetApp().plater(), GUI::format_wxstr(_L("Internal error: %1%"), e.what()), false).ShowModal();
            failure_occurred = true;
            err_ptr = nullptr;
        }
    }

    if (!was_cancelled && !failure_occurred) {
        Plater::TakeSnapshot snap(wxGetApp().plater(), _u8L("Arrange for sequential print"));
        m_arranger->commit_sequential_arrange(wxGetApp().model());
        wxGetApp().plater()->canvas3D()->refresh_view(true);
        wxGetApp().obj_list()->refresh_after_undo_redo();
    }

    m_arranger.reset();
}

