#include <unistd.h>
#endif

using namespace lemon;

// Shared shutdown indicator across threads/signal context
static std::atomic<bool> g_request_stop(false);
static Server* g_active_server = nullptr;

// Async-signal-safe handler for termination signals
void handle_termination_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
#ifndef _WIN32
        constexpr const char msg[] = "Shutdown signal received, exiting...\n";
        write(STDOUT_FILENO, msg, sizeof(msg) - 1);
#endif
        // Set flag and terminate immediately without invoking non-async-signal-safe functions
        g_request_stop = true;
        _exit(EXIT_SUCCESS);
#ifdef SIGHUP
    } else if (sig == SIGHUP) {
        // Do nothing: SIGHUP is intentionally ignored to support daemonization
        return;
#endif
    }
}

int main(int argc, char** argv) {
    // Early check: prevent multiple instances
    if (SingleInstance::IsAnotherInstanceRunning("Router")) {
        std::cerr << "Error: Another instance of lemonade-router is already running.\n"
                  << "Only one instance can run at a time." << std::endl;
        return EXIT_FAILURE;
    }

    try {
        CLIParser cli_parser;
        cli_parser.parse(argc, argv);

        // Exit early if help/version requested or parsing failed
        if (!cli_parser.should_proceed()) {
            return cli_parser.get_exit_code();
        }

        auto cfg = cli_parser.get_config();

        // Setup logging sink
        auto log_sink = std::make_shared<AixLog::SinkCout>(
            AixLog::Filter(AixLog::to_severity(cfg.log_level)),
            "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message"
        );
        AixLog::Log::init({log_sink});

        // Log startup info
        LOG(INFO) << "Starting Lemonade Server..." << std::endl;
        LOG(INFO) << "  Version: " << LEMON_VERSION_STRING << std::endl;
        LOG(INFO) << "  Port: " << cfg.port << std::endl;
        LOG(INFO) << "  Host: " << cfg.host << std::endl;
        LOG(INFO) << "  Log level: " << cfg.log_level << std::endl;
        if (!cfg.extra_models_dir.empty()) {
            LOG(INFO) << "  Extra models dir: " << cfg.extra_models_dir << std::endl;
        }

        // Construct server with parsed config
        Server srv(
            cfg.port,
            cfg.host,
            cfg.log_level,
            cfg.recipe_options,
            cfg.max_loaded_models,
            cfg.extra_models_dir,
            cfg.no_broadcast,
            cfg.global_timeout
        );

        // Install signal handlers before starting the server loop
        g_active_server = &srv;
        std::signal(SIGINT, handle_termination_signal);
        std::signal(SIGTERM, handle_termination_signal);

        // Run server until shutdown signal arrives
        srv.run();

        // Cleanup after successful run
        g_active_server = nullptr;
        return EXIT_SUCCESS;

    } catch (const std::exception& ex) {
        LOG(ERROR) << "Fatal error: " << ex.what() << std::endl;
        return EXIT_FAILURE;
    }
}

