namespace duckdb {

static string FindMatchingExtension(const string &path_pattern) {
	for (const auto &entry : EXTENSION_FILE_PREFIXES) {
		if (path_pattern.compare(0, entry.name.length(), entry.name) == 0) {
			return entry.extension;
		}
	}
	return "";
}

void DuckLakeInitializer::CheckAndAutoloadRequiredExtension(const string &data_path) {
	// This function:
	//	1. Detects if the data path begins with a known extension prefix
	//	2. Ensures the corresponding extension is loaded or provides helpful error guidance
	string needed_extension = FindMatchingExtension(data_path);

	if (!needed_extension.empty() && !context.db->ExtensionIsLoaded(needed_extension)) {
		bool can_autoload = ExtensionHelper::CanAutoloadExtension(needed_extension);
		bool autoload_enabled = Settings::Get<AutoloadKnownExtensionsSetting>(context);

		if (!can_autoload || !autoload_enabled) {
			string msg = "Data path '" + data_path + "' requires extension '" + needed_extension + "'";
			msg = ExtensionHelper::AddExtensionInstallHintToErrorMsg(context, msg, needed_extension);
			throw MissingExtensionException(msg);
		}

		// Attempt to automatically load the required extension
		ExtensionHelper::AutoLoadExtension(context, needed_extension);

		// Verify the extension was successfully loaded
		if (!context.db->ExtensionIsLoaded(needed_extension)) {
			throw InternalException("Extension '" + needed_extension + "' failed to load despite no exception being thrown");
		}
	}
}

} // namespace duckdb

