#include <asio/ts/executor.hpp>
#include <condition_variable>
#include <iostream>
#include <memory>
#include <mutex>
#include <vector>
using asio::dispatch;
using asio::execution_context;

class priority_scheduler : public execution_context
{
public:
  class executor_type
  {
  public:
    executor_type(priority_scheduler& ctx, int pri) noexcept
      : context_(ctx), priority_(pri)
    {
    }

    priority_scheduler& context() const noexcept
    {
      return context_;
    }

    void on_work_started() const noexcept {}
    void on_work_finished() const noexcept {}

    template <class Func, class Alloc>
    void dispatch(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }

    template <class Func, class Alloc>
    void post(Func f, const Alloc& a) const
    {
      auto p = std::allocate_shared<task_wrapper>(
        typename std::allocator_traits<
          Alloc>::template rebind_alloc<task_wrapper>(a),
        priority_, std::move(f));

      std::lock_guard<std::mutex> guard(context_.tasks_mutex_);
      context_.tasks_.push_back(p);
      context_.new_task_available_.notify_one();
    }

    template <class Func, class Alloc>
    void defer(Func&& f, const Alloc& a) const
    {
      post(std::forward<Func>(f), a);
    }

    friend bool operator==(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ == &b.context_;
    }

    friend bool operator!=(const executor_type& a,
        const executor_type& b) noexcept
    {
      return &a.context_ != &b.context_;
    }

  private:
    priority_scheduler& context_;
    int priority_;
  };

  executor_type get_executor(int pri = 0) noexcept
  {
    return executor_type(*const_cast<priority_scheduler*>(this), pri);
  }

  void run()
  {
    std::unique_lock<std::mutex> lock(tasks_mutex_);
    for (;;)
    {
      new_task_available_.wait(lock, [this] { 
        return shutdown_requested_ || !tasks_.empty(); 
      });

      if (shutdown_requested_)
        return;

      // Find highest priority task
      size_t best_idx = 0;
      int max_priority = tasks_[0]->priority_;

      for (size_t i = 1; i < tasks_.size(); ++i)
      {
        if (tasks_[i]->priority_ > max_priority)
        {
          max_priority = tasks_[i]->priority_;
          best_idx = i;
        }
      }

      auto task = tasks_[best_idx];
      tasks_.erase(tasks_.begin() + best_idx);

      lock.unlock();
      task->invoke();
      lock.lock();
    }
  }

  void stop()
  {
    std::lock_guard<std::mutex> guard(tasks_mutex_);
    shutdown_requested_ = true;
    new_task_available_.notify_all();
  }

private:
  struct base_task
  {
    int priority_;
    virtual void invoke() = 0;
    virtual ~base_task() = default;
  };

  template <class Func>
  struct concrete_task : base_task
  {
    concrete_task(int pri, Func fn) : function_(std::move(fn))
    {
      priority_ = pri;
    }

    void invoke() override
    {
      function_();
    }

    Func function_;
  };

  using task_wrapper = concrete_task<std::function<void()>>;

  mutable std::mutex tasks_mutex_;
  std::condition_variable new_task_available_;
  std::vector<std::shared_ptr<base_task>> tasks_;
  bool shutdown_requested_ = false;
};

int main()
{
  priority_scheduler sched;
  auto low = sched.get_executor(0);
  auto med = sched.get_executor(1);
  auto high = sched.get_executor(2);

  dispatch(low, []{ std::cout << "1\n"; });
  dispatch(low, []{ std::cout << "11\n"; });
  dispatch(med, []{ std::cout << "2\n"; });
  dispatch(med, []{ std::cout << "22\n"; });
  dispatch(high, []{ std::cout << "3\n"; });
  dispatch(high, []{ std::cout << "33\n"; });
  dispatch(high, []{ std::cout << "333\n"; });
  dispatch(sched.get_executor(-1), [&]{ sched.stop(); });

  sched.run();
}

