// Global flag to signal termination of worker threads
atomic<bool> shutdownRequested(false);

// Forward declaration for Scheduler
struct CoroutineScheduler;

// Task type based on C++20 coroutines
struct WorkItem {
    struct promise_type {
        CoroutineScheduler* ownerScheduler;

        WorkItem get_return_object() {
            return WorkItem{ std::coroutine_handle<promise_type>::from_promise(*this) };
        }

        std::suspend_never initial_suspend() noexcept { return {}; }

        struct completion_awaiter {
            bool await_ready() const noexcept { return false; }
            void await_suspend(std::coroutine_handle<>) noexcept {}
            void await_resume() noexcept {}
        };

        completion_awaiter final_suspend() noexcept { return {}; }

        void unhandled_exception() noexcept { std::terminate(); }
        void return_void() noexcept {}
    };

    std::coroutine_handle<promise_type> coroutineHandle;

    WorkItem(std::coroutine_handle<promise_type> h) : coroutineHandle(h) {}

    ~WorkItem() {
        if (coroutineHandle) {
            coroutineHandle.destroy();
        }
    }

    void activate(CoroutineScheduler& scheduler);
};

// Scheduler managing scheduled tasks with timing support
struct CoroutineScheduler {
    using ScheduledTask = pair<steady_clock::time_point, std::coroutine_handle<>>;
    priority_queue<ScheduledTask, vector<ScheduledTask>, greater<>> taskQueue;

    void enqueue_immediate(std::coroutine_handle<> handle) {
        taskQueue.emplace(steady_clock::now(), handle);
    }

    void enqueue_at(std::coroutine_handle<> handle, steady_clock::time_point targetTime) {
        taskQueue.emplace(targetTime, handle);
    }

    void execute_until_stopped() {
        while (!shutdownRequested.load()) {
            if (!taskQueue.empty()) {
                auto [targetTime, task] = taskQueue.top();

                if (steady_clock::now() >= targetTime) {
                    taskQueue.pop();
                    if (!task.done()) {
                        task.resume();
                    }
                } else {
                    auto remaining = targetTime - steady_clock::now();
                    if (remaining > milliseconds(1)) {
                        this_thread::sleep_for(milliseconds(1));
                    } else {
                        this_thread::yield();
                    }
                }
            } else {
                this_thread::yield();
            }
        }
    }
};

void WorkItem::activate(CoroutineScheduler& scheduler) {
    coroutineHandle.promise().ownerScheduler = &scheduler;
    scheduler.enqueue_immediate(coroutineHandle);
}

// Awaitable for yielding control temporarily
struct DelayAwaiter {
    CoroutineScheduler& schedulerRef;
    steady_clock::time_point wakeUpPoint;

    DelayAwaiter(CoroutineScheduler& sched, microseconds duration)
        : schedulerRef(sched), wakeUpPoint(steady_clock::now() + duration) {}

    bool await_ready() const noexcept {
        return steady_clock::now() >= wakeUpPoint;
    }

    void await_suspend(std::coroutine_handle<> h) {
        schedulerRef.enqueue_at(h, wakeUpPoint);
    }

    void await_resume() noexcept {}
};

// Asynchronous coroutine simulating transaction processing
WorkItem process_transactions(CoroutineScheduler& scheduler, int& localCounter) {
    while (!shutdownRequested.load()) {
        localCounter++;
        co_await DelayAwaiter(scheduler, microseconds(15));
    }
}

// Worker thread function: runs two concurrent coroutines
void worker_function(int id, int& throughputCounter) {
    CoroutineScheduler scheduler;

    WorkItem item1 = process_transactions(scheduler, throughputCounter);
    WorkItem item2 = process_transactions(scheduler, throughputCounter);

    item1.activate(scheduler);
    item2.activate(scheduler);

    scheduler.execute_until_stopped();
}

int main(int argc, char* argv[]) {
    int threadCount = 4;
    vector<thread> workers;
    vector<int> perThreadCounts(threadCount, 0); // Local counters per thread

    // Launch worker threads
    for (int i = 0; i < threadCount; ++i) {
        workers.emplace_back(worker_function, i, ref(perThreadCounts[i]));
    }

    // Run for specified duration
    int durationSeconds = 10;
    this_thread::sleep_for(seconds(durationSeconds));

    // Signal shutdown
    shutdownRequested.store(true);

    // Wait for all workers to finish
    for (auto& worker : workers) {
        worker.join();
    }

    // Aggregate results
    int totalOperations = 0;
    for (int count : perThreadCounts) {
        totalOperations += count;
    }

    // Output average throughput
    cout << "Throughput: " << totalOperations / durationSeconds << " txn/sec" << endl;

    return 0;
}

