class Solution {
public:
    int findKthLargest(std::vector<int>& nums, int k) {
        // Sort the array in ascending order
        std::sort(nums.begin(), nums.end());

        // Access the k-th largest element (which is at index size - k)
        int index = nums.size() - k;
        return nums[index];
    }
};

