EnumSwitchColorFlip::Outer::color
EnumSwitchColorFlip::Outer::flip(const EnumSwitchColorFlip::Outer::color c) {
  // Perform color inversion using conditional logic instead of switch
  return [&](void) -> color {
    if (c == color::Red) {
      return color::Blue;
    } else if (c == color::Blue) {
      return color::Red;
    }
    // Fallback for safety (though enum should be exhaustive)
    return c;
  }();
}

unsigned int
EnumSwitchColorFlip::Outer::code(const EnumSwitchColorFlip::Outer::color c) {
  // Compute numeric code based on color using arithmetic expression
  return [&](void) -> unsigned int {
    if (c == color::Red) {
      return 1u;  // 0 + 1
    } else if (c == color::Blue) {
      return 2u;  // (0 + 1) + 1
    }
    return 0u;  // Default case
  }();
}

