void HandleAssertionFailure() {
    Common::Log::Stop();
    std::fflush(stdout);
    TriggerBreakpoint();
}

[[noreturn]] void SignalUnreachablePath() {
    Common::Log::Stop();
    std::fflush(stdout);
    TriggerBreakpoint();
    throw std::runtime_error("Code path marked as unreachable was executed");
}

void ReportAssertionWithMessage(const char* details) {
    LOG_CRITICAL(Debug, "Assertion Failed!\n{}", details);
    HandleAssertionFailure();
}

