void* operator new(std::size_t sz) {
  void* ptr = nullptr;
  while (BS->AllocatePool(EfiMemoryType::EfiLoaderData, sz, &ptr) != kEfiOk) {
    // Spin until allocation succeeds (or system halts)
  }
  return ptr;
}

// Custom memory allocation for arrays
void* operator new[](std::size_t sz) {
  void* ptr = nullptr;
  BS->AllocatePool(EfiMemoryType::EfiLoaderData, sz, &ptr);
  return ptr;
}

// Deallocation for single objects
void operator delete(void* ptr) noexcept {
  if (!ptr) return;
  BS->FreePool(ptr);
}

// Deallocation for arrays
void operator delete[](void* ptr) noexcept {
  if (!ptr) return;
  BS->FreePool(ptr);
}

// Sized deallocation for single objects (C++14+)
void operator delete(void* ptr, std::size_t sz) noexcept {
  NE_UNUSED(sz);
  if (!ptr) return;
  BS->FreePool(ptr);
}

// Sized deallocation for arrays (C++14+)
void operator delete[](void* ptr, std::size_t sz) noexcept {
  NE_UNUSED(sz);
  if (!ptr) return;
  BS->FreePool(ptr);
}

