#include <iostream>
#include <vector>
#include <utility>

// Vector to store the sequence of moves
// Each move is represented as a pair: (source_basket, target_basket)
std::vector<std::pair<int, int>> move_sequence;

/**
 * @brief Recursive function to solve Tower of Hanoi problem
 * 
 * This implementation follows the classic recursive approach:
 * 1. Move n-1 disks from source to auxiliary peg
 * 2. Move the bottom disk from source to destination peg
 * 3. Move n-1 disks from auxiliary to destination peg
 * 
 * @param disks Number of disks remaining to move
 * @param source_id Identifier for the source basket
 * @param target_id Identifier for the destination basket
 * @param helper_id Identifier for the auxiliary basket
 */
void hanoi_solver(int disks, int source_id, int target_id, int helper_id) {
    if (disks <= 0) {
        return;
    }

    // First, move top (disks-1) disks from source to helper
    hanoi_solver(disks - 1, source_id, helper_id, target_id);

    // Then, move the largest disk from source to target
    move_sequence.push_back(std::make_pair(source_id, target_id));

    // Finally, move the (disks-1) disks from helper to target
    hanoi_solver(disks - 1, helper_id, target_id, source_id);
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int number_of_disks;
    std::cin >> number_of_disks;

    // Initialize the solution by moving all disks from basket 1 to basket 3
    hanoi_solver(number_of_disks, 1, 3, 2);

    // Print the total number of moves required
    std::cout << move_sequence.size() << "\n";

    // Print each individual move
    for (const auto& move : move_sequence) {
        std::cout << move.first << " " << move.second << "\n";
    }

    return 0;
}

