namespace {
    class TGlobalLogsRegistry {
    private:
        TVector<TLogBackend*> BackendList;
        TMutex RegistryLock;

    public:
        void Add(TLogBackend* backend) {
            TGuard<TMutex> guard(RegistryLock);
            BackendList.push_back(backend);
        }

        void Remove(TLogBackend* backend) {
            TGuard<TMutex> guard(RegistryLock);
            for (size_t idx = 0; idx < BackendList.size(); ++idx) {
                if (BackendList[idx] == backend) {
                    BackendList.erase(BackendList.begin() + static_cast<ptrdiff_t>(idx));
                    return;
                }
            }
            Y_FAIL("Attempted to unregister invalid log backend pointer");
        }

        void Refresh(bool shouldFlush) {
            TGuard<TMutex> guard(RegistryLock);
            for (auto& entry : BackendList) {
                if (dynamic_cast<const TLogBackend*>(entry)) {
                    continue;
                }
                if (shouldFlush) {
                    entry->Rotate();
                } else {
                    entry->RotateNoFlush();
                }
            }
        }
    };
}

template <>
class TSingletonTraits<TGlobalLogsRegistry> {
public:
    static const size_t Priority = 50;
};

ELogPriority TLogBackend::GetFilteringThreshold() const {
    return LOG_MAX_PRIORITY;
}

TLogBackend::TLogBackend() noexcept {
    Singleton<TGlobalLogsRegistry>()->Add(this);
}

TLogBackend::~TLogBackend() {
    Singleton<TGlobalLogsRegistry>()->Remove(this);
}

void TLogBackend::RotateNoFlush() {
    Rotate();
}

void TLogBackend::RefreshAll(bool flush) {
    Singleton<TGlobalLogsRegistry>()->Refresh(flush);
}

