XmlFuseWriter::XmlFuseWriter(QFile &outputFile) : XflXmlWriter(outputFile)
{
}

void XmlFuseWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("xflfuse");
    writeAttribute("version", "1.0");

    writeStartElement("Units");
    {
        double lengthFactor = 1.0 / Units::mtoUnit();
        writeTextElement("length_unit_to_meter", QString::number(lengthFactor));

        double massFactor = 1.0 / Units::kgtoUnit();
        writeTextElement("mass_unit_to_kg", QString::number(massFactor));
    }
    writeEndElement();
}

void XmlFuseWriter::writeXMLFuse(FuseXfl const *pFuse)
{
    writeStartDocument();
    writeHeader();

    writeStartElement("xflfuse");
    {
        // Write basic properties
        writeTextElement("Name", pFuse->name());
        writeTextElement("Description", pFuse->description());

        // Handle inertia configuration
        writeComment("If the field AUTOINERTIA is set to TRUE, the fields COG and COG_I** will be ignored");
        writeTextElement("AutoInertia", xfl::boolToString(pFuse->bAutoInertia()));

        // Write inertia data
        writeInertia(pFuse->inertia());

        writeEndElement();

        // Write extended FUSE data with zero offset
        Vector3d zeroOffset(0.0, 0.0, 0.0);
        writeXflFuse(*pFuse, zeroOffset);
    }

    writeEndElement();
    writeEndDocument();
}

