class Solution {
public:
    int findDuplicate(vector<int>& nums) {
        int duplicate = 0;
        int size = nums.size();

        // Sort the array to bring duplicates next to each other
        sort(nums.begin(), nums.end());

        // Iterate through the sorted array to find adjacent duplicates
        for (int j = 0; j < size - 1; ++j) {
            if (nums[j] == nums[j + 1]) {
                duplicate = nums[j];
                break;  // Early exit once duplicate is found
            }
        }

        return duplicate;
    }
};

