namespace fuzzer {

// Define start marker for extra counters section
// Aligned to 16 bytes to ensure proper layout relative to adjacent symbols
#pragma section(".data$__libfuzzer_extra_countaaa")
ATTRIBUTE_ALIGNED(16)
__declspec(allocate(".data$__libfuzzer_extra_countaaa")) 
uint8_t __start___libfuzzer_extra_counters[16] = {0};

// Define end marker for extra counters section
// Placed after user-provided counters; aligned to 1 byte to avoid padding
#pragma section(".data$__libfuzzer_extra_countzzz")
ATTRIBUTE_ALIGNED(1)
__declspec(allocate(".data$__libfuzzer_extra_countzzz")) 
uint8_t __stop___libfuzzer_extra_counters = 0;

// Compute beginning of actual counter region (skip the fixed-size start marker)
uint8_t *ExtraCountersBegin() {
  return __start___libfuzzer_extra_counters + sizeof(__start___libfuzzer_extra_counters);
}

// Compute end of counter region (address of stop symbol)
uint8_t *ExtraCountersEnd() { 
  return &__stop___libfuzzer_extra_counters; 
}

// Clear all user-defined counters in the region between begin and end
ATTRIBUTE_NO_SANITIZE_ALL
void ClearExtraCounters() {
  uint8_t *startPtr = ExtraCountersBegin();
  size_t length = ExtraCountersEnd() - startPtr;

  // Use SecureZeroMemory for safe zeroing on Windows
  if (length > 0) {
    SecureZeroMemory(startPtr, length);
  }
}

} // namespace fuzzer
#endif

#include <format>
#include <sm/vec>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

int main() {
    // Initialize visualization window
    mplot::Visual scene{1280, 575, "Made with mplot::GraphVisual"};

    // Instantiate graph visualizer at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Register model with scene
    scene.bindmodel(graph);

    // Prepare x-axis data points from 0 to 10 in steps of 1
    sm::vvec<double> abscissae;
    abscissae.linspace(0, 10, 11);

    // Define corresponding y-values manually
    sm::vvec<double> ordinates = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure primary dataset style (line plot)
    mplot::DatasetStyle mainStyle{mplot::stylepolicy::lines};
    mainStyle.linecolour = mplot::colour::crimson;

    // Enforce y-axis range [0, 10]
    graph->setlimits_y(0, 10);

    // Feed data into graph
    graph->setdata(abscissae, ordinates, mainStyle);

    // Style for horizontal reference line at y = 7
    mplot::DatasetStyle crossLineStyle{mplot::stylepolicy::lines};
    crossLineStyle.linecolour = mplot::colour::grey68;
    crossLineStyle.linewidth = mainStyle.linewidth * 0.6f;

#ifdef GRAPH_LINES_SIMPLE
    // In simple mode, just draw the crossing lines using main style
    graph->add_y_crossing_lines(abscissae, ordinates, 7.0, mainStyle);
#else
    // Advanced mode: compute exact crossing x-coordinates and annotate them
    sm::vvec<double> crossingPoints = graph->add_y_crossing_lines(
        abscissae, ordinates, 7.0, mainStyle, crossLineStyle);

    // Format annotation string listing crossing positions
    std::ostringstream msgBuilder;
    const size_t count = crossingPoints.size();

    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            bool isFirst = (idx == 0);
            bool isLast = (idx == count - 1);
            std::string separator = (isFirst || isLast) ? "" : ", ";
            std::string conjunction = isLast ? " and " : "";
            msgBuilder << separator << conjunction << std::format("{:.2f}", crossingPoints[idx]);
        }
    } else {
        msgBuilder << "[no values]";
    }

    // Insert label at lower-left corner
    graph->addLabel(
        std::format("y=7 at x = {}", msgBuilder.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures{0.03f}
    );
#endif

    // Finalize geometry generation
    graph->finalize();

    // Transfer ownership of graph to scene
    scene.addVisualModel(std::move(graph));

    // Launch interactive viewer loop
    scene.keepOpen();

    // Memory cleanup handled automatically via RAII
    return 0;
}

#include <catch2/catch_test_macros.hpp>
#include <Gorgon/Encoding/LZMA.h>
#include <fstream>
#include <string>
using namespace Gorgon;
using namespace Gorgon::Encoding;

TEST_CASE("LZMA round-trip compression/decompression with vector", "[LZMA]") {
    // Load README.md from the project root directory
    std::ifstream input_file(TESTDIR "/../../README.md", std::ios::binary);
    REQUIRE(input_file.is_open());

    std::string content((std::istreambuf_iterator<char>(input_file)),
                         std::istreambuf_iterator<char>());
    input_file.close();
    REQUIRE_FALSE(content.empty());

    // Transform string into byte vector for processing
    std::vector<Byte> data_vector(content.begin(), content.end());

    SECTION("Using explicit uncompressed size") {
        LZMA compressor(true);  // include size header

        std::vector<Byte> encoded_data;
        compressor.Encode(data_vector, encoded_data);
        REQUIRE(!encoded_data.empty());
        REQUIRE(encoded_data.size() != data_vector.size());  // Ensure actual compression occurred

        std::vector<Byte> decoded_data;
        compressor.Decode(encoded_data, decoded_data);

        REQUIRE(decoded_data.size() == data_vector.size());
        std::string recovered_string(decoded_data.begin(), decoded_data.end());
        REQUIRE(recovered_string == content);
    }

    SECTION("Without uncompressed size (relying on end marker)") {
        LZMA compressor(false);  // no size header

        std::vector<Byte> encoded_data;
        compressor.Encode(data_vector, encoded_data);
        REQUIRE(!encoded_data.empty());

        std::vector<Byte> decoded_data;
        compressor.Decode(encoded_data, decoded_data);

        REQUIRE(decoded_data.size() == data_vector.size());
        std::string recovered_string(decoded_data.begin(), decoded_data.end());
        REQUIRE(recovered_string == content);
    }

    SECTION("Verify property sizes") {
        LZMA lzma_with_size(true);
        REQUIRE(lzma_with_size.PropertySize() == 13); // 5 properties + 8-byte size field

        LZMA lzma_without_size(false);
        REQUIRE(lzma_without_size.PropertySize() == 5); // only 5 properties
    }
}

TEST_CASE("LZMA string-based compression and decompression", "[LZMA]") {
    std::string test_input = "Hello, this is a test string for LZMA compression! "
                             "It needs to be long enough to actually compress. "
                             "LZMA compression works best with repeated patterns. "
                             "Repeated patterns. Repeated patterns. Repeated patterns. "
                             "The quick brown fox jumps over the lazy dog. "
                             "The quick brown fox jumps over the lazy dog. "
                             "The quick brown fox jumps over the lazy dog.";

    LZMA lzma_encoder;

    // Compress directly from string to byte vector
    std::vector<Byte> compressed_buffer;
    lzma_encoder.Encode(test_input, compressed_buffer);
    REQUIRE_FALSE(compressed_buffer.empty());

    // Decompress back to string
    std::string decompressed_output;
    lzma_encoder.Decode(compressed_buffer, decompressed_output);
    REQUIRE(decompressed_output == test_input);
}

