void FDMXLibraryRecorderAddAllPatchesButtonCustomization::CustomizeHeader(
    TSharedRef<IPropertyHandle> InPropertyHandle,
    FDetailWidgetRow& HeaderRow,
    IPropertyTypeCustomizationUtils& CustomizationUtils)
{
    StructHandle = InPropertyHandle;

    // Gather all outer objects from the property handle
    TArray<UObject*> SourceObjects;
    InPropertyHandle->GetOuterObjects(SourceObjects);

    // Reserve space for recorder pointers to avoid reallocations
    CustomizedDMXRecorders.Empty();
    CustomizedDMXRecorders.Reserve(SourceObjects.Num());

    for (UObject* Obj : SourceObjects)
    {
        if (!Obj || !Obj->IsValidLowLevelFast())
        {
            continue;
        }

        UTakeRecorderDMXLibrarySource* Recorder = Cast<UTakeRecorderDMXLibrarySource>(Obj);
        if (Recorder && Recorder->IsValidLowLevelFast())
        {
            CustomizedDMXRecorders.Add(Recorder);
        }
    }

    ensureMsgf(CustomizedDMXRecorders.Num() > 0, TEXT("At least one valid DMX recorder must be present."));

    // Build the UI row with button
    HeaderRow
        .NameContent()
        [
            SNullWidget::NullWidget // No label needed — button contains its own text
        ]
        .ValueContent()
        .MinDesiredWidth(0.0f)
        .MaxDesiredWidth(0.0f)
        .HAlign(HAlign_Left)
        [
            SNew(SButton)
            .IsEnabled(this, &FDMXLibraryRecorderAddAllPatchesButtonCustomization::AreAllLibrariesValid)
            .OnClicked(this, &FDMXLibraryRecorderAddAllPatchesButtonCustomization::OnAddAllPatchesClicked)
            .ToolTipText(LOCTEXT("ToolTip", "Add all Patches in the DMX Library to be recorded"))
            .Content()
            [
                SNew(STextBlock)
                .Font(IDetailLayoutBuilder::GetDetailFont())
                .Text(LOCTEXT("AddAllPatches", "Add all Fixture Patches"))
            ]
        ];
}

bool FDMXLibraryRecorderAddAllPatchesButtonCustomization::AreAllLibrariesValid() const
{
    // Ensure every recorder has a valid DMX library reference
    for (const TWeakObjectPtr<UTakeRecorderDMXLibrarySource>& WeakRecorder : CustomizedDMXRecorders)
    {
        if (!WeakRecorder.IsValid())
        {
            return false;
        }

        UTakeRecorderDMXLibrarySource* RecorderPtr = WeakRecorder.Get();
        if (!RecorderPtr || !RecorderPtr->IsValidLowLevelFast())
        {
            return false;
        }

        UDMXLibrary* Library = RecorderPtr->DMXLibrary;
        if (!Library || !Library->IsValidLowLevelFast())
        {
            return false;
        }
    }

    return true;
}

FReply FDMXLibraryRecorderAddAllPatchesButtonCustomization::OnAddAllPatchesClicked()
{
    check(StructHandle.IsValid() && StructHandle->IsValidHandle());

    // Begin transaction scope
    {
        const FScopedTransaction Transaction(LOCTEXT("Transaction", "Add all Fixture Patches for recording"));

        // Notify pre-change for undo support
        StructHandle->NotifyPreChange();

        // Iterate over each recorder and invoke patch addition
        for (TWeakObjectPtr<UTakeRecorderDMXLibrarySource>& WeakRecorder : CustomizedDMXRecorders)
        {
            if (UObject* Obj = WeakRecorder.Get())
            {
                if (Obj->IsValidLowLevelFast())
                {
                    WeakRecorder->AddAllPatches();
                }
            }
        }

        // Notify post-change
        StructHandle->NotifyPostChange();
    }

    // Final notification after transaction ends
    StructHandle->NotifyFinishedChangingProperties();

    return FReply::Handled();
}

