#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>

// Demonstrates two approaches to obtain the 'this' context in sol2:
// one for constructors, one for member functions.
int main() {
    // Define a test class bound to Lua
    struct example_object {
        // Constructor: receives sol::this_state to access the Lua stack
        example_object(sol::this_state ctx) {
            lua_State* L = ctx;
            // Retrieve the first argument from the stack (the object being constructed)
            sol::stack_object obj_ref(L, 1);
            // Cast it to our type and verify identity with current 'this'
            example_object& instance = obj_ref.as<example_object>();
            SOL_ASSERT(&instance == this);
        }

        // Member function: also receives sol::this_state
        void process(sol::this_state ctx) const {
            lua_State* L = ctx;
            // Again, get the first stack element—the object instance
            sol::stack_object self_ref(L, 1);
            example_object& self_instance = self_ref.as<example_object>();
            // Confirm that the retrieved reference matches 'this'
            SOL_ASSERT(&self_instance == this);
        }
    };

    // Initialize Lua state and load base library
    sol::state vm;
    vm.open_libraries(sol::lib::base);

    // Register the class with Lua, exposing constructor and method
    vm.new_usertype<example_object>("example_object",
        sol::constructors<example_object(sol::this_state)>(),
        "process", &example_object::process);

    // Execute Lua script that instantiates and calls the object
    vm.script(R"(
obj = example_object.new()
obj:process()
)");

    return 0;
}

