namespace tpa {

namespace {

// Determines whether a CFG node belongs to the top-level category
// Top-level nodes (Alloc, Copy, Offset) influence only environment variables (Env)
// and do not involve memory store operations.
bool isTopLevelOperation(const CFGNode* node) {
    return node->isAllocNode() || node->isCopyNode() || node->isOffsetNode();
}

} // anonymous namespace

// Attempts to update the memoization cache with new store information.
// Returns true if the stored state for this program point was modified,
// indicating that the point should be scheduled for reprocessing.
bool SemiSparsePropagator::enqueueIfMemoChange(const ProgramPoint& pp, const Store& store) {
    if (memo.update(pp, store)) {
        workList.enqueue(pp);
        return true;
    }
    return false;
}

// Handles propagation for top-level operations (Alloc, Copy, Offset).
// Since these operations don't alter the Store, we simply schedule the successor
// without performing any store merging. Environment changes are applied globally.
void SemiSparsePropagator::propagateTopLevel(const EvalSuccessor& evalSucc) {
    workList.enqueue(evalSucc.getProgramPoint());
    // errs() << "\tENQ(T) " << evalSucc.getProgramPoint() << "\n";
}

// Manages propagation for memory-affecting operations (Load, Store, Call, Ret).
// These require checking whether the outgoing Store differs from previously seen states.
void SemiSparsePropagator::propagateMemLevel(const EvalSuccessor& evalSucc) {
    const auto *node = evalSucc.getProgramPoint().getCFGNode();
    assert(!isTopLevelOperation(node));
    assert(evalSucc.getStore() != nullptr);

    bool updated = enqueueIfMemoChange(evalSucc.getProgramPoint(), *evalSucc.getStore());
    //if (updated)
    //    errs() << "\tENQ(M) " << evalSucc.getProgramPoint() << "\n";
}

// Primary entry point for flow propagation.
// Iterates through all successors generated by transfer function evaluation
// and routes them to the appropriate handler based on their operation type.
void SemiSparsePropagator::propagate(const EvalResult& evalResult) {
    for (const auto& evalSucc : evalResult) {
        if (evalSucc.isTopLevel()) {
            propagateTopLevel(evalSucc);
        } else {
            propagateMemLevel(evalSucc);
        }
    }
}

} // namespace tpa

