namespace faiss {

class InvertedListsIOHook {
public:
    std::string key;
    std::string classname;

    InvertedListsIOHook(const std::string& k, const std::string& c)
        : key(k), classname(c) {}

    virtual ~InvertedListsIOHook() = default;

    static InvertedListsIOHook* lookup(int h);
    static InvertedListsIOHook* lookup_classname(const std::string& cn);
    static void add_callback(InvertedListsIOHook* cb);
    static void print_callbacks();

    virtual InvertedLists* read_ArrayInvertedLists(
            IOReader*,
            int,
            size_t,
            size_t,
            const std::vector<size_t>&) const;
};

namespace {

struct DeleterVector : std::vector<InvertedListsIOHook*> {
    DeleterVector() {
#ifndef _WIN32
        push_back(new OnDiskInvertedListsIOHook());
#endif
        push_back(new BlockInvertedListsIOHook());
    }

    ~DeleterVector() {
        for (auto ptr : *this) {
            delete ptr;
        }
    }
};

static DeleterVector io_hook_registry;

} // anonymous namespace

InvertedListsIOHook* InvertedListsIOHook::lookup(int h) {
    for (auto hook : io_hook_registry) {
        if (h == fourcc(hook->key)) {
            return hook;
        }
    }
    FAISS_THROW_FMT(
            "read_InvertedLists: could not load ArrayInvertedLists as "
            "%08x (\"%s\")",
            h,
            fourcc_inv_printable(h).c_str());
}

InvertedListsIOHook* InvertedListsIOHook::lookup_classname(
        const std::string& cn) {
    for (auto hook : io_hook_registry) {
        if (hook->classname == cn) {
            return hook;
        }
    }
    FAISS_THROW_FMT(
            "read_InvertedLists: could not find classname %s",
            cn.c_str());
}

void InvertedListsIOHook::add_callback(InvertedListsIOHook* cb) {
    io_hook_registry.push_back(cb);
}

void InvertedListsIOHook::print_callbacks() {
    printf("registered %zu InvertedListsIOHooks:\n",
           io_hook_registry.size());
    for (auto hook : io_hook_registry) {
        printf("%08x %s %s\n",
               fourcc(hook->key.c_str()),
               hook->key.c_str(),
               hook->classname.c_str());
    }
}

InvertedLists* InvertedListsIOHook::read_ArrayInvertedLists(
        IOReader*,
        int,
        size_t,
        size_t,
        const std::vector<size_t>&) const {
    FAISS_THROW_FMT("read to array not implemented for %s", classname.c_str());
}

} // namespace faiss

