// Calculate shipping cost based on weight and destination type
double computeFreightCharge(int weight, char region) {
    double fee;

    // Handle local shipments
    if (region == 'L') {
        fee = (weight <= 50) ? 5.0 : 8.0;
    }
    // Handle international shipments
    else if (region == 'I') {
        fee = (weight <= 50) ? 12.0 : 20.0;
    }
    // Invalid destination code
    else {
        fee = 0.0;
    }

    return fee;
}

int main() {
    int weightInput;
    std::cout << "Please enter the weight: " << std::endl;
    std::cin >> weightInput;

    char destCode;
    std::cout << "Please enter the destination: " << std::endl;
    std::cin >> destCode;

    double totalFee = computeFreightCharge(weightInput, destCode);

    if (totalFee == 0.0) {
        std::cout << "Invalid Destination Entered" << std::endl;
    } else {
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "The final cost is $" << totalFee << std::endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>
using namespace std;

// Maze dimensions: actual grid size
const int GRID_ROWS = 20;
const int GRID_COLS = 20;

// Logical maze size (cells only, walls are implicit)
const int MAZE_HEIGHT = 10;
const int MAZE_WIDTH = 10;

// Initialize the grid with empty cells ('0')
vector<string> maze_grid(GRID_ROWS, string(GRID_COLS, '0'));

// Track visited logical cells to avoid cycles
vector<vector<bool>> is_visited(MAZE_HEIGHT, vector<bool>(MAZE_WIDTH, false));

// Seeded random number generator for reproducible mazes
mt19937 prng(1337);

// Recursive backtracking function to carve the maze
void carve_maze(int row, int col) {
    // Mark current logical cell as visited and open in the grid
    is_visited[row][col] = true;
    maze_grid[2 * row][2 * col] = '1';

    // Define movement directions: up, down, left, right
    vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Randomize direction order for variety
    shuffle(directions.begin(), directions.end(), prng);

    // Explore each direction
    for (const auto& move : directions) {
        int next_row = row + move.first;
        int next_col = col + move.second;

        // Validate bounds and check if unvisited
        if (next_row >= 0 && next_row < MAZE_HEIGHT &&
            next_col >= 0 && next_col < MAZE_WIDTH &&
            !is_visited[next_row][next_col]) {

            // Carve the wall between current and next cell
            maze_grid[2 * row + move.first][2 * col + move.second] = '1';

            // Continue recursively from the neighbor
            carve_maze(next_row, next_col);
        }
    }
}

int main() {
    // Begin maze generation from top-left logical cell
    carve_maze(0, 0);

    // Output grid dimensions
    cout << GRID_ROWS << " " << GRID_COLS << endl;

    // Print the generated maze
    for (int i = 0; i < GRID_ROWS; ++i) {
        cout << maze_grid[i] << endl;
    }

    return 0;
}

#include <TranslatorRoster.h>
#include <TranslatorFormats.h>
#include <DataIO.h>
#include <File.h>
#include <Entry.h>
#include <Message.h>
#include <iostream>

int main() {
    // Open the Markdown input file in read-only mode
    BFile markdownInput("./sample.md", B_READ_ONLY);
    if (markdownInput.InitCheck() != B_OK) {
        std::cerr << "Error: Unable to open ./sample.md for reading\n";
        return 1;
    }

    // Create or overwrite the output text file
    BFile txtOutput("./sample.txt", B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
    if (txtOutput.InitCheck() != B_OK) {
        std::cerr << "Error: Unable to create ./sample.txt\n";
        return 1;
    }

    // Retrieve the default translator roster
    BTranslatorRoster* roster = BTranslatorRoster::Default();
    if (!roster) {
        std::cerr << "Error: Cannot access default translator roster\n";
        return 1;
    }

    // Build message with file identification metadata
    BMessage identificationParams;
    identificationParams.AddString("name", "./sample.md");
    identificationParams.AddString("BEOS:TYPE", "text/markdown");

    translator_info info;
    status_t identifyResult = roster->Identify(&markdownInput, &identificationParams, &info);

    if (identifyResult == B_OK) {
        const char* translatorName = nullptr;
        const char* translatorDesc = nullptr;
        int32 translatorVersion = 0;

        if (roster->GetTranslatorInfo(info.translator, &translatorName, &translatorDesc, &translatorVersion) == B_OK) {
            std::cout << "Chosen translator: " << translatorName 
                      << " (v" << translatorVersion << ")\n";
            std::cout << "Description: " << translatorDesc << "\n";
        } else {
            std::cerr << "Warning: Could not retrieve translator details\n";
        }
    } else {
        std::cerr << "Error: Translation format identification failed (code: " 
                  << identifyResult << ")\n";
        return 1;
    }

    // Rewind input file to start for translation
    markdownInput.Seek(0, SEEK_SET);

    // Perform actual translation from Markdown to plain text
    status_t translateStatus = roster->Translate(
        &markdownInput, 
        nullptr, 
        &identificationParams, 
        &txtOutput, 
        B_TRANSLATOR_TEXT
    );

    if (translateStatus != B_OK) {
        std::cerr << "Translation process failed with code: " << translateStatus << "\n";
        return 1;
    } else {
        std::cout << "Success: Output saved as ./sample.txt\n";
    }

    return 0;
}

#include <asio.hpp>
#include <boost/bind.hpp>
#include <boost/shared_ptr.hpp>
#include <boost/enable_shared_from_this.hpp>
#include <iostream>
#include <cstdlib>

using asio::ip::tcp;

class connection_handler : public boost::enable_shared_from_this<connection_handler>
{
public:
  explicit connection_handler(asio::io_context& ctx)
    : work_strand_(ctx),
      tcp_socket_(ctx),
      keep_alive_timer_(ctx)
  {
  }

  tcp::socket& get_socket()
  {
    return tcp_socket_;
  }

  void start_processing()
  {
    asio::spawn(work_strand_,
        boost::bind(&connection_handler::handle_echo,
          shared_from_this(), _1));
    asio::spawn(work_strand_,
        boost::bind(&connection_handler::handle_watchdog,
          shared_from_this(), _1));
  }

private:
  void handle_echo(asio::yield_context ctx)
  {
    try
    {
      char buffer[128];
      for (;;)
      {
        keep_alive_timer_.expires_after(std::chrono::seconds(10));
        std::size_t bytes_read = tcp_socket_.async_read_some(asio::buffer(buffer), ctx);
        asio::async_write(tcp_socket_, asio::buffer(buffer, bytes_read), ctx);
      }
    }
    catch (const std::exception&)
    {
      tcp_socket_.close();
      keep_alive_timer_.cancel();
    }
  }

  void handle_watchdog(asio::yield_context ctx)
  {
    while (tcp_socket_.is_open())
    {
      asio::error_code ec;
      keep_alive_timer_.async_wait(ctx[ec]);
      if (keep_alive_timer_.expiry() <= asio::steady_timer::clock_type::now())
        tcp_socket_.close();
    }
  }

  asio::io_context::strand work_strand_;
  tcp::socket tcp_socket_;
  asio::steady_timer keep_alive_timer_;
};

void run_acceptor(asio::io_context& context, unsigned short listening_port, asio::yield_context yield)
{
  tcp::acceptor server(context, tcp::endpoint(tcp::v4(), listening_port));
  for (;;)
  {
    asio::error_code error;
    boost::shared_ptr<connection_handler> client(new connection_handler(context));
    server.async_accept(client->get_socket(), yield[error]);
    if (!error)
      client->start_processing();
  }
}

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: echo_server <port>\n";
      return 1;
    }

    asio::io_context service;
    asio::spawn(service,
        boost::bind(run_acceptor,
          boost::ref(service), static_cast<unsigned short>(std::atoi(argv[1])), _1));
    service.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Runtime error: " << ex.what() << "\n";
  }
  return 0;
}

