// Constructor for PowerPC XCOFF streamer
PPCXCOFFStreamer::PPCXCOFFStreamer(MCContext &Context,
                                   std::unique_ptr<MCAsmBackend> MAB,
                                   std::unique_ptr<MCObjectWriter> OW,
                                   std::unique_ptr<MCCodeEmitter> Emitter)
    : MCXCOFFStreamer(Context, std::move(MAB), std::move(OW),
                      std::move(Emitter)) {}

// Handle emission of prefixed instructions with proper boundary alignment
void PPCXCOFFStreamer::handlePrefixedInstr(const MCInst &Instruction,
                                           const MCSubtargetInfo &STI) {
  // Prefixed instructions require special alignment: prefix must be before a
  // 64-byte boundary, remaining bytes after. Insert nops to maintain this.
  // Try to align to 64-byte boundaries, but limit padding to 4 bytes max.
  unsigned MaxPadding = 4;
  emitCodeAlignment(Align(64), &STI, MaxPadding);

  // Emit the actual instruction - this creates a new fragment as first instr
  MCXCOFFStreamer::emitInstruction(Instruction, STI);
}

// Override instruction emission to handle prefixed instructions specially
void PPCXCOFFStreamer::emitInstruction(const MCInst &Instruction,
                                       const MCSubtargetInfo &STI) {
  // Get the code emitter and check if this is a prefixed instruction
  PPCMCCodeEmitter *CodeEmitter =
      static_cast<PPCMCCodeEmitter *>(getAssembler().getEmitterPtr());

  // If not prefixed, use default handling
  if (!CodeEmitter->isPrefixedInstruction(Instruction)) {
    MCXCOFFStreamer::emitInstruction(Instruction, STI);
    return;
  }

  // For prefixed instructions, apply special alignment handling
  handlePrefixedInstr(Instruction, STI);
}

// Factory function to create a PPC XCOFF streamer instance
MCXCOFFStreamer *
llvm::createPPCXCOFFStreamer(MCContext &Context,
                             std::unique_ptr<MCAsmBackend> MAB,
                             std::unique_ptr<MCObjectWriter> OW,
                             std::unique_ptr<MCCodeEmitter> Emitter) {
  return new PPCXCOFFStreamer(Context, std::move(MAB), std::move(OW),
                              std::move(Emitter));
}

