// Helper to print header/footer consistently
inline void logPenaltyHeader(const std::string& fieldName, bool verbose) {
  if (!verbose) return;
  std::cerr << "\n #### " << fieldName;
  std::cerr << "\n #### =============================================================================\n";
}

inline void logPenaltyFooter(bool verbose) {
  if (!verbose) return;
  std::cerr << " #### =============================================================================\n" << std::endl;
}

// Common loading logic for penalties with scale, stepSize, and optionally relaxation
template <typename ConfigType>
void loadCommonPenaltyConfig(const std::string& fileName,
                             const std::string& fieldName,
                             ConfigType& config,
                             bool verbose,
                             bool hasRelaxation = false) {
  boost::property_tree::ptree pt;
  boost::property_tree::read_info(fileName, pt);

  logPenaltyHeader(fieldName, verbose);

  // Load mandatory fields
  loadPtreeValue(pt, config.scale, fieldName + ".scale", verbose);
  loadPtreeValue(pt, config.stepSize, fieldName + ".stepSize", verbose);

  // Optional: load relaxation only if supported
  if (hasRelaxation) {
    loadPtreeValue(pt, config.relaxation, fieldName + ".relaxation", verbose);
  }

  logPenaltyFooter(verbose);
}

