        void Close();
        double LatencyMs() const;
    };
}

class CommandExecutor {
 public:
    std::mutex mtx;
    std::vector<mongodb_handler::SampleCommand> processed;

    void handle_command(mongodb_handler::SampleCommand cmd) {
        std::lock_guard<std::mutex> guard(mtx);
        processed.push_back(cmd);
    }
};

int main() {
    auto global_start = std::chrono::high_resolution_clock::now();

    const int thread_pool_capacity = 4000;
    CommandExecutor executor;

    // Bind member function to instance for callback
    auto handler = std::bind(&CommandExecutor::handle_command, &executor, std::placeholders::_1);
    mongodb_handler::MongodbConnectionThreadPool pool(thread_pool_capacity, handler);

    // Seed random number generator
    std::srand(static_cast<unsigned>(std::time(nullptr)));

    const int request_count = 100000;
    auto work_start = std::chrono::high_resolution_clock::now();

    for (int idx = 0; idx < request_count; ++idx) {
        mongodb_handler::SampleCommand req{
            std::rand() % 2,
            idx,
            std::rand() % 1000000
        };
        pool.MongodbRequest(req);
    }

    pool.Close();

    auto work_end = std::chrono::high_resolution_clock::now();
    auto setup_time = std::chrono::duration_cast<std::chrono::milliseconds>(work_start - global_start);
    auto exec_time = std::chrono::duration_cast<std::chrono::milliseconds>(work_end - work_start);

    std::cout << "Setup Duration: " << setup_time.count() << " ms" << std::endl;
    std::cout << "Pool Setup Throughput: " << thread_pool_capacity * 1000.0 / setup_time.count() << " connections/sec" << std::endl;
    std::cout << "Execution Time: " << exec_time.count() << " ms" << std::endl;
    std::cout << "Request Rate: " << request_count * 1000.0 / exec_time.count() << " req/sec" << std::endl;
    std::cout << "Avg MongoDB Latency: " << pool.LatencyMs() << " ms" << std::endl;
    std::cout << "Total Commands Processed: " << executor.processed.size() << std::endl;

    return 0;
}

