void mysql_connect_and_create(MYSQL& mysql_conn, const char* sock_path) {
    if (!mysql_real_connect(&mysql_conn, nullptr, "root", "", "mysql", 0, sock_path, 0)) {
        std::cerr << "Failed to connect to MySQL: " << mysql_error(&mysql_conn) << std::endl;
