struct Vehicle {
    char color[32];
    char brand[64];
};

void ndb_run_scan(const char* conn_str) {
    Ndb_cluster_connection cluster_conn(conn_str);

    // Attempt connection with timeout parameters: max 4 retries, wait up to 5 seconds per retry, total timeout 30s
    if (cluster_conn.connect(4, 5, 1) != 0) {
        std::cout << "Unable to connect to cluster within 30 secs." << std::endl;
        std::exit(-1);
    }

    // Wait for cluster readiness (max 30 seconds)
    if (cluster_conn.wait_until_ready(30, 0) < 0) {
        std::cout << "Cluster was not ready within 30 secs.\n";
        std::exit(-1);
    }

    Ndb my_ndb(&cluster_conn, "ndb_examples");
    if (my_ndb.init(1024) == -1) {  // Max 1024 concurrent transactions
        std::cerr << "Ndb init failed: " << my_ndb.getNdbError().message << std::endl;
        std::exit(-1);
    }

    /*******************************************
     * Validate table schema                   *
     *******************************************/
    int color_column_index = -1;
    {
        const NdbDictionary::Dictionary* dict = my_ndb.getDictionary();
        const NdbDictionary::Table* table = dict->getTable("api_scan");
        if (!table) {
            std::cout << "Dictionary::getTable() failed.";
            std::exit(-1);
        }

        Vehicle sample_vehicle;
        const NdbDictionary::Column* col_color = table->getColumn("COLOR");
        const NdbDictionary::Column* col_brand = table->getColumn("BRAND");

        if (!col_color || !col_brand ||
            col_color->getLength() != sizeof(sample_vehicle.color) ||
            col_brand->getLength() != sizeof(sample_vehicle.brand)) {
            std::cout << "Wrong table definition" << std::endl;
            std::exit(-1);
        }

        color_column_index = col_color->getColumnNo();
    }

    if (populate(&my_ndb) > 0)
        std::cout << "populate: Success!" << std::endl;

    if (scan_print(&my_ndb) > 0)
        std::cout << "scan_print: Success!" << std::endl << std::endl;

    std::cout << "Going to delete all pink vehicles!" << std::endl;
    {
        Vehicle temp;
        // Use snprintf for safety instead of sprintf
        snprintf(temp.color, sizeof(temp.color), "Pink");
        if (scan_delete(&my_ndb, color_column_index, temp.color) > 0)
            std::cout << "scan_delete: Success!" << std::endl << std::endl;
    }

    if (scan_print(&my_ndb) > 0)
        std::cout << "scan_print: Success!" << std::endl << std::endl;

    {
        Vehicle v1{}, v2{};
        snprintf(v1.color, sizeof(v1.color), "Blue");
        snprintf(v2.color, sizeof(v2.color), "Black");

        std::cout << "Going to update all " << v1.color << " vehicles to "
                  << v2.color << " vehicles!" << std::endl;
        if (scan_update(&my_ndb, color_column_index, v1.color, v2.color) > 0)
            std::cout << "scan_update: Success!" << std::endl << std::endl;
    }

    if (scan_print(&my_ndb) > 0)
        std::cout << "scan_print: Success!" << std::endl << std::endl;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::cout << "Usage: <socket mysqld> <connect_string cluster>\n";
        std::exit(-1);
    }

    const char* mysql_socket = argv[1];
    const char* cluster_connect_string = argv[2];

    MYSQL mysql_handle;
    mysql_init(&mysql_handle);
    mysql_connect_and_create(mysql_handle, mysql_socket);

    ndb_init();
    ndb_run_scan(cluster_connect_string);
    ndb_end(0);

    mysql_close(&mysql_handle);
    return 0;
}

