namespace YimMenu
{
	Commands::Commands() :
	    IStateSerializer("commands")
	{
	}

	void Commands::RunScript()
	{
		EnableBoolCommands();
		while (g_Running)
		{
			RunLoopedCommands();
			ScriptMgr::Yield();
		}
	}

	void Commands::AddCommandImpl(Command* cmd)
	{
		m_Commands.emplace(cmd->GetHash(), cmd);
	}

	void Commands::AddBoolCommandImpl(BoolCommand* cmd)
	{
		m_BoolCommands.push_back(cmd);
	}

	void Commands::AddLoopedCommandImpl(LoopedCommand* cmd)
	{
		m_LoopedCommands.push_back(cmd);
	}

	void Commands::EnableBoolCommandsImpl()
	{
		for (size_t i = 0; i < m_BoolCommands.size(); ++i)
		{
			BoolCommand* cmd = m_BoolCommands[i];
			if (cmd && cmd->GetState())
				cmd->Initialize();
		}
	}

	void Commands::RunLoopedCommandsImpl()
	{
		for (size_t i = 0; i < m_LoopedCommands.size(); ++i)
		{
			LoopedCommand* cmd = m_LoopedCommands[i];
			if (cmd && cmd->GetState() && cmd->IsReady())
				cmd->Tick();
		}
	}

	Command* Commands::GetCommandImpl(joaat_t hash)
	{
		auto found = m_Commands.find(hash);
		return (found != m_Commands.end()) ? found->second : nullptr;
	}

	void Commands::SaveStateImpl(nlohmann::json& state)
	{
		for (auto&& pair : m_Commands)
		{
			const char* name = pair.second->GetName();
			if (!state.contains(name))
				state[name] = nlohmann::json::object();
			pair.second->SaveState(state[name]);
		}
	}

	void Commands::LoadStateImpl(nlohmann::json& state)
	{
		for (auto&& pair : m_Commands)
		{
			const char* name = pair.second->GetName();
			if (state.contains(name))
				pair.second->LoadState(state[name]);
		}
	}

	void Commands::ShutdownImpl()
	{
		for (size_t i = 0; i < m_LoopedCommands.size(); ++i)
		{
			LoopedCommand* cmd = m_LoopedCommands[i];
			if (cmd && cmd->GetState())
				cmd->Shutdown();
		}
	}
}

