class RelocModifier : public eld::plugin::SectionIteratorPlugin {
public:
  RelocModifier() : SectionIteratorPlugin("RelocModifier") {}

  // Initialization hook — no setup required here
  void Initialize(std::string /*config*/) override {}

  // Process each section — currently unused
  void HandleSection(eld::plugin::Section /*S*/) override {}

  // Final execution step after all sections processed
  eld::plugin::Plugin::Status Execute(bool /*trace*/) override {
    return eld::plugin::Plugin::Status::SUCCESS;
  }

  // Cleanup hook — no cleanup needed
  void Finalize() override {}

  uint32_t GetLastErrorCode() override { return 0; }
  std::string GetLastErrorMessage() override { return "Success"; }
  std::string GetPluginName() override { return "RelocModifier"; }

  eld::plugin::LinkerWrapper* RetrieveLinker() { return Linker; }
};

// Configuration handler for relocation processing
class RelocConfigHandler : public eld::plugin::LinkerPluginConfig {
public:
  RelocConfigHandler(RelocModifier* owner)
      : LinkerPluginConfig(owner), Owner(owner) {}

  void Setup() override {
    // Register the R_HEX_B22_PCREL relocation type for custom handling
    std::string relocName = "R_HEX_B22_PCREL";
    uint32_t type = Owner->RetrieveLinker()->GetRelocationHandler().LookupRelocationType(relocName);
    Owner->RetrieveLinker()->SubscribeToRelocation(type);
  }

  // Callback invoked per matched relocation
  void OnRelocationEvent(eld::plugin::Use& U) override {
    // Log source section and symbol info
    std::string srcSecName = U.GetSourceChunk().GetName();
    std::cout << "Relocation event. Source section: " << srcSecName
              << ", symbol: " << U.GetName() << "\n";

    // Replace 'HelloWorld' symbol with 'HelloQualcomm'
    if (U.GetSymbol().GetName() == "HelloWorld") {
      eld::Expected<eld::plugin::Symbol> symExp =
          Owner->RetrieveLinker()->FindSymbol("HelloQualcomm");
      ELDEXP_REPORT_AND_RETURN_VOID_IF_ERROR(Owner->RetrieveLinker(), symExp);

      eld::plugin::Symbol newSym = symExp.value();
      U.AdjustSymbol(newSym);
    }
  }

private:
  RelocModifier* Owner;
};

// Global plugin instances
eld::plugin::Plugin* MainPluginInstance = nullptr;
eld::plugin::LinkerPluginConfig* MainConfigInstance = nullptr;

extern "C" {

// Register all plugins and configs exposed by this library
bool DLL_A_EXPORT RegisterAll() {
  MainPluginInstance = new RelocModifier();
  MainConfigInstance = new RelocConfigHandler(
      static_cast<RelocModifier*>(MainPluginInstance));
  return true;
}

// Return the registered plugin instance by name
eld::plugin::Plugin* DLL_A_EXPORT GetPlugin(const char* /*name*/) {
  return MainPluginInstance;
}

// Return the associated configuration instance
