  return MainConfigInstance;
}

// Release resources used by this plugin library
void DLL_A_EXPORT ReleaseResources() {
  delete MainConfigInstance;
  MainConfigInstance = nullptr;
  delete MainPluginInstance;
  MainPluginInstance = nullptr;
}
}

#include "server.hpp"
#include <signal.h>
#include <memory>

namespace http {
namespace server {

server::server(const std::string& addr, const std::string& port_num,
    const std::string& root_dir)
  : service_context_(1),
    termination_signals_(service_context_),
    listening_socket_(service_context_),
    active_connections_(),
    request_processor_(root_dir)
{
  // Set up signal handlers for graceful shutdown
  termination_signals_.add(SIGINT);
  termination_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  termination_signals_.add(SIGQUIT);
#endif

  prepare_for_shutdown();

  // Setup network endpoint and acceptor
  asio::ip::tcp::resolver resolver(service_context_);
  auto endpoints = resolver.resolve(addr, port_num);
  auto ep = *endpoints.begin();

  listening_socket_.open(ep.protocol());
  listening_socket_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  listening_socket_.bind(ep);
  listening_socket_.listen();

  start_accepting();
}

void server::execute()
{
  // Run the event loop until all operations complete
  service_context_.run();
}

void server::start_accepting()
{
  listening_socket_.async_accept(
      [this](std::error_code err, asio::ip::tcp::socket client_socket)
      {
        // Verify that the acceptor is still open before proceeding
        if (!listening_socket_.is_open())
        {
          return;
        }

        if (!err)
        {
          active_connections_.add(std::make_shared<connection>(
              std::move(client_socket), active_connections_, request_processor_));
        }

        // Continue accepting new connections
        start_accepting();
      });
}

void server::prepare_for_shutdown()
{
  termination_signals_.async_wait(
