#include <iostream>
#include <vector>
using namespace std;

// Replaced global array with vector for better encapsulation
vector<int> reconstructedArray;
int totalElements;

// Renamed function to reflect its purpose more clearly
void requestRangeInformation(int left, int right, int &modeValue, int &modeCount) {
    if (left > right) {
        modeValue = -1;
        modeCount = -1;
        return;
    }

    cout << "? " << left << " " << right << endl;
    cin >> modeValue >> modeCount;

    // Handle invalid response as per original logic
    if (modeValue == -1) {
        exit(0);
    }
}

// Completely refactored recursive function with different control flow
void determineValues(int segmentStart, int segmentEnd, int precomputedMode, int precomputedCount) {
    // Base case: empty segment
    if (segmentStart > segmentEnd) return;

    int currentMode, currentCount;

    // Use precomputed info if available, otherwise make query
    if (precomputedMode != -1) {
        currentMode = precomputedMode;
        currentCount = precomputedCount;
    } else {
        requestRangeInformation(segmentStart, segmentEnd, currentMode, currentCount);
    }

    int segmentLength = segmentEnd - segmentStart + 1;

    // If all elements are the same (mode dominates entire segment)
    if (currentCount == segmentLength) {
        for (int pos = segmentStart; pos <= segmentEnd; ++pos) {
            reconstructedArray[pos] = currentMode;
        }
        return;
    }

    // Query left portion: [segmentStart, segmentEnd - currentCount]
    int leftMode, leftCount;
    requestRangeInformation(segmentStart, segmentEnd - currentCount, leftMode, leftCount);

    // Check if mode appears in left portion
    if (leftMode == currentMode) {
        // Mode is present in left part, process accordingly
        determineValues(segmentStart, segmentEnd - currentCount, leftMode, leftCount);
        determineValues(segmentEnd - currentCount + 1, segmentEnd, -1, -1);
        return;
    }

    // Query right portion: [segmentStart + currentCount, segmentEnd]
    int rightMode, rightCount;
    requestRangeInformation(segmentStart + currentCount, segmentEnd, rightMode, rightCount);

    // Check if mode appears in right portion
    if (rightMode == currentMode) {
        // Mode is present in right part, process accordingly
        determineValues(segmentStart, segmentStart + currentCount - 1, -1, -1);
        determineValues(segmentStart + currentCount, segmentEnd, rightMode, rightCount);
        return;
    }

    // If mode doesn't dominate either end, it must be in the overlapping region
    // This happens when 2 * currentCount > segmentLength
    if (2 * currentCount > segmentLength) {
        int overlapStart = segmentEnd - currentCount + 1;
        int overlapEnd = segmentStart + currentCount - 1;

        // Fill the guaranteed overlapping region with the mode value
        for (int i = overlapStart; i <= overlapEnd; ++i) {
            reconstructedArray[i] = currentMode;
        }
    }

    // Recursively solve remaining parts using previously obtained query results
    determineValues(segmentStart, segmentEnd - currentCount, leftMode, leftCount);
    determineValues(segmentStart + currentCount, segmentEnd, rightMode, rightCount);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> totalElements)) return 0;

    // Resize vector to accommodate 1-indexed array
    reconstructedArray.resize(totalElements + 1);

    // Start solving from full range [1, totalElements]
    determineValues(1, totalElements, -1, -1);

    // Output final result
    cout << "!";
    for (int i = 1; i <= totalElements; ++i) {
        cout << " " << reconstructedArray[i];
    }
    cout << endl;

    return 0;
}

