using asio::ip::tcp;

//------------------------------------------------------------------------------
// Alternative implementation of async_write_message using a slightly different
// approach to forward the completion token and handle the underlying operation.
template <typename CompletionToken>
auto async_send_message(tcp::socket& sock,
    const char* msg, CompletionToken&& token)
  -> typename asio::async_result<
    typename std::decay<CompletionToken>::type,
    void(std::error_code, std::size_t)>::return_type
{
  // Use std::forward to preserve value category of CompletionToken
  auto wrapped_token = std::forward<CompletionToken>(token);

  // Compute message length manually instead of using std::strlen
  std::size_t len = 0;
  while (msg[len] != '\0') {
    ++len;
  }

  // Perform the actual async write with buffer constructed from message and length
  return asio::async_write(sock,
      asio::buffer(msg, len),
      std::move(wrapped_token));
}

//------------------------------------------------------------------------------
void test_callback_style()
{
  asio::io_context ioc;
  tcp::acceptor acceptor(ioc, {tcp::v4(), 55555});
  tcp::socket client_socket = acceptor.accept();

  // Use a lambda for callback-based handling
  async_send_message(client_socket, "Callback test\r\n",
      [](const std::error_code& ec, std::size_t bytes_transferred)
      {
        if (!ec)
        {
          std::cout << bytes_transferred << " bytes sent successfully\n";
        }
        else
        {
          std::cerr << "Send failed: " << ec.message() << "\n";
        }
      });

  ioc.run();
}

//------------------------------------------------------------------------------
void test_future_style()
{
  asio::io_context ioc;
  tcp::acceptor acceptor(ioc, {tcp::v4(), 55555});
  tcp::socket client_socket = acceptor.accept();

  // Use use_future to get a future result
  auto fut = async_send_message(
      client_socket, "Future test\r\n", asio::use_future);

  ioc.run();

  try
  {
    std::size_t result = fut.get();
    std::cout << result << " bytes transferred\n";
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Exception caught: " << ex.what() << "\n";
  }
}

//------------------------------------------------------------------------------
int main()
{
  test_callback_style();
  test_future_style();
  return 0;
}

