#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int size = nums.size();
        int pivot = -1;

        // Step 1: Locate the rightmost index where nums[i] < nums[i+1]
        for (int idx = size - 2; idx >= 0; --idx) {
            if (nums[idx] < nums[idx + 1]) {
                pivot = idx;
                break;
            }
        }

        // If no pivot found, array is in descending order - reverse to get smallest permutation
        if (pivot == -1) {
            reverse(nums.begin(), nums.end());
        } else {
            // Step 2: Find the smallest element to the right of pivot that is larger than nums[pivot]
            for (int jdx = size - 1; jdx > pivot; --jdx) {
                if (nums[jdx] > nums[pivot]) {
                    swap(nums[jdx], nums[pivot]);
                    break;
                }
            }

            // Step 3: Reverse the suffix after the pivot to get the next lexicographically greater permutation
            reverse(nums.begin() + pivot + 1, nums.end());
        }
    }
};

