// Allocates a new int buffer.
// The new buffer's position will be zero, its limit will be its capacity, and its mark will be undefined.
// It will have a backing array, and its array offset will be zero.
//
// Parameters:
// capacity - The new buffer's capacity, in ints
IntBuffer::IntBuffer(unsigned int capacity) : Buffer(capacity)
{
	buffer = new int[capacity];
	for (unsigned int i = 0; i < capacity; ++i) {
		buffer[i] = 0;
	}
}

// Constructs an IntBuffer using an externally-provided backing array.
IntBuffer::IntBuffer(unsigned int capacity, int* backingArray) : Buffer(capacity)
{
	hasBackingArray = true;
	buffer = backingArray;
}

IntBuffer::~IntBuffer()
{
	if (!hasBackingArray && buffer != nullptr) {
		delete[] buffer;
		buffer = nullptr;
	}
}

int* IntBuffer::getBuffer()
{
	return buffer;
}

// Flips this buffer: sets limit to current position, then resets position to zero.
// If the mark is defined, it is discarded.
//
// Returns:
// This buffer
IntBuffer* IntBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Absolute get method: reads the int at the specified index.
//
// Parameters:
// index - The index from which the int will be read
// Returns:
// The int at the given index
int IntBuffer::get(unsigned int index)
{
	if (index >= m_limit) {
		// In production code, throw appropriate exception here
		// For now, retain assert as placeholder
		// assert(false && "Index out of bounds");
	}
	return buffer[index];
}

// Relative bulk put method (optional operation).
// Copies 'length' elements from 'inputArray', starting at 'offset',
// into this buffer beginning at the current position.
//
// Throws if insufficient space remains or indices are invalid.
//
// Parameters:
// inputArray - Source array
// offset     - Starting index in source array
// length     - Number of elements to copy
// Returns:
// This buffer
IntBuffer* IntBuffer::put(intArray* inputArray, unsigned int offset, unsigned int length)
{
	// Validate preconditions
	if (offset + length > inputArray->length) {
		// Handle error appropriately (e.g., throw exception)
		// assert(false);
		return this;
	}

	// Ensure enough space in destination buffer
	if (m_position + length > m_limit) {
		// assert(false); // Buffer overflow
		return this;
	}

	// Manual copy loop instead of std::copy
	for (unsigned int i = 0; i < length; ++i) {
		buffer[m_position + i] = inputArray->data[offset + i];
	}
	m_position += length;

	return this;
}

// Overload: copies entire array into buffer.
IntBuffer* IntBuffer::put(intArray inputArray)
{
	if (inputArray.length > remaining()) {
		// assert(false); // Not enough space
		return this;
	}

	for (unsigned int i = 0; i < inputArray.length; ++i) {
		buffer[m_position + i] = inputArray.data[i];
	}
	m_position += inputArray.length;

	return this;
}

// Writes the given int into this buffer at the current position,
// then increments the position.
//
// Parameters:
// i - The int to be written
// Returns:
// This buffer
IntBuffer* IntBuffer::put(int i)
{
	if (m_position >= m_limit) {
		// assert(false); // Overflow
		return this;
	}
	buffer[m_position] = i;
	++m_position;
	return this;
}

