#include <iostream>
#include <cstdlib>

// Function to interact with the judge
long long query(long long v, long long x) {
    std::cout << "? " << v << " " << x << std::endl;
    long long result;
    std::cin >> result;
    return result;
}

// Function to submit the answer
void answer(long long s) {
    std::cout << "! " << s << std::endl;
    int feedback;
    std::cin >> feedback;
    if (feedback == -1) {
        // Terminate immediately on incorrect answer
        std::exit(0);
    }
}

void solve() {
    // Find a node on the cycle by starting from node 1 and making a large jump
    long long cycle_node = query(1, 5000000000000000000LL);

    // Phase 1: Determine an upper bound for the cycle length using exponential search
    long long current_length = 1;
    long long farthest_node = query(cycle_node, 1);

    while (farthest_node != cycle_node) {
        farthest_node = query(farthest_node, current_length);
        current_length *= 2;
    }

    // Now we know the cycle length lies in (current_length/2, current_length]
    long long left = current_length / 2 + 1;
    long long right = current_length;
    long long cycle_length = current_length;

    // Phase 2: Binary search within the identified range to find the minimal cycle length
    while (left <= right) {
        long long mid = left + (right - left) / 2;

        // Skip zero-length case (shouldn't happen given constraints)
        if (mid == 0) {
            left = 1;
            continue;
        }

        if (query(cycle_node, mid) == cycle_node) {
            // Found a valid cycle length; try smaller ones
            cycle_length = mid;
            right = mid - 1;
        } else {
            // Not enough steps to complete the cycle; need more
            left = mid + 1;
        }
    }

    answer(cycle_length);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        solve();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <list>
#include <queue>
using namespace std;

// Topological Sorting via Kahn's Algorithm:
// Linear ordering of vertices such that for every directed edge u -> v, vertex u comes before v in the ordering.
// Uses: Dependency resolution, task scheduling, build systems, etc.

class Digraph {
    int vertexCount; // Total number of vertices
    list<int>* adjacencyList; // Adjacency list representation
public:
    Digraph(int V) : vertexCount(V) {
        adjacencyList = new list<int>[V];
    }

    void insertEdge(int from, int to) {
        adjacencyList[from].push_back(to); // Add an edge from 'from' to 'to'
    }

    // Perform topological sort using Kahn's algorithm (BFS-based approach)
    void performTopologicalSort() {
        vector<int> inDegree(vertexCount, 0);

        // Compute in-degrees of all vertices
        for (int u = 0; u < vertexCount; ++u) {
            for (int v : adjacencyList[u]) {
                inDegree[v]++;
            }
        }

        // Enqueue all vertices with in-degree 0
        queue<int> zeroInDegreeQueue;
        for (int i = 0; i < vertexCount; ++i) {
            if (inDegree[i] == 0) {
                zeroInDegreeQueue.push(i);
            }
        }

        vector<int> resultOrder;
        while (!zeroInDegreeQueue.empty()) {
            int current = zeroInDegreeQueue.front();
            zeroInDegreeQueue.pop();
            resultOrder.push_back(current);

            // Decrease in-degree of adjacent vertices
            for (int neighbor : adjacencyList[current]) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) {
                    zeroInDegreeQueue.push(neighbor);
                }
            }
        }

        // Output the topological order
        for (int node : resultOrder) {
            cout << node << " ";
        }
        cout << endl;
    }

    ~Digraph() {
        delete[] adjacencyList;
    }
};

int main() {
    Digraph g(6);
    g.insertEdge(5, 2);
    g.insertEdge(5, 0);
    g.insertEdge(4, 0);
    g.insertEdge(4, 1);
    g.insertEdge(2, 3);
    g.insertEdge(3, 1);

    cout << "Topological Sort (Kahn's Algorithm) of the given graph:\n";
    g.performTopologicalSort();
    return 0;
}
