#include <sol/sol.hpp>
#include <string>
#include <iostream>
#include <vector>

int main() {
    std::cout << "=== coroutine ===" << std::endl;

    sol::state lua_env;
    std::vector<sol::coroutine> task_list;

    // Initialize required Lua libraries
    lua_env.open_libraries(sol::lib::base, sol::lib::coroutine);

    // Create a dedicated thread for task execution
    sol::thread worker_thread = sol::thread::create(lua_env);

    // Register the task starter function
    lua_env.set_function("initiate_task",
        [&worker_thread, &task_list](
            sol::function func, 
            sol::variadic_args args) {

            // Access the state of the worker thread
            sol::state_view worker_state = worker_thread.state();

            // Add the new coroutine to our tracking list
            std::size_t task_id = task_list.size();
            task_list.emplace_back(worker_state, func);

            // Get reference to the newly added coroutine
            sol::coroutine& active_task = task_list[task_id];

            // Execute the coroutine with provided arguments
            int result = active_task(args);
            std::cout << "Initial result: " << result << std::endl;

            // Resume the coroutine without additional arguments
            active_task();
            std::cout << "Finalization complete: " << result << std::endl;
        });

    // Define and execute Lua scripts
    lua_env.script(
        R"(
function entry_point(a, b, c)
    -- Simulate some work
    coroutine.yield(30)
    -- Continue processing
    print(a, b, c)
end

function secondary_entry(p, q)
    coroutine.yield(15)
    print(p, q)
end

-- Start tasks using renamed function name
initiate_task(entry_point, 5, 7, 9)
initiate_task(secondary_entry, 3, 4)
)");

    std::cout << std::endl;
    return 0;
}

