// Select OpenGL version — adjust as needed
constexpr int opengl_api_version = mplot::gl::version_4_1;

// Custom frame class derived from mplot::wx::Frame template
class SineWaveFrame : public mplot::wx::Frame<opengl_api_version>
{
public:
    SineWaveFrame(const wxString& title)
        : mplot::wx::Frame<opengl_api_version>(title)
        , phaseOffset(0.0)
        , graphModel(nullptr)
    {
        auto mainLayout = new wxBoxSizer(wxVERTICAL);

        // Add OpenGL canvas
        mainLayout->Add(this->canvas, 1, wxEXPAND);

        // Bottom panel with controls
        auto controlBar = new wxBoxSizer(wxHORIZONTAL);
        auto colorBtn = new wxButton(this, wxID_ANY, wxT("Pick Graph Color"));
        controlBar->Add(colorBtn, 0, wxALL | wxALIGN_CENTER, FromDIP(12));
        controlBar->AddStretchSpacer();

        mainLayout->Add(controlBar, 0, wxEXPAND);
        SetSizerAndFit(mainLayout);

        // Bind color change event
        colorBtn->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) {
            wxColourData initialData;
            wxColourDialog dlg(this, &initialData);
            if (dlg.ShowModal() == wxID_OK) {
                wxColour col = dlg.GetColourData().GetColour();
                if (graphModel) {
                    // Assuming GraphVisual has setLineColor() — adapt if needed
                    graphModel->setLineColor({col.Red()/255.0f, col.Green()/255.0f, col.Blue()/255.0f});
                    canvas->Refresh(false); // trigger redraw
                }
            }
        });

        // Setup periodic update timer
        updateTimer.SetOwner(this);
        updateTimer.Bind(wxEVT_TIMER, [this](wxTimerEvent&) {
            updateSineCurve();
        });
        updateTimer.Start(30); // ~33 FPS
    }

private:
    double phaseOffset;
    sm::vvec<double> xCoords;
    mplot::GraphVisual<double, opengl_api_version>* graphModel;
    wxTimer updateTimer;

    void initializeRenderingScene()
    {
        if (!canvas->ready()) {
            throw std::runtime_error("OpenGL context not initialized yet.");
        }

        // Create visual model at origin
        auto gv = std::make_unique<mplot::GraphVisual<double, opengl_api_version>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));
        gv->twodimensional(false); // enable 3D rendering

        // Bind to canvas
        canvas->v.bindmodel(gv);

        // Generate x-values: [-π, π] with 100 points
        xCoords.linspace(-sm::mathconst<double>::pi, sm::mathconst<double>::pi, 100);

        // Initial y = sin(x + phaseOffset)
        gv->setdata(xCoords, (xCoords + phaseOffset).sin());

        // Finalize geometry
        gv->finalize();

        // Transfer ownership and store pointer
        graphModel = canvas->v.addVisualModel(std::move(gv));
    }

    void updateSineCurve()
    {
        phaseOffset += 0.02;
        if (phaseOffset > 2 * sm::mathconst<double>::pi) {
            phaseOffset -= 2 * sm::mathconst<double>::pi;
        }

        if (graphModel && canvas->ready()) {
            graphModel->update(xCoords, (xCoords + phaseOffset).sin(), 0);
            canvas->needs_reinit = 0;
            canvas->Refresh(false);
        }
    }

public:
    // Called after Show() to ensure GL context exists
    void prepareGraphics()
    {
        try {
            initializeRenderingScene();
        } catch (const std::exception& e) {
            wxLogError(wxString("Failed to initialize scene: ") + e.what());
        }
    }
};

// Application entry point
class SineApp : public wxApp
{
public:
    bool OnInit() override
    {
        if (!wxApp::OnInit()) return false;

        auto frame = new SineWaveFrame(wxT("Interactive Sine Wave Demo"));
        frame->Show(true);
        frame->prepareGraphics(); // Must happen after Show()

        return true;
    }
};

