#include <catch2/catch_all.hpp>
#include <CLI/CLI.hpp>
#include <vector>
#include "test_config.h"

int main(int argc, char** argv) {
    testing_config::TestSizeConfig config{};
    CLI::App parser{"LLMQ unit tests"};
    parser.allow_extras();

    // Parse command-line options with alternative variable names
    int batch_size = 0;
    int seq_length = 0;
    int channel_count = 0;
    int query_head_count = 0;
    int kv_head_count = 0;

    parser.add_option("-B, --batch", batch_size, "Batch size (B)");
    parser.add_option("-T, --seq", seq_length, "Sequence length (T)");
    parser.add_option("-C, --channels", channel_count, "Channel size (C)");
    parser.add_option("--query-heads", query_head_count, "Query heads (Nq)");
    parser.add_option("--kv-heads", kv_head_count, "Key/Value heads (Nkv)");

    std::vector<std::string> leftover_args;
    try {
        parser.parse(argc, argv);
        leftover_args = parser.remaining();
    } catch (const CLI::ParseError &err) {
        return parser.exit(err);
    }

    // Populate the configuration struct from parsed values
    config.B = batch_size;
    config.T = seq_length;
    config.C = channel_count;
    config.Nq = query_head_count;
    config.Nkv = kv_head_count;

    testing_config::set_test_config(config);

    // Prepare arguments for Catch2 runner
    std::vector<const char*> catch_args;
    catch_args.reserve(1 + leftover_args.size());
    catch_args.push_back(argv[0]);

    for (const auto& arg_str : leftover_args) {
        catch_args.push_back(arg_str.c_str());
    }

    return Catch::Session().run(static_cast<int>(catch_args.size()), 
                                const_cast<char**>(catch_args.data()));
}

#include <iostream>
