// Custom smart pointer wrapper to simulate Lua's usertype behavior with initializers
struct holy {
private:
    int value;

    holy() : value(0) {}
    holy(int v) : value(v) {}

public:
    ~holy() {}

    struct custom_deleter {
        void operator()(holy* ptr) const {
            destroy_instance(*ptr);
        }
    };

    static std::unique_ptr<holy, custom_deleter> factory_create() {
        std::cout << "creating 'holy' unique_ptr directly and "
                     "letting sol/Lua handle it"
                  << std::endl;
        return std::unique_ptr<holy, custom_deleter>(new holy(50));
    }

    static void construct_at(void* mem) {
        std::cout << "initializing 'holy' userdata at "
                  << mem
                  << std::endl;
        new (mem) holy();
    }

    static void destroy_instance(holy& instance) {
        std::cout << "destroying 'holy' userdata at "
                  << &instance
                  << std::endl;
        instance.~holy();
    }

    int get_value() const { return value; }
};

int main() {
    std::cout << "=== usertype_initializers ===" << std::endl;

    // Simulate Lua environment behavior manually
    {
        // Create instances using our factory and constructor
        auto h1 = holy::factory_create();

        // Allocate raw memory for second instance
        alignas(holy) unsigned char storage[sizeof(holy)];
        holy* h2_ptr = reinterpret_cast<holy*>(storage);

        // Manually invoke placement new constructor
        holy::construct_at(h2_ptr);

        // Use the objects
        std::cout << "h1.value is " << h1->get_value() << std::endl;
        std::cout << "h2.value is " << h2_ptr->get_value() << std::endl;

        // Verify expected values
        if (h1->get_value() != 50) {
            std::cerr << "Assertion failed: h1.value should be 50" << std::endl;
            return 1;
        }
        if (h2_ptr->get_value() != 0) {
            std::cerr << "Assertion failed: h2.value should be 0" << std::endl;
            return 1;
        }

        // Explicitly destroy h2 before scope ends
        h2_ptr->~holy();
    }

    std::cout << std::endl;
    return 0;
}

#include <algorithm>
#include "IRsend.h"

// Constants
const uint16_t kGlobalCacheMaxRepeat = 50;
const uint32_t kGlobalCacheMinUsec = 80;
const uint8_t kGlobalCacheFreqIndex = 0;
const uint8_t kGlobalCacheRptIndex = kGlobalCacheFreqIndex + 1;
const uint8_t kGlobalCacheRptStartIndex = kGlobalCacheRptIndex + 1;
const uint8_t kGlobalCacheStartIndex = kGlobalCacheRptStartIndex + 1;

#if SEND_GLOBALCACHE
/// Send a shortened GlobalCache (GC) IRdb/control tower formatted message.
/// Status: STABLE / Known working.
/// @param[in] buf Array of uint16_t containing the shortened GlobalCache data.
/// @param[in] len Nr. of entries in the buf[] array.
/// @note Global Cache format without the emitter ID or request ID.
///  Starts at the frequency (Hertz), followed by nr. of times to emit (count),
///  then the offset for repeats (where a repeat will start from),
///  then the rest of entries are the actual IR message as units of periodic
///  time.
///  e.g. sendir,1:1,1,38000,1,1,9,70,9,30,9,... -> 38000,1,1,9,70,9,30,9,...
/// @see https://irdb.globalcache.com/Home/Database
void IRsend::sendGC(uint16_t buf[], uint16_t len) {
  // Extract frequency and set up output
  uint16_t carrier_freq = buf[kGlobalCacheFreqIndex];
  enableIROut(carrier_freq);

  // Calculate microsecond duration per period unit
  uint32_t usec_per_unit = calcUSecPeriod(carrier_freq, false);

  // Determine how many times to transmit (with max limit)
  uint16_t raw_repeats = buf[kGlobalCacheRptIndex];
  uint8_t actual_emits = (raw_repeats < kGlobalCacheMaxRepeat) ? 
                         static_cast<uint8_t>(raw_repeats) : 
                         kGlobalCacheMaxRepeat;

  // Main transmission loop
  for (uint8_t pass = 0; pass < actual_emits; pass++) {
    // Set starting position for this pass
    uint16_t current_pos = kGlobalCacheStartIndex;

    // For subsequent passes, apply repeat offset
    if (pass > 0) {
      current_pos += buf[kGlobalCacheRptStartIndex] - 1;
    }

    // Process each data element
    while (current_pos < len) {
      // Convert GC units to microseconds, enforcing minimum value
      uint32_t pulse_duration = buf[current_pos] * usec_per_unit;
      if (pulse_duration < kGlobalCacheMinUsec) {
        pulse_duration = kGlobalCacheMinUsec;
      }

      // Determine whether this is a mark or space based on position parity
      if ((current_pos % 2) == 1) {
        mark(pulse_duration);
      } else {
        space(pulse_duration);
      }

      current_pos++;
    }
  }

  // Ensure LED is turned off after transmission completes
  ledOff();
}
#endif

#include <iostream>

int main() {
    // Disable synchronization for faster I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int distance;
    std::cin >> distance;

    // Continue until we reach the destination (distance becomes 0)
    while (distance > 0) {
        int result;
        int next_distance;

        // Attempt path with color 0
        std::cout << "move 0" << std::endl;
        std::cin >> result;
        if (result == 1) break; // Destination reached

        std::cout << "query" << std::endl;
        std::cin >> next_distance;
        if (next_distance < distance) {
            distance = next_distance;
            continue;
        }

        // Backtrack from color 0 attempt
        std::cout << "move 0" << std::endl;
        std::cin >> result;

        // Attempt path with color 1
        std::cout << "move 1" << std::endl;
        std::cin >> result;
        if (result == 1) break; // Destination reached

        std::cout << "query" << std::endl;
        std::cin >> next_distance;
        if (next_distance < distance) {
            distance = next_distance;
            continue;
        }

        // Backtrack from color 1 attempt
        std::cout << "move 1" << std::endl;
        std::cin >> result;

        // Since colors 0 and 1 didn't help, try color 2
        std::cout << "move 2" << std::endl;
        std::cin >> result;
        if (result == 1) break; // Destination reached

        // Update distance since we know we moved closer without querying
        distance--;
    }

    return 0;
}

#include <Alembic/Abc/All.h>
#include <Alembic/AbcCoreOgawa/All.h>
#include <Alembic/AbcMaterial/OMaterial.h>
#include <Alembic/AbcMaterial/IMaterial.h>
#include <Alembic/AbcMaterial/MaterialFlatten.h>
#include "PrintMaterial.h"

namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

void createMaterials()
{
    Abc::OArchive archive(
        Alembic::AbcCoreOgawa::WriteArchive(), "FlattenMaterial.abc");
    Abc::OObject root(archive, Abc::kTop);

    // Create container object for materials
    Abc::OObject matContainer(root, "materials");

    // Define parent material with shaders and parameters
    Mat::OMaterial parentMat(matContainer, "parentMaterial");
    auto& parentSchema = parentMat.getSchema();

    parentSchema.setShader("prman", "surface", "paintedplastic");
    parentSchema.setShader("prman", "displacement", "knobby");

    // Set surface shader parameters
    {
        Abc::OFloatProperty kdProp(
            parentSchema.getShaderParameters("prman", "surface"), "Kd");
        kdProp.set(0.5);
    }
    {
        Abc::OStringProperty texNameProp(
            parentSchema.getShaderParameters("prman", "surface"), "texname");
        texNameProp.set("taco");
    }

    // Set displacement shader parameters
    {
        Abc::OFloatProperty heightProp(
            parentSchema.getShaderParameters("prman", "displacement"), "height");
        heightProp.set(0.75);
    }

    // Create child material inheriting from parent
    Mat::OMaterial childMat(parentMat, "childMaterial");
    auto& childSchema = childMat.getSchema();

    childSchema.setShader("prman", "surface", "betterpaintedplastic");

    // Override texture name in child
    {
        Abc::OStringProperty texNameProp(
            childSchema.getShaderParameters("prman", "surface"), "texname");
        texNameProp.set("cheese");
    }
}

void inspectMaterials()
{
    Abc::IArchive archive(Alembic::AbcCoreOgawa::ReadArchive(),
        "FlattenMaterial.abc");
    Abc::IObject topObj = archive.getTop();
    Abc::IObject matObj(topObj, "materials");

    Mat::IMaterial parentMat(matObj, "parentMaterial");
    Mat::IMaterial childMat(parentMat, "childMaterial");

    std::cout << "----------------------------------------\n";
    std::cout << "LOCAL\n";
    std::cout << "---------------------------\n";
    std::cout << "Local parent material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(parentMat.getSchema());

    std::cout << "---------------------------\n";
    std::cout << "Local child material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(childMat.getSchema());

    std::cout << "----------------------------------------\n";
    std::cout << "FLATTENED\n";
    printFlattenedMaterial(parentMat);
    printFlattenedMaterial(childMat);
}

int main(int argc, char* argv[])
{
    createMaterials();
    inspectMaterials();
    return 0;
}

