namespace FFBEngineTests {

// Helper to find preset index by name (refactored for clarity)
static int FindPresetIndexByName(const std::string& name) {
    for (size_t idx = 0; idx < Config::presets.size(); ++idx) {
        if (Config::presets[idx].name == name) {
            return static_cast<int>(idx);
        }
    }
    return -1;
}

TEST_CASE(test_issue_42_ffb_inversion_persistence, "Config") {
    std::cout << "\nTest: Issue #42 - FFB Inversion Persistence Across Presets" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);
    Config::LoadPresets();

    // ===== Scenario A: Start with inversion ON =====
    FFBEngineTestAccess::SetInvertForce(engine, true);
    ASSERT_TRUE(engine.m_invert_force);

    Config::ApplyPreset(0, engine); // Apply "Default"
    ASSERT_TRUE(engine.m_invert_force); // Must stay true

    int t300_idx = FindPresetIndexByName("T300");
    if (t300_idx >= 0) {
        Config::ApplyPreset(t300_idx, engine);
        ASSERT_TRUE(engine.m_invert_force); // Should remain true
    }

    // ===== Scenario B: Start with inversion OFF =====
    FFBEngineTestAccess::SetInvertForce(engine, false);
    ASSERT_FALSE(engine.m_invert_force);

    Config::ApplyPreset(0, engine); // Apply "Default"
    ASSERT_FALSE(engine.m_invert_force); // Must stay false

    if (t300_idx >= 0) {
        Config::ApplyPreset(t300_idx, engine);
        ASSERT_FALSE(engine.m_invert_force); // Should remain false
    }

    // ===== Scenario C: Verify preset update doesn't capture inversion state =====
    // Create a custom preset, simulate user workflow
    Preset user_preset("UserTest", false);

    // Set engine inversion to true, then save to preset
    FFBEngineTestAccess::SetInvertForce(engine, true);
    user_preset.UpdateFromEngine(engine);

    // Change engine inversion back to false *before* applying preset
    FFBEngineTestAccess::SetInvertForce(engine, false);
    user_preset.Apply(engine);

    // After applying, inversion should still be false — preset didn’t override it
    ASSERT_FALSE(engine.m_invert_force);
}

TEST_CASE(test_issue_42_ffb_inversion_global_persistence, "Config") {
    std::cout << "\nTest: Issue #42 - FFB Inversion Global Persistence (Save/Load)" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);
    const std::string test_ini_path = "test_issue_42_persistence.ini";

    // ===== Test Save/Load with True =====
    FFBEngineTestAccess::SetInvertForce(engine, true);
    Config::Save(engine, test_ini_path);

    FFBEngine loaded_engine_1;
    FFBEngineTestAccess::SetInvertForce(loaded_engine_1, false); // Intentionally corrupt initial state
    Config::Load(loaded_engine_1, test_ini_path);
    ASSERT_TRUE(loaded_engine_1.m_invert_force); // Must restore saved value

    // ===== Test Save/Load with False =====
    FFBEngineTestAccess::SetInvertForce(engine, false);
    Config::Save(engine, test_ini_path);

    FFBEngine loaded_engine_2;
    FFBEngineTestAccess::SetInvertForce(loaded_engine_2, true); // Corrupt again
    Config::Load(loaded_engine_2, test_ini_path);
    ASSERT_FALSE(loaded_engine_2.m_invert_force); // Must restore saved value

    // Cleanup
    std::remove(test_ini_path.c_str());
}

