#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <cassert>

int main(int, char*[]) {
    sol::state lua;
    lua.script("function func (a, b) return (a + b) * 2 end");

    // Retrieve the function reference
    sol::reference func_ref = lua["func"];

    // Push the function onto the stack manually
    func_ref.push();

    // Get the underlying Lua state
    lua_State* L = lua.lua_state();

    // Create a stack-aligned unsafe function from the top of the stack
    sol::stack_aligned_unsafe_function func(L, -1);

    // Push arguments onto the stack: first argument is 5, second is 6
    lua_pushinteger(L, 3);
    lua_pushinteger(L, 8);

    // Call the function with 2 arguments; expects 1 result
    int result_count = func(sol::stack_count(2));

    // Verify the result is correct: (3 + 8) * 2 = 22
    assert(result_count == 1); // One result returned
    int result_value = lua_tointeger(L, -1);
    assert(result_value == 22);

    // Ensure stack is clean and balanced
    assert(lua.stack_top() == 0);

    return 0;
}

