#include <iostream>
using namespace std;

class Distance {
private:
    int feet, inches;
public:
    void input();
    void display();
    Distance combine(Distance d);
};

void Distance::input() {
    cout << "Enter feet and inches: ";
    cin >> feet >> inches;
}

void Distance::display() {
    cout << feet << " feet " << inches << " inches" << endl;
}

Distance Distance::combine(Distance d) {
    Distance temp;
    temp.feet = feet + d.feet;
    temp.inches = inches + d.inches;

    if (temp.inches >= 12) {
        temp.feet += temp.inches / 12;
        temp.inches = temp.inches % 12;
    }

    return temp;
}

int main() {
    Distance d1, d2, d3;
    d1.input();
    d2.input();
    d1.display();
    d2.display();
    d3 = d1.combine(d2);
    d3.display();
    return 0;
}

