namespace s11n_example {

/// Client class to fetch stock data from a remote server
class client
{
public:
  /// Constructor initiates the connection process asynchronously
  client(asio::io_context& ctx,
      const std::string& hostname, const std::string& port)
    : conn_(ctx)
  {
    // Convert host and service into endpoints using resolver
    asio::ip::tcp::resolver rslv(ctx);
    asio::ip::tcp::resolver::query q(hostname, port);
    auto ep_iter = rslv.resolve(q);

    // Begin asynchronous connection
    asio::async_connect(conn_.socket(), ep_iter,
        boost::bind(&client::on_connection_complete, this,
          asio::placeholders::error));
  }

  /// Called when the connect operation finishes
  void on_connection_complete(const asio::error_code& err)
  {
    if (!err)
    {
      // Connection successful — start receiving stock data
      conn_.async_read(stock_list_,
          boost::bind(&client::on_data_received, this,
            asio::placeholders::error));
    }
    else
    {
      // Log error and terminate
      std::cerr << "Connection failed: " << err.message() << std::endl;
    }
  }

  /// Called after reading stock list from server
  void on_data_received(const asio::error_code& err)
  {
    if (!err)
    {
      // Output each stock record in a formatted way
      for (std::size_t idx = 0; idx < stock_list_.size(); ++idx)
      {
        const auto& s = stock_list_[idx];
        std::cout << "Stock #" << idx << ":\n";
        std::cout << "  Code: " << s.code << "\n";
        std::cout << "  Name: " << s.name << "\n";
        std::cout << "  Open: " << s.open_price << "\n";
        std::cout << "  High: " << s.high_price << "\n";
        std::cout << "  Low: " << s.low_price << "\n";
        std::cout << "  Last: " << s.last_price << "\n";
        std::cout << "  Buy: " << s.buy_price << " @ " << s.buy_quantity << "\n";
        std::cout << "  Sell: " << s.sell_price << " @ " << s.sell_quantity << "\n";
      }
    }
    else
    {
      std::cerr << "Read error: " << err.message() << std::endl;
    }
    // No further operations scheduled — io_context will exit naturally
  }

private:
  connection conn_;                 // Active connection to server
  std::vector<stock> stock_list_;   // Container for received stock records
};

} // namespace s11n_example

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: " << argv[0] << " <host> <port>" << std::endl;
      return 1;
    }

    asio::io_context ioc;
    s11n_example::client cli(ioc, argv[1], argv[2]);
    ioc.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Exception: " << ex.what() << std::endl;
    return 1;
  }

  return 0;
}

class Solution {
public:
    int smallestNumber(int n) {
        // Handle edge case where n might be 0
        if (n <= 0) return 0;

        // Set all bits below the highest set bit
        int result = n;
        result |= result >> 1;
        result |= result >> 2;
        result |= result >> 4;
        result |= result >> 8;
        result |= result >> 16;

        return result;
    }
};

