    }
};

// A pollable that never throws and always succeeds
struct SafePollable : arc::NoexceptPollable<SafePollable, void> {
    bool poll(arc::Context& cx) noexcept {
        return true;
    }
};

// Main asynchronous function demonstrating exception handling in coroutines
Future<> asyncMain() {
    // First, await a safe pollable without risk of exceptions
    co_await SafePollable{};

    // Then attempt to await the throwing pollable inside a try-catch block
    try {
        co_await ExceptionThrowingPollable{};
        fmt::println("No exception was thrown (unexpected)");
    } catch (const std::exception& ex) {
        fmt::println("Caught standard exception from ExceptionThrowingPollable: {}", ex.what());
    } catch (...) {
        fmt::println("Caught non-standard exception from ExceptionThrowingPollable");
    }
}

ARC_DEFINE_MAIN_NT(asyncMain, 1);

