namespace rccl {

namespace {

// Helper to extract file name safely at compile/runtime
inline const char* get_file_name() {
    static const std::string filename = ROCP_REG_FILE_NAME;
    return filename.c_str();
}

// Global API table pointer — now guarded by mutex instead of atomic CAS
static std::mutex s_api_table_mutex;
static rcclApiFuncTable* s_const_api_table_ptr = nullptr;
static rcclApiFuncTable* s_profiler_api_table_ptr = nullptr;

// Initialize constant API table from library import
void setup_const_api_table() {
    if (!s_const_api_table_ptr) {
        static rcclApiFuncTable const_table{};
        initialize_rccl_api_table(&const_table);
        s_const_api_table_ptr = &const_table;
    }
}

// Copy and prepare profiler-modifiable API table
void setup_profiler_api_table() {
    if (!s_profiler_api_table_ptr) {
        static rcclApiFuncTable profiler_table{};
        copy_rccl_api_table(&profiler_table, s_const_api_table_ptr);
        s_profiler_api_table_ptr = &profiler_table;
    }
}

// Register the RCCL library with rocprofiler
void do_registration() {
    setup_const_api_table();
    setup_profiler_api_table();

    void* profiler_table_ptr = static_cast<void*>(s_profiler_api_table_ptr);

    rocprofiler_register_library_indentifier_t lib_id{};
    auto result = rocprofiler_register_library_api_table(
        "rccl",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rccl),
        ROCP_REG_VERSION,
        &profiler_table_ptr,
        1,
        &lib_id);

    if (result == 0) {
        std::cout << "[" << get_file_name() << "] rccl identifier " << lib_id.handle << "\n";

        // Atomically swap tables under lock
        std::lock_guard<std::mutex> lock{s_api_table_mutex};
        s_const_api_table_ptr = s_profiler_api_table_ptr;
    } else if (result != ROCP_REG_NO_TOOLS) {
        std::cerr << "rccl library failed to register with rocprofiler-register: "
                  << rocprofiler_register_error_string(result) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

// Registration guard flag
static std::once_flag s_registration_flag;
static std::atomic<bool> s_is_registered{false};

// Thread-safe registration wrapper
void ensure_registered() {
    if (!s_is_registered.load(std::memory_order_acquire)) {
        std::lock_guard<std::mutex> guard{s_api_table_mutex};
        if (!s_is_registered.load(std::memory_order_relaxed)) {
            std::call_once(s_registration_flag, do_registration);
            s_is_registered.store(true, std::memory_order_release);
        }
    }
}

} // anonymous namespace

// Public accessor for current API table
rcclApiFuncTable* get_rccl_api_table() {
    ensure_registered();
    std::lock_guard<std::mutex> lock{s_api_table_mutex};
    return s_const_api_table_ptr;
}

// Initialization hook
void rccl_init_internal() {
    std::cout << "[" << get_file_name() << "] " << __FUNCTION__ << "\n";
}

} // namespace rccl

