using Row_t = Table::Row_t;

int main() {
  Table table;

  // Add header row
  table.add_row(Row_t{"Company", "Contact", "Country"});

  // Add data rows using a vector for cleaner initialization
  std::vector<Row_t> dataRows = {
    Row_t{"Alfreds Futterkiste", "Maria Anders", "Germany"},
    Row_t{"Centro comercial Moctezuma", "Francisco Chang", "Mexico"},
    Row_t{"Ernst Handel", "Roland Mendel", "Austria"},
    Row_t{"Island Trading", "Helen Bennett", "UK"},
    Row_t{"Laughing Bacchus Winecellars", "Yoshi Tannamuri", "Canada"},
    Row_t{"Magazzini Alimentari Riuniti", "Giovanni Rovelli", "Italy"}
  };

  for (const auto& row : dataRows) {
    table.add_row(row);
  }

  // Set column widths
  table.column(0).format().width(40);
  table.column(1).format().width(30);
  table.column(2).format().width(30);

  // Apply formatting to header row cells
  for (auto& cell : table[0]) {
    cell.format().font_style({FontStyle::underline}).font_align(FontAlign::center);
  }

  // Right-align company names (excluding header)
  for (size_t i = 1; i < table.size(); ++i) {
    auto& cell = table[i][0];
    if (cell.get_text() != "Company") {
      cell.format().font_align(FontAlign::right);
    }
  }

  // Apply bold styling and alternating blue background to rows
  size_t rowIndex = 0;
  for (auto& row : table) {
    row.format().font_style({FontStyle::bold});

    // Apply blue background to even-indexed rows after the header
    if (rowIndex > 0 && rowIndex % 2 == 0) {
      for (auto& cell : row) {
        cell.format().font_background_color(Color::blue);
      }
    }
    rowIndex++;
  }

  std::cout << table << std::endl;
  return 0;
}

