void XmlSailWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("xflsail");
    writeAttribute("version", "1.0");
    writeComment("The fields in this section specify the factors to apply to convert the units of this file to IS units."
                 "The section should be the first in the file.");
    writeUnits();
}

void XmlSailWriter::writeXMLSail(Sail *pSail)
{
    writeStartDocument();
    writeHeader();

    if (pSail->isNURBSSail()) {
        SailNurbs *pNS = dynamic_cast<SailNurbs*>(pSail);
        writeNURBSSail(pNS, Vector3d());
    } 
    else if (pSail->isSplineSail()) {
        const SailSpline *pSSail = static_cast<const SailSpline*>(pSail);
        writeSplineSail(pSSail, Vector3d());
    } 
    else if (pSail->isWingSail()) {
        const SailWing *pWSail = static_cast<const SailWing*>(pSail);
        writeWingSail(pWSail, Vector3d());
    }

    writeEndElement();
    writeEndDocument();
}

#include "Python.h"

/* Safe string formatting functions with consistent behavior across platforms.
   These wrappers ensure null-termination and handle platform-specific
   differences in vsnprintf implementations. */
int
PyOS_snprintf(char *str, size_t size, const char *format, ...)
{
    int result;
    va_list args;
    va_start(args, format);
    result = PyOS_vsnprintf(str, size, format, args);
    va_end(args);
    return result;
}

int
PyOS_vsnprintf(char *str, size_t size, const char *format, va_list args)
{
    /* Validate preconditions */
    assert(str != NULL);
    assert(size > 0);
    assert(size <= (INT_MAX - 1));
    assert(format != NULL);

    int written;  /* Number of characters written, not counting '\0' */

    /* Check for potential overflow on size conversion */
    if (size > INT_MAX - 1) {
        written = -666;
        goto Terminate;
    }

#if defined(_MSC_VER)
    /* Microsoft Visual C++ specific handling */
    written = _vsnprintf(str, size, format, args);
#else
    /* Standard C99-compliant implementation */
    written = vsnprintf(str, size, format, args);
#endif

Terminate:
    /* Ensure buffer is always null-terminated */
    if (size > 0) {
        str[size - 1] = '\0';
    }

    return written;
}

