#include <iostream>
#include <string>
#include <asio/ip/tcp.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[]) {
    try {
        if (argc != 3) {
            std::cerr << "Usage: http_client <server> <path>\n";
            std::cerr << "Example:\n";
            std::cerr << "  http_client www.boost.org /LICENSE_1_0.txt\n";
            return 1;
        }

        tcp::iostream connection;
        // Set timeout for the entire operation
        connection.expires_after(std::chrono::seconds(60));

        // Connect to the server using hostname and service name
        connection.connect(argv[1], "http");
        if (!connection) {
            std::cerr << "Connection failed: " << connection.error().message() << "\n";
            return 1;
        }

        // Build and send HTTP request
        connection << "GET " << argv[2] << " HTTP/1.0\r\n"
                   << "Host: " << argv[1] << "\r\n"
                   << "Accept: */*\r\n"
                   << "Connection: close\r\n\r\n";

        // Read and validate HTTP response line
        std::string version;
        unsigned int code;
        std::string message;

        connection >> version >> code;
        std::getline(connection, message);

        // Verify HTTP response format and status
        if (!connection || version.substr(0, 5) != "HTTP/") {
            std::cerr << "Malformed HTTP response\n";
            return 1;
        }
        if (code != 200) {
            std::cerr << "HTTP error: " << code << " " << message << "\n";
            return 1;
        }

        // Print headers until blank line
        std::string line;
        while (std::getline(connection, line)) {
            if (line.empty() || line == "\r") break;
            std::cout << line << "\n";
        }
        std::cout << "\n";

        // Output remaining body content
        std::cout << connection.rdbuf();

    } catch (const std::exception& ex) {
        std::cerr << "Runtime error: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

