using namespace std;

int main() {
    // Initialize a string variable
    string text = "hello world";

    // Display the initial string
    cout << "Text: " << text << endl;

    // Another string with different content
    string phrase = "Learning C++ is fun!";

    // Concatenate and display both strings
    cout << text + " " + phrase << endl;

    // Compare the two strings lexicographically
    cout << (text == phrase) << endl;  // Outputs 0 (false)
    cout << (text < phrase) << endl;   // Outputs 1 (true)

    // Output the length of the first string
    cout << text.size() << endl;  // Equivalent to length()

    // Read a single word from user input
    string inputWord;
    cout << "Enter a word: ";
    cin >> inputWord;
    cout << "You entered: " << inputWord << endl;

    // Clear the newline character left in the buffer after cin
    cin.ignore();  // Discard the newline character

    // Read a full line including spaces
    string fullLine;
    cout << "Enter a sentence: ";
    getline(cin, fullLine);
    cout << "You entered: " << fullLine << endl;

    // Print characters using index-based loop
    for (int idx = 0; idx < text.length(); ++idx) {
        cout << text[idx];
    }
    cout << endl;

    // Print characters using range-based for loop
    for (char c : phrase) {
        cout << c;
    }
    cout << endl;

    // Reverse the second user-input string
    reverse(fullLine.begin(), fullLine.end());
    cout << "Reversed: " << fullLine << endl;

    return 0;
}

#include <hip/hip_runtime.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>

int main() {
    // Initialize the HIP runtime environment
    hipError_t init_result = hipInit(0);
    if (init_result != hipSuccess) {
        std::cerr << "HIP runtime initialization failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Retrieve the per-thread default stream
    hipStream_t worker_stream = hipStreamPerThread;

    // Allocate device memory using the obtained stream context
    void* device_buffer = nullptr;
    const std::size_t buffer_size = 1024;

    hipError_t alloc_result = hipMalloc(&device_buffer, buffer_size);
    if (alloc_result != hipSuccess) {
        std::cerr << "Device memory allocation failed." << std::endl;
        return EXIT_FAILURE;
    }

    // Asynchronously initialize the allocated memory to zero
    hipError_t memset_result = hipMemsetAsync(device_buffer, 0, buffer_size, worker_stream);
    if (memset_result != hipSuccess) {
        std::cerr << "Memory initialization operation failed." << std::endl;
        hipFree(device_buffer);  // Clean up before exiting
        return EXIT_FAILURE;
    }

    // Ensure all operations in the stream are completed
    hipError_t sync_result = hipStreamSynchronize(worker_stream);
    if (sync_result != hipSuccess) {
        std::cerr << "Stream synchronization failed." << std::endl;
        hipFree(device_buffer);  // Clean up before exiting
        return EXIT_FAILURE;
    }

    // Release the device memory
    hipError_t free_result = hipFree(device_buffer);
    if (free_result != hipSuccess) {
        std::cerr << "Memory deallocation failed." << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "All operations completed successfully with per-thread stream." << std::endl;
    return EXIT_SUCCESS;
}

