    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    unsigned int k;
    std::cin >> k;

    // Handle base case directly
    if (k == 1) {
        std::cout << 1 << "\n";
        std::cout << "HALT PUSH 1 GOTO 1\n";
        return 0;
    }

    // Calculate q = (k-1)/2 using bit shifting instead of division
    unsigned int q = (k - 1) >> 1;

    // Convert q to binary using built-in bit operations
    std::vector<int> binary_digits;

    // Use do-while loop to ensure at least one iteration for q=0 case
    if (q == 0) {
        binary_digits.push_back(0);
    } else {
        unsigned int current_value = q;
        while (current_value > 0) {
            // Extract least significant bit using bitwise AND
            binary_digits.push_back(current_value & 1);
            // Right shift by 1 bit
            current_value >>= 1;
        }
    }

    // Reverse to get MSB first order
    std::reverse(binary_digits.begin(), binary_digits.end());

    // Determine number of bits needed
    int m = static_cast<int>(binary_digits.size());
    if (q == 0) m = 0;

    // Calculate total number of instructions
    int n = m + 3;
    std::cout << n << "\n";

    // First instruction: entry point
    std::cout << "POP 1 GOTO 2 PUSH 1 GOTO 2\n";

    // Generate middle instructions based on each bit
    for (int i = 0; i < m; ++i) {
        int instruction_index = i + 2;
        if (binary_digits[i] == 1) {
            std::cout << "HALT PUSH 1 GOTO " << (instruction_index + 1) << "\n";
        } else {
            std::cout << "POP 1 GOTO " << (m + 2) << " PUSH 2 GOTO " << (instruction_index + 1) << "\n";
        }
    }

    // Return mechanism instruction
    std::cout << "POP 1 GOTO 2 PUSH 2 GOTO " << (m + 2) << "\n";

    // Final halt instruction
    std::cout << "HALT PUSH 99 GOTO " << (m + 2) << "\n";

    return 0;
}

#include "rslcpp/rslcpp.hpp"
#include <limits>
#include <rslcpp_exceptions/exceptions.hpp>

namespace rslcpp
{

exit_code_t run_job(int argc, char ** argv, Job::SharedPtr job)
{
  // Acquire singleton time delay backend instance
  time_delay::CallbackBackend & time_backend = time_delay::CallbackBackend::getInstance();

  // Initialize ROS 2 context
  rclcpp::InitOptions init_opts;
  rclcpp::init(argc, argv, init_opts);

  // Retrieve nodes from the job
  auto node_list = job->create_and_get_nodes();

  // Validate that all nodes are configured to use simulation time
  for (auto const & node : node_list) {
    if (!node->get_parameter("use_sim_time").as_bool()) {
      throw exceptions::NodeNotUsingSimTime(node->get_fully_qualified_name());
    }
  }

  // Prepare executor with custom events queue
  auto context = rclcpp::contexts::get_global_default_context();
  rclcpp::ExecutorOptions exec_opts;
  exec_opts.context = context;

  rclcpp::experimental::executors::EventsExecutor executor{
    std::make_unique<rclcpp::experimental::executors::SimpleEventsQueue>(),
    false,
    exec_opts
  };

  // Register all nodes with the executor
  for (auto const & node : node_list) {
    executor.add_node(node);
  }

  // Start simulation at initial time
  rclcpp::Time sim_time = job->get_initial_time();

  // Simulation main loop: continue until job signals completion or shutdown requested
  do {
    // Update time backend with current simulated time
    time_backend.set_time(sim_time.nanoseconds());

    // Synchronize all node clocks to current simulation time
    for (auto & node : node_list) {
      rslcpp::set_clock(sim_time, node->get_clock());
    }

    // Process any delayed callbacks whose deadlines have passed
    time_backend.execute_ready_delayed_callables();

    // Run all ready callbacks — using a very large timeout to simulate infinite wait
    executor.spin_all(
      std::chrono::hours(200 * 365 * 24));  // ~200 years; avoids early termination due to timeout

    // Determine next event time: either next timer or next delayed callback
#ifdef RSLCPP__CUSTOM__RCLCPP
    std::chrono::nanoseconds next_timer_time = executor.get_time_until_next_timer();
#else
    std::chrono::nanoseconds next_timer_time = std::chrono::milliseconds(1);  // fallback
#endif

    if (next_timer_time == std::chrono::nanoseconds::max()) {
      // No further timers scheduled → simulation can terminate
      break;
    }

    // Query time until next delayed callable
    rslcpp::time_delay::Duration next_delayed_time =
      time_backend.get_time_until_next_delayed_callable();

    // Choose smallest increment for advancing simulation time
    rclcpp::Duration time_step;
    if (next_delayed_time < next_timer_time.count()) {
      time_step = rclcpp::Duration(std::chrono::nanoseconds(next_delayed_time));
    } else {
      time_step = rclcpp::Duration(next_timer_time);
    }

    // Advance simulation clock
    sim_time += time_step;

  } while (!job->get_finished() && rclcpp::ok(context));

  // Finalize execution
  rclcpp::shutdown();
  return job->get_exit_code();
}

