void XmlBtPolarWriter::storePolarInformation(BoatPolar const *polarData)
{
    QString buffer;
    writeStartElement("Polar");

    {
        writeTextElement("Polar_Name", polarData->name());
        writeComment("For scripts: if the boat's name is left blank, the analysis will be associated to all available boats");
        writeTextElement("Boat_Name", polarData->boatName());
        writeComment("Boat polars are necessarily of the control type");
        writeTheStyle(polarData->theStyle());
        writeTextElement("Method", Polar3d::analysisMethod(polarData->analysisMethod()));

        writeStartElement("Reference_Dimensions");
        {
            writeComment("Available options are AUTO and CUSTOM");
            writeTextElement("Reference_Dimensions", Polar3d::referenceDimension(polarData->referenceDim()));
            writeComment("The following fields are required only if dimensions are set to CUSTOM");

            double areaScaled = polarData->referenceArea() * Units::m2toUnit();
            double chordScaled = polarData->referenceChordLength() * Units::mtoUnit();

            writeTextElement("Reference_Area", QString::asprintf("%11.5f", areaScaled));
            writeTextElement("Reference_Chord_Length", QString::asprintf("%11.5f", chordScaled));
        }
        writeEndElement();

        writeWakeData(*polarData);

        // CoG formatting with unit conversion
        buffer.sprintf("%g, %g, %g",
                       polarData->CoG().x * Units::mtoUnit(),
                       polarData->CoG().y * Units::mtoUnit(),
                       polarData->CoG().z * Units::mtoUnit());
        writeTextElement("CoG", buffer);

        writeStartElement("Wind_gradient");
        {
            writeWindSpline(polarData->windSpline());
        }
        writeEndElement();

        writeFluidProperties(polarData->viscosity(), polarData->density());

        if (polarData->hasExtraDrag())
            writeExtraDrag(polarData->extraDragList());

        writeComment("Min and max values separated by a comma ,");

        // Speed ranges
        writeTextElement("Boat_Speed", QString::asprintf(" %g, %g", polarData->VBtMin(), polarData->VBtMax()));
        writeTextElement("TWS",        QString::asprintf(" %g, %g", polarData->qInfMin(), polarData->qInfMax()));
        writeTextElement("TWA",        QString::asprintf(" %g, %g", polarData->twaMin(), polarData->twaMax()));
        writeTextElement("Phi",        QString::asprintf(" %g, %g", polarData->phiMin(), polarData->phiMax()));
        writeTextElement("Ry",         QString::asprintf(" %g, %g", polarData->RyMin(), polarData->RyMax()));

        writeStartElement("SailAngles");
        {
            int numSails = polarData->sailAngleSize();
            for (int sailIndex = 0; sailIndex < numSails; ++sailIndex)
            {
                QString elementName, angleRange;
                elementName = QString("Sail_%1").arg(sailIndex + 1);
                angleRange.sprintf("%.3f,  %.3f", polarData->sailAngleMin(sailIndex), polarData->sailAngleMax(sailIndex));
                writeTextElement(elementName, angleRange);
            }
        }
        writeEndElement();
    }

    writeEndElement(); // </Polar>
}

void XmlBtPolarWriter::writeWindSpline(BSpline const &splineCurve)
{
    writeTextElement("Degree", QString::number(splineCurve.degree()));

    int pointCount = splineCurve.ctrlPointCount();
    for (int idx = 0; idx < pointCount; ++idx)
    {
        QPointF pt = splineCurve.controlPoint(idx);
        writeTextElement("Point", QString::asprintf("%g, %g", pt.x(), pt.y())); // meters only
    }
}

#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int maxAbsoluteSum(std::vector<int>& nums) {
        int n = nums.size();

        // Track maximum subarray sum (Kadane's algorithm)
        int currentMax = 0;
        int globalMax = 0;

        // Track minimum subarray sum (modified Kadane's for negative sums)
        int currentMin = 0;
        int globalMin = nums[0];

        // First pass: find maximum subarray sum
        for (int i = 0; i < n; ++i) {
            currentMax += nums[i];
            if (currentMax > globalMax) {
                globalMax = currentMax;
            }
            if (currentMax < 0) {
                currentMax = 0;
            }
        }

        // Second pass: find minimum subarray sum
        for (int i = 0; i < n; ++i) {
            currentMin += nums[i];
            if (currentMin < globalMin) {
                globalMin = currentMin;
            }
            if (currentMin > 0) {
                currentMin = 0;
            }
        }

        // Return the maximum of the absolute values
        return std::max(globalMax, std::abs(globalMin));
    }
};

