#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>
#include <string>

using asio::bind_executor;
using asio::dispatch;
using asio::get_associated_executor;
using asio::make_work_guard;
using asio::post;
using asio::thread_pool;

// Asynchronously read one line from input stream using a different approach
template <typename CompletionToken>
void read_single_line(std::istream& stream, CompletionToken&& token)
{
  // Create work guard tied to the completion token's executor
  auto guard = make_work_guard(token);

  // Schedule the actual I/O operation on the executor
  post([&stream, guard, token = std::forward<CompletionToken>(token)]() mutable {
    std::string buffer;
    std::getline(stream, buffer);

    // Ensure handler runs on its associated executor
    dispatch(guard.get_executor(), 
        [buffer = std::move(buffer), token = std::forward<CompletionToken>(token)]() mutable {
      token(std::move(buffer));
    });
  });
}

// Recursively read multiple lines until empty line is encountered
template <typename CompletionToken>
void read_multiple_lines(std::istream& stream, std::string accumulated, CompletionToken&& token)
{
  // Extract the final handler's executor for consistent execution context
  auto exec = get_associated_executor(token);

  // Chain operations using the same executor
  read_single_line(stream,
      bind_executor(exec,
          [&stream, text = std::move(accumulated), token = std::forward<CompletionToken>(token)]
          (std::string current) mutable {
            if (current.empty()) {
              // Termination condition: pass accumulated result to final handler
              token(std::move(text));
            } else {
              // Continue reading with updated accumulator
              read_multiple_lines(stream, text + current + "\n", std::move(token));
            }
          }));
}

int main()
{
  thread_pool worker_pool;

  std::cout << "Enter text, terminating with a blank line:\n";

  // Start asynchronous reading process bound to the thread pool
  read_multiple_lines(std::cin, "",
      bind_executor(worker_pool, [](std::string content) {
        std::cout << "Collected lines:\n" << content << "\n";
      }));

  // Wait for all tasks in the pool to complete
  worker_pool.join();
}

