// Macro to check if a virtual key is currently pressed (low-order bit set)
#define IS_KEY_DOWN(VK_CODE) ((GetAsyncKeyState(VK_CODE) & 0x8000) != 0)

int main() {
    runtime::RuntimeContext context;

    // Initialize the runtime context with configuration file
    if (!context.initialize("config.ini")) {
        std::cerr << "Failed to initialize runtime context" << std::endl;
        return 1;
    }

    std::cout << std::endl;

    engine::FishEngine engine(context);

    // Handle pause/resume functionality if configured
    if (context.config().is_pause) {
        std::cout << "Press Tab to pause/resume, Esc to stop" << std::endl;

        std::atomic<bool> shouldExit{ false };
        std::thread inputHandler([&engine, &shouldExit]() {
            while (!shouldExit.load()) {
                // Check for Tab key press (toggle pause state)
                if (IS_KEY_DOWN(VK_TAB)) {
                    engine.togglePause();

                    if (engine.isPaused()) {
                        std::cout << "Paused" << std::endl;
                    } else {
                        std::cout << "Resumed" << std::endl;
                    }

                    // Small delay to prevent multiple toggles from single press
                    Sleep(200);
                }

                // Check for Escape key press (stop execution)
                if (IS_KEY_DOWN(VK_ESCAPE)) {
                    std::cout << "Stopping..." << std::endl;
                    engine.requestStop();
                    break;
                }

                Sleep(50);  // Reduce CPU usage by polling at regular intervals
            }
        });

        // Run the main engine loop
        engine.runLoop();

        // Signal thread to exit and wait for completion
        shouldExit.store(true);
        if (inputHandler.joinable()) {
            inputHandler.join();
        }
    } else {
        // Run without pause functionality
        engine.runLoop();
    }

    return 0;
}

