#include <cstddef>

// Redefine PTMF with reordered fields and alternative naming
struct MemberFunctionPtr {
    long this_adjustment;   // offset to apply to 'this' pointer
    long vtable_index;      // -1 indicates non-virtual function
    union {
        void* direct_address;     // address for non-virtual functions
        long vtable_slot;         // index into virtual table
    } function_info;
};

// Define null representation using different initialization syntax
const MemberFunctionPtr null_mfp = {0, -1, {nullptr}};

/* clang-format off */
asm void check_ptmf_validity(register MemberFunctionPtr* mfp_ptr) {
  nofralloc
  // Load each component of the pointer-to-member structure
  lwz r4, MemberFunctionPtr.this_adjustment(mfp_ptr)
  lwz r5, MemberFunctionPtr.vtable_index(mfp_ptr)
  lwz r6, MemberFunctionPtr.function_info(mfp_ptr)

  // Set result to true initially
  li r3, 1

  // Test each field for zero/non-zero values
  cmpwi cr0, r4, 0
  cmpwi cr1, r5, -1
  cmpwi cr2, r6, 0

  // Branch return if any field indicates invalid pointer
  bnelr cr0
  bne cr1, @invalid_check
  bnelr cr2

  // If we reach here, all checks passed
  blr

@invalid_check:
  li r3, 0
  blr
}

asm void invoke_member_function(...) {
  nofralloc
  // Extract PTMF components from r12 register
  lwz r0, MemberFunctionPtr.this_adjustment(r12)
  lwz r11, MemberFunctionPtr.vtable_index(r12)
  lwz r12, MemberFunctionPtr.function_info(r12)

  // Adjust 'this' pointer by delta
  add r3, r3, r0

  // Check if virtual function
  cmpwi r11, -1
  ble @non_virtual_path

  // Virtual function path: dereference vtable twice
  lwzx r12, r3, r12      // load vtable pointer
  lwzx r12, r12, r11     // load function address from vtable
  b @end_dispatch

@non_virtual_path:
  // Non-virtual function: use direct address
  // (r12 already contains the direct address from union)

@end_dispatch:
  // Setup and branch to target function
  mtctr r12
  bctr
}
