#include <iostream>
#include <boost/array.hpp>
#include <asio.hpp>

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: client <host>" << std::endl;
      return 1;
    }

    asio::io_context io_context;
    asio::ip::udp::resolver resolver(io_context);
    auto endpoints = resolver.resolve(asio::ip::udp::v4(), argv[1], "daytime");

    // Use the first resolved endpoint
    asio::ip::udp::endpoint target_endpoint = *endpoints.begin();

    asio::ip::udp::socket socket(io_context);
    socket.open(asio::ip::udp::v4());

    // Send a single null byte to trigger daytime service response
    boost::array<char, 1> request_buffer = {{ '\0' }};
    socket.send_to(asio::buffer(request_buffer), target_endpoint);

    // Prepare buffer for receiving time string
    boost::array<char, 128> response_buffer;
    asio::ip::udp::endpoint source_endpoint;

    size_t bytes_received = socket.receive_from(
        asio::buffer(response_buffer), source_endpoint);

    // Output the received time string without trailing newline
    std::cout.write(response_buffer.data(), bytes_received);
    std::cout << std::endl;
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << std::endl;
    return 1;
  }

  return 0;
}

