StopCmd::~StopCmd() = default;

int StopCmd::execute() {
    LogSetup::setupLogConsole(); // Initialize console logging only, as log files are managed externally

    TuringConfig config;
    if (!_turingDir.empty()) {
        config.setTuringDirectory(fs::Path{_turingDir});
    }

    _turingDir = config.getTuringDir().value_or("");
    const fs::Path socketPath = config.getSocketPath();

    if (!socketPath.exists()) {
        spdlog::error("No TuringDB instance appears to be active at {}", _turingDir);
        return EXIT_FAILURE;
    }

    // Send stop signal via Unix domain socket
    if (!SystemEventHandler::initiateShutdown(socketPath)) {
        spdlog::error("Failed to send shutdown request to TuringDB instance at {}", _turingDir);
        return EXIT_FAILURE;
    }

    LockFile lockFile;
    lockFile.setPath(config.getLockFilePath());

    // Poll until the lock file is released (may take time for large memory usage or long-running queries)
    constexpr auto pollIntervalMs = 50; // Check every 50ms
    auto elapsed = 0ms;
    while (lockFile.isLocked() && elapsed < _timeout) {
        std::this_thread::sleep_for(std::chrono::milliseconds{pollIntervalMs});
        elapsed += pollIntervalMs;
    }

    if (lockFile.isLocked()) {
        spdlog::error("TuringDB at {} did not shut down within {} ms", _turingDir, _timeout.count());
        return EXIT_FAILURE;
    }

    spdlog::info("Successfully stopped TuringDB instance at {}", _turingDir);
    return EXIT_SUCCESS;
}

std::unique_ptr<StopCmd> StopCmd::create() {
    auto cmd = std::make_unique<StopCmd>();
    cmd->initialize();
    return cmd;
}

void StopCmd::initialize() {
    _argParser.add_description("Terminates the TuringDB server process");
    _argParser.add_argument("-turing-dir")
        .metavar("path")
        .help("Base directory of the TuringDB installation")
        .store_into(_turingDir);
    _argParser.add_argument("-timeout", "-t")
        .metavar("milliseconds")
        .help("Maximum duration in milliseconds to wait for graceful shutdown (default: 3000)")
        .store_into(_timeout);
}

