void TempPath::collectOptions(std::shared_ptr<ProgramOptions> options) {
  options->addSection("temp", "temporary files configuration");

  options
    ->addOption("--temp.path", 
                "Directory path used for storing temporary files.",
                new StringParameter(&_path))
    .setLongDescription(R"(SereneDB utilizes this directory for various temporary operations,
including extraction of uploaded archives and intermediate data processing.
It is recommended to configure this path as a process-specific subdirectory
within the system's designated temporary folder. To prevent accidental data loss,
ensure that this path does not intersect with critical directories such as
the database storage location.
