#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sm/vvec>

int main() {
    // Initialize a visualization window with specified dimensions and title
    mplot::Visual scene(1024, 768, "Created using mplot::GraphVisual");

    // Construct a GraphVisual instance for double-precision data, positioned at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));

    // Establish the parent-child relationship between Visual and GraphVisual
    scene.bindmodel(graph);

    // Prepare x-axis data points using vvec (vector with vectorized operations)
    sm::vvec<double> abscissae;

    // Generate evenly spaced points from -0.5 to 0.8 over 14 samples
    abscissae.linspace(-0.5, 0.8, 14);

    // Define the cubic function y = x^3 as the dataset
    graph->setdata(abscissae, abscissae.pow(3));

    // Finalize graph geometry preparation for rendering
    graph->finalize();

    // Integrate the graph into the scene, transferring ownership
    scene.addVisualModel(graph);

    // Display the visualization until user terminates with Ctrl+Q
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' destructor handles the owned GraphVisual
    return 0;
}

