#include <iostream>
#include <vector>
#include <algorithm>

// Global state for the permutation processing
int arraySize;
std::vector<int> currentPermutation;
std::vector<int> positionMap;
std::vector<std::pair<int, int>> recordedOperations;

// Execute an operation and document it
void executeOperation(int leftCount, int rightCount) {
    // Validate operation parameters
    if (leftCount <= 0 || rightCount <= 0 || leftCount + rightCount >= arraySize) {
        return;
    }

    recordedOperations.push_back({leftCount, rightCount});

    // Split the array into three segments
    std::vector<int> firstPart(currentPermutation.begin(), currentPermutation.begin() + leftCount);
    std::vector<int> secondPart(currentPermutation.begin() + leftCount, currentPermutation.end() - rightCount);
    std::vector<int> thirdPart(currentPermutation.end() - rightCount, currentPermutation.end());

    // Reassemble as: thirdPart + secondPart + firstPart
    currentPermutation.clear();
    currentPermutation.insert(currentPermutation.end(), thirdPart.begin(), thirdPart.end());
    currentPermutation.insert(currentPermutation.end(), secondPart.begin(), secondPart.end());
    currentPermutation.insert(currentPermutation.end(), firstPart.begin(), firstPart.end());

    // Update position mapping
    for (int idx = 0; idx < arraySize; ++idx) {
        positionMap[currentPermutation[idx]] = idx + 1;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> arraySize;
    currentPermutation.resize(arraySize);
    positionMap.resize(arraySize + 1);

    // Read initial permutation and build position map
    for (int pos = 0; pos < arraySize; ++pos) {
        std::cin >> currentPermutation[pos];
        positionMap[currentPermutation[pos]] = pos + 1;
    }

    if (arraySize == 3) {
        // Special case for size 3: check if reverse gives smaller lexicographic order
        std::vector<int> reversedPerm = currentPermutation;
        std::reverse(reversedPerm.begin(), reversedPerm.end());

        if (reversedPerm < currentPermutation) {
            executeOperation(1, 1);
        }
    } else {
        // General case for n >= 4: sort by placing each number i at position i
        for (int targetValue = 1; targetValue <= arraySize; ++targetValue) {
            int currentPosition = positionMap[targetValue];

            if (currentPosition == targetValue) {
                continue;
            }

            // Bring element to front using two operations
            if (currentPosition > 1) {
                executeOperation(currentPosition - 1, 1);
                executeOperation(arraySize - 1, 1);
            }

            // Move from front to correct position
            if (targetValue > 1) {
                executeOperation(1, arraySize - targetValue);
                executeOperation(targetValue, 1);
            }
        }
    }

    // Output results
    std::cout << recordedOperations.size() << "\n";
    for (const auto& op : recordedOperations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

