    void RegisterCommand(const FString& Name, const FText& Description,
                         const FConsoleCommandWithWorldArgsAndOutputDeviceDelegate& Handler);

    // Aliases mapping legacy/deprecated commands to current ones
    TMap<FString, FString> CommandAliases;

