FOculusCmdRegistry::FOculusCmdRegistry(FOculusHMD* InOculusPtr)
{
    // Define all supported console commands
    const auto Register = [this](const FString& Name, const FText& Desc, auto&& Handler) {
        auto Cmd = IConsoleManager::Get().RegisterConsoleCommand(
            *Name, *Desc.ToString(), TEXT(""), FConsoleCommandWithWorldArgsAndOutputDeviceDelegate::CreateRaw(InOculusPtr, Handler));
        RegisteredCommands.Add(Cmd);
    };

    // Core runtime commands
    Register(TEXT("vr.oculus.bUpdateOnRenderThread"),
             NSLOCTEXT("OculusRift", "CCommandText_UpdateRT", "Enables or disables updating on the render thread."),
             &FOculusHMD::UpdateOnRenderThreadCommandHandler);

    Register(TEXT("vr.oculus.PixelDensity.min"),
             NSLOCTEXT("OculusRift", "CCommandText_PixelDensityMin", "Minimum pixel density when adaptive pixel density is enabled"),
             &FOculusHMD::PixelDensityMinCommandHandler);

    Register(TEXT("vr.oculus.PixelDensity.max"),
             NSLOCTEXT("OculusRift", "CCommandText_PixelDensityMax", "Maximum pixel density when adaptive pixel density is enabled"),
             &FOculusHMD::PixelDensityMaxCommandHandler);

    Register(TEXT("vr.oculus.bHQBuffer"),
             NSLOCTEXT("OculusRift", "CCommandText_HQBuffer", "Enable or disable using floating point texture format for the eye layer."),
             &FOculusHMD::HQBufferCommandHandler);

    Register(TEXT("vr.oculus.bHQDistortion"),
             NSLOCTEXT("OculusRift", "CCommandText_HQDistortion", "Enable or disable using multiple mipmap levels for the eye layer."),
             &FOculusHMD::HQDistortionCommandHandler);

    Register(TEXT("vr.oculus.ShowGlobalMenu"),
             NSLOCTEXT("OculusRift", "CCommandText_GlobalMenu", "Opens the global menu."),
             &FOculusHMD::ShowGlobalMenuCommandHandler);

    Register(TEXT("vr.oculus.ShowQuitMenu"),
             NSLOCTEXT("OculusRift", "CCommandText_QuitMenu", "Opens the quit menu."),
             &FOculusHMD::ShowQuitMenuCommandHandler);

#if !UE_BUILD_SHIPPING
    Register(TEXT("vr.oculus.Debug.bShowStats"),
             NSLOCTEXT("OculusRift", "CCommandText_Stats", "Enable or disable rendering of stats."),
             &FOculusHMD::StatsCommandHandler);

    Register(TEXT("vr.oculus.Debug.CaptureCubemap"),
             NSLOCTEXT("OculusRift", "CCommandText_Cubemap",
                 "Captures a cubemap for Oculus Home.\nOptional args:\n  xoff=<float>, yoff=<float>, zoff=<float>\n  yaw=<float>\n  mobile"),
             &UOculusSceneCaptureCubemap::CaptureCubemapCommandHandler);

    Register(TEXT("vr.oculus.Debug.Show"),
             NSLOCTEXT("OculusRift", "CCommandText_Show", "Shows current stereo rendering parameters."),
             &FOculusHMD::ShowSettingsCommandHandler);

    Register(TEXT("vr.oculus.Debug.IPD"),
             NSLOCTEXT("OculusRift", "CCommandText_IPD", "Shows or modifies interpupillary distance (meters)."),
             &FOculusHMD::IPDCommandHandler);
#endif // !UE_BUILD_SHIPPING

    // Populate alias table manually
    CommandAliases.Add(TEXT("OVRGLOBALMENU"), TEXT("vr.oculus.ShowGlobalMenu"));
    CommandAliases.Add(TEXT("OVRQUITMENU"),   TEXT("vr.oculus.ShowQuitMenu"));

#if !UE_BUILD_SHIPPING
    CommandAliases.Add(TEXT("vr.oculus.Debug.EnforceHeadTracking"), TEXT("vr.HeadTracking.bEnforced"));
#endif
}

bool FOculusCmdRegistry::HandleExec(UWorld* InWorld, const TCHAR* Cmd, FOutputDevice& Ar)
{
    const TCHAR* Original = Cmd;
    FString AliasTarget;

    // Try to match deprecated command prefixes
    for (const auto& Pair : CommandAliases)
    {
        const FString& OldCmd = Pair.Key;
        if (FCString::Strnicmp(Cmd, *OldCmd, OldCmd.Len()) == 0 && 
            (Cmd[OldCmd.Len()] == TEXT(' ') || Cmd[OldCmd.Len()] == TEXT('\0')))
        {
            AliasTarget = Pair.Value;
            break;
        }
    }

    if (!AliasTarget.IsEmpty())
    {
        Ar.Logf(ELogVerbosity::Warning, TEXT("%s is deprecated. Use %s instead"), Original, *AliasTarget);
        return IConsoleManager::Get().ProcessUserConsoleInput(*AliasTarget, Ar, InWorld);
    }

    return false;
}

