#include <iostream>
#include <vector>
using namespace std;

// Global variables for array size and data storage
int arraySize;
vector<int> dataArray;

// Recursive function to reconstruct the array using queries
void reconstruct(int left, int right) {
    // Base case: invalid range
    if (left > right) return;

    // Skip already-filled positions from the left
    while (left <= right && dataArray[left] != 0) left++;
    // Skip already-filled positions from the right
    while (right >= left && dataArray[right] != 0) right--;

    // If no unfilled positions remain, exit
    if (left > right) return;

    // Perform query on current segment
    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    // Handle error response
    if (value == -1) exit(0);

    // If all elements in range are the same value
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            dataArray[idx] = value;
        }
        return;
    }

    // Divide the segment at midpoint
    int center = (left + right) / 2;

    // Process left half first
    reconstruct(left, center);

    // Use information from query to optimize right half filling
    // Check if value appears at the center position
    if (dataArray[center] == value) {
        int countLeft = 0;
        int scanPos = center;

        // Count occurrences of 'value' in [left, center]
        while (scanPos >= left && dataArray[scanPos] == value) {
            countLeft++;
            scanPos--;
        }

        // Calculate how many should be in right half
        int remaining = frequency - countLeft;
        for (int offset = 1; offset <= remaining; ++offset) {
            int pos = center + offset;
            if (pos <= arraySize) {
                dataArray[pos] = value;
            }
        }
    }

    // Process right half
    reconstruct(center + 1, right);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> arraySize) {
        dataArray.resize(arraySize + 1, 0); // 1-based indexing

        reconstruct(1, arraySize);

        // Output final result
        cout << "! ";
        for (int i = 1; i <= arraySize; ++i) {
            cout << dataArray[i];
            if (i < arraySize) cout << " ";
        }
        cout << "\n";
    }

    return 0;
}

