#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>
#include <signal.h>
#include "server.hpp"
#include "file_handler.hpp"

int main(int argc, char* argv[])
{
  try
  {
    // Validate command line arguments
    if (argc != 4)
    {
      std::cerr << "Usage: http_server <address> <port> <doc_root>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 80 .\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 80 .\n";
      return 1;
    }

    asio::io_context io_context;

    // Create file handler and server instance
    http::server4::file_handler handler(argv[3]);
    http::server4::server s(io_context, argv[1], argv[2], handler);

    // Start the server coroutine
    s();

    // Set up signal handling for graceful shutdown
    asio::signal_set signals(io_context);
    signals.add(SIGINT);
    signals.add(SIGTERM);
#if defined(SIGQUIT)
    signals.add(SIGQUIT);
#endif

    // Register async wait for termination signals
    signals.async_wait(boost::bind(
          &asio::io_context::stop, &io_context));

    // Run the event loop until stopped
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Error occurred: " << e.what() << "\n";
  }

  return 0;
}

