Tooltip::~Tooltip() = default;

// Helper to apply or restore instruction bytes at given addresses
static void patch_bytes_at_address(std::uintptr_t addr, const std::vector<BYTE>& bytes) {
    if (bytes.size() == 2) {
        mem::write<BYTE[2]>(addr, {bytes[0], bytes[1]});
    } else {
        mem::set(addr, bytes[0], static_cast<int>(bytes.size()));
    }
}

void Tooltip::synchronize_hover_timeout() {
    mem::write<int>(0x59E10D, hover_timeout.get());
}

void Tooltip::synchronize_alt_all_containers() {
    // Toggle behavior based on all_containers flag
    if (all_containers.get()) {
        // Patch two locations with NOPs to bypass hover checks
        patch_bytes_at_address(0x416D1D, {0x90, 0x90});
        patch_bytes_at_address(0x416D22, {0x90, 0x90});
    } else {
        // Restore original conditional jump instructions
        patch_bytes_at_address(0x416D1D, {0x74, 0x74});
        patch_bytes_at_address(0x416D22, {0x74, 0x6F});
    }
}

Tooltip::Tooltip(ZealService *zeal) {
    // Modify initial tooltip timer condition: change jbe (0x86) to jb (0x82)
    // Prevents flickering when timer is disabled
    mem::write<BYTE>(0x59E112, 0x82);

    // Register /tooltipall command
    zeal->commands_hook->Add("/tooltipall", {}, 
                             "Toggle showing all open containers tooltips when holding alt.",
                             [this](std::vector<std::string>& args) -> bool {
                                 all_containers.toggle();
                                 return true; // Stop further command processing
                             });

    // Register /tooltiptimer command
    zeal->commands_hook->Add("/tooltiptimer", {"/ttimer"}, 
                             "Set the time limit before a tooltip appears.",
                             [this](std::vector<std::string>& args) -> bool {
                                 int new_timeout = 0;
                                 if (args.size() > 1 && Zeal::String::tryParse(args[1], &new_timeout)) {
                                     hover_timeout.set(new_timeout);
                                     Zeal::Game::print_chat("Tooltip hover timer now set to %i", hover_timeout.get());
                                 }
                                 return true; // Stop further command processing
                             });
}

#include "ncl.h"

/*----------------------------------------------------------------------------------------------------------------------
|	Constructor: initializes member variables to default values.
|	- Sets pointer members (next, nexus) to NULL
|	- Sets boolean flags: isEmpty = true, isEnabled = true, isUserSupplied = false
|	- Clears string members id and errormsg
*/
NxsBlock::NxsBlock()
	{
	next			= nullptr;
	nexus			= nullptr;
	isEmpty			= true;
	isEnabled		= true;
	isUserSupplied	= false;
	id.clear();
	errormsg.clear();
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Destructor: no special cleanup required in base class
*/
NxsBlock::~NxsBlock()
	{
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Base implementation for character label to number conversion.
|	Returns 0 by default; derived classes should override if needed.
|	Parameter 's' is unused in this base version.
*/
unsigned NxsBlock::CharLabelToNumber(
  NxsString s)	// the character label to be translated to its numeric index
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(s)
#	endif
	return 0;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Disables this block. When disabled, the block will be skipped during file processing.
|	Can be used to prevent execution of blocks not relevant to current operation.
*/
void NxsBlock::Disable()
	{
	isEnabled = false;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Re-enables this block after it has been disabled.
|	Once enabled, the block will be processed normally during file reading.
*/
void NxsBlock::Enable()
	{
	isEnabled = true;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns whether this block is currently enabled.
|	A disabled block will be skipped during NEXUS file parsing.
*/
bool NxsBlock::IsEnabled() const
	{
	return isEnabled;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns whether this block was created from user-supplied data (i.e., Read() was called).
|	Useful for determining if internal vs external data sources are being used.
*/
bool NxsBlock::IsUserSupplied() const
	{
	return isUserSupplied;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns whether the block is empty — i.e., whether Read() has been called since last Reset().
|	Default behavior returns value of isEmpty flag.
*/
bool NxsBlock::IsEmpty() const
	{
	return isEmpty;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns the identifier string associated with this block.
*/
NxsString NxsBlock::GetID() const
	{
	return id;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Pure virtual method for reading block contents after block name has been parsed.
|	Must be implemented by all derived classes.
|	Uses token parameter for lexical analysis during parsing.
*/
void NxsBlock::Read(
  NxsToken &token)	// token object used for parsing input stream
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(token)
#	endif
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Resets the block's state in preparation for re-reading a new block of same type.
|	Called automatically by NxsReader before invoking Read().
|	Should clear any previous data and reset flags appropriately.
*/
void NxsBlock::Reset()
	{
	isEmpty = true;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Generates a summary report of the block's contents to the given output stream.
|	Base implementation does nothing; derived classes may provide detailed reporting.
*/
void NxsBlock::Report(
  std::ostream &out)	// destination output stream
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(out)
#	endif
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Sets the associated NxsReader instance for this block.
|	Used to maintain bidirectional references between block and reader.
*/
void NxsBlock::SetNexus(
  NxsReader *nxsptr)	// pointer to the NxsReader managing this block
	{
	nexus = nxsptr;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Callback invoked when an unrecognized command is encountered and about to be skipped.
|	Base version takes no action; subclasses can override to issue warnings or handle unknown commands.
*/
void NxsBlock::SkippingCommand(
  NxsString commandName)	// name of the unrecognized command
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(commandName)
#	endif
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Base implementation for taxon label to number mapping.
|	Returns 0 unless overridden in derived classes.
|	Parameter 's' represents the taxon label to convert.
*/
unsigned NxsBlock::TaxonLabelToNumber(
  NxsString s)	// the taxon label to translate into its numeric index
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(s)
#	endif
	return 0;
	}
